local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["quest:3124"] = {n="Muisek von Hippogryphen",s="In der oberen Wildnis tragen Frayfeather-Hippogryphen Geister in sich, die Ihr für Uzer'i einfangen sollt. Ihr Muisek kann entkommen, wenn Ihr nicht schnell handelt.",h="In der oberen Wildnis tragen Frayfeather-Hippogryphen Geister in sich, die Ihr für Uzer'i einfangen sollt.",kw={"feralas","frayfeather","die obere wildnis","muisek von hippogryphen","muisek-gefäß","hexendoktor uzer'i"},sec={{t="Treue Gefährten",b="Hexendoktor Uzer'i vertraut Euch das Gefäß an und bittet Euch, den Geist einer anderen Kreatur einzufangen. Hippogryphen sind seit Langem Gefährten der Nachtelfen, und ihre Geister sind treu und standhaft. Ihr braucht zehn Frayfeather-Hippogryphen beliebiger Art. Tötet jeden einzelnen, schrumpft ihn dann schnell mit dem Gefäß und fangt ihn damit ein, um sein Muisek zu bewahren. Uzer'i verortet sie in der oberen Wildnis, südlich des Lagers."},{t="Uzer'is Warnung",b="Hexendoktor Uzer'i warnt, dass das Muisek eines erschlagenen Tieres entkommen und die Gestalt einer größeren Kreatur annehmen könnte. Dann ließe seine Rache keinen Frieden zu. Die Arbeit ist gefährlich, und Uzer'i sagt, Ihr habt sie erneut gut erledigt."}},faq={{q="Wer schickt Euch los, um Hippogryphen einzufangen?",a="Hexendoktor Uzer'i schickt Euch nach Testing the Vessel los, um Hippogryphen einzufangen.",al={"muisek von hippogryphen questgeber","wer vergibt muisek von hippogryphen","wo gibt es muisek von hippogryphen"}},{q="Wo sind die Frayfeather-Hippogryphen zu finden?",a="Uzer'i verortet die Frayfeather-Hippogryphen in der oberen Wildnis, südlich des Lagers.",al={"wo sind frayfeather-hippogryphen","hippogryphen fundort feralas","wo findet man hippogryphen in feralas"}},{q="Warum will Hexendoktor Uzer'i die Geister von Hippogryphen?",a="Hippogryphen sind alte Gefährten der Nachtelfen, und Uzer'i sagt, ihre Geister seien treu und standhaft. Er will ihr Muisek bewahren lassen.",al={"warum hippogryphen","warum muisek von hippogryphen einfangen","uzeri hippogryphen begründung"}},{q="Wie wird das Muisek eingefangen?",a="Tötet einen Frayfeather-Hippogryphen, schrumpft ihn dann schnell mit dem Muisek-Gefäß und fangt ihn damit ein. Zehn werden verlangt, gleich welcher Art.",al={"wie benutzt man das muisek-gefäß","wie erhält man muisek von hippogryphen","frayfeather-muisek einfangen"}},{q="Welcher Schritt kommt in dieser Reihe davor?",a="Testing the Vessel kommt davor. Dort habt Ihr bewiesen, dass Ihr vertrauenswürdig seid und mit dem Muisek-Gefäß umgehen könnt.",al={"muisek von hippogryphen voraussetzung","vorherige quest muisek von hippogryphen","voraussetzung für muisek von hippogryphen"}}},fp="17,138,16.400.0,16.214.1,37.78.0,44.84.0,53.138.0,27.118.0,41.102.0"}
P.entries["quest:3125"] = {n="Muisek von Feendrachen",s="Westlich von Hexendoktor Uzer'i sucht die Horde nach den Geistern von Feendrachen. Grimmlingflitzer und Feendrachen tragen die Stärke in sich, die Uzer'i einzufangen hofft.",h="Westlich von Hexendoktor Uzer'i sucht die Horde nach den Geistern von Feendrachen.",kw={"muisek von feendrachen","feralas","hippogryph muisek","horde","muisek-gefäß","grimmlingflitzer","feendrache","treant muisek","hexendoktor uzer'i"},sec={{t="Zarter Schein, starker Geist",b="Hexendoktor Uzer'i sieht Stärke in Feendrachen, auch wenn sie zart wirken. Sie sind seit Langem Verbündete der Nachtelfen, und Uzer'i möchte, dass die Horde an ihrer Macht teilhat. Uzer'i gibt Euch ein Muisek-Gefäß und schickt Euch nach Westen. Erschlagt acht Grimmlingflitzer oder Feendrachen und benutzt dann das Gefäß bei jedem gefallenen Feendrachen, um seinen Geist zu schrumpfen und einzufangen."},{t="Zurück an Uzer'is Seite",b="Wenn Ihr mit den eingefangenen Geistern zurückkehrt, dankt Euch Hexendoktor Uzer'i. Die Horde kann nun auf die spirituelle Macht der Feendrachen zurückgreifen. Uzer'i hofft, dass Ihr einer weiteren Aufgabe zustimmen werdet."}},faq={{q="Warum will Hexendoktor Uzer'i die Geister von Feendrachen?",a="Uzer'i sagt, dass Feendrachen zerbrechlich aussehen, aber einen mächtigen Geist in sich tragen. Sie sind seit Langem Verbündete der Nachtelfen, und Uzer'i möchte, dass auch die Horde von ihrer Stärke profitiert.",al={"warum feendrachen","muisek von feendrachen zweck","warum grimmlingflitzer töten"}},{q="Wo sind die Feendrachen zu finden?",a="Die Feendrachen befinden sich westlich von Hexendoktor Uzer'i.",al={"wo sind grimmlingflitzer","grimmlingflitzer fundort","feendrachen fundort feralas"}},{q="Welche Kreaturen liefern dieses Muisek?",a="Grimmlingflitzer und Feendrachen liefern das Muisek. Ihr müsst acht von ihnen töten und einfangen.",al={"welche gegner für muisek","was für muisek von feendrachen töten","muisek von feendrachen ziele"}},{q="Was muss mit den gefallenen Kreaturen geschehen?",a="Benutzt das Muisek-Gefäß bei jedem gefallenen Feendrachen, um ihn zu schrumpfen und sein Muisek einzufangen.",al={"wie muisek von feendrachen erhalten","wie funktioniert das muisek-gefäß","muisek einfangen"}},{q="Wo steht dieser Schritt in der Reihe von Uzer'is Aufträgen?",a="Dieser Schritt folgt auf Hippogryph Muisek. Danach folgt Treant Muisek.",al={"welche quest kommt davor","muisek questreihe reihenfolge","was folgt auf muisek von feendrachen"}}},fp="20,152,28.356.0,21.182.1,56.177.0,38.51.0,35.97.0,42.87.0,49.62.0"}
P.entries["quest:3126"] = {n="Muisek von Treants",s="In Feralas lenkt Hexendoktor Uzer'i Eure Suche auf die umherwandernden Treants. Nach den Feendrachen schickt er Euch los, um drei Waldläufer zu finden.",h="In Feralas lenkt Hexendoktor Uzer'i Eure Suche auf die umherwandernden Treants.",kw={"feralas","muisek-gefäß","muisek von treants","treants","uzer'i","umherwandernder waldläufer"},sec={{t="Langsame Beschützer",b="Die Nachtelfen haben die Treants zu ihren Verbündeten gegen die Horde gemacht. Uzer'i sagt, sie bewegen sich langsam, doch niemand kann ihre Stärke als Beschützer leugnen. Er will diese Stärke für die Horde nutzen."},{t="Drei Waldläufer",b="Uzer'i bittet Euch, drei umherwandernde Waldläufer zu finden und zu töten. Sobald ein Treant fällt, verwendet das Muisek-Gefäß, um ihn zu schrumpfen und einzufangen."},{t="Uzer'is Urteil",b="Bei Eurer Rückkehr dankt Euch Hexendoktor Uzer'i. Er sagt, die Sammlung von Muisek sei beinahe vollständig."}},faq={{q="Wer schickt Abenteurer auf die Jagd nach den Treants?",a="Hexendoktor Uzer'i schickt Euch nach den Feendrachen auf die Jagd nach den Treants.",al={"wer vergibt muisek von treants","muisek von treants questgeber","uzeri treantquest"}},{q="Warum will Hexendoktor Uzer'i Muisek von Treants?",a="Die Nachtelfen haben die Treants zu ihren Verbündeten gegen die Horde gemacht. Uzer'i will ihre schützende Kraft für die Horde nutzen.",al={"warum waldläufer töten","warum muisek von treants","uzeri treants beweggrund"}},{q="Welche Kreaturen müssen für Muisek von Treants gefunden werden?",a="Ihr müsst drei umherwandernde Waldläufer finden, die den Wald durchstreifen.",al={"welche treants töten","umherwandernde waldläufer","muisek von treants ziele"}},{q="Wie werden die Treants eingefangen?",a="Sobald ein umherwandernder Waldläufer fällt, verwendet das Muisek-Gefäß, um ihn zu schrumpfen und einzufangen.",al={"wie muisek-gefäß verwenden","waldläufer einfangen","treants schrumpfen"}},{q="Wo steht Muisek von Treants in der Reihenfolge von Uzer'is Aufträgen?",a="Muisek von Treants folgt auf Faerie Dragon Muisek. Mountain Giant Muisek kommt als Nächstes.",al={"muisek von treants questreihe","was kommt nach faerie dragon muisek","nächste quest nach muisek von treants"}}},fp="13,144,15.196.0,20.136.0,16.101.1,40.78.0,48.128.0,47.67.0,29.85.0,53.77.0"}
P.entries["quest:3127"] = {n="Muisek von Bergriesen",s="Im Nordwesten von Feralas begegnet Ihr den letzten Kreaturen, deren Macht Hexendoktor Uzer'i nutzen will: Bergriesen.",h="Im Nordwesten von Feralas begegnet Ihr den letzten Kreaturen, deren Macht Hexendoktor Uzer'i nutzen will...",kw={"brennende legion","klippenriese","feralas","landläufer","muisek von bergriesen","muisekgefäß","treant muisek","hexendoktor uzer'i"},sec={{t="Riesen auf felsigem Boden",b="Hexendoktor Uzer'i sagt, die Bergriesen seien aus den Bergen herabgestiegen, um den Nachtelfen zu helfen, als die Brennende Legion erstmals in die Welt kam. Ihre gewaltige Größe zeichnet sie aus, und felsiger Boden erzittert unter ihren Schritten. Uzer'i hofft, Macht von diesem Ausmaß nutzbar zu machen.\n\nSieben Landläufer oder Klippenriesen müssen fallen. Dann kann das Muisekgefäß sie schrumpfen und einfangen."},{t="Uzer'is Prahlerei",b="Wenn Ihr zurückkehrt, spricht Hexendoktor Uzer'i darüber, was die gesammelten Materialien ermöglichen. Uzer'i behauptet, damit die Geister der Kreaturen für immer in allem bannen zu können, was Uzer'i sich wünscht."}},faq={{q="Wer verlangt nach dem Muisek der Bergriesen?",a="Hexendoktor Uzer'i verlangt nach dem Muisek der Bergriesen. Uzer'i nennt es Eure letzte Bitte.",al={"questgeber","wer vergibt muisek von bergriesen","uzeri quest"}},{q="Wo befinden sich die Bergriesen?",a="Uzer'i schickt Euch nach Nordwesten durch Feralas, wo die Bergriesen durch felsiges Gelände streifen.",al={"bergriesen fundort","wo sind landläufer","klippenriesen fundort"}},{q="Warum sind Bergriesen hier?",a="Laut Uzer'i stiegen die Bergriesen aus den Bergen herab, um den Nachtelfen zu helfen, als die Brennende Legion erstmals in die Welt kam.",al={"warum sind riesen hier","bergriesen hintergrundgeschichte feralas"}},{q="Welche Kreaturen liefern das benötigte Muisek?",a="Landläufer und Klippenriesen liefern das Muisek. Sieben werden benötigt, und das Muisekgefäß schrumpft jeden gefallenen Riesen und fängt ihn ein.",al={"was für muisek töten","welche riesen zählen"}},{q="Was kommt in der Abfolge davor?",a="Treant Muisek kommt davor, und Weapons of Spirit ist danach aufgeführt.",al={"vorherige quest","muisek questreihenfolge"}}},fp="21,108,26.366.0,14.175.1,41.92.0,38.88.0,29.144.0,44.129.0,39.74.0"}
P.entries["quest:3128"] = {n="Natürliche Materialien",s="In Camp Mojache benötigt Hexendoktor Uzer'i natürliche Materialien für ein Vorhaben. Die Materialien stammen von Treants, Bergriesen, Feendrachen, Eulenbestien und Hippogryphen und werden neben den anderen Prüfungen gesammelt.",h="In Camp Mojache benötigt Hexendoktor Uzer'i natürliche Materialien für ein Vorhaben.",kw={"camp mojache","verkrustete mineralien","feralas","metallische fragmente","muisek","natürliche materialien","zähe sehnen","zersplitterter holzscheit","hinterland","hexendoktor uzer'i"},sec={{t="Sammeln für den Hexendoktor",b="Nachdem Ihr zu Hexendoktor Uzer'i zurückgekehrt seid, erwartet Euch neben den anderen Prüfungen eine weitere Materialliste. Bringt zwei zersplitterte Holzscheite von einem Treant in Feralas. Bergriesen und Feendrachen weiter westlich tragen sechs Stück verkrustete Mineralien bei sich. Eulenbestien im Hinterland oder Hippogryphen in Feralas liefern zwanzig Stück zähe Sehnen. Jede dieser Kreaturen kann die vierzig benötigten metallischen Fragmente liefern."},{t="Uzer'is Urteil",b="Hexendoktor Uzer'i ist erfreut, wenn Ihr die Materialien zurückbringt. Zusammen mit dem Muisek sollten sie die Ergebnisse bringen, die er sich gewünscht hat."}},faq={{q="Wer verlangt diese natürlichen Materialien?",a="Hexendoktor Uzer'i in Camp Mojache verlangt sie.",al={"wer vergibt natürliche materialien","questgeber natürliche materialien","wo beginnt natürliche materialien"}},{q="Welche Kreaturen haben die zersplitterten Holzscheite?",a="Ein Treant in Feralas liefert die zwei zersplitterten Holzscheite, die Ihr benötigt.",al={"woher zersplitterte holzscheite bekommen","wer lässt zersplitterte holzscheite fallen","quelle für zersplitterte holzscheite"}},{q="Wo lassen sich verkrustete Mineralien sammeln?",a="Bergriesen und Feendrachen weiter westlich tragen die sechs verkrusteten Mineralien bei sich, die Ihr benötigt.",al={"wie verkrustete mineralien bekommen","quelle für verkrustete mineralien","wer lässt verkrustete mineralien fallen"}},{q="Welche Tiere liefern die zähen Sehnen?",a="Eulenbestien im Hinterland oder Hippogryphen in Feralas liefern die zwanzig Stück zähe Sehnen, die Ihr benötigt.",al={"beute zähe sehnen","wo zähe sehnen finden","wer hat zähe sehnen"}},{q="Woher stammen die metallischen Fragmente?",a="Die vierzig metallischen Fragmente können von Treants, Bergriesen, Feendrachen, Eulenbestien oder Hippogryphen stammen.",al={"quelle für metallische fragmente","wie metallische fragmente bekommen","wer lässt metallische fragmente fallen"}},{q="Was ging dieser Bitte voraus?",a="Diese Bitte folgt auf „Return to Hexendoktor Uzer'i“.",al={"voraussetzung natürliche materialien","vorherige quest natürliche materialien","was führt zu natürliche materialien"}}},fp="17,206,30.401.0,16.134.1,37.50.0,40.59.0,41.86.0,41.109.0,38.110.0,30.51.0"}
P.entries["quest:3129"] = {n="Waffen des Geistes",s="Hexendoktor Uzer'i bereitet in Feralas Waffen für Euch vor. Die Arbeit braucht Zeit, also wartet Ihr, während die Geister gebunden werden.",h="Hexendoktor Uzer'i bereitet in Feralas Waffen für Euch vor.",kw={"feralas","muisek","geisterwaffen","waffen des geistes","hexendoktor uzer'i"},sec={{t="Ein Moment Geduld",b="Hexendoktor Uzer'i hat die Materialien und die Geister, die Ihr gefangen habt. Waffen mit Muisek zu erfüllen, ist harte Arbeit, also bittet Uzer'i Euch zu warten, während die Waffen vorbereitet werden."},{t="Wenn das Warten endet",b="Hexendoktor Uzer'i kehrt mit Waffen zurück, aus denen Ihr wählen könnt. Die Geister der gefangenen Kreaturen sind für immer darin eingeschlossen, und Ihr könnt ihre Energie wie Eure eigene nutzen."}},faq={{q="Wer steht hinter Waffen des Geistes?",a="Hexendoktor Uzer'i hat Euch ausgeschickt, um Muisek zu sammeln. Dies folgt auf Mountain Giant Muisek.",al={"wer vergibt waffen des geistes","waffen des geistes questgeber","uzeri quest"}},{q="Was tut Hexendoktor Uzer'i während dieses Schritts?",a="Uzer'i arbeitet daran, die gefangenen Muisek in Waffen zu binden. Die Arbeit ist schwierig, also bittet Uzer'i Euch zu warten, während die Waffen vorbereitet werden.",al={"was geschieht in waffen des geistes","was tut uzeri"}},{q="Was wird benötigt, bevor Uzer'i beginnen kann?",a="Uzer'i hat die benötigten Materialien und die Geister, die Ihr gefangen habt, also kann die Arbeit beginnen.",al={"anforderungen für waffen des geistes","voraussetzungen für waffen des geistes"}}},fp="17,122,19.171.0,18.168.1,32.82.0,50.136.0,39.84.0"}
P.entries["quest:313"] = {n="Zum Zusehen verdammt",s="In Stahlrosts Depot nahe Kharanos schickt Euch Pilot Steinsegel nach Westen, um im Graufelsbau Wendigos zu jagen. Ihre dicken Pelze sollen seine Belagerungsmaschine, den Trollpflüger, warm halten.",h="In Stahlrosts Depot nahe Kharanos schickt Euch Pilot Steinsegel nach Westen, um im Graufelsbau Wendigos zu...",kw={"dun morogh","der graufelsbau","kharanos","pilot steinsegel","trollpflüger","wendigo","wendigomähne"},ang={["profession:Engineering"]="Wenn Ihr zwergische Belagerungstechnik schätzt, wisst Ihr, dass schwere Maschinen bei Minusgraden ausgeklügelte Methoden brauchen, um warm zu bleiben.",["race:Dwarf"]="Als junger Mountaineer oder Abenteurer aus Eisenschmiede gehört es zur örtlichen Bewährungsprobe, sich den Wendigos im Graufelsbau zu stellen.",["race:Gnome"]="Wenn Ihr unter den Zwergen rund um Kharanos lebt, könnt Ihr helfen, Eisenschmiedes schwere gepanzerte Maschinen auszurüsten."},sec={{t="Eine Mutprobe",b="Steinsegel stellt Neulinge auf die Probe, bevor er ihnen die Arbeit anvertraut. Ein gewaltiger Belagerungspanzer lässt sich in eisiger Bergluft nur schwer bedienen. Dafür braucht es eiserne Nerven und eine robuste Konstitution. Stellt Euch den einheimischen Bestien in den gefrorenen Hügeln, um zu beweisen, dass Ihr beides besitzt."},{t="Behaglichkeit im Trollpflüger",b="Die bittere Kälte Dun Moroghs dringt durch die enge, eisenbeschlagene Kabine des Trollpflügers. Steinsegel will dicke Wendigomähnen für einen warmen, strapazierfähigen Teppich auf dem Deck der Maschine. Die Jagd hilft auch, die örtlichen Bestien in Schach zu halten."}},faq={{q="Wer ist Pilot Steinsegel?",a="Pilot Steinsegel ist ein zwergischer Belagerungsmaschinenfahrer, der vor Kharanos in Dun Morogh stationiert ist. Er steuert den Trollpflüger, eine gepanzerte Kriegsmaschine, und ist stolz auf seine eisernen Nerven und sein mechanisches Handwerk.",al={"pilot steinsegel","wer vergibt die quest","wer ist steinsegel"}},{q="Wo liegt der Graufelsbau?",a="Zum Zusehen verdammt liegt in den schneebedeckten Bergen direkt westlich von Kharanos. Seine Höhlen bieten den bösartigen Wendigos Dun Moroghs Unterschlupf.",al={"graufelsbau lage","wo ist die wendigohöhle","wie den graufelsbau finden"}},{q="Warum will Steinsegel Wendigomähnen?",a="Steinsegel will Wendigofell für einen warmen Teppich auf dem Innendeck des Trollpflügers. Das Sammeln der Pelze stellt zugleich den Mut eines Abenteurers auf die Probe.",al={"warum wendigomähnen","zweck der mähnen","wofür sind die mähnen"}},{q="Was ist der Trollpflüger?",a="Der Trollpflüger ist Pilot Steinsegels persönliche zwergische Belagerungsmaschine. Sein Name spiegelt den Konflikt zwischen den Zwergen aus Eisenschmiede und den feindseligen Frostmane-Trollen in den umliegenden Felsklippen wider.",al={"trollpflüger","steinsegels panzer","was ist der trollpflüger"}},{q="Welche Kreaturen bewohnen den Graufelsbau?",a="Wilde Wendigos bewohnen den Graufelsbau. Diese ungezähmten, affenartigen Bestien sind in Dun Moroghs verschneiten Höhen heimisch und verteidigen ihr Revier erbittert.",al={"monster im graufelsbau","was lebt im graufelsbau"}},{q="Sind die Wendigos eine Gefahr für Kharanos?",a="Wendigos organisieren nur selten Angriffe wie die Frostmane-Trolle. Doch ihre brutale Wildheit und die Nähe zu den Hauptstraßen gefährden Reisende und örtliche Handwerker.",al={"sind wendigos eine bedrohung","wendigo gefahr"}}},fx={["9edb896b"]={q="Wofür werden die Wendigomähnen verwendet?",a="Pilot Steinsegel will die dicken, zotteligen Mähnen der Wendigos aus The Grizzled Den für einen sehr praktischen Luxus für Zwerge: die Inneneinrichtung. Eine massive Belagerungsmaschine wie den Trollpflug bei der beißenden Kälte von Dun Morogh zu bedienen, lässt den Metalldeckboden unter den Füßen gefrieren. Steinsegel plant, die geernteten Mähnen zu einem warmen, schweren Teppich zusammenzunähen, um die Kabine des Trollpflugs während langer Patrouillen gemütlicher zu machen.",al={"nutzen wendigomähne","wofür ist wendigomähne","warum wendigomähnen"}},["72b90979"]={q="Warum schickt Pilot Steinsegel Euch anstatt die Mähnen selbst zu holen?",a="Steinsegel ist Pilot einer Belagerungsmaschine, und die Instandhaltung einer Eisenmaschine wie des Trollpflugs sowie deren Verteidigungsbereitschaft in Kharanos erfordern seine volle Aufmerksamkeit. Die Jagd auf wendige, wilde Wendigos in engen, zugefrorenen Höhlengängen ist keine Arbeit, die für eine massive Kriegsmaschine geeignet ist. Steinsegel betrachtet die Aufgabe auch als eine offene Herausforderung, um zu sehen, ob Ihr den Mut, das Rückgrat und die Nerven besitzt, die man von den Verteidigern von Dun Morogh verlangt.",al={"warum ich steinsegel","warum braucht steinsegel hilfe","warum mähnen nicht selbst holen"}}},fp="16,162,14.246.0,30.212.0,23.192.0,34.127.0,38.128.0,18.177.0,48.148.0,39.161.0"}
P.entries["quest:3130"] = {n="Gegen die Hasskämme",s="In der Mondfederfeste schickt Shandris Euch zu Latronicus, während sie die Bedrohung durch die Naga abwägt.",h="In der Mondfederfeste schickt Shandris Euch zu Latronicus, während sie die Bedrohung durch die Naga abwägt.",kw={"against the hatecrest","mondfederfeste","feralas","hatecrest","horde","latronicus moonspear","naga","shandris mondfeder"},sec={{t="Shandris wägt das Risiko ab",b="Generalin Shandris Mondfeder schickt Euch zu Latronicus Moonspear, ihrem Stellvertreter. Er hat die Streitkräfte der Naga genau beobachtet, und Shandris muss abschätzen, welche Gefahr insgesamt von ihnen ausgeht.\n\nSie würde gern ihre gesamte Streitmacht gegen sie einsetzen. Doch dann wäre die Mondfederfeste einem direkten Angriff der Horde oder etwas Schlimmerem schutzlos ausgeliefert. Latronicus erwartet Euch in der Feste."},{t="Was Latronicus beabsichtigt",b="Latronicus Moonspear sagt, Generalin Shandris habe ihn beauftragt, die Naga direkt zu bekämpfen. Sein Plan besteht aus zwei Teilen: ihre Reihen lichten und ihre Führung schwächen, dann herausfinden, was sie in den Ruinen tun.\n\nMit Eurer Hilfe lässt sich den Naga Einhalt gebieten, während die Mondfederfeste gesichert bleibt."}},faq={{q="Warum schickt Shandris Mondfeder Euch zu Latronicus?",a="Shandris wird ihre gesamte Streitmacht nicht gegen die Naga einsetzen, wenn die Mondfederfeste dadurch der Horde oder etwas Schlimmerem schutzlos ausgeliefert wäre. Sie schickt Euch zu Latronicus, ihrem Stellvertreter, der die Naga beobachtet hat.",al={"warum mit latronicus sprechen","warum latronicus moonspear","mondfeder verweisung"}},{q="Wo befindet sich Latronicus Moonspear?",a="Latronicus Moonspear befindet sich in der Mondfederfeste, wo Shandris Euch zu ihm schickt, damit Ihr Euch bei ihm meldet.",al={"latronicus standort","wo ist latronicus","latronicus moonspear finden"}},{q="Was ging diesem Auftrag voraus?",a="Ihr kehrt zur Mondfederfeste zurück, und Shandris schickt Euch weiter zu Latronicus.",al={"against the hatecrest voraussetzung","vorherige quest","hatecrest questreihe start"}}},fp="21,90,24.362.0,23.285.1,53.202.0,38.93.0,33.78.0"}
P.entries["quest:314"] = {n="Die Herde beschützen",s="Auf dem Gehöft Bernruh fürchtet Rudra Amberstill, dass Vagash weitere wertvolle Bergwidder reißt. Er bittet vorbeiziehende Kämpfer, die Herde zu schützen und einen Beweis für den Tod des Raubtiers zu bringen.",h="Auf dem Gehöft Bernruh fürchtet Rudra Amberstill, dass Vagash weitere wertvolle Bergwidder reißt.",kw={"gehöft bernruh","dun morogh","eisenschmiede","bergwidder","die herde beschützen","rudra amberstill","vagash","veron bernruh"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euer Geschick in Dun Moroghs Schneewehen auf die Probe, wenn Ihr Vagash bis zu seinem Unterschlupf in den Bergen verfolgt.",["faction:Alliance"]="Als Kämpfer der Allianz könnt Ihr ländlichen Gehöften helfen, während Regimenter von High Seat die Verpflichtungen der Allianz in den Östlichen Königreichen unterstützen.",["race:Dwarf"]="Als Zwerg könnt Ihr helfen, die Bergwidder zu verteidigen, die Euer Volk in ganz Khaz Modan in die Schlacht tragen."},sec={{t="Bedrohung für das Gehöft",b="Vagash hat zwei wertvolle Bergwidder vom Gehöft Bernruh gerissen. Das Gehöft versorgt die Bronzebeardzwerge mit Reit- und Arbeitstieren, und die Herde stützt die ländliche Wirtschaft von Dun Morogh. Vagash jagt das Vieh der Umgebung in den zerklüfteten Felsen oberhalb des Gehöfts."},{t="Überlastete Verteidigung",b="Eisenschmiedes Streitkräfte sind über das ganze Reich verstreut und unterstützen die Allianz an fernen Fronten. Da keine Militärpatrouille die Bergkämme bewacht, bittet Rudra Amberstill unabhängige Kämpfer, Vagash zu jagen. Er verlangt einen der tödlichen Reißzähne der Bestie als Beweis."}},faq={{q="Wer ist Vagash?",a="Vagash ist ein gefährliches Raubtier, das auf den verschneiten Bergkämmen oberhalb des Gehöfts Bernruh umherstreift. Seine Stärke und sein unbändiger Hunger bedrohen die wertvollen Widder des Gehöfts und Reisende im Osten von Dun Morogh.",al={"was ist vagash","vagash monster","vagash hintergrundgeschichte"}},{q="Wo ist Vagash zu finden?",a="Vagash hat seinen Unterschlupf in einer schneebedeckten Höhle hoch in den zerklüfteten Felsen oberhalb des Gehöfts Bernruh. Steigt den verschneiten Hügel jenseits der Kiefern hinter dem Gehöft hinauf, um ihren Eingang zu erreichen.",al={"vagash aufenthaltsort","wo ist vagash","vagash finden"}},{q="Warum kümmern sich die Wachen von Eisenschmiede nicht darum?",a="Eisenschmiedes Streitkräfte sind auf ferne Garnisonen und Feldzüge der Allianz verteilt und stark beansprucht. Das Gehöft Bernruh hat keine militärische Hilfe in der Nähe, daher müssen seine Züchter das Gehöft verteidigen oder fähige Kämpfer suchen.",al={"warum keine wachen","wo ist eisenschmiedes armee","warum amberstill helfen"}},{q="Wer ist Veron, den Rudra erwähnt?",a="Veron Bernruh züchtet, trainiert und versorgt die Reitwidder der Bronzebeardzwerge auf dem Gehöft. Rudra sagt, Veron werde erleichtert sein, wenn das Raubtier verschwunden ist, das ihren wertvollen Tieren nachstellt.",al={"wer ist veron","veron bernruh","veron"}},{q="Warum wird ein Beweis für die Tötung verlangt?",a="Rudra will Vagashs Reißzahn als Beweis dafür, dass das Monster, das die Herde terrorisiert, tot ist, und nicht irgendein gewöhnliches Raubtier von den Berghängen.",al={"warum vagashs reißzahn","fangzahn von vagash","was ist der beweis"}},{q="Welche Bedeutung haben die Widder für Dun Morogh?",a="Bergwidder sind auf dem eisigen, felsigen Boden von Khaz Modan widerstandsfähig und trittsicher. Sie dienen den Zwergen als Zugtiere, Wolllieferanten und Reittiere für die Kavallerie.",al={"warum sind widder wichtig","zweck der widder vom gehöft bernruh","zwergenwidder hintergrundgeschichte"}}},fx={["81b569d0"]={q="Warum will Rudra Amberstill, dass dies erledigt wird?",a="Rudra Amberstill verteidigt die Lebensgrundlage ihrer Familie. Das Gehöft Bernruh züchtet und pflegt die robusten Bergwidder, die in ganz Dun Morogh und Eisenschmiede geschätzt werden. Vagash hat begonnen, in der Nähe des Gehöfts herumzustreunen und schleicht sich im Schutz der Dunkelheit heran, um das Vieh zu töten. Da bereits zwei preisgekrönte Widder in einer einzigen Nacht verschleppt wurden, kann das Gehöft keine fortwährenden Überfälle eines solch bösartigen Raubtiers überstehen.",al={"warum will rudra vagash tot","rudra amberstills motiv","warum vagash töten"}},["34abe682"]={q="Wozu dient der Fangzahn von Vagash?",a="Der Fangzahn dient als unbestreitbarer physischer Beweis dafür, dass die gefürchtete Bestie tatsächlich erlegt wurde. Vagash ist auf dem Gehöft für seine Größe und Wildheit berüchtigt, und Rudra Amberstill braucht absolute Gewissheit, dass das Raubtier, das auf den Felsen über ihnen lauert, tot ist, bevor sie und ihre Familie sich wegen ihrer überlebenden Herde beruhigen können.",al={"warum fangzahn von vagash nötig","zweck fangzahn von vagash","vagash zahn"}}},fp="19,175,21.251.0,17.255.0,14.189.0,26.169.0,47.199.0,32.179.0,34.133.0,47.154.0"}
P.entries["quest:315"] = {n="Das perfekte Starkbier",s="In Bräuhall strebt Rejold Gerstenbräu noch immer nach dem perfekten Starkbier. Er schöpft aus der Brautradition seiner Familie und exotischen heimischen Zutaten und sucht nun Schimmerkraut, eine scharf schmeckende Pflanze, die nur die feindseligen Frostmähnentrolle auf dem Schimmergrat anbauen. Er schickt wagemutige Reisende in ihr Lager, um das Kraut aus den Stammeskörben zu entwenden.",h="In Bräuhall strebt Rejold Gerstenbräu noch immer nach dem perfekten Starkbier.",kw={"bräuhall","dun morogh","zwergenbräu","frostmähnen","perfektes starkbier","rejold gerstenbräu","schimmergrat","schimmerkraut"},ang={["profession:Herbalism"]="Als Kräuterkundiger mögt Ihr Schimmerkraut eine faszinierende Neuheit finden. Seine ungewöhnlichen botanischen Eigenschaften lassen es auf den eisigen Felsen von Dun Morogh überleben.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass das Brauen dem Clan Bronzebeard beinahe heilig ist. Ein exotisches Kraut zu finden, um rivalisierende Schenken zu übertreffen, ist ein edles Unterfangen."},sec={{t="Der Ehrgeiz eines Brauers",b="Das Brauen ist in Bräuhall eine Lebensart, besonders für die Familie Gerstenbräu. Rejold Gerstenbräu glaubt, dass ihm wahre Größe im Blut liegt, doch das perfekte Starkbier verlangt nach neuen Ideen. Er blickt über Hopfen, Malz und Gebirgsquellwasser hinaus auf die Wildpflanzen von Dun Morogh und hofft, seinem Bier damit eine unverwechselbare Schärfe zu verleihen."},{t="Das Trollkraut vom Schimmergrat",b="Östlich von Bräuhall bauen die Frostmähnentrolle auf dem Schimmergrat Schimmerkraut an. Sie sammeln es für Stammesrituale und mystische Riten, während Zwerge es wegen seines scharfen, unverwechselbaren Geschmacks kennen. Das Kraut wird in Körben im Trolldorf aufbewahrt, wo Rejolds neuestes und kühnstes Brauexperiment darauf wartet."}},faq={{q="Was ist Schimmerkraut?",a="Schimmerkraut ist eine besondere Pflanze, die von den Frostmähnentrollen auf dem Schimmergrat angebaut und geerntet wird. Sie verwenden es hauptsächlich für Stammeszeremonien und Rituale, während Rejold Gerstenbräu hofft, dass sein scharfer Geschmack der zwergischen Braukunst etwas Neues bringt.",al={"schimmerkraut hintergrund","was bewirkt schimmerkraut","frostmähnen pflanze"}},{q="Wo liegt der Schimmergrat?",a="Der Schimmergrat erhebt sich im nördlichen Dun Morogh, östlich von Bräuhall. Er dient den dort heimischen Frostmähnentrollen als befestigtes Lager, weshalb das Kräutersammeln dort bedeutet, feindliches Gebiet zu betreten.",al={"schimmergrat lage","wo liegt der schimmergrat","wie den schimmergrat finden"}},{q="Warum will Rejold die Frostmähnentrolle bestehlen?",a="Nur die Frostmähnentrolle bauen in Dun Morogh Schimmerkraut an, und die Spannungen zwischen Zwergen und Trollen machen friedlichen Handel unmöglich. Rejold bleibt nur, sich in ihr Lager zu schleichen oder hindurchzukämpfen, um die geernteten Pflanzen aus ihren Stammeskörben zu entwenden.",al={"warum trolle bestehlen","warum trollkörbe","rejolds trollplan"}},{q="Wer ist Rejold Gerstenbräu?",a="Rejold Gerstenbräu ist ein ehrgeiziger zwergischer Brauer, der in Bräuhall lebt. Auf der Suche nach dem perfekten Starkbier experimentiert er mit neuen Geschmacksnoten und kräftigen wilden Zutaten.",al={"wer ist rejold","rejold gerstenbräu","familie gerstenbräu"}},{q="Gilt Schimmerkraut als Alchemiekraut?",a="Nein. Schimmerkraut ist kein alchemistisches Reagenz, das an wilden Kräutervorkommen gesammelt wird. Es ist der gesuchte Gegenstand, der in Weidenkörben und Vorratsverstecken überall in den Siedlungen der Frostmähnen auf dem Schimmergrat lagert.",al={"können kräuterkundige schimmerkraut pflücken","ist schimmerkraut kräuterkunde","schimmerkraut sammeln"}},{q="Was geschieht nach der Abgabe mit dem Schimmerkraut?",a="Wenn das Schimmerkraut ihn in Bräuhall erreicht, wirft Rejold es in einen bereits gärenden Sud. Er hofft, dass sein einzigartiger Geschmack ihm endlich zu dem makellosen Rezept verhilft, das er sucht.",al={"gelingt das starkbier","rejolds brauergebnis","schimmerkraut bier"}}},fx={["3780a202"]={q="Wer sind die Frostmähnentrolle?",a="Die Frostmähne sind ein einheimischer Stamm von Eistrollen, die auf den verschneiten Felsen von Dun Morogh heimisch sind. Von den expandierenden Zwergen aus Eisenschmiede aus ihren historischen Jagdgründen vertrieben, hegen sie eine tiefe Feindseligkeit gegenüber ihren zwergischen Nachbarn. Von Siedlungen wie der auf dem Schimmergrat aus kultivieren sie Schimmerkraut für ihre Stammesrituale und verteidigen ihre Lager erbittert gegen jeden Eindringling.",al={"frostmähnentrolle","wer sind die trolle auf dem schimmergrat","frostmähnentamm"}}},fp="17,335,19.319.0,31.300.0,20.238.0,31.188.0,56.267.0,25.170.0,42.191.0,47.182.0"}
P.entries["quest:3161"] = {n="Gahz'ridian",s="In Tanaris sucht Marvon Rivetseeker dreißig Verzierungen, die von den einstigen Trollen des Landes hinterlassen wurden. Er gibt Euch einen selbst gebauten Detektor, der Euch bei der Suche hilft.",h="In Tanaris sucht Marvon Rivetseeker dreißig Verzierungen, die von den einstigen Trollen des Landes...",kw={"zerbrochene säule","detektor","ostmondruinen","gahz'ridian","gahz'rilla","marvon rivetseeker","südmondruinen","tanaris","troll"},sec={{t="Relikte des Hydragottes",b="Vor langer Zeit lebten Trolle in Tanaris und schnitzten Verzierungen nach dem Abbild von Gahz'rilla, der Hydra, die sie als Gott verehrten. Marvon Rivetseeker benannte das Element in den Schnitzereien nach der Hydra: Gahz'ridian. Er hat einige Verzierungen gefunden und möchte weitere untersuchen."},{t="Der Detektor",b="Marvon Rivetseeker gibt Euch einen Detektor, den er erfunden hat, um Gahz'ridian leichter zu finden. Legt ihn an, und die Suche beginnt. Die Verzierungen können fast überall in Tanaris liegen. Am häufigsten sind sie nahe der Zerbrochenen Säule, der Ostmondruinen und der Südmondruinen zu finden."}},faq={{q="Wer ist Marvon Rivetseeker?",a="Marvon Rivetseeker ist ein Wissenschaftler in Tanaris, der Verzierungen der einstigen Trolle untersucht und ein Herz für die Schatzsuche hat.",al={"marvon rivetseeker","wer vergibt gahzridian","questgeber"}},{q="Was ist Gahz'ridian?",a="Gahz'ridian ist der Name, den Marvon Rivetseeker dem Element gab, das in die Verzierungen der Trolle zu Ehren des Hydragottes geschnitzt wurde.",al={"was ist gahzridian","gahzridian mineral","gahzridian material"}},{q="Wer ist Gahz'rilla?",a="Gahz'rilla ist eine Hydra, die von den einstigen Trollen als Gott verehrt wurde. Sie schnitzten Verzierungen nach ihrem Abbild.",al={"gahzrilla gottheit","hydraverehrung","wer ist gahzrilla"}},{q="Wo findet man Gahz'ridian-Verzierungen?",a="Gahz'ridian-Verzierungen lassen sich fast überall in Tanaris finden, doch am häufigsten sind sie nahe der Zerbrochenen Säule, der Ostmondruinen und der Südmondruinen.",al={"wo gahzridian finden","bester ort für gahzridian","gahzridian fundorte"}},{q="Wie findet Ihr die Verzierungen?",a="Marvon Rivetseeker hat einen Detektor erfunden, der beim Finden der Verzierungen hilft. Legt ihn an, um die Suche zu beginnen.",al={"wie verzierungen erkennen","gahzridian detektor","gahzridian finden"}}},fp="11,145,23.255.0,12.251.0,26.127.0,20.111.0,18.93.0,38.148.0,30.95.0"}
P.entries["quest:317"] = {n="Vorräte für Dampfstrahl",s="Bei Stahlrosts Depot bereitet Pilot Bellfiz Jetsteam auf einen langen Einsatz mit der Belagerungsbrigade von Eisenschmiede vor. Seine Besatzung braucht Eberfleisch und Bärenpelze für die Reise.",h="Bei Stahlrosts Depot bereitet Pilot Bellfiz Jetsteam auf einen langen Einsatz mit der Belagerungsbrigade von...",kw={"bärenpelze","eberfleisch","dun morogh","der graufelsbau","jetsteam","pilot bellfiz","belagerungsbrigade","stahlrosts depot"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, zwergische Reparaturhöfe mit den Panzerbesatzungen der Belagerungsbrigade zu verbinden und die Belagerungstechnik der Allianz einsatzfähig zu halten.",["profession:Cooking"]="Als Koch könnt Ihr das Eberfleisch verwenden, das die Gebirgsgarnisonen von Dun Morogh ernährt.",["race:Dwarf"]="Als Zwerg helft Ihr, die Besatzungen der Belagerungsbrigade zu verpflegen und ihnen Ruhe zu ermöglichen, während sie von Khaz Modans Maschinenhöfen aus operieren.",["race:Gnome"]="Als Gnom sichert Eure Hilfe die Versorgung der zwergischen Belagerungsbrigade auf ihren langen Feldzügen. Die Brigade ist mit den vertriebenen Gnomen verbündet."},sec={{t="Vorräte für die Maschine",b="Meisteringenieur Beldin Stahlrost stimmt den Belagerungspanzer bei Stahlrosts Depot ab, direkt vor Kharanos. Jetsteam wird für einen Einsatz im Auftrag der Belagerungsbrigade vorbereitet. Die Besatzung braucht Proviant für einen Monat, um den Minusgraden von Dun Morogh standzuhalten."},{t="Jagd auf den Schneefeldern",b="Beldin Stahlrost arbeitet unter Jetsteams Haube, weshalb Bellfiz das Fahrzeug nicht verlassen kann, um Nahrung und Isoliermaterial zu beschaffen. Auf den verschneiten Ebenen südlich des Graufelsbaus leben Eber, die Fleisch liefern, und Bären, deren Pelze die Schlafstätten im Panzer auskleiden und warm halten können."}},faq={{q="Was ist Jetsteam?",a="Jetsteam ist der Belagerungspanzer, den Pilot Bellfiz, ein Zwerg, steuert. Bei Stahlrosts Depot wird er für einen langen Einsatz mit der Belagerungsbrigade von Eisenschmiede abgestimmt und mit Vorräten bestückt.",al={"jetsteam","wer ist jetsteam","was ist jetstream","bellfiz panzer"}},{q="Wer ist Pilot Bellfiz?",a="Pilot Bellfiz, genannt Fizzer, ist ein zwergischer Pilot einer Belagerungsmaschine bei der Belagerungsbrigade von Eisenschmiede. Während sein Fahrzeug bei Stahlrosts Depot eingestellt wird, koordiniert er die Versorgung für eine bevorstehende Mission.",al={"pilot bellfiz","bellfiz","wer ist pilot bellfiz"}},{q="Wo lassen sich die benötigten Vorräte sammeln?",a="Auf den verschneiten Ebenen südlich des Graufelsbaus leben die Eber und Bären, deren Fleisch und Pelze Nahrung und Schlafunterlagen liefern.",al={"wo sind die eber","wo sind bären","jagdgebiet","eberfleisch dun morogh"}},{q="Was ist die Belagerungsbrigade?",a="Die Belagerungsbrigade ist Eisenschmiedes Korps von Belagerungsmaschinenpiloten. Ihre schwer gepanzerten Maschinen, darunter Jetsteam und Trollplow, unterstützen die Verteidigung der Zwerge und die Feldzüge der Allianz.",al={"belagerungsbrigade"}},{q="Wohin führt diese Mission als Nächstes?",a="Sobald Jetsteam wieder mit Fleisch und Pelzen versorgt ist, schickt Pilot Bellfiz Reisende nach Westen nach Bräuhall, um Evershine zu holen. Er nutzt das starke Gebräu, um sich warm zu halten, und als Notbrennstoff für die Feuerung des Panzers.",al={"nächste quest","was kommt nach vorräte für dampfstrahl","vorräte für dampfstrahl folgequest"}},{q="Warum braucht eine Belagerungsmaschine Tierpelze?",a="Zwergische und gnomische Dampfpanzer werden bei langen Einsätzen im Schnee der Berge eisig kalt und zugig. Dicke Bärenpelze halten die Schlafstätten der Besatzung bei längeren Aufenthalten fernab des Lagers warm.",al={"warum pelz","dickes bärenfell verwendung","schlafunterlagen"}}},fx={bd6a237a={q="Warum will Pilot Bellfiz, dass dies erledigt wird?",a="Pilot Bellfiz rüstet sich für einen längeren Einsatz mit der Belagerungsbrigade. Die bevorstehende Mission wird ihn mindestens einen Monat lang im Feld halten, und der Betrieb tief in der eisigen Wildnis von Dun Morogh erfordert eine sorgfältige Vorbereitung. Er benötigt reichlich Vorräte, die an Bord von Jetsteam verstaut werden müssen, bevor er in den aktiven Dienst geht.",al={"pilot bellfiz motiv","warum jetsteam bestücken","warum braucht bellfiz vorräte"}},f0e85f28={q="Wozu dient das Stück Eberfleisch?",a="Das Eberfleisch dient als lebenswichtige Ration für Pilot Bellfiz’ bevorstehenden einmonatigen Einsatz. Der Betrieb einer schweren Belagerungsmaschine in der eisigen Kälte verbrennt viel Energie, und haltbares Fleisch, das von den örtlichen Felsebern gesammelt wird, liefert die Nahrung, die er benötigt, während er weit entfernt von freundlichen Außenposten stationiert ist.",al={"nutzen stück eberfleisch","warum eberfleisch","eberfleisch jetsteam"}},["779906a6"]={q="Warum braucht Pilot Bellfiz Euch für die Jagd?",a="Bellfiz kann die Zeit nicht für die Jagd aufbringen, da er die Wartung von Jetsteam beaufsichtigt. Der Mechanikermeister Beldin Stahlrost stimmt den Panzer in Stahlrosts Depot aktiv ab und repariert ihn, was erfordert, dass der Pilot in der Nähe bleibt und sicherstellt, dass die Maschine ordnungsgemäß für die Abreise vorbereitet ist.",al={"warum kann bellfiz nicht jagen","warum ich bellfiz","warum muss ich für bellfiz jagen"}}},fp="17,169,23.257.0,23.248.0,17.177.0,23.202.0,44.114.0,26.174.0,34.201.1,44.185.0"}
P.entries["quest:318"] = {n="Immerschimmer",s="In Stahlrosts Depot nahe Kharanos braucht Pilot Bellfiz Evershine von Rejold Gerstenbräu aus Bräuhall. Das starke Gebräu wärmt ihn und kann seine Belagerungsmaschine Dampfstrahl antreiben.",h="In Stahlrosts Depot nahe Kharanos braucht Pilot Bellfiz Evershine von Rejold Gerstenbräu aus Bräuhall.",kw={"bräuhall","dun morogh","evershine","dampfstrahl","kharanos","pilot bellfiz","rejold gerstenbräu"},ang={["profession:Engineering"]="Als Ingenieur erkennt Ihr, wie leicht entzündlicher Schnaps Piloten wie Bellfiz eine weitere Möglichkeit bietet, Belagerungsmaschinen unter rauen Bedingungen am Laufen zu halten.",["race:Dwarf"]="Als Zwerg kennt Ihr die feurigen Extreme zwergischer Braukunst, und Rejold Gerstenbräus Schnaps bringt sie auf Dun Moroghs kalte Gipfel.",["race:Gnome"]="Als Gnom wisst Ihr vielleicht zu schätzen, wie Pilot Bellfiz gewöhnliche Dinge, sogar zwergisches Gebräu, in improvisierten Treibstoff verwandelt."},sec={{t="Ein starkes Gebräu",b="Rejold Gerstenbräus Brauexperimente gehen über gewöhnliche Zwergenbiere hinaus. Evershine kann alle außer den widerstandsfähigsten Zwergen umhauen, doch seine Wärme wird in Dun Moroghs bitterer Kälte geschätzt."},{t="Treibstoff für Pilot Bellfiz",b="In Stahlrosts Depot außerhalb von Kharanos nimmt Pilot Bellfiz einen wärmenden Schluck Evershine gegen die eisigen Winde. Das leicht entzündliche Gebräu kann auch Dampfstrahls Feuerung speisen. Wenn Bellfiz in einer misslichen Lage steckt, verleiht es seiner Belagerungsmaschine einen explosiven Notfallschub."}},faq={{q="Was ist Evershine?",a="Evershine ist ein außergewöhnlich starkes, experimentelles Gebräu des zwergischen Brauers Rejold Gerstenbräu aus Bräuhall. Seine feurige Stärke kann selbst trinkfeste Zwerge umhauen.",al={"was ist evershine","evershine gebräu","was für ein getränk ist evershine"}},{q="Warum will Pilot Bellfiz Evershine?",a="Pilot Bellfiz trinkt Evershine, um sich gegen Dun Moroghs Kälte zu wärmen, und nutzt es als Notfalltreibstoff. In Dampfstrahls Feuerung verleiht der leicht entzündliche Schnaps der Belagerungsmaschine einen sofortigen Kraftschub.",al={"warum bellfiz das gebräu will","pilot bellfiz evershine","warum braucht bellfiz es"}},{q="Wo liegt Bräuhall?",a="Bräuhall liegt im Westen von Dun Morogh, an der Straße westlich von Kharanos. Brauer wie Rejold Gerstenbräu leben dort nahe den verschneiten Hügeln.",al={"wo liegt bräuhall","bräuhall lage","bräuhall finden"}},{q="Wer ist Rejold Gerstenbräu?",a="Rejold Gerstenbräu ist ein experimentierfreudiger zwergischer Brauer in Bräuhall. Er stellt viele Getränke her, von wohlschmeckenden Bieren bis zu scharfen Gebräuen, die stark genug sind, um Maschinenfeuerungen zu entzünden.",al={"wer ist rejold","rejold gerstenbräu infos","gerstenbräu brauer"}},{q="Wie geht es weiter, nachdem Ihr Rejold Gerstenbräu erreicht habt?",a="Rejold braucht Hilfe, bevor er seinen Schnaps herausgibt. In Bräuhall findet Ihr A Favor for Evershine, wo Ihr dem Brauer helft, bevor er Euch ein Fass für Pilot Bellfiz gibt.",al={"nächste quest nach evershine","was kommt nach evershine","rejold folgequest"}},{q="Kann man Evershine wirklich bedenkenlos trinken?",a="Pilot Bellfiz sagt, dass Evershine fast jeden Zwerg umhaut, der es probiert. Die stärksten Bergbewohner können es trinken, doch seine extreme Entflammbarkeit macht es auch für eine Maschinenfeuerung nützlich.",al={"kann man evershine trinken","ist evershine gift","evershine gefährlich"}}},fp="9,179,19.179.0,24.268.0,18.177.0,40.201.0,26.144.0,25.171.0,49.181.1,33.188.0"}
P.entries["quest:3181"] = {n="Das Horn der Bestie",s="In der Sengenden Schlucht steckt eine abgebrochene Axtklinge im Horn von Margol the Rager.",h="In der Sengenden Schlucht steckt eine abgebrochene Axtklinge im Horn von Margol the Rager.",kw={"gigantisches horn","loch modan","margol the rager","pebblebitty","sengende schlucht","steinwerkpass"},sec={{t="Ein zerschmetterter Hinweis",b="Das Horn von Margol the Rager ist zerkratzt und rissig. Eine abgebrochene Axtklinge steckt in seiner rauen Oberfläche, und der Name von Gebirgsjägerin Pebblebitty ist im Metall zu sehen. Als Ihr versucht, sie zu lösen, zerspringt die Axtklinge in eine Million Stücke."},{t="Das Tor",b="Der Steinwerkpass verläuft zwischen Loch Modan und der Sengenden Schlucht. Das Horn ist der Auftakt der Questreihe, die das Tor öffnet, und Ihr sollt es zu Gebirgsjägerin Pebblebitty bringen. Pebblebitty ist nicht bereit, das Tor zu öffnen."},{t="Am Tor",b="Gebirgsjägerin Pebblebitty bezeichnet das Horn als offensichtliche Fälschung. Pebblebitty ist Margol begegnet und sagt, ihr Horn sei viel größer als Eures, mindestens achtmal so groß. Pebblebitty sagt, Eures stamme wahrscheinlich von einem stormsnout im Brachland."}},faq={{q="Woher stammt dieses Horn?",a="Das Horn von Margol the Rager stammt aus der Sengenden Schlucht.",al={"wo finde ich das horn","aufenthaltsort von margol the rager","wer lässt das horn fallen"}},{q="Wer ist Gebirgsjägerin Pebblebitty?",a="Gebirgsjägerin Pebblebitty ist die Gebirgsjägerin, zu der Ihr das Horn bringen sollt. Pebblebitty ist nicht bereit, das Tor zu öffnen.",al={"pebblebitty","wer ist pebblebitty","gebirgsjägerin pebblebitty"}},{q="Was geschieht mit dem Axtkopf im Horn?",a="Die Axtklinge trägt den Namen von Gebirgsjägerin Pebblebitty. Als Ihr versucht, sie zu lösen, zerspringt sie in eine Million Stücke.",al={"warum steckte pebblebittys axt im horn","inschrift auf dem axtkopf"}},{q="Wozu führt das Horn?",a="Das Horn ist der Auftakt der Questreihe, die den Steinwerkpass zwischen Loch Modan und der Sengenden Schlucht öffnet.",al={"steinwerkpass","was ist der schlüssel zur sengenden schlucht"}}},fp="21,66,16.221.0,8.203.0,11.230.1,31.49.0,31.114.0,41.110.0,27.92.1"}
P.entries["quest:319"] = {n="Ein Gefallen für etwas Immerschimmer",s="Bei Stahlrosts Depot braucht Pilot Bellfiz Evershine für seine Belagerungsmaschine Jetsteam. Rejold Gerstenbräu gibt erst ein Fass heraus, wenn Ihr die Raubtiere aus der Umgebung von Bräuhall vertrieben habt.",h="Bei Stahlrosts Depot braucht Pilot Bellfiz Evershine für seine Belagerungsmaschine Jetsteam.",kw={"bellfiz","bräuhall","dun morogh","uralter felseber","evershine","eisklauenbär","rejold gerstenbräu","schneeleopard"},ang={["class:Hunter"]="Als Jäger stellt Ihr Eure Treffsicherheit an den zähesten Winterbestien in den Felsen im Westen von Dun Morogh auf die Probe.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass wilde Raubtiere von einer ehrlichen Brennerei ferngehalten werden müssen.",["race:Gnome"]="Als Gnom wisst Ihr, dass die Belagerungsmaschinenpiloten und Tüftler bei Stahlrosts Depot auf das Fass warten. Sie verlassen sich auf Abenteurer, die den eigensinnigen Brauer besänftigen, damit die Vorbereitungen für Jetsteam weitergehen können."},sec={{t="Der Handel eines Brauers",b="Rejold bietet sein Gebräu an, wenn Ihr die wilden Tiere im Westen von Dun Morogh dezimiert. Eisklauenbären, uralte Felseber und Schneeleoparden streifen nahe Bräuhall umher. Ihre Anwesenheit gefährdet die Einheimischen und hält Rejold davon ab, das Fass ohne Weiteres herauszugeben."},{t="Ruhe für die Handwerker",b="Rejold sagt, kein Zwerg mit Selbstachtung kusche vor wilden Tieren. Doch nach Raubtieren rund um das Dorf Ausschau zu halten, kostet die Handwerker wertvolle Stunden. Sobald die Bestien vertrieben sind, können sich die Dorfbewohner aufs Destillieren und Schmieden konzentrieren, ohne den Waldrand im Auge behalten zu müssen."}},faq={{q="Warum will Rejold diese Tiere töten lassen?",a="Eisklauenbären, uralte Felseber und Schneeleoparden streifen nahe Bräuhall umher. Die Zwerge fürchten sie nicht, doch die Bestien zu vertreiben, kostet Stunden, die beim Brauen und Handwerken fehlen.",al={"warum bären töten","warum tiere bei bräuhall dezimieren","grund für rejolds auftrag"}},{q="Was ist Evershine?",a="Evershine ist ein starker, hochgeschätzter Schnaps, den nur Rejold Gerstenbräu in Bräuhall braut. Belagerungsmaschinenpiloten wie Pilot Bellfiz schätzen ihn als Getränk und als leicht entzündlichen Treibstoffzusatz.",al={"was ist evershine","evershine gebräu","rejolds schnaps"}},{q="Wer hat ursprünglich um Evershine gebeten?",a="Pilot Bellfiz bei Stahlrosts Depot hat Euch nach Evershine geschickt, damit es ihn unterwegs wärmt und im Feuerungskessel seiner Belagerungsmaschine Jetsteam für einen Leistungsschub sorgt.",al={"wer schickte mich nach evershine","wer will evershine","beginn der questreihe"}},{q="Wo sind die Tiere zu finden?",a="Die Tiere durchstreifen die gefrorenen Felder und Felsen rund um Bräuhall und den Eiswellensee im Westen von Dun Morogh.",al={"wo sind eisklauenbären","schneeleopard fundort","uralter felseber fundort"}},{q="Was geschieht, nachdem der Gefallen erledigt ist?",a="Sobald die Bestien dezimiert sind, gibt Rejold Euch ein Fass Evershine, das Ihr zu Pilot Bellfiz bei Stahlrosts Depot zurückbringen sollt.",al={"nächste quest","was folgt auf einen gefallen für etwas evershine"}},{q="Sind die Dorfbewohner durch die Raubtiere wirklich in Gefahr?",a="Rejold sagt, kein Zwerg mit Selbstachtung fürchte eine Bestie im Schnee. Doch Raubtiere vor der Haustür stören die tägliche Arbeit und stellen eine Gefahr dar.",al={"ist bräuhall in gefahr","haben zwerge angst"}}},fx={["02738ac5"]={q="Welche Tiere schickt Euch Rejold Gerstenbräu jagen?",a="Rejold schickt Euch, um die wilden Raubtiere und Bestien zu dezimieren, die in den Schneewehen um Bräuhall herumstreifen: Eiskrallenbären, Ältere Felseber und Schneeleoparden. Diese einheimischen Bestien wandern gefährlich nah an die Siedlungsgrenze, knurren und schnauben draußen, während die Dorfbewohner versuchen, sich um ihre Bottiche und Werkstätten zu kümmern.",al={"rejolds ziele","welche bestien","tiere töten für evershine","welche tiere bräuhall"}},fe0fe64f={q="Warum bittet Rejold Euch, anstatt die Dorfbewohner von Bräuhall die Bestien erledigen zu lassen?",a="Die Zwerge von Bräuhall haben kaum Angst vor der örtlichen Tierwelt – kein Zwerg mit Selbstachtung würde vor einem Eber oder Schneeleoparden zurückweichen. Doch die Jagd auf umherstreifende Raubtierrudel nimmt wertvolle Zeit von ihren wahren Leidenschaften in Anspruch: Bier brauen, Handwerk und die Pflege ihrer Bottiche. Da Ihr ein rüstiger Reisender seid, der ohnehin nach einem Fass von Evershine sucht, schließt Rejold einen Handel ab, damit sein Volk in Frieden weiterarbeiten kann.",al={"warum können dorfbewohner sie nicht töten","warum ich rejold","warum braucht rejold hilfe","jäger von bräuhall"}}},fp="21,187,18.238.0,23.265.0,42.176.0,18.185.0,39.168.0,31.108.0,40.120.0,54.133.0"}
P.entries["quest:32"] = {n="Aufstieg der Silithid",s="In Orgrimmar bringt Ihr den Bericht des Leitenden Feldmessers Rutenwünschels über die Insektenbedrohung zu Zilzibin Drumlore.",h="In Orgrimmar bringt Ihr den Bericht des Leitenden Feldmessers Rutenwünschels über die Insektenbedrohung zu...",kw={"drag","drumlore","rutenwünschels","insekten","orgrimmar","silithiden","tanaris","zilzibin"},sec={{t="Jemand, der sich auskennt",b="Leitender Feldmesser Rutenwünschels möchte den Bericht in den Händen von jemandem wissen, der solche Angelegenheiten versteht. Zilzibin Drumlore ist ein Trollgelehrter und Historiker, der viel Zeit damit verbracht hat, Azeroths einzigartige Lebensformen zu erforschen. Rutenwünschels hofft, dass Zilzibin herausfinden kann, worin die Gefahr besteht und wie sie aufgehalten werden könnte. Sie werden jede Hilfe brauchen, die sie bekommen können. Zilzibin lebt in einem Haus auf der zweiten Ebene der Drag in Orgrimmar."},{t="Zilzibins Antwort",b="Zilzibin Drumlore ist diesen Kreaturen schon früher begegnet. Er glaubt, dass Rutenwünschels gut daran getan hat, den Bericht und Euch zu schicken. Sie werden die Wüste von Tanaris rasch verschlingen und zu den größten Bedrohungen zählen, denen sich je jemand stellen muss. Es sind die Silithiden, Werkzeuge einer der schwersten Bedrohungen für Horde und Allianz gleichermaßen. Zilzibin beklagt, dass niemand die Gefahr früher erkannt hat."}},faq={{q="Wer ist Zilzibin Drumlore?",a="Zilzibin Drumlore ist ein Trollgelehrter und Historiker, der viel Zeit damit verbracht hat, die einzigartigen Lebensformen von Azeroths Ökologie zu erforschen.",al={"wer ist drumlore","zilzibin drumlore hintergrund","trollgelehrter in orgrimmar"}},{q="Wer schickt Euch zu Zilzibin?",a="Leitender Feldmesser Rutenwünschels gibt Euch den Bericht und bittet Euch, ihn nach Orgrimmar zu bringen.",al={"aufstieg der silithid beginn","wer vergibt aufstieg der silithid"}},{q="Wo in Orgrimmar befindet sich Zilzibin Drumlore?",a="Zilzibin Drumlore lebt in einem Haus auf der zweiten Ebene der Drag in Orgrimmar.",al={"wo ist zilzibin","wo ist drumlores haus"}},{q="Was kommt unmittelbar vor diesem Schritt?",a="Dies folgt auf Insect Part Analysis.",al={"vorherige quest aufstieg der silithid","was führte zu aufstieg der silithid"}}},fp="20,104,17.407.0,17.364.1,25.127.0,26.88.0,48.75.0,37.34.0"}
P.entries["quest:320"] = {n="Rückkehr zu Bellowfiz",s="Ihr bringt Evershine zu Pilot Bellfiz bei Stahlrosts Depot in Dun Morogh. Nach der örtlichen Jagd wartet der durstige Fahrer auf ein frisches Getränk.",h="Ihr bringt Evershine zu Pilot Bellfiz bei Stahlrosts Depot in Dun Morogh.",kw={"fass evershine","dun morogh","evershine","kharanos","pilot bellfiz","rückkehr zu bellowfiz","stahlrosts depot"},ang={["faction:Alliance"]="Als Mitglied der Allianz stärkt Ihr die Moral und Kameradschaft unter den Truppen in Dun Morogh, indem Ihr Gefälligkeiten zwischen zwergischen Jägern und Piloten überbringt.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass kräftiges Evershine in ganz Dun Morogh sehr gefragt ist. Es sicher zu durstigen Kameraden zu bringen, ist für Euch selbstverständlich.",["race:Gnome"]="Pilot Bellfiz ist ein zwergischer Belagerungsmaschinenfahrer bei Stahlrosts Depot. Wenn fleißige Ingenieure mit Getränken versorgt sind, laufen auch die Maschinen reibungslos."},sec={{t="Ein Fass fürs Depot",b="Nachdem Ihr bei der örtlichen Jagd geholfen habt, erhaltet Ihr ein frisches Fass Evershine für Pilot Bellfiz. Tragt es durch das verschneite Dun Morogh zu Stahlrosts Depot. Solche Gefallen helfen den Menschen im kalten Grenzland, füreinander zu sorgen."},{t="Durstige Flieger",b="Stahlrosts Depot liegt direkt vor Kharanos. Gnome testen dort Maschinen, warten Fahrzeuge und üben ihr Handwerk aus. Die Piloten trotzen eisigen Winden und freuen sich über ein starkes Getränk aus der Gegend. Als Ihr mit dem Fass eintrefft, brennt Pilot Bellfiz darauf, eine Flasche zu entkorken und das Gebräu der Einheimischen zu kosten."}},faq={{q="Was ist die Quest Rückkehr zu Bellowfiz?",a="Ihr bringt ein frisches Fass Evershine zu Pilot Bellfiz bei Stahlrosts Depot in Dun Morogh.",al={"was ist rückkehr zu bellowfiz","bellfiz quest"}},{q="Wer ist Pilot Bellfiz?",a="Pilot Bellfiz ist ein zwergischer Belagerungsmaschinenfahrer, der bei Stahlrosts Depot direkt vor Kharanos in Dun Morogh stationiert ist. Er brennt darauf, eine frische Lieferung Evershine zu probieren.",al={"wer möchte evershine","wer ist bellfiz"}},{q="Was ist das Fass Evershine?",a="Evershine ist ein starkes lokales Gebräu, das in Dun Morogh hergestellt und in einem robusten Fass aufbewahrt wird. Durstige Piloten und Einheimische schätzen es.",al={"was ist evershine","fass evershine"}},{q="Wo liefert Ihr das Fass ab?",a="Bringt das Fass zu Pilot Bellfiz bei Stahlrosts Depot, einem Ingenieurszentrum mit Werkstatt direkt östlich von Kharanos in Dun Morogh.",al={"wo ist bellfiz","bellfiz standort"}},{q="Warum wurde das Evershine an Bellfiz geschickt?",a="Nachdem Ihr bei der Jagd in der Region geholfen habt, erhaltet Ihr ein Fass Evershine für Pilot Bellfiz. Er wartet sehnsüchtig auf einen Schluck.",al={"warum evershine liefern","grund für evershine lieferung"}},{q="Was geschieht, wenn Bellfiz das Evershine erhält?",a="Als Pilot Bellfiz das Fass erhält, sagt er, dass es genau das Richtige sei, und macht sich sofort daran, eine Flasche zum Probieren zu öffnen.",al={"was macht bellfiz mit dem gebräu","bellfiz reaktion"}}},fp="19,141,20.218.0,16.291.0,38.91.0,23.168.0,30.114.0,30.124.0,40.122.0,51.116.0"}
P.entries["quest:321"] = {n="Lichtgeschmiedetes Eisen",s="Im Hafen von Menethil sucht Glorin Stahlbraue nach Fracht, die mit einem elfischen Zerstörer verloren ging. Die Flying Osprey trug seltenes Lichtgeschmiedetes Eisen, als sie im Zweiten Krieg mit der Third Fleet von Kul Tiras sank.",h="Im Hafen von Menethil sucht Glorin Stahlbraue nach Fracht, die mit einem elfischen Zerstörer verloren ging.",kw={"flying osprey","glorin stahlbraue","barren","kul tiras","lichtgeschmiedetes eisen","hafen von menethil","murloc","third fleet","durchnässte truhe","sumpfland"},ang={["class:Paladin"]="Als Paladin wisst Ihr, dass Waffen aus Lichtgeschmiedetem Eisen eng mit dem Heiligen Licht verbunden sind. Selbst die Bergung eines einzigen verlorenen Barrens hat geistliche Bedeutung.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr die versunkenen Schiffe vor dem Hafen von Menethil als feierliche Mahnmale des Zweiten Krieges betrachten. Seeleute aus Kul Tiras und Lordaeron fielen dort dem Drachenfeuer zum Opfer.",["profession:Blacksmithing"]="Als Schmied wisst Ihr, warum Schmiede Lichtgeschmiedetes Eisen verehren. Sie schätzen seinen mächtigen Segen und seine unübertroffene Festigkeit."},sec={{t="Eine heilige Fracht",b="Die Flying Osprey segelte von Lordaeron aus an der Seite der Third Fleet von Kul Tiras. Der elfische Zerstörer trug eine kostbare Ladung Lichtgeschmiedetes Eisen und fuhr zum Schutz im Geleit der Flotte. Dann stießen die versklavten roten Drachen des Drachenmalklans vom Himmel herab. Sie setzten die Schiffe in Brand und ließen Seeleute und geweihtes Metall unter den Wellen versinken."},{t="Von den Gezeiten geplündert",b="Südlich des Hafens von Menethil liegt die zerschmetterte Flying Osprey unter Wasser. Ihre Truhe wurde aufgebrochen und mit Klauen durchwühlt. Küstenmurlocs plünderten das Wrack und verstreuten die Barren. Von dem kostbaren Erz, das Glorin Stahlbraue sucht, ist nur wenig übrig."}},faq={{q="Was ist die Flying Osprey?",a="Die Flying Osprey war ein elfischer Zerstörer, der während des Zweiten Krieges von Lordaeron aus segelte. Sie trug seltenes Lichtgeschmiedetes Eisen und fuhr zum Schutz an der Seite der Third Fleet von Kul Tiras. Die versklavten roten Drachen des Drachenmalklans setzten die Flotte in Brand und versenkten sie.",al={"flying osprey geschichte","elfischer zerstörer sumpfland","welches schiff hatte das eisen"}},{q="Wer ist Glorin Stahlbraue?",a="Glorin Stahlbraue ist ein Zwerg, der im Hafen von Menethil im Sumpfland stationiert ist. Er sucht nach historischen Fundstücken und wertvollen Materialien aus versunkenen Schiffen entlang der Küste, besonders nach legendären Metallen wie Lichtgeschmiedetem Eisen.",al={"glorin stahlbraue","zwerg in menethil","wer vergibt lichtgeschmiedetes eisen"}},{q="Was ist Lichtgeschmiedetes Eisen?",a="Lichtgeschmiedetes Eisen ist ein seltenes, geheiligtes Metall, aus dem geweihte Waffen und Rüstungen geschmiedet werden. Schmiede und Streiter des Heiligen Lichts schätzen seine Reinheit und geistige Widerstandskraft.",al={"lichtgeschmiedetes metall","was ist lichtgeschmiedetes eisen","lichtgeschmiedete barren"}},{q="Warum wurden die Schiffe im Sumpfland versenkt?",a="Während des Zweiten Krieges nutzte der Drachenmalklan der Horde die Demon Soul, um die Red Dragonflight zu versklaven. Drachenreiter griffen die Third Fleet von Kul Tiras vor der Küste des Sumpflands an, verbrannten die Schiffe und schickten sie auf den Meeresgrund.",al={"wer versenkte die third fleet","warum schiffswracks im sumpfland","rote drachen sumpfland flotte"}},{q="Warum ist die Truhe fast leer?",a="Küstenmurlocs rissen die durchnässte Truhe an Bord der Flying Osprey mit ihren Klauen auf und plünderten ihre Fracht. Die meisten Barren sind verschwunden und liegen entlang des sumpfigen Ufers verstreut.",al={"wo sind die barren","warum klauenspuren an der truhe","wer stahl das lichtgeschmiedete eisen"}},{q="Wo liegt das Wrack der Flying Osprey?",a="Die Flying Osprey liegt zwischen den Untiefen unmittelbar südlich des Hafens von Menethil, an der Westküste des Sumpflands. Ihre Wrackteile liegen im flachen Wasser nahe den dortigen Murlocsiedlungen verstreut.",al={"flying osprey fundort","wo ist die truhe","sumpfland schiffswrack fundort"}}},fx={["915ea990"]={q="Warum will Glorin Stahlbraue Lightforge Iron?",a="Glorin Stahlbraue ist ein Priester, der versucht, das seltene Metall zu bergen, um eine Waffe gegen Morbent Fel vorzubereiten. Die versunkene Ladung der Flying Osprey bietet eine seltene Gelegenheit, Lightforge Iron zu bergen, ein kostbares elfisches Handelsgut, das seit dem Zweiten Krieg verloren ist. Indem er Euch schickt, es zu bergen, hofft er, genug verarbeitbares Metall zu sammeln, um Waffen zu schmieden, die seiner dauerhaften Legende würdig sind.",al={"warum will glorin eisen","glorin stahlbraues lightforge iron motiv","warum lightforge iron finden"}}},fp="15,195,14.335.0,22.251.1,26.226.0,24.209.0,24.167.0,40.227.0,30.162.0,51.192.0"}
P.entries["quest:322"] = {n="Gesegnete Waffe",s="In Sturmwind schickt Glorin Stahlbraue Lightforge Iron für eine Waffe gegen Morbent Fel auf den Weg. Ihr bringt das seltene Metall aus dem Wrack der Flying Osprey im Sumpfland zu Waffenmeister Grimand Elmore, der es für den Kampf schmieden kann.",h="In Sturmwind schickt Glorin Stahlbraue Lightforge Iron für eine Waffe gegen Morbent Fel auf den Weg.",kw={"gesegnete waffe","der zwergendistrikt","glorin stahlbraue","grimand elmore","lightforge iron","loch modan","morbent fel","sturmwind"},ang={["class:Paladin"]="Als Paladin bringt Ihr geweihtes Eisen, um daraus eine Waffe gegen einen Nekromanten im Dämmerwald zu schmieden. Das entspricht der Berufung der Silver Hand: dunkler Zauberei mit heiliger Wachsamkeit zu begegnen.",["faction:Alliance"]="Als Mitglied der Allianz bringt Ihr Hilfe von einem Königreich ins andere, von einem zwergischen Priester im Hafen von Menethil zum Zwergendistrikt von Sturmwind. Die Menschen im Dämmerwald sind schwer bedrängt.",["profession:Blacksmithing"]="Lightforge Iron ist selten und schwer zu bearbeiten. Dem erfahrenen Zwergenschmied Grimand Elmore dabei zuzusehen, zeigt, welches Können nötig ist, um heilige Waffen zu schmieden."},sec={{t="Ein seltenes Metall kehrt zurück",b="Glorin Stahlbraue verpackt das geborgene Lightforge Iron für Sturmwind. Das Metall ist selten und mächtig gegen verderbte und unheilige Wesen und braucht einen Schmied, der es zu bearbeiten weiß. Die Lieferung stammt aus dem Wrack der Flying Osprey vor der Küste des Sumpflands. Glorin kennt in den südlichen Königreichen nur einen Handwerker, der dieser Aufgabe gewachsen ist: Waffenmeister Grimand Elmore."},{t="Die Schmiede im Zwergendistrikt",b="Im Zwergendistrikt von Sturmwind unterhält Grimand Elmore einen der besten Ambosse der Stadt. Jahre seien vergangen, seit er zuletzt Lightforge Iron gehämmert habe, sagt er, als Ihr ihm die geborgene Lieferung bringt. Der erfahrene Handwerker begrüßt die Gelegenheit, einen Schlag gegen den Nekromanten Morbent Fel zu führen. Er erklärt sich bereit, seinen Hammer ans Werk zu setzen."}},faq={{q="Welchen Zweck hat diese Lieferung?",a="Die Kiste enthält Lightforge Iron, das aus dem Wrack der Flying Osprey im Sumpfland geborgen wurde. Glorin Stahlbraue schickt es zu Grimand Elmore, der das geweihte Metall zu einer Waffe gegen Morbent Fel schmieden kann.",al={"warum blöcke nach sturmwind bringen","gesegnete waffe zweck","wofür ist die kiste mit lichtschmiedeblöcken"}},{q="Wer ist Grimand Elmore?",a="Grimand Elmore ist ein angesehener zwergischer Waffenschmied im Zwergendistrikt von Sturmwind. Nur wenige Handwerker haben die nötige Ausbildung, um besondere Metalle wie Lightforge Iron zu schmieden.",al={"grimand elmore hintergrund","wer ist der schmied im zwergendistrikt"}},{q="Warum ist Lightforge Iron gegen Morbent Fel so wichtig?",a="Lightforge Iron besitzt Macht gegen verderbte und unheilige Wesen. Grimand Elmore kann das geweihte Metall zu einer Waffe gegen den Nekromanten Morbent Fel schmieden.",al={"warum lightforge iron","wie schadet lightforge iron morbent fel"}},{q="Wohin schickt Euch Glorin Stahlbraue?",a="Glorin Stahlbraue schickt Euch vom Hafen von Menethil im Sumpfland zu Grimand Elmores Schmiede im Zwergendistrikt von Sturmwind.",al={"wohin für gesegnete waffe","wo ist grimand elmore"}},{q="Hat Grimand Elmore schon einmal mit Lightforge Iron gearbeitet?",a="Ja. Grimand sagt, es sei Jahre her, seit er zuletzt mit Lightforge Iron gearbeitet habe. Er begrüßt die Gelegenheit, das sagenumwobene Metall erneut zu formen.",al={"hat grimand schon lightforge iron geschmiedet","elmores schmiedeerfahrung"}},{q="Was muss geschehen, bevor die Waffe fertiggestellt werden kann?",a="Grimand erklärt sich bereit, das geborgene Lightforge Iron zu Morbents Bann zu schmieden. Sobald er fertig ist, bringt Ihr die Waffe zu Sven Yorgen im Dämmerwald.",al={"was kommt nach gesegnete waffe","wird die waffe sofort geschmiedet"}}},fx={["983cc211"]={q="Warum will Glorin Stahlbraue diese Lieferung zustellen lassen?",a="Glorin weiß, dass gewöhnlicher Stahl die dunklen Schutzzauber um Morbent Fel im Dämmerwald nicht durchdringen kann. Nachdem er das Lightforge Iron erhalten hat, das Ihr aus dem Wrack der Flying Osprey im Sumpfland geborgen habt, erkennt er Euren Feldzug gegen den Nekromanten an und verweist Euch an einen geschickten Schmied, der eine Waffe schmieden kann, die ihm wirklich zu schaden vermag.",al={"glorin stahlbraue beweggrund","warum hilft glorin","warum barren zu grimand schicken"}}},fp="11,236,20.355.0,28.315.0,37.202.0,22.167.0,56.155.0,37.127.0,54.135.0,51.143.0"}
P.entries["quest:3221"] = {n="Sprecht mit Renferrel",s="Im Grabmal erwartet Apotheker Renferrel Eure Erkenntnisse über die verdorbenen Wolfsherzen. Hochexekutor Hadrec hat Euch geschickt, um mit dem Forscher der Königlichen Apothekervereinigung zu sprechen.",h="Im Grabmal erwartet Apotheker Renferrel Eure Erkenntnisse über die verdorbenen Wolfsherzen.",kw={"hadrec","renferrel","königliche apothekervereinigung","das grabmal","silberwald","wolfsherzen"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr erfahren, wie Verderbnis die Bestien des Silberwalds verändert.",["race:Undead"]="Als Untoter könnt Ihr hören, wie die Forscher der Königlichen Apothekervereinigung mit der militärischen Führung im Grabmal zusammenarbeiten. Sie untersuchen ungewöhnliche Kreaturen im Silberwald."},sec={{t="Vorladung der Vereinigung",b="Nachdem Ihr den Todespirschern im gesamten Silberwald geholfen habt, übergibt Euch Hochexekutor Hadrec eine dringende Nachricht von Apotheker Renferrel. Renferrel hat verfärbte Wolfsherzen untersucht, die von der örtlichen Tierwelt gesammelt wurden, und braucht Euch sofort."},{t="Alchemistische Kuriositäten",b="Apotheker Renferrel arbeitet für die Königliche Apothekervereinigung in einem Labor in der Krypta des Grabmals. Er untersucht, wie dunkle Magie und Krankheiten die Bestien des Silberwalds verändern. Seine alchemistische Forschung stützt sich auf militärische Berichte von der Front."}},faq={{q="Wo befindet sich Apotheker Renferrel?",a="Apotheker Renferrel arbeitet neben seiner Alchemieausrüstung in der Krypta des Grabmals im Herzen des Silberwalds. Er ist nur einen kurzen Fußweg von Hochexekutor Hadrec entfernt.",al={"renferrel standort","wo ist renferrel","renferrel finden"}},{q="Warum möchte Apotheker Renferrel mit mir sprechen?",a="Renferrel hat verfärbte Herzen von Wölfen aus dem Silberwald untersucht und seltsame Anzeichen ihrer Verderbnis entdeckt. Er muss weiterforschen und nach Unterstadt berichten.",al={"warum braucht renferrel mich","renferrel wolfsherzen"}},{q="Wer schickt Euch zu Renferrel?",a="Hochexekutor Hadrec, der Kommandant der Verlassenen im Grabmal, übergibt Euch Renferrels Vorladung, nachdem Ihr von Eurer Hilfe für die Todespirscher zurückgekehrt seid.",al={"wer vergibt sprecht mit renferrel","questgeber"}},{q="Was folgt auf dieses Gespräch?",a="Euer Gespräch mit Renferrel führt zu weiteren Aufgaben, die die alchemistische Forschung des Grabmals mit hochrangigen Persönlichkeiten in Unterstadt verbinden, darunter Apothekerin Zinge.",al={"nächste quest nach sprecht mit renferrel","renferrel folgequest"}}},fx={["1f8d2902"]={q="Warum schickt Euch Hochexekutor Hadrec zu Renferrel?",a="Hochexekutor Hadrec übermittelt lediglich eine formelle Vorladung im Namen der Königlichen Apothekervereinigung. Während Ihr an der Front im Silberwald für The Todespirscher Aufklärung betrieben habt, bat Apotheker Renferrel um Eure Rückkehr, um die Wolfsherzen zu besprechen, die Ihr zuvor für seine alchemistischen Forschungen gesammelt habt. Hadrec stellt sicher, dass wichtige Geschäfte zwischen dem Militärposten und der Vereinigung reibungslos weiterlaufen.",al={"hadrecs motiv","warum will hadrec, dass ich mit renferrel spreche","warum mich zu apotheker renferrel schicken"}}},fp="20,179,24.231.0,22.241.0,38.155.0,52.168.0,27.141.0,31.164.0"}
P.entries["quest:323"] = {n="Bewährungsprobe",s="Im Dämmerwald prüft Sven Yorgen Eure Stärke, bevor Ihr Morbent Fel gegenübersteht. Der Einsiedler will Rache für seine Familie und braucht den Beweis, dass Ihr die Untoten auf dem Friedhof von Rabenflucht besiegen könnt.",h="Im Dämmerwald prüft Sven Yorgen Eure Stärke, bevor Ihr Morbent Fel gegenübersteht.",kw={"dark riders","dämmerwald","das verlassene gut","morbent fel","bewährungsprobe","friedhof von rabenflucht","skeletal healer","skeletal raider","skeletal warder","sven yorgen"},ang={["class:Paladin"]="Als Paladin könnt Ihr die Gerechtigkeit des Lichts zum Friedhof von Rabenflucht bringen und die rastlosen Toten von Morbent Fels Magie reinigen.",["class:Priest"]="Als Priester könnt Ihr die Schändung der Gräber von Rabenflucht mit spiritueller Reinigung beantworten und der Verderbnis von Leben und Tod durch die Warders und Healers ein Ende setzen.",["faction:Alliance"]="Im westlichen Dämmerwald fehlen regelmäßige Patrouillen aus Sturmwind, und Anarchie hat sich ausgebreitet. Als Streiter der Allianz könnt Ihr Grenzlandbewohnern wie Sven helfen, die Untoten zurückzudrängen."},sec={{t="Die Prüfung eines verbitterten Einsiedlers",b="Sven Yorgen trauert in einem abgelegenen Lager nördlich der heulenden Wälder. Der Mord an seiner Familie lässt Zorn in ihm brennen. Er hat erfahren, dass die Dark Riders, die sein Gehöft zerstörten, mit dem Nekromanten Morbent Fel verbündet waren. Sven will Rache, doch er wird keinen unerprobten Verbündeten in Fels Fänge schicken. Zuerst bittet er Euch, Eure Kampfkunst gegen die Skelette auf dem Friedhof von Rabenflucht zu beweisen."},{t="Die Gruften von Rabenflucht",b="Der Friedhof von Rabenflucht liegt südlich des Verlassenen Guts, und von Fels Magie gebundene Leichen füllen sein Gelände und sein Mausoleum. Skeletal Raiders patrouillieren mit Schwertern zwischen den Grabsteinen. Darunter kümmern sich Skeletal Warders und Healers um die Kammern. Um Svens Vertrauen zu gewinnen, müsst Ihr tief in die Nekropole vordringen und diese Vorhut beseitigen. Mor'Ladim, ein rachsüchtiges Phantom, durchstreift die Friedhofspfade."},{t="Der Weg zum Nekromanten",b="Dass Ihr die Katakomben von Rabenflucht überlebt, überzeugt Sven davon, dass Ihr mehr als Mut besitzt. Fels niedere Diener sind nur das erste Hindernis. Morbent Fels dunkle Verzauberungen schützen ihn vor gewöhnlichen Waffen. Deshalb sucht Sven vor der letzten Konfrontation nach größerer Weisheit und uralten Relikten."}},faq={{q="Warum lässt Sven mich gegen Skelette kämpfen, bevor ich Morbent Fel gegenübertrete?",a="Sven weiß, dass Morbent Fel ein tödlicher Nekromant ist, der mit den geheimnisvollen Dark Riders verbündet ist. Er schickt Euch erst gegen Fel, wenn Ihr bewiesen habt, dass Ihr Euch durch eine Vorhut von Untoten kämpfen könnt.",al={"warum bewährungsprobe","warum sven skelette töten lässt","svens prüfung"}},{q="Wo sind die Skeletal Warders und Healers zu finden?",a="Skeletal Raiders patrouillieren auf dem offenen Friedhofsgelände südlich des Verlassenen Guts. Skeletal Healers und Warders sammeln sich im und um das große Mausoleum sowie in den Gruftgängen westlich der Friedhofsmitte.",al={"wo sind warders","wo sind skeletal healers","skeletal warders finden"}},{q="Wer ist Mor'Ladim und warum sollte ich mich hier vor ihm in Acht nehmen?",a="Mor'Ladim ist ein mächtiger untoter Ritter, der auf dem Friedhof von Rabenflucht umherstreift. Er ist weitaus stärker als die gewöhnlichen Skelette und kann Unachtsame schnell niederstrecken.",al={"morladim gefahr","wer ist mor'ladim","wandernde elite rabenflucht"}},{q="Wie ist Morbent Fel mit den Dark Riders verbunden?",a="Sven hat erfahren, dass Morbent Fel sich mit den verhüllten Dark Riders verbündete, die seine Frau und seine Kinder abschlachteten. Die Reiter verschwanden in den Schatten, während Fel im Dämmerwald bleibt und seine Nekromantie fortsetzt.",al={"morbent fel dark riders verbindung","warum dark riders und fel","mörder von svens familie"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Nachdem Ihr Eure Stärke bewiesen habt, erklärt Sven, dass rohe Gewalt allein Morbent Fel nicht töten kann. Er schickt Euch zu Bischof Heller in der Kathedrale des Lichts in Sturmwind, um zu erfahren, wie sich die Schutzzauber des Nekromanten aufheben lassen.",al={"nächste quest nach bewährungsprobe","was tun nach den skeletten"}},{q="Wo liegt Sven Yorgens Lager?",a="Sven unterhält ein verborgenes Lager in den Hügeln am äußersten nordwestlichen Rand des Dämmerwalds. Es liegt nördlich von Rabenflucht und westlich der Straße nach Westfall.",al={"wo ist sven","svens lager standort"}}},fx={["865aa68b"]={q="Wer sind die skelettierten Diener auf Raven Hill?",a="Die skelettierten Plünderer, Heiler und Wächter, die den Friedhof von Rabenflucht heimsuchen, sind die wiederbelebten Toten, die der Nekromant Morbent Fel erweckt hat. Aus den geschändeten Gräbern im Dämmerwald stammend, bilden diese ruhelosen Toten nun ein unheiliges Bollwerk, das die Friedhofskrypten bewacht und den dunklen Willen ihres Meisters ausführt.",al={"skelettierte plünderer raven hill","wer sind die skelette raven hill","morbent fels diener"}},fbdf818d={q="Warum braucht Sven Yorgen Euch, um gegen Morbent Fels Diener zu kämpfen?",a="Sven Yorgen ist ein isolierter Einsiedler, der allein in der verwunschenen Wildnis des Dämmerwalds überlebt. Von Trauer zerrissen und angetrieben vom Hass auf die Dunklen Reiter, die seine Familie abgeschlachtet haben, fehlen ihm die Kraft und die Ressourcen, um Morbent Fels untote Armee allein anzugreifen. Er wendet sich an fähige Abenteurer, die bereit sind, den Friedhof von Rabenflucht zu trotzen, um seine Rache zu üben.",al={"warum braucht sven hilfe","warum kämpft sven nicht","warum mich fragen sven"}}},fp="18,179,22.397.0,21.370.0,27.276.1,64.179.0,49.187.0,57.152.0,48.200.0,41.216.1,36.136.0"}
P.entries["quest:324"] = {n="Die verlorenen Blöcke",s="Glorin Stahlbraue sucht Lightforge Iron aus einem Schiffswrack vor dem Sumpfland. Die Kiste enthält nur einen Barren, und Murlocs der Bluegill haben den Rest an sich genommen.",h="Glorin Stahlbraue sucht Lightforge Iron aus einem Schiffswrack vor dem Sumpfland.",kw={"bluegill","flying osprey","glorin stahlbraue","barren","lightforge iron","murloc","vollgesogene kiste","sumpfland"},ang={["class:Paladin"]="Als Paladin helft Ihr durch die Bergung von Lightforge Iron, heiliges Metall für Waffen zu bewahren, die für das Licht streiten.",["profession:Blacksmithing"]="Als Schmied wisst Ihr, dass feines Lightforge Iron in einem Murlocnest an der Küste verschwendet ist, wenn es an einem Amboss verarbeitet werden könnte.",["race:Dwarf"]="Als Zwerg ehrt Ihr durch die Bergung verlorenen meisterhaften Erzes für einen Zwergenpriester wie Glorin Stahlbraue das Handwerk Eures Volkes und seine Tradition, Verlorenes zurückzuholen."},sec={{t="Ein geplündertes Schiffswrack",b="Die Flying Osprey liegt zerschellt vor der Küste des Sumpflands. Glorin Stahlbraue, ein Zwergenpriester, hat Euch ausgesandt, um ihr Lightforge Iron zu bergen. Doch die vollgesogene Kiste im Frachtraum enthält nur einen Barren. Murlocs der Bluegill nahe dem Wrack haben den Rest der Ladung geplündert."},{t="Das heilige Metall zurückholen",b="Lightforge Iron ist ein seltenes Metall, das sich für heiliges Schmiedehandwerk eignet. Glorin Stahlbraue braucht es für eine Waffe, also dürfen die Barren nicht in den Lagern der Bluegill bleiben. Die Räuber der Bluegill jagen im seichten Wasser nahe dem zerborstenen Rumpf. Holt die verstreuten Barren für Glorin zurück."}},faq={{q="Welches Schiff beförderte das Lightforge Iron?",a="Die Flying Osprey beförderte das Lightforge Iron, bevor sie vor der Küste des Sumpflands sank. Ihre zerbrochenen Planken liegen teilweise unter Wasser im seichten Küstengewässer.",al={"welches schiff","flying osprey","name des schiffswracks"}},{q="Warum waren die Barren nicht in der Kiste?",a="Nur ein Barren war in der vollgesogenen Kiste verblieben. Murlocs der Bluegill haben den Rest der Ladung aus dem Wrack geplündert.",al={"wo sind die barren","warum haben murlocs eisen","kiste leer"}},{q="Wer ist Glorin Stahlbraue?",a="Glorin Stahlbraue ist ein Zwergenpriester der Kirche des Heiligen Lichts in der Tiefenwassertaverne im Hafen von Menethil. Als Kollege von Bischof Heller sucht er Lightforge Iron für eine Waffe gegen den Nekromanten Morbent Fel.",al={"glorin","wer ist glorin stahlbraue","questgeber"}},{q="Was ist das Besondere an Lightforge Iron?",a="Lightforge Iron ist ein seltenes Metall, das sich für heilige Verzauberungen und heiliges Schmiedehandwerk eignet. Handwerker fertigen daraus Waffen, die auf das Heilige Licht abgestimmt sind.",al={"geschichte von lightforge iron","was ist lightforge iron","warum ist das eisen wichtig"}},{q="Welche Murlocs haben das Eisen genommen?",a="Murlocräuber der Bluegill haben die fehlenden Barren an sich genommen. Sie durchstreifen das seichte Wasser und die Strände rund um das Wrack der Flying Osprey.",al={"wer hat die barren gestohlen","welcher stamm","räuber der bluegill"}},{q="Was folgt nach der Rückgabe der Barren?",a="Nachdem Glorin Stahlbraue alle Barren erhalten hat, verpackt er das geweihte Metall in einer Kiste und schickt Euch zum Waffenschmied Grimand Elmore in Sturmwind. Dort wird das Metall zu Blessed Arm geschmiedet.",al={"nächste quest","was macht glorin","blessed arm quest"}}},fp="15,147,21.264.0,27.242.0,38.141.0,37.117.0,24.219.0,38.140.0,28.114.0,43.191.1"}
P.entries["quest:325"] = {n="Bewaffnet und bereit",s="Ihr bringt Morbents Bann zu Sven Yorgen zurück, eine Waffe, die Morbent Fels unheilige Schutzzauber brechen soll.",h="Ihr bringt Morbents Bann zu Sven Yorgen zurück, eine Waffe, die Morbent Fels unheilige Schutzzauber brechen...",kw={"bewaffnet und bereit","dämmerwald","grimand elmore","morbent fel","morbents bann","rabenflucht","sturmwind","sven yorgen"},ang={["class:Paladin"]="Als Paladin wisst Ihr, dass heilige Macht in Verbindung mit zwergischem Stahl Schutzzauber brechen kann, die Untote schützen.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie die Handwerker aus Sturmwind den Überlebenden im Dämmerwald das Können vermitteln, das sie gegen die um sich greifende Verderbnis brauchen.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr, wie Grimand Elmore feine Schmiedekunst mit heiligen Riten verband, um eine Waffe gegen übernatürliche Bedrohungen zu schaffen."},sec={{t="Eine geschmiedete Waffe",b="Gewöhnlicher Stahl kann Morbent Fels Herrschaft über den Friedhof von Rabenflucht nicht brechen. Klingen zersplittern oder prallen an den dunklen Schutzzaubern um ihn ab. Grimand Elmore formte das Metall im Zwergendistrikt von Sturmwind, und heilige Macht weihte es. Nun kann Morbents Bann Fels Verbindung zum Unleben durchtrennen."},{t="Rückkehr zum Hermit",b="In seinem einsamen Lager nahe der Westgrenze des Dämmerwalds musste Sven Yorgen mitansehen, wie die Dunkelheit seine Familie, seinen Hof und seine Gefährten zugrunde richtete. Ihr bringt ihm Morbents Bann, und er erkennt die göttliche Handwerkskunst und das Feuer in Euren Augen. Mit der Waffe in seinen Händen kann Sven gegen den Meister von Rabenflucht vorgehen."}},faq={{q="Was ist Morbents Bann?",a="Morbents Bann ist eine Waffe, die geschmiedet und geweiht wurde, um die magischen Schutzzauber um Morbent Fel in Rabenflucht zu brechen.",al={"morbents bann","was ist die waffe","morbents bann schwert"}},{q="Wer hat die Waffe geschmiedet?",a="Grimand Elmore, ein Schmied im Zwergendistrikt von Sturmwind, fertigte die Waffe aus geweihtem Lightforge Iron.",al={"wer hat morbents bann geschmiedet","grimand elmores rolle"}},{q="Wo liefere ich Morbents Bann ab?",a="Ihr bringt Morbents Bann zu Sven Yorgen in seinem Lager im westlichen Dämmerwald, nahe der Grenze zu Westfall.",al={"wo ist sven","sven yorgens standort","abgabeort"}},{q="Warum kann Sven Yorgen Morbent Fel nicht selbst bekämpfen?",a="Die dunklen Mächte in den Wäldern vertrieben Sven Yorgen aus seinem Heim und kosteten ihn seine Familie und seine Gefährten. Einsam und gejagt ist er auf die Streiter der Allianz angewiesen, um sie zu rächen.",al={"warum kämpft sven nicht","sven yorgens vorgeschichte"}},{q="Was geschieht nach dem Abschluss von Bewaffnet und bereit?",a="Nachdem Sven die gesegnete Waffe erhalten hat, schickt er Euch zum Friedhof von Rabenflucht, um Morbent Fel entgegenzutreten und ihn niederzustrecken.",al={"what comes next","nächste quest nach bewaffnet und bereit"}},{q="Was ist der schnellste Rückweg zu Svens Lager?",a="Reist von der Späherkuppe in Westfall nach Osten über den Fluss, um Svens Lager zu erreichen. Dieser Weg ist kürzer und sicherer als der Weg nach Westen durch die Gefahren von Dunkelhain.",al={"schnellster weg zu sven","wie schnell zu sven gelangen"}}},fx={["4a0f4d98"]={q="Warum will Grimand Elmore, dass Morbents Bann an Sven geliefert wird?",a="Grimand Elmore ist ein Meisterschmied aus Sturmwind, der die Aufgabe übernommen hat, eine Waffe zu schmieden, die dunkle Magie durchdringen kann. Nachdem er Morbents Bann fertiggestellt hat, schickt er Euch eifrig zurück in den Dämmerwald, damit die Waffe ihrem beabsichtigten Zweck zugeführt werden kann. Er wünscht Euch den Sieg gegen den Nekromanten und freut sich darauf, Eure Geschichte vom Triumph zu hören.",al={"grimand elmores motiv","warum hilft grimand","warum sven grimand helfen"}},["2182c2f5"]={q="Warum benötigt Grimand Elmore Euch, um die Waffe zu überbringen, anstatt sie selbst auszuliefern?",a="Grimand ist ein Schmied, der im Zwergendistrikt in Sturmwind arbeitet, kein umherziehender Abenteurer oder Kurier. Ihr habt ihm die Materialien und die düsteren Neuigkeiten aus dem Dämmerwald gebracht, und da Ihr die Person seid, die sich gemeinsam mit Sven Yorgen dem Unhold stellen wird, ist es an Euch, die geweihte Waffe zurück zum Schlachtfeld zu bringen.",al={"warum ich armed and ready","warum geht grimand nicht in den dämmerwald","warum spieler zu sven schicken"}}},fp="15,99,15.277.0,20.301.1,23.110.0,23.121.0,34.100.0,48.170.0,46.116.1,47.153.0"}
P.entries["quest:3261"] = {n="Jorn Himmelsdeuter",s="Im südlichen Brachland führt Jorn Himmelsdeuter Jäger der Horde zu tieferem Wissen über die Wildnis. Nach Euren Jagden für Sergra Dunkeldorn schickt sie Euch nach Süden nach Camp Taurajo, wo ein alter Fährtenleser Euch mehr lehrt.",h="Im südlichen Brachland führt Jorn Himmelsdeuter Jäger der Horde zu tieferem Wissen über die Wildnis.",kw={"camp taurajo","pfad des jägers","jorn himmelsdeuter","sensenklauen","sergra darkthorn","brachland","das wegekreuz"},ang={["class:Hunter"]="Als Jäger begegnet Ihr Jorn Himmelsdeuter, der Eure Fähigkeit prüft, die legendären Spitzenprädatoren der mittleren und südlichen Ebenen zu überlisten und zu bezwingen.",["faction:Horde"]="Als Mitglied der Horde reist Ihr vom Wegekreuz nach Camp Taurajo, tiefer in das umkämpfte südliche Brachland.",["race:Tauren"]="Als Tauren, der nach Süden in Richtung Camp Taurajo zurückkehrt, verbindet Ihr die Jagdtraditionen Eures Stammes mit der spirituellen Obhut über die Wildnis des Brachlands."},sec={{t="Die Verantwortung weitergeben",b="Ihr habt Sonnenschuppen- und Sensenklauenraptoren in der nördlichen Savanne gejagt und Euch Sergra Darkthorns Respekt am Wegekreuz verdient. Sie weiß, dass ein Jäger mehr braucht als Geschick mit Waffen; die großen Bestien des Landes verlangen Verständnis. Ihre Unterweisung hier ist beendet, also schickt sie Euch nach Süden."},{t="Der Weg nach Taurajo",b="Die Goldstraße führt nach Süden über rauere Ebenen nach Camp Taurajo, einer Taurensiedlung nahe der südlichen Wildnis. Dort wartet Jorn Himmelsdeuter, ein alter Fährtenleser, der Jäger unterweist, die im Brachland scheue und legendäre Beute suchen."}},faq={{q="Wer schickt mich zu Jorn Himmelsdeuter?",a="Nachdem Ihr die einheimischen Sensenklauen gejagt habt, schickt Euch Sergra Dunkeldorn, die Raptorenjägerin am Wegekreuz, nach Süden. Eure Jagden beweisen Euer Geschick beim Fährtenlesen und Jagen.",al={"wer vergibt jorn himmelsdeuter","wer startet jorn himmelsdeuter","sergra darkthorn quest"}},{q="Wo befindet sich Jorn Himmelsdeuter?",a="Jorn Himmelsdeuter befindet sich in Camp Taurajo, weit im Süden entlang der Hauptstraße durch das Brachland.",al={"wo ist jorn himmelsdeuter","jorn himmelsdeuter standort","jorn himmelsdeuter finden"}},{q="Was geschieht, nachdem ich Jorn Himmelsdeuter erreicht habe?",a="Wenn Ihr Euch bei ihm meldet, heißt Jorn Euch auf dem Pfad des Jägers willkommen und schickt Euch, scheue Bestien im südlichen Brachland aufzuspüren und zu jagen. Die erste ist der legendäre Raptor Ishamuhale.",al={"was lehrt jorn","jorn himmelsdeuter folgequest","nächste quest nach jorn himmelsdeuter"}},{q="Muss ich der Klasse Jäger angehören, um diese Quest zu erledigen?",a="Nein. Jeder Abenteurer der Horde, der Sergra Darkthorns Raptorenjagden abschließt, kann lernen, die Fährten der Ebenen zu lesen, ganz gleich, welcher Klasse er angehört.",al={"nur für jäger","klassenvoraussetzung jorn himmelsdeuter"}},{q="Warum unterweist Sergra Euch nicht länger selbst?",a="Sergra Dunkeldorn arbeitet zwischen den Raptorennestern im Norden nahe dem Wegekreuz. Sobald Ihr diese Jagden meistert, schickt sie Euch nach Süden zu Jorn Himmelsdeuter, der Euch auf ausgedehnteren Jagdzügen nach dem Wild des Südens anleitet.",al={"warum schickt sergra einen fort","sergras unterweisung beendet"}},{q="Was ist Camp Taurajo?",a="Camp Taurajo ist ein Taurenlager im südlichen Brachland. Es ist Jagdposten, Handelszentrum und kulturelle Raststätte für Reisende zwischen den nördlichen Ebenen und Mulgore oder Tausend Nadeln.",al={"über camp taurajo","was ist taurajo"}}},fp="12,214,18.283.0,19.235.0,29.161.0,30.83.0,41.186.0,48.127.0,42.191.0,21.205.0"}
P.entries["quest:328"] = {n="Der versteckte Schlüssel",s="Buchmacher Herods Unterlagen führen Euch zu einer Geldkassette im Stockpile. Ihr Inhalt könnte enthüllen, wie die Tarnung von Gefreitem Thorsen aufflog.",h="Buchmacher Herods Unterlagen führen Euch zu einer Geldkassette im Stockpile.",kw={"buchmacher herod","messingschlüssel","kurzens truppenlager","gefreiter thorsen","stockpile","schlingendorntal","geldkassette"},sec={{t="Ein Geheimnis im Buchrücken",b="Buchmacher Herods Hauptbücher nennen Gefreiten Thorsen nie beim Namen. Doch im Buchrücken eines Buches verbirgt sich ein kleiner Messingschlüssel. Schnipsel zwischen den Unterlagen weisen auf eine Geldkassette im Stockpile hin, dem Höhlenkomplex hinter Kurzens Truppenlager. Darin könnte der Grund liegen, weshalb Thorsens Tarnung aufflog."},{t="Tief in den Stockpile",b="Tief im Höhlensystem hinter Kurzens Truppenlager wartet die Geldkassette zwischen gestapelten Kisten. Die robuste Truhe ist schwer und mit Bronze beschlagen."}},faq={{q="Woher stammt dieser Messingschlüssel?",a="Der kleine Messingschlüssel war im Buchrücken eines von Buchmacher Herods Hauptbüchern versteckt, das zwischen seinen Unterlagen lag.",al={"wo war der schlüssel","wie kam ich an den schlüssel","herkunft des kleinen messingschlüssels"}},{q="Wo befindet sich Buchmacher Herods Geldkassette?",a="Buchmacher Herods Geldkassette steht im Stockpile, dem Höhlenkomplex an der Rückseite von Kurzens Truppenlager.",al={"fundort der geldkassette","wo ist die geldkassette","wo ist die truhe"}},{q="Warum nach Herods Geldkassette suchen?",a="Buchmacher Herods lose Unterlagen erklären nicht, wie die Anwesenheit von Gefreitem Thorsen aufgedeckt wurde. Sie weisen auf eine sichere Geldkassette hin, die die Antwort enthalten könnte.",al={"warum die geldkassette finden","was ist in der kiste","zweck der geldkassette"}},{q="Was geschah vor diesem Schritt?",a="Dies folgt auf die Durchsuchung von Buchmacher Herods Hauptbüchern im Zuge der Ermittlungen gegen ihn.",al={"vorherige quest","welche quest kommt zuerst"}}},fp="14,126,24.264.0,23.138.0,35.111.0,42.98.0,33.149.0,27.94.0"}
P.entries["quest:3281"] = {n="Gestohlenes Silber",s="Am Wegekreuz schickt Gazrog Euch los, um Silber zurückzuholen, das Raptoren aus der Soldlieferung für die Wachen gestohlen haben. Ihre Schläue hat Euch südlich von Ratschet in die Raptorgründe geführt. Die Garnison braucht ihren Sold zurück.",h="Am Wegekreuz schickt Gazrog Euch los, um Silber zurückzuholen, das Raptoren aus der Soldlieferung für die...",kw={"brachland","das wegekreuz","gazrog","soldzahlung","raptorgründe","raptor thieves","ratschet","gestohlenes silber"},ang={["class:Hunter"]="Als Jäger seht Ihr, wie die Raptoren des Brachlands in komplexen sozialen Gruppen nisten und von künstlicher, glänzender Fracht angelockt werden.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass das Wegekreuz seine Wachen bezahlt und versorgt, um die Grenze in Kalimdor zu halten."},sec={{t="Ein bestialischer Raub",b="Gazrog muss die Wachen des Wegekreuzes bezahlen, doch Raptoren haben ihren Sold geraubt. Er schickt Euch los, um die gestohlenen Münzen zurückzuholen, nicht bloß die Bestien zu bestrafen. Zunächst wollte er Rache für den Überfall auf die Soldlieferung. Doch das Rudel zu töten würde das Geld nicht zurückbringen. Die Horde muss herausfinden, wie die Raptoren schwere Münzkisten fortschaffen konnten und wohin sie diese brachten."},{t="Die Raptorgründe",b="Späher fanden ein Raptorennest zwischen zwei zerklüfteten Gipfeln, südlich von Ratschet und nordwestlich der Feste Northwatch. Die Kreaturen zerrten die unversehrte Schatulle in ihr Revier und bewachen sie neben ihren Eiern und frisch erlegter Beute. Gazrogs Geschichten über die Schläue und das Horten der Raptoren scheinen nun wahr zu sein. Gewöhnliche Bestien verstecken nur selten metallene Wertsachen."}},faq={{q="Warum haben die Raptoren überhaupt Silber gestohlen?",a="Die Raptoren des Brachlands zeigen erstaunliche Schläue und ein merkwürdiges Sammelverhalten. Sie zerrten die unversehrte Geldkassette zu ihren gemeinschaftlichen Nestern in den Raptorgründen, vielleicht angelockt vom Glanz, dem gegerbten Leder der Truhe oder einem Sammeltrieb.",al={"warum wollen raptoren silber","warum silber raptoren","raptoren münzen motiv"}},{q="Wer ist Gazrog?",a="Gazrog ist ein im Hauptbunker des Wegekreuzes stationierter Orc-Offizier. Er kümmert sich um Sicherheit und Logistik, darunter Bedrohungen durch die örtliche Tierwelt, Einfälle von Zentauren und Störungen der Soldversorgung.",al={"gazrog","wer vergibt gestohlenes silber","wegekreuz questgeber gazrog"}},{q="Wo liegen die Raptorgründe?",a="Die Raptorgründe liegen im östlichen Brachland, südlich von Ratschet und nordwestlich der Feste Northwatch. Ihre Nester füllen einen zerklüfteten Durchgang zwischen zwei Bergen.",al={"raptorgründe lage","wo gestohlenes silber finden","gestohlenes silber truhe fundort"}},{q="Was geschieht, wenn das Silber nicht zurückgeholt wird?",a="Das gestohlene Silber umfasst einen Monatssold für die Wachen des Wegekreuzes. Ohne das Silber droht den Verteidigern des Außenpostens Dienst ohne Bezahlung, und die Moral könnte in der von Stachelebern, Zentauren und Allianzräubern bedrängten Festung leiden.",al={"warum ist gestohlenes silber wichtig","wegekreuz wachen sold"}},{q="Gehört dies zu einer längeren Questreihe?",a="Bevor Ihr nach dem Versteck sucht, müsst Ihr Raptor Thieves für Gazrog abschließen. Dabei dezimiert Ihr die Raptoren, die den ersten Transport angegriffen haben, und spürt das Versteck auf.",al={"gestohlenes silber voraussetzungen","raptor thieves folgequest"}},{q="Ist die Allianz an dem Diebstahl beteiligt?",a="Nein. Die Feste Northwatch liegt südöstlich der Raptorgründe, doch einheimische Raptoren haben den Diebstahl begangen. Ihre Dieberei und ihr Horten überraschten selbst erfahrene Befehlshaber der Horde.",al={"hat die feste northwatch silber gestohlen","allianz raptoren brachland"}}},fx={f31163b7={q="Warum möchte Gazrog, dass das Gestohlenes Silber zurückgeholt wird?",a="Das Gestohlenes Silber macht den Lohn für den kommenden Monat für die Wachen in Das Wegekreuz aus. Als ein lebenswichtiger Außenposten der Horde, der Bedrohungen durch Zentauren, Stacheleber und die nahegelegene Allianz ausgesetzt ist, hängt Das Wegekreuz stark von diesen Wachen ab. Ohne ihren Sold könnten die Moral und die Verteidigung der Siedlung zusammenbrechen, weshalb Gazrog entschlossen ist, jede Münze zurückzuholen.",al={"gazrog motiv gestohlenes silber","warum braucht gazrog das silber","warum gestohlenes silber zurückholen"}},b903b9d8={q="Was ist das Gestohlenes Silber?",a="Das Silber ist der Sold, der für die Wachen in Das Wegekreuz bestimmt war, und der in einer verschlossenen Truhe aufbewahrt wurde, bis schlaue Raptoren ihn entwendeten. Tief in den Raptorgründe südlich von Ratschet versteckt, repräsentiert diese Kiste voller Münzen den Lebensunterhalt der Beschützer des Außenpostens und die Sicherheit der wichtigsten Kreuzung im Brachland.",al={"was ist gestohlenes silber","gestohlenes silber questgegenstand","wem gehört das silber"}},["03250c10"]={q="Gegen wen werdet Ihr in den Raptorgründe ausgesandt?",a="Ihr werdet in die Raptorgründe entsandt, einen rauen Nistplatz südlich von Ratschet und nordwestlich von Die Feste Northwatch. Das Gebiet wimmelt von wilden Sonnenfeuerraptoren, überraschend schlauen Bestien, die dafür bekannt sind, glänzende Wertsachen in ihren Nestern zu horten und die gestohlene Truhe aggressiv gegen jeden Eindringling zu verteidigen.",al={"wer bewacht das gestohlene silber","raptorgründe feinde","was lebt in den raptorgründe"}}},fp="13,198,15.370.0,18.323.0,48.236.0,14.185.0,37.150.0,44.214.0,37.176.0,38.168.0"}
P.entries["quest:329"] = {n="Der entlarvte Spion",s="Ihr habt eine schlammige Notiz in Buchmacher Herods Geldkassette gefunden. Ihr Bericht über den Tagesablauf des Gefreiten Thorsen deutet auf einen Informanten unter den Rebellen im nördlichen Schlingendorntal hin und ist für Lieutenant Doren bestimmt.",h="Ihr habt eine schlammige Notiz in Buchmacher Herods Geldkassette gefunden.",kw={"doren","herod","schlammige notiz","rebellenlager","spion","schlingendorntal","geldkassette","thorsen","verräter"},ang={["faction:Alliance"]="Als Rebell der Allianz helft Ihr, Euren gefährdeten Brückenkopf im Schlingendorntal vor örtlichen Bedrohungen zu schützen, indem Ihr einen Informanten aufspürt."},sec={{t="Ein Verräter in den Reihen",b="Im Rebellenlager zeichnet die Notiz die Patrouillen, Begleiter und täglichen Aktivitäten des Gefreiten Thorsen nach. Jemand hat ihn genau beobachtet. Die Unterschrift lautet nur -M, und die Einzelheiten deuten auf einen Verräter hin, der Seite an Seite mit ihm im Lager lebt."},{t="Bericht an Doren",b="Ihr bringt das feuchte Pergament zurück ins Rebellenlager und legt es Lieutenant Doren vor. Die mit einem Initial versehenene Notiz liefert ihm Beweise, um innerhalb des eigenen Lagers der Rebellen nach einem Infiltrator zu suchen."}},faq={{q="Was steht auf der schlammigen Notiz?",a="Die schlammige Notiz hält den Tagesablauf des Gefreiten Thorsen fest, darunter seine Patrouillenwege, seine Gesprächspartner und wie er seine Stunden im Lager verbringt. Sie trägt nur die Unterschrift -M.",al={"text der schlammigen notiz","was steht in der notiz","einzelheiten der spionagenotiz"}},{q="Woher stammt diese Notiz?",a="Ihr findet die Notiz unter dem Inhalt von Buchmacher Herods Geldkassette, nachdem Ihr sie aufgeschlossen habt.",al={"wo ist die schlammige notiz zu finden","der entlarvte spion start","wie beginnt der entlarvte spion"}},{q="Wer erhält die Notiz?",a="Lieutenant Doren erhält die Notiz im Rebellenlager im nördlichen Schlingendorntal.",al={"bei wem die schlammige notiz abgeben","wohin mit der notiz","bei lieutenant doren abgeben"}},{q="Wie geht es weiter, nachdem Ihr über die Notiz berichtet habt?",a="Nachdem Ihr über die Notiz berichtet habt, setzt Lieutenant Doren seine Ermittlungen mit Patrol Schedules fort.",al={"welche quest folgt","nächster schritt nach der entlarvte spion","nach der entlarvte spion"}}},fp="17,214,22.220.0,18.188.1,34.172.0,30.84.0,22.84.0,41.94.0"}
P.entries["quest:33"] = {n="Wölfe an der Grenze",s="Im Nordhaintal bittet Eagan Peltskinner Euch, Wölfe zu jagen und ihm ihr Fleisch zu bringen. Er wartet vor der Abtei von Nordhain, wo der tägliche Bedarf bestehen bleibt, während sich die Wachen auf Defias-Banditen konzentrieren.",h="Im Nordhaintal bittet Eagan Peltskinner Euch, Wölfe zu jagen und ihm ihr Fleisch zu bringen.",kw={"abtei","eagan","elwynn","fleisch","nordhain","peltskinner","holzfällerwolf","wölfe"},ang={["profession:Cooking"]="Als Koch lernt Ihr durch Eagans Verlangen nach Wolfssteaks eine Wahrheit des Grenzlandes kennen: Was Ihr jagt, lässt sich oft kochen und essen.",["race:Human"]="Als menschlicher Rekrut in Nordhain ist dies eine Eurer ersten praktischen Möglichkeiten, zur Sicherung der nahen Grenzen von Sturmwind beizutragen."},sec={{t="Eine pragmatische Bitte",b="Eagan Peltskinner wartet an den Mauern der Abtei von Nordhain und ist wütend auf die örtlichen Holzfällerwölfe. Marschall McBride und die Wachen von Sturmwind haben nur wenig Kraft, um die Abtei gegen Defias-Banditen zu verteidigen. Handwerker haben weiterhin ihren täglichen Bedarf, also bittet Eagan Euch, die Zahl der Wölfe zu verringern und ihr zähes Fleisch für seine Küche mitzubringen."},{t="Die Wildnis von Nordhain",b="Wölfe streifen näher an der Abtei von Nordhain umher, während die Patrouillen schwächer werden. Das Königreich Sturmwind hat zu wenige Truppen und es fehlt an Führung. Junge Wölfe und Holzfällerwölfe durchstreifen die Wege und Obstgärten der Abtei. Die Jagd auf sie füllt Eagans Vorratskammer und macht die nahen Pfade für Novizen, Arbeiter und neu eingetroffene Verteidiger sicherer."}},faq={{q="Wer ist Eagan Peltskinner?",a="Eagan Peltskinner ist ein Jäger und Händler nahe dem Eingang zur Abtei von Nordhain. Er mag die örtlichen Holzfällerwölfe nicht und kocht und isst ihr Fleisch gern.",al={"wer ist eagan","peltskinner","eagan peltskinner"}},{q="Warum will Eagan Wolfsfleisch?",a="Eagan isst gern Wolfssteaks. Er bietet Rekruten, die ihm frisches Fleisch bringen, nützliche Ausrüstung für den Anfang und ein paar Münzen.",al={"warum wolfsfleisch","eagan hungrig","was macht eagan mit fleisch"}},{q="Wo sind die Wölfe zu finden?",a="Holzfällerwölfe und junge Wölfe durchstreifen die Felder, Hügel und Flussufer des Nordhaintals, besonders südlich und östlich der Abtei.",al={"wo sind die wölfe","fundorte der wölfe","wölfe finden"}},{q="Warum sind Wölfe in Nordhain ein Problem?",a="Weniger Patrouillen und Defias-Banditen haben dazu geführt, dass Nordhains Straßen und Höfe wilden Tieren schutzlos ausgeliefert sind. Reisen ohne Geleitschutz sind für Geistliche und Arbeiter gefährlich.",al={"warum greifen wölfe an","wolfsproblem in nordhain"}},{q="Muss ich mit jemandem sprechen, bevor ich diese Quest annehme?",a="Nein. Deputy Willem schickt Neuankömmlinge mitunter durch einen ersten Botengang zu Eagan, doch Eagan bietet die Jagd jedem direkt an, der ihn vor der Abtei anspricht.",al={"questvoraussetzungen","voraussetzungen","wer vergibt diese quest"}},{q="Wird Zähes Wolfsfleisch für Kochrezepte verwendet?",a="Eagan will das Fleisch selbst zubereiten. Angehende Köche lernen oft, dass im Wald von Elwynn gesammeltes Wolfsfleisch eine Grundzutat für das Kochen im Freien ist.",al={"zähes wolfsfleisch kochen","können spieler wolfsfleisch kochen"}}},fx={["12d6ae41"]={q="Wofür ist das Zähes Wolfsfleisch gedacht?",a="Eagan Peltskinner beabsichtigt, daraus Wolfssteaks für sich selbst zu kochen. Obwohl er die Bestien, die das Tal durchstreifen, verabscheut, hat er einen herzhaften Appetit auf ihr Fleisch entwickelt und tauscht gerne nützliche Ausrüstung gegen alles, was seinen Tisch deckt.",al={"wofür ist das zähes wolfsfleisch","warum zähes wolfsfleisch","verwendung von zähem wolfsfleisch"}},acd05579={q="Warum durchstreifen Wölfe das Nordhain?",a="Junge Wölfe und Holzfällerwölfe durchstreifen auf natürliche Weise die bewaldeten Ränder und offenen Wiesen im Nordhaintal. Da die örtlichen Wachen von Sturmwind jedoch mit der wachsenden Bedrohung durch The Defias Brotherhood beschäftigt sind, streifen die Raubtiere ungehindert näher an das Gelände der Abtei heran.",al={"warum sind hier wölfe","holzfällerwölfe im nordhain","wölfe im nordhain"}}},fp="24,189,19.323.0,19.318.0,25.158.0,30.109.0,29.128.0,39.151.0,53.160.0,44.149.0"}
P.entries["quest:330"] = {n="Patrouillen-Pläne",s="Im Rebellenlager sucht Lieutenant Doren den Verfasser einer Notiz, die nur mit einer Initiale unterzeichnet ist. Der Verfasser schreibt, er habe in der vergangenen Woche Patrouillenrouten mit Gefreitem Thorsen geteilt, und die Dienstaufzeichnungen könnten seinen Namen verraten.",h="Im Rebellenlager sucht Lieutenant Doren den Verfasser einer Notiz, die nur mit einer Initiale unterzeichnet...",kw={"corporal sethman","kurzen","lieutenant doren","patrouillen-pläne","gefreiter thorsen","rebellenlager","schlingendorntal"},sec={{t="Eine Spur in den Dienstplänen",b="Eine im Rebellenlager gefundene Notiz trägt die Initiale M. Ihr Verfasser schreibt, er sei in der vergangenen Woche regelmäßig mit Gefreitem Thorsen dieselben Routen gegangen. Das könnte auf denjenigen hinweisen, der die Kurzen-Truppen unterstützt. Lieutenant Doren schickt Euch zu Corporal Sethman, der die Dienstbücher führt. Seine Aufzeichnungen könnten zeigen, wer an Thorsens Seite patrouillierte."},{t="Was die Aufzeichnungen zeigen",b="Gefreiter Merle teilte während der gesamten vergangenen Woche Thorsens Dienstzeiten und Routen. Diese Übereinstimmung entlarvt Merle als den Informanten, der Kurzens Männer mit Informationen versorgt. Merle flieht aus dem Lager in Richtung der nördlichen Grenze des Dämmerwalds."}},faq={{q="Warum schickt Lieutenant Doren Euch zu Corporal Sethman?",a="Corporal Sethman führt die Dienstbücher und Dienstpläne des Rebellenlagers. Laut der Notiz ging ihr Verfasser regelmäßig dieselben Routen wie Gefreiter Thorsen, daher könnten Sethmans Aufzeichnungen zeigen, wer an seiner Seite diente.",al={"warum mit sethman sprechen","corporal sethmans rolle","sethman patrouillen-pläne"}},{q="Welcher Hinweis findet sich in der sichergestellten Notiz?",a="Die sichergestellte Notiz trägt den Buchstaben M. Ihr Verfasser schreibt, er sei in der vergangenen Woche dieselben Dienstwege wie Gefreiter Thorsen gegangen.",al={"hinweis in der notiz","buchstabe als hinweis","wer hat die notiz unterzeichnet"}},{q="Wo findet diese Untersuchung statt?",a="Die Untersuchung findet im Rebellenlager im nördlichen Schlingendorntal statt, zwischen Lieutenant Doren und Corporal Sethman.",al={"wo findet patrouillen-pläne statt","patrouillen-pläne ort"}},{q="Welches Ereignis ging dieser Untersuchung voraus?",a="Vor dieser Untersuchung brachtet Ihr Lieutenant Doren in The Spy Revealed! die schlammige Notiz, die unter Buchmacher Herods Wertsachen gefunden wurde. Sie trug nur eine Initiale.",al={"vorherige quest","was führte zu patrouillen-pläne"}}},fp="16,228,21.317.0,21.225.1,55.186.0,41.131.0,35.124.0,33.147.0"}
P.entries["quest:3301"] = {n="Mura Runentotem",s="Im Grabmal im Silberwald hofft Mura Runentotem, dass ein Panzer aus dem Brachland den Verlassenen helfen kann.",h="Im Grabmal im Silberwald hofft Mura Runentotem, dass ein Panzer aus dem Brachland den Verlassenen helfen kann.",kw={"brachland","mura runentotem","oasen","das grabmal","silberwald","schnappkieferpanzer","tonga runentotem"},ang={["class:Druid"]="Als Druide untersucht Ihr ungewöhnliche Formen wiederkehrenden Lebens in der Natur, selbst solche, die aus seltsamen Mutationen entstehen, um verwüsteten Landstrichen das Gleichgewicht zurückzugeben.",["faction:Horde"]="Als Mitglied der Horde seht Ihr ihren wachsenden Zusammenhalt in der Zusammenarbeit zwischen Kalimdors Verteidigern und den Verlassenen in Lordaeron.",["race:Tauren"]="Als Tauren seht Ihr, wie die Fürsorge des Runentotem-Clans für die Natur über das Meer bis zu den verdorrten Hainen des Silberwalds reicht.",["race:Undead"]="Als Untoter seht Ihr vielleicht, wie Verfall und Fäulnis den Wald um das Grabmal vereinnahmen. Taurendruiden wie Mura Runentotem bemühen sich, ihn zu erneuern."},sec={{t="Eine Brücke über Meere",b="Rund um die Barrens Oases untersucht Tonga Runentotem durch Magie veränderte Wildtiere. Die veränderten Schnappkiefer fallen ihm auf. Trotz ihrer Verderbnis pulsieren ihre Panzer vor widerstandsfähiger Energie. Deshalb bittet er Euch, einen davon über das große Meer zu seiner Clangefährtin Mura Runentotem zu bringen, die in den Östlichen Königreichen stationiert ist."},{t="Hilfe für die Verlassenen",b="Im Grabmal, einem Außenposten der Verlassenen im Silberwald, hilft Mura Runentotem ihren Verbündeten. Sie unternahm die beschwerliche Reise, um ihnen zu helfen, ihren kranken, von Fäulnis befallenen Wald zu reinigen und zu erneuern. Der Panzer birgt ein inneres Leuchten und einen beständigen Lebensfunken. Mura hofft, dass er offenbaren könnte, wie sich die Lebenskraft des nördlichen Kontinents wiederherstellen lässt."}},faq={{q="Wer ist Mura Runentotem?",a="Mura Runentotem ist eine Taurendruidin und Tonga Runentotems Clangefährtin. Sie überquerte das Meer und ließ sich im Grabmal nieder, um den Verlassenen zu helfen, Wege zur Heilung ihres sterbenden Waldes zu finden.",al={"mura","wer ist mura","runentotem silberwald"}},{q="Wo befindet sich Mura Runentotem?",a="Mura Runentotem befindet sich im Grabmal, einer Ortschaft der Verlassenen an der Straße im mittleren Silberwald in den Östlichen Königreichen.",al={"mura standort","wo ist mura","mura runentotem finden"}},{q="Warum will Tonga einen Schnappkieferpanzer in den Silberwald schicken lassen?",a="Die Panzer veränderter Schnappkiefer nahe den Barrens Oases zeigen unnatürliche Lebenskraft und ein inneres Leuchten. Tonga hofft, dass ihre widerstandsfähige Lebenskraft Mura helfen könnte, einen Weg zur Heilung der von Fäulnis befallenen, sterbenden Natur des Silberwalds zu finden.",al={"warum panzer schicken","schnappkieferpanzer zweck","warum braucht mura den panzer"}},{q="Warum versuchen die Tauren, die Ländereien der Verlassenen zu heilen?",a="Die Tauren sehen es als heilige Pflicht an, die Natur zu pflegen und zu heilen. Angesichts des verfallenden, von Fäulnis befallenen Silberwalds hofft Mura, dass die Heiltraditionen der Erde den neuen Verbündeten der Horde helfen und das Gleichgewicht des Bodens wiederherstellen können.",al={"tauren helfen untoten","warum silberwald heilen","druiden im silberwald"}},{q="Wie verbindet diese Quest das Brachland mit dem Silberwald?",a="Die Reise des Panzers führt Euch von den Ebenen Kalimdors in die Wälder der Östlichen Königreiche und verbindet frühe Gebiete der Horde.",al={"quest vom brachland zum silberwald","kontinentübergreifende quest"}},{q="Was geschieht, nachdem Ihr Mura den Panzer gegeben habt?",a="Mura ist vom anhaltenden inneren Leuchten des Panzers fasziniert. Sie beschließt, ihn eingehend zu untersuchen, während sie nach einem Heilmittel für die von Fäulnis befallenen Wälder des Silberwalds sucht.",al={"mura fortsetzung","what comes next"}}},fx={["10ada1ab"]={q="Warum bittet Tonga Runentotem Euch, den Panzer auszuliefern?",a="Tonga Runentotem ist in Das Wegekreuz stationiert und damit beschäftigt, die bizarren Mutationen zu untersuchen, die die Oasen im Brachland befallen. Eine Reise über das Meer zum fernen Kontinent Lordaeron würde ihn von seinen dringenden Pflichten in Kalimdor abhalten, was einen abenteuerlustigen Boten zur idealen Wahl macht, um seine Probe zu Mura zu bringen.",al={"warum mich schicken","warum kann tonga es nicht ausliefern","warum ich mura runetotem"}}},fp="14,107,20.296.0,19.320.0,22.172.0,32.121.0,55.204.0,49.218.0,54.132.0,41.147.0"}
P.entries["quest:331"] = {n="Meldung bei Doren",s="Corporal Sethman schickt Euch zu Lieutenant Doren, um über die Patrouillenerkenntnisse zu berichten. Der Befehlshaber der Rebellen nimmt sie im Rebellenlager im nördlichen Schlingendorntal entgegen.",h="Corporal Sethman schickt Euch zu Lieutenant Doren, um über die Patrouillenerkenntnisse zu berichten.",kw={"doren","kurzen","patrol schedules","sethman","schlingendorntal"},sec={{t="Die Erkenntnisse überbringen",b="Corporal Sethman möchte, dass Ihr Lieutenant Doren persönlich über die Patrouilleninformationen berichtet. Bringt zurück, was Ihr erfahren habt."},{t="Ein Verräter entlarvt",b="Lieutenant Doren erfährt, dass Merle das Lager verraten hat, als Ihr die Patrouilleninformationen vorlegt. Er trauert um einen Soldaten, den er einst für tapfer und loyal hielt. Doch er ist sehr erleichtert, dass der Verräter gefunden wurde, bevor Colonel Kurzen daraus einen Vorteil ziehen kann."}},faq={{q="Wer schickt Euch zu Lieutenant Doren?",a="Corporal Sethman schickt Euch zu Lieutenant Doren, nachdem er die Patrouillenpläne mit Euch durchgesehen hat.",al={"wer startet meldung bei doren","wer schickt mich zu doren","meldung bei doren questgeber"}},{q="Was ging diesem Bericht voraus?",a="Dies folgt auf Patrol Schedules, wo Corporal Sethman die Patrouillenpläne mit Euch durchsieht.",al={"vorherige quest","was kommt vor meldung bei doren","patrol schedules"}},{q="Wo wird dieser Bericht abgeliefert?",a="Ihr überbringt Lieutenant Doren den Bericht im Rebellenlager im nördlichen Schlingendorntal.",al={"wo ist lieutenant doren","doren standort","wohin muss ich"}}},fp="15,159,27.124.0,18.241.1,34.93.0,29.92.0,31.88.0"}
P.entries["quest:332"] = {n="Weinladen-Werbung",s="Renato Gallina lockt Passanten in den Weinladen seiner Familie in Sturmwind. Er bietet einen Gutschein für eine kostenlose Flasche Jahrgangswein aus ihrem Laden am Kanal an, ein kleines Zeichen des Handels in der wiederaufgebauten Hauptstadt.",h="Renato Gallina lockt Passanten in den Weinladen seiner Familie in Sturmwind.",kw={"canals","gallina winery","pinot noir","renato gallina","suzetta gallina","der handelsdistrikt","weinladen-werbung","weingutschein"},ang={["faction:Alliance"]="Selbst in unruhigen Zeiten, während Könige vermisst werden und Krieg herrscht, bleibt Sturmwinds Handelsdistrikt ein lebhafter Markt für heimische Luxuswaren und Importgüter.",["profession:Cooking"]="Der Pinot Noir der Gallinas passt zu herzhaften Gerichten, die in Tavernen überall in den Östlichen Königreichen zubereitet werden.",["race:Human"]="Als Mensch, der sich in Sturmwind ein neues Leben aufbaut, könnt Ihr familiengeführte Weinkellereien an den Kanälen als tröstliches Zeichen für das Wiederaufleben der Stadt empfinden."},sec={{t="Eine Kostprobe von Canals",b="Im Handelsdistrikt von Sturmwind erfüllt reger Handel die gepflasterten Straßen. Renato Gallina ist dort unterwegs und wirbt für Gallina Winery, den kleinen Laden, den er mit seiner Schwester Suzetta betreibt. Er verteilt Werbezettel an durstige Reisende und Einheimische. Jeder bietet eine kostenlose Verkostung an."},{t="Der Jahrgang des Pinot Noir",b="Die Familie Gallina bietet eine Flasche ihres berühmten Pinot Noir an. Folgt dem Gutschein zum Eingang der Weinkellerei nahe den Kanälen, wo Suzetta Gallina Euch die Flasche überreicht. Die Familie hofft, dass eine Kostprobe ihres Vorzeigeweins neue Kunden zur Rückkehr bewegt."}},faq={{q="Wo befindet sich Gallina Winery?",a="Gallina Winery liegt im Handelsdistrikt von Sturmwind, an den Kanälen nahe der Route von Renato Gallina.",al={"wo ist gallina winery","suzetta gallina standort","wo wird weinladen-werbung abgegeben"}},{q="Wer sind Renato und Suzetta Gallina?",a="Renato und Suzetta Gallina sind Geschwister, die einen Weinladen in Sturmwind betreiben. Renato wirbt mit Werbezetteln dafür, während Suzetta den Laden führt und den Wein ausschenkt.",al={"wer sind die gallinas","renato gallina","suzetta gallina hintergrundgeschichte"}},{q="Welchen Wein erhält man für den Gutschein?",a="Für den Gutschein erhält man eine Flasche des berühmten Pinot Noir der Gallinas, ihres charakteristischen Rotweins.",al={"pinot noir wein","welchen wein erhält man","pinot noir sturmwind"}},{q="Warum verteilt Renato Gutscheine für kostenlosen Wein?",a="Renato verteilt Gutscheine für kostenlosen Wein, um Kunden in den Laden am Kanal zu locken und sie zur Rückkehr zu bewegen.",al={"warum kostenloser wein","zweck des weinladen-gutscheins"}},{q="Birgt dieser Botengang Gefahren oder Kämpfe?",a="Nein. Ihr nehmt einen Werbegutschein von Renato entgegen und geht ein kurzes Stück durch die sicheren Straßen des Handelsdistrikts zu Suzetta am Ladeneingang.",al={"ist weinladen-werbung gefährlich","weinquest kämpfe"}},{q="Verkauft Gallina Winery auch andere Waren?",a="Suzetta führt gewöhnliche Weine und andere alkoholische Getränke für Reisende, Wachen in ihrer Pause und Lieferanten der örtlichen Tavernen.",al={"was verkauft suzetta sonst noch","gallina winery getränke"}}},fp="16,202,21.251.0,22.241.0,36.99.0,35.155.0,31.87.0,43.107.0,46.148.0,41.116.0"}
P.entries["quest:333"] = {n="Harlan braucht Nachschub",s="In Sturmwind kann Händler Harlan Bagley robuste Kleidung und Rüstung kaum auf Lager halten. Die Nachfrage steigt rasant, also schickt er eine dringende Stoffbestellung an Rema Schneider in der Schneiderei an den Kanälen, ahnungslos, welche Konflikte sich jenseits der Stadtmauern anbahnen.",h="In Sturmwind kann Händler Harlan Bagley robuste Kleidung und Rüstung kaum auf Lager halten.",kw={"bagley","kanal","stoff","harlan","rema","nachschub","schneider","sturmwind"},ang={["faction:Alliance"]="Sturmwinds Käufer zeigen die wachsende Unruhe im Kernland der Allianz, während König Varian Wrynn abwesend ist.",["profession:Tailoring"]="Sturmwinds Werkstätten an den Kanälen beliefern größere Läden und zeigen so den Alltag des städtischen Textilhandels.",["race:Human"]="Sturmwinds Handwerker misstrauen ihren Herrschern und vermuten, dass der Adel das einfache Volk über drohende Gefahren im Unklaren lässt."},sec={{t="Ansturm auf robuste Kleidung",b="Überall in Sturmwind leeren sich Harlan Bagleys Regale rasch. Bürger und umherziehende Abenteurer kaufen verstärkte Tuniken, Reisekleidung und kampftaugliche Rüstung. Harlan fragt sich, ob sie sich auf eine raue Jahreszeit oder den Winter vorbereiten. Durch den Ansturm fehlt es seinem Laden an verarbeitetem Stoff."},{t="Fragen an den Canals",b="Harlan schickt einen Boten über die Wasserwege der Stadt zu Rema Schneider, einer Schneiderin in der Schneiderei an den Kanälen. Sie freut sich über seine Aufträge, doch die plötzliche Nachfrage nach schützender Kleidung beunruhigt sie. Gerüchte über Spannungen verbreiten sich im Königreich. Rema fragt sich, ob das Haus der Adligen dem einfachen Volk Gespräche über einen offenen Krieg verheimlicht."}},faq={{q="Wer ist Harlan Bagley?",a="Harlan Bagley ist Tuchhändler und Ladenbesitzer in Sturmwind. Örtliche Schneider liefern die Strickwaren und reisetaugliche Kleidung, die er verkauft.",al={"harlan bagley","wer ist harlan","bagley sturmwind"}},{q="Wer ist Rema Schneider?",a="Rema Schneider ist gelernte Schneiderin und Näherin in der Schneiderei an den Kanälen in Sturmwind. Mit ihrem Mann Corbett beliefert sie Händler in der ganzen Stadt mit frisch genähten Stoffwaren und Kleidungsstücken.",al={"rema schneider","schneiderin rema","schneiderei an den kanälen"}},{q="Warum geht Harlan die Kleidung aus?",a="Bürger und Reisende kaufen ungewöhnlich große Mengen an Rüstung und strapazierfähiger Kleidung. Harlan scherzt, sie schienen einen bitterkalten Winter zu erwarten, doch wachsende Unruhen und Gefahren jenseits der Grenzen des Königreichs sind der wahre Grund.",al={"warum geht der stoff aus","warum rüstung kaufen","harlans geschäft floriert"}},{q="Warum verdächtigt Rema Schneider die Adligen?",a="Rema findet es seltsam, dass sich einfache Leute plötzlich auf den Kampf vorbereiten, ohne dass ein Konflikt offiziell verkündet wurde. Das Haus der Adligen lenkt die königlichen Angelegenheiten, während König Varian Wrynn abwesend ist. Sie fürchtet, dass die Adligen einen bevorstehenden Krieg vor der Öffentlichkeit verbergen.",al={"rema adlige","sturmwinds adlige verheimlichen krieg","warum adlige verdächtigen"}},{q="Wo liegt die Schneiderei an den Kanälen?",a="Die Schneiderei an den Kanälen liegt an den Wasserwegen, die durch Sturmwind führen, zwischen den großen Stadtvierteln, damit Händlerlieferungen sie bequem erreichen.",al={"schneiderei an den kanälen standort","wo ist rema schneider","wo ist die schneiderei an den kanälen"}},{q="Was geschieht, nachdem die Stoffanforderung überbracht wurde?",a="Nachdem Rema die Bestellung erhalten hat, bittet sie ihren Mann Corbett Schneider, eine weitere Ladung Strickwaren durch die Stadt zu Harlan in der Lionheart Armory zu bringen. Auf dem Rückweg zum Laden hält Corbett bei Trias' Cheese für einen Imbiss an.",al={"corbett schneider spaziergang","was macht corbett","remas ehemann"}}},fp="23,240,23.276.0,23.337.0,21.135.0,22.205.0,38.221.0,43.269.0,47.156.0,50.232.0"}
P.entries["quest:334"] = {n="Eine Lieferung für Thurman",s="Rema Schneider braucht Hilfe, um Schere und Nadeln ihres Sohnes zu Larson Clothiers im Magierviertel von Sturmwind zu bringen. Thurman macht dort eine Lehre und könnte ohne sie in Rückstand geraten.",h="Rema Schneider braucht Hilfe, um Schere und Nadeln ihres Sohnes zu Larson Clothiers im Magierviertel von...",kw={"lehrling","kleiderhändler","larson","das magierviertel","rema","schneider","nähzeug","sturmwind","thurman"},ang={["faction:Alliance"]="Sturmwinds einfache Bürger und Handwerker sorgen dafür, dass die Hauptstadt Kleidung und Nahrung hat und der Alltag weitergeht, eine Besorgung nach der anderen.",["profession:Tailoring"]="Jeder große Schneider fängt ganz unten an, zieht Nähte und hält Stecknadeln bereit. Bei Larson Clothiers möchte selbst ein Lehrling manchmal seinen Pflichten entfliehen."},sec={{t="Die Besorgung einer Mutter",b="Thurman hat in aller Eile das Haus verlassen, ohne sein Werkzeug mitzunehmen. Rema fürchtet, er könnte in seiner Lehre in Rückstand geraten, und bittet Euch, Schere und Nadeln über Sturmwinds Kanäle zu seiner Werkstatt zu bringen."},{t="Ein widerwilliger Lehrling",b="Larson Clothiers liegt in der Nähe des Magierturms. Als Thurman sein Werkzeug erhält, gibt er zu, es absichtlich zurückgelassen zu haben, um seinen täglichen Pflichten zu entgehen und sich zu vergnügen. Remas Eingreifen beendet seinen freien Nachmittag, und er kehrt an seine Näharbeit zurück."}},faq={{q="Wer vergibt die Quest Eine Lieferung für Thurman?",a="Rema Schneider bittet Euch, Schere und Nadeln ihres Sohnes zu seinem Arbeitsplatz im Magierviertel zu bringen.",al={"wer vergibt quest","rema schneider quest","questgeber"}},{q="Wo ist Thurman Schneider zu finden?",a="Thurman Schneider arbeitet bei Larson Clothiers im Magierviertel von Sturmwind, nahe dem Weg zum Magierturm.",al={"thurman aufenthaltsort","wo ist thurman","thurman finden"}},{q="Hat Thurman sein Werkzeug wirklich versehentlich vergessen?",a="Rema glaubt, Thurman habe in aller Eile das Haus ohne sein Werkzeug verlassen, und bittet Euch, es ihm zu bringen.",al={"hat thurman es vergessen","warum ließ thurman sein werkzeug zurück","thurman faulenzt"}},{q="In welchem Geschäft macht Thurman seine Lehre?",a="Thurman macht eine Schneiderlehre bei Larson Clothiers, einem Bekleidungsgeschäft im Magierviertel von Sturmwind, das von der Familie Larson geführt wird.",al={"wo arbeitet thurman","larson clothiers","für wen arbeitet thurman"}},{q="Warum bittet Rema Schneider einen Abenteurer um Hilfe?",a="Rema fürchtet, Thurman könnte ohne sein Werkzeug in seiner Lehre in Rückstand geraten. Da sie ihre eigenen Verpflichtungen nicht verlassen kann, bittet sie Reisende auf dem Weg zum Magierviertel um Hilfe.",al={"warum den spieler fragen","rema helfen"}},{q="Was geschieht, nachdem Ihr das Nähzeug abgeliefert habt?",a="Thurman nimmt sein Werkzeug entgegen und kehrt bei Larson Clothiers an seine Näharbeit zurück.",al={"questbelohnung","nach eine lieferung für thurman","thurmans reaktion"}}},fx={["3c7bea70"]={q="Warum möchte Rema Schneider, dass dies erledigt wird?",a="Rema sorgt sich um die Zukunft ihres Sohnes Thurman. Er hat einen Platz als Lehrling bei Larson Clothiers im Magierviertel bekommen, eilte jedoch los, ohne seine Scheren und Nadeln mitzunehmen. Ohne sein Werkzeug kann Thurman seine Aufgaben nicht erfüllen oder sein Handwerk erlernen, was seinen Stand bei seinen Arbeitgebern gefährdet. Da sie glaubt, es sei ein bloßes Versehen gewesen, möchte sie, dass sein Set sofort geliefert wird, damit seine Ausbildung nicht gefährdet wird.",al={"warum muss das nähzeug an rema geliefert werden","beweggründe rema schneider","warum thurman das werkzeug bringen"}}},fp="19,179,17.193.0,22.236.1,41.101.0,37.111.0,50.86.1,38.123.0,51.173.0,46.69.1"}
P.entries["quest:335"] = {n="Ein nobles Bräu",s="Unter Sturmwind schmiedet Zardeth der Schwarzen Klaue Pläne gegen den Adel der Stadt. Lord Wishocks Forderung nach einer Untersuchung bedroht den verborgenen Hexenmeisterzirkel.",h="Unter Sturmwind schmiedet Zardeth der Schwarzen Klaue Pläne gegen den Adel der Stadt.",kw={"dunkelhain","house of nobles","bisam","slaughtered lamb","der steinwerkdamm","tilloa","wishock","zardeth"},ang={["class:Warlock"]="Als Hexenmeister sind die Krypten unter dem Slaughtered Lamb Euer sicherer Zufluchtsort in Sturmwind. Wenn Ihr Zardeth helft, schützt Ihr Eure Brüder und Schwestern der dunklen Künste vor der Entdeckung durch den rechtschaffenen Adel des Königreichs.",["faction:Alliance"]="Während König Varian Wrynn weiterhin vermisst wird, erreichen die politischen Ränkespiele im House of Nobles ihren Höhepunkt. Dadurch werden Skandale innerhalb der Stadt besonders gefährlich für ihre Stabilität.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass Tilloaträne und Bisamwurzel seltene Pflanzen sind, die nur in Gegenden wachsen, die von düsterer Geschichte oder reißenden Strömen unberührten Wassers geprägt sind."},sec={{t="Bedrohung durch den Adel",b="Hexenmeister versammeln sich unter dem Mage Quarter im Slaughtered Lamb und halten ihren Zirkel verborgen. Lord Wishock, ein Mitglied des House of Nobles, hat von der dunklen Magie unter der Stadt gehört. Nun drängt er seine Standesgenossen, eine umfassende Untersuchung einzuleiten. Bald könnten die Stadtwache und das prüfende Auge der Krone auf den Zirkel gerichtet sein."},{t="Ein Gebräu im Schatten",b="Zardeth der Schwarzen Klaue sucht ein unauffälliges Mittel, um Lord Wishock beschäftigt zu halten und einen offenen Konflikt mit Sturmwinds herrschender Schicht zu vermeiden. Das Gebräu erfordert seltene Pflanzen aus entlegenen Teilen der Östlichen Königreiche: die blasse Tilloaträne aus dem Dämmerwald und eine unter Wasser gesammelte Bisamwurzel unterhalb des Steinwerkdamms."}},faq={{q="Wer ist Lord Wishock?",a="Lord Wishock ist ein Adliger in Sturmwinds House of Nobles. Nachdem er Hinweise auf Hexenmeister unter dem Mage Quarter vernommen hatte, begann er, den Rat zur Einleitung einer förmlichen Untersuchung zu drängen.",al={"wishock","lord wishock","wer ist wishock"}},{q="Wer ist Zardeth der Schwarzen Klaue?",a="Zardeth ist ein hochrangiger Hexenmeister in den Krypten unter Sturmwinds Slaughtered Lamb. Er versucht, den Hexenmeisterzirkel der Stadt vor Entdeckung und einer Säuberung durch die Obrigkeit zu schützen.",al={"zardeth","zardeth schwarzen klaue","wer ist zardeth"}},{q="Woher stammt die Tilloaträne?",a="Die Tilloaträne ist eine zarte weiße Blume, die im überwucherten Garden of Stalvan am Rand von Dunkelhain im Dämmerwald wächst.",al={"tilloaträne fundort","tilloaträne","wo ist die tilloaträne"}},{q="Wo findet man die Bisamwurzel?",a="Die Bisamwurzel wächst nur in den Feuchtgebieten am Fuß der gewaltigen Wasserfälle unterhalb des Steinwerkdamms im Sumpfland.",al={"bisamwurzel fundort","bisamwurzel","wo bekommt man bisamwurzel"}},{q="Warum weiß Sturmwinds Regierung noch nichts von den Hexenmeistern?",a="Hexenmeistern wird in Sturmwind tiefes Misstrauen entgegengebracht, daher hält der Zirkel unter dem Slaughtered Lamb seine Praktiken unter der Erde verborgen, fern von Stadtwachen und Adligen. Lord Wishock hat erst kürzlich davon Wind bekommen.",al={"sturmwind hexenmeister geheimnis","warum verstecken sich hexenmeister","sind hexenmeister verboten"}},{q="Was will Zardeth mit diesen Reagenzien brauen?",a="Zardeth sagt, das Gebräu werde Lord Wishock beschäftigt halten und die Untersuchung verzögern. Was er mit dem Adligen vorhat, wird erst klar, wenn das Gebräu fertig ist.",al={"was ist das gebräu","nobles gebräu zweck","warum das gebräu herstellen"}}},fx={e620a973={q="Warum möchte Zardeth der Schwarzen Klaue, dass dies erledigt wird?",a="Lord Wishock entdeckte den geheimen Hexenmeister-Zirkel, der unter The Slaughtered Lamb im Mage Quarter von Sturmwind operiert. Da Wishock das Haus der Adligen aktiv dazu aufruft, eine formelle Untersuchung ihrer Präsenz einzuleiten, benötigt Zardeth ein Gebräu, um den sich einmischenden Adligen abzulenken, bevor die städtischen Behörden gegen ihre dunklen Praktiken vorgehen.",al={"warum zardeth helfen","zardeth motiv","warum will zardeth a noble brew"}},["9e466bd7"]={q="Wofür ist die Tilloaträne?",a="Die Tilloaträne ist eine zarte weiße Blume, die aus dem Garten von Stalvan in der Nähe von Dunkelhain geerntet wird. Zardeth benötigt sie als Hauptreagenz für das Brauen einer speziellen Mischung, die dazu bestimmt ist, Lord Wishocks politischen Kreuzzug gegen den Zirkel zu neutralisieren.",al={"was bewirkt tilloaträne","zweck der tilloaträne","warum tilloaträne benötigt"}},["84ab02b5"]={q="Wofür ist die Bisamwurzel?",a="Die Bisamwurzel wächst am nebelverhangenen Fuß der Wasserfälle unterhalb vom Steinwerkdamm im Sumpfland. Zardeth verwendet ihre wirkungsvollen Eigenschaften zusammen mit der Tilloaträne, um ein Gebräu herzustellen, das stark genug ist, um Lord Wishock abzulenken.",al={"was bewirkt bisamwurzel","zweck der bisamwurzel","warum bisamwurzel benötigt"}},["256dc9f2"]={q="Warum benötigt Zardeth einen Abenteurer, anstatt die Zutaten selbst zu beschaffen?",a="Zardeth und seine Hexenmeister-Gefährten müssen unter The Slaughtered Lamb verborgen bleiben. Das Verlassen ihres Zufluchtsortes riskiert, die sofortige Aufmerksamkeit der Stadtwache und des Hauses der Adligen auf sich zu ziehen, insbesondere während Lord Wishock aktiv eine Untersuchung fordert.",al={"warum ich a noble brew","warum braucht zardeth mich","warum kann zardeth die reagenzien nicht besorgen"}}},fp="12,156,24.304.0,27.311.1,20.186.0,33.170.0,40.130.0,33.128.0,67.202.0,53.158.1"}
P.entries["quest:336"] = {n="Ein nobles Bräu",s="Zardeth der Schwarzen Klaue schickt Euch mit Schwarzklauenbier für Lord Baurles K. Wischock zum Royal Keep. Das Gebräu muss ihn in der Halle der Bittsteller erreichen.",h="Zardeth der Schwarzen Klaue schickt Euch mit Schwarzklauenbier für Lord Baurles K.",kw={"baurles wischock","schwarzklauenbier","halle der bittsteller","nobles bräu","slaughtered lamb","burg sturmwind","zardeth"},sec={{t="Ein adliger Heuchler",b="In Burg Sturmwind spricht Lord Baurles K. Wischock über seine Bedeutung und die Zukunft des Königreichs. Doch die Gäste des Slaughtered Lamb wissen, dass er nachts in den oberen Räumen der Taverne trinkt und hohe Rechnungen unbezahlt lässt. Tagsüber fordert er die Schließung der Taverne."},{t="Ein tödlicher Trinkspruch",b="Unter dem Slaughtered Lamb braut Zardeth der Schwarzen Klaue Schwarzklauenbier, um Wischocks Schulden ein für alle Mal zu begleichen. Zardeth sagt, der Trunk habe es ordentlich in sich. Wischock hält Euch für einen Diener und wirft Euch eine Kupfermünze zu. Er trinkt gierig und bricht dann in den Hallen der Burg tot zusammen."}},faq={{q="Wer ist Zardeth der Schwarzen Klaue?",a="Zardeth der Schwarzen Klaue ist ein Hexenmeister mit einem verborgenen Zirkel in den Katakomben unter dem Slaughtered Lamb im Magierviertel von Sturmwind. Er führt gefährliche, geheime Unternehmungen fernab der Blicke der Stadtwache durch.",al={"wer ist zardeth","zardeth der schwarzen klaue","wer vergibt die quest"}},{q="Warum nimmt Zardeth Lord Wischock ins Visier?",a="Wischock trinkt nachts in den oberen Stockwerken des Slaughtered Lamb, ohne seine Rechnungen zu bezahlen. Tagsüber geht er in die Halle der Bittsteller und fordert die Obrigkeit auf, die Taverne zu schließen.",al={"warum wischock töten","wischocks beweggründe","warum vergiftet"}},{q="Wo ist Lord Wischock zu finden?",a="Lord Baurles K. Wischock ist in der Halle der Bittsteller zu finden, einem Vorraum in Burg Sturmwind, wo Adlige und Bürger bei der Regentschaft des Reiches vorsprechen.",al={"lord wischocks aufenthaltsort","wo ist wischock","halle der bittsteller wischock"}},{q="Wie nimmt Lord Wischock das Gebräu entgegen?",a="Wischock hält Euch für einen Diener, nimmt das Bier als Erfrischung entgegen und entlässt Euch mit einer Kupfermünze.",al={"stirbt wischock","wischocks tod","was bewirkt das bier"}},{q="Erregt die Lieferung des Biers die Aufmerksamkeit der Wachen?",a="Die Lieferung wirkt, als bringe ein gewöhnlicher Diener ein Getränk, und Ihr könnt ohne eine Konfrontation mit den Wachen weiterziehen.",al={"greifen die wachen an","werde ich in sturmwind gesucht","folgen der vergiftung"}},{q="Welche Quest folgt auf diese Lieferung?",a="Auf die Lieferung folgt „You Have Served Us Well“, was Euch zurück zu Zardeth unter dem Slaughtered Lamb schickt.",al={"what comes next","nach ein nobles bräu","nächste quest"}}},fx={c4eeba5d={q="Warum muss ich das Starkbier für Zardeth ausliefern, anstatt dass er es selbst tut?",a="Zardeth und seine Hexenmeisterkollegen operieren heimlich aus den Krypten unter dem The Slaughtered Lamb im Herzen von Sturmwind. Persönlich vor den Adligen und der Stadtwache in der Burg Sturmwind zu erscheinen, würde sofortige Aufmerksamkeit erregen und zur Verhaftung führen, besonders da Lord Wischock Zardeths Lokal bereits kennt. Indem er einen unauffälligen Abenteurer schickt, sieht die Lieferung wie die eines gewöhnlichen Dieners aus, der Erfrischungen bringt, was Zardeths Plan vor Blicken verborgen hält.",al={"warum braucht zardeth mich","warum das bier ausliefern","warum kann zardeth es ihm nicht selbst geben"}},["46bddf0f"]={q="Wer ist Lord Wischock, und warum hat man es auf ihn abgesehen?",a="Lord Baurles K. Wischock ist ein wichtigtuerischer Adliger aus Sturmwind, der sich in der Hall of Petitioners aufhält, um am Königshof vorzusprechen. Obwohl er sich für die Zukunft des Königreichs für unverzichtbar hält, verbringt er seine Nächte trinkend im Obergeschoss des Slaughtered Lamb, häuft gewaltige Zechschulden an, deren Begleichung er verweigert, und setzt sich zugleich aktiv für die Schließung des Lokals ein. Zardeth nimmt ihn ins Visier, um seinen Einmischungen ein Ende zu setzen und seine offenen Schulden einzutreiben.",al={"wer ist lord wischock","warum wischock töten","wer ist wischock","lord wischock"}}},fp="12,156,17.267.0,14.291.1,33.208.0,37.182.1,28.158.0,39.111.1,56.123.1,33.116.1"}
P.entries["quest:3361"] = {n="Dilemma eines Flüchtlings",s="Gnomeregans vertriebene Gnome fliehen nach Dun Morogh, nachdem Troggs und Strahlung sie aus ihrer Heimat vertrieben haben. Nahe Ambossar hat Ingenieur Felix Windenbolz seine Werkzeuge und Habseligkeiten an plündernde Frostmanetrolle verloren.",h="Gnomeregans vertriebene Gnome fliehen nach Dun Morogh, nachdem Troggs und Strahlung sie aus ihrer Heimat...",kw={"ambossar","eimer voller bolzen","coldridge","felix windenbolz","frostmane","gnomeregan","strahlung"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, dass ein Handwerker nicht tatenlos zusehen kann, wenn Plünderer Präzisionsbolzen, Messschieber und Werkzeugkästen rauben, die er ein Leben lang zusammengetragen hat.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Berge von Coldridge Eurem Volk seit Jahrhunderten Schutz bieten. Indem Ihr gnomischen Flüchtlingen helft, in Ambossar Fuß zu fassen, ehrt Ihr das uralte Bündnis zwischen Eisenschmiede und Gnomeregan.",["race:Gnome"]="Als Gnom kennt Ihr die bittere Tragödie, Eure wundersame Heimat durch Gift und Verrat zu verlieren. Nun müssen einfache Tüftler Fremde darum bitten, ihnen grundlegende Werkzeuge von den Trollen zurückzuholen."},sec={{t="Die Flucht aus Gnomeregan",b="Troggs überrannten Gnomeregan, die hochtechnisierte Stadt unter der Erde. Hochtüftler Gelbin Mekkadrill und seine Berater setzten radioaktives Gas frei, um die Eindringlinge zu töten. Stattdessen brachte das Gas Unheil. Tausende Unschuldige starben, Überlebende wurden zu geistlosen Lepragnomen, und die Übrigen flohen quer durch Dun Morogh."},{t="Plünderer im Schnee",b="Gnomische Ingenieure und Tüftler nahmen die Werkzeuge und Baupläne mit, die sie retten konnten. Frostmanetrolle durchstreifen die eisigen Gebirgspässe zwischen Gnomeregan und dem Coldridgetal. Als Felix Windenbolz zur Zuflucht in Ambossar eilte, raubten Frostmaneräuber seinen Werkzeugkasten, seine Schatulle und seinen Eimer voller Bolzen. Sie brachten seine Habseligkeiten in Lager südwestlich der Stadt."}},faq={{q="Wer ist Felix Windenbolz?",a="Felix Windenbolz ist ein gnomischer Ingenieur, der der radioaktiven Zerstörung Gnomeregans entkam. Er hat nahe Ambossar Zuflucht gefunden und kann sich der Gefahren Dun Moroghs nicht erwehren, also versucht er, seine gestohlene Ausrüstung zurückzubekommen.",al={"felix windenbolz","wer ist felix","felix ambossar"}},{q="Warum ist Gnomeregan verstrahlt?",a="Die gnomische Obrigkeit setzte während einer Trogginvasion radioaktives Gas frei, in der Hoffnung, die Eindringlinge auszulöschen. Stattdessen verseuchte das Gas Gnomeregans Belüftungssysteme. Es tötete die meisten Bewohner oder ließ sie mutieren und machte die Stadt unbewohnbar.",al={"was geschah mit gnomeregan","gnomeregan strahlung","fall von gnomeregan"}},{q="Wer hat Felix' Habseligkeiten gestohlen?",a="Frostmanetrolle raubten Felix' Truhe, seine Schatulle und seinen Eimer voller Bolzen. Sie überfallen Reisende auf Dun Moroghs Gebirgspfaden und bringen gestohlenen Schrott und Ausrüstung in ihre Lager südwestlich von Ambossar.",al={"wer stahl die bolzen","wer hat felix' sachen","frostmanetrolle"}},{q="Wo suchten die vertriebenen Gnome Zuflucht?",a="Viele vertriebene Gnome flohen quer durch Dun Morogh nach Eisenschmiede. Andere fanden vorübergehend Unterschlupf in Siedlungen wie Ambossar und Kharanos.",al={"wo leben gnome","gnomische flüchtlinge","gnomensiedlung"}},{q="Warum ist ein Eimer voller Bolzen so wichtig?",a="Für einen gnomischen Tüftler im Exil sind Werkzeuge, Spezialschrauben und präzise gefertigte Bolzen die Lebensgrundlage. Ohne geeignete Ausrüstung können geflüchtete Ingenieure weder ihrem Handwerk nachgehen noch Verteidigungsanlagen bauen oder sich im Exil ein neues Leben aufbauen.",al={"warum bolzen","felix eimer voller bolzen"}},{q="Welche Gefahr stellen die Frostmanetrolle für das Coldridgetal dar?",a="Der Stamm der Frostmane lebt seit Langem in Dun Moroghs unwirtlichen Gipfeln. Seit Troggvorstöße und Gnomeregans Evakuierung Chaos stiften, sind die Trolle kühner geworden. Sie überfallen Versorgungslinien und lauern Reisenden auf.",al={"trolle in dun morogh","bedrohung durch frostmanetrolle","frostmanelager"}}},fx={["0b2d3aab"]={q="Warum möchte Felix Windenbolz seine Habseligkeiten zurück?",a="Nachdem er vor der Strahlenvergiftung aus Gnomeregan floh und kaum die Kleidung am Leib hatte, verlor Felix die letzten Überreste seines Lebensunterhalts und Handwerks. Ohne seine persönliche Truhe, seinen Kasten und seine Werkzeuge sitzt er völlig mittellos in Ambossar fest und hat keine Möglichkeit, sein Leben neu aufzubauen oder als Flüchtling seinem Handwerk nachzugehen.",al={"felix motiv","warum braucht felix das","felix windenbolz habseligkeiten"}},["48f90e68"]={q="Warum kann Felix seine Habseligkeiten nicht selbst zurückholen?",a="Felix ist ein gewöhnlicher Tüftler und vertriebener Flüchtling, kein Abenteurer oder Soldat. Verängstigt von der feindseligen Wildnis und den Frostmähnentrollen, die seine Ausrüstung verschleppt haben, nicht gewachsen, kann er es nicht riskieren, sich allein in ihre Lager zu wagen.",al={"warum holt felix seine sachen nicht selbst","warum braucht felix mich","felix warum ich"}},["6a13a14f"]={q="Was befindet sich in Felix' Kasten und Felix' Truhe?",a="Felix' Truhe und Kasten enthalten die persönlichen Habseligkeiten und Spezialwerkzeuge, die er bei der Flucht vor der Katastrophe in Gnomeregan einpacken konnte. Für einen vertriebenen Handwerker weit weg von zu Hause enthalten diese Behälter alles, was für einen Neuanfang erforderlich ist.",al={"felix' kasten","felix' truhe","was ist in felix' truhe"}}},fp="20,206,26.299.0,22.354.0,25.201.0,29.233.0,29.194.0,43.135.0,42.212.0,61.203.0"}
P.entries["quest:3362"] = {n="Disteltal",s="In Tanaris halten seltsame Bestien Tran'rek davon ab, das Disteltal zu betreten. Er hofft, zurückzukehren, sobald die Kreaturen beseitigt sind.",h="In Tanaris halten seltsame Bestien Tran'rek davon ab, das Disteltal zu betreten.",kw={"kaktus","gadgetzan","gnarled thistleshrub","rootshaper","tanaris","thistleshrub","tran'rek","disteltal"},sec={{t="Ein gefährliches Tal",b="Südwestlich von Gadgetzan warnt Tran'rek, dass das Disteltal ein gefährlicher Ort ist. Seltsame Bestien streifen dort umher, darunter gnarled thistleshrubs und thistleshrub rootshapers. Solange dort so viele unterwegs sind, will Tran'rek nicht zurückkehren."},{t="Die thistleshrubs ausdünnen",b="Tran'rek bittet Euch, acht gnarled thistleshrubs und acht thistleshrub rootshapers zu beseitigen. Er möchte sich auch den Kaktus im Tal genauer ansehen, also lasst einen Teil davon unversehrt."}},faq={{q="Wer bittet um Hilfe im Disteltal?",a="Tran'rek in Gadgetzan bittet um Hilfe.",al={"questgeber","tran'rek standort","wer bietet disteltal an"}},{q="Wo liegt das Disteltal?",a="Das Disteltal liegt südwestlich von Gadgetzan.",al={"disteltal lage","wo liegt das tal","tal in tanaris finden"}},{q="Welche Kreaturen müssen beseitigt werden?",a="Beseitigt acht gnarled thistleshrubs und acht thistleshrub rootshapers.",al={"ziele","was töten","welche thistleshrubs"}},{q="Warum möchte Tran'rek, dass ein Teil des Kaktus unversehrt bleibt?",a="Tran'rek möchte sich den Kaktus im Tal genauer ansehen, also lasst einen Teil davon unversehrt.",al={"tranrek beweggrund","warum ins tal gehen","interesse an kakteen"}}},fp="19,132,18.221.0,26.186.0,43.38.0,29.49.0,34.73.0,60.91.0"}
P.entries["quest:3364"] = {n="Lieferung des kochend heißen Morgengebräus",s="Nori Stolzmut schickt Euch mit heißem Morgengebräu für Durnan Pelznaht in Ambossar durch das Coldridgetal. Die Bergkälte kann ihm vor der Ankunft die Wärme rauben.",h="Nori Stolzmut schickt Euch mit heißem Morgengebräu für Durnan Pelznaht in Ambossar durch das Coldridgetal.",kw={"ambossar","das coldridgetal","dun morogh","durnan pelznaht","morgengebräu","nori stolzmut"},ang={["profession:Cooking"]="Als Koch wisst Ihr, dass ein Getränk mit der richtigen Temperatur ein Zeichen des Respekts ist, besonders in der bitteren Kälte von Dun Morogh.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass kaltes Gebräu in der Bergluft ein Jammer ist, den zu verhindern sich ein Weg durchs Tal lohnt."},sec={{t="Ein Wettlauf gegen den Frost",b="Nachdem Ihr Grelin Weißbart beliefert habt, hat Nori einen weiteren Becher zu verschicken. Er kann ihn nicht selbst hinbringen, bevor das Morgengebräu zu Schneematsch gefriert. Also bittet er Euch, dem Schnee zu trotzen und seinen Kunden nicht warten zu lassen."},{t="Der Preis eines warmen Bechers",b="Durnan Pelznaht wartet in Ambossars warmer Berghalle und ist bei seinen Erfrischungen wählerisch. Abgekühltes Morgengebräu nimmt er nicht an. Ein heißer Becher verschafft dem erschöpften Zwerg eine nötige Pause von seinen Pflichten. Nori erwartet seinen Lieblingsbecher in einem Stück zurück."}},faq={{q="Wer ist Durnan Pelznaht?",a="Durnan Pelznaht ist ein Zwerg in Ambossars unterirdischer Halle im Coldridgetal. Nori Stolzmut bringt ihm heißes Morgengebräu.",al={"durnan pelznaht","wer ist durnan","pelznaht"}},{q="Warum muss die Lieferung so schnell ankommen?",a="Die Kälte im Coldridgetal lässt heiße Getränke rasch abkühlen. Durnan hat kochend heißes Morgengebräu bestellt, und Zwerge betrachten kaltes Bier oder kalten Tee als verdorben.",al={"warum zeitlimit","morgengebräu zeitlimit","warum eilen"}},{q="Wer ist Nori Stolzmut?",a="Nori Stolzmut ist ein Zwerg, der an den verschneiten Wegen des Coldridgetals stationiert ist. Er bringt Lieferungen zwischen den örtlichen Lagern hin und her, darunter Getränke für Grelin Weißbart und Arbeiter in Ambossar.",al={"nori stolzmut","nori","wer ist nori"}},{q="Was ist Morgengebräu?",a="Morgengebräu ist ein warmes, belebendes Morgentrunk der Zwerge. Es vertreibt die Kälte der Gipfel von Dun Morogh und stärkt die zähen Bergarbeiter.",al={"was ist morgengebräu","morgengebräu hintergrund"}},{q="Wo liegt Ambossar?",a="Ambossar liegt nordöstlich von Noris Posten, in den Bergfels des Coldridgetals gehauen. Es bietet jungen Gebirgsjägern und Handwerkern Schutz vor den Schneestürmen.",al={"wo liegt ambossar","ambossar lage","ambossar finden"}},{q="Will Nori den Becher zurück?",a="Ja. Wenn Durnan sein heißes Gebräu ausgetrunken hat, gibt er den leeren Becher für Nori im Coldridgetal zurück.",al={"becher zurückgeben","bring back the mug","noris becher"}}},fx={["77d8ea01"]={q="Warum möchte Nori Stolzmut, dass das Morgenbräu ausgeliefert wird?",a="Nori sollte frisches, kochend heißes Morgenbräu an Durnan Pelznaht ausliefern, aber eine frühere Lieferung an Grelin Weißbart hielt ihn auf. Durnan erwartet sein Gebräu speziell kochend heiß, nicht lauwarm oder kalt, daher bemüht sich Nori, das Getränk nach Ambossar zu bringen, bevor es vollständig abkühlt.",al={"warum morgenbräu ausliefern","nori motiv","warum muss das von nori ausgeliefert werden"}},["4fdc3467"]={q="Warum bittet Nori Euch, es auszuliefern, anstatt es selbst zu bringen?",a="Nori ist bereits in Verzug geraten, nachdem er angehalten hatte, um Grelin Weißbart zu bedienen. Da er weiß, dass das Gebräu nur für wenige kurze Minuten kochend heiß bleibt, erkennt er, dass er den Bergpfad aus eigener Kraft nicht schnell genug hinaufsprinten kann. Als er Euch sah, verließ er sich auf Eure frischen Beine, um nach Ambossar zu eilen, bevor das Getränk kalt wird.",al={"warum braucht nori mich","warum kann nori es nicht ausliefern","warum ich nori lieferung"}}},fp="26,157,24.205.0,23.249.0,24.120.0,41.133.0,23.187.0,17.141.0,26.155.0,28.94.0"}
P.entries["quest:3365"] = {n="Den Becher zurückbringen",s="Durnan Pelznaht schickt Euch mit Nori Stolzmuts leerem Becher zurück durch das Coldridgetal. Mit seiner Rückgabe ist die Mornbrew-Lieferung abgeschlossen.",h="Durnan Pelznaht schickt Euch mit Nori Stolzmuts leerem Becher zurück durch das Coldridgetal.",kw={"den becher zurückbringen","dun morogh","durnan pelznaht","kharanos","mornbrew","nori stolzmut","humpen"},ang={["profession:Cooking"]="Als Koch oder Brauer wisst Ihr, dass guter Service erst endet, wenn das Geschirr vollständig beisammen und wieder in der Küche ist.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass es zu einer Schlägerei führen kann, den Humpen eines Wirts zu behalten. Noris Becher zurückzubringen, gehört zu den grundlegenden zwergischen Umgangsformen."},sec={{t="Eine Frage der Wirtshausmanieren",b="Nachdem er sich mit dem Mornbrew aufgewärmt hat, vertraut Durnan Euch den Humpen an. In Dun Morogh beißt die Kälte bitter, und Gastfreundschaft beruht dort auf gegenseitigem Respekt. Auch gutes Geschirr sollte seinen Weg zurückfinden."},{t="Becher wachsen nicht auf Bäumen",b="Nori Stolzmut schätzt robustes Trinkgeschirr. Becher wachsen nicht auf Bäumen, besonders nicht zwischen den eisigen Klippen der Zwergenheimat. Bringt seinen Becher heil zurück, und Ihr zeigt der örtlichen Gemeinschaft, dass man Euch vertrauen kann."}},faq={{q="Wer erteilt diesen Auftrag?",a="Nachdem Ihr Durnan Pelznaht in Dun Morogh den frisch gebrauten Mornbrew gebracht habt, schickt er Euch mit dem leeren Humpen zurück.",al={"questgeber","wer vergibt den becher zurückbringen","durnan pelznaht quest"}},{q="Wem bringe ich den Becher zurück?",a="Bringt den leeren Becher zu Nori Stolzmut zurück, der durch das Coldridgetal in Dun Morogh zieht und seinen Mornbrew verkauft.",al={"wohin mit dem becher","wer bekommt den becher","nori standort"}},{q="Gibt es eine Frist für die Rückgabe des Bechers?",a="Es gibt keine Frist. Für die erste Lieferung des Scalding Mornbrew galt eine strenge Zeitvorgabe, damit er kochend heiß blieb, doch den leeren Becher könnt Ihr in aller Ruhe zurückbringen.",al={"hat diese quest ein zeitlimit","becher zeitlimit","ist bei der rückkehr eile nötig"}},{q="Warum ist Nori ein leerer Becher so wichtig?",a="Hochwertige Becher und Humpen sind in Dun Morogh wertvolles Schankgeschirr. Nori betont, dass Becher nicht auf Bäumen wachsen und Schenken es sich nicht leisten können, Trinkgeschirr an vorbeiziehende Kuriere zu verlieren.",al={"warum will nori den becher zurück","bedeutung des bechers"}},{q="Welche Quest führt direkt zu dieser?",a="Diese Quest folgt direkt auf Scalding Mornbrew Delivery, nachdem Durnan das Getränk getrunken hat, das Ihr ihm gebracht habt.",al={"vorausgesetzte quest","was kommt vor den becher zurückbringen"}},{q="Wo ist Durnan Pelznaht zu finden?",a="Ihr findet Durnan Pelznaht in Ambossar, der in den Berg gegrabenen Siedlung im Coldridgetal. Er verkauft Stoff- und Lederrüstung.",al={"durnan standort","wo ist durnan"}}},fx={aa771bb6={q="Warum möchte Durnan Pelznaht, dass dies erledigt wird?",a="Durnan Pelznaht hat gerade das kochend heiße Morgenbräu genossen, das von Nori im Coldridgetal geliefert wurde, um die Kälte zu vertreiben. Den leeren Krug zurückzugeben, ist einfache Höflichkeit gegenüber Nori Stolzmut, der seine Glaswaren zurückerwartet, anstatt Kuriere sie verstreut im eisigen Schnee von Dun Morogh liegen zu lassen.",al={"warum krug zurückgeben","durnan krug zurückgeben","warum den krug zurückschicken"}}},fp="18,130,28.195.0,24.218.0,23.122.0,27.105.0,40.160.0,46.172.0,40.104.0,36.130.0"}
P.entries["quest:3367"] = {n="Suntara-Steine",s="In der Sengenden Schlucht liegt Dorius Stonetender schwer verletzt und bittet Euch, ihm nach Eisenschmiede zu helfen.",h="In der Sengenden Schlucht liegt Dorius Stonetender schwer verletzt und bittet Euch, ihm nach Eisenschmiede zu...",kw={"dorius stonetender","eisenschmiede","sengende schlucht","angesengter brief","steinwerkpass","suntara-steine"},sec={{t="Eine Bitte um Hilfe",b="Dorius Stonetender stöhnt vor Schmerzen. Ihm ist schwindelig, während sich die Welt um ihn dreht, und er hat innere Blutungen. Er sehnt sich danach, nach Eisenschmiede zurückzukehren. Also bittet er Euch, ihm bei der Reise zu helfen."},{t="Der Weg zum Pass",b="Die Straße endet kurz vor dem Steinwerkpass. Dort wird Dorius erschossen und stirbt. Ein Brief, den er bei sich trug, fällt angesengt zu Boden."}},faq={{q="Wer ist Dorius Stonetender?",a="Dorius Stonetender ist in der Sengenden Schlucht schwer verletzt und braucht Hilfe, um Eisenschmiede zu erreichen.",al={"wer ist dorius","dorius stonetender","verletzter zwerg sengende schlucht"}},{q="Wohin will Dorius gelangen?",a="Dorius versucht, nach Eisenschmiede zurückzukehren.",al={"dorius ziel","wohin geht dorius","dorius eskortort"}},{q="In welchem Zustand ist Dorius?",a="Dorius ist schwer verletzt, ihm ist schwindelig und er hat innere Blutungen. Die Welt dreht sich um ihn.",al={"dorius zustand","ist dorius verletzt","warum braucht dorius hilfe"}}},fp="14,94,15.194.0,20.127.1,26.87.0,29.40.0,28.87.0"}
P.entries["quest:3368"] = {n="Suntara-Steine",s="Bei den Suntara-Steinen berichtet Dorius' Brief von einem Team, das die Dunkeleisenzwerge versklavt haben. Die Steine existieren wirklich und sind in den Händen der Dunkeleisenzwerge. Ihr Anführer, Lathoric the Black, nutzt die Macht der Steine, um Dorius' Ausgrabungsteam zu versklaven. Ihr bringt den Brief zu seinem Bruder Thorius in der Hall of Explorers in Eisenschmiede.",h="Bei den Suntara-Steinen berichtet Dorius' Brief von einem Team, das die Dunkeleisenzwerge versklavt haben.",kw={"kessel","dorius","hall of explorers","eisenschmiede","lathoric the black","obsidion","sengende schlucht","versengter brief","suntara-steine","thorius"},sec={{t="Der Brief des Toten",b="Dorius schreibt seinem Bruder in dem Brief, dass er nicht mehr lebt, wenn die Nachricht gelesen wird. Die Suntara-Steine existieren wirklich, und die Dunkeleisenzwerge besitzen sie. Ihr Anführer, Lathoric the Black, nutzt ihre Macht, um Dorius' Ausgrabungsteam zu versklaven. Das Team wurde in den Kessel gebracht, wo ihr Geist verdreht wird, während sie Tag und Nacht schuften, um etwas namens Obsidion fertigzustellen. Dorius fleht seinen Bruder an, ihnen zu helfen. Er nennt es seinen letzten Wunsch und bittet darum, jenen zu danken, die den Brief überbringen."},{t="Thorius erfährt die Nachricht",b="Kurator Thorius schluchzt, als Dorius' Brief eintrifft. Dann trocknet er sein Gesicht und schwört beim Licht, dass Dorius sein Wunsch erfüllt wird."}},faq={{q="Wer hat den versengten Brief geschrieben?",a="Dorius schrieb den versengten Brief an seinen Bruder, damit er nach seinem Tod gelesen wird.",al={"wer schrieb den brief","verfasser des versengten briefs","dorius brief"}},{q="Wo lebt Thorius?",a="Kurator Thorius lebt in der Hall of Explorers in Eisenschmiede.",al={"wo ist thorius","kurator thorius aufenthaltsort","thorius hall of explorers"}},{q="Was ist mit Dorius' Ausgrabungsteam geschehen?",a="Laut dem Brief nutzen Lathoric the Black und die Dunkeleisenzwerge die Macht der Steine, um Dorius' Ausgrabungsteam zu versklaven. Sie brachten das Team in den Kessel.",al={"was geschah mit dem ausgrabungsteam","dorius ausgrabungsteam","versklavte bergleute kessel"}},{q="Woran arbeitet das versklavte Team?",a="Laut dem Brief wird der Geist der Teammitglieder verdreht, während sie Tag und Nacht an etwas namens Obsidion schuften.",al={"was ist obsidion","kessel ausgrabungsprojekt","dunkeleisenzwerge projekt obsidion"}},{q="Wer ist Lathoric the Black?",a="Der Brief nennt Lathoric the Black als Anführer der Dunkeleisenzwerge. Sie besitzen die Suntara-Steine und nutzen ihre Macht, um Dorius' Team zu versklaven.",al={"wer ist lathoric","lathoric the black","anführer der dunkeleisenzwerge sengende schlucht"}},{q="Wie schließt dies an die frühere Quest „Suntara-Steine“ an?",a="Die erste Quest „Suntara-Steine“ erzählt, wie Dorius erschossen wurde und der Brief zu Boden fiel. Ihr bringt den Brief nach Eisenschmiede.",al={"vorherige suntara-steine-quest","suntara-steine-questreihe"}}},fp="14,302,21.469.0,22.129.1,28.74.0,26.57.0,42.148.0,37.101.0,26.143.0,48.115.0"}
P.entries["quest:3369"] = {n="Alptraum",s="Ein Splitter aus den Höhlen des Wehklagens bringt eine beunruhigende Vision nach Donnerfels. Ihr bringt den leuchtenden Alptraumsplitter zu Erzdruide Hamuul Runentotem auf der Anhöhe der Ältesten, wo er Verderbnis im Smaragdgrünen Traum offenbart.",h="Ein Splitter aus den Höhlen des Wehklagens bringt eine beunruhigende Vision nach Donnerfels.",kw={"die anhöhe der ältesten","smaragdgrüner traum","falla weisenwind","leuchtender splitter","hamuul runetotem","alptraum","alptraumsplitter","donnerfels","die höhlen des wehklagens"},ang={["class:Druid"]="Für Druiden ist der Splitter ein alarmierender Beweis dafür, dass die unberührte Heiligkeit des Smaragdgrünen Traums befleckt ist. Er bestätigt das Flüstern über Verderbnis, die durch die Zirkel des Cenarius schleicht.",["faction:Horde"]="Als Mitglied der Horde helft Ihr durch die Überbringung des Splitters, das geistige Wohlergehen des zentralen Kalimdor zu bewahren. Das zeigt die entscheidende Rolle der Horde beim Eindämmen der durch Pilze und Träume entstandenen Verderbnis, die aus dem Brachland strömt.",["race:Tauren"]="Als Tauren spiegelt Eure Rückkehr zu Erzdruide Hamuul Runentotem die wachsende Bedeutung der Taurendruiden im Zirkel des Cenarius wider. An der Seite ihrer nachtelfischen Lehrer stellen sie sich uralten kosmologischen Bedrohungen."},sec={{t="Eine beunruhigende Entdeckung",b="Falla Weisenwind erkennt die reine Essenz des Smaragdgrünen Traums in einem seltsamen Kristall aus den Höhlen des Wehklagens. In seinem Inneren liegt eine dunkle, chaotische Vision, eher ein wacher Alptraum als friedlicher Schlummer. Da sie nicht offen über das Omen sprechen will, vertraut sie Euch den Splitter an. Dann schickt sie Euch zu Erzdruide Hamuul Runentotem, dem ehrwürdigsten der alten Druiden von Donnerfels."},{t="Ein Geheimnis im Traum",b="Auf der Anhöhe der Ältesten blickt Hamuul Runetotem in den Alptraumsplitter, und seine Fassung gerät ins Wanken. Er liefert ihm einen greifbaren Beweis dafür, dass der Smaragdgrüne Traum in einen Alptraum zerfällt. Er mahnt zur Diskretion und warnt, dass gewöhnliche Reisende solch heikle Angelegenheiten nicht verstehen können. Im Stillen beschließt er, das Leiden zu untersuchen, das das schlummernde Reich bedroht."}},faq={{q="Was ist der Alptraumsplitter?",a="Der Alptraumsplitter ist das leuchtende Fragment, das in den Höhlen des Wehklagens geborgen wurde. Falla Weisenwind vertraut ihn Euch an, nachdem sie ihn untersucht hat. Er besteht aus der reinen geistigen Essenz des Smaragdgrünen Traums und birgt eine verderbte, verzerrte Vision, die zeigt, dass im Traum etwas furchtbar schiefgegangen ist.",al={"was ist der alptraumsplitter","leuchtender splitter alptraum","was hat falla gefunden"}},{q="Wer ist Falla Weisenwind?",a="Falla Weisenwind ist eine kundige Taurendruidin am Berghang über den Höhlen des Wehklagens im Brachland. Sie untersucht seltsame Phänomene in den verderbten Oasenhöhlen und schickt Kuriere der Horde zu Hamuul Runetotem, wenn gefährliche Relikte gefunden werden.",al={"falla weisenwind","wer hat mir diese quest gegeben","questgeber"}},{q="Wo finde ich Erzdruide Hamuul Runentotem?",a="Erzdruide Hamuul Runentotem lebt auf der Anhöhe der Ältesten, einem der hoch aufragenden Tafelberge von Donnerfels. Er steht im Druidenkreis bei seinen Mitstreitern aus dem Zirkel des Cenarius.",al={"wo ist hamuul","hamuul runetotem aufenthaltsort","anhöhe der ältesten hamuul"}},{q="Warum will Hamuul den Splitter geheim halten?",a="Hamuul will den Splitter geheim halten, weil der Smaragdgrüne Traum die heilige Zuflucht der Natur und der schlummernden Druiden ist. Der Beweis für seine Verwandlung in einen Alptraum könnte den Zirkel des Cenarius in Panik versetzen und die fragilen Bemühungen schwächen, das geistige Leben in ganz Kalimdor wiederherzustellen, weshalb Hamuul zum Schweigen mahnt.",al={"warum geheim halten","hamuuls geheimnis","warum versteckt hamuul den splitter"}},{q="Gibt es eine Version dieser Quest für die Allianz?",a="Ja. Die Champions der Horde bringen den Alptraumsplitter zu Erzdruide Hamuul Runentotem in Donnerfels. Ermittler der Allianz aus den Höhlen des Wehklagens bringen ihren Splitter über das Meer nach Darnassus und überreichen ihn Mathrengyl Bärenfährte vom Zirkel des Cenarius.",al={"allianzversion","alptraum allianz","kann die allianz das machen"}},{q="Wie hängt das mit den Höhlen des Wehklagens zusammen?",a="Der Splitter stammt aus den Höhlen des Wehklagens, wo der Druide Naralex in tiefe Trance fiel, um unterirdische Quellen ins Brachland zu leiten. Sein Schlummer wurde zu einem wachen Alptraum, statt das Land zu heilen. Dieser ließ die Tierwelt der Höhlen mutieren und breitete sich in Kristallsplittern wie diesem aus.",al={"höhlen des wehklagens zusammenhang","naralex zusammenhang","wie hängt das mit naralex zusammen"}}},fx={d74ecb00={q="Warum möchte Falla Weisenwind, dass der Alptraumsplitter an Hamuul Runetotem ausgeliefert wird?",a="Als Falla Weisenwind den Splitter untersucht, erkennt sie ihn als reine Essenz des Smaragdgrünen Traums, jedoch befleckt von Visionen eines wachen Alptraums. Beunruhigt von dem, was sie sieht, erkennt sie, dass die Entdeckung viel zu gefährlich und bedeutsam ist, als dass sie allein damit umgehen könnte. Sie weigert sich, weiter darüber zu sprechen und besteht darauf, dass Ihr ihn sofort zum Erzdruide Hamuul Runetotem nach Donnerfels bringt, da sie nur einem der ranghöchsten und weisesten Druiden des Zirkel des Cenarius zutraut, ein solch schlimmes Omen zu verstehen und zu bewältigen.",al={"warum splitter an hamuul schicken","warum möchte falla das erledigt haben","falla weisenwind motiv"}}},fp="13,214,22.348.0,21.351.1,28.276.0,22.253.0,45.172.0,48.297.0,47.252.0,44.273.0"}
P.entries["quest:337"] = {n="Ein altes Geschichtsbuch",s="Milton Garbenbund erwartet in der Royal Library eine verschollene Chronik Sturmwinds. Das Buch „Die Geschichte von Sturmwind“ trägt das Siegel der Bibliothek und verschwand, bevor das Königreich nach dem Ersten Krieg wiedererstand. Seine Rückkehr könnte helfen, die Geschichte der südlichen Menschenlande zu bewahren.",h="Milton Garbenbund erwartet in der Royal Library eine verschollene Chronik Sturmwinds.",kw={"ein altes geschichtsbuch","dämmerwald","milton garbenbund","wissen bewahren","süderstade","burg sturmwind","bibliothek von sturmwind","die geschichte von sturmwind"},ang={["class:Mage"]="Als Magier wisst Ihr, dass alte Bibliotheken Wissen bergen, das verfallen oder vernachlässigt werden kann, wenn es in der Wildnis zurückbleibt.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr, Bruchstücke von Sturmwinds Erbe wiederherzustellen, die die Verwüstungen des Ersten Krieges überstanden haben.",["race:Human"]="Als Mensch aus dem Süden helft Ihr, schriftliche Aufzeichnungen aus der Wildnis zurückzuholen und eine von der Old Horde zerschlagene Kultur wiederaufzubauen."},sec={{t="Ein Relikt des Ersten Krieges",b="Ihr findet das schlammverkrustete Buch zwischen den Ruinen des Dämmerwalds, wo Untote und Oger umherstreifen. Seine erste Seite trägt das offizielle Bibliothekssiegel Sturmwinds, das es als seltenes Relikt aus der Zeit vor der Zerstörung der Stadt ausweist. Es wurde vor Jahrzehnten ausgeliehen, bevor die Horde die Hauptstadt niederbrannte, und galt seit dem Fall des Südens als verschollen."},{t="Vergessene Annalen wiederherstellen",b="Milton Garbenbund erkennt das Buch wieder, als Ihr es zur Royal Library in Burg Sturmwind bringt. Er will es im Archiv für seltene Bücher unterbringen, doch die Jahre in der heimgesuchten Wildnis haben seine Seiten schwer beschädigt. Der Fund veranlasst Garbenbund, in Süderstade nach weiterem verschollenem Wissen zu suchen, der nächstgelegenen Stadt zu Alteracs zerstörtem Königreich und seinen verlassenen Bibliotheken."}},faq={{q="Wo ist dieses Buch zu finden?",a="Ihr findet das Buch bei den feindseligen Kreaturen des Dämmerwalds, oft bei Untoten auf Friedhöfen und Feldern oder bei Ogern in den südlichen Hügeln.",al={"wo altes geschichtsbuch finden","fundort des buches","geschichtsbuch dämmerwald"}},{q="Zu wem bringe ich das Buch?",a="Bringt den Band zu Milton Garbenbund, dem Chefbibliothekar der Royal Library in Burg Sturmwind.",al={"abgabeort","wo wird das abgegeben","milton garbenbund standort"}},{q="Warum ist das Buch in so schlechtem Zustand?",a="Das Buch wurde vor dem Ersten Krieg und der Plünderung Sturmwinds ausgeliehen. Es verbrachte Jahrzehnte in der Wildnis des Dämmerwalds, war Schmutz und Fäulnis ausgesetzt und ging durch die Hände umherstreifender Plünderer und Monster.",al={"warum ist es schlammig","warum beschädigt"}},{q="Führt die Rückgabe dieses Buches zu weiteren Aufgaben?",a="Ja. Milton Garbenbund schickt Euch nach Norden nach Süderstade im Vorgebirge des Hügellands, um mit Meister der Lehren Dibbs zu sprechen, der Euch zu Büchern in den Ruinen von Alterac führen kann.",al={"what comes next","folgequest","buch questreihe"}},{q="Warum liegt Milton Garbenbund gerade dieser Wälzer so am Herzen?",a="Nur wenige Originalaufzeichnungen überstanden den Fall des Königreichs und den Brand Sturmwinds während des Ersten Krieges. Echte Texte aus der Vorkriegszeit helfen Gelehrten, die Vergangenheit des Königreichs zu rekonstruieren.",al={"warum ist das buch wichtig","bedeutung der geschichte von sturmwind"}},{q="Können Spieler der Horde diese Quest abschließen?",a="Nein. Das Buch gehört zur Royal Library von Sturmwind, und nur Bibliothekare der Allianz in Burg Sturmwind können es entgegennehmen.",al={"hordenversion","nur für die allianz"}}},fp="19,265,24.316.0,26.343.0,25.134.0,27.92.0,39.188.0,45.159.0,60.171.0,38.114.0"}
P.entries["quest:3370"] = {n="Alptraum",s="Falla Weisenwind schickt einen leuchtenden Splitter zu den Ältestendruiden in Darnassus. Er birgt die Essenz des Smaragdgrünen Traums, getrübt von dunklen Visionen.",h="Falla Weisenwind schickt einen leuchtenden Splitter zu den Ältestendruiden in Darnassus.",kw={"zirkel des cenarius","die enklave des cenarius","darnassus","smaragdgrüner traum","falla weisenwind","leuchtender splitter","alptraum","mathrengyl bärenfährte","alptraumsplitter"},ang={["class:Druid"]="Als Druide erfahrt Ihr, dass der heilige Smaragdgrüne Traum nicht die unberührte Zuflucht ist, mit der Ihr in Einklang zu treten gelernt habt. Der Splitter deutet auf eine Gefahr in seinem Inneren hin.",["faction:Alliance"]="Als Reisender der Allianz tragt Ihr das Relikt nach Darnassus und gewährt der Führung der Nachtelfen einen frühen Einblick in die Verderbnis unter der Weltoberfläche.",["race:NightElf"]="Als Nachtelf ehrt Ihr das schlafende Reich, in dem Malfurion Sturmgrimm verweilt. Ein erwachender Alptraum in seiner Essenz trifft Euer spirituelles Erbe ins Herz."},sec={{t="Eine beunruhigende Offenbarung",b="Falla Weisenwind sieht mehr als einen Kristall in dem leuchtenden Splitter, der aus den Tiefen der Höhlen des Wehklagens geborgen wurde. In ihm liegt die reine Essenz des Smaragdgrünen Traums. Doch der Splitter zeigt furchterregende Visionen, wo die Natur in Harmonie sein sollte. Erschüttert will Falla ihn nicht weiter untersuchen. Sie schickt Euch los, um den Splitter zu den hochrangigen Druiden des Zirkels des Cenarius zu bringen."},{t="Flüstern in der Enklave des Cenarius",b="Mathrengyl Bärenfährte untersucht den Splitter, den Ihr zur Enklave des Cenarius in Darnassus bringt. Ruhige Neugier weicht Unbehagen, als er in dessen Kern blickt. Er erkennt, dass die Verderbnis im Brachland mit Störungen tief im Smaragdgrünen Traum verbunden ist. Dann bringt Mathrengyl das Gespräch zum Schweigen. Solche Schrecken sind nicht für gewöhnliche Ohren bestimmt, und er nimmt den Splitter in Verwahrung, um den sich im Traum ausbreitenden Schatten zu erforschen."}},faq={{q="Was ist der Alptraumsplitter?",a="Der Alptraumsplitter ist ein Kristall, der einen Teil der Essenz des Smaragdgrünen Traums birgt. Er wurde zunächst als geheimnisvoller leuchtender Splitter gefunden. Seine dunklen Visionen offenbaren, dass eine unheilvolle Präsenz in den Traum eingedrungen ist.",al={"was ist der alptraumsplitter","leuchtender splitter hintergrund","smaragdgrüner traum splitter"}},{q="Wer ist Falla Weisenwind?",a="Falla Weisenwind ist eine Taurendruidin, die das Wissen der Natur erforscht und seltsame Relikte untersucht, die in der Wildnis gefunden werden. Nachdem sie den erschreckenden Ursprung des Splitters erkannt hat, schickt sie Reisende zu den hochrangigen Druiden in Darnassus.",al={"falla weisenwind","wer ist falla"}},{q="Wer ist Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte ist ein Ältestendruide und Druidenlehrer des Zirkels des Cenarius in der Enklave des Cenarius in Darnassus. Er unterweist Druiden und untersucht schwerwiegende spirituelle Bedrohungen für die Natur und den Smaragdgrünen Traum.",al={"mathrengyl bärenfährte","bärenfährte darnassus","wer ist mathrengyl"}},{q="Warum ist Mathrengyl wegen des Splitters so verschwiegen?",a="Mathrengyl schweigt, weil der Splitter Verderbnis im Smaragdgrünen Traum zeigt, einem heiligen Reich der Natur, das von der Green Dragonflight und schlafenden Druiden gelenkt wird. Die Bedrohung ist eine tiefgreifende spirituelle Krise, und der Zirkel des Cenarius zögert, sie öffentlich bekannt zu machen.",al={"warum geheim","was verbirgt mathrengyl","warum spricht mathrengyl nicht"}},{q="Wo beginnt diese Questreihe?",a="Die Geschichte beginnt mit dem Leuchtenden Splitter, einem Gegenstand, der bei Mutanus dem Verschlinger am Ende der Höhlen des Wehklagens gefunden wird. Gelehrte verfolgen die Spur seines unheilvollen Ursprungs schließlich nach Darnassus oder Donnerfels.",al={"alptraum voraussetzung","wo begann das","wie erhält man alptraum"}},{q="Gibt es für Spieler der Horde eine entsprechende Quest?",a="Ja. Reisende der Allianz bringen ihre Erkenntnisse zu Mathrengyl Bärenfährte in Darnassus, während Reisende der Horde Hamuul Runetotem auf der Anhöhe der Ältesten in Donnerfels Bericht erstatten. Beide hören dieselben beunruhigenden Nachrichten über den Smaragdgrünen Traum.",al={"hordenversion","gibt es alptraum für die horde","alptraum horde"}}},fx={da5fa45e={q="Warum möchte Falla Weisenwind, dass der Alptraumsplitter ausgeliefert wird?",a="Falla Weisenwind erkannte, dass der Splitter die Essenz des Smaragdgrünen Traums enthält, aber die Vision, die sie darin erhaschte, war tief in einen Alptraum verdreht. Alarmiert von dem, was sie sah, und im Wissen, dass eine solch bedrohliche Verderbnis weit über ihr Verständnis hinausgeht, besteht sie darauf, dass er umgehend von einem weisen Druiden des Zirkel des Cenarius in Darnassus untersucht wird.",al={"warum den splitter nach darnassus schicken","warum möchte falla das erledigt haben","falla weisenwind motiv"}}},fp="13,138,22.349.0,32.414.1,28.202.1,22.210.0,29.200.0,47.266.1,34.189.0,42.227.0"}
P.entries["quest:3372"] = {n="Erlöst sie",s="In der Sengenden Schlucht fleht Euch ein sterbender Archäologe an, jene zu erlösen, die unter der Macht der Suntara noch immer arbeiten. Ihre Körper haben versagt, und das vom Twilight's Hammer bewachte Relikt muss auf den Altar von Suntara gelegt werden.",h="In der Sengenden Schlucht fleht Euch ein sterbender Archäologe an, jene zu erlösen, die unter der Macht der...",kw={"altar von suntara","sterbender archäologe","geheimnisvolles artefakt","erlöst sie","sengende schlucht","die schlackengrube","twilight's hammer"},sec={{t="Eine sterbende Bitte",b="Ein sterbender Archäologe bittet Euch, jene zu erlösen, die noch immer ihrer Arbeit nachgehen, und bricht dann zusammen. Ihre Körper haben versagt, doch die Macht der Suntara treibt sie weiter an. Der Archäologe sagt, der Altar von Suntara sei der Schlüssel."},{t="Der Altar von Suntara",b="Nordwestlich der Höhle, in den Hügeln darüber, bewachen Götzendiener des Twilight's Hammer das Geheimnisvolle Artefakt. Nehmt ihnen das Relikt ab und bringt es in die Schlackengrube. Legt es dort auf den Altar von Suntara."}},faq={{q="Wer bittet bei „Erlöst sie“ um Hilfe?",a="Ein sterbender Archäologe in der Sengenden Schlucht bittet um Hilfe und bricht dann zusammen.",al={"questgeber","wer vergibt erlöst sie","sterbender archäologe"}},{q="Wo befindet sich das Geheimnisvolle Artefakt?",a="Götzendiener des Twilight's Hammer bewachen das Geheimnisvolle Artefakt im nordwestlichen Teil der Sengenden Schlucht, in den Hügeln über der Höhle.",al={"geheimnisvolles artefakt fundort","wo ist das relikt","götzendiener des twilight's hammer"}},{q="Wohin muss das Artefakt gebracht werden?",a="Bringt das Artefakt in die Schlackengrube und legt es auf den Altar von Suntara.",al={"altar von suntara standort","wo ist der altar","wohin muss das artefakt"}},{q="Warum können die Opfer keine Ruhe finden?",a="Der Archäologe sagt, die Macht der Suntara treibe die Opfer dazu an, weiterzuarbeiten, obwohl ihre Körper versagt haben.",al={"warum sie erlösen","was geschieht mit ihnen","macht der suntara"}}},fp="12,204,12.201.0,20.195.0,36.69.0,41.130.0,37.65.0,35.117.0"}
P.entries["quest:3374"] = {n="Die Essenz des Eranikus",s="Am Schwurstein erreicht Euch Itharius durch den Stein und bittet Euch, Eranikus' verderbte Seele zu erlösen. Das erste Opfer ist der Edelstein, der den freien Teil von Eranikus' Geist in Ketten hält. Itharius wartet in den Sümpfen des Elends.",h="Am Schwurstein erreicht Euch Itharius durch den Stein und bittet Euch, Eranikus' verderbte Seele zu erlösen.",kw={"chained essence","eranikus","green dragonflight","itharius","schwurstein","sümpfe des elends","ysera"},sec={{t="Eine Stimme durch den Stein",b="Durch den Schwurstein bittet Euch Itharius, Yseras Drachenschwarm dabei zu helfen, Eranikus' verderbte Seele zu erlösen. Er warnt, dass Euch beiden viele Opfer abverlangt werden. Gebt ihm zuerst den Edelstein, der den noch freien Teil von Eranikus' Geist in Ketten hält. Bringt den Schwurstein und die Chained Essence of Eranikus zu Itharius in den Sümpfen des Elends. Dort entscheidet Ihr, ob Ihr dem Drachenschwarm helft."},{t="Eine Wahl getroffen",b="An einer weiteren Wegkreuzung bittet Euch Itharius, eine Wahl zu treffen. Dann sagt er, dass Eure bisherigen Entscheidungen richtig waren. Was Ihr jetzt tut, wird entscheiden, ob sie es bleiben."}},faq={{q="Wer ist Itharius?",a="Durch den Schwurstein spricht Itharius im Namen von Yseras Drachenschwarm in Euren Geist. Er wartet in den Sümpfen des Elends und sucht Eranikus' verderbte Seele zu erlösen.",al={"wer ist itharius","itharius' rolle","wer sendet die nachricht"}},{q="Was ist die Chained Essence of Eranikus?",a="Die Chained Essence of Eranikus ist der Edelstein, der den noch freien Teil von Eranikus' Geist in Ketten hält. Itharius bittet Euch, ihn als erstes Opfer herzugeben.",al={"chained essence of eranikus","was ist der angekettete edelstein","eranikus' essenz"}},{q="Was ging dieser Quest voraus?",a="Sie folgt auf den ersten Schritt der Essenz des Eranikus, der denselben Namen trägt.",al={"vorausgesetzte quest","vorheriger schritt"}},{q="Wohin bringt Ihr den Schwurstein und die Essenz?",a="Bringt den Schwurstein und die Essenz zu Itharius in den Sümpfen des Elends. Dort entscheidet Ihr, ob Ihr dem Drachenschwarm helft.",al={"wohin den schwurstein bringen","wo ist itharius","abgabeort"}}},fp="23,228,25.384.0,13.153.1,16.167.0,40.150.0,28.80.0,48.122.0"}
P.entries["quest:3376"] = {n="Tötet Spitzhauer!",s="Auf der Hochwolkenebene schickt Kriegerheldin Windfeather Euch nach Osten, um die Überfälle auf Mulgore zu beenden. Sharptusk Thornmantle führt die Stacheleber der Bristleback in der Dornrankenklamm an, und sein Tod könnte ihre Angriffe schwächen.",h="Auf der Hochwolkenebene schickt Kriegerheldin Windfeather Euch nach Osten, um die Überfälle auf Mulgore zu...",kw={"brambleblade","bristleback","mulgore","narache","stacheleber","die hochwolkenebene","sharptusk","thornmantle","windfeather"},ang={["class:Hunter"]="Als Jäger steht Ihr früh vor einer Prüfung: Beute aufzuspüren, die selbst über List und Waffen verfügt und ihrerseits Jagd auf Euch machen will.",["faction:Horde"]="Als Verbündeter der Horde helft Ihr, Mulgore zu festigen und Euren neuen Taurenbrüdern friedliches Land zu sichern, indem Ihr Häuptling Sharptusk tötet.",["race:Tauren"]="Für einen jungen Tauren ist das Töten von Sharptusk Thornmantle eine der letzten Prüfungen vor dem Verlassen von Camp Narache. Es beweist, dass Ihr bereit seid, die Stämme gegen feindselige Nachbarn zu verteidigen."},sec={{t="Eine mit Blut erkämpfte Heimat",b="Junge Tauren lernen auf der Hochwolkenebene zu jagen und den Wegen der Erdenmutter zu folgen. Östlich der Ebene halten die Stacheleber der Bristleback die Dornrankenklamm besetzt. Sie betrachten die Tauren als Eindringlinge auf heiligem Boden, und ihre Scharmützel bedrohen die Stämme, die versuchen, in Mulgore eine Heimat zu finden."},{t="Die Bedrohung durch Thornmantle",b="Häuptling Sharptusk Thornmantle befehligt die Angriffe der Bristleback auf die Hochwolkenebene. Von einem befestigten, behelfsmäßigen Dorf tief in der Dornrankenklamm aus lenkt er Krieger und Geomanten gegen die Shu'halo. Kriegerheldin Windfeather weiß, dass die Überfälle weitergehen werden, solange Sharptusk lebt. Sie schickt Euch in die Klamm, um ihn zu töten und seinen abgetrennten Kopf als Beweis zurückzubringen."},{t="Die Lehren der Jagd",b="Kriegerheldin Windfeather lehrt, dass die Jagd auf einen Feind, der selbst Jagd auf Euch macht, mehr als Geschick auf die Probe stellt. Für junge Tauren und ihre Verbündeten erfordert die Jagd auf Sharptusk Mut, Aufmerksamkeit und Disziplin. Sein Tod bringt gefallenen Angehörigen Gerechtigkeit und zeigt, dass ein Jäger bereit ist, durch die weiten Ebenen Mulg ores zu ziehen."}},faq={{q="Wer ist Häuptling Sharptusk Thornmantle?",a="Häuptling Sharptusk Thornmantle führt die Stacheleber der Bristleback in der Dornrankenklamm an. Sein Stamm führt Überfälle und Scharmützel gegen die Taurensiedlung auf der Hochwolkenebene.",al={"wer ist sharptusk","sharptusk thornmantle hintergrundgeschichte","wer ist der stacheleberhäuptling"}},{q="Wo ist Häuptling Sharptusk Thornmantle zu finden?",a="Sharptusk Thornmantle lebt tief in der Dornrankenklamm, östlich der Hochwolkenebene. Er lenkt seinen Stamm von einem behelfsmäßigen Dorf in der dornenbewachsenen Schlucht aus.",al={"wo ist sharptusk","sharptusk aufenthaltsort","sharptusk finden"}},{q="Wer vergibt die Quest „Tötet Spitzhauer!“?",a="Kriegerheldin Windfeather schickt Euch auf die Jagd nach Sharptusk. Die erfahrene Taurenkriegerin bewacht Camp Narache auf der Hochwolkenebene und beauftragt Neuankömmlinge, sich gegen die Bedrohung durch die Bristleback zu beweisen.",al={"questgeber tötet spitzhauer","wer vergibt tötet spitzhauer","kriegerheldin windfeather aufenthaltsort"}},{q="Warum hassen die Stacheleber der Bristleback die Tauren?",a="Die Stacheleber der Bristleback verehren ihren Halbgott Agamaggan und verteidigen die Gebiete, die sie beanspruchen. Sie betrachten Taurensiedlungen in Mulgore als Eindringen in ihre angestammten Jagdgründe.",al={"warum greifen stacheleber an","konflikt zwischen tauren und stachelebern","warum sind stacheleber feindselig"}},{q="Welchen Beweis verlangt Kriegerheldin Windfeather?",a="Kriegerheldin Windfeather verlangt den abgetrennten Kopf von Sharptusk Thornmantle. Er beweist, dass der Häuptling gefallen ist, und warnt die übrigen Bristleback.",al={"was zu windfeather bringen","sharptusk beweis","questziel sharptusk"}},{q="Welche kulturelle Bedeutung hat diese Jagd für junge Tauren?",a="Reife bedeutet für Tauren, das Gleichgewicht zwischen Jäger und Gejagtem zu verstehen. Windfeather lehrt, dass die Begegnung mit einem gerissenen Feind wie Sharptusk jungen Kriegern den Preis tödlicher Kämpfe und die Pflicht zur Verteidigung ihres Stammes zeigt.",al={"warum sharptusk töten hintergrundgeschichte","tauren übergangsritus sharptusk","bedeutung der jagd"}}},fx={d0ec7fec={q="Warum möchte Kriegerheldin Windfeather, dass Häuptling Sharptusk getötet wird?",a="Die Borstennackenstacheleber führen einen unerbittlichen Feldzug gegen die Tauren der Hochwolkenebene und bedrohen die Sicherheit ihres neu erbauten Zuhauses. Häuptling Sharptusk Dornmantel leitet diese Überfälle aus der nahegelegenen Dornrankenklamm. Kriegerheldin Windfeather versucht, einen entscheidenden Schlag gegen ihre Führung zu führen, um das Blutvergießen zu stoppen und jedem, der die Anwesenheit der Tauren auf der Ebene in Frage stellen würde, eine feste Warnung zu übermitteln.",al={"windfeather motiv","warum sharptusk töten","warum sharptusk brechen"}},["8bbc47fc"]={q="Warum beauftragt Euch Kriegerheldin Windfeather, anstatt sich selbst um Sharptusk zu kümmern?",a="Andere erfahrene Verteidiger haben bereits versucht, den Stacheleberhäuptling zu vertreiben, sind aber gescheitert, während die verbleibenden Krieger zurückbleiben müssen, um Camp Narache zu bewachen und die Jungen vor umherstreifenden Bedrohungen zu schützen. Da sie von Eurem wachsenden Potenzial als aufstrebender Jäger gehört hat, sieht Windfeather in Euch ein ungetestetes, aber beeindruckendes Talent, das in der Lage ist, einen gerissenen Gegner zu besiegen und die wahre Bedeutung der Jagd zu lernen.",al={"warum werde ich geschickt","warum nicht die krieger","warum nicht kriegerheldin windfeather"}}},fp="16,197,19.275.0,25.356.0,23.301.0,35.162.0,47.159.0,37.190.0,48.175.0,41.132.0,64.223.0"}
P.entries["quest:3377"] = {n="Gebet an Elune",s="In der Sengenden Schlucht wartet Zamael Lunthistle in einem Käfig und bittet Euch um Hilfe. Viele Jahre sind vergangen, seit ihn jemand besucht hat, und zunächst bittet er Euch, seine Geschichte anzuhören.",h="In der Sengenden Schlucht wartet Zamael Lunthistle in einem Käfig und bittet Euch um Hilfe.",kw={"dunkelküste","elune","lunthistle","gebet","reue","sengende schlucht","tafel","twilight's hammer","zamael"},sec={{t="Ein Geist im Käfig",b="Zamael Lunthistle begrüßt Euch mit einem Lobpreis auf Elune. Viele Jahre sind vergangen, seit ihn jemand besucht hat. Nun bittet er Euch um Hilfe. Hört zunächst seine Geschichte an."},{t="Zamaels Geschichte",b="Als junger Nachtelf von der Dunkelküste geriet Zamael unter den Einfluss von Twilight's Hammer und wandte sich von Elune ab. Dann riss ihn eine Vision von Elune aus seiner Lethargie als Anhänger der Alten Götter. Voller Reue ritzte er seinen Kummer als Gebet an Elune in eine Tafel aus reinem Gold.\n\nTwilight's Hammer fand die Tafel und brandmarkte ihn als Blasphemiker. Sie ließen ihn hinrichten, bevor sein Gebet vollendet war. Nun ist Zamaels Geist an die Welt gebunden und wird als Warnung für alle, die den Glauben von Twilight's Hammer verraten würden, in einem Käfig festgehalten. Er hat sein Schicksal akzeptiert, doch das Gebet muss noch gefunden werden."}},faq={{q="Wer ist Zamael Lunthistle?",a="Zamael Lunthistle ist ein Geist, der in der Sengenden Schlucht in einem Käfig gefangen gehalten wird. Er bittet Euch, seine Geschichte anzuhören.",al={"wer ist zamael","zamael lunthistle geschichte","wer ist der geist im käfig"}},{q="Worum bittet Zamael Euch?",a="Zamael bittet Euch um Hilfe. Zunächst bittet er Euch, seine Geschichte anzuhören.",al={"was will zamael","zamaels bitte"}},{q="Was folgt, nachdem Ihr Zamaels Geschichte angehört habt?",a="Nachdem Ihr Zamaels Geschichte angehört habt, könnt Ihr ihren zweiten Teil von ihm hören.",al={"nächster schritt gebet an elune","gebet an elune questreihe"}}},fp="15,164,18.154.0,13.595.1,25.92.0,28.63.0,39.67.0"}
P.entries["quest:3378"] = {n="Gebet an Elune",s="Auf Zamael Lunthistles Bitte sucht Ihr ein Gebet an Elune, das unter den Götzenanbetern verloren ging. Es ist auf einer goldenen Tafel eingraviert und für Astarii Starseeker in Darnassus bestimmt.",h="Auf Zamael Lunthistles Bitte sucht Ihr ein Gebet an Elune, das unter den Götzenanbetern verloren ging.",kw={"astarii starseeker","darnassus","goldene tafel","gebet an elune","sengende schlucht","tempel des mondes","zamael lunthistle"},sec={{t="Das verlorene Gebet",b="Zamael Lunthistles Glaube ist wieder erwacht. Doch er sagt, das bedeute wenig nach all dem Leid, das er der Welt und ihren Bewohnern zugefügt hat. Er erwartet keine Absolution. Er bittet nur darum, dass sein Gebet erhört wird, also sucht Ihr die goldene Tafel bei den Götzenanbetern und bringt sie zu Astarii Starseeker in Darnassus."},{t="Im Tempel des Mondes",b="Im Tempel des Mondes sagt Euch Astarii Starseeker, dass Elune an diesem Abend auf Euch herablächelt. Durch Eure Hand ist eine verlorene Seele zu ihr zurückgekehrt. Astarii dankt Euch."}},faq={{q="Wer ist Zamael Lunthistle?",a="Zamael Lunthistle bittet Euch, sein Gebet an Elune zu finden. Sein Glaube ist zurückgekehrt, obwohl er der Welt durch unzählige Taten Schaden zugefügt hat.",al={"zamael lunthistle hintergrundgeschichte","wer gibt gebet an elune","zamael"}},{q="Worauf ist das Gebet eingraviert?",a="Zamaels Gebet ist auf einer goldenen Tafel eingraviert. Er glaubt, dass einer der Götzenanbeter sie bei sich trägt.",al={"gebet an elune gegenstand","goldene tafel","was ist das gebet"}},{q="Wem soll das Gebet überbracht werden?",a="Bringt das Gebet zu Astarii Starseeker im Tempel des Mondes in Darnassus.",al={"wer erhält gebet an elune","astarii starseeker","wohin das gebet bringen"}},{q="Erwartet Zamael Vergebung für seine Vergangenheit?",a="Nein. Zamael erwartet keine Absolution für seine Vergangenheit, bittet aber darum, dass sein Gebet erhört wird.",al={"will zamael vergebung","zamael absolution"}}},fp="15,169,15.303.0,25.169.1,25.140.0,32.99.0,39.78.0,44.81.0"}
P.entries["quest:338"] = {n="Die Grünen Hügel des Schlingendorntals",s="Im ganzen Schlingendorntal liegen lose Seiten aus Hemet Nesingwarys Roman im Dschungel verstreut. Barnil Stonepot bittet Euch, sie zu vier Kapiteln zusammenzufügen und zurückzubringen.",h="Im ganzen Schlingendorntal liegen lose Seiten aus Hemet Nesingwarys Roman im Dschungel verstreut.",kw={"barnil stonepot","kapitel","die grünen hügel des schlingendorntals","hemet nesingwary","manuskript","seiten","schlingendorntal"},sec={{t="Ein verstreutes Manuskript",b="Im Expeditionslager ist Barnil Stonepot nach Welcome to the Jungle beunruhigt. Während er Hemet Nesingwarys Entwurf Korrektur las, riss ein Sturm die losen Seiten fort und schleuderte sie in die Wildnis. Barnil konnte viele bergen, doch andere liegen noch immer im Dickicht verloren. Er braucht Euch, um sie zu finden und Chapter I, Chapter II, Chapter III und Chapter IV zusammenzustellen, bevor Nesingwary erfährt, was geschehen ist."},{t="Die Erzählung des Jägers bewahren",b="Sobald Ihr alle vier Kapitel zurückbringt, kann Barnil eine unangenehme Konfrontation mit Nesingwary vermeiden. Er hofft, dass das wiederhergestellte Manuskript bald Bibliotheken auf der ganzen Welt erreicht."}},faq={{q="Wer schrieb Die Grünen Hügel des Schlingendorntals?",a="Hemet Nesingwary, der Leiter der Expedition, schrieb den Roman und vertraute Barnil Stonepot den Entwurf zum Korrekturlesen an.",al={"autor der grünen hügel des schlingendorntals","wer schrieb das buch","nesingwarys buch"}},{q="Wie gingen die Seiten verloren?",a="Ein heftiger Windstoß fegte durch das Jagdlager, während Barnil das Manuskript durchging, und verstreute lose Seiten im ganzen Dschungel.",al={"warum sind die seiten verstreut","was geschah mit den seiten","wie wurden die seiten fortgeweht"}},{q="Was wird benötigt, um das Manuskript zu vervollständigen?",a="Sammelt die verstreuten Seiten, stellt Chapter I, Chapter II, Chapter III und Chapter IV zusammen und bringt dann alle vier Kapitel zu Barnil.",al={"welche kapitel werden benötigt","wie die grünen hügel abschließen","anforderungen für das manuskript"}},{q="Woher stammt dieser Auftrag?",a="Barnil bietet Euch diese Arbeit im Expeditionslager im Schlingendorntal an, nachdem Ihr Welcome to the Jungle abgeschlossen habt.",al={"voraussetzung für die grünen hügel","quest vor den grünen hügeln","wie ist diese quest erhältlich"}},{q="Was hat Barnil mit dem wiederhergestellten Roman vor?",a="Barnil hofft, dass das wiederhergestellte Manuskript Bibliotheken auf der ganzen Welt erreicht. Seine Rückgabe wird ihm auch Nesingwarys Zorn ersparen.",al={"warum die seiten sammeln","was geschieht mit dem buch","wohin kommt das buch"}}},fp="32,178,22.377.0,28.173.0,43.120.0,24.125.0,40.127.0,36.110.0,54.126.0"}
P.entries["quest:339"] = {n="Kapitel I",s="Im Schlingendorntal durchsucht Barnil Stonepot den Dschungel nach vier verlorenen Seiten von Hemet Nesingwarys Jagdmanuskript.",h="Im Schlingendorntal durchsucht Barnil Stonepot den Dschungel nach vier verlorenen Seiten von Hemet...",kw={"barnil stonepot","kapitel i","die grünen hügel des schlingendorntals","hemet nesingwary","schlingendorntal"},sec={{t="Die fehlende Einleitung",b="Barnil Stonepot möchte die einleitende Passage der Grünen Hügel des Schlingendorntals wiederherstellen. Er sagt, sie bereitet die Bühne für die weitere Geschichte und beschreibt Hemet Nesingwarys Jagdgesellschaft, einschließlich Barnil selbst. Die Seiten eins, vier, sechs und acht sind im Dschungel verschollen."},{t="Den ersten Abschnitt binden",b="Wenn Ihr die vier fehlenden Blätter zurückbringt, setzt Barnil den ersten Abschnitt von Hemet Nesingwarys Text wieder zusammen."}},faq={{q="Wer bittet um diese Seiten?",a="Barnil Stonepot, Hemet Nesingwarys Gefährte in ihrem Lager im Schlingendorntal, braucht die Seiten, um die verstreuten Jagderinnerungen zusammenzufügen.",al={"wer vergibt kapitel eins","barnil stonepot","questgeber"}},{q="Welche Seiten werden für diesen Teil des Manuskripts benötigt?",a="Barnil braucht die Seiten eins, vier, sechs und acht, um den einleitenden Abschnitt des Manuskripts wieder zusammenzusetzen.",al={"welche seiten werden benötigt","fehlende seiten","welche seiten"}},{q="Was wird in diesem Teil des Manuskripts beschrieben?",a="Barnil sagt, der einleitende Abschnitt schildert den Hintergrund der Geschichte und stellt Hemet Nesingwarys Jagdgefährten vor, einschließlich Barnil selbst.",al={"worum geht es in kapitel eins","inhalt des manuskripts"}},{q="Was führte zu diesem Schritt?",a="Barnil erzählte Euch erstmals von den fehlenden Seiten, als er daran arbeitete, die Grünen Hügel des Schlingendorntals wiederherzustellen.",al={"voraussetzung","vorherige quest"}}},fp="9,115,24.266.0,25.114.0,30.141.0,55.92.0,49.139.0,25.104.0"}
P.entries["quest:34"] = {n="Ein ungebetener Gast",s="In Seenhain bittet Martie Jainrose Euch, Bellygrub ein für alle Mal aufzuhalten. Das Wildschwein hat ihren Garten verwüstet und ihre Narzissen zertrampelt, und sie bietet ein Kopfgeld für seinen Stoßzahn.",h="In Seenhain bittet Martie Jainrose Euch, Bellygrub ein für alle Mal aufzuhalten.",kw={"ein ungebetener gast","bellygrub","wildschwein","narzissen","seenhain","marschall marris","martie jainrose","rotkammgebirge"},ang={["class:Hunter"]="Als Jäger könnt Ihr Bellygrub, die namentlich bekannte Bestie, die südwestlich von Seenhain umherstreift, durch das Rotkammgebirge verfolgen.",["faction:Alliance"]="Als Reisender der Allianz bringt Ihr Seenhain Erleichterung und Ordnung, indem Ihr Martie Jainrose helft, während die Bewohner im Rotkammgebirge bereits größeren Bedrohungen gegenüberstehen.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, mit welcher Sorgfalt Martie Jainrose ihr Blumenbeet gepflegt hat. Bellygrubs Wüten hat ihre Narzissen für diese Saison ruiniert und die Pflanzen in den Gärten der Stadt beschädigt."},sec={{t="Ärger im Garten",b="Martie Jainrose lebt in Seenhain, einer Stadt am See unter den aufziehenden Schatten über dem Rotkammgebirge. Ein Wildschwein dringt immer wieder in ihren Garten ein und stört den Frieden ihres Heims. Bellygrub hat ihre Narzissen für diese Saison unwiederbringlich zertrampelt. Nun bittet Martie Reisende, dem Wüten des Tieres ein Ende zu setzen."},{t="Die Bedrohung durch Bellygrub",b="Marschall Marris, der Seenhains Stadtwache anführt, gab dem Wildschwein seinen Namen: Bellygrub. Die meiste Zeit wühlt er auf den Feldern südwestlich der Stadt nach Nahrung. Sein Hunger und seine Dreistigkeit treiben ihn nahe an die Häuser, wo er Marties Blumenbeete verwüstet hat. Wegen dieser Schäden will sie ihn loswerden."}},faq={{q="Wer vergibt die Quest „Ein ungebetener Gast“?",a="Martie Jainrose bittet in Seenhain um Hilfe, der Stadt am See im Rotkammgebirge. Ihr Garten wurde wiederholt verwüstet, und sie will das verantwortliche Wildschwein zur Strecke bringen lassen.",al={"wer vergibt ein ungebetener gast","wo gibt es ein ungebetener gast","martie jainrose quest"}},{q="Wer oder was ist Bellygrub?",a="Bellygrub ist ein aggressives Wildschwein, das die Gegend um Seenhain terrorisiert. Marschall Marris, der Anführer der Stadtwache, gab ihm diesen Namen.",al={"wer ist bellygrub","was ist bellygrub","warum heißt bellygrub so"}},{q="Wo ist Bellygrub zu finden?",a="Bellygrub sucht gewöhnlich auf den offenen Feldern südwestlich von Seenhain nach Nahrung. Oft streift er näher an die Stadt heran und in die Gärten der Bewohner.",al={"bellygrub fundort","wo ist bellygrub","bellygrub finden","wo erscheint bellygrub"}},{q="Warum will Martie Jainrose Bellygrub töten lassen?",a="Bellygrub hat Martie Jainroses Garten wiederholt zertrampelt und ihre Narzissen für diese Saison ruiniert. Sie will ihn töten lassen, damit er keinen weiteren Schaden anrichtet.",al={"warum will martie bellygrub tot sehen","warum bellygrub töten","was hat bellygrub getan"}},{q="Welcher Beweis wird benötigt, um die Quest abzuschließen?",a="Martie Jainrose bittet Euch, ihr Bellygrubs Stoßzahn als Beweis dafür zu bringen, dass das Wildschwein erledigt ist. Sie wird Euch dafür belohnen.",al={"bellygrub beweis","ein ungebetener gast abgeben","was martie jainrose bringen"}},{q="Wer ist Marschall Marris und welche Verbindung hat er zu der Bestie?",a="Marschall Marris führt Seenhains Stadtwache an. Er gab dem Wildschwein den Namen Bellygrub, während Martie Jainrose Rache für ihre verwüsteten Narzissen sucht.",al={"wer ist marschall marris","marschall marris bellygrub"}}},fp="18,165,21.315.0,23.287.0,39.177.0,25.136.0,29.129.0,47.136.0,43.126.0,62.137.0"}
P.entries["quest:340"] = {n="Kapitel II",s="Im Schlingendorntal sucht Barnil Stonepot nach fehlenden Blättern aus Hemet Nesingwarys Manuskript. Die meisten hat er selbst zusammengetragen, doch Reisende müssen helfen, den Rest zu finden.",h="Im Schlingendorntal sucht Barnil Stonepot nach fehlenden Blättern aus Hemet Nesingwarys Manuskript.",kw={"barnil stonepot","kapitel ii","die grünen hügel des schlingendorntals","nesingwary","seiten","panther","schlingendorntal","tiger"},sec={{t="Jagd auf Dschungelkatzen",b="Barnil Stonepot hat im ganzen Schlingendorntal viele Blätter aus Hemet Nesingwarys verstreutem Manuskript wiedergefunden. Das zweite Kapitel folgt Panthern und Tigern durch die Wildnis. Die Seiten zehn, elf, vierzehn und sechzehn fehlen noch, weshalb diese Jagdberichte unvollständig sind."}},faq={{q="Wer bittet um diese Manuskriptseiten?",a="Barnil Stonepot, der die Nesingwary-Expedition im Schlingendorntal unterstützt, bittet um die fehlenden Blätter.",al={"wer vergibt kapitel zwei","questgeber kapitel ii","barnil stonepot"}},{q="Welche Seiten werden für das zweite Kapitel benötigt?",a="Barnil benötigt die Seiten zehn, elf, vierzehn und sechzehn für das zweite Kapitel.",al={"welche seiten werden benötigt","seiten für kapitel zwei","kapitel ii seiten"}},{q="Welche Geschichten sind im zweiten Kapitel festgehalten?",a="Das zweite Kapitel erzählt vom Aufspüren und Jagen der Panther und Tiger, die durch das Schlingendorntal streifen.",al={"worum geht es in kapitel zwei","kapitel ii hintergrundgeschichte","grüne hügel kapitel zwei inhalt"}},{q="Was geht dieser Bitte voraus?",a="Barnils Bitte folgt auf seinen ersten Aufruf, bei der Suche nach Hemet Nesingwarys verstreutem Manuskript „Die Grünen Hügel des Schlingendorntals“ zu helfen.",al={"vorherige quest","voraussetzung kapitel zwei","grüne hügel questreihe"}}},fp="10,175,24.283.0,41.104.0,46.77.0,48.103.0,31.134.0"}
P.entries["quest:341"] = {n="Kapitel III",s="Barnil Stonepot sucht im Schlingendorntal nach den fehlenden Blättern von Hemet Nesingwarys Jagdmanuskript. Das dritte Kapitel erzählt vom ersten Abschuss mit einer Zwergenflinte durch Sir Erlgadin und Lady Rouack.",h="Barnil Stonepot sucht im Schlingendorntal nach den fehlenden Blättern von Hemet Nesingwarys Jagdmanuskript.",kw={"barnil stonepot","kapitel iii","erlgadin","die grünen hügel des schlingendorntals","hemet nesingwary","seite 18","seite 20","seite 21","seite 24","rouack","schlingendorntal"},sec={{t="Eine Jagd in Worten",b="Barnil Stonepot mag diesen Teil der Grünen Hügel des Schlingendorntals besonders. Er folgt Sir Erlgadin und Lady Rouack bei ihren frühen Heldentaten, darunter ihrem ersten Abschuss mit einer Zwergenflinte. Dann bricht die Erzählung jäh mit einem Cliffhanger ab."},{t="Fehlende Blätter",b="Barnil braucht vier Blätter, um die Geschichte wiederherzustellen: die Seiten achtzehn, zwanzig, einundzwanzig und vierundzwanzig. Sie wurden mit dem Rest des Manuskripts fortgetragen und über das Schlingendorntal verstreut."}},faq={{q="Wer sucht nach Kapitel III?",a="Barnil Stonepot sucht nach Kapitel III. Er las Hemet Nesingwarys Manuskript im Expeditionslager im nördlichen Schlingendorntal Korrektur und versucht nun, die fehlenden Seiten wieder zusammenzutragen.",al={"wer vergibt kapitel 3","kapitel 3 questgeber","barnil stonepot kapitel iii"}},{q="Was geschieht in Kapitel III des Buches?",a="Kapitel III schildert den ersten Abschuss mit einer Zwergenflinte durch Sir Erlgadin und Lady Rouack. Die Erzählung endet mit einem ungelösten Cliffhanger.",al={"worum geht es in kapitel 3","kapitel iii geschichte","erlgadin und rouack"}},{q="Welche Seiten werden benötigt, um Kapitel III zu vervollständigen?",a="Barnil braucht die Seiten achtzehn, zwanzig, einundzwanzig und vierundzwanzig, um Kapitel III zusammenzusetzen.",al={"welche seiten kapitel 3","kapitel iii benötigte seiten","seiten für kapitel 3"}},{q="Was ging dieser Quest voraus?",a="Diese Quest folgt auf die Grünen Hügel des Schlingendorntals, als Barnil erstmals erklärte, wie Hemet Nesingwarys Manuskript verloren ging.",al={"kapitel 3 voraussetzung","was führt zu kapitel iii"}}},fp="11,199,15.232.0,14.194.0,31.194.0,40.128.0,45.89.0,28.118.0"}
P.entries["quest:342"] = {n="Kapitel IV",s="Barnil Stonepot sucht in Kapitel IV nach dem Ende von Hemet Nesingwarys Jagderzählung. Drei Seiten sind im Dschungel verschollen.",h="Barnil Stonepot sucht in Kapitel IV nach dem Ende von Hemet Nesingwarys Jagderzählung.",kw={"barnil stonepot","kapitel 4","kapitel iv","die grünen hügel des schlingendorntals","hemet nesingwary","seite 25","seite 26","seite 27","schlingendorntal"},sec={{t="Das große Finale",b="Barnil Stonepot nennt das vierte Kapitel Hemet Nesingwarys großes Finale. Er braucht Euch, um die Seiten fünfundzwanzig, sechsundzwanzig und siebenundzwanzig zu finden. Die drei Blätter liegen im Dschungel verstreut. Ohne sie kann er den Schluss der Erzählung nicht wiederherstellen."}},faq={{q="Wer möchte Kapitel IV wiederherstellen lassen?",a="Barnil Stonepot möchte, dass Ihr die verstreuten Seiten sammelt, damit er das Ende von Hemet Nesingwarys Jagdbuch zusammensetzen kann.",al={"wer vergibt kapitel iv","kapitel iv questgeber","wer braucht kapitel 4"}},{q="Welche Seiten werden benötigt, um Kapitel IV zu vervollständigen?",a="Ihr braucht die Seiten fünfundzwanzig, sechsundzwanzig und siebenundzwanzig der Grünen Hügel des Schlingendorntals, um das vierte Kapitel zu vervollständigen.",al={"kapitel 4 seiten","welche seiten für kapitel iv","welche seiten werden benötigt"}},{q="Was geht dieser Bitte voraus?",a="Barnil Stonepot bat zunächst um die verstreuten Blätter der Grünen Hügel des Schlingendorntals. Jetzt sucht er die Seiten, die den Schluss wiederherstellen.",al={"kapitel iv voraussetzungen","kapitel 4 vorherige quest"}}},fp="10,134,16.248.0,30.127.0,46.122.0,31.137.0"}
P.entries["quest:343"] = {n="Reden über Kraft",s="Bruder Kristoff hat Chefbibliothekar Milton Garbenbund beauftragt, in der Royal Library nach einem bestimmten Band zu suchen.",h="Bruder Kristoff hat Chefbibliothekar Milton Garbenbund beauftragt, in der Royal Library nach einem bestimmten...",kw={"bruder kristoff","kathedrale des lichts","metallurgie","milton garbenbund","royal library","reden über kraft","burg sturmwind","die belastungen des eisens"},ang={["class:Priest"]="Als Priester könnt Ihr sehen, wie Sturmwinds Geistliche neben der Hingabe an das Licht auch alltägliches Handwerk heranziehen, um Seelenstärke zu vermitteln.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr sehen, wie die Priesterschaft des Kathedralenplatzes mit der Royal Library in Burg Sturmwind verbunden ist, einem Teil des städtischen und gelehrten Lebens der Hauptstadt.",["profession:Blacksmithing"]="Als Schmied kennt Ihr die Härten der Schmiede. Bruder Kristoff möchte „Die Belastungen des Eisens“ nutzen, um Standhaftigkeit unter Druck zu erklären."},sec={{t="Eine Metapher aus Metall",b="Bruder Kristoff bereitet eine Predigt über die Seelenstärke vor. Um seiner Gemeinde geistige Stärke anschaulich zu machen, zieht er neben der Heiligen Schrift auch die Metallbearbeitung heran. Er hofft, eine Abhandlung darüber, wie Eisen Druck standhält, als Beispiel nutzen zu können."},{t="Die königlichen Bücherregale",b="Chefbibliothekar Milton Garbenbund kennt das Archiv der Royal Library auswendig. Dennoch muss er prüfen, ob es genau den Titel enthält, den Kristoff sucht. Geschichtswerke, Schriften zum Gemeinwesen und Handwerksliteratur aus Jahrhunderten bieten ihm reichlich Stoff zum Durchsuchen."}},faq={{q="Wer ist Bruder Kristoff?",a="Bruder Kristoff ist ein Priester im Dienst der Kirche des Heiligen Lichts auf dem Kathedralenplatz in Sturmwind. Er bittet Besucher oft, Materialien und Quellen für seine Lehren und Predigten zu beschaffen.",al={"kristoff","wer vergibt reden über kraft","bruder kristoff"}},{q="Welches Buch sucht Bruder Kristoff?",a="Bruder Kristoff sucht „Die Belastungen des Eisens“, einen Fachtext über Metallbearbeitung. Er möchte daraus zitieren, um geistiges Durchhaltevermögen zu veranschaulichen.",al={"welches buch","die belastungen des eisens","kristoffs buch"}},{q="Wer ist Milton Garbenbund?",a="Milton Garbenbund ist Chefbibliothekar der Royal Library in Burg Sturmwind. Er verwaltet die Bücher, Schriftrollen und Verwaltungsakten des Königreichs und kennt die Sammlung gut.",al={"milton garbenbund","bibliothekar sturmwind","chefbibliothekar"}},{q="Wo befindet sich die Royal Library?",a="Die Royal Library liegt im nordöstlichen Flügel von Burg Sturmwind. Ihr erreicht sie durch die Haupthalle des königlichen Palasts.",al={"standort bibliothek sturmwind","wo ist die royal library","bibliothek burg sturmwind"}},{q="Warum braucht ein Priester ein Buch über Metallurgie?",a="Bruder Kristoff bereitet eine Predigt mit dem Titel „Seelenstärke“ vor. Er möchte die Belastung des Eisens beim Schmieden damit vergleichen, wie Prüfungen den menschlichen Geist stärken.",al={"warum metallurgie","warum ein buch über eisen","predigt über seelenstärke"}},{q="Hat Milton Garbenbund das Buch sofort zur Hand?",a="Milton Garbenbund sagt, die Bibliothek besitze Bücher über Metallbearbeitung, doch er müsse nach dem genauen Titel sehen und eine Suche nach Kristoffs Buch veranlassen.",al={"hat garbenbund das buch","reden über kraft abgeben"}}},fp="21,102,19.253.0,16.228.0,24.189.0,42.139.0,20.166.0,35.113.0,41.170.0,49.142.0"}
P.entries["quest:344"] = {n="Bruder Paxton",s="In Sturmwinds königlichen Archiven schickt Euch Milton Garbenbund wegen einer fehlenden zwergischen Abhandlung zur Abtei von Nordhain. Das Buch wurde vor Monaten zum Abschreiben dorthin gebracht, ist aber noch nicht in die Regale der Stadt zurückgekehrt.",h="In Sturmwinds königlichen Archiven schickt Euch Milton Garbenbund wegen einer fehlenden zwergischen...",kw={"bruder paxton","margulf blaggon","milton garbenbund","abtei von nordhain","bibliothek von sturmwind","die belastbarkeit des eisens","abschrift"},ang={["class:Priest"]="In der Abtei von Nordhain könnt Ihr die Gelehrtenarbeit der Kleriker sehen. Sie schreiben Bücher von Hand ab, um Wissen für den Orden zu bewahren.",["faction:Alliance"]="Ihr könnt die Verbindungen zwischen Sturmwind und Eisenschmiede daran erkennen, dass Bibliotheken der Menschen grundlegende zwergische Schriften studieren und bewahren.",["profession:Mining"]="Margulf Blaggons „Die Belastbarkeit des Eisens“ bewahrt Jahrzehnte zwergischen Bergbauwissens aus den Bergen von Khaz Modan.",["race:Dwarf"]="Das gesuchte Buch ist ein Werk zwergischer Handwerkskunst des Bergmannskollegen Margulf Blaggon. Sturmwinds Schreiber schätzen es so sehr, dass sie sich um Abschriften bemühen."},sec={{t="Ein geliehener Band",b="Sturmwinds Oberbibliothekar Milton Garbenbund sucht ein Buch, das in den Regalen der Hauptstadt fehlt. „Die Belastbarkeit des Eisens“, eine Abhandlung über metallurgische Verfahren des zwergischen Prospektors Margulf Blaggon, wurde vor Monaten den Klerikern der Abtei von Nordhain zum Abschreiben geliehen. Es wurde nicht in Sturmwind verlegt."},{t="Nordhains Schreiber",b="In der Abtei von Nordhain kümmert sich Bruder Paxton um die Bibliothek und ihre Bücher. Der Heilige Orden der Kleriker von Nordhain schätzt Wissen, doch ein langes Fachmanuskript von Hand abzuschreiben braucht Zeit. Paxton gibt zu, dass er Blaggons Werk noch nicht vollständig abgeschrieben hat. Deshalb ist das Original noch nicht nach Sturmwind zurückgekehrt."}},faq={{q="Warum schickt Euch Milton Garbenbund zur Abtei von Nordhain?",a="Vor Monaten lieh Milton Garbenbund Bruder Paxton Sturmwinds Exemplar von „Die Belastbarkeit des Eisens“, damit die Abtei eine Abschrift anfertigen konnte. Da weder eine Nachricht noch das Buch zurückgekommen ist, schickt Garbenbund Euch los, um nach dem Fortschritt der Abschrift zu fragen.",al={"warum bruder paxton","wo ist das buch","milton garbenbund botengang"}},{q="Wer ist Bruder Paxton?",a="Bruder Paxton ist ein Kleriker, der die Bibliothek der Abtei von Nordhain betreut. Er katalogisiert wertvolle Bücher und schreibt sie von Hand für die Sammlung der Abtei ab.",al={"wer ist paxton","bruder paxton hintergrundgeschichte","paxton nordhain"}},{q="Was ist „Die Belastbarkeit des Eisens“?",a="„Die Belastbarkeit des Eisens“ ist ein Fachhandbuch, das der zwergische Bergmann Margulf Blaggon vor Jahrzehnten verfasst hat. Es hält sein Wissen über den Erzabbau und metallurgische Spannungen tief in den Bergen von Khaz Modan fest.",al={"was ist die belastbarkeit des eisens","die belastbarkeit des eisens buch","margulf blaggon buch"}},{q="Warum hat Paxton das Buch noch nicht zurückgegeben?",a="Bruder Paxton schreibt das Manuskript noch immer von Hand für die Regale der Abtei ab. Das umfangreiche Werk erfordert Zeit und Material, und er gibt das Original nur ungern ab, bevor er fertig ist.",al={"warum überfällig","warum braucht paxton so lange","paxton verzögerung"}},{q="Wo ist Bruder Paxton zu finden?",a="Bruder Paxton lebt in der Abtei von Nordhain, dem Sitz des Heiligen Ordens der Kleriker von Nordhain, im Nordhaintal im nördlichen Wald von Elwynn.",al={"paxton aufenthaltsort","wo ist bruder paxton"}},{q="Was geschieht, nachdem Ihr Bruder Paxton zur Rede gestellt habt?",a="Paxton gibt zu, dass er das Buch hat, und sagt, er brauche mehr Schreibmaterial, um die Abschrift fertigzustellen. Er schickt Euch los, um Tintenvorräte zu beschaffen.",al={"nächste quest nach paxton","was braucht paxton"}}},fx={["4a96b020"]={q="Warum benötigt Milton Garbenbund einen Abenteurer, um Bruder Paxton zu finden?",a="Milton Garbenbund ist der oberste Bibliothekar von Sturmwind und dazu verpflichtet, die Royal Library in Burg Sturmwind zu beaufsichtigen. Er kann seinen Posten nicht einfach verlassen, um wegen eines längst überfälligen Buches ins Nordhaintal zu gehen. Als Ihr ankommt und nach 'The Stresses of Iron' fragt, bietet Ihr ihm einen praktischen Boten, der ohnehin unterwegs ist und bereit ist, Bruder Paxton aufzuspüren.",al={"warum ich brother paxton","warum braucht mich milton garbenbund","warum kann milton das buch nicht selbst holen"}}},fp="14,196,17.308.0,19.296.0,51.209.0,22.143.0,31.203.0,40.183.0,34.139.0,47.128.1"}
P.entries["quest:3441"] = {n="Göttliche Vergeltung",s="In der Sengenden Schlucht erzählt Euch Kalaran Windblade, wie sein Vater starb und warum er Rache sucht. Sturmwind wollte seine Bitte nicht anhören, also wendet er sich an einen tapferen Abenteurer.",h="In der Sengenden Schlucht erzählt Euch Kalaran Windblade, wie sein Vater starb und warum er Rache sucht.",kw={"kessel","dunkeleisen","kalaran windblade","ragnaros","vergeltung","sturmwind","rache","windblade"},sec={{t="Ein erschlagener Vater",b="Kalaran sagt, der Abschaum im Kessel habe seinen Vater getötet. Er flehte den Magistrat von Sturmwind an, doch niemand antwortete. Er sagt, Sturmwind würde lieber die Existenz dieses Teils der Welt leugnen, als Soldaten zu entsenden, um für Gerechtigkeit zu sorgen."},{t="Ein Ruf nach Rache",b="Kalaran will Rache. Nur ein schwerfälliger Tölpel von einem Knappen steht ihm bei, während die Dunkeleisenzwerge und Ragnaros' Bestien ihn allein zerschmettern könnten. Deshalb vertraut er darauf, dass ein tapferer Abenteurer sich den Bewohnern des Kessels stellt. Jedem, der hilft, verspricht er Reichtümer jenseits aller Träume."}},faq={{q="Wer ist Kalaran Windblade?",a="Kalaran Windblade ist ein Mann in der Sengenden Schlucht, dessen Vater erschlagen wurde. Sein Knappe steht ihm bei, während er Rache sucht.",al={"wer ist kalaran","kalarans geschichte","kalarans hintergrund"}},{q="Warum sucht Kalaran Vergeltung?",a="Kalaran macht den Abschaum im Kessel für den Tod seines Vaters verantwortlich und sucht Rache.",al={"warum göttliche vergeltung","kalarans rache","was geschah mit kalarans vater"}},{q="Warum hat Sturmwind Kalaran nicht geholfen?",a="Kalaran sagt, der Magistrat von Sturmwind habe seine Bitten ignoriert. Er glaubt, Sturmwind würde lieber die Existenz dieses Teils der Welt leugnen, als Soldaten zu entsenden, um für Gerechtigkeit zu sorgen.",al={"sturmwinds weigerung","warum will sturmwind nicht helfen","magistrat von sturmwind"}},{q="Welche Bedrohungen erwähnt Kalaran?",a="Kalaran nennt die Dunkeleisenzwerge und Ragnaros' Bestien als Bedrohungen, die ihn überwältigen könnten, wenn er allein wäre.",al={"wer ist im kessel","feinde im kessel","kalarans feinde"}},{q="Was verspricht Kalaran im Gegenzug für Hilfe?",a="Kalaran verspricht einem tapferen Abenteurer, der ihm hilft, Reichtümer jenseits aller Träume.",al={"kalarans angebot","was bietet kalaran an"}}},fp="18,163,14.226.0,20.272.0,25.117.0,35.85.0,34.166.0,34.100.0,47.78.0"}
P.entries["quest:3442"] = {n="Die fehlerlose Flamme",s="In der Sengenden Schlucht bereitet Kalaran Windblade einen Schlag vor, der den größten Schaden anrichten soll. Er will die vier Wachtürme niederbrennen, damit eine Offensive beginnen kann, bevor jemand reagieren kann. Zuerst braucht er eine torch of flawless flame.",h="In der Sengenden Schlucht bereitet Kalaran Windblade einen Schlag vor, der den größten Schaden anrichten soll.",kw={"golemöl","herz der flamme","kalaran windblade","sengende schlucht","wachtürme","torch of flawless flame"},sec={{t="Die Fackel vorbereiten",b="Nach Divine Retribution legt Kalaran Windblade seinen Plan dar. Er will die vier Wachtürme niederbrennen, damit eine Offensive beginnen kann, bevor jemand Zeit zum Reagieren hat.\n\nDafür braucht er das richtige Werkzeug und die Materialien, um es herzustellen. Bringt Kalaran vier Herzen der Flamme und vier Kugeln Golemöl, und er wird die torch of flawless flame herstellen. Er verweist Euch an die Golems und Elementare dieser Lande."}},faq={{q="Wozu werden diese Materialien gesammelt?",a="Kalaran Windblade braucht vier Herzen der Flamme und vier Kugeln Golemöl, um eine Fackel herzustellen, die die vier Wachtürme in Brand setzen wird.",al={"warum flamme und öl sammeln","zweck der fehlerlosen flamme","grund für torch of flawless flame"}},{q="Wo findet Ihr die benötigten Bestandteile?",a="Kalaran verweist Euch an die Golems und Elementare der Sengenden Schlucht.",al={"wo golemöl finden","wo herz der flamme finden","fehlerlose flamme materialien fundort"}},{q="Was kommt vor diesem Schritt?",a="Dies folgt auf Divine Retribution, wo Ihr Kalaran Windblades Geschichte gehört habt.",al={"fehlerlose flamme voraussetzung","vorherige quest fehlerlose flamme"}},{q="Warum sollen die Wachtürme brennen?",a="Kalaran sagt, dass ein Schlag gegen die vier Wachtürme den größten Schaden anrichten wird. Sobald sie brennen, kann eine Offensive beginnen, bevor jemand Zeit zum Reagieren hat.",al={"warum wachtürme","plan für die wachtürme"}}},fp="18,221,19.401.0,50.134.0,42.69.0,28.74.0,27.147.0"}
P.entries["quest:3443"] = {n="Das Schmieden des Schafts",s="Nach The Flawless Flame braucht Kalaran Windblade einen Schaft, um das Feuer zu halten. Acht thoriumbeschlagene Dolche aus dem Kessel lassen sich zu einem solchen Schaft umschmieden.",h="Nach The Flawless Flame braucht Kalaran Windblade einen Schaft, um das Feuer zu halten.",kw={"kessel","sklavenhändler der dunkeleisenzwerge","zuchtmeister der dunkeleisenzwerge","makellose flamme","kalaran windblade","sengende schlucht","thoriumbeschlagener dolch"},sec={{t="Verzauberte Legierung",b="Kalaran Windblade braucht einen Schaft und eine Fassung, um die makellose Flamme zu halten. Im Kessel führen Sklavenhändler und Zuchtmeister der Dunkeleisenzwerge Waffen aus verzaubertem Thorium, einem widerstandsfähigen Metall. Kalaran kann acht ihrer Dolche zerlegen und die Legierung zu einem Schaft umschmieden."},{t="Eine scharfe Zunge",b="Wenn Ihr die Dolche bringt, erntet Ihr von Kalaran Spott statt Dank. Er nennt Euch eine außergewöhnliche Arbeitskraft und fragt dann, ob Ihr schon einmal über eine andere Berufung nachgedacht habt. Vielleicht Detektiv, Schrottsammler oder einer jener albernen Gnome, die mit metallsuchenden Apparaturen Azeroths Strände durchkämmen, auf der Jagd nach verlorenen Schätzen."}},faq={{q="Warum braucht Kalaran thoriumbeschlagene Dolche?",a="Kalaran Windblade kann die Legierung der Dolche zerlegen und zu einem Schaft umschmieden, der dabei hilft, die makellose Flamme zu halten.",al={"warum dolche","zweck thoriumbeschlagener dolche","warum thoriumdolche"}},{q="Wer trägt die benötigten Dolche?",a="Sklavenhändler und Zuchtmeister der Dunkeleisenzwerge im Kessel führen Waffen aus verzaubertem Thorium.",al={"wer lässt die dolche fallen","wo sind die dolche","wer hat thoriumdolche"}},{q="Wo gehört dieser Schritt in die Questreihe?",a="Er folgt auf The Flawless Flame, als Ihr Materialien für die Fackel der makellosen Flamme gesammelt habt.",al={"welche quest kommt vor das schmieden des schafts","position in der questreihe"}},{q="Wie viele Dolche werden benötigt?",a="Kalaran bittet Euch, acht thoriumbeschlagene Dolche zu bringen.",al={"wie viele dolche","anzahl der dolche","wie viele thoriumdolche"}}},fp="17,148,15.246.0,14.308.1,45.114.0,33.85.0,40.91.0,30.55.0"}
P.entries["quest:3444"] = {n="Der runde Stein",s="Marvon Rivetseeker wartet in Ratschet auf einen Stein mit einem Schlangensymbol. Er ist dem Versunkenen Tempel nur knapp entkommen und hofft, dass der Stein seine Erinnerungen zurückbringt.",h="Marvon Rivetseeker wartet in Ratschet auf einen Stein mit einem Schlangensymbol.",kw={"marvon rivetseeker","ratschet","schlangenstatue","versunkener tempel","tanaris","steinkreis"},sec={{t="Marvons Erinnerung",b="Marvon Rivetseeker erinnert sich an das Böse, das jeden berührte, der den Versunkenen Tempel betrat. Um zu entkommen, musste er sich durch den Schlamm kämpfen, der über die Böden verteilt war. Ein Ort blieb ihm im Gedächtnis: ein großer runder Raum voller Schlangenstatuen."},{t="Der Stein in Ratschet",b="Marvon Rivetseeker fand einen runden Stein, der offenbar dasselbe Schlangensymbol trägt. Er ließ ihn in eine Kiste packen und in seine Werkstatt in Ratschet schicken. Bringt ihn zu ihm, und vielleicht erinnert er sich an mehr."},{t="Wenn der Stein zurückkehrt",b="Marvon Rivetseeker erkennt, dass es der richtige Stein ist. Seine Erinnerungen kehren allmählich zurück."}},faq={{q="Wer ist Marvon Rivetseeker?",a="Marvon Rivetseeker bittet Euch, ihm einen Stein zu bringen. Er betrat einst den Versunkenen Tempel und entkam nur knapp.",al={"marvon rivetseeker","wer vergibt die steinkreisquest","questgeber tanaris"}},{q="Wo ist der Steinkreis?",a="Der Stein wurde in eine Kiste gepackt und in Marvon Rivetseekers Werkstatt in Ratschet geschickt.",al={"wo ist der steinkreis","steinkreis werkstatt","steinkreis fundort"}},{q="Warum will Marvon den Steinkreis?",a="Der Stein trägt ein Schlangensymbol wie die Statuen, an die sich Marvon Rivetseeker aus einem runden Raum im Versunkenen Tempel erinnert. Mit dem Stein in der Hand kann er vielleicht mehr erzählen.",al={"warum den steinkreis suchen","steinkreis zweck"}},{q="Was geschah mit Marvon im Versunkenen Tempel?",a="Marvon Rivetseeker entkam dem Versunkenen Tempel nur knapp und watete dabei durch Schlamm, der über die Böden verteilt war. Er erinnert sich, wie er durch einen großen runden Raum voller Schlangenstatuen stolperte.",al={"marvon versunkener tempel","marvon vorgeschichte"}}},fp="16,143,15.231.0,20.189.0,22.87.1,26.103.0,26.74.0,38.170.0,45.177.0"}
P.entries["quest:3445"] = {n="Der Versunkene Tempel",s="Angelas Moonbreeze weist Euch den Weg zu einem verschütteten Ort und einem vermissten Gelehrten. Tief unter der Erde liegt der Versunkene Tempel, jenseits aller Macht, die Angelas je gesehen hat. Um mehr zu erfahren, sucht Marvon Rivetseeker, der sich zuletzt in Tanaris aufgehalten haben soll.",h="Angelas Moonbreeze weist Euch den Weg zu einem verschütteten Ort und einem vermissten Gelehrten.",kw={"angelas moonbreeze","feralas","marvon rivetseeker","ratschet","versunkener tempel","tanaris","trollruinen"},sec={{t="In die Tiefe verbannt",b="Angelas Moonbreeze erzählt Euch, dass der Versunkene Tempel von Mächten tief unter die Erde getrieben wurde, die alles übertreffen, was sie je gesehen hat. Sie schickt Euch zu Marvon Rivetseeker, einem Goblin, der mit ihr und Troyas uralte Stätten erforscht.\n\nMarvon verließ sein Zuhause in Ratschet, um die Trollruinen von Tanaris zu untersuchen. Seit einiger Zeit gibt es keine Nachricht von ihm."},{t="Was Marvon erzählt",b="Marvon Rivetseeker sagt, er habe den Versunkenen Tempel mit eigenen Augen gesehen. Er hält Euch für reiselustig und bietet an, mehr zu erzählen, denn er glaubt, sein Wissen werde Euer Interesse wecken."}},faq={{q="Wer beginnt die Suche nach dem Versunkenen Tempel?",a="Angelas Moonbreeze weist Euch den Weg zum Versunkenen Tempel, der durch Mächte tief unter die Erde sank, die alles übertreffen, was sie je gesehen hat.",al={"versunkener tempel questgeber","wer vergibt den versunkenen tempel","angelas moonbreeze"}},{q="Wer ist Marvon Rivetseeker?",a="Marvon Rivetseeker ist ein Goblin, der mit Angelas und Troyas uralte Stätten auf der ganzen Welt erforscht.",al={"marvon rivetseeker","wo ist marvon rivetseeker","wer ist marvon"}},{q="Wohin ist Marvon Rivetseeker gegangen?",a="Marvon Rivetseeker verließ sein Zuhause in Ratschet, um die Trollruinen von Tanaris zu untersuchen. Seit einiger Zeit gibt es keine Nachricht von ihm.",al={"marvon aufenthaltsort","wo marvon finden","marvon tanaris"}}},fp="17,222,22.333.0,16.185.1,44.125.0,26.98.0,32.125.0"}
P.entries["quest:345"] = {n="Tinten-Zutaten",s="Bruder Paxton in der Abtei von Nordhain geht die Tinte für seine Schriften aus. Er schickt Euch nach Osten nach Seenhain, um Rethban Ore zu beschaffen.",h="Bruder Paxton in der Abtei von Nordhain geht die Tinte für seine Schriften aus.",kw={"brother paxton","großknecht oslow","tinten-zutaten","seenhain","abtei von nordhain","rotkammgebirge","rethban ore","the stresses of iron"},ang={["class:Priest"]="Als Priester könnt Ihr den Geistlichen bei gelehrten Arbeiten helfen. Brother Paxtons Besorgung folgt auf Bruder Kristoffs Predigt über Fortitude of the Spirit.",["faction:Alliance"]="Als Reisender der Allianz erlebt Ihr den Gegensatz zwischen der stillen Abgeschiedenheit der Abtei von Nordhain und der Gewalt, die Seenhain bedroht.",["profession:Mining"]="Als Bergarbeiter könnt Ihr hoch in den zerklüfteten Felsen des Rotkammgebirges nach Rethban-Eisenerz suchen."},sec={{t="Die Rezeptur eines Schreibers",b="Bruder Paxton verwendet seine besondere Tinte für wichtige Schriften, darunter The Stresses of Iron. Die Tinte trocknet schnell und ist wischfest. Doch ihre Rezeptur hat einen Makel: Steht sie zu lange, härtet sie im Tiegel aus. Um frische Tinte anzumischen, braucht Paxton rohes Rethban-Eisenerz aus dem felsigen Rotkammgebirge."},{t="Eine Stadt unter Belagerung",b="Großknecht Oslow kann keine Arbeiter für den Bergbau entbehren. Seine Arbeiter verstärken Seenhains Barrikaden, bauen zerstörte Gebäude wieder auf und verteidigen die Stadt gegen Überfälle der Schwarzfelsorcs. Also müsst Ihr Euch selbst in die gefährlichen Rethbanhöhlen wagen, um das Erz zu finden, das Paxton braucht."}},faq={{q="Warum braucht Bruder Paxton Eisenerz für Tinte?",a="Bruder Paxton braucht Rethban-Eisenerz, um seine besondere Tinte herzustellen. Gemahlenes Erz verleiht der Tinte ihre mineralischen Farbpigmente und ihre Bindeeigenschaften, sodass sie schnell trocknet und wischfest ist.",al={"warum eisen für tinte","paxton erz tinte","brother paxton tintenrezept"}},{q="Wer ist Großknecht Oslow?",a="Großknecht Oslow beaufsichtigt öffentliche Bauarbeiten und Reparaturen in Seenhain. Während Schwarzfelsorcs die Stadt bedrängen, leitet er ihren Wiederaufbau und ihre Befestigung.",al={"großknecht oslow","oslow seenhain","wer ist oslow"}},{q="Wohin schickt Euch Bruder Paxton?",a="Paxton schickt Euch vom Wald von Elwynn nach Osten nach Seenhain im Rotkammgebirge. Dort sollt Ihr Großknecht Oslow finden.",al={"tinten-zutaten ziel","wo ist oslow","wohin für tinten-zutaten"}},{q="Warum gibt Euch Großknecht Oslow nicht einfach das Erz?",a="Angriffe der Schwarzfelsorcs halten Seenhain unter Druck. Oslows Arbeiter sind damit beschäftigt, beschädigte Gebäude zu reparieren und die Stadt zu befestigen, sodass niemand für den Erzabbau übrig bleibt.",al={"warum kein erz","oslow verweigert erz","warum ist oslow wütend"}},{q="Welches Buch versucht Bruder Paxton abzuschreiben?",a="Bruder Paxton schreibt The Stresses of Iron ab. Seine Arbeit kam zum Erliegen, als seine letzte Mischung schnell trocknender Tinte in ihrem Gefäß aushärtete.",al={"paxton buch","was schreibt paxton ab","the stresses of iron"}},{q="Was geschieht nach dem Gespräch mit Großknecht Oslow?",a="Großknecht Oslow fordert Euch auf, selbst Rethban-Eisenerz in den gefährlichen Rethbanhöhlen nördlich des Immerruhsees zu sammeln.",al={"nächste quest nach tinten-zutaten","wie weiter nach oslow","folgequest tinten-zutaten"}}},fx={["3b01bf84"]={q="Warum möchte Bruder Paxton, dass Ihr Rethban Ore holt?",a="Bruder Paxton widmet sich dem Kopieren der wissenschaftlichen Abhandlung The Stresses of Iron für die Bibliothek der Abtei von Nordhain. Er besteht darauf, seine eigene Spezialtinte zu brauen, für die pulverisiertes Rethban Ore benötigt wird, um sicherzustellen, dass sie schnell trocknet und nicht verschmiert. Leider ist seine vorherige Charge vollständig eingetrocknet, bevor er mit der Transkription fertig war, wodurch sein wissenschaftliches Projekt ins Stocken geraten ist, bis frische Mineralien eintreffen.",al={"warum braucht brother paxton erz","beweggrund von brother paxton","warum tintenvorräte"}},c7dba9bc={q="Warum schickt Euch Bruder Paxton, anstatt das Erz selbst zu besorgen?",a="Bruder Paxton ist ein hingebungsvoller Kopist, der an seine Pflichten innerhalb der klösterlichen Mauern der Abtei von Nordhain gebunden ist. Eine Reise bis nach Seenhain im Rotkammgebirge geht weit über seinen friedlichen klösterlichen Alltag hinaus, zumal die Reisewege immer gefährlicher werden. Als fähiger Abenteurer, der ohnehin durch das Reich reist, könnt Ihr seine übliche Kontaktperson leicht benachrichtigen.",al={"warum kann paxton das erz nicht selbst holen","warum einen abenteurer schicken","warum ich tintenvorräte"}}},fp="12,126,18.292.0,18.271.0,46.172.0,21.151.0,35.118.0,46.166.0,47.135.0,47.118.0"}
P.entries["quest:3452"] = {n="Die Ummantelung der Flamme",s="Kalaran Windblade sucht das letzte Stück für die Fackel. Ein großes Lager von Twilight's Hammer soll in den Bergen im Nordwesten liegen, wo seine Bewohner ihren Gott mit Symbolen und Götzenbildern ehren. Er will ein Symbol von Ragnaros.",h="Kalaran Windblade sucht das letzte Stück für die Fackel.",kw={"ummantelung der flamme","kalaran windblade","sengende schlucht","symbol von ragnaros","fackel der vergeltung","twilight's hammer"},sec={{t="Ein Stück für die Ummantelung",b="Kalaran Windblade sagt, die Fackel brauche noch ein letztes Stück. Ein großes Lager von Twilight's Hammer soll in den Bergen im Nordwesten liegen, mit Symbolen und Götzenbildern zu Ehren ihres Gottes. Ihre Verzauberung könnte der Fackel eine magische Ummantelung verleihen. Kalaran bittet Euch um ein Symbol von Ragnaros und hofft, dessen Magie freizusetzen. Ohne eine geeignete Quelle arkaner Energie lässt sich die Fackel der Vergeltung nicht vollenden."},{t="Das Symbol untersucht",b="Das Symbol von Ragnaros verströmt eine üble Magie, genau die Art, die Kalaran für seine Arbeit braucht."}},faq={{q="Was wird benötigt, um die Ummantelung der Flamme zu erschaffen?",a="Kalaran Windblade bittet Euch um ein Symbol von Ragnaros und hofft, dessen Magie für die Ummantelung freizusetzen.",al={"ummantelung der flamme gegenstand","was braucht kalaran","benötigtes symbol"}},{q="Wo liegt das Lager von Twilight's Hammer?",a="Ein großes Lager von Twilight's Hammer soll in den Bergen im Nordwesten liegen.",al={"twilight's hammer standort","wo liegt das kultlager","berge nordwesten kult"}},{q="Warum will Kalaran ein Symbol von Ragnaros?",a="Die Symbole und Götzenbilder von Twilight's Hammer könnten genügend Verzauberung für eine magische Ummantelung in sich tragen. Kalaran hofft, diese Magie aus einem Symbol von Ragnaros zu ziehen.",al={"warum symbol von ragnaros","ragnaros symbol zweck","was bewirkt das symbol"}},{q="Was kommt vor diesem Schritt in der Questreihe?",a="Dies folgt auf Forging the Shaft, als Kalaran um mit Thorium beschichtete Dolche bat, um sie zu einem Schaft umzuschmieden.",al={"vorherige quest","welche quest vor ummantelung der flamme"}}},fp="18,233,22.404.0,19.88.1,44.99.0,42.89.0,43.148.0,41.102.0"}
P.entries["quest:3453"] = {n="Die Fackel der Vergeltung",s="An Kalaran Windblades Seite wartet Ihr, während er die Teile zusammenfügt und die Fackel der Vergeltung verzaubert.",h="An Kalaran Windblades Seite wartet Ihr, während er die Teile zusammenfügt und die Fackel der Vergeltung...",kw={"kanalisierung","verzauberung","kalaran windblade","sengende schlucht","fackel der vergeltung"},sec={{t="Die Teile zusammenfügen",b="Kalaran Windblade braucht Zeit, um die Teile zusammenzufügen und die Fackel zu verzaubern. Bei seiner Arbeit kanalisiert er Magie, also wartet Ihr und lasst ihn ungestört."},{t="Wenn das Warten endet",b="Nach einer Weile erscheint die Fackel vor Kalaran, und er erklärt, dass die Arbeit getan ist. Eine letzte Angelegenheit bleibt, um die Ihr Euch kümmern müsst."}},faq={{q="Wer fertigt die Fackel?",a="Kalaran Windblade fügt die Teile zusammen und verzaubert die Fackel. Er kanalisiert Magie, um sie fertigzustellen.",al={"hersteller der fackel","wer fertigt die fackel","kalaran windblades rolle"}},{q="Was kam direkt vor diesem Schritt?",a="The Flame's Casing kam unmittelbar davor. Ihr habt ein Symbol von Ragnaros für Kalaran gefunden, aus dem er die Hülle fertigen sollte.",al={"vorherige quest","voraussetzung","was wurde gerade erledigt"}},{q="Warum dürft Ihr Kalaran nicht unterbrechen?",a="Kalaran kanalisiert Magie, während er die Teile zusammenfügt. Er warnt Euch davor, ihn zu unterbrechen.",al={"nicht unterbrechen","kanalisierungsvorgang"}}},fp="24,102,18.140.0,18.122.1,21.92.0,33.109.0,35.86.0"}
P.entries["quest:3454"] = {n="Die Fackel der Vergeltung",s="Kalaran Windblade hat die Fackel fertiggestellt und bittet Euch, sie an Euch zu nehmen.",h="Kalaran Windblade hat die Fackel fertiggestellt und bittet Euch, sie an Euch zu nehmen.",kw={"bindung","kalaran windblade","sengende schlucht","fackel der vergeltung"},sec={{t="Die Bindung der Flamme",b="Kalaran Windblade sagt, die Fackel müsse an ihren Besitzer gebunden werden. Er bittet Euch, sie selbst an Euch zu nehmen."},{t="Die Fackel in Händen",b="Hass und Zorn durchströmen Euch, als Ihr die Fackel mit beiden Händen hebt."}},faq={{q="Wer fordert Euch auf, die Fackel an Euch zu nehmen?",a="Kalaran Windblade fordert Euch auf, die Fackel an Euch zu nehmen, damit sie an ihren Besitzer gebunden werden kann.",al={"wer gibt die fackel","questgeber der fackel","kalaran fackel"}},{q="Warum müsst Ihr die Fackel aufheben?",a="Kalaran sagt, die Fackel müsse an ihren Besitzer gebunden werden, und bittet Euch deshalb, sie an Euch zu nehmen.",al={"warum die fackel aufheben","bindung der fackel"}},{q="Wo gehört dieser Schritt in die Questreihe?",a="Dies folgt auf den früheren Schritt der Fackel der Vergeltung, bei dem Ihr gewartet habt, während Kalaran die Teile zusammenfügte und verzauberte.",al={"questreihe der fackel","vorherige quest"}}},fp="24,66,17.96.0,17.73.1,32.78.0,31.80.0,40.118.0"}
P.entries["quest:346"] = {n="Rückkehr zu Kristoff",s="Auf dem Kathedralenplatz wartet Bruder Kristoff auf die Rückkehr von The Stresses of Iron. Nach langer Suche in Nordhain bringt Ihr das geliehene Buch zur Kathedrale des Lichts zurück.",h="Auf dem Kathedralenplatz wartet Bruder Kristoff auf die Rückkehr von The Stresses of Iron.",kw={"bruder kristoff","brother paxton","kathedralenplatz","milton garbenbund","abtei von nordhain","rückkehr zu kristoff","sturmwind","the stresses of iron"},ang={["class:Priest"]="Als Priester seht Ihr, wie die Kirche des Heiligen Lichts wichtige gelehrte Schriften im ganzen Königreich bewahrt und weitergibt.",["faction:Alliance"]="Als Mitglied der Allianz seid Ihr auf sichere Straßen angewiesen, die Burg Sturmwind, Nordhain und das umkämpfte Rotkammgebirge verbinden."},sec={{t="Eine längst überfällige Rückkehr",b="Bruder Kristoff wartet auf dem Kathedralenplatz auf The Stresses of Iron, ein Buch über Metallurgie. Sein Weg führte von der Royal Library in Burg Sturmwind zur Abtei von Nordhain, wo Bruder Paxton es von Hand abschrieb. Die Arbeit stockte, als Paxton nicht mehr genug Rethban Ore für seine Tinte hatte. Nun ist das Erz gefunden und die Abschrift vollendet. Ihr bringt das Original nach Sturmwind zurück."},{t="Die Arbeit der Schreiber",b="Bruder Paxton bittet Euch, Euch bei Bibliothekar Milton Garbenbund für die Verzögerung zu entschuldigen. Die Kopisten von Nordhain bewahren weltliches und geistliches Wissen, obwohl ihre Vorräte knapp sind. Wertvolle Bücher müssen Strich für Strich mit mineralreicher Tinte abgeschrieben werden. Erst dann können sie die Abtei verlassen und wieder in Sturmwinds Obhut gelangen."}},faq={{q="Wovon handelt das Buch The Stresses of Iron?",a="The Stresses of Iron ist eine Abhandlung über Metallurgie und Metallverarbeitung. Bruder Kristoff wollte es auf dem Kathedralenplatz studieren, und die Schreiber der Abtei von Nordhain benötigten eine Abschrift, um sein Wissen zu bewahren.",al={"was ist stresses of iron","stresses of iron buch","welches buch sucht kristoff"}},{q="Warum war das Buch in der Abtei von Nordhain?",a="Die Royal Library lieh Bruder Paxton The Stresses of Iron, damit er eine illustrierte Abschrift für die Archive der Abtei von Nordhain anfertigen konnte. Seine Arbeit stockte, als ihm Rethban Ore für eine spezielle Tinte ausging.",al={"warum hatte paxton das buch","warum war es in nordhain"}},{q="Wer ist Bruder Kristoff?",a="Bruder Kristoff gehört zur Geistlichkeit des Heiligen Lichts und dient auf dem Kathedralenplatz vor Sturmwinds Kathedrale des Lichts. Er hat das Buch angefordert und gewährt zum Dank geistlichen Segen.",al={"wer ist kristoff","kristoff sturmwind"}},{q="Wer ist Milton?",a="Milton Garbenbund ist der leitende Bibliothekar der Royal Library in Burg Sturmwind. Er erlaubte die Ausleihe von The Stresses of Iron und wurde wegen der langen Verzögerung ungeduldig.",al={"wer ist bibliothekar milton","milton garbenbund"}},{q="Wo beginnt diese Questreihe?",a="Die Reihe beginnt auf Sturmwinds Kathedralenplatz, wo Bruder Kristoff Speaking of Fortitude anbietet. Sie führt zu Bibliothekar Milton Garbenbund, dann zur Abtei von Nordhain und ins Rotkammgebirge, bevor sie Euch zu Kristoff zurückbringt.",al={"wie beginnt speaking of fortitude","beginn der questreihe"}},{q="Hat diese Quest Folgequests?",a="Rückkehr zu Kristoff beendet die Questreihe Speaking of Fortitude. Wenn Ihr The Stresses of Iron abliefert, dankt Euch Bruder Kristoff und gewährt Euch einen Segen des Lichts.",al={"was folgt auf rückkehr zu kristoff","gibt es eine folgequest"}}},fx={["46830297"]={q="Warum möchte Bruder Paxton, dass das Buch an Bruder Kristoff zurückgegeben wird?",a="Bruder Paxton hat The Stresses of Iron nur ausgeliehen, um seinen Inhalt in der Abtei von Nordhain kopieren zu können. Jetzt, da seine Transkription abgeschlossen ist, hat er keinen Anspruch mehr auf den seltenen Band und schuldet seine sichere Rückgabe an die Kathedrale des Lichts in Sturmwind, in der Hoffnung, etwaige Probleme, die durch seine lange Verzögerung entstanden sind, wiedergutzumachen.",al={"warum stresses of iron zurückgeben","beweggrund von brother paxton","warum buch an kristoff zurückschicken"}}},fp="18,178,21.367.0,20.305.0,44.196.0,37.202.0,24.194.0,14.155.0,34.222.0,36.159.0"}
P.entries["quest:3462"] = {n="Knappe Maltrake",s="Mit der Fackel der Vergeltung in der Hand schickt Euch Kalaran Windblade zu Knappe Maltrake, um Anweisungen zu erhalten.",h="Mit der Fackel der Vergeltung in der Hand schickt Euch Kalaran Windblade zu Knappe Maltrake, um Anweisungen...",kw={"gesandter","kalaran windblade","sengende schlucht","knappe maltrake","fackel der vergeltung"},sec={{t="Ein Wort mit dem Gesandten",b="Kalaran Windblade schickt Euch zu Knappe Maltrake. Der Knappe wird Euch erklären, wie Ihr die Fackel der Vergeltung verwendet."}},faq={{q="Wer schickt Euch zu Knappe Maltrake?",a="Kalaran Windblade schickt Euch zu Knappe Maltrake und weist Euch an, die Anweisungen anzuhören.",al={"wer vergibt knappe maltrake","knappe maltrake questgeber","wer startet knappe maltrake"}},{q="Welche Rolle spielt Knappe Maltrake?",a="Knappe Maltrake wird Euch erklären, wie Ihr die Fackel der Vergeltung verwendet.",al={"was macht knappe maltrake","wer ist maltrake","warum mit maltrake sprechen"}},{q="Was geschieht vor dem Gespräch mit Knappe Maltrake?",a="Ihr erhaltet die Fackel der Vergeltung, bevor Ihr mit Knappe Maltrake sprecht.",al={"voraussetzung knappe maltrake","welche quest kommt vor knappe maltrake","vorherige quest maltrake"}}},fp="15,103,21.108.0,33.88.0,31.65.0,46.72.0"}
P.entries["quest:3463"] = {n="Setzt sie in Brand!",s="In der Sengenden Schlucht tragt Ihr Maltrakes Fackel zu den vier Wachtürmen. Ihre Flammen lassen sich nicht löschen, und die Türme können nicht zerstört werden. Während sie brennen, verlassen Wachen und Wachposten ihre Stellungen, wodurch die Dunkeleisenzwerge ihre erste Verteidigungslinie verlieren.",h="In der Sengenden Schlucht tragt Ihr Maltrakes Fackel zu den vier Wachtürmen.",kw={"dunkeleisenzwerge","sengende schlucht","wachtürme","setzt sie in brand","squire maltrake","fackel der vergeltung"},sec={{t="Ein unauslöschliches Feuer",b="Die Fackel der Vergeltung brennt so stark, dass kein Element und keine Macht sie löschen kann. Maltrake schickt Euch in jeden der vier Wachtürme im Norden, Süden, Osten und Westen, um sie innerhalb der Mauern einzusetzen. Dort halten Späher der Dunkeleisenzwerge Wache, weshalb Maltrake Euch zur Vorsicht mahnt."},{t="Nach der letzten Flamme",b="Als Ihr zu Maltrake zurückkehrt, nachdem der letzte Turm brennt, ruft er triumphierend nach seinem Meister. Velarok the Deceiver antwortet und offenbart sich als Drache des Schwarzen Drachenschwarms. Sein Plan habe vollkommen funktioniert, frohlockt er, denn Ihr hättet der Blackrock-Legion niemals geholfen, wenn sie Euch einfach darum gebeten hätte.\n\nMaltrake überlegt, was mit Euch geschehen soll, doch Velarok bringt ihn zum Schweigen. Ihr werdet am Leben bleiben, um mit anzusehen, wie die Blackrock-Legion in die Schlucht einmarschiert. Velarok lässt Maltrake Schmuckstücke aushändigen, spricht von einer Häutung und fliegt dann in Richtung der Schlucht."}},faq={{q="Wer schickt Euch los, um die Türme in Brand zu setzen?",a="Squire Maltrake schickt Euch zu den Türmen und gibt Euch die Fackel der Vergeltung.",al={"wer vergibt setzt sie in brand","setzt sie in brand questgeber","maltrake quest"}},{q="Welche Türme müssen entzündet werden?",a="Betretet die vier Wachtürme im Norden, Süden, Osten und Westen und setzt sie in Brand.",al={"welche türme","standorte der wachtürme","setzt sie in brand türme"}},{q="Warum soll die Fackel der Vergeltung eingesetzt werden, statt die Türme niederzureißen?",a="Die Türme können nicht zerstört werden. Die Fackel der Vergeltung hält sie für eine sehr lange Zeit in Brand, und kein Element und keine Macht kann ihre Flammen löschen.",al={"warum fackel","wachtürme zerstören"}},{q="Was war der vorherige Schritt?",a="Ihr habt mit Squire Maltrake gesprochen, der Euch daraufhin diesen Auftrag gegeben hat.",al={"setzt sie in brand voraussetzung","vorherige quest"}}},fp="16,257,26.265.0,20.519.1,39.79.0,29.69.0,68.132.0,43.67.0"}
P.entries["quest:347"] = {n="Rethbanerz",s="Rethbanerz aus dem Rotkammgebirge wird in der Abtei von Nordhain wegen seiner dunklen Farbe benötigt. Großknecht Oslow schickt Euch in die Rethbanhöhlen, um das weiche Mineral zu sammeln, das sich nicht für robuste Waffen oder Rüstungen eignet.",h="Rethbanerz aus dem Rotkammgebirge wird in der Abtei von Nordhain wegen seiner dunklen Farbe benötigt.",kw={"bart rethban","brother paxton","großknecht oslow","abtei von nordhain","schinder des rotkammgebirges","rethbanhöhlen","rethbanerz","stresses of iron"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr sehen, wie überlastet die Nachschubwege des Königreichs Sturmwind sind. Die Schriftgelehrten des Klosters sind auf Reisende angewiesen, die Schreibmaterial aus Kriegsgebieten beschaffen.",["profession:Mining"]="Als Bergmann könnt Ihr Rethbanerz mit einer Spitzhacke aus den Adern der Höhlen abbauen, statt rohe Brocken bei Gnollschindern zu erbeuten.",["race:Human"]="Als Mensch teilt Ihr die Pflicht der Gelehrten von Sturmwind, die Manuskripte der Abtei von Nordhain zu bewahren und im Ersten und Zweiten Krieg verlorenes Wissen wiederzugewinnen."},sec={{t="Ein seltsames Mineral",b="Die Schriftgelehrten der Abtei von Nordhain schätzen Rethbanerz wegen seiner dunklen, matten Farbe. Bart Rethban hat es entdeckt, doch am Amboss eines Rüstungsschmieds ist das Mineral kaum von Nutzen. Das aus dem Erz geschmolzene Metall ist zu schwach für robuste Waffen oder Plattenrüstungen. Seine natürliche Farbe bildet stattdessen eine geschätzte Grundlage für Manuskriptfarben."},{t="Umkämpfte Höhlen",b="Die größten Erzvorkommen liegen in den nördlichen Bergen des Rotkammgebirges, in den Rethbanhöhlen. Die Steinmetze von Seenhain sind fort, vertrieben von einer wilden Schar Gnolle aus dem Rotkammgebirge. Die Gnolle zwingen Schinder, für ihre eigenen primitiven Zwecke Erz aus den Felsadern zu schlagen."},{t="Das Wort bewahren",b="Bruder Paxton, ein Mönch der Abtei von Nordhain, braucht das Pigment, um historische Texte abzuschreiben. Seine Arbeit an The Stresses of Iron ruht, weil ihm der passende Farbstoff fehlt. Boten und Abenteurer reisen nun in das von Gnollen besetzte Gebiet, um ihm das Rohgestein zu bringen."}},faq={{q="Wofür wird Rethbanerz verwendet?",a="Geschmolzenes Rethbanerz ist zu schwach für haltbare Waffen oder Rüstungen. Seine dunkle, matte Farbe bildet eine nützliche Grundlage für Tinten und Farbstoffe, mit denen Bruder Paxton und andere Schriftgelehrte der Abtei von Nordhain historische Manuskripte abschreiben.",al={"warum wird rethbanerz gebraucht","rethbanerz verwendung","wofür ist rethbanerz"}},{q="Wer war Bart Rethban?",a="Bart Rethban war ein Entdecker und Prospektor, der die dunklen Erzadern in den nördlichen Bergen des Rotkammgebirges entdeckte. Das Mineral und die Rethbanhöhlen sind nach ihm benannt.",al={"wer entdeckte rethbanerz","bart rethban geschichte"}},{q="Warum hat Seenhain in letzter Zeit kein Erz abgebaut?",a="Großknecht Oslow und die Arbeiter von Seenhain sind damit beschäftigt, die Stadt gegen Einfälle der Schwarzfelsorcs zu verteidigen. Außerdem haben Gnolle aus dem Rotkammgebirge die Rethbanhöhlen besetzt und die zivilen Bergleute vertrieben.",al={"warum baut oslow es nicht ab","warum sind die minen verlassen"}},{q="Welches Buch schreibt Bruder Paxton ab?",a="Bruder Paxton schreibt The Stresses of Iron ab. Er braucht dunklen Farbstoff aus Rethbanerz, um den Text für die Bibliothek der Abtei fertigzustellen.",al={"welches buch schreibt paxton","paxton manuskript"}},{q="Warum wollen die Gnolle das Erz?",a="Die Gnolle des Rotkammgebirges lassen ihre Schinder überall in den Höhlen graben. Vielleicht wollen sie das Erz für primitive Werkzeuge, zum Handeln oder um ihre Bergbaue gegen Eindringlinge zu befestigen.",al={"warum bauen gnolle erz ab","gnollschinder rethban"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Nachdem Bruder Paxton das Erz erhalten und seine Tinten zubereitet hat, schickt er Euch zurück nach Sturmwind, um Kristoff Euren Erfolg zu melden. Damit ist der Auftrag für die Schriftgelehrten von Nordhain erledigt.",al={"welche quest folgt auf rethbanerz","return to kristoff als nächstes"}}},fx={["86e7e5db"]={q="Warum möchte Großknecht Oslow, dass dies erledigt wird?",a="Großknecht Oslow sucht das Erz nicht für sich selbst oder die Baumeister von Seenhain. Bruder Paxton aus der Abtei von Nordhain hat Euch zu Oslow geschickt, um Rethban Ore für Tinte zum Buchbinden zu beschaffen. Oslow kommt der Bitte lediglich nach, indem er Euch zur Quelle schickt, da die Vorräte der Stadt leer sind und seine Arbeiter nicht die Zeit erübrigen können, es selbst zu graben.",al={"beweggrund von großknecht oslow","warum braucht oslow erz","warum hilft oslow paxton"}},fa5d21e9={q="Wer besetzt die Rethbanhöhlen?",a="Die Gnolle des Rotkammgebirges haben die Rethbanhöhlen nördlich von Seenhain überrannt. Anstatt die Höhlen leer stehen zu lassen, haben Gnollplünderer begonnen, die dunklen Erzadern für ihre eigenen Zwecke auszugraben und dabei alle einheimischen Bergleute, die sich zu nähern versuchen, gewaltsam vertrieben.",al={"feinde in den rethbanhöhlen","wer ist in den rethbanhöhlen","gnolle im rotkammgebirge höhlen"}}},fp="11,190,17.286.0,17.260.0,19.246.0,29.214.0,21.177.0,44.191.0,36.133.0,27.170.0,38.181.1"}
P.entries["quest:348"] = {n="Schlingendornfieber",s="In Beutebucht wird Fin Fizracket durch das Schlingendorntalfieber immer schwächer. Er glaubt, im Sterben zu liegen, und sagt, nur das Herz von Mokk the Savage könne ihn heilen.",h="In Beutebucht wird Fin Fizracket durch das Schlingendorntalfieber immer schwächer.",kw={"beutebucht","fin fizracket","herz von mokk","mokk the savage","schlingendorntalfieber","schlingendorntal","hexendoktor unbagwa"},sec={{t="Ein verzweifeltes Heilmittel",b="Fin Fizracket stammelt, während seine Kräfte schwinden. Er ist sicher, dass er sich das Schlingendorntalfieber zugezogen hat, und sagt, er müsse das Herz von Mokk the Savage essen, um geheilt zu werden. Mokk ist eine schwer zu fassende weiße Bestie, und nur Hexendoktor Unbagwa kann ihn beschwören. Fin schickt Euch los, um Unbagwa im Geisterhöhlenbau zu finden, einer verborgenen Höhle am südlichen Kap."},{t="Zurück an Fins Seite",b="Nachdem Fin Mokks Herz erhalten hat, kehren seine Kräfte allmählich zurück. Er erwacht und weiß nicht recht, wo er ist, erfährt dann, dass er in Beutebucht ist, und erzählt von einem seltsamen Traum. Doch ein Teil seiner Schwäche bleibt."}},faq={{q="An welcher Krankheit leidet Fin Fizracket?",a="Fin sagt, er habe das Schlingendorntalfieber, ein tödliches Virus, das ihn frieren lässt und ins Delirium versetzt. Er glaubt, im Sterben zu liegen.",al={"welche krankheit hat fin","schlingendorntalfieber krankheit","fin fizracket krank"}},{q="Was ist nötig, um das Fieber zu heilen?",a="Fin sagt, er müsse das Herz von Mokk the Savage essen, einer schwer zu fassenden weißen Bestie, um geheilt zu werden.",al={"wie schlingendorntalfieber heilen","heilmittel für fin fizracket","mokks herz als heilmittel"}},{q="Wer ist Hexendoktor Unbagwa?",a="Nur Hexendoktor Unbagwa kann Mokk the Savage beschwören. Er befindet sich im Geisterhöhlenbau, einer verborgenen Höhle am südlichen Kap im Schlingendorntal.",al={"wo ist unbagwa","wer kann mokk beschwören","rolle von hexendoktor unbagwa"}},{q="Wo ist Fin Fizracket zu finden?",a="Fin Fizracket befindet sich in Beutebucht.",al={"fin fizracket aufenthaltsort","wo ist fin fizracket","kerl mit fieber in beutebucht"}}},fp="19,142,16.313.0,18.188.1,45.112.0,35.87.0,28.137.0,33.30.0"}
P.entries["quest:3481"] = {n="Plunder...",s="Nach Set Them Ablaze! findet Ihr den Hort des schwarzen Drachenschwarms in der Sengenden Schlucht.",h="Nach Set Them Ablaze!",kw={"hort des schwarzen drachenschwarms","sengende schlucht","set them ablaze","plunder"},sec={{t="Eine verschlossene Truhe",b="Der Hort des schwarzen Drachenschwarms wartet in der Sengenden Schlucht, nachdem die Türme gebrannt haben. Die Truhe scheint verschlossen zu sein, und es liegt an Euch, sie zu öffnen."},{t="Bei Eurer Berührung",b="Die Truhe öffnet sich bei Eurer Berührung ohne Schlüssel. Darin liegt eine Häutung des Schwarzen Drachenschwarms. Könnte darin Käse sein? Das lässt sich nur herausfinden, indem Ihr nachseht."}},faq={{q="Was ist der Hort des schwarzen Drachenschwarms?",a="Der Hort des schwarzen Drachenschwarms ist eine Truhe in der Sengenden Schlucht, die nach Set Them Ablaze! erscheint. Sie scheint verschlossen zu sein.",al={"was ist der hort des schwarzen drachenschwarms","wem gehört die truhe","plunder truhe fundort"}},{q="Was kommt vor der Truhe?",a="Set Them Ablaze!, wobei Ihr die Türme der Sengenden Schlucht in Brand setzt.",al={"plunder voraussetzung","vorherige quest","was führt zu plunder"}},{q="Was sollt Ihr mit der Truhe tun?",a="Ihr sollt die Truhe öffnen. Sie scheint verschlossen zu sein, doch sie zu öffnen ist alles, was von Euch verlangt wird.",al={"ist die truhe verschlossen","wie die truhe öffnen","was mit der truhe tun"}}},fp="11,86,14.130.0,13.148.1,44.117.0,28.67.0,40.93.0"}
P.entries["quest:349"] = {n="Schlingendornfieber",s="Im Schlingendorntal bereitet Hexendoktor Unbagwa einen Gesang vor, um Mokk den Wilden aus dem Dschungel zu locken. Er braucht zehn Gorillareißzähne, um zu beginnen. Während er mit den Geistern Zwiesprache hält, kommen Gorillas aus der Umgebung und bedrohen ihn.",h="Im Schlingendorntal bereitet Hexendoktor Unbagwa einen Gesang vor, um Mokk den Wilden aus dem Dschungel zu...",kw={"gorillareißzahn","mokk der wilde","schlingendornfieber","schlingendorntal","unbagwa","hexendoktor"},sec={{t="Ein Ritual für den Wilden",b="Hexendoktor Unbagwa kennt ein Ritual, das Mokk den Wilden aus dem Dschungel locken kann. Er verlangt zehn Gorillareißzähne, bevor er mit dem Gesang beginnt. Während er mit den Geistern Zwiesprache hält, lockt der Gesang Gorillas aus der Umgebung an. Sie bedrohen den Hexendoktor, während er versucht, das Ritual zu vollenden."}},faq={{q="Wer ist Hexendoktor Unbagwa?",a="Hexendoktor Unbagwa ist ein Troll im Schlingendorntal, der behauptet, mit den Geistern sprechen und den großen Affen Mokk den Wilden hervorlocken zu können.",al={"unbagwa","wer ist unbagwa","hexendoktor unbagwa"}},{q="Was benötigt Hexendoktor Unbagwa, um zu beginnen?",a="Hexendoktor Unbagwa verlangt zehn Gorillareißzähne, bevor er sich bereit erklärt, mit den Geistern zu sprechen.",al={"gorillareißzahn quest","welcher gegenstand für unbagwa","unbagwa voraussetzungen"}},{q="Warum muss der Hexendoktor verteidigt werden?",a="Das Gespräch mit den Geistern lockt Gorillas aus der Umgebung zu Unbagwa. Sie bedrohen ihn während seiner Zwiesprache mit den Geistern, und wenn sie ihn überwältigen, kann er weder das Ritual vollenden noch Mokk beschwören.",al={"warum unbagwa verteidigen","hexendoktor unbagwa verteidigen","gorillabestien ritual"}},{q="Wer ist Mokk der Wilde?",a="Mokk der Wilde ist ein furchterregender Gorilla, der durch das Schlingendorntal streift, und Hexendoktor Unbagwa weiß, wie man ihn beschwört.",al={"mokk","wer ist mokk","mokk der wilde"}}},fp="19,209,23.274.0,28.134.0,48.91.0,38.167.0,23.118.0"}
P.entries["quest:35"] = {n="Weitere Sorgen",s="Östlich von Goldhain lässt Marschall Dughan Euch Berichten über Gefahren nachgehen. Ihr durchquert den Wald von Elwynn, um mit Wache Thomas am Flussübergang zum Rotkammgebirge zu sprechen.",h="Östlich von Goldhain lässt Marschall Dughan Euch Berichten über Gefahren nachgehen.",kw={"östliche brücke","wald von elwynn","weitere sorgen","goldhain","wache thomas","marschall dughan","murloc"},ang={["faction:Alliance"]="Für die Allianz offenbart die schwache Verteidigung nahe der Hauptstadt wachsende Risse in der Stärke des Königreichs Sturmwind.",["race:Human"]="Als Mensch aus Elwynn steht Ihr Murlocs gegenüber, deren Ausbreitung die Höfe der Kornkammer und die Handelswege zwischen Goldhain und Seenhain bedroht."},sec={{t="Blick auf den Ostübergang",b="Marschall Dughan befehligt Goldhains Garnison und nimmt Berichte über feindselige Kreaturen an Elwynns Flussufern ernst. Banditen und Ungeziefer plagen bereits das Herz des Waldes, daher kann er keine Wachen aus der Stadt entbehren. Er schickt Euch nach Osten, um Wache Thomas zu befragen, den Wachposten an der Brücke zum Rotkammgebirge."},{t="Eine überforderte Grenzwacht",b="Wache Thomas hält den Brückenaußenposten seit über einer Woche und hat die Gefahr selbst gesehen. Feindselige, halbintelligente Murlocs haben an den Gewässern im östlichen Elwynn Lager errichtet. Sturmwinds Armee ist abwesend, und die örtlichen Garnisonen bewachen Stadtmauern und Versorgungswege. Ländliche Brückenposten wie der von Thomas bleiben auf sich gestellt, während die Gefahr wächst."}},faq={{q="Warum schickt Marschall Dughan mich zu Wache Thomas?",a="Marschall Dughan schickt Euch zu Wache Thomas, weil Berichte von Murlocs sprechen, die sich in die östlichen Gewässer einschleichen. Thomas ist seit einer Woche an der Brücke im östlichen Elwynn stationiert, daher vertraut Dughan darauf, dass er die Bedrohung bestätigen kann.",al={"warum wache thomas","dughans absicht","mit thomas sprechen"}},{q="Wo ist Wache Thomas stationiert?",a="Wache Thomas bewacht die Holzbrücke über den Fluss ganz im Osten des Waldes von Elwynn, an der Straße zum Rotkammgebirge.",al={"standort von wache thomas","wo ist thomas","wache an der östlichen brücke"}},{q="Welche Bedrohung bestätigt Wache Thomas?",a="Wache Thomas bestätigt, dass sich feindselige, halbintelligente Murlocs an den Bächen und Wasserwegen im östlichen Elwynn niedergelassen haben. Sie bedrohen Reisende und nahe gelegene Gehöfte.",al={"bedrohung durch murlocs","was hat thomas entdeckt","bedrohung am östlichen fluss"}},{q="Wie erreicht Ihr Wache Thomas?",a="Folgt von Goldhain aus der Straße nach Osten durch den Wald von Elwynn zur Brücke über den östlichen Fluss, wo Wache Thomas wacht.",al={"schnellreise zu thomas","ritt zu dughan","schlachtross zur brücke"}},{q="Warum schickt Sturmwind keine Armee, um dem östlichen Elwynn zu helfen?",a="Sturmwinds Streitkräfte sind überlastet, da König Varian Wrynn vermisst wird und Mittel aus den ländlichen Gebieten abgezogen werden. Wachposten wie Wache Thomas müssen sich weitgehend auf vorbeiziehende Abenteurer verlassen.",al={"wo sind sturmwinds wachen","warum ist elwynn unverteidigt","militärische hilfe aus sturmwind"}},{q="Was geschieht nach der Meldung bei Wache Thomas?",a="Nachdem Wache Thomas die Anwesenheit der Murlocs bestätigt hat, bittet er Euch, dem Schicksal der anderen Wachposten nachzugehen, die am Flussufer patrouillierten und nicht zurückkehrten.",al={"nächste quest nach weitere sorgen","folgeauftrag von thomas","quest zu vermissten wachen"}}},fx={["01d891f6"]={q="Warum schickt Marschall Dughan einen Abenteurer anstelle seiner eigenen Wachen?",a="Marschall Dughan ist überlastet, während er Goldhain gegen Defias-Banditen und Gnolle sichert. Da Sturmwind zusätzliche Truppen und Ressourcen verweigert, kann die örtliche Garnison keine Soldaten für routinemäßige Botengänge oder weit entfernte Erkundungen entbehren. Weil Ihr ihm die erste Warnung überbracht und Sorge um die Sicherheit von Elwynn gezeigt habt, vertraut er Euch damit, nach Osten zu reisen, um mit Wache Thomas an der östlichen Brücke Rücksprache zu halten.",al={"warum werde ich geschickt","warum keine wachen einsetzen","warum braucht mich dughan"}}},fp="16,161,28.298.0,25.337.0,48.221.0,32.126.0,38.166.0,30.124.0,58.192.0,45.158.0"}
P.entries["quest:350"] = {n="Auf einen alten Freund verlassen",s="Meister Mathias Shaw schickt Euch zu einem ungewöhnlichen Verbündeten im Handelsdistrikt von Sturmwind. Korruption im Adel schützt Verräter vor der gewöhnlichen Justiz, also wendet sich Shaw an den besten Käsehändler der Stadt und dessen Geheimdienstnetzwerk.",h="Meister Mathias Shaw schickt Euch zu einem ungewöhnlichen Verbündeten im Handelsdistrikt von Sturmwind.",kw={"defias","elling trias","lescovar","marzon","mathias shaw","sturmwind","der handelsdistrikt","trias' cheese"},ang={["class:Rogue"]="Als Schurke erkennt Ihr die angespannte Rivalität zwischen Mathias Shaw und Elling Trias. Informanten auf der Straße können mehr Einfluss haben als der offizielle Geheimdienst der Krone.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie Korruption im House of Nobles die innere Sicherheit Sturmwinds beeinträchtigt, während King Varian Wrynn weiterhin vermisst wird."},sec={{t="Über dem Gesetz",b="Lord Gregor Lescovar und Marzon the Silent Blade haben Verbindungen zur Bruderschaft der Defias, doch Meister Mathias Shaw steckt in einer Sackgasse. Edwin van Cleef liegt tot in den Todesminen, und Bazil Thredd wurde im Verlies ausgeschaltet. Kein Banditenanführer ist mehr am Leben, um auszusagen.\n\nLescovars Adelsrang und politische Verbindungen schützen ihn vor der gewöhnlichen Justiz der Königlichen Garde und formellen Haftbefehlen des SI:7."},{t="Das Ohr des Käsehändlers",b="Meister Mathias Shaw schickt Euch zu Elling Trias, dem Besitzer von Trias' Cheese im Handelsdistrikt. In ganz Sturmwind ist Trias als temperamentvoller Händler bekannt, der importierte Käsestücke und Käselaibe verkauft. Er führt auch ein unabhängiges Netzwerk aus Augen und Ohren, das dem SI:7 ebenbürtig ist.\n\nShaw widerstrebt es, sich an seinen ehemaligen Kollegen zu wenden. Doch um Verrat in der Burg Sturmwind aufzudecken, braucht es Methoden jenseits der offiziellen königlichen Wege."}},faq={{q="Warum schickt Euch Mathias Shaw zu einem Käsehändler?",a="Elling Trias ist mehr als ein Käsehändler. Er betreibt Trias' Cheese nahe dem Eingang zum Handelsdistrikt und unterhält ein weitreichendes Geheimdienstnetzwerk. Shaw widerstrebt es, ihn um Hilfe zu bitten, doch der SI:7 braucht ungewöhnliche Mittel, um gegen einen Adligen vorzugehen, den die gewöhnliche Strafverfolgung nicht erreicht.",al={"warum elling trias","warum mit trias sprechen","warum käseladen"}},{q="Warum kann Mathias Shaw Lord Lescovar nicht einfach verhaften?",a="Lord Lescovar ist ein hochrangiger Adliger aus Sturmwind mit engen Verbindungen im gesamten House of Nobles. Shaw fehlen die Zeugenaussagen, damit die Beweise gegen einen Aristokraten Bestand haben.",al={"warum lescovar nicht verhaften","warum kann shaw lescovar nicht verhaften","warum ist lescovar unantastbar"}},{q="Wer ist Marzon the Silent Blade?",a="Marzon the Silent Blade ist ein tödlicher Agent, der eng mit der Verschwörung der Defias zusammenarbeitet. Er steht heimlich mit Lord Lescovar am Hof von Sturmwind in Verbindung.",al={"wer ist marzon","rolle von marzon the silent blade"}},{q="Warum erwähnt Trias Deathwing, wenn Ihr mit ihm sprecht?",a="Als Trias von der Verschwörung der Bruderschaft der Defias hört, antwortet er mit bitterem Sarkasmus. Er spottet, als Nächstes würdet Ihr ihm erzählen, der lange verschollene schwarze Drachenaspekt Deathwing sei am Leben und greife das Königreich an.",al={"warum erwähnt trias deathwing","trias aussage über deathwing","deathwing greift sturmwind an"}},{q="Was geschieht nach dem Treffen mit Elling Trias?",a="Nachdem Trias den vollständigen Bericht über die Verschwörung gehört hat, beginnt er, eine heimliche Infiltration der Burg Sturmwind zu planen. Er will Lord Lescovar in die Enge treiben, ohne den übrigen Adel am Hof aufzuschrecken.",al={"nächste quest nach trias","wohin nach auf einen alten freund verlassen"}},{q="Wo befindet sich Elling Trias?",a="Elling Trias befindet sich in Trias' Cheese im Handelsdistrikt von Sturmwind, gleich neben der Hauptstraße, die von den Stadttoren herführt.",al={"trias standort","wo ist trias' cheese"}}},fx={["9cbff8f4"]={q="Warum schickt Mathias Shaw Euch, anstatt dies über das SI:7 zu regeln?",a="Lord Gregor Lescovar ist ein mächtiger, gut vernetzter Adliger, was ihn effektiv über das konventionelle Gesetz von Sturmwind stellt. Shaw fehlen die Zeugenaussagen, die nötig wären, um den Fall gegen ihn offiziell vor Gericht zu beweisen. Ein offizielles Vorgehen des SI:7 oder der Stadtwache würde ohne eiserne Beweise politisches Entsetzen beim Adel auslösen. Ihr hingegen operiert inoffiziell als unabhängiger Agent, was es Shaw ermöglicht, unkonventionelle, diskrete Wege zu verfolgen, ohne vorzeitige Aufmerksamkeit von Lescovars Verbündeten im Haus der Adligen auf sich zu ziehen.",al={"warum werde ich geschickt","warum nicht das si:7","warum braucht mich shaw"}}},fp="21,219,13.387.1,22.404.1,52.263.0,51.164.0,31.159.0,55.204.0,45.190.1,30.111.0"}
P.entries["quest:351"] = {n="Findet OOX-17/TN!",s="In Tanaris dreht Ihr am Knopf, und Findet OOX-17/TN! erwacht zum Leben. Oglethorpes Stimme sagt, dass sein Heimkehrroboter vermisst wird, und bittet Euch, den Peilsender zu ihm zu bringen.",h="In Tanaris dreht Ihr am Knopf, und Findet OOX-17/TN!",kw={"notpeilsender","die klaffende schlucht","heimkehrroboter","mechanisches huhn","oglethorpe","oox-17/tn","tanaris"},sec={{t="Eine Stimme aus dem Ei",b="Ein Knopf öffnet das seltsame Ei und gibt den Blick auf eine gnomische Vorrichtung frei. Eine Stimme knistert aus dem Inneren und stellt ihren Sprecher als Oglethorpe vor. Sein Heimkehrroboter wird vermisst. Oglethorpe hat berechnet, wo er abgestürzt ist, nahe der Klaffenden Schlucht in Tanaris, und bittet Euch, den Peilsender dorthin zu bringen."},{t="An der Absturzstelle",b="Der vermisste Heimkehrroboter an der Absturzstelle ist ein Roboterhuhn. Oglethorpe sagt, es brauche Starthilfe, bevor es für Reparaturen nach Hause nach Beutebucht fliegen könne, also steckt Ihr den Peilsender hinein. Summen und Surren ertönen, während das Huhn mühsam aufzustehen versucht. Dann ertönt Oglethorpes Stimme aus dem Roboter selbst. Er funktioniert, braucht aber größere Reparaturen und ist zu schwer, als dass Ihr ihn heben könntet."}},faq={{q="Wer nimmt durch das Gerät Kontakt mit Euch auf?",a="Eine Stimme aus dem Inneren des Eis stellt ihren Sprecher als Oglethorpe vor. Er sagt, dass sein Heimkehrroboter vermisst wird.",al={"wer ist oglethorpe","wer spricht durch das ei"}},{q="Wo ist der Heimkehrroboter abgestürzt?",a="Die von Oglethorpe berechneten Koordinaten verorten die Absturzstelle nahe der Klaffenden Schlucht in Tanaris.",al={"wo ist der roboter","wo ist oox-17/tn","wohin mit dem peilsender","roboterstandort klaffende schlucht"}},{q="Wozu dient der Peilsender?",a="Oglethorpe bittet Euch, den Peilsender zu seinem vermissten Heimkehrroboter zu bringen.",al={"was bewirkt der peilsender","was ist das ei","warum den peilsender tragen"}}},fp="15,158,20.280.0,17.359.1,41.103.0,33.83.0,23.68.0"}
P.entries["quest:3512"] = {n="Mit Eranikus' eigenen Worten",s="Itharius sucht durch den Edelstein nach Eranikus' Stimme. Eranikus liegt zwischen Schlaf und Tod, gefangen in Albträumen. Die Essenz, die Ihr übergeben habt, ist schwer verdorben, doch es bleibt Hoffnung. Itharius schickt Euch ins östliche Winterquell.",h="Itharius sucht durch den Edelstein nach Eranikus' Stimme.",kw={"eranikus","itharius","albtraum","geistsprecher","sümpfe des elends","umbranse","winterquell"},sec={{t="Eine Stimme durch den Albtraum",b="Itharius sagt, Eranikus liege zwischen Schlaf und Tod, gefangen in einem Geflecht aus Albträumen. Die Essenz, die Ihr übergeben habt, ist schwer verdorben, doch vielleicht gibt es einen Weg, ihn zu erreichen. Um durch den Edelstein zu sprechen, schickt Itharius Euch ins östliche Winterquell, wo Ihr einen seiner sterblichen Verbündeten aufsuchen sollt."},{t="Der Geistsprecher",b="Umbranse der Geistsprecher ist der Verbündete, den Itharius im Sinn hat. Umbranse ist ein Mensch, der als Medium für die Toten wirkt. Eranikus ist nicht wahrhaftig tot, doch Itharius glaubt, dass Umbranse dennoch helfen könnte."},{t="Umbranses Bedingung",b="Umbranse sagt, Itharius habe weise gehandelt, Euch zu schicken. Eranikus wird bald mit seinen eigenen Worten Rat erteilen. Vorerst kann Umbranse nicht direkt helfen, wird aber seine Fertigkeit im Sprechen mit den Toten zur Verfügung stellen.\n\nZuerst braucht Umbranse Hilfe von jemandem, den das Alter nicht einschränkt. Das mächtigste Wahrsagegerät in Umbranses Obhut wurde gegen Umbranses Willen entwendet. Ohne dieses Gerät kann Eranikus nicht geholfen werden."}},faq={{q="Wer schickt Euch auf diese Reise?",a="Itharius schickt Euch von den Sümpfen des Elends aus los, nachdem er die verdorbene Essenz von Eranikus von Euch entgegengenommen hat.",al={"wer vergibt mit eranikus' eigenen worten","eranikus questgeber"}},{q="Wer ist Umbranse der Geistsprecher?",a="Umbranse der Geistsprecher ist ein menschliches Medium für die Toten und einer von Itharius' sterblichen Verbündeten. Umbranse befindet sich im östlichen Winterquell.",al={"wer ist umbranse","umbranse der geistsprecher hintergrundgeschichte"}},{q="Gilt Eranikus als tot?",a="Eranikus ist nicht wahrhaftig tot. Er liegt zwischen Schlaf und Tod, gefangen in einem Geflecht aus Albträumen.",al={"ist eranikus tot","eranikus zustand"}},{q="Wo gehört dieser Schritt in die Geschichte?",a="Dies folgt auf den zweiten Schritt von The Essence of Eranikus, als Ihr Itharius den Edelstein mit dem Rest von Eranikus' freiem Willen übergeben habt.",al={"eranikus questreihe reihenfolge","was kam vor mit eranikus' eigenen worten"}}},fp="22,209,28.264.0,17.190.0,20.363.1,30.99.0,34.130.0,28.93.0,42.133.0"}
P.entries["quest:3513"] = {n="Die runenverzierte Rolle",s="Die runenverzierte Rolle wurde in Kalimdors Wildnis gefunden und trägt eine förmliche Botschaft von jenseits der Grenze. Ihr Fund führt Späher der Horde zum Mor'shan-Schutzwall, um die Wachen vor Aktivitäten im Norden zu warnen.",h="Die runenverzierte Rolle wurde in Kalimdors Wildnis gefunden und trägt eine förmliche Botschaft von jenseits...",kw={"eschental","grenze der horde","kadrak","der mor'shan-schutzwall","nachtelfenrolle","runenverzierte rolle","brachland"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass abgefangene Informationen der Allianz helfen, die Holzfällertrupps und Grenzwachen zu schützen, die den Zugang nach Eschental sichern.",["race:Orc"]="Als Orc wisst Ihr, dass die Ausbreitung des Kriegshymnenklans nach Eschental von den Verteidigungsanlagen des Mor'shan-Schutzwalls abhängt. Botschaften der Nachtelfen enthalten entscheidende Nachrichten."},sec={{t="Ein silbriges Band",b="Ein silbriges Band hält die Rolle zusammen, anders als das derbe Leder und Pergament, das im Brachland üblich ist. Ihre Machart und Schrift weisen nach Norden, zu den Nachtelfen unter Eschentals Baumkronen. Die Bergkämme und Straßen sind umkämpft, daher könnte eine dem Feind abgenommene Botschaft für die Frontlinien der Horde von großer Bedeutung sein."},{t="Blick auf die Nordgrenze",b="Die Rolle gehört zur örtlichen Befehlsführung, nicht in die Halle des Kriegshäuptlings in Orgrimmar. Kadrak, ein Orc-Krieger, bewacht die Grenze vom Mor'shan-Schutzwall aus, wo die rote Erde des Brachlands auf Eschentals Wälder trifft. Bringt die Rolle zu diesem Außenposten, und seine Wachen erfahren von den Truppenbewegungen der Nachtelfen."}},faq={{q="Was ist die Runenverzierte Rolle?",a="Die runenverzierte Rolle ist fein gearbeitet und mit einem silbrigen Band verschnürt, und ihre Gestaltung deutet auf einen Ursprung bei den Nachtelfen hin. Sie enthält Informationen über ihre Bewegungen oder Pläne entlang der Grenze des Brachlands.",al={"was ist diese rolle","runenverzierte rolle hintergrund","rolle mit silbrigem band"}},{q="Wohin soll ich die Rolle bringen?",a="Bringt die Rolle zu Kadrak am Mor'shan-Schutzwall, dem nördlichen Grenzposten zwischen dem Brachland und Eschental.",al={"wohin die runenverzierte rolle bringen","rolle abgeben","wer will die rolle"}},{q="Wer ist Kadrak?",a="Kadrak ist ein Späher und Wächter der Horde auf einem Wehrturm am Mor'shan-Schutzwall. Er hält nach Bedrohungen aus Eschental Ausschau.",al={"kadrak","orc am turm"}},{q="Warum sollten die Nachtelfen eine Rolle im Brachland verlieren?",a="Schildwachen und Späher der Nachtelfen patrouillieren an Eschentals Grenzen und Randgebieten. Manchmal wagen sie sich nach Süden, um die Verteidigung der Horde auf die Probe zu stellen oder Nachschublinien nach Norden zu überfallen.",al={"warum ist die rolle hier","nachtelfen im brachland"}},{q="Was geschieht, nachdem ich Kadrak die Rolle gegeben habe?",a="Nachdem Kadrak die Rolle gelesen hat, nennt er Rynthariel als ihre Verfasserin, eine Dryade und Schlüsselmeisterin des Krallenbaus. Er schickt Euch zum Steinkrallengipfel, um sie zu töten und eine Flagge der Horde im Bau aufzustellen.",al={"horde presence quest","what comes next"}},{q="Warum ist die Rolle für die Horde wichtig?",a="Holzeinschlag und Grenzstreitigkeiten schüren die Spannungen zwischen der Horde und den Nachtelfen. Abgefangene Botschaften können die Horde vor Hinterhalten der Allianz gegen den Mor'shan-Schutzwall warnen.",al={"bedeutung der runenverzierten rolle","interesse der horde an der rolle"}}},fp="16,188,16.299.0,27.291.0,25.185.0,31.106.0,14.116.0,55.159.0,47.183.0,40.162.0"}
P.entries["quest:3514"] = {n="Hordenpräsenz",s="An der Grenze zum Brachland schickt Kadrak einen Champion der Horde zum Steinkrallengipfel, nachdem ein Schreiben abgefangen wurde. Der Champion soll die Dryade Rynthariel töten und im Krallenbau ein Banner der Horde aufstellen.",h="An der Grenze zum Brachland schickt Kadrak einen Champion der Horde zum Steinkrallengipfel, nachdem ein...",kw={"brachland","dryade","hordenpräsenz","kadrak","kadraks flagge","rynthariel","der steinkrallengipfel","krallenbau","runenverzierte rolle"},ang={["class:Druid"]="Als Druide der Horde seid Ihr schmerzlich zwischen Fraktionstreue und heiliger Naturverbundenheit hin- und hergerissen, wenn Ihr zum Steinkrallengipfel marschiert, um eine Dryade, ein Kind des Cenarius, niederzustrecken.",["faction:Horde"]="Für die Horde hilft die Sicherung der Nordgrenze des Brachlands dabei, Kalimdors zentrale Ebenen zu halten und ihre jungen Siedlungen vor Vorstößen der Nachtelfen zu schützen.",["race:Orc"]="Als Orc könnt Ihr Kadraks Offensive als Zeichen der Stärke und Antwort auf das Eindringen in sein Gebiet sehen, die der Allianz keinen Handlungsspielraum lässt."},sec={{t="Eine abgefangene Botschaft",b="Kadrak bewacht die Nordgrenze des Brachlands gegen Vorstöße der Allianz und der Nachtelfen. Ein Bote mit einer runenverzierten Rolle wird niedergestreckt, und Kadrak entschlüsselt das Schreiben. Es führt ihn zu Rynthariel der Schlüsselmeisterin, einer einflussreichen Dryade auf dem Steinkrallengipfel. Statt nur die Gebirgspässe zu bewachen, schlägt Kadrak zuerst zu, um künftige Späher davon abzuhalten, Hordengebiet auszukundschaften."},{t="Trotz im Krallenbau",b="Krieger der Horde betreten den Krallenbau, eine Höhle mit Blick über den Steinkrallengipfel. Rynthariels Tod trifft die örtliche Koordination der Nachtelfen. Kadraks Banner wird in der Höhle aufgestellt. Seine rote Standarte kennzeichnet das Herz des Dryadengebiets mit einer Warnung: Vorstöße ins Brachland werden mit entschlossener Gewalt beantwortet."}},faq={{q="Wer ist Kadrak und warum befiehlt er diesen Angriff?",a="Kadrak ist ein Orc-Krieger, der am nördlichen Grenzposten zwischen dem Brachland und Eschental stationiert ist. Er befiehlt den Angriff, nachdem er entdeckt hat, dass Allianzboten durch nahe gelegene Pässe schleichen, um das Hordengebiet gegen fremde Übergriffe zu sichern.",al={"kadrak","wer ist kadrak","kadraks ziel"}},{q="Wer ist Rynthariel die Schlüsselmeisterin?",a="Rynthariel ist eine Anführerin der Dryaden im Krallenbau auf dem Steinkrallengipfel. Sie schrieb die runenverzierte Rolle, die der abgefangene Bote bei sich trug, und koordinierte damit die Bewegungen der Allianz und der Schildwachen durch die Gebirgskorridore.",al={"rynthariel","rynthariel die schlüsselmeisterin","krallenbau boss"}},{q="Wo liegt der Krallenbau?",a="Der Krallenbau ist ein unterirdischer Höhlenkomplex an den Westhängen des Steinkrallengipfels, hoch im Steinkrallengebirge.",al={"krallenbau standort","wo ist der krallenbau","rynthariel standort"}},{q="Welchen Zweck hat das Aufstellen von Kadraks Flagge?",a="Kadrak stellt die Flagge als Warnung auf. Er will, dass die Nachtelfen und die Allianz das rote Hordenbanner über ihrer gefallenen Anführerin sehen und zögern, weitere Späher durch das Brachland zu schicken.",al={"warum die flagge aufstellen","kadraks flagge","hordenflagge zweck"}},{q="Wie hängt diese Quest mit „Runenverzierte Rolle“ zusammen?",a="Hordenpräsenz folgt auf „Runenverzierte Rolle“. Die Mission beginnt, nachdem ein Spieler das abgefangene Pergament bei einem Allianzboten findet und es Kadrak zum Übersetzen bringt.",al={"runenverzierte rolle zusammenhang","vorherige quest","hordenpräsenz voraussetzung"}},{q="Warum ist die Horde wegen der Allianzboten im Brachland besorgt?",a="Das Brachland verbindet Orgrimmar, Donnerfels und die umliegenden Siedlungen. Allianzboten und verbündete Nachtelfen, die ungehindert durch Gebirgspässe reisen, bedrohen die Versorgungslinien der Horde und die Sicherheit ihrer Grenzen.",al={"allianz im brachland","warum dryaden bekämpfen","brachland bedrohung"}}},fp="14,197,21.378.0,19.313.0,48.251.0,32.209.0,31.122.0,46.192.0,50.172.0,65.201.0"}
P.entries["quest:3519"] = {n="Ein Freund in der Not",s="Im Laubschattental liegt Iverron nach einem Biss in Lebensgefahr. Der junge Nachtelf ruft nach Dirania Silberschein, deren Hilfe ihn vor dem Gift von Githyiss the Vile retten könnte.",h="Im Laubschattental liegt Iverron nach einem Biss in Lebensgefahr.",kw={"aldrassil","dirania silberschein","githyiss","iverron","gift","laubschattental","spinne","teldrassil"},ang={["class:Druid"]="Als Druide lernt Ihr früh, dass aus dem Gleichgewicht geratene Wildtiere Unachtsame niederstrecken können und dass es wichtig ist, die Gifte der Natur zu verstehen und ihnen entgegenzuwirken.",["race:NightElf"]="Als junger Kaldorei, der seine Ausbildung unter Aldrassil beginnt, erkennt Ihr, dass selbst die schützenden Äste des Laubschattentals Verderbnis und tödliche Gefahren bergen."},sec={{t="Ein leichtsinniges Wagnis",b="Iverron liegt geschwächt von einem Biss durch Githyiss the Vile darnieder. Er missachtete Warnungen und wagte sich zu nah an die Webwood-Höhlen heran, wo die bösartige Spinne zuschlug. Nun hindern ihn Schwindel und schwindende Kräfte daran, sich allein in Sicherheit zu bringen."},{t="Ein Hilferuf nach Aldrassil",b="Iverron schickt Vorbeikommende zum zentralen Baum von Aldrassil, um Dirania Silberschein zu finden. Sie wacht über ihn und kennt die Gefahren des Laubschattentals. Sein Leben könnte davon abhängen, dass sie ein Gegengift zubereitet, bevor das Gift tödlich wirkt."}},faq={{q="Wer ist Iverron?",a="Iverron ist ein junger Nachtelf, der im Laubschattental auf Teldrassil lebt. Trotz der Warnungen seiner Gefährten begibt er sich oft in Gefahr, und Githyiss the Vile hat ihn an den Rand des Todes gebracht.",al={"iverron hintergrund","wer ist der vergiftete elf","wer vergibt ein freund in der not"}},{q="Was hat Iverron angegriffen?",a="Githyiss the Vile hat Iverron gebissen. Die hochgiftige Spinne lauert in einer Spinnenhöhle im Laubschattental.",al={"was hat iverron gebissen","wer ist githyiss","welche spinne hat ihn vergiftet"}},{q="Wer ist Dirania Silberschein?",a="Dirania Silberschein ist eine Nachtelfe, die bei Aldrassil im Laubschattental lebt. Sie ist Iverrons enge Freundin und Beschützerin und weiß, wie man durch Gift verursachte Verletzungen behandelt.",al={"diranias rolle","mit wem wegen iverron sprechen"}},{q="Wo spielt diese Quest?",a="Die Ereignisse spielen sich vollständig im Laubschattental ab, dem geschützten Tal der Nachtelfen hoch oben in der Krone Teldrassils.",al={"wo ist ein freund in der not","iverrons aufenthaltsort"}},{q="Was geschieht, nachdem Dirania von Iverrons Zustand erfahren hat?",a="Nachdem Dirania von Iverrons Zustand erfahren hat, beginnt sie, ein Heilmittel zuzubereiten. Sie schickt Abenteurer durch den Hain, um seltene Reagenzien für ein Gegengift zu sammeln, bevor das Gift ihn tötet.",al={"was kommt nach ein freund in der not","wird iverron gerettet"}},{q="Warum gibt es tödliche Spinnen im Laubschattental?",a="Das Laubschattental bietet jungen Nachtelfen Schutz, doch die Verderbnis, die sich über Teldrassil ausbreitet, hat wilde Tiere und Ungeziefer, darunter Webwood-Spinnen, zu ungewöhnlich aggressiven und giftigen Raubtieren gemacht.",al={"warum gibt es spinnen im laubschattental","spinnen verderbnis teldrassil"}}},fx={c3a2deab={q="Warum möchte Iverron, dass dies erledigt wird?",a="Iverron wurde von der giftigen Webwoodspinne Githyiss die Niederträchtige gebissen, während er eine nahe gelegene Höhle erkundete. Das tödliche Gift breitet sich schnell in seinen Adern aus und macht ihn schwach, schwindelig und lässt ihn um sein Leben fürchten. Da er weiß, dass er das Leiden nicht alleine heilen kann, benötigt er dringend das Eingreifen von Dirania Silberschein, bevor das Gift ihn vollständig überwältigt.",al={"warum braucht iverron hilfe","beweggrund von iverron","was ist mit iverron passiert"}},b12cb73c={q="Warum benötigt Iverron Euch, anstatt selbst Hilfe zu suchen?",a="Das Gift von Githyiss die Niederträchtige hat Iverron schwer getroffen, was ihn völlig desorientiert und kaum in der Lage sein lässt, zu stehen. Allein in der Wildnis gestrandet, kann er den Rückweg nach Aldrassil nicht antreten, ohne zusammenzubrechen. Ihr seid der einzige fähige Reisende, der ihn rechtzeitig gefunden hat, um zurückzueilen und Diranias Hilfe zu rufen.",al={"warum kann iverron nicht selbst gehen","warum ich a friend in need","warum holt iverron keine wachen"}}},fp="16,156,18.223.0,19.218.0,15.182.0,22.100.0,27.165.0,33.105.0,60.180.1,47.194.0"}
P.entries["quest:3520"] = {n="Kreischergeister",s="Am Dampfdruckpier bittet Euch Yeh'kinya, die Geister der Talschreier von Feralas zu sammeln. Sie sind mit einem uralten Gott verwandt, und er verspricht, Euch mehr zu erzählen, wenn Ihr drei Essenzen zurückbringt.",h="Am Dampfdruckpier bittet Euch Yeh'kinya, die Geister der Talschreier von Feralas zu sammeln.",kw={"dornenrute","feralas","kreischergeister","dampfdruckpier","tanaris","talschreier","yeh'kinya"},sec={{t="Geister von Feralas",b="Yeh'kinya sagt, die Talschreier von Feralas seien mit einem uralten Gott verwandt. Ihre Geister sind mit ihm verbunden. Er gibt Euch eine Dornenrute und schickt Euch in den Süden und das Zentrum von Feralas. Schwenkt sie über einem gefallenen Talschreier, um seinen Geist hervorzulocken, und berührt dann den Geist, um seine Essenz zu sammeln. Er möchte drei Essenzen zusammen mit der Dornenrute zurückerhalten."},{t="Was Yeh'kinya erzählt",b="Yeh'kinya nennt den alten Gott Hakkar the Soulflayer. Eine uralte Prophezeiung der Trolle sagt die Rückkehr des toten Gottes in die Welt voraus. Einige erwarten, dass seine Rückkehr den Trollen Ruhm und Freude bringt; andere fürchten, dass sie allem ein Ende setzt. Yeh'kinya schenkt dem Mythos keinen Glauben, weiß aber, dass Hakkars Essenz mächtig ist und nicht in die falschen Hände geraten sollte."}},faq={{q="Wer vergibt diese Quest und wo?",a="Yeh'kinya erteilt Euch den Auftrag am Dampfdruckpier.",al={"wer vergibt kreischergeister","yehkinya standort","wo ist yehkinya"}},{q="Wo sind die Talschreier?",a="Talschreier leben im Süden und im Zentrum von Feralas.",al={"wo kreischer finden","kreischer standort","wo sind kreischer in feralas"}},{q="Wie fangt Ihr die Kreischergeister ein?",a="Schwenkt Yeh'kinyas Dornenrute über einem gefallenen Talschreier, um seinen Geist hervorzulocken. Berührt dann den Geist, um seine Essenz zu sammeln.",al={"wie kreischergeist erhalten","yehkinyas dornenrute benutzen","dornenrute"}},{q="Warum will Yeh'kinya Kreischergeister?",a="Yeh'kinya sagt, die Talschreier seien mit einem uralten Gott verwandt und ihre Geister mit ihm verbunden. Er verspricht, Euch bei Eurer Rückkehr mehr über den Gott zu erzählen.",al={"warum kreischergeister sammeln","yehkinyas beweggrund"}}},fp="17,191,18.337.0,21.335.1,40.40.0,30.53.0,41.127.0,42.158.0"}
P.entries["quest:3521"] = {n="Iverrons Gegengift",s="Im Laubschattental muss Iverrons Gegengift gebraut werden, bevor das Gift im Körper eines Spähers seine volle Wirkung entfaltet. Dirania Silberschein braucht wilde Pilze, Lilien und Spinnensekret, um das Heilmittel herzustellen.",h="Im Laubschattental muss Iverrons Gegengift gebraut werden, bevor das Gift im Körper eines Spähers seine volle...",kw={"aldrassil","gegengift","dirania silberschein","hyazinthpilz","iverron","mondblütenlilie","laubschattental","schattenweberhöhle","waldwebersekret"},ang={["class:Druid"]="Als Druide spiegeln das Herstellen von Heilmitteln aus heimischen Pflanzen und das Bekämpfen natürlicher Gifte das Gleichgewicht wider, das Ihr in der Wildnis bewahren wollt.",["profession:Herbalism"]="Als Kräuterkundiger erkennt Ihr, welche Heilkraft Teldrassils wilde Pflanzen bei sorgfältiger Verarbeitung entfalten. Mondblütenlilien und Hyazinthpilze sind Beispiele dafür.",["race:NightElf"]="Als Nachtelf ist es Eure heilige Pflicht im Laubschattental, Euch um gefallene Angehörige Eures Volkes zu kümmern. Jeder Verteidiger wird gebraucht, um den frisch austreibenden World Tree zu schützen."},sec={{t="Ein Wettlauf gegen das Gift",b="Der junge Iverron kundschaftete das Geäst des Laubschattentals aus, als Webwood-Spinnen ihn mit ihren giftigen Fängen verletzten. Nun liegt er zusammengebrochen im Sterben und ist auf Dirania Silberscheins Kräuterwissen bei Aldrassil angewiesen. Das Gift breitet sich rasch in ihm aus, also muss sie ein Heilmittel zubereiten, bevor es seine volle Wirkung entfaltet."},{t="Reagenzien des Laubschattentals",b="Dirania setzt Teldrassils heilende Pflanzen gegen das Gift der Spinnen ein. Hyazinthpilze, die bei den diebischen Grell im Süden beliebt sind, bilden eine erdige Grundlage. Mondblütenlilien aus stillen Waldtümpeln verleihen reinigende Eigenschaften. Sie braucht auch Waldwebersekret von Spinnen nahe der Schattenweberhöhle, um das Heilmittel auf deren Gift abzustimmen."}},faq={{q="Wer ist Iverron?",a="Iverron ist ein junger Nachtelfenspäher im Laubschattental. Er wagte sich zu nahe an die feindseligen Webwood-Spinnen heran, und ihr Gift streckte ihn nieder.",al={"iverron","wer ist iverron","wer hat ihn vergiftet"}},{q="Wer vergibt die Quest Iverrons Gegengift?",a="Dirania Silberschein erteilt den Auftrag und braut das Heilmittel. Sie steht außerhalb des mächtigen Geästs von Aldrassil im Laubschattental.",al={"questgeber","dirania","dirania silberschein"}},{q="Warum braucht das Gegengift Spinnensekret?",a="Traditionelle Kräuterheilmittel verwenden etwas von den Körperflüssigkeiten oder dem Gift einer Kreatur, um den Giftstoffen in ihrem Opfer entgegenzuwirken. Mit Waldwebersekret kann Dirania das Heilmittel also auf das Gift der Spinnen abstimmen.",al={"warum spinnensekret","waldwebersekret verwendung","spinnengift heilmittel"}},{q="Wo findet man Hyazinthpilze?",a="Hyazinthpilze wachsen am Fuß großer Bäume im gesamten Laubschattental. Man kann sie auch den Grell entreißen, die sie im Süden horten.",al={"wo hyazinthpilze finden","hyazinthpilz fundort"}},{q="Wo wachsen Mondblütenlilien?",a="Mondblütenlilien blühen an den Ufern stiller Süßwassertümpel auf der Nordwestseite von Aldrassil.",al={"mondblütenlilie fundort","wo sind lilien"}},{q="Wo befinden sich die Webwood-Spinnen?",a="Webwood-Spinnen leben in den nördlichen Wäldern des Laubschattentals, besonders nahe dem dunklen Eingang zur Schattenweberhöhle.",al={"webwood-spinnen fundort","spinnen fundort laubschattental"}}},fx={["77bb41e6"]={q="Warum möchte Dirania Silberschein, dass dies erledigt wird?",a="Dirania weiß, wie man ein Heilmittel braut, das das tödliche Gift, das durch Iverrons Körper fließt, neutralisieren kann. Ohne schnelles Eingreifen wird sich sein Zustand verschlechtern, und sie verlässt sich auf Eure Geschwindigkeit, um die notwendigen Waldzutaten zu sammeln, bevor es zu spät ist, ihn zu retten.",al={"beweggrund von dirania silberschein","warum iverron helfen","warum das gegenmittel herstellen"}},d7eaa833={q="Wofür wird der Hyazinthpilz verwendet?",a="Hyazinthpilze sind einheimische Pilze, die unter den großen Ästen von Laubschattental wachsen. Dirania verwendet sie als primäre pflanzliche Komponente, um das Gegenmittel zu brauen, das die härteren Gifte ausgleicht und das Toxin neutralisiert, das in Iverrons Körper eingedrungen ist.",al={"zweck des hyazinthpilzes","warum hyazinthpilz","wissen zum hyazinthpilz"}},ece05283={q="Wofür wird die Mondblütenlilie verwendet?",a="Mondblütenlilien sind zarte Wasserblüten, die an den ruhigen Waldteichen von Laubschattental gedeihen. Dirania mischt sie in ihr Heilmittel, um ihre beruhigenden natürlichen Eigenschaften zu nutzen und dem bösartigen Spinnengift entgegenzuwirken.",al={"zweck der mondblütenlilie","warum mondblütenlilie","wissen zur mondblütenlilie"}}},fp="18,171,20.278.0,22.331.0,15.136.0,39.126.0,40.186.0,35.157.0,31.98.0,38.109.0"}
P.entries["quest:3522"] = {n="Iverrons Gegengift",s="In Laubschattental wartet Iverron auf Heilung, bevor das Gift seine Wirkung entfaltet. Webwood-Spinnen haben den Nachtelfenspäher vergiftet, und Dirania Silberscheins Gebräu muss ihn innerhalb von fünf Minuten erreichen.",h="In Laubschattental wartet Iverron auf Heilung, bevor das Gift seine Wirkung entfaltet.",kw={"gegengift","dirania silberschein","iverron","laubschattental","teldrassil","gift","webwood-spinne"},ang={["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass sich unverarbeitete Waldpflanzen oft schwer verarbeiten lassen. Ohne die richtige Konservierung verlieren ihre Gebräue schnell ihre lebenswichtigen Eigenschaften.",["race:NightElf"]="Als junger Nachtelf in der Ausbildung in Laubschattental seht Ihr Iverrons Rettung als ernüchterndes Zeichen der Verderbnis und Aggression, die sich unter Teldrassils heimischen Wildtieren regen."},sec={{t="Ein Wettlauf gegen die Zeit",b="Dirania Silberschein stellt das Heilmittel aus frischen Giftsäcken, Lilienwurzeln und Hyazinthenpilzen her. Nach der Destillation behält das instabile Gebräu seine Wirksamkeit nur fünf Minuten lang. Bringt die Phiole ohne Verzögerung von der Lichtung direkt zu den nördlichen Anhöhen."},{t="Ständig in Schwierigkeiten",b="Webwood-Spinnen nahe den Grabhügeln und Höhlen von Laubschattental haben Iverron vergiftet. Er gibt zu, oft in Gefahr zu geraten, und verlässt sich darauf, dass Diranias Kräuterkunde ihn rettet. Selbst nachdem er das Gegengift getrunken hat, bleibt er schwach. Feindselige Spinnen bewachen noch immer seinen Heimweg, und er fürchtet sie."}},faq={{q="Warum gibt es eine Zeitbegrenzung für die Lieferung des Gegengifts?",a="Dirania Silberscheins Gegengift verliert schnell seine Heilkraft, weil es aus frischen Pflanzen und Gift hergestellt wird. Iverron muss es innerhalb von fünf Minuten trinken, nachdem es ihre Obhut verlassen hat.",al={"warum fünf minuten","gegengift zeitlimit","quest mit zeitlimit"}},{q="Wo befindet sich Iverron?",a="Iverron wartet an den Felsen vor der nördlichen Höhle von Laubschattental, nördlich des Hauptwegs durch den Hain.",al={"wo ist iverron","iverron aufenthaltsort","iverron finden"}},{q="Wie wurde Iverron vergiftet?",a="Webwood-Spinnen haben Iverron vergiftet. Sie leben am nördlichen Rand von Laubschattental und haben sich rund um Teldrassils Wurzeln und Höhlen vermehrt.",al={"wer hat iverron vergiftet","warum ist iverron krank","iverron gift"}},{q="Was geschieht, nachdem Iverron das Gegengift getrunken hat?",a="Das Gegengift neutralisiert das Gift, doch Iverron bleibt zu schwach und erschüttert, um allein sicher zu reisen. Er bittet um Hilfe dabei, die nahen Webwood-Spinnen zu beseitigen, die ihm den Weg in Sicherheit versperren.",al={"wie geht es mit iverron weiter","nach iverrons gegengift","iverron folgequest"}},{q="In welcher Beziehung stehen Dirania und Iverron zueinander?",a="Dirania Silberschein ist eine Kräuterkundige und Heilerin in Laubschattental, die Iverron oft aus Schwierigkeiten rettet. Er gibt zu, immer wieder in Gefahr zu geraten, und Dirania hilft ihm stets aus der Klemme.",al={"dirania und iverron","wer ist dirania für iverron","sind sie freunde"}},{q="Was geschieht, wenn das Gegengift abläuft, bevor es ihn erreicht?",a="Wenn das Gebräu verdirbt, bevor es Iverron erreicht, holt Euch eine frische Dosis von Dirania Silberschein in Laubschattental und lauft erneut los.",al={"gegengift abgelaufen","zeitlimit überschritten","gegengift verloren"}}},fx={b60b9a13={q="Warum möchte Dirania Silberschein, dass Ihr das Gegenmittel überbringt?",a="Iverron ist in der Wildnis von Laubschattental einem tödlichen Spinnengift zum Opfer gefallen und wird ohne sofortiges Eingreifen sterben. Dirania Silberschein hat das Heilmittel bereits vorbereitet, aber die Mischung ist instabil und wird schnell verderben, wenn sie nicht unverzüglich verabreicht wird. Sie sorgt sich um Iverron und hilft ihm routinemäßig aus Schwierigkeiten, was Eure schnelle Lieferung zu einer Frage von Leben und Tod macht.",al={"beweggrund von dirania silberschein","warum iverron helfen","warum will dirania, dass dies erledigt wird"}}},fp="18,187,24.248.0,18.273.0,53.180.0,25.99.0,25.135.0,47.183.1,46.178.0,57.123.0"}
P.entries["quest:3523"] = {n="Scourge of the Downs",s="Belnistrasz bittet Euch um Hilfe und gibt Euch einen Oathstone. Ihr könnt zustimmen und ihn zu ihm zurückbringen.",h="Belnistrasz bittet Euch um Hilfe und gibt Euch einen Oathstone.",kw={"hilfe","belnistrasz","oathstone","zurückgeben","scourge of the downs"},faq={{q="Wer bittet um Hilfe?",a="Belnistrasz bittet Euch, ihm zu helfen.",al={"wer ist belnistrasz","hilfe für belnistrasz"}},{q="Was gibt Belnistrasz Euch?",a="Belnistrasz gibt Euch einen Oathstone.",al={"was ist der oathstone","oathstone"}},{q="Was soll ich mit dem Oathstone tun?",a="Wenn Ihr zustimmt, Belnistrasz zu helfen, sprecht erneut mit ihm und gebt ihm den Oathstone zurück.",al={"oathstone zurückgeben","stein zurückgeben"}}},fp="20,93,18.32.0,31.35.0,32.80.0"}
P.entries["quest:3524"] = {n="An Land gespült",s="An der Dunkelküste werden immer mehr Meereskreaturen angespült. Gwennyth Bly'Leggonde untersucht die Todesfälle von Auberdine aus für den Tempel des Mondes in Darnassus, wo Priesterinnen in den Strandungen ein böses Omen fürchten.",h="An der Dunkelküste werden immer mehr Meereskreaturen angespült.",kw={"auberdine","dunkelküste","darnassus","greymist-murlocs","gwennyth bly'leggonde","meereskreaturknochen","tempel des mondes","an land gespült"},ang={["class:Druid"]="Als Druide könnt Ihr das Massensterben der Meereslebewesen als Warnung vor einem gestörten ökologischen Gleichgewicht an Kalimdors Küste deuten, die wachsame Aufmerksamkeit verlangt.",["class:Priest"]="Als Priester wisst Ihr, dass die Sisterhood of Elune spirituelle Omen und Ungleichgewichte in der Natur deuten muss. Gwennyth versucht, diese Zeichen in den Überresten der Meereskreatur zu entschlüsseln.",["race:NightElf"]="Die Strandungen stören das Gleichgewicht der Dunkelküste. Die Sisterhood of Elune greift von Darnassus aus direkt ein."},sec={{t="Ein beunruhigendes Omen",b="Gewaltige Meereskreaturen sind bisweilen an der Dunkelküste gestrandet. Es ist ein tragischer Anblick, doch bisher kam es nur gelegentlich vor. Nun werden immer mehr von ihnen entlang der Küste angespült. Die Priesterinnen von Elune im Tempel des Mondes fürchten, diese Todesfälle könnten böse Omen für das nördliche Kalimdor bringen."},{t="Aasfresser der Untiefen",b="Der Tempel des Mondes schickt die Gelehrte Gwennyth Bly'Leggonde in die Hafenstadt Auberdine, um zu ergründen, warum die gewaltigen Bestien an Land kommen. Von dort aus sammelt sie biologische Proben, die sie per Hippogryph zur genauen Untersuchung nach Darnassus schickt. Greymist-Murlocs umschwärmen die Kadaver in der Brandung und plündern die Überreste. Ohne bewaffneten Schutz können Forscher die Knochen nicht erreichen."}},faq={{q="Warum werden riesige Meereskreaturen an der Dunkelküste angespült?",a="Der Tempel des Mondes untersucht noch immer, warum riesige Meereskreaturen an der Dunkelküste angespült werden. Solche Strandungen kommen gelegentlich vor, doch ihre plötzliche Zunahme lässt nachtelfische Gelehrte eine tiefere Störung oder ein böses Omen unter dem Großen Meer fürchten.",al={"warum gestrandete kreaturen","strandungen von meereskreaturen","sterbende meeresbestien"}},{q="Wer ist Gwennyth Bly'Leggonde?",a="Gwennyth Bly'Leggonde ist eine Forscherin, die vom Tempel des Mondes aus Darnassus entsandt wurde. Von Auberdine aus erfasst sie Auffälligkeiten an der Küste und sammelt Proben gestrandeter Leviathane, die sie der Priesterschaft zur Untersuchung schickt.",al={"gwennyth","wer ist gwennyth bly'leggonde"}},{q="Wo liegt die Kreatur südlich von Auberdine?",a="Die Knochen der Kreatur liegen am Ufer, einen kurzen Marsch südlich der Anlegestege von Auberdine. Greymist-Murlocs umringen den gewaltigen Kadaver in der Brandung und bewachen ihn.",al={"fundort der kreatur","fundort der meereskreaturknochen","wo ist die gestrandete bestie"}},{q="Was wird Darnassus mit den Meereskreaturknochen tun?",a="Hippogryphen bringen die Knochen direkt nach Darnassus. Gelehrte und Priesterinnen im Tempel des Mondes untersuchen Mark, Struktur und Verwesungsspuren, um herauszufinden, ob Krankheit, finstere Magie oder unnatürliche Bejagung die Bestie an Land trieben.",al={"warum knochen sammeln","zweck der meereskreaturknochen","darnassus knochen"}},{q="Warum haben sich die Greymist-Murlocs um den Kadaver versammelt?",a="Die Greymist-Murlocs nutzen die gestrandeten Riesen als leicht zugängliche Quelle für Nahrung, Werkzeuge und Knochenarbeiten. Sie beanspruchen die Kadaver für sich, sodass eine unbewaffnete Annäherung für Gelehrte lebensgefährlich ist.",al={"murlocs beim wal","warum murlocs um die kreatur"}},{q="Endet diese Untersuchung, nachdem die ersten Knochen geborgen wurden?",a="Nein. Der Kadaver südlich der Stadt ist der erste Fundort. Gwennyth setzt ihre Forschungen mit weiteren Untersuchungen anderer Leviathane fort, die entlang der langen, nebelverhangenen Dunkelküste gestorben sind.",al={"ist dies eine questreihe","an land gespült fortsetzung"}}},fx={d10a93c6={q="Warum möchte Gwennyth Bly'Leggonde, dass dies erledigt wird?",a="Gwennyth wurde vom Tempel des Mondes in Darnassus entsandt, um einen alarmierenden Anstieg riesiger Seebestien zu untersuchen, die an der Dunkelküste stranden. Sie betrachtet diesen plötzlichen Anstieg der Strandungen als böses Omen für die Region und benötigt dringend Skelettüberreste, damit Gelehrte in der Hauptstadt feststellen können, was diese majestätischen Kreaturen an Land treibt.",al={"beweggrund von gwennyth","warum gwennyth helfen","warum gestrandete kreaturen untersuchen"}},a35c5129={q="Warum kann Gwennyth die Meereskreaturknochen nicht selbst sammeln?",a="Obwohl Gwennyth eine fähige Forscherin für den Tempel des Mondes ist, fehlt ihr die kampfkräftige Stärke, um sich einen Weg an den aggressiven Graunebel-Murlocs vorbeizukämpfen, die die Küste bevölkern. Die örtlichen Sentinels haben alle Hände voll damit zu tun, Auberdine selbst zu schützen, also verlässt sie sich auf reisende Abenteurer, um Proben aus den befallenen Gewässern zu bergen.",al={"warum braucht mich gwennyth","warum kann gwennyth keine knochen sammeln","warum einen abenteurer schicken"}}},fp="13,224,17.285.0,26.369.0,52.249.0,29.220.0,47.155.0,51.234.0,57.177.0,73.185.0"}
P.entries["quest:3525"] = {n="Extinguishing the Idol",s="Belnistrasz bittet Euch, zum Götzen der Quilboar in den Hügeln der Klingenhauer vorzudringen. Er will ein Ritual vollziehen, um ihn außer Kraft zu setzen.",h="Belnistrasz bittet Euch, zum Götzen der Quilboar in den Hügeln der Klingenhauer vorzudringen.",kw={"belnistrasz","götze","quilboar","hügel der klingenhauer","ritual","außer kraft setzen"},sec={{t="Der Götze",b="In den Hügeln der Klingenhauer braucht Belnistrasz Euch an seiner Seite beim Götzen der Quilboar. Ihr sollt ihn dorthin eskortieren und beschützen, während er ein Ritual vollzieht, um ihn außer Kraft zu setzen. Das Ritual soll die fortwährende Präsenz des Götzen beenden."}},faq={{q="Wer ist Belnistrasz?",a="Belnistrasz ist derjenige, den Ihr zum Götzen der Quilboar in den Hügeln der Klingenhauer eskortiert.",al={"belnistrasz","wer ist belnistrasz","belnistrasz quest"}},{q="Was möchte Belnistrasz tun?",a="Belnistrasz plant, ein Ritual zu vollziehen, um den Götzen der Quilboar außer Kraft zu setzen.",al={"was macht belnistrasz","götzenritual","götzen außer kraft setzen"}},{q="Wo befindet sich der Götze?",a="Der Götze der Quilboar befindet sich in den Hügeln der Klingenhauer.",al={"standort des götzen","wo ist der götze","quilboar-götze"}},{q="Warum muss ich Belnistrasz begleiten?",a="Ihr sollt Belnistrasz zum Götzen eskortieren und ihn während seines Rituals beschützen.",al={"warum ihn eskortieren","belnistrasz beschützen","was soll ich tun"}}},fp="22,116,8.226.0,19.75.0,33.71.0,18.41.0,37.82.0"}
P.entries["quest:353"] = {n="Sturmlanzes Lieferung",s="Grimand Elmore schickt Reisende mit einer Axt für Gebirgsjäger Gringer Stormpike nach Norden. Vom Zwergendistrikt in Sturmwind führt der Weg zu einem Außenposten von Eisenschmiede in Loch Modan.",h="Grimand Elmore schickt Reisende mit einer Axt für Gebirgsjäger Gringer Stormpike nach Norden.",kw={"axt","elmore","grimand","gringer","wachturm","loch modan","gebirgsjäger","stormpike"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, militärische Güter zwischen Sturmwind und den Gebirgsaußenposten zu transportieren. Menschen und Zwerge sind dort aufeinander angewiesen.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr das Können in Grimand Elmores Arbeit. Die Gebirgswachen schätzen seine zwergischen Metallarbeiten so sehr, dass sie diese über Königreichsgrenzen hinweg bestellen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Stormpikes unter Euresgleichen hohes Ansehen genießen. Einem anderen Gebirgsjäger an den wilden Grenzen von Loch Modan zu helfen, stärkt die Bande des Klans."},sec={{t="Eine Waffe für den Norden",b="Grimand Elmore wurde gebeten, eine Axt für Gebirgsjäger Gringer Stormpike zu fertigen. In Eisenschmiede genießt der Klan Stormpike wegen seines anspruchsvollen Geschmacks und seines kriegerischen Stolzes hohes Ansehen. Elmore vertraut Reisenden die Waffe an, damit sie sie von Sturmwind nach Norden in die Grenzlande der Zwerge bringen."},{t="Auf Wacht in Loch Modan",b="Am nördlichen Wachturm von Loch Modan bewacht Gebirgsjäger Sturmlanze Ländereien, die von umherstreifenden Troggs und grabenden Kobolden heimgesucht werden. Gerüchte über Unruhen und Banditentum erreichen die südlichen Menschenkönigreiche, während das Grenzland der Zwerge seine eigenen Gefahren birgt. Stormpike braucht eine neue Klinge, um die Gebirgspässe zu sichern."}},faq={{q="Wer ist Gebirgsjäger Sturmlanze?",a="Gringer Stormpike ist ein Gebirgsjäger aus Eisenschmiede und gehört dem angesehenen Klan Stormpike an. Er ist am nördlichen Wachturm von Loch Modan stationiert und verteidigt die Talstraße gegen Troggs und örtliche Bedrohungen.",al={"gringer stormpike","wer ist stormpike","gebirgsjäger gringer stormpike"}},{q="Was ist in dem Paket?",a="Das Paket enthält eine eigens angefertigte Zwergenaxt, die Grimand Elmore geschmiedet hat. Gebirgsjäger Sturmlanze hat sie für den Einsatz gegen Troggs und Kobolde in Loch Modan in Auftrag gegeben.",al={"was liefere ich","stormpikes paketinhalt","grimand elmores waffe"}},{q="Wo liefere ich das Paket ab?",a="Bringt das Paket zu Gebirgsjäger Sturmlanze am nördlichen Wachturm von Loch Modan, entlang der Straße durch die Hügel zu den nördlichen Gebirgsgrenzen.",al={"wo ist stormpike","gebirgsjäger sturmlanze finden","standort des wachturms in loch modan"}},{q="Warum kauft ein Zwerg in Loch Modan Waffen aus Sturmwind?",a="Grimand Elmore ist ein geschickter zwergischer Waffenschmied im Zwergendistrikt von Sturmwind. Der Klan Stormpike schätzt feine Metallarbeiten, und Gringer hat Elmore trotz der Entfernung mit der Fertigung seiner Axt beauftragt.",al={"warum aus sturmwind kaufen","warum elmore","zwerg bestellt aus menschenstadt"}},{q="Wie hängt das mit Elmore's Task zusammen?",a="Diese Lieferung folgt auf Elmore's Task. Grimand Elmore bittet Reisende um einen weiteren Botendienst zwischen Sturmwind und Khaz Modan.",al={"elmores questreihe","quest vor sturmlanzes lieferung","diese quest beginnen"}},{q="Wie gelangen Reisende von Sturmwind nach Loch Modan?",a="Nehmt die Tiefenbahn vom Zwergendistrikt in Sturmwind nach Eisenschmiede. Folgt von den Great Gates aus der östlichen Hauptstraße durch die verschneiten Pässe von Dun Morogh und den Nordtorpass nach Loch Modan.",al={"wie nach loch modan gelangen","reise nach khaz modan","tiefenbahn nach loch modan"}}},fp="20,171,22.290.0,22.315.0,29.189.0,27.152.0,31.151.0,58.192.0,39.123.0,49.189.0"}
P.entries["quest:354"] = {n="Todesfälle in der Familie",s="In Brill sinnt Coleman Heller auf Rache an der Familie Agamand. Einst arbeitete er in ihren Mühlen und blieb während des Dritten Krieges, um ihr Anwesen zu verteidigen. Seine Arbeitsgefährten und ihre sturen Herren starben dort und erhoben sich dann als geistlose Knechte des Lichkönigs.",h="In Brill sinnt Coleman Heller auf Rache an der Familie Agamand.",kw={"agamand","agamands mühlen","brill","coleman heller","todesfälle in der familie","gregor agamand","nissa agamand","geißel","thurman agamand","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr dabei, gefährliche Befehlshaber der Geißel nahe Brill und den nördlichen Zugängen zur Unterstadt zu beseitigen.",["race:Undead"]="Als Untoter tragt Ihr den persönlichen Groll mit Euch, den viele Verlassene aus ihrem sterblichen Leben bewahrt haben. Lordaerons Fall hinterließ tiefe Wunden und Verbitterung gegenüber jenen, die sie ins Verderben führten."},sec={{t="Ein Erbe des Hochmuts",b="Vor dem Dritten Krieg waren die Agamands die reichste und einflussreichste Bauernfamilie in Tirisfal. Ihre Mühlen und fruchtbaren Weiden lieferten Getreide durch die Arbeit Dutzender Pachtbauern und Müller. Als die Seuche des Untodes Lordaeron durchzog, weigerte sich die Familie zu fliehen oder ihre angestammten Ländereien zu verlassen. Sie glaubten, ihre Steinmauern und treuen Arbeiter könnten die aus dem Osten heranrückenden Schrecken aufhalten."},{t="Der Preis der Treue",b="Coleman Heller und die anderen Arbeiter vertrauten den Beteuerungen ihrer Herren und blieben, um das Anwesen zu verteidigen. Die Geißel überwältigte sie. Die Agamands und ihre Arbeiter wurden niedergemetzelt und dort in den Untod erhoben, wo sie gefallen waren. Heller kam schließlich durch die Befreiung durch Sylvanas Windläufer frei. Die Patriarchen und Erben der Agamands blieben im geistigen Griff des Lichkönigs und streiften als geistlose Wächter der Geißel durch die verfallenen Mühlen."},{t="Bittere Vergeltung",b="Coleman Heller lebt heute in Brill und hegt noch immer Groll gegen die Herren, deren Hochmut ihn sein sterbliches Leben kostete. Auf der Suche nach Rache und innerem Frieden schickt er Champions der Verlassenen nach Agamands Mühlen, um Gregor, Nissa und Thurman Agamand zu vernichten. Er hofft, dass seine einstigen Herren hinter ihren verfaulenden Gesichtern genug Bewusstsein bewahrt hatten, um Schrecken zu empfinden, als ihr Unleben endete."}},faq={{q="Wer war die Familie Agamand?",a="Vor dem Fall Lordaerons waren die Agamands die reichsten und erfolgreichsten Landbesitzer in Tirisfal. Sie besaßen und betrieben Agamands Mühlen und beschäftigten zahlreiche Bauern und Müller aus der Gegend.",al={"wer sind die agamands","vorgeschichte der agamands","geschichte von agamands mühlen"}},{q="Warum ist Coleman Heller so wütend auf sie?",a="Coleman Heller arbeitete in ihren Mühlen. Als die Geißel kam, überredeten die Agamands ihre Arbeiter, zu bleiben und das Anwesen zu verteidigen, statt zu fliehen. Heller macht ihren adligen Hochmut für seinen Tod und Untod sowie den seiner Arbeitsgefährten verantwortlich.",al={"coleman hellers groll","warum hasst heller die agamands","hellers beweggrund"}},{q="Haben sich die Agamands den Verlassenen angeschlossen?",a="Nein. Coleman Heller und andere Verlassene kamen frei, doch die Agamands blieben unter der Kontrolle des Lichkönigs. Sie suchen noch immer als geistlose Diener der Geißel die verfallenen Mühlen der Familie heim.",al={"sind die agamands verlassene","warum gehören die agamands zur geißel","wer kontrolliert die agamands"}},{q="Welche Mitglieder der Familie Agamand müssen vernichtet werden?",a="Ihr werdet ausgesandt, Gregor Agamand, Nissa Agamand und Thurman Agamand zu jagen und dann ihre Überreste vom Familienanwesen zu sammeln, um ihre Vernichtung zu bestätigen.",al={"wer muss getötet werden","agamand ziele","welche agamands"}},{q="Wo liegen Agamands Mühlen?",a="Agamands Mühlen liegen im Norden von Tirisfal, nordwestlich von Brill. Verfallene Windmühlen und Bauernhäuser prägen das einst fruchtbare Anwesen, das nun von der Geißel verseucht ist.",al={"wo liegen agamands mühlen","agamand standort"}},{q="Was macht Coleman Heller mit ihren Überresten?",a="Coleman verlangt ihre Überreste, um ihre Vernichtung zu bestätigen. Sie lassen ihn mit seinem Groll aus dem sterblichen Leben abschließen und beweisen, dass die Herren ausgelöscht wurden, die ihn ins Verderben stürzten.",al={"warum überreste sammeln","heller überreste"}}},fx={["5fad58e7"]={q="Wen sollt Ihr in den Mühlen vernichten?",a="Ihr werdet ausgesandt, um die untoten Überreste der Familie Agamand zu vernichten: Gregor, Nissa und Thurman. Zu Lebzeiten besaßen sie die weitläufigen Agamands Mühlen und überzeugten ihre Arbeiter, zu bleiben und das Anwesen gegen die Geißel zu verteidigen. Ihr Widerstand scheiterte und die Familienmitglieder wurden als gedankenlose Sklaven des Lichkönigs wiedererweckt, die nun das Gelände heimsuchen, auf dem ihre Arbeiter umkamen.",al={"wer sind die ziele","wer sind die agamands","agamand-ziele"}}},fp="20,257,17.416.0,20.431.0,18.353.0,27.180.0,41.248.0,35.178.0,47.152.0,32.156.0,49.166.0"}
P.entries["quest:355"] = {n="Sprecht mit Sevren",s="In Brill ruft Magistrat Sevren Euch nach Coleman Hellers Abrechnung bei Agamands Mühlen nach Norden. Die Untoten dort bedrohen Brills nördliche Grenze.",h="In Brill ruft Magistrat Sevren Euch nach Coleman Hellers Abrechnung bei Agamands Mühlen nach Norden.",kw={"agamands mühlen","brill","coleman heller","magistrat sevren","sevren","the family crypt","the haunted mills","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, Brill zu verteidigen, die erste Verteidigungslinie vor Unterstadt. Wenn Ihr das Ackerland vor der Geißel sichert, schützt Ihr die Herrschaft der Horde im nördlichen Lordaeron.",["race:Undead"]="Als Untoter erlangt Ihr in Brill Anerkennung, indem Ihr Euch gegen die geistlosen Diener der Geißel bewährt. So gelangt Ihr von Gelegenheitsarbeiten zur unmittelbaren Verteidigung des Ortes unter Magistrat Sevren."},sec={{t="Von Rache zu Bürgerpflicht",b="Coleman Heller suchte Rache an seinen früheren Nachbarn, den Agamands, und schickte Reisende nach Norden, um die Untoten rund um deren Getreidemühlen zu töten. Als Ihr ihre Überreste zurückbrachtet, erkannte Coleman, dass sein Groll eine größere Gefahr aufgedeckt hatte. Auf dem Anwesen der Agamands nahe Brill wimmelt es noch immer von aggressiven Dienern der Geißel."},{t="Der Ruf des Magistrats",b="Magistrat Sevren wacht im Namen der Dunklen Fürstin über Brills zivile und militärische Sicherheit. Berichten zufolge habt Ihr tiefe Vorstöße in das heimgesuchte Ackerland überlebt. Nun schickt Sevren Euch zur Quelle des Befalls: der uralten Gruft der Familie Agamand."}},faq={{q="Warum schickt Coleman Heller mich zu Magistrat Sevren?",a="Coleman hat seine Rache an der auferstandenen Familie Agamand vollzogen, doch die Untoten bei den Mühlen bedrohen ganz Brill. Er hat Magistrat Sevren von Eurem Geschick im Kampf berichtet, und Sevren leitet nun Brills Verteidigung.",al={"warum zu sevren gehen","coleman hellers empfehlung","wer ist magistrat sevren"}},{q="Wo ist Magistrat Sevren zu finden?",a="Magistrat Sevren ist im Rathaus von Brill in Brill, Tirisfal, zu finden. Er leitet die örtlichen Angelegenheiten der Verlassenen.",al={"sevrens standort","wo ist magistrat sevren","sevren finden"}},{q="Welche Gefahr geht von Agamands Mühlen aus?",a="Agamands Mühlen liegen unmittelbar nördlich von Brill und sind weiterhin von geistlosen Dienern der Geißel befallen. Die Toten und ruhelosen Geister auf den Feldern könnten den Ort überrennen, wenn ihnen niemand Einhalt gebietet.",al={"gefahr bei agamands mühlen","warum sind die mühlen eine bedrohung"}},{q="Was geschieht nach dem Gespräch mit Magistrat Sevren?",a="Magistrat Sevren schickt Euch in die Gruft der Familie Agamand, um die tiefer verborgene Bedrohung durch die Geißel anzugreifen, die die Untoten an die Mühlen bindet.",al={"nächste quest nach sevren","was will sevren"}},{q="Muss ich für diese Quest sofort zu den Mühlen zurückkehren?",a="Ihr erstattet Sevren in Brill Bericht, um Colemans Hinweis nachzugehen, bevor Ihr den nächsten Auftrag in der Gruft annehmt.",al={"muss ich zu den mühlen zurück","geht es bei dieser quest nur ums reden"}},{q="Warum ist die Familie Agamand für Brill von Bedeutung?",a="Die Agamands waren wohlhabende Mühlenbesitzer und angesehene Nachbarn in Tirisfal. Nach ihrem Tod dient ihr Anwesen als befestigtes Aufmarschgebiet für die geistlosen Diener der Geißel.",al={"bedeutung der agamands","wer sind die agamands für brill"}}},fp="17,147,28.318.0,21.245.0,55.211.0,37.123.0,38.166.0,51.131.0,59.106.0,45.149.0"}
P.entries["quest:356"] = {n="Patrouille zur Rückendeckung",s="Am Bollwerk schickt Euch Todeswache Linnea los, um Tirisfals Ostflanke zu sichern. Schrecken der Geißel und verweilende Geister bedrohen Balnirs Bauernhof, die Straße und die Nachschublinien, die die Front versorgen.",h="Am Bollwerk schickt Euch Todeswache Linnea los, um Tirisfals Ostflanke zu sichern.",kw={"balnir","bleeding horror","das bollwerk","linnea","geißel","tirisfal","wandering spirit","zygand"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, Tirisfals östliche Verteidigungslinie zu halten und den unsicheren Stützpunkt der Horde im Norden der Östlichen Königreiche vor den untoten Legionen zu schützen.",["race:Undead"]="Als Verlassener hängt Euer Überleben von der rückwärtigen Verteidigung des Bollwerks ab. Die Vertreibung der Geißel von Balnirs Bauernhof hilft zu verhindern, dass der Lichkönig erneut nach Eurer Heimat greift."},sec={{t="Die Flanke des Bollwerks sichern",b="Das Bollwerk schützt Tirisfal vor der Seuche und den Armeen der Westlichen Pestländer. Todeswache Linnea wacht über die Verteidiger hinter der Grenze. Sie können keine Truppen entbehren, um Angriffe aus dem Rücken abzuwehren. Deshalb müssen alle Untoten, die den Engpass passieren, vernichtet werden, bevor sie die Nachschublinien zur Front kappen."},{t="Die Ruinen von Balnirs Bauernhof",b="Balnirs Bauernhof war einst ein bewirtschafteter Hof im östlichen Tirisfal, verfiel jedoch während des Dritten Krieges. Die Felder sind verseucht, und Bleeding Horrors und ruhelose Wandering Spirits finden in den verfallenden Ställen Unterschlupf. Die Säuberung des Bauernhofs verwehrt dem Lichkönig einen Ort, an dem er Truppen innerhalb Tirisfals sammeln kann. Sie hält auch die Straße für Verstärkungen der Horde offen."}},faq={{q="Warum ist diese Patrouille für das Bollwerk wichtig?",a="Das Bollwerk bewacht den schmalen Pass zwischen Tirisfal und den Westlichen Pestländern. Gelangen Untote der Geißel hinter die Befestigung, könnten die Verteidiger von beiden Seiten angegriffen werden und die Nachschublinien nach Brill und Unterstadt verlieren.",al={"warum patrouille zur rückendeckung","bedeutung des bollwerks","warum balnir sichern"}},{q="Wer befiehlt diese Mission?",a="Todeswache Linnea, die nahe der Straße nach Osten in die Plaguelands stationiert ist, befiehlt die Patrouille. Sie schickt Erfolgsmeldungen an Exekutor Zygand.",al={"wer vergibt patrouille zur rückendeckung","todeswache linnea"}},{q="Welche Kreaturen suchen Balnirs Bauernhof heim?",a="Bleeding Horrors und Wandering Spirits suchen Balnirs Bauernhof heim. Nekromantie belebt die Horrors wieder und näht sie zusammen, während die Geister einstige Bewohner waren, die während der ersten Eroberung durch die Geißel starben.",al={"gegner auf balnirs bauernhof","welche monster sind bei balnir","bleeding horror"}},{q="Wer ist Exekutor Zygand?",a="Exekutor Zygand ist ein hochrangiger Kommandant der Todeswache der Verlassenen mit Sitz in Brill. Er ist der Vorgesetzte von Todeswache Linnea.",al={"geschichte von exekutor zygand","wer ist zygand"}},{q="Warum geben die Verlassenen die Ostgrenze nicht einfach auf?",a="Wenn die Verlassenen das Bollwerk aufgeben, könnten die endlosen Horden der Geißel aus den Plaguelands ganz Tirisfal und die Tore von Unterstadt erreichen.",al={"warum das bollwerk verteidigen","warum an der grenze kämpfen"}}},fx={a47e493a={q="Warum benötigt Todeswache Linnea einen Abenteurer, anstatt die Patrouille selbst zu übernehmen?",a="Die Verteidiger, die am Bollwerk stationiert sind, sind überlastet, während sie die östliche Grenze gegen ständige Angriffe aus den Pestländern halten. Linnea und die Garnison können es sich nicht leisten, ihre befestigten Posten aufzugeben, um das Hinterland zu säubern, ohne die Hauptlinie zu schwächen. Sich an fähige Reisende zu wenden, ermöglicht es den Verlassenen, Infiltratoren hinter sich zu beseitigen und gleichzeitig eine ununterbrochene Verteidigungsmauer gegen die Geißel aufrechtzuerhalten.",al={"warum ich linnea","warum einen abenteurer für rear guard patrol schicken","warum macht linnea das nicht selbst"}}},fp="17,204,28.339.0,29.350.0,45.227.0,24.137.0,42.216.0,23.109.0,55.153.0"}
P.entries["quest:3566"] = {n="Erhebt Euch, Obsidion!",s="Als der Archäologe nach Luft ringt, erfahrt Ihr die Wahrheit: Die Rettung war eine Falle. Er fleht Euch an, ihn und Thorius zu rächen, indem Ihr Lathoric the Black und Obsidion tötet. Kurator Thorius in Eisenschmiede braucht Beweise.",h="Als der Archäologe nach Luft ringt, erfahrt Ihr die Wahrheit: Die Rettung war eine Falle.",kw={"kurator thorius","sterbender archäologe","eisenschmiede","lathoric the black","obsidion","ragnaros","erhebt euch obsidion","sengende schlucht"},sec={{t="Eine letzte Bitte",b="Der Archäologe kann kaum sprechen. Er keucht, dass alles eine Falle war, bittet um Vergebung und fleht Euch dann an, den Verräter für ihn und für Thorius zu töten. Lathoric the Black und Obsidion müssen beide fallen. Kurator Thorius in Eisenschmiede braucht Beweise: einen Kopf und ein Herz."},{t="Eine Stimme antwortet",b="Dorius nennt Euch Narren. Er nutzte die schwachen Gefühle seines Bruders aus und entsandte Retter, damit sie dem Schattenhammer den letzten Suntara-Stein abnehmen würden. An der Ausgrabungsstätte Grimesilt fand er die Suntara-Steine. Dann durchströmte ihn Ragnaros' Macht und gab ihm eine Bestimmung.\n\nNach Ragnaros' Willen wurde Obsidion erbaut, um die Schwarzfelsorcs der Schwarzfelsspitze zu vernichten. Als Akolyth des Feuers wiedergeboren, nahm Dorius den Namen Lathoric the Black an. In Eisenschmiede erbleicht Thorius angesichts der Beweise: Sein eigener Bruder hat all dies in Gang gesetzt und ihn und Eisenschmiede verraten. Thorius fürchtet, dass die Alten Götter hier noch immer großen Einfluss ausüben. Wenn ein so ehrenhafter Mann so leicht zu Ragnaros bekehrt werden konnte, ist niemand sicher."}},faq={{q="Wer vergibt diese Quest?",a="Ein sterbender Archäologe vergibt sie und fleht Euch an, ihn und Thorius zu rächen.",al={"questgeber","wer startet erhebt euch obsidion","sterbender archäologe"}},{q="Welche Quest kommt davor?",a="Release Them kommt davor.",al={"vorherige quest","voraussetzung","questreihe vor erhebt euch obsidion"}},{q="Wem bringt Ihr die Beweise?",a="Bringt die Beweise zu Kurator Thorius in Eisenschmiede. Er verlangt einen Kopf und ein Herz.",al={"wo abgeben","bei wem abgeben","wo ist thorius"}},{q="Wen sollt Ihr töten?",a="Ihr sollt Lathoric the Black und Obsidion töten.",al={"wer ist obsidion","wer ist lathoric","ziele"}}},fp="15,200,12.265.0,15.684.1,21.71.0,29.31.0,30.77.0,25.53.0"}
P.entries["quest:3567"] = {n="An die Spitze",s="Marli Wishrunner bietet Euch einen Ausblick von einem der Zwillingskolosse von Feralas, mit einer Warnung: Der Weg führt nur hinauf.",h="Marli Wishrunner bietet Euch einen Ausblick von einem der Zwillingskolosse von Feralas, mit einer Warnung...",kw={"kolosse","feralas","marli wishrunner","gipfel","an die spitze","die zwillingskolosse"},sec={{t="Nur hinauf",b="Marli Wishrunner kann Euch auf die Spitze eines der Zwillingskolosse von Feralas schicken, um die Aussicht zu genießen. Sie warnt Euch, darüber nachzudenken, wie Ihr wieder hinunterkommt. Die Reise geht nur in eine Richtung."}},faq={{q="Wer kann Euch auf die Spitze eines Kolosses schicken?",a="Marli Wishrunner, die Euch auf einen der Zwillingskolosse von Feralas schicken kann, um die Aussicht zu genießen.",al={"wer vergibt an die spitze","an die spitze questgeber","marli wishrunner"}},{q="Wohin führt diese Reise?",a="Ihr erreicht die Spitze eines der Zwillingskolosse.",al={"wohin schickt marli","ziel","an die spitze ort"}},{q="Bietet Marli einen Weg zurück nach unten?",a="Nein. Marli warnt, dass die Reise nur in eine Richtung geht, also überlegt Euch, wie Ihr wieder hinunterkommt.",al={"wie kommt man hinunter","gibt es eine rückreise","weg hinunter von den zwillingskolossen"}}},fp="10,113,10.170.0,42.90.0,29.47.0,35.89.0"}
P.entries["quest:357"] = {n="Die Identität des Lichs",s="Bethor Eismacht sucht den Namen des einsamen Lichs auf dem Blendwassersee. Er schickt einen Abgesandten, um das Zauberbuch des Lichs zu holen und seine Macht und Loyalität zu ergründen.",h="Bethor Eismacht sucht den Namen des einsamen Lichs auf dem Blendwassersee.",kw={"bethor eismacht","blendwassersee","verlassene","magieviertel","nekromant","sylvanas","das zauberbuch des lichs","unterstadt"},ang={["class:Mage"]="Als Magier seht Ihr, wie Bethor Eismacht im Magieviertel die magischen Traditionen Lordaerons und Dalarans fortführt, um das Überleben der Verlassenen zu sichern.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass mächtige Nekromanten deren nördliche Grenze gegen den Scharlachroten Kreuzzug und die Geißel stärken können.",["race:Undead"]="Als Verlassener wisst Ihr, dass die Befreiung unabhängiger Untoter beweist, dass Eure Loslösung von der Kontrolle des Lichkönigs kein einmaliges Wunder war. Ihre nekromantische Macht kann auch Sylvanas' Hof stärken."},sec={{t="Ein Einsiedler auf dem See",b="Ein einsamer Lich lebt im Exil auf einer kleinen Insel im Blendwassersee, nördlich von Unterstadt. Anders als die geistlosen Marionetten des Lichkönigs hat er einen freien Willen, doch Paranoia beherrscht ihn. Er glaubt, alle Untoten, die sich nähern, seien Knechte der Geißel, die ihn zurück in die Knechtschaft zerren sollen. Deshalb hetzt er beschworene Diener auf jeden, der sein Ufer betritt."},{t="Ein wertvoller Verbündeter",b="Kunde von dem abtrünnigen Lich erreicht Bethor Eismacht, den Erzmagier, der die Magier von Unterstadt beaufsichtigt. Bethor weiß, dass Fürstin Sylvanas Windläufer jeden Funken magischer Meisterschaft und jeden fähigen Willen sucht, um die Verlassenen gegen ihre vielen Feinde zu stärken. Um herauszufinden, ob sich der Einsiedler anwerben lässt, braucht Bethor Beweise für dessen Identität und nekromantisches Können."},{t="Ein alter Freund gefunden",b="Als das gestohlene Zauberbuch das Magieviertel erreicht, untersucht Bethor dessen arkane Schrift und erfährt die Identität des Lichs: Gunther Arkanus. Bevor die Seuche Lordaeron verheerte, war Gunther ein talentierter Nekromant und Bethors enger Kamerad. Sein unabhängiger Wille und seine größere nekromantische Macht könnten dem Reich der Dunklen Fürstin helfen."}},faq={{q="Wer schickt Euch auf diese Mission?",a="Bethor Eismacht, ein mächtiger Magier der Verlassenen im Magieviertel von Unterstadt, schickt Euch.",al={"questgeber","bethor eismacht standort","wer vergibt die identität des lichs"}},{q="Warum greift der Lich jeden an, der sich ihm nähert?",a="Der Lich hat sich der Kontrolle des Lichkönigs entzogen, glaubt aber irrtümlich, alle anderen Untoten in Lordaeron seien weiterhin willenlose Knechte der Geißel. Er befiehlt seinen Dienern, jeden anzugreifen, der sich seiner Insel nähert, um seine Freiheit zu schützen.",al={"warum ist gunther feindselig","warum greift der lich an","blendwassersee lich feindselig"}},{q="Wo befindet sich das Lager des Lichs?",a="Der Lich lebt auf einer Insel im Blendwassersee in Tirisfal, direkt nördlich der Ruinen von Lordaeron und Unterstadt.",al={"wo ist der lich","blendwassersee insel","gunther arkanus standort"}},{q="Warum will Fürstin Sylvanas ihn in die Reihen der Verlassenen aufnehmen?",a="Fürstin Sylvanas sucht seltene Untote mit großer magischer Begabung und freiem Willen. Ein Nekromant mit freiem Willen und mächtiger Todesmagie könnte den Verlassenen im Kampf gegen die Geißel und den Scharlachroten Kreuzzug helfen.",al={"warum den lich anwerben","interesse der verlassenen an gunther","sylvanas lich"}},{q="Als wer entpuppt sich der Lich?",a="Bethor enthüllt, dass der Lich Gunther Arkanus ist, ein ehemaliger Magier aus Dalaran und geschickter Nekromant, der vor dem Dritten Krieg Bethors enger Kampfgefährte war.",al={"identität des lichs","wer ist der lich"}},{q="Was geschieht, nachdem Ihr das Zauberbuch abgeliefert habt?",a="Nachdem Bethor Gunthers Identität bestätigt hat, schickt er Euch mit dem Zauberbuch zurück zum Blendwassersee. Ihr sollt Gunther davon überzeugen, dass die Verlassenen frei sind und ihn willkommen heißen wollen.",al={"was kommt als nächstes","return the book quest","nach die identität des lichs"}}},fx={f276cf7d={q="Wozu dient das Zauberbuch des Lichs?",a="Das Zauberbuch gehört dem zurückgezogen lebenden Lich am Blendwassersee. Es enthält seine nekromantischen Arkanas und persönlichen magischen Signaturen. Bethor Eismacht benutzt es, um den Eremiten zu identifizieren und dessen nekromantische Fähigkeiten einzuschätzen, ohne ihn in ein direktes Gespräch verwickeln zu müssen.",al={"zauberbuch des lichs","zweck des lich-zauberbuchs","wofür ist das zauberbuch"}},e5299862={q="Wer ist der Lich am Blendwassersee?",a="Das Ziel ist ein mächtiger, willensfreier untoter Magier, der auf einer Insel im nördlich gelegenen Blendwassersee haust. Er misstraut jedem und glaubt, dass alle anderen Untoten noch immer willenlose Sklaven der Geißel sind. Folglich hat er sich mit beschworenen Dienern umgeben und weist jeden gewaltsam ab, der sich nähert.",al={"wer ist der lich","lich am blendwassersee","wem stehle ich das buch"}},["2f6ced1e"]={q="Warum möchte Bethor Eismacht das Zauberbuch des Lichs haben?",a="Bethor Eismacht versucht, den zurückgezogen lebenden untoten Magier im Namen der Dunklen Fürstin in den Schoß der Verlassenen zu bringen. Da der Lich jeden, der sich nähert, gewaltsam vertreibt, kann Bethor nicht einfach mit ihm sprechen. Er muss das Zauberbuch untersuchen, um die wahre Identität des Zauberers aufzudecken, das Ausmaß seiner nekromantischen Macht einzuschätzen und festzustellen, ob seine Talente der Sache der Verlassenen wirklich dienen können.",al={"beweggrund von bethor","warum will bethor das buch","warum das zauberbuch des lichs stehlen"}}},fp="19,154,21.337.0,16.351.0,19.318.1,30.86.0,51.235.0,33.123.0,58.192.0,33.155.1,45.178.1"}
P.entries["quest:358"] = {n="Grabräuber",s="Am Massengrab südwestlich von Garrens Schlupfwinkel graben Gnolle der Rot Hide zwischen den Toten. Magistrat Sevren schickt Euch los, um sie aufzuhalten und ihr Einbalsamierungssekret für die Königliche Apothekervereinigung zurückzubringen.",h="Am Massengrab südwestlich von Garrens Schlupfwinkel graben Gnolle der Rot Hide zwischen den Toten.",kw={"brill","einbalsamierungssekret","garrens schlupfwinkel","graverobbers","magistrat sevren","massengrab","rot hide","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, den Truppennachschub der Geißel aufzuhalten und den Norden Lordaerons zu sichern, und stärkt den Stützpunkt der Horde gegen die verbliebenen Streitkräfte des Lichkönigs.",["race:Undead"]="Als Verlassene helft Ihr, die Geißel daran zu hindern, Tirisfals einstige Bürger zu erheben und Eure gefallenen Landsleute zu willenloser Knechtschaft zu verdammen."},sec={{t="Schändung der Massengräber",b="Die Seuche des Untods fegte durch Tirisfal und hinterließ mehr Tote, als die Lebenden bestatten konnten. Im gesamten Norden hoben die Menschen gewaltige Massengräber für die zahllosen Opfer aus. Eine Zeit lang blieben die dort Bestatteten von der Wiederbelebung verschont.\n\nNun schickt die Geißel Gnolle der Rot Hide zu den Gräben südwestlich von Garrens Schlupfwinkel. Sie graben die Überreste aus, um die Armeen des Lichkönigs zu verstärken."},{t="Alchemie gegen die Geißel",b="Einbalsamierungssekret konserviert und belebt die verrottenden Leiber der Rot Hides. Magistrat Sevren schickt Euch los, um die Grabräuber zu töten und die Flüssigkeit zu bergen. So wird die Geißel daran gehindert, weitere Leichen zu sammeln, und die Apotheker in Brill erhalten Proben für ihre Forschungen.\n\nSie hoffen, die Alchemie des Lichkönigs gegen ihn selbst wenden zu können."}},faq={{q="Warum gräbt die Geißel das Massengrab auf?",a="Die Geißel gräbt Opfer des ersten Seuchenausbruchs in Tirisfal aus, um sie als Soldaten zu erheben und ihre Armeen gegen die Verlassenen zu verstärken.",al={"warum graben gnolle leichen aus","was will die geißel mit leichen","zweck des massengrabs"}},{q="Was sind die Gnolle der Rot Hide?",a="Die Gnolle der Rot Hide sind untote Gnolle, die von der Geißel versklavt wurden. Einbalsamierungssekret belebt und konserviert sie, und sie dienen als Aasfresser und Stoßtruppen rund um Garrens Schlupfwinkel und die benachbarten Gräber.",al={"geschichte der rot hide","untote gnolle tirisfal","was sind rot hides"}},{q="Wo liegt das Massengrab?",a="Das Massengrab liegt südwestlich von Garrens Schlupfwinkel, in den nördlichen Hügeln von Tirisfal, gleich nördlich von Brill.",al={"wo sind graverobbers","lage des massengrabs","garrens schlupfwinkel massengrab"}},{q="Was wollen die Verlassenen mit dem Einbalsamierungssekret?",a="Magistrat Sevren übergibt das gesammelte Sekret den Apothekern der Verlassenen. Sie erforschen, wie die Geißel ihre niederen Diener belebt und erhält, und suchen nach Schwachstellen, die sich im anhaltenden Krieg ausnutzen lassen.",al={"warum einbalsamierungssekret sammeln","wozu dient das sekret","geschichte des sekrets"}},{q="Wer befiehlt den Tod der Graverobbers?",a="Magistrat Sevren, der Aufseher der Verlassenen in Brill, befiehlt, die Grabräuber zu töten, um Tirisfals Grenzen zu verteidigen und nützliche Reagenzien für die Apotheker zu sichern.",al={"wer vergibt graverobbers","rolle von magistrat sevren"}},{q="Warum kümmert es die Verlassenen, wenn tote Seuchenopfer erhoben werden?",a="Die Geißel verwandelt jede Leiche, derer sie habhaft wird, in einen feindlichen Soldaten unter dem Willen des Lichkönigs und bedroht damit das frisch befreite Königreich der Verlassenen.",al={"warum schützen verlassene gräber","warum sind leichen wichtig"}}},fx={["9e6ccf32"]={q="Gegen wen werdet Ihr am Massengrab entsandt?",a="Ihr werdet entsandt, um die Rotkammgnolle – speziell die Graverobbers und Bastarde –, die Garrens Schlupfwinkel und das nahegelegene Massengrab heimsuchen, zu vernichten. Diese untoten Bestien agieren als niederträchtige Sklaven der Geißel, deren Aufgabe es ist, die zahllosen Opfer der ursprünglichen Seuche zu exhumieren, um die Reihen der Armeen des Lichkönigs direkt vor Brills Haustür zu verstärken.",al={"wer sind die feinde","was tun die rotkammgnolle","ziel der graverobbers"}}},fp="12,194,30.368.0,30.307.0,45.133.0,29.199.0,32.111.0,51.189.0,41.154.0,59.140.0"}
P.entries["quest:359"] = {n="Verlassenen-Pflichten",s="Magistrat Sevren braucht Nachricht von Tirisfals Ostgrenze. Er fürchtet, die Geißel könnte am Bollwerk vorbeischlüpfen und nahe Siedlungen bedrohen.",h="Magistrat Sevren braucht Nachricht von Tirisfals Ostgrenze.",kw={"balnirs bauernhof","brill","todeswache linnea","verlassenen-pflichten","magistrat sevren","geißel","das bollwerk","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass der Schutz Tirisfals vor Einfällen der Geißel einen verlässlichen Stützpunkt im nördlichen Lordaeron sichert.",["race:Undead"]="Als Untoter wisst Ihr, dass ein Grenzdurchbruch Brill und die jüngst von den Verlassenen beanspruchte Unterstadt bedroht."},sec={{t="Wachsamkeit an der Grenze",b="Magistrat Sevren wacht über Brill und das Umland und behält Tirisfals Ostgrenze mit wachsamen Augen im Blick. Die Geißel schwärmt durch die Westlichen Pestländer, daher müssen Wachposten berichten, was sie sehen. Sevren schickt Euch die Hauptstraße entlang nach Süden und dann nach Osten, um Todeswache Linneas Einschätzung einzuholen."},{t="Berichte von der Front",b="Todeswache Linnea überwacht die Grenze von einem Außenposten an der östlichen Straße aus. Ihr Bericht bestätigt Sevrens Befürchtungen. Das Bollwerk hält das Hauptheer der Geißel auf, doch kleine Gruppen schlüpfen manchmal an seinen Verteidigungsanlagen vorbei. Diese versprengten Truppen sammeln sich beim nahe gelegenen Balnirs Bauernhof und bedrohen Tirisfal."}},faq={{q="Wer vergibt die Quest Verlassenen-Pflichten?",a="Magistrat Sevren in Brill bittet Euch, einen aktuellen Bericht vom östlichen Außenposten der Deathguard einzuholen.",al={"wer vergibt verlassenen-pflichten","wer startet verlassenen-pflichten","sevren quest"}},{q="Wer ist Todeswache Linnea?",a="Todeswache Linnea ist an der Wegstation der Deathguard östlich von Brill stationiert. Sie überwacht die Straße und bewacht die Zugänge zu den Plaguelands.",al={"wer ist linnea","todeswache linnea standort","wo ist linnea"}},{q="Was ist das Bollwerk?",a="Das Bollwerk ist ein befestigter Grenzposten zwischen Tirisfal und den Westlichen Pestländern. Seine Verteidiger verhindern, dass die Geißel die Ländereien der Verlassenen überrennt.",al={"was ist das bollwerk","bollwerk verteidigung","warum ist das bollwerk wichtig"}},{q="Wo schlüpft die Geißel über die Grenze?",a="Kleine Gruppen der Geißel schlüpfen manchmal am Bollwerk vorbei und sammeln sich bei Balnirs Bauernhof östlich der Wegstation.",al={"geißel in tirisfal","balnirs bauernhof geißel","wo schlüpft die geißel durch"}},{q="Warum will Magistrat Sevren einen Lagebericht?",a="Magistrat Sevren will verhindern, dass die Geißel in Tirisfal fest Fuß fasst. Die Deathguard müssen wachsam bleiben.",al={"warum braucht sevren einen bericht","sevrens sorge"}},{q="Wie gelangt Ihr zu Todeswache Linneas Posten?",a="Folgt von Brill aus der Straße nach Süden und biegt dann an der Gabelung nach Osten in Richtung der östlichen Ausläufer Tirisfals ab.",al={"wo ist die wegstation","wie linnea erreichen"}}},fp="15,142,23.301.0,22.288.0,36.104.0,25.141.0,20.158.0,43.112.0,48.129.0,43.102.0"}
P.entries["quest:36"] = {n="Westfalleintopf",s="Banditentum vertreibt die Siedler von Westfall von ihren Höfen. Während sich die Furlbrows auf die Abreise vorbereiten, vertraut Verna Salma Saldean ihr geschätztes Rezept an.",h="Banditentum vertreibt die Siedler von Westfall von ihren Höfen.",kw={"kochen","bauer brauenwirbel","rezept","saldeans farm","salma saldean","eintopf","verna brauenwirbel","westfall"},ang={["profession:Cooking"]="Westfalleintopf ist Grenzlandkost für menschliche Siedler, zubereitet aus aufgetriebenem Präriewild und robustem Wurzelgemüse.",["race:Human"]="Als Mensch seht Ihr, wie die Landbevölkerung des Königreichs von ihren angestammten Höfen ins städtische Exil vertrieben wird, während Sturmwinds Grenzland zerfällt."},sec={{t="Ein weitergegebenes Rezept",b="Diebe der Defias und außer Kontrolle geratene mechanische Ernteschnitter haben Verna und Bauer Brauenwirbel vom Land ihrer Familie vertrieben. Sie beladen ihren Wagen und bereiten sich darauf vor, hinter Sturmwinds Mauern Zuflucht zu suchen. Vor ihrer Abreise gibt Verna ihrer Nachbarin Salma Saldean das Rezept für Westfalleintopf. Sie hofft, dass die heimische Kochtradition ihres Hofes weiterlebt."},{t="Zusammenhalt unter Siedlern",b="Salma Saldean und ihr Mann, Bauer Saldean, halten noch immer ihr Gehöft ein Stück die Straße hinunter. Vernas Rezept hält eine örtliche bäuerliche Tradition am Leben, während eine weitere Familie fortzieht. Salma macht sich daran, Zutaten zu sammeln, um jene zu ernähren, die im Grenzland noch immer ums Überleben kämpfen."}},faq={{q="Warum verlassen die Furlbrows ihren Hof?",a="Diebe der Defias und Banditen haben die Felder der Furlbrows zu gefährlich gemacht, um sie zu bewirtschaften. Verna und Bauer Brauenwirbel beladen ihren Wagen, um nach Sturmwind zu fliehen.",al={"warum furlough fortgeht","furlbrows verlassen westfall","warum verna packt"}},{q="Wer ist Salma Saldean?",a="Salma Saldean ist eine Siedlerin aus Westfall, die mit ihrer Familie auf Saldeans Farm lebt, gleich hinter der Weggabelung vom Gehöft der Furlbrows aus. Trotz der Gesetzlosigkeit um sie herum bewirtschaften sie weiterhin ihr Land.",al={"wer ist salma","salma saldean hintergrundgeschichte"}},{q="Was ist Westfalleintopf?",a="Westfalleintopf ist ein traditionelles regionales Gericht aus Zutaten, die überall in den Ebenen von Westfall zu finden sind, und wird unter den örtlichen Bauernfamilien geteilt.",al={"was ist westfalleintopf","westfalleintopf rezept"}},{q="Wohin wollen die Furlbrows ziehen?",a="Die Furlbrows ziehen nach Norden, um in Sturmwind Sicherheit zu finden. Vernas Freunde glauben, dass sie dort gut hineinpassen wird.",al={"wohin gehen die furlbrows","furlbrow reiseziel"}},{q="Wo liegt Saldeans Farm?",a="Saldeans Farm liegt gleich hinter der Gabelung der Hauptstraße, südlich des Kürbisfeldes der Furlbrows in Westfall.",al={"saldeans farm lage","wo ist salma saldean"}},{q="Gibt es bei dieser Quest das eigentliche Kochrezept als Belohnung?",a="Die schriftliche Anleitung zu Salma zu bringen, ist nur der erste Schritt. Um den Eintopf zuzubereiten, bittet sie um Hilfe beim Sammeln der Zutaten.",al={"rezept als belohnung","westfalleintopf rezept erhalten"}}},fx={["6757b659"]={q="Warum möchte Verna Brauenwirbel, dass ihr Eintopf-Rezept an Salma Saldean überbracht wird?",a="Da ihr Gehöft von Dieben und Banditen überrannt wurde, flieht Verna Brauenwirbel für immer aus Westfall. Bevor sie und ihr Mann die Landschaft zugunsten der Sicherheit von Sturmwind verlassen, möchte sie sicherstellen, dass ihr geliebtes Rezept für herzhaften Westfall-Eintopf in den Händen ihrer lieben Nachbarin und Mitbäuerin Salma Saldean bleibt.",al={"warum westfall-eintopfrezept liefern","verna brauenwirbels beweggrund","warum salma rezept geben"}},["5964e98d"]={q="Warum kann Verna Brauenwirbel das Rezept nicht selbst überbringen?",a="Die Straßen sind voller Defias-Banditen, was Reisen durch die Ebenen unsicher macht. Viel dringender ist jedoch, dass Verna und ihr Mann am Wegesrand festsitzen und darauf warten, dass Bauer Brauenwirbel ihren kaputten Wagen repariert, damit sie in Richtung Sturmwind fliehen können, was es ihr unmöglich macht, den Weg zu Saldeans Farm allein zurückzulegen.",al={"warum braucht verna mich","warum kann verna nicht liefern","verna lieferung warum ich"}}},fp="13,151,18.332.0,20.254.0,41.158.0,21.210.0,22.142.0,39.114.0,32.107.0,49.134.0"}
P.entries["quest:360"] = {n="Rückkehr zum Magistrat",s="In Brill erfährt Magistrat Sevren, dass die Diener des Lichkönigs weiter gegen die Grenze der Verlassenen vordringen. Todeswache Linnea sendet die Warnung aus dem Osten.",h="In Brill erfährt Magistrat Sevren, dass die Diener des Lichkönigs weiter gegen die Grenze der Verlassenen...",kw={"brill","das bollwerk","pflichten der verlassenen","linnea","geißel","sevren","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Tirisfal Euren Brückenkopf in den Östlichen Königreichen sichert. Das Bollwerk schützt ihn vor den Schrecken der Pestländer.",["race:Undead"]="Als Untoter wisst Ihr, wie zerbrechlich die Freiheit der Verlassenen noch immer ist. Der Herr, dem Ihr entkommen seid, rückt weiterhin gegen Eure neue Heimat vor."},sec={{t="Berichte von der Grenze",b="Östlich von Tirisfal führt die Straße zu den verseuchten Ruinen der Westlichen Pestländer, wo die Geißel herrscht. Die Verlassenen errichteten das Bollwerk, um die Untoten von ihrer Heimat fernzuhalten. Todeswache Linnea hält von einer Zwischenstation hinter der Frontlinie aus Wache und sammelt Berichte vom östlichen Tor. Dann schickt sie Boten auf dem Königsweg westwärts nach Brill, bevor feindliche Infiltratoren Lücken in der Verteidigung finden können."},{t="Sevrens Schwur",b="In Brill erfährt Magistrat Sevren, dass Kundschafter der Geißel Wege um die Frontlinie herum oder durch sie hindurch finden. Jeder kriechende Ghul und jedes geistlose Skelett erinnert an die Versklavung der Verlassenen, die mit dem Fall von Lordaeron endete. Sevren schwört, dass die freien Untoten ihre neu gewonnene Selbstbestimmung niemals aufgeben werden, wie unablässig der Lichkönig auch angreifen mag."}},faq={{q="Woher stammt dieser Bericht?",a="Todeswache Linnea sendet den Bericht von ihrer Zwischenstation östlich von Brill, an der Straße zum Bollwerk. Sie sammelt Nachrichten von den Barrikaden zwischen Tirisfal und den von der Geißel beherrschten Westlichen Pestländern.",al={"ursprung der quest","wer hat diesen bericht geschickt","wo ist linnea"}},{q="Warum beunruhigt diese Nachricht Magistrat Sevren?",a="Die Depesche warnt Sevren, dass Streitkräfte der Geißel an den Befestigungen des Bollwerks vorbeigelangt sind. Ihre Vorstöße bedrohen die jungen Städte der Verlassenen und erinnern an die Bemühungen des Lichkönigs, sie wieder unter seine Herrschaft zu zwingen.",al={"warum ist sevren besorgt","was steht im bericht","bedrohung durch die geißel"}},{q="Wer ist Magistrat Sevren?",a="Magistrat Sevren verwaltet Brill von dessen Rathaus aus. Er beaufsichtigt die örtliche Verteidigung, die Infrastruktur und die Musterung neu erweckter Verlassener im gesamten Zentrum von Tirisfal.",al={"sevrens geschichte","wer ist der magistrat"}},{q="Was ist das Bollwerk?",a="Das Bollwerk ist ein befestigter Außenposten an der Hauptstraße zwischen Tirisfal und den Westlichen Pestländern. Es verhindert Vorstöße der Geißel in die Ländereien der Verlassenen.",al={"geschichte des bollwerks","östliche grenze von tirisfal"}},{q="Warum hassen die Verlassenen die Geißel so sehr?",a="Die Verlassenen waren einst die willenlosen Knechte der Geißel, im Leben erschlagen und erweckt, um ihre eigenen Angehörigen abzuschlachten. Nun besitzen sie einen freien Willen, hassen den Lichkönig und fürchten, erneut unter seine Kontrolle zu geraten.",al={"verlassene gegen geißel","warum den lichkönig hassen"}},{q="Welchen Weg nimmt diese Nachricht?",a="Boten tragen die Nachricht von der Zwischenstation von Todeswache Linnea westwärts entlang der Hauptstraße durch das Zentrum von Tirisfal bis in den Ortskern von Brill.",al={"weg vom bollwerk nach brill","straße nach brill"}}},fx={["8343d5ab"]={q="Warum möchte Todeswache Linnea, dass dies erledigt wird?",a="Todeswache Linnea ist an einer Außenpostenstation der Todeswache östlich von Brill, auf der Straße zum Bollwerk, stationiert. Wenn Streitkräfte der Geißel diese östlichen Verteidigungslinien durchbrechen und in Tirisfal eindringen, muss die Führung von Brill dies sofort wissen. Linnea muss Magistrat Sevren unverzüglich warnen, damit die lokalen Behörden sich auf Überfälle vorbereiten und Verteidiger gegen die unerbittlichen Diener des Lichkönigs mobilisieren können.",al={"warum linneas bericht","warum bericht an sevren","beweggrund todeswache linnea"}},["0dd03a94"]={q="Warum benötigt Todeswache Linnea Euch für die Überbringung der Nachricht?",a="Linnea und ihre Mitstreiter der Todeswache halten an einem Außenposten östlich von Brill Wache und überwachen die Aktivitäten der Geißel, die am Bollwerk vorbeischlüpfen. Sie bittet einen vorbeikommenden Abenteurer, ihren Bericht an Magistrat Sevren zu überbringen, damit die Stadt sich vorbereiten kann, während der Außenposten weiter seine Wache hält.",al={"warum keine todeswache senden","warum linnea mich braucht","warum nachricht an sevren"}}},fp="24,165,16.411.0,12.330.0,33.193.0,51.197.0,25.174.0,20.152.0,45.188.0,35.147.0"}
P.entries["quest:361"] = {n="Ein nie zugestellter Brief",s="Ein nie zugestellter Brief liegt blutbefleckt und verblasst in den skelettartigen Ruinen von Agamands Mühlen. Er erinnert an zwei Liebende, die getrennt wurden, als die Geißel über Lordaeron hinwegfegte, und an das Leben, das die Verlassenen zurückließen.",h="Ein nie zugestellter Brief liegt blutbefleckt und verblasst in den skelettartigen Ruinen von Agamands Mühlen.",kw={"agamand","brill","heller","brief","geißel","taverne","thurman","nicht zugestellt","yvette"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr in diesem geborgenen Pergament die Gefühlsdistanz erkennen, die das Volk der Verlassenen prägt.",["race:Undead"]="Als Untoter kennt Ihr die schmerzhafte Kluft zwischen sterblichen Erinnerungen und dem kalten, zielgerichteten Leben, das die Verlassenen unter der Banshee Queen führen."},sec={{t="Eine im Untergang verlorene Botschaft",b="Thurman Agamand, ältester Sohn des Patriarchen Gregor Agamand, schrieb eine Nachricht, die Yvette Heller nie erreichte. Als die Seuche des Untods Tirisfal verschlang, weigerte sich Thurman, sein angestammtes Heim oder seine Angehörigen zu verlassen. Als die Geißel zuschlug, griff er für Yvette zur Feder. Er hatte sie geliebt, bevor das Königreich zu Asche zerfiel."},{t="Das zerrissene Band",b="In der Taverne Zur Galgenschlinge in Brill erhält Yvette Heller Thurmans Brief und erinnert sich an ihren Abschied. Sie erinnert sich daran, wie sie ihn anflehte, mit ihr und ihrem Vater aus Agamands Mühlen zu fliehen. Sie sagt, sein Bruder Brand sei ihm feindlich gesinnt gewesen.\n\nDie Wärme verfliegt bald. Yvette verhärtet ihr Herz, wirft sterbliche Reue ab und erklärt, dass Liebe in ihrer neuen Existenz keinen Platz hat."}},faq={{q="Wer hat diesen Brief geschrieben?",a="Thurman Agamand, ältester Sohn von Gregor Agamand, schrieb den Brief. Er starb mit den übrigen Mitgliedern seiner verfluchten Familie, als er die Mühlen seiner Familie gegen die Geißel verteidigte.",al={"verfasser","thurman agamand","wer ist thurman"}},{q="Wer ist Yvette Heller?",a="Yvette Heller ist eine Verlassene, die in der Taverne in Brill lebt. Zu Lebzeiten flehte sie ihren Geliebten Thurman Agamand an, Agamands Mühlen mit ihr und ihrem Vater zu verlassen, doch er blieb bei seiner Familie.",al={"yvette","wer ist yvette","empfängerin"}},{q="Woher stammt der Brief?",a="Der Brief wird bei wandelnden Skeletten gefunden, die über das verwüstete Gelände und die Felder von Agamands Mühlen im westlichen Tirisfal streifen.",al={"wo den brief finden","briefbeute","fundort des briefs"}},{q="Was geschah zwischen Thurman und Yvette?",a="Thurman und Yvette waren vor dem Dritten Krieg ein Liebespaar. Sie flehte ihn an, die Mühlen seiner Familie zu verlassen und mit ihr zu fliehen, doch er blieb bei seinen Angehörigen, um der Seuche entgegenzutreten.",al={"thurman und yvette","yvettes vorgeschichte","was geschah mit ihnen"}},{q="Was tut Yvette, als sie den Brief liest?",a="Yvette trauert kurz um Thurman und verflucht sowohl die Geißel als auch seinen Bruder Brand, unterdrückt dann aber rasch ihre Gefühle. Sie sagt, Reue sei etwas für die Schwachen und Romantik habe in ihrer Existenz als Verlassene keinen Platz.",al={"yvettes reaktion","was sagt yvette"}},{q="Wer ist Brand Agamand?",a="Brand war Thurman Agamands Bruder. Yvette sagt, Brand habe schon tiefen Groll und böse Absichten gegen Thurman gehegt, bevor das Anwesen der Seuche zum Opfer fiel.",al={"brand","brand agamand","wer ist brand"}}},fp="20,189,26.324.0,16.360.1,22.169.0,23.195.0,31.131.0,41.163.0,46.209.1,21.152.0"}
P.entries["quest:362"] = {n="Die Spukmühlen",s="Coleman Heller schickt Euch von Brill nach Norden zu Agamands Mühlen, um Rache an der Familie zu nehmen, der einst sein Land gehörte. Zuerst will er Devlins sterbliche Überreste sammeln lassen. Ihre Fehde begann, als die Agamands das einfache Volk von Tirisfal nicht vor der Seuche beschützten.",h="Coleman Heller schickt Euch von Brill nach Norden zu Agamands Mühlen, um Rache an der Familie zu nehmen, der...",kw={"agamands mühlen","brill","coleman heller","devlin agamand","spukmühlen","seuche","geißel","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr den Verlassenen, die Grenzgebiete von Brill und Unterstadt von der gefährlichen Geißel zu säubern.",["race:Undead"]="Als Verlassene erlebt Ihr, wie der Fall Lordaerons den Groll aus dem Leben fortbestehen ließ. Die adeligen Grundbesitzer beschützten das einfache Volk nicht vor der Seuche, und die Verbitterung bleibt."},sec={{t="Eine bittere Ernte",b="Vor dem Dritten Krieg herrschte die wohlhabende Familie Agamand über die Mühlen und versorgte das nördliche Tirisfal mit Nahrung. Als die Geißel über Lordaeron hinwegfegte, suchte das einfache Volk Schutz bei den Adeligen, fand jedoch keine Zuflucht. Coleman Heller überlebte als Untoter, doch der Hass auf die Familie, der er diente, verzehrt ihn noch immer. Er will ihre Knochen sammeln lassen, um sie unter seinem Absatz zu schänden."},{t="Der jüngere Bruder",b="Devlin Agamand war der jüngere Bruder von Thurman Agamand. Die Leute erinnerten sich an Devlin als schwach, boshaft und scharfzüngig, ganz anders als sein sanftmütiger älterer Bruder. Als die Seuche des Untods das Mühlengut erreichte, erlag Devlin rasch ihrer Verderbnis. Nun plappert sein geistloser Leichnam unaufhörlich an der nördlichen Straße entlang, die zu den Mühlen der Familie führt."}},faq={{q="Warum will Coleman Heller Devlins sterbliche Überreste?",a="Coleman Heller wirft den Agamands vor, ihn und seine Verwandten im Stich gelassen zu haben, als die Geißel Lordaeron überrannte. Im Untod sucht er Rache, indem er ihre Knochen sammelt, um sie auf seinem Kaminsims auszustellen und zu Staub zu zermahlen.",al={"warum will coleman knochen","coleman hellers beweggrund","warum devlin töten"}},{q="Wo ist Devlin Agamand zu finden?",a="Devlin streift nahe der Straße unmittelbar südlich von Agamands Mühlen im nördlichen Tirisfal umher und brabbelt zwischen den Untoten, die am Rand des Anwesens lauern.",al={"devlins aufenthaltsort","devlin agamand finden","wo ist devlin"}},{q="Wie war Devlin vor der Seuche?",a="Coleman Heller beschreibt Devlin als den kleineren, schwächeren, scharfzüngigen jüngeren Sohn der Agamands. Devlin war ganz anders als sein großer, sanftmütiger älterer Bruder Thurman.",al={"wer war devlin","devlin agamands geschichte","devlin agamand zu lebzeiten"}},{q="Gehört Devlin zur Geißel oder zu den Verlassenen?",a="Devlin ist ein geistloser Diener der Geißel. Er konnte sich nie aus dem Griff des Lich King befreien, wie es den Verlassenen von Unterstadt gelang, und durchstreift nun die verwüsteten Ländereien seiner Familie.",al={"gehört devlin zur geißel","devlins fraktion"}},{q="Welche anderen Quests finden bei Agamands Mühlen statt?",a="Deaths in the Family schickt ebenfalls verlassene Abenteurer zu Agamands Mühlen, um den Rest des Haushalts der Agamands auszulöschen. Ihr könnt beide Aufgaben zugleich verfolgen.",al={"quests bei agamands mühlen","quests nahe devlin"}},{q="Was geschieht nach der Abgabe von Devlins sterblichen Überresten?",a="Nachdem Coleman Heller die Knochen entgegengenommen hat, schickt er Euch zu Sevren in Brill, um mit ihm zu sprechen. Das führt tiefer in die Gruft der Familie Agamand.",al={"questfortsetzung","nächste quest nach den spukmühlen"}}},fx={["6ae9875b"]={q="Was macht Coleman Heller mit Devlins sterblichen Überresten?",a="Coleman beabsichtigt, Devlins Knochen direkt auf seinem Kaminsims aufzustellen und sie als grimmige Trophäe der Rache zu behalten. Er hegt tiefen, bitteren Hass gegenüber der Familie Agamand, weil sie ihn und seine Verwandten im Stich ließen, als die Geißel durch Tirisfal fegte. Anstatt den Überresten ein angemessenes Begräbnis oder eine Untersuchung zukommen zu lassen, sucht Coleman die kleingeistige Befriedigung, über den Überresten des schwachen, scharfzüngigen jüngeren Bruders zu triumphieren, und schwört letztlich, die Agamand-Knochen unter seiner Ferse zu zermahlen.",al={"verwendung von devlins überresten","warum devlins überreste behalten","was passiert mit devlins knochen"}},["67792824"]={q="Wer ist Devlin Agamand?",a="Devlin war der jüngere Sohn der angesehenen Agamand-Dynastie, zu Lebzeiten bekannt als schwach und bösartig scharfzüngig im Gegensatz zu seinem sanften älteren Bruder Thurman. Als die Seuche des Untods Agamands Mühlen verschlang, gehörte Devlin zu den Ersten, die erlagen. Nun als willenloses untodes Monster unter der Geißel-Kontrolle auferstanden, wandert er auf der Straße direkt südlich der zerstörten Mühlen seiner Familie und plappert im Zwielicht von Tirisfal wahnsinnig vor sich hin.",al={"wer ist devlin agamand","wer ist devlin","devlin agamand lore"}}},fp="17,254,16.369.0,19.339.0,48.209.0,34.149.0,39.165.0,42.171.0,46.146.0,47.133.1"}
P.entries["quest:3625"] = {n="Verzauberte Azsharit-Teufelswaffe",s="Im Schlingendorntal fertigt Galvan der Alte verzauberte Waffen gegen einen mächtigen Dämon. Ihr Felcurse soll Razelikh the Defiler und seine Diener schwächen.",h="Im Schlingendorntal fertigt Galvan der Alte verzauberte Waffen gegen einen mächtigen Dämon.",kw={"azsharit","verwüstete lande","felbane","felcurse","galvan der alte","razelikh the defiler","schlingendorntal"},sec={{t="Eine Waffe gegen den Defiler",b="Direkt südlich des Pfades nach Zul'Gurub arbeitet Galvan der Alte mit Sorgfalt. Eine Klinge, einen Stab oder einen Dolch zu schmieden, erfordert Geduld, und Eile birgt die Gefahr eines Fehlers. Jede Waffe trägt den Felcurse, der von Zeit zu Zeit gegen Razelikh the Defiler und seine dämonischen Untergebenen entfesselt werden kann. Seine schwächende Wirkung hält unterschiedlich lange an."}},faq={{q="Wer schmiedet diese Waffen?",a="Galvan der Alte, ein Meisterschmied, schmiedet die Waffen direkt südlich des Weges nach Zul'Gurub im Schlingendorntal.",al={"wer fertigt die waffe","galvan der alte","wer ist der schmied"}},{q="Welche Macht birgt die geschmiedete Waffe?",a="Jede Waffe kanalisiert den Felcurse, eine Magie, die Razelikh the Defiler und seine dämonischen Diener schwächen soll. Die Wirkung hält unterschiedlich lange an.",al={"was bewirkt die waffe","macht des felcurse","wie funktioniert felcurse"}},{q="Wohin führt die Reise, nachdem die Waffe geschmiedet wurde?",a="Wenn Galvan die Waffe fertigstellt und überreicht, kehrt Ihr mit „Return to the Blasted Lands“ den Pfad entlang in die Verwüsteten Lande zurück.",al={"was kommt als nächstes","wohin geht es als nächstes","nächste quest"}}},fp="32,165,28.336.0,25.117.0,39.150.0,55.105.0"}
P.entries["quest:3626"] = {n="Rückkehr in die Verwüsteten Lande",s="Galvan der Alte schickt Euch mit Euren neu geschmiedeten Waffen zurück in die Verwüsteten Lande. Der Gefallene Held der Horde wartet dort, bereit zu fragen, ob Ihr Euch Razelikh stellen werdet.",h="Galvan der Alte schickt Euch mit Euren neu geschmiedeten Waffen zurück in die Verwüsteten Lande.",kw={"verwüstete lande","gefallener held der horde","teufelswaffen","galvan der alte","razelikh","erlösung","schlingendorntal"},sec={{t="Ein Ruf zur Erlösung",b="Galvan der Alte sagt, Eure Stunde der Erlösung sei gekommen. Eure verzauberten Waffen sind fertig, also tragt Ihr sie zurück in die Verwüsteten Lande, um den Gefallenen Helden der Horde zu finden. Der geisterhafte Krieger fragt, ob Ihr bereit seid, Euch Razelikh und seinen Dienern zu stellen."}},faq={{q="Wer schickt Euch zurück in die Verwüsteten Lande?",a="Galvan der Alte schmiedet Eure Waffen und schickt Euch dann mit ihnen zurück in die Verwüsteten Lande.",al={"wer vergibt diese quest","questgeber","galvan der alte"}},{q="Wen sollt Ihr in den Verwüsteten Landen treffen?",a="Ihr werdet ausgesandt, um den Gefallenen Helden der Horde erneut zu treffen. Er erwartet Eure Rückkehr und wird Eure letzte Konfrontation enthüllen.",al={"bei wem die quest abgeben","wo abgeben","gefallener held"}},{q="Was kommt vor diesem Schritt?",a="Dies folgt auf Enchanted Azsharite Fel Weaponry, wo Eure Spezialwaffen fertiggestellt wurden.",al={"vorherige quest","voraussetzung"}},{q="Welcher Feind erwartet Euch in den Verwüsteten Landen?",a="Der Gefallene Held der Horde fragt, ob Ihr bereit seid, Euch Razelikh und seinen Dienern zu stellen.",al={"gegen wen kämpfen wir","razelikh","endboss"}}},fp="27,168,20.252.0,40.91.0,47.120.0,28.93.0,51.84.0"}
P.entries["quest:363"] = {n="Unsanftes Erwachen",s="Frisch erwachte Verlassene verlassen Todesends Grüfte und stehen vor einem ungewohnten Leben. Befreit aus dem Griff des Lichkönigs werdet Ihr den Hügel hinabgeschickt, fort von den Verbrennungsöfen, um von Schattenpriester Sarvis zu erfahren, wie es weitergeht.",h="Frisch erwachte Verlassene verlassen Todesends Grüfte und stehen vor einem ungewohnten Leben.",kw={"todesend","verlassene","lichkönig","mordo","unsanftes erwachen","sarvis","geißel","schattenpriester sarvis","sylvanas","tirisfal","totengräber mordo"},ang={["class:Priest"]="Als Priester lernt Ihr durch Schattenpriester Sarvis die Priesterschaft der Verlassenen kennen. Nach dem Eintritt in den Untod erhält geistliche Hingabe eine neue Bedeutung.",["faction:Horde"]="Als Mitglied der Horde tretet Ihr einem brüchigen Bündnis bei, das aus schierer Notwendigkeit entstand, um der gemeinsamen Auslöschung zu entgehen.",["race:Undead"]="Als Untoter habt Ihr die Fesseln der Geißel abgestreift und beginnt ein von Groll erfülltes, freies Leben unter den Verlassenen."},sec={{t="Ein Anfang im Grab",b="In Todesends Gruft erwacht Ihr zwischen feuchtem Stein und kalter Luft zum Untod. Totengräber Mordo wacht über die frisch Bestatteten und trennt jene, die ihren freien Willen wiedererlangen, von denen, die für die Verbrennungsgruben bestimmt sind. Viele erheben sich verwirrt, umgeben von Fäulnis und Stein. Durch Zufall sind sie dem Griff der Geißel entkommen."},{t="Dem Frozen Throne entrinnen",b="Bevor Ihr die Kapelle erreicht, steht Ihr vor einer düsteren Wahrheit: Einst wart Ihr ein willenloses Werkzeug des Lichkönigs. Fürstin Sylvanas Windläufer brach diese geistige Versklavung und befreite die Überreste Eurer einstigen Menschlichkeit, sodass Ihr wieder eigenständig denken konntet. Ihr verlasst die Gruft und steigt nach Todesend hinab. Damit beginnt Euer Leben in einer Welt, in der die Lebenden und die Geißel Euch gleichermaßen als Abscheulichkeit betrachten, die vernichtet werden muss."}},faq={{q="Warum war ich in einer Gruft?",a="Ihr seid während des Dritten Krieges durch Seuche oder Gewalt gestorben und wurdet dann in Tirisfal begraben. In Todesend werden die frisch Auferstandenen beobachtet, um festzustellen, ob sie ihren Verstand wiedererlangen oder in geistlose Fäulnis versinken.",al={"warum in der gruft","wo bin ich erwacht","todesend gruft"}},{q="Wer ist Totengräber Mordo?",a="Totengräber Mordo kümmert sich um Todesends Gruft. Er beobachtet die frisch Erwachten und schickt jene, die bei Verstand bleiben, zur Kapelle des Ortes. Wer beim Erwachen seinen Verstand nicht bewahrt hat, wird beseitigt.",al={"totengräber mordo","wer ist mordo","grabwächter"}},{q="Warum sprach Mordo davon, Leute ins Feuer zu werfen?",a="Nicht jeder Leichnam, der sich aus dem Grab erhebt, erlangt seinen freien Willen oder einen klaren Verstand zurück. Wer wahnsinnig oder völlig verwildert erwacht, kann sich der Gesellschaft der Verlassenen nicht anschließen. Diese Wesen werden vernichtet und verbrannt, damit sie nicht mordend umherziehen.",al={"leichen verbrennen","ins feuer werfen","einäscherung"}},{q="Wer hat mich vom Lichkönig befreit?",a="Fürstin Sylvanas Windläufer, bekannt als Banshee Queen, befreite sich aus der geistigen Herrschaft des Lichkönigs, als seine Macht schwand. Sie sammelte andere Untote mit freiem Willen unter ihrem Banner und gründete die Verlassenen, um ihren einstigen Meister und die feindseligen verbliebenen Lebenden zu bekämpfen.",al={"wer hat mich befreit","sylvanas befreite untote","warum bin ich frei"}},{q="Wo befindet sich Schattenpriester Sarvis?",a="Schattenpriester Sarvis befindet sich in der beschädigten Kapelle am Fuß des Hügels in Todesend. Verlasst die Gruft und folgt dem Kopfsteinpflasterweg bergab bis zum Eingang der Kapelle.",al={"sarvis finden","sarvis aufenthaltsort","wo ist die kapelle"}},{q="Gegen wen kämpfen die Verlassenen?",a="Die Verlassenen führen einen Überlebenskampf an zwei Fronten. Sie stehen der Geißel gegenüber, die sie zurückgewinnen oder vernichten will, sowie menschlichen Eiferern und überlebenden Siedlungen, die zwischen ihnen und geistlosen Monstern keinen Unterschied sehen.",al={"feinde der verlassenen","gegen wen kämpfen wir","feinde der untoten"}}},fx={e742af5a={q="Warum schickt mich Totengräber Mordo zu Schattenpriester Sarvis?",a="Totengräber Mordos Aufgabe ist lediglich, die Krypten zu pflegen und die verwertbaren Untoten von den wirklich Verlorenen zu trennen. Er ist kein Staatsmann oder spiritueller Führer. Neu erwachte Verlassene sind desorientiert, traumatisiert und gefährlich unwissend über den Krieg um sie herum. Indem Mordo Euch sofort den Hügel hinunter zu Schattenpriester Sarvis in der Kapelle schickt, stellt er sicher, dass Ihr gebildet, in die Sache von Lady Sylvanas integriert und für das Überleben trainiert werdet, bevor Ihr fortlauft oder in die Hände von Feinden fallt.",al={"warum sarvis besuchen","mordos beweggrund","warum zum kirchhof schicken"}}},fp="14,219,17.289.0,38.388.0,21.200.0,24.200.0,52.194.0,32.262.0,38.169.0,38.214.0"}
P.entries["quest:3633"] = {n="Goblin-Ingenieurskunst",s="Unter Meistererfindern bietet die Goblin-Ingenieurskunst einen Weg, explosive Kräfte und unberechenbare Erschütterungsgeschosse zu beherrschen. Ihr Handwerk beruht auf hochwirksamen Sprengpulvern und unerbittlicher Feuerkraft und ist damit eine zerstörerische Wahl neben ausgefeilten Tüfteleien.",h="Unter Meistererfindern bietet die Goblin-Ingenieurskunst einen Weg, explosive Kräfte und unberechenbare...",kw={"sprengpulver","bomben","ingenieurskunst","sprengstoffe","gadgetzan","goblin-ingenieurskunst","nixx sprocketspring","steamwheedle cartel"},ang={["profession:Engineering"]="Goblin-Ingenieurskunst ist eine der beiden großen spezialisierten Traditionen, die Meisteringenieuren offenstehen. Sie konzentriert sich auf instabile Munition, gewaltige Sprengkraft und katastrophale Zerstörung.",["profession:Mining"]="Ingenieure, die dem Handwerk der Goblins nachgehen, benötigen große Mengen an veredelten Erzen, Sprengpulvern und festen Steinen, um Brandmittel und Bomben herzustellen."},sec={{t="Die Kunst der Detonation",b="Azeroths Ingenieure folgen zwei unterschiedlichen Philosophien. Goblin-Tüftler bevorzugen heftige Verbrennungen, während andere Erfinder filigrane Uhrwerke und subtile Vorrichtungen herstellen. Goblins nutzen Sprengpulver, um Werkzeuge von gewaltiger Zerstörungskraft zu bauen, und setzen Feuer, Schrapnelle und Erschütterungskraft gegen praktische Probleme ein."},{t="Unberechenbarkeit und Macht",b="Goblin-Ingenieure machen aus den Gefahren kein Geheimnis. Rekruten arbeiten mit instabilen Gemischen, schweren Brandmitteln und Prototypen, die ihrem Schöpfer die Augenbrauen versengen oder eine feindliche Barrikade einebnen können. Sie schätzen höchste Sprengkraft und Zerstörungsmacht und heißen Ingenieure willkommen, die entscheidende Feuerkraft fragilen Sicherheitsvorschriften vorziehen."}},faq={{q="Was ist Goblin-Ingenieurskunst?",a="Goblin-Ingenieurskunst ist eine Disziplin, die sich Explosionen mit hoher Sprengkraft widmet. Ihre Vertreter fertigen mächtige Sprengstoffe, Bomben und schwere Zerstörungsgeräte anstelle der ausgeklügelten Apparate, die gnomische Ingenieure bevorzugen.",al={"was ist goblin-ingenieurskunst","goblin-spezialisierung","goblin-ingenieurskunst quest"}},{q="Wie unterscheidet sich Goblin-Ingenieurskunst von gnomischer Ingenieurskunst?",a="Gnomische Ingenieurskunst bevorzugt seltsame Hilfsgeräte, komplexe Tüfteleien und einfallsreiche Apparate. Goblin-Ingenieurskunst stellt Feuerkraft, Sprengpulver und Zerstörungskraft an erste Stelle. Goblinerfindungen sind aggressiv und wirksam, wenn auch gefährlich in der Handhabung.",al={"goblin- gegen gnomische ingenieurskunst","gnomisch oder goblin","unterschied goblin- und gnomische ingenieurskunst"}},{q="Wer lehrt die Disziplin der Goblin-Ingenieurskunst?",a="Meister der Goblin-Ingenieurskunst unterrichten Rekruten, die bereit sind, mit Explosionen und Sprengpulver zu arbeiten. Meisteringenieur Nixx Sprocketspring in Gadgetzan ist ein bekannter Lehrer, der Anwärter prüft, bevor er ihnen das Handwerk beibringt.",al={"wer lehrt goblin-ingenieurskunst","wo goblin-ingenieurskunst lernen","goblin-ingenieurskunst lehrer"}},{q="Ist die Ausübung der Goblin-Ingenieurskunst gefährlich?",a="Goblins akzeptieren als Erfinder die Gefahr als Teil ihres Handwerks. Ihre Konstruktionen maximieren Sprengwirkung und Erschütterungskraft und bringen unvorhersehbare Fehlfunktionen, plötzliche Detonationen und persönliche Risiken für die Handwerker mit sich, die damit umgehen.",al={"goblin-ingenieurskunst gefahren","explodieren goblinsprengstoffe","ist goblin-ingenieurskunst sicher"}},{q="Können beide Fraktionen Goblin-Ingenieurskunst erlernen?",a="Ingenieure der Allianz und der Horde können Goblin-Ingenieurskunst erlernen, sobald sie ausreichend geübt sind. Goblin-Tüftler arbeiten vor allem über neutrale Kartelle wie das Steamwheedle Cartel, das jeden mit ruhigen Händen, genug Münzen und einer Liebe zur Sprengkraft willkommen heißt.",al={"kann jeder goblin-ingenieurskunst lernen","allianz goblin-ingenieurskunst","horde goblin-ingenieurskunst"}},{q="Warum wählt ein Ingenieur die Disziplin der Goblins?",a="Ingenieure wählen Goblin-Ingenieurskunst wegen ihrer unübertroffenen Zerstörungskraft. Sie bringt tödliche Kampfsprengstoffe, Mörser, Landminen und tragbare Raketen hervor, die dafür geschaffen sind, Widerstand auf dem Schlachtfeld auszulöschen.",al={"warum goblin-ingenieurskunst wählen","was stellt goblin-ingenieurskunst her","goblin-ingenieurskunst gegenstände"}}},fp="18,250,25.303.0,20.320.0,27.213.0,60.251.0,46.234.0,44.219.0,43.276.0,51.211.0"}
P.entries["quest:3636"] = {n="Bring the Light",s="Erzbischof Benedictus bittet Euch, Euch Amnennar the Coldbringer in den Hügeln der Klingenhauer zu stellen. Seine Bitte macht die Sorge des Erzbischofs deutlich.",h="Erzbischof Benedictus bittet Euch, Euch Amnennar the Coldbringer in den Hügeln der Klingenhauer zu stellen.",kw={"amnennar the coldbringer","erzbischof bendictus","bring das licht","coldbringer","hügel der klingenhauer"},sec={{t="Benedictus' Bitte",b="Ihr seid auf Bitte von Erzbischof Benedictus auf dem Weg zu den Hügeln der Klingenhauer. Er nennt Amnennar the Coldbringer als den, den Ihr töten sollt. Die Sorge des Erzbischofs gilt diesem Feind."}},faq={{q="Wer schickt mich zu den Hügeln der Klingenhauer?",a="Erzbischof Benedictus bittet Euch, Amnennar the Coldbringer in den Hügeln der Klingenhauer zu töten.",al={"wer hat mich geschickt","bendictus' bitte","wer will amnennar tot sehen"}},{q="Wer ist Amnennar the Coldbringer?",a="Amnennar the Coldbringer ist der Feind, den Erzbischof Benedictus Euch in den Hügeln der Klingenhauer zu töten aufträgt.",al={"wer ist amnennar","coldbringer"}},{q="Wo ist Amnennar?",a="Erzbischof Benedictus nennt die Hügel der Klingenhauer als den Ort, an dem Ihr Amnennar the Coldbringer finden sollt.",al={"wo ist amnennar","lage der hügel der klingenhauer","coldbringer finden"}}},fp="15,134,22.178.0,36.82.0,32.98.0,18.89.0"}
P.entries["quest:364"] = {n="Die Hirnlosen",s="Am Nordrand von Todesend stehen frisch auferstandene Verlassene den Hirnlosen gegenüber. Schattenpriester Sarvis schickt sie gegen Hirnlose Zombies und Elende Zombies, Knechte der Geißel, die dem Befehl des Lichkönigs unterworfen sind.",h="Am Nordrand von Todesend stehen frisch auferstandene Verlassene den Hirnlosen gegenüber.",kw={"todesend","verlassene","lichkönig","die hirnlosen","hirnloser zombie","geißel","schattenpriester sarvis","elender zombie"},ang={["class:Priest"]="Als Priester dient Ihr unter Schattenpriester Sarvis und lernt die pragmatische, vom Schatten geprägte Lebensweise der Verlassenen kennen. Sie nahmen sie anstelle des Heiligen Lichts an, das sie im Stich ließ.",["faction:Horde"]="Als Mitglied der Horde erkennt Ihr, warum die Horde die Verlassenen einst mit tiefem Misstrauen betrachtete, bevor sie sie in die Fraktion aufnahm.",["race:Undead"]="Als Untoter erkennt Ihr unter den Zombies am Dorfrand vielleicht einen ehemaligen Nachbarn, einen Verwandten oder einen Freund. Sie erinnern Euch daran, was Euch erspart blieb und was geschehen könnte, wenn die Verlassenen fallen."},sec={{t="Sklaven des Frozen Throne",b="Viele, die sich aus Lordaerons Erde erheben, erlangen ihren Verstand nie zurück. Die Verlassenen befreiten sich aus Ner'zhuls Herrschaft, als seine Macht schwand, doch unzählige Tote bleiben an seinen Willen gekettet. Im Norden von Todesend streifen Hirnlose Zombies und Elende Zombies umher, von Gewalt getrieben. Für Euch, frisch auferstanden unter den Untoten, ist es die erste schwere Prüfung, ihnen die letzte Ruhe zu schenken. Ihr beweist Eure Freiheit, indem Ihr die Knechtschaft jener beendet, die ihr nie entkamen."},{t="Gnade durch Vernichtung",b="Schattenpriester Sarvis bedauert, dass diese Legionen von Toten den verzweifelten Kampf der Verlassenen nicht verstärken können. Für sie gibt es keine Heilung. Ihr Verstand ist gebrochen, und sie bleiben Werkzeuge des Schlachtens. Lässt man sie umherstreifen, bringen sie Chaos vor die Tore von Todesend und liefern dem Lichkönig leichte Beute. Ihre Vernichtung ist für die Siedlung notwendig und bringt einigen von Lordaerons Gefallenen ein düsteres Ende."}},faq={{q="Warum können die hirnlosen Zombies nicht für die Verlassenen rekrutiert werden?",a="Die Zombies können sich nicht dafür entscheiden, sich Lady Sylvanas anzuschließen, weil ihr Verstand gebrochen und an den Lichkönig gebunden ist. Schattenpriester Sarvis sagt, ihre große Zahl wäre von unschätzbarem Wert, doch sie bleiben gefährliche Knechte der Geißel.",al={"hirnlose zombies rekrutieren","warum sie töten","können hirnlose zombies geheilt werden","die zombies befreien"}},{q="Wer waren diese Zombies ursprünglich?",a="Die Zombies waren menschliche Bewohner Lordaerons, die während des Dritten Krieges der Seuche des Untodes zum Opfer fielen. Anders als Ihr erlangten sie ihre Erinnerungen, ihre Persönlichkeit oder ihre Entscheidungsfreiheit nie zurück, als der Griff des Lichkönigs nachließ.",al={"wer waren die hirnlosen","identität der hirnlosen zombies","leichen in todesend"}},{q="Warum befehligt Schattenpriester Sarvis hier die Verteidigung?",a="Schattenpriester Sarvis wacht über die ersten Tage frisch auferstandener Untoter in Todesend. Er beurteilt, ob sie die nötige Willenskraft und einen klaren Verstand haben, um ihr neues Dasein zu überstehen.",al={"wer ist sarvis","sarvis' rolle in todesend","priester sarvis"}},{q="Was unterscheidet Verlassene von Zombies der Geißel?",a="Verlassene haben einen freien Willen, Zombies der Geißel hingegen nicht. Verlassene entkamen der telepathischen Kontrolle des Lichkönigs und behielten ihre Intelligenz und Gefühle. Der Lichkönig lenkt die leeren Hüllen der Geißel unmittelbar wie Marionetten.",al={"geißel gegen verlassene","unterschied zwischen verlassenen und hirnlosen","warum sind manche zombies hirnlos"}},{q="Sind die hirnlosen Zombies eine Bedrohung für Todesend?",a="Ja. Diese Zombies streifen unmittelbar nördlich von Todesend umher und bedrohen die Neuankömmlinge aus den Gräbern sowie die Priester der Verlassenen, die die Siedlung zu organisieren versuchen.",al={"gefahr in todesend","warum den norden von todesend säubern","bedrohung durch zombies"}},{q="Wohin führt diese Aufgabe als Nächstes?",a="Euer Erfolg gegen die hirnlosen Toten führt zu weiteren Aufgaben, um Todesend zu sichern. Dazu gehören das Dezimieren der Skelettstreitkräfte der Geißel in Rattling the Rattlecages und der Beginn Eurer Ausbildung bei Eurem Klassenlehrer.",al={"nächste quest nach den hirnlosen","folgequest der hirnlosen","what comes next"}}},fx={b9d2809d={q="Warum will Schattenpriester Sarvis, dass die Zombies vernichtet werden?",a="Todesend ist umzingelt und steht unter ständigem Druck durch die Diener des Lichkönigs. Sarvis sieht die überrannte Nordseite des Dorfes als unmittelbare Gefahr für den Stützpunkt der Verlassenen hier. Mit der Geißel kann man nicht verhandeln oder sie auf Eure Seite ziehen, daher ist deren Vernichtung der einzige Weg, das Gebiet zu sichern und das Überleben Eures neu erwachten Volkes zu garantieren.",al={"sarvis beweggrund","warum willenlose zombies töten","warum willenlose vernichten"}},["40675fbd"]={q="Wer sind die willenlosen Zombies, die im nördlichen Todesend umherwandern?",a="Es handelt sich um erschlagene Bewohner von Lordaeron, die von der Geißel wiedererweckt wurden und nie ihren freien Willen zurückerlangten. Als wilde Sklaven unter dem Willen des Lichkönigs gefangen, schlurfen diese willenlosen und elenden Leichen nun durch die Ruinen des nördlichen Todesend und greifen jeden an, der ihren Weg kreuzt.",al={"wer sind die willenlosen zombies","elende zombies","was sind die willenlosen"}},["58c1d115"]={q="Warum schickt Sarvis Euch aus, um die Zombies zu töten, anstatt die Wachen?",a="Sarvis ist ein Test Eurer Entschlossenheit und Fähigkeit in dieser neuen Existenz. Die etablierten Wächter von Todesend müssen ihre Posten um die Kapelle und den Umkreis halten. Zu beweisen, dass Ihr sogar willenlose ehemalige Verwandte vernichten könnt, zeigt, dass Ihr den Magen und die militärische Stärke besitzt, die benötigt werden, um der Dunklen Fürstin zu dienen.",al={"warum ich","warum mich zombies töten lassen","warum sarvis fragt"}}},fp="17,204,27.417.0,25.394.0,62.210.0,33.222.0,56.165.0,60.211.0,48.150.0,31.194.0"}
P.entries["quest:365"] = {n="Felder des Kummers",s="Kürbisse von einem Bauernhof der Menschen nördlich von Todesend sind für die Königliche Apothekervereinigung in Brill bestimmt. Todeswache Simmer schickt die frisch auferstandenen Verlassenen los, um sie zu sammeln.",h="Kürbisse von einem Bauernhof der Menschen nördlich von Todesend sind für die Königliche Apothekervereinigung...",kw={"apotheker johaan","brill","todeswache simmer","todesend","felder des kummers","königliche apothekervereinigung","scharlachroter kreuzzug","tirisfalkürbis"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, Tirisfal zu sichern, indem Ihr die verbliebene Präsenz der Menschen brecht und den Einfluss des Scharlachroten Kreuzzugs entlang der südlichen Straßen zurückdrängt.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass Apotheker für tödliche Mixturen auf Tirisfals entstellte Pflanzenwelt angewiesen sind. Jede örtliche Wurzel und Feldfrucht kann zu einem Reagenz des Krieges werden.",["race:Undead"]="Als Untoter ist dies Euer erster militärischer Auftrag außerhalb von Todesend. Ihr beraubt Eure einstigen sterblichen Verwandten ihrer Lebensgrundlage, um die Königliche Apothekervereinigung voranzubringen."},sec={{t="Eine Lektion im Überleben",b="Todeswache Simmer schickt Euch aus den Krypten von Todesend in feindliches Land. Er dient den Streitkräften von Sylvanas Windläufer. Dort bedeutet Überleben, den Lebenden ihren Besitz zu entreißen und ihn für die finstereren Ziele von Unterstadt einzusetzen."},{t="Überfall auf die Lebenden",b="Der Bauernhof liegt westlich der Straße und nördlich von Todesend. Menschliche Bauern bearbeiten seinen verseuchten Boden, und Simmer sagt, sie befallen das Reich wie Schimmel eine Leiche. Sie halten ihre Gehöfte unter dem unsicheren Schutz nahegelegener Türme des Scharlachroten Kreuzzugs. Ihre Ernte zu rauben, trifft ihre Vorräte und liefert der Königlichen Apothekervereinigung Feldfrüchte für die Forschung."},{t="Vorräte für die Vereinigung",b="In Brill betreibt Apotheker Johaan experimentelle Forschung, und die gestohlenen Kürbisse werden ihm geliefert. Die Königliche Apothekervereinigung nutzt häufig örtliche Feldfrüchte und Pflanzen als Grundlage für alchemistische Gebräue, Gifte und Seuchenforschung. Ihre Arbeit soll den unsicheren Stand der Verlassenen im nördlichen Lordaeron festigen."}},faq={{q="Wer vergibt die Quest Felder des Kummers?",a="Todeswache Simmer erteilt Euch den Auftrag. Er bewacht die Straße im südlichen Tirisfal, direkt nördlich des Weges aus Todesend.",al={"questgeber","felder des kummers questgeber","wer startet felder des kummers"}},{q="Wohin bringe ich die Tirisfal-Kürbisse?",a="Bringt die zehn Tirisfal-Kürbisse zu Apotheker Johaan in Brill, weiter östlich in Tirisfal.",al={"wo kürbisse abgeben","kürbisse abgeben","felder des kummers abgeben"}},{q="Warum betreiben lebende Menschen in Tirisfal Landwirtschaft?",a="Die menschlichen Bauern sind Überreste der ursprünglichen Bevölkerung Lordaerons, die den Dritten Krieg und die Seuche der Geißel überlebt haben. Sie klammern sich an ihre Gehöfte nahe den Wachposten des Scharlachroten Kreuzzugs und widersetzen sich der Herrschaft der Verlassenen.",al={"warum menschen hier","lebende menschen tirisfal","warum menschen im untotengebiet"}},{q="Warum will Apotheker Johaan Kürbisse?",a="Apotheker Johaan will Kürbisse für die Forschung der Königlichen Apothekervereinigung. Die Vereinigung verwendet Pflanzen, verseuchte Feldfrüchte und biologisches Material als Versuchsstoffe und Grundbestandteile für alchemistische Mischungen, Gifte und experimentelle Seuchen.",al={"warum kürbisse","wozu dienen die kürbisse","apotheker johaan kürbisse"}},{q="Wer patrouilliert in der Nähe des Gehöfts?",a="Zeloten des Scharlachroten Kreuzzugs patrouillieren von einem nahegelegenen Wachturm aus hinunter. Sie verteidigen die menschliche Siedlung und versuchen, Untote zu vernichten, die sich den Feldern nähern.",al={"scharlachroter kreuzzug nahe bauernhof","wer beschützt den bauernhof"}},{q="Was folgt auf Felder des Kummers?",a="Nachdem Ihr die Kürbisse abgeliefert habt, erteilt Euch Apotheker Johaan einen weiteren Auftrag mit demselben Namen. Er gibt Euch einen mit seiner neuesten Formel versetzten Kürbis, den Ihr zu einem Gefangenen Scharlachroten Zeloten im Keller der Taverne Zur Galgenschlinge bringen sollt.",al={"nächste quest","felder des kummers folgequest","was folgt auf felder des kummers"}}},fx={["39021143"]={q="Warum möchte Todeswache Simmer, dass dies erledigt wird?",a="Todeswache Simmer betrachtet überlebende Menschen, die in der Lichtung Ackerbau betreiben, als Schimmel auf einer verwesenden Leiche – eine unerträgliche Plage auf Land, das nun den Verlassenen gehört. Ihre Ernte zu stehlen, trifft sie an ihrem kargen Lebensunterhalt und hilft gleichzeitig der Königlichen Apothekervereinigung mit frischen Reagenzien, was beweist, ob neu erwachte Verlassene den Mumm haben, der Dunklen Fürstin zu dienen.",al={"warum simmer kürbisse","beweggrund todeswache simmer","grund für fields of grief"}}},fp="15,164,20.216.0,18.350.0,24.312.1,36.133.0,38.86.0,55.211.0,41.238.0,31.143.0,33.228.0"}
P.entries["quest:366"] = {n="Rückgabe des Buches",s="Bethor Eismacht sendet Gunther Arkanus auf dem Blendwassersee eine verzauberte Nachricht. Das gestohlene Zauberbuch könnte seinen alten Gefährten der Kirin Tor den Verlassenen näherbringen.",h="Bethor Eismacht sendet Gunther Arkanus auf dem Blendwassersee eine verzauberte Nachricht.",kw={"bethor eismacht","blendwassersee","dalaran","gunther arkanus","gunthers zufluchtsort","gunthers zauberbuch","kirin tor","rückgabe des buches","thule ravenclaw","tirisfal"},ang={["class:Mage"]="Als Magier wisst Ihr, wie ehemalige Magier der Kirin Tor die Magie des anderen auch im Untod wiedererkennen können.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die arkanen Reihen der Unterstadt zu stärken, wenn unabhängige untote Zauberer wie Gunther gegen die Geißel und den Scharlachroten Kreuzzug kämpfen.",["race:Undead"]="Als Untoter teilt Ihr Gunthers Ringen: aus willenlosem Dienst zu erwachen und einer feindseligen, einsamen Welt gegenüberzustehen."},sec={{t="Eine Botschaft in arkaner Tinte",b="Das Zauberbuch, das Ihr Gunther Arkanus genommen habt, kehrt zu ihm zurück, doch nun ist es verzaubert. Als Bethor erfährt, dass der Nekromant auf dem Blendwassersee sein alter Gefährte ist, verzaubert er die Seiten. Seine Magie hinterlässt ein Zeichen auf dem Folianten. Es zeigt Gunther, dass Bethor in Lordaeron wirkt und frei von der Kontrolle des Lichkönigs ist."},{t="Der alte Kreis von Dalaran",b="Bevor der Dritte Krieg Lordaeron verwüstete, studierten Bethor Eismacht, Gunther Arkanus und Thule Rabenklaue gemeinsam bei den Kirin Tor von Dalaran und wurden Freunde. Als der Lichkönig aufstieg, verriet Thule sie und schloss sich freiwillig der Geißel an. Bethor und Gunther erlagen der Seuche. Bethor befreite sich später an der Seite von Königin Sylvanas.\n\nBethor hielt Gunther für tot oder versklavt. Nun erfährt er, dass auch sein alter Freund die Freiheit errungen hat, und will ihn in die Reihen der Verlassenen holen."},{t="Misstrauen auf der Insel",b="Gunther Arkanus begegnet einem Eindringling auf seiner Insel voller Zorn. Er vermutet, dass ein Agent der Geißel gekommen ist, um ihn erneut zu versklaven, oder dass der Dieb zurückgekehrt ist, der seine Magie stahl. Dann sieht er sein Grimoire und spürt darin Bethors vertraute Magie. Dieses Zeichen von jemandem aus seiner sterblichen Vergangenheit lässt den einsamen Magier seine Abgeschiedenheit hinterfragen."}},faq={{q="Warum hat Bethor Gunthers Zauberbuch verzaubert?",a="Bethor Eismacht versieht das gestohlene Zauberbuch mit seiner magischen Signatur, um Gunther zu zeigen, dass er frei von der Kontrolle des Lichkönigs ist. Gunther fürchtet die Geißel und könnte einen gewöhnlichen Boten abweisen oder vernichten.",al={"warum das buch verzaubern","zauber auf gunthers buch","was hat bethor mit dem buch gemacht"}},{q="Wer war Gunther Arkanus vor seinem Tod?",a="Vor seinem Tod war Gunther Arkanus ein menschlicher Magier und Gelehrter der Kirin Tor in Dalaran. Er studierte vor dem Dritten Krieg mit Bethor Eismacht und Thule Rabenklaue und erlag dann der Plague of Undeath der Geißel.",al={"wer ist gunther arkanus","gunthers vorgeschichte","gunthers geschichte"}},{q="Warum versteckt sich Gunther auf dem Blendwassersee?",a="Nachdem Gunther sich von der Kontrolle des Lichkönigs befreit hatte, glaubte er, als Einziger frei zu sein. Er versteckte sich auf einer Insel im Blendwassersee, um der Geißel und lebenden Feinden zu entgehen, die ihn jagen oder töten könnten.",al={"warum ist gunther auf der insel","geschichte von gunthers zuflucht","warum ging gunther fort"}},{q="Wer ist Thule Rabenklaue?",a="Thule Rabenklaue studierte mit Bethor Eismacht und Gunther Arkanus bei den Kirin Tor von Dalaran. Anders als sie dient Thule der Geißel freiwillig als treuer Nekromant im Silberwald.",al={"wer ist thule","thule ravenclaws geschichte","dritter freund"}},{q="Warum hält Gunther den Spieler für einen Dieb?",a="Bethor schickte zuvor Abenteurer der Verlassenen in Gunthers Heiligtum, um sein Zauberbuch zu stehlen und herauszufinden, wer auf dem See Nekromantie praktizierte. Gunther erkennt in dem zurückkehrenden Abenteurer denjenigen, der ihn bestohlen hat.",al={"warum nennt gunther mich einen dieb","habe ich gunthers buch gestohlen","gestohlenes buch"}},{q="Schließt sich Gunther sofort den Verlassenen an?",a="Nein. Gunther ist fassungslos, als er erfährt, dass Bethor lebt und frei ist, doch er bleibt den Verlassenen gegenüber misstrauisch. Er bittet Euch, Eure Feindschaft zur Geißel zu beweisen, indem Ihr ihre Agentin Lillith Nefara an einem alten Altar vor der Südküste der Insel beschwört und vernichtet.",al={"schließt sich gunther sylvanas an","gunthers loyalität","wie geht es mit gunther weiter"}}},fx={["3bda1a56"]={q="Warum möchte Bethor Eismacht Gunther rekrutieren?",a="Bethor und Gunther waren enge Freunde und Magierkollegen innerhalb des Kirin Tor von Dalaran, bevor beide der Seuche erlagen. Nachdem er erfahren hat, dass es Gunther gelungen war, sich aus dem Griff des Lichkönigs aus eigener Kraft zu befreien, möchte Bethor seinen mächtigen ehemaligen Kollegen verzweifelt zu den Verlassenen holen. Durch die Rückgabe von Gunthers verzaubertem Zauberbuch hofft Bethor zu beweisen, dass andere Untote ihren freien Willen zurückgewonnen haben, und den zurückgezogenen Nekromanten davon zu überzeugen, dass er nicht länger allein dastehen muss.",al={"warum will bethor gunther","bethor eismachts beweggründe","warum gunther rekrutieren"}}},fp="15,161,23.313.0,25.473.0,22.328.1,43.204.0,39.204.0,42.202.0,23.186.0,45.205.0,43.240.1"}
P.entries["quest:367"] = {n="Eine neue Seuche",s="In Brill sammelt Apotheker Johaan Blut von Schattenhunden für eine neue Seuche. Die Königliche Apothekervereinigung arbeitet auf Befehl von Fürstin Sylvanas Windläufer.",h="In Brill sammelt Apotheker Johaan Blut von Schattenhunden für eine neue Seuche.",kw={"apotheker","arthas","brill","schattenhund","johaan","seuche","geißel","sylvanas","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde steht Ihr an der Seite der Verlassenen. Ihre alchemistische Arbeit in Tirisfal konzentriert sich auf eine finstere Waffe, die gegen Northrend gerichtet ist.",["race:Undead"]="Als Untoter leistet Ihr Euren ersten direkten Beitrag zum Projekt der Königlichen Apothekervereinigung: der Erschaffung jener Waffe, die Sylvanas gegen Arthas einsetzen will."},sec={{t="Ein königlicher Auftrag",b="Apotheker Johaan dient der Königlichen Apothekervereinigung in Brill auf Befehl der Dunklen Fürstin. Sylvanas Windläufer hat ihre Alchemisten beauftragt, eine Krankheit zu erschaffen, wie Azeroth sie noch nie gekannt hat.\n\nDie Seuche des Untodes des Lichkönigs schlachtete die Menschheit ab und knechtete ihre Seelen. Diese neue Seuche soll Arthas Menethil vernichten und seine Legionen der Geißel verheeren."},{t="Die Grundzutaten",b="Johaan strebt finstere Experimente für eine Waffe gegen die Untoten an. Er glaubt, dass das Blut einheimischer Bestien nützliche chemische Eigenschaften besitzen könnte, und beginnt mit Schattenhunden, die Tirisfal durchstreifen.\n\nIhr sammelt Phiolen ihres verdorbenen Blutes. Johaan kann dessen Bestandteile isolieren und prüfen, ob die Widerstandskraft und die räuberische Natur der Bestien helfen könnten, eine tödliche Seuche zu erschaffen."}},faq={{q="Was ist das Ziel der neuen Seuche?",a="Fürstin Sylvanas hat die Königliche Apothekervereinigung beauftragt, eine Krankheit zu brauen, die tödlicher ist als jede andere auf Azeroth. Sie soll Arthas und seine Armee der Geißel vernichten.",al={"warum eine neue seuche erschaffen","zweck der neuen seuche","was bewirkt die seuche"}},{q="Wer ist Apotheker Johaan?",a="Johaan dient der Königlichen Apothekervereinigung in Brill. Er führt erste Feldversuche mit Substanzen durch, die von den einheimischen Bestien Tirisfals stammen.",al={"wer ist johaan","geschichte von apotheker johaan"}},{q="Warum braucht Johaan Schattenhundblut?",a="Johaan glaubt, dass das Blut einheimischer Bestien eine Grundlage für seine alchemistischen Formeln liefern könnte. Er braucht Schattenhundblut, um seine ersten Theorien im Labor zu prüfen.",al={"warum schattenhundblut","wozu dient das blut"}},{q="Wie unterscheidet sich diese Seuche von der Seuche der Geißel?",a="Die Seuche des Untodes des Lichkönigs wurde erschaffen, um die Lebenden abzuschlachten und ihre Seelen zu knechten. Sylvanas' neue Seuche soll Arthas' untote Legionen ins Verderben stürzen.",al={"unterschied zwischen den seuchen","seuche der geißel gegen seuche der verlassenen"}},{q="Wer hat die Erschaffung dieser Seuche angeordnet?",a="Fürstin Sylvanas Windläufer hat der Königlichen Apothekervereinigung direkt befohlen, die Seuche zu erschaffen. Sie glaubt, dass die Alchemie der Verlassenen zusammen mit neu entdeckter Magie Arthas besiegen kann.",al={"wer begann die seuchenforschung","wer will die seuche"}},{q="Was geschieht nach dem Sammeln des Blutes?",a="Das Sammeln von Schattenhundblut leitet eine Reihe von Experimenten ein. Johaan nutzt die Proben, um den Krankheitserreger durch weitere Feldversuche in ganz Tirisfal zu verfeinern.",al={"was ist der nächste schritt","wirkt die seuche"}}},fx={["399e4c7c"]={q="Warum möchte Apotheker Johaan, dass dies erledigt wird?",a="Lady Sylvanas persönlich forderte die Königliche Apothekervereinigung auf, eine Waffe zu erschaffen, die tödlicher ist als jede Plage auf Azeroth, konstruiert, um Arthas und seine Armee der Geißel ins Verderben zu stürzen. Als Apotheker der Vereinigung, stationiert in Brill, strebt Johaan danach, das Mandat der Dunklen Fürstin zu erfüllen, indem er seine Theorien an heimischen Tier-Reagenzien testet.",al={"johaan beweggrund","warum will johaan eine neue seuche","warum johaan helfen"}},["762eb481"]={q="Was sind Dunkelhunde und warum sollte man sie hier jagen?",a="Dunkelhunde sind wilde, korrumpierte Raubbestien, die durch die verpesteten Wälder und Pfade von Tirisfal streifen. Ihr Blut hat die korrumpierenden Energien aufgesogen, die in das Land sickern, was sie zu erstklassigen biologischen Proben für die toxikologischen Experimente der Königlichen Apothekervereinigung macht.",al={"was sind dunkelhunde","dunkelhunde tirisfal","warum dunkelhunde"}}},fp="12,151,15.367.0,15.361.0,35.160.0,25.142.0,37.161.0,54.161.0,40.170.0,39.151.0"}
P.entries["quest:368"] = {n="Eine neue Seuche",s="In Brill sammelt Apotheker Johaan Finsterflossenschuppen für die Arbeit der Königlichen Apothekervereinigung an einer Seuche. Er hofft, dass sie sich über vereinzelte Opfer hinaus ausbreitet und größere Bevölkerungsgruppen erfasst.",h="In Brill sammelt Apotheker Johaan Finsterflossenschuppen für die Arbeit der Königlichen Apothekervereinigung...",kw={"eine neue seuche","apotheker johaan","brill","murloc","königliche apothekervereinigung","tirisfal","finsterflossenschuppe"},ang={["faction:Horde"]="Als Mitglied der Horde führt Ihr gemeinsam mit den Verlassenen Krieg gegen die Geißel. Die Verlassenen entwickeln ihre neue Seuche als Waffe gegen die Geißel.",["race:Undead"]="Als Angehörige der Verlassenen helft Ihr Apotheker Johaan, eine tödliche Seuche zu entwickeln, um Euer souveränes Reich zu schützen und Eure Feinde zu vernichten."},sec={{t="Die Ansteckung ausweiten",b="Apotheker Johaans Arbeit in Brill verlangt mehr als ein Gift, das einem einzelnen Ziel schadet. Er sucht nach einer Krankheit, die sich selbstständig ausbreiten und in freier Wildbahn überdauern kann. Deshalb untersucht er die Tierwelt an den Küsten von Tirisfal. Die widerstandsfähigen Finsterflossenmurlocs liefern vielversprechendes Material."},{t="Die Reagenzien der Finsterflossen",b="Aggressive Stämme der Finsterflossenmurlocs machen die nördlichen und westlichen Küsten von Tirisfal unsicher. Ihre Schuppen enthalten organische Verbindungen, die an feuchte, raue Bedingungen angepasst sind. Johaan hofft, dass diese glitschigen, widerstandsfähigen Schuppen die neue Seuche der Königlichen Apothekervereinigung stärken und ihr helfen, in freier Wildbahn zu überdauern."}},faq={{q="Was ist das Ziel von Apotheker Johaans Forschung?",a="Apotheker Johaan entwickelt eine Seuche für die Königliche Apothekervereinigung und Lady Sylvanas. Er hofft, dass sie sich über ganze Bevölkerungen und Länder ausbreitet und sowohl die Lebenden als auch die Geißel trifft.",al={"warum eine neue seuche entwickeln","johaan seuche ziel","was macht johaan"}},{q="Warum braucht Johaan ausgerechnet Murlocschuppen?",a="Johaan sucht Finsterflossenschuppen wegen ihrer biologischen Verbindungen, die seiner Seuche helfen könnten, in freier Wildbahn zu überdauern und von Wirt zu Wirt überzugehen. Seine frühen Brauversuche zeigten, dass einfachen Giften die nötige Komplexität fehlt, um sich wirksam auszubreiten.",al={"warum murlocschuppen","finsterflossenschuppe zweck","warum schuppen für die seuche"}},{q="Wo sind die Finsterflossenmurlocs zu finden?",a="Die Finsterflossenmurlocs leben an den Küsten von Tirisfal, besonders an den nördlichen Stränden am großen Meer und entlang der Westküste.",al={"wo sind murlocs in tirisfal","finsterflossen fundort","murloc fundorte"}},{q="Wem untersteht Apotheker Johaan?",a="Apotheker Johaan dient der Königlichen Apothekervereinigung, einer Alchemistengilde mit Sitz in Unterstadt. Die Vereinigung untersteht unmittelbar Königin Sylvanas Windläufer.",al={"wer führt die apotheker","johaan vorgesetzter","königliche apothekervereinigung anführer"}},{q="Was ist der nächste Schritt in dieser Questreihe?",a="Nachdem Ihr Johaan die Finsterflossenschuppen gebracht habt, verfeinert er die Formel weiter. Er braucht weitere biologische Bestandteile und plant, den frisch gebrauten Erregerstamm zu testen.",al={"what comes next","nach den finsterflossenschuppen","nächste seuchenquest"}},{q="Haben die Verlassenen Bedenken, Teile von Murlocs zu verwenden?",a="Die Königliche Apothekervereinigung geht bei ihren Experimenten pragmatisch und amoralisch vor. Sie gewinnt Material aus der örtlichen Pflanzenwelt, Tierwelt oder aus Bestien, wann immer diese die benötigten biochemischen Eigenschaften bieten.",al={"murloc alchemie gefährlich","warum murlocs ausschlachten"}}},fx={["2300af12"]={q="Wozu dient die Finsterflossenschuppe?",a="Apotheker Johaan benötigt Finsterflossenschuppen als lebenswichtiges Reagenz für die Formulierung der neuen Plage der Königlichen Apothekervereinigung. Während einfache Gifte leicht ein isoliertes Opfer zu Fall bringen können, erkennt Johaan, dass die Entwicklung einer virulenten Krankheit, die imstande ist, sich über eine ganze Welt auszubreiten, weit komplexere biologische Inhaltsstoffe erfordert, um eine ordnungsgemäße Ansteckung sicherzustellen.",al={"zweck der finsterflossenschuppe","warum finsterflossenschuppen","wofür sind die murloc-schuppen"}},["0dd4c7ec"]={q="Wer sind die Finsterflossen-Murlocs?",a="Die Finsterflossen sind ein Stamm primitiver Murlocs, die entlang der Nordküste und der westlichen Gewässer von Tirisfal hausen. Wie die meisten ihrer Art verteidigen sie ihre Siedlungen an der Küste und ihre Nahrungsgründe aggressiv gegen alle Außenstehenden, die sich in die Nähe ihrer Ufer verirren.",al={"finsterflossen-murlocs","wer sind die finsterflossen","murlocs in tirisfal"}}},fp="12,182,24.269.0,21.291.0,49.195.0,48.227.0,40.137.0,37.165.0,42.157.0,52.167.0"}
P.entries["quest:3681"] = {n="Foliant der Offenbarung",s="In Eisenschmiede schickt Meister Brandur Eisenhammer vielversprechende menschliche Paladine zur vertieften Ausbildung nach Süden. In Sturmwinds Kathedrale des Lichts leitet Meister Duthorian Rall ihr Studium der heiligen Folianten der Offenbarung.",h="In Eisenschmiede schickt Meister Brandur Eisenhammer vielversprechende menschliche Paladine zur vertieften...",kw={"brandur eisenhammer","kathedrale des lichts","duthorian rall","eisenschmiede","paladin","erlösung","sturmwind","foliant der offenbarung"},ang={["class:Paladin"]="Als Paladin entwickelt Ihr Euch vom Kampfneuling zum geweihten Diener des Heiligen Lichts, der dessen tiefste heilende Wunder wirken kann.",["faction:Alliance"]="Als Mitglied der Allianz teilt Ihr die Ausbildung zum heiligen Krieger in Sturmwind und stärkt damit das geistliche und militärische Band zwischen Eisenschmiede und Sturmwind.",["race:Dwarf"]="Als Zwerg folgt Ihr den stolzen Paladintraditionen Khaz Modans und widmet Euch den Folianten der Offenbarung in Eisenschmiede. Menschliche Paladine werden nach Sturmwind gerufen."},sec={{t="Ein Ruf aus Sturmwind",b="Sturmwind ruft vielversprechende heilige Krieger nach Süden zur Kathedrale des Lichts. Hohe Priester und Paladinmentoren erwarten sie dort und halten die Traditionen der Silver Hand in der Kirche des Heiligen Lichts in den Menschenlanden lebendig."},{t="Der Weg zur Kathedrale",b="Meister Brandur Eisenhammer erkennt, wann ein Schüler für ein vertieftes Studium des Glaubens bereit ist. Ihr könnt Sturmwinds Cathedral District mit der Tiefenbahn oder über die Gebirgspässe erreichen. Dort bereitet Duthorian Rall Initianden darauf vor, die heiligen Folianten zu studieren und die Riten der Erlösung zu erlernen."}},faq={{q="Warum schickt mich ein Ausbilder aus Eisenschmiede nach Sturmwind?",a="Sturmwinds Kathedrale des Lichts übernimmt die fortgeschrittene Ausbildung der Paladine der Allianz. Brandur Eisenhammer schickt vielversprechende Initianden zu Meister Duthorian Rall, um die Prüfungen zu bestehen, die mit den heiligen Folianten der Offenbarung verbunden sind.",al={"warum nach sturmwind","warum zu duthorian rall geschickt","eisenschmiede nach sturmwind paladin"}},{q="Wer ist Brandur Eisenhammer?",a="Brandur Eisenhammer ist ein zwergischer Paladinausbilder in Eisenschmiedes Hall of Mysteries im Mystic Ward. Er wacht über Initianden, lehrt Hingabe im Kampf und führt sie zu höheren Studien, während ihre Bindung an das Heilige Licht wächst.",al={"brandur eisenhammer","wer ist brandur"}},{q="Wer ist Duthorian Rall?",a="Duthorian Rall ist ein hochrangiger Paladinausbilder und Prälat in Sturmwinds Kathedrale des Lichts. Er stellt angehende Paladine auf geistliche Prüfungen, bevor er ihnen die Folianten der Offenbarung anvertraut.",al={"duthorian rall","wer ist duthorian"}},{q="Was sind die Folianten der Offenbarung?",a="Die Folianten der Offenbarung sind heilige Schriften und Lehrbücher der Kirche des Heiligen Lichts. Sie lehren Paladine die Riten der Auferstehung, der Selbstaufopferung und des Mitgefühls.",al={"was ist der foliant der offenbarung","foliant der offenbarung bedeutung"}},{q="Wie kommt man von Eisenschmiede am schnellsten nach Sturmwind?",a="Die Tiefenbahn ist der schnellste und sicherste Weg von Eisenschmiede nach Sturmwind. Von Tüftlerstadt aus bringt sie Reisende unter den Bergen hindurch nach Sturmwind.",al={"wie nach sturmwind kommen","tiefenbahn nach sturmwind"}},{q="Ist diese Prüfung für alle Paladine der Allianz erforderlich?",a="Nein. Menschliche Paladine studieren die Folianten unter Duthorian Rall in Sturmwinds Kathedrale des Lichts. Zwergische Paladine beginnen ihre eigenen Prüfungen zum Folianten der Offenbarung in Eisenschmiede bei Tiza Kriegshammer.",al={"müssen zwerge das machen","paladin klassenquest voraussetzung"}}},fx={["538cdf30"]={q="Warum schickt Brandur Eisenhammer Euch nach Sturmwind?",a="Brandur Eisenhammer folgt einer offiziellen Vorladung der Kathedrale des Lichts in Sturmwind. Die Anführer der Silbernen Hand haben darum gebeten, dass vielversprechende Paladine für eine rigorose, fortgeschrittene Ausbildung nach Süden entsandt werden. Da Brandur Eure wachsende Stärke und Hingabe erkennt, weiß er, dass Ihr einen kritischen Punkt in Eurer Berufung erreicht habt, an dem die Standardausbildung in Eisenschmiede nicht mehr ausreicht; Ihr seid bereit, die heiligen Folianten direkt unter Duthorian Rall zu studieren.",al={"beweggrund brandur eisenhammer","warum schickt mich brandur","brandur eisenhammer sturmwind"}},["3ec0b7fd"]={q="Warum werdet Ihr für diese Aufgabe ausgewählt und nicht jemand anderes?",a="Ihr werdet ausgewählt, weil die Vorladung ausdrücklich nach aufstrebenden Paladinen verlangt, die sich für die tieferen Mysterien des Heiligen Lichts bereit erwiesen haben. Weder Wachen noch erfahrene Veteranen können diese Reise für Euch antreten, da die Tome of Divinity eine zutiefst persönliche spirituelle und kriegerische Prüfung darstellen, die für das Vorankommen innerhalb der Silbernen Hand erforderlich ist.",al={"warum ich tome of divinity","warum sendet ihr mich sturmwind paladin","warum kein anderer paladin"}}},fp="16,206,24.219.0,25.284.0,52.200.0,26.231.0,22.192.0,31.174.0,58.159.0,49.183.0"}
P.entries["quest:369"] = {n="Eine neue Seuche",s="In Brill sucht Apotheker Johaan in alten Aufzeichnungen nach einer Seuche, die im Spinnengift überdauert hat. Er hofft, den Verlassenen einen wirksamen neuen biologischen Kampfstoff zu verschaffen.",h="In Brill sucht Apotheker Johaan in alten Aufzeichnungen nach einer Seuche, die im Spinnengift überdauert hat.",kw={"eine neue seuche","apotheker johaan","brill","nachtnetzspinne","königliche apothekervereinigung","tirisfal","gift","giftwebertal"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr den Forschern der Verlassenen als verbündeter Orc oder Tauren helfen. Ihre biologischen Experimente beunruhigen oft den Rest der Horde.",["race:Undead"]="Als Verlassener sucht Ihr nach einer neuartigen Waffe, um Euer Volk vor Überresten der Geißel und Scarlet crusaders vor Eurer Haustür zu schützen."},sec={{t="Uralte Seuchen aufspüren",b="Apotheker Johaan studiert in Brill alte Texte für die Königliche Apothekervereinigung. Dort findet er Aufzeichnungen über eine uralte Pestilenz, die Tausende tötete. Den Schriften zufolge überdauerte ihr Erreger über Generationen hinweg im Gift der in Tirisfal heimischen Spinnen. Johaan benötigt dieses Gift als biologisches Reagenz."},{t="Jagd im Giftwebertal",b="Apotheker Johaan schickt Agenten ins östliche Tirisfal, um eine lebende Probe zu beschaffen. Das Giftwebertal liegt südlich des Scharlachroten Klosters, und bösartige Nachtnetzspinnen bevölkern seine Senke. Um frische Giftdrüsen für Johaans experimentelles Gebräu zu sammeln, müssen die Sammler in die Baue der Spinnen vordringen."},{t="Die endgültige Mischung brauen",b="Apotheker Johaan gießt das gewonnene Gift in einen brodelnden Kessel mit zuvor gesammelten Reagenzien. Während die Mischung einkocht, vervollständigt der ansteckende Bestandteil der Spinnen das Gemisch. Die Königliche Apothekervereinigung kommt praktischen Feldversuchen näher."}},faq={{q="Warum will Apotheker Johaan Spinnengift?",a="Ein uralter Text, den Apotheker Johaan gefunden hat, besagt, dass eine Seuche, die Tausende tötete, im Gift der Nachtnetzspinnen Tirisfals überdauerte. Er will diesen ansteckenden Bestandteil für sein Gebräu nutzen.",al={"warum spinnengift","apotheker johaan spinnen","spinnengift verwendung"}},{q="Wo leben die bösartigen Nachtnetzspinnen?",a="Bösartige Nachtnetzspinnen leben im Giftwebertal, im östlichen Tirisfal südlich des Scharlachroten Klosters.",al={"wo sind nachtnetzspinnen","nachtnetzspinnen fundort","giftwebertal lage"}},{q="Welches Ziel verfolgt die Königliche Apothekervereinigung mit ihrer Forschung hier?",a="Die Königliche Apothekervereinigung sucht nach einem tödlichen neuen Erregerstamm, um sowohl die Geißel als auch die Lebenden auszurotten. Die Verlassenen hoffen, damit ihr Überleben und ihre Unabhängigkeit in Lordaeron zu sichern.",al={"warum eine neue seuche erschaffen","verlassene seuche ziele","königliche apothekervereinigung seuche"}},{q="Wer ist Apotheker Johaan?",a="Apotheker Johaan ist ein Forscher der Verlassenen in Brill, der für die Königliche Apothekervereinigung arbeitet. Er beaufsichtigt die örtlichen chemischen und biologischen Experimente und verbindet dabei dunkle Alchemie mit Reagenzien, die in Tirisfal gesammelt werden.",al={"wer ist johaan","apotheker johaan hintergrund"}},{q="Was geschieht, nachdem dieses Gift gesammelt wurde?",a="Nachdem Johaan das Gift in seinem Gebräu eingekocht hat, bereitet er sich darauf vor, das Gemisch zu testen. Er will herausfinden, ob der entstandene Giftstoff die gewünschte tödliche Wirkung hat.",al={"was geschieht als nächstes","eine neue seuche questfortsetzung","nach eine neue seuche 3"}},{q="Ist dies dieselbe Seuche, die die Geißel erschaffen hat?",a="Nein. Die Geißel verbreitete die Plague of Undeath, die vom Lich King erschaffen wurde. Die Apotheker der Verlassenen entwickeln eine eigene, andersartige biologische Waffe.",al={"ist das die seuche der geißel","plague of undeath unterschied"}}},fx={["25fc540a"]={q="Warum benötigt Apotheker Johaan dieses Gift ausgerechnet jetzt?",a="Beim Studium seiner Folianten entdeckte Apotheker Johaan, dass eine uralte Seuche, die Tausende Unschuldige dahinraffte, im Gift von Nachtweberspinnen konserviert wurde. Er benötigt dieses letzte Reagenz, um zu testen, ob dessen ansteckende Eigenschaften sein Gebräu wahrhaft tödlich und infektiös machen können.",al={"johaan beweggrund","warum will johaan das erledigt haben","warum spinnengift sammeln"}},["3c54dfe3"]={q="Was sind Bösartige Nachtweberspinnen und warum sind sie das Ziel?",a="Bösartige Nachtweberspinnen sind tödliche Arachniden, die in den östlichen Ausläufern von Tirisfal lauern, insbesondere um das Giftwebertal. Johaan hat es auf sie abgesehen, da in alten Texten vermerkt ist, dass ihr Gift auf natürliche Weise die tödlichen, virulenten Eigenschaften einer vergessenen historischen Seuche in sich trägt und bewahrt.",al={"warum bösartige nachtweberspinnen","was sind nachtweberspinnen","gegen wen werden wir ausgesandt"}}},fp="12,152,29.306.0,25.287.0,29.253.1,45.188.0,44.107.0,65.181.0,25.206.0,42.156.1,49.151.0"}
P.entries["quest:37"] = {n="Suche nach den vermissten Wachen",s="Wache Thomas wartet an Elwynns östlicher Brücke auf Nachricht von zwei vermissten Wachen aus Sturmwind.",h="Wache Thomas wartet an Elwynns östlicher Brücke auf Nachricht von zwei vermissten Wachen aus Sturmwind.",kw={"wald von elwynn","suche nach den vermissten wachen","wache thomas","halb aufgefressene leiche","malakai","malakai stone","murlocs","rolf"},ang={["class:Paladin"]="Als Paladin könnt Ihr gefallene Verteidiger ehren, indem Ihr ihre Abzeichen bergt und jenen Gerechtigkeit bringt, die die Grenze des Königreichs bewachen.",["faction:Alliance"]="Als Soldat der Allianz seht Ihr, wie Angriffe von Wildtieren und Murlocs Elwynns Außengrenzen bedrohen, selbst so nahe an Sturmwind."},sec={{t="Eine verschwundene Patrouille",b="Am Übergang, wo sich die Königsstraße dem Rotkammgebirge nähert, sind die Flussufer gefährlicher geworden. Vor Tagen schickte Thomas Rolf und Malakai am Fluss entlang nach Norden, um die Bedrohung durch Murlocs auszukundschaften und ihre Nester auszuräumen. Nun fürchtet er, dass Gewalt ihre Patrouille aufgehalten hat."},{t="Ein grausiger Fund",b="Nördlich am Fluss entlang in Richtung des Steinhügelsees umringen Euch Murlocs in Scharen. Am Wasserrand findet Ihr eine halb aufgefressene Leiche im Schlamm. Ein graviertes Medaillon daneben trägt den Namen Soldat Malakai Stone. Malakai ist tot, doch Rolf wird noch immer vermisst."}},faq={{q="Wer hat diese Quest vergeben und wo ist diese Person zu finden?",a="Wache Thomas wartet neben der Brücke an der östlichen Grenze des Walds von Elwynn, wo die Straße zum Rotkammgebirge führt.",al={"questgeber","wo ist wache thomas","wer startet suche nach den vermissten wachen"}},{q="Wer sind die vermissten Wachen?",a="Rolf und Malakai sind zwei Fußsoldaten der Stadt Sturmwind. Wache Thomas schickte sie los, um die Flussufer auszukundschaften und nach aggressiven Murlocs Ausschau zu halten.",al={"vermisste wachen elwynn","wer sind rolf und malakai","namen der vermissten wachen"}},{q="Wo werden die Überreste gefunden?",a="Die halb aufgefressenen Überreste von Soldat Malakai Stone liegen am östlichen Flussufer, etwas nördlich vom Posten von Wache Thomas, nahe dem Rand einer Murlocsiedlung.",al={"wo ist malakais leiche","fundort der halb aufgefressenen leiche","fundort der vermissten wachen"}},{q="Was hat Malakai getötet?",a="Die örtlichen Flussmurlocs überwältigten Malakai und fraßen ihn. Sie bevölkern die Ufer im östlichen Wald von Elwynn.",al={"wie starb malakai","wer tötete die wachen"}},{q="Was ist mit Rolf geschehen?",a="Ihr findet nur Malakais Überreste am Fluss. Rolf wird noch immer vermisst, und sein Schicksal bleibt unbekannt, während Ihr tiefer in die Murloclager vordringt.",al={"wo ist rolf","hat rolf überlebt"}},{q="Warum wurden die Wachen allein ausgesandt?",a="Sturmwinds Streitkräfte sind über mehrere Gebiete verteilt und stark ausgelastet. Kleine Garnisonen wie die von Wache Thomas sind auf Wachpaare angewiesen, die an den Grenzen zur Wildnis patrouillieren.",al={"warum wurden sie ausgesandt","wachenmangel in sturmwind"}}},fx={["5aa1fbbd"]={q="Warum möchte Wache Thomas, dass Ihr die vermissten Wachen findet?",a="Wache Thomas hat Rolf und Malakai vor Tagen auf eine Erkundungspatrouille den Fluss entlang nach Norden geschickt. Sie sind nie zurückgekehrt. Als der Offizier, der diesen Abschnitt des östlichen Waldes von Elwynn beaufsichtigt, muss Thomas für seine vermissten Männer Rechenschaft ablegen, um seinen offiziellen Bericht für die Wache von Sturmwind fertigzustellen – sei es, indem er sie nach Hause bringt oder ihren Tod bestätigt.",al={"warum vermisste wachen finden","wache thomas beweggrund","warum nach rolf und malakai suchen"}},["18be7cf7"]={q="Warum bittet Wache Thomas einen Abenteurer, anstatt mehr Wachen zu schicken?",a="Wache Thomas und seine verbleibenden Männer sind bei der Verteidigung der Brücken und Grenzen des östlichen Waldes von Elwynn durch zunehmende Murloc-Überfälle und Gnolleinfälle vollkommen ausgelastet. Da das Militär von Sturmwind über das ganze Königreich verteilt ist und bereits zwei Fußsoldaten fehlen, kann er es sich nicht leisten, weitere Posten abzuziehen, um einen Suchtrupp zu bilden.",al={"warum kann thomas sie nicht finden","warum fragt ihr mich nach den vermissten wachen","warum braucht thomas hilfe"}}},fp="20,92,17.254.0,14.257.1,47.124.0,27.129.0,28.151.1,20.97.1,22.141.1,35.160.0"}
P.entries["quest:370"] = {n="Im Krieg mit dem Scharlachroten Kreuzzug",s="In Tirisfal greifen die Verlassenen Truppen des Scharlachroten Kreuzzugs an, die ihre Grenzen bedrohen. Exekutor Zygand schickt Recken gegen Hauptmann Perrine und seine Garnison an einem verfallenen Turm südwestlich von Brill, gestützt auf in Todesend erbeutete Informationen.",h="In Tirisfal greifen die Verlassenen Truppen des Scharlachroten Kreuzzugs an, die ihre Grenzen bedrohen.",kw={"brill","hauptmann perrine","exekutor arren","exekutor zygand","proof of demise","verfallener turm","scharlachroter kreuzzug","scharlachroter missionar","scharlachroter eiferer","tirisfal"},ang={["faction:Horde"]="Der Brückenkopf der Horde in den Östlichen Königreichen hängt davon ab, dass die Verlassenen Tirisfal gegen feindliche menschliche Eiferer sichern.",["race:Undead"]="Für die Verlassenen ist die Vernichtung des Scharlachroten Kreuzzugs überlebenswichtig. Die Eiferer unterscheiden nicht zwischen Untoten mit freiem Willen und der Geißel."},sec={{t="Erkenntnisse im Einsatz",b="Exekutor Arren erbeutete in Todesend Dokumente des Scharlachroten Kreuzzugs. Sie enthüllten Truppenbewegungen in ganz Tirisfal. Deshalb nutzt Exekutor Zygand diese Informationen, um zuerst die Feldkommandanten anzugreifen, bevor die Fanatiker das neu befestigte Brill angreifen können."},{t="Bedrohung am verfallenen Turm",b="An einem verfallenen Wachturm südwestlich von Brill befehligt Hauptmann Perrine Scharlachrote Eiferer und Missionare. Der Kreuzzug beobachtet von dort aus die Bewegungen der Verlassenen und dringt weiter nach Tirisfal vor. Perrines Tod ist für die Verteidigung des jungen Reiches der Dunklen Fürstin von Bedeutung."}},faq={{q="Wer ist Hauptmann Perrine?",a="Hauptmann Perrine ist ein Offizier des Scharlachroten Kreuzzugs an einem verfallenen Wachturm südwestlich von Brill. Er befehligt eine Abteilung aus Eiferern und Missionaren, die nach Tirisfal vordringen.",al={"hauptmann perrine","perrine","wer ist perrine"}},{q="Woher haben die Verlassenen Informationen über Hauptmann Perrine?",a="Exekutor Arren erbeutete während der Verteidigung von Todesend Dokumente des Kreuzzugs. Sie beschreiben Truppenzuweisungen und die Standorte von Außenposten, darunter Perrines Posten.",al={"strategische dokumente zygand","arrens dokumente","scharlachrote dokumente todesend"}},{q="Warum sind Scharlachrote Missionare und Eiferer in Tirisfal?",a="Der Scharlachrote Kreuzzug betrachtet alle Untoten als Abscheulichkeiten, die ausgerottet werden müssen, ob sie der Geißel oder den Verlassenen dienen. Seine Missionare und Eiferer dringen nach Tirisfal vor, um einen heiligen Krieg zu führen und Lordaeron für die Lebenden zurückzuerobern.",al={"warum ist der scharlachrote kreuzzug in tirisfal","scharlachrote missionare tirisfal","scharlachrote eiferer"}},{q="Wie fügt sich diese Quest in den Feldzug gegen den Kreuzzug ein?",a="Perrines Tod zerschlägt einen örtlichen Spähposten. Er ist der zweite Schritt im Feldzug gegen den Kreuzzug in Tirisfal, bevor Exekutor Zygand die Einsätze gegen größere Lager in der Region ausweitet.",al={"im krieg mit dem scharlachroten kreuzzug questreihe","was kommt nach perrine"}},{q="Lässt sich diese Quest mit anderen Aufgaben in der Nähe verbinden?",a="Ja. Proof of Demise lässt sich damit verbinden. Todeswache Burgess verlangt Scharlachrote Insignienringe von denselben Kreuzfahrern als Beweis der Treue gegenüber Varimathras und der Dunklen Fürstin.",al={"proof of demise kombinieren","quests kombinieren perrine","brill turm quests"}},{q="Wer ist Exekutor Zygand?",a="Exekutor Zygand ist der oberste in Brill stationierte Militärkommandant. Er sichert Tirisfal und leitet strategische Offensiven für Sylvanas Windläufer.",al={"zygand","exekutor zygand brill"}}},fx={["6b0cf47a"]={q="Warum möchte Exekutor Zygand, dass Hauptmann Perrine getötet wird?",a="Exekutor Zygand beabsichtigt, die Ländereien um Brill von dem zu säubern, was er als menschlichen Befall betrachtet. Nachdem er abgefangene strategische Dokumente des Kreuzzugs analysiert hat, weiß er, dass Hauptmann Perrine eine befestigte Brigade am zerstörten Turm südwestlich der Stadt befehligt. Ein Schlag gegen Perrine und sein Gefolge bricht das lokale Kommando des Kreuzzugs und dient direkt der Eroberung von Tirisfal durch die Dunkle Fürstin.",al={"warum perrine töten","zygand beweggründe","warum die scharlachrote brigade angreifen"}}},fp="31,240,23.253.0,30.259.0,23.171.0,58.164.0,53.222.0,62.206.0,58.171.0,23.154.0"}
P.entries["quest:371"] = {n="Krieg mit dem Scharlachroten Kreuzzug",s="Nahe Balnirs Bauernhof schickt Exekutor Zygand Kämpfer der Verlassenen gegen den Scharlachroten Kreuzzug. Ihr Ziel sind Captain Vachon und seine Brüder im südöstlichen Tirisfal, wo Überfälle der Kreuzfahrer die Ländereien der Dunklen Fürstin bedrohen.",h="Nahe Balnirs Bauernhof schickt Exekutor Zygand Kämpfer der Verlassenen gegen den Scharlachroten Kreuzzug.",kw={"arren","balnir","brill","kreuzfahrer","bruder","tirisfal","turm","vachon","zygand"},ang={["class:Priest"]="Als Priester steht Ihr Scarlet Friars gegenüber, deren dogmatischer Glaube an heilige Macht mit Eurer Beherrschung des Schattens und verzerrter heiliger Macht kollidiert.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, den Zugang nach Unterstadt offen zu halten und die Verbindungswege durch das nördliche Lordaeron zu sichern.",["race:Undead"]="Als Untoter helft Ihr mit jedem geräumten Posten der Kreuzfahrer in Tirisfal, die Grenzen Eurer jungen Nation zu sichern. Ihr schützt Lady Sylvanas' Reich vor lebenden Läuterern."},sec={{t="Ein drohender Vorstoß",b="Brill und Unterstadt werden von den Verlassenen bewacht, während der Scharlachrote Kreuzzug befestigte Stellungen im gesamten Umland hält. Von einem verfallenden Wachturm im südöstlichen Tirisfal meldet Exekutor Arren aktive Vorstöße der Kreuzfahrer. Der Turm steht nahe dem verlassenen Balnirs Bauernhof."},{t="Die Befehlskette durchtrennen",b="Exekutor Zygand greift die Anführer des Kreuzzugs im Feld an, denn koordinierte Trupps sind gefährlicher als verstreute Eiferer. Ihr greift Captain Vachon und die Scarlet Friars an, die seine Männer mit heiliger Magie stärken. Ohne ihre Anführer und Unterstützung könnte die Zelle ihren Zusammenhalt verlieren, und ihre Überfälle auf die Ländereien der Verlassenen könnten ins Stocken geraten."}},faq={{q="Wer befiehlt diesen Angriff?",a="Exekutor Zygand, der in Brill stationiert ist, befiehlt den Angriff. Exekutor Arren sammelte und überbrachte die Frontberichte über Bewegungen des Kreuzzugs nahe Balnirs Bauernhof.",al={"questgeber","wer gibt diese quest","wer ist zygand"}},{q="Wo befindet sich Captain Vachon?",a="Captain Vachon und seine Scarlet Friars haben ihren Stützpunkt in einem verfallenen Wachturm im südöstlichen Tirisfal, unmittelbar östlich von Balnirs Bauernhof.",al={"vachons standort","wo ist vachon","wo sind scarlet friars"}},{q="Warum nimmt Exekutor Zygand gezielt Scarlet Friars ins Visier?",a="Scarlet Friars geben den Eiferern magische und geistliche Unterstützung. Werden diese Zauberwirker besiegt, fallen Schutzzauber und Heilung weg, was die Einsätze des Trupps im Feld lähmt.",al={"warum brüder töten","scarlet friars"}},{q="Welche Bedrohung stellt der verfallene Turm für Brill dar?",a="Der verfallene Turm bietet dem Scharlachroten Kreuzzug eine erhöhte Stellung und einen befestigten Ausgangspunkt für Angriffe. Seine Patrouillen können Reisenden der Verlassenen auflauern und die Versorgungswege stören, die von Brill nach Osten führen.",al={"bedrohung durch den turm","warum den turm angreifen","balnir turm"}},{q="Wie fügt sich das in den größeren Konflikt mit dem Kreuzzug ein?",a="Dies ist die dritte Phase von Exekutor Zygands Feldzug gegen die Stützpunkte des Scharlachroten Kreuzzugs in Tirisfal. Er will die Eiferer zurückdrängen, bevor sie Unterstadt belagern können.",al={"questreihe zum scharlachroten krieg","hintergrund zum krieg mit dem scharlachroten kreuzzug"}},{q="Was geschieht, nachdem Captain Vachon getötet wurde?",a="Captain Vachons Niederlage verlangsamt die Vorstöße der Kreuzfahrer im südöstlichen Tirisfal. Exekutor Zygand richtet seine Aufmerksamkeit daraufhin auf größere Befestigungen des Scharlachroten Kreuzzugs in anderen Teilen der Region.",al={"nächste quest","was kommt nach vachon","folgen von vachons niederlage"}}},fx={bf2ccde1={q="Warum möchte Exekutor Zygand Hauptmann Vachon und die Brüder tot sehen?",a="Exekutor Arren sandte Nachricht, dass sich Scharlachrote Kreuzzügler im zerstörten Turm nahe The Balnir Farmstead verschanzt haben und aktiv Überfälle im südöstlichen Tirisfal durchführen. Der Scharlachrote Kreuzzug wird an den Grenzen des Gebiets immer stärker und bedroht Brill sowie die umfassendere Kampagne der Dunklen Fürstin. Durch die Ausschaltung von Hauptmann Vachon und seinen begleitenden Brüdern beabsichtigt Zygand, ihren offensiven Schwung zu bremsen und der lokalen Befehlsstruktur einen vernichtenden Schlag zu versetzen, bevor sie weiter in das Land der Verlassenen vorstoßen können.",al={"warum hauptmann vachon töten","zygand beweggründe","warum den scharlachroten turm angreifen"}},["6cf92196"]={q="Gegen wen werdet Ihr ausgesandt?",a="Ihr werdet ausgesandt, um Hauptmann Vachon und fünf Scharlachrote Brüder zu eliminieren, die den zerstörten Wachturm mit Blick auf das südöstliche Tirisfal besetzt halten. Vachon befehligt diese vorgeschobene Streitmacht des Scharlachroten Kreuzzugs und verlässt sich bei der heiligen Unterstützung und der Führung vor Ort auf eifernde Brüder. Ihre Anwesenheit so nah an The Balnir Farmstead bietet ihnen einen befestigten Stützpunkt, um Reisen der Verlassenen zu stören und die Untertanen der Dunklen Fürstin im ganzen Umland zu schikanieren.",al={"wer ist hauptmann vachon","wer sind die scharlachroten brüder","wen muss ich töten"}}},fp="31,219,22.295.0,29.320.0,23.159.0,32.134.0,60.171.0,48.187.0,61.187.0,43.180.0"}
P.entries["quest:372"] = {n="Im Krieg mit dem Scharlachroten Kreuzzug",s="In Tirisfal schickt Exekutor Zygand Agenten der Verlassenen von Brill aus gegen den Scharlachroten Kreuzzug. Hauptmann Melrache und seine eingeschworenen Wachen halten einen verfallenen Wachturm jenseits von Faols Ruheplatz.",h="In Tirisfal schickt Exekutor Zygand Agenten der Verlassenen von Brill aus gegen den Scharlachroten Kreuzzug.",kw={"brill","hauptmann melrache","exekutor zygand","faols ruheplatz","scharlachroter leibwächter","scharlachroter kreuzzug","tirisfal"},ang={["class:Rogue"]="Als Schurke schlagt Ihr hinter den feindlichen Linien zu, um einen Befehlshaber von seinen Truppen zu trennen, wie es die Todespirscher tun.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, ihren verwundbaren Stützpunkt in den Östlichen Königreichen zu schützen, indem Ihr die Grenzen von Tirisfal sichert.",["race:Undead"]="Als Angehöriger der Verlassenen tötet Ihr mit jedem Kreuzzügler einen weiteren Fanatiker, der Euch das Recht abspricht, in Eurer einstigen Heimat zu leben."},sec={{t="Ein Schlag gegen die Vorhut",b="Die Verlassenen sichern die Ruinen von Lordaeron, doch der Scharlachrote Kreuzzug stellt die Grenzen von Tirisfal immer wieder auf die Probe. Von einem Turm im Norden jenseits von Faols Ruheplatz aus führen Kreuzzügler Überfälle auf Patrouillen und Ländereien der Verlassenen an. Exekutor Zygand will die Offiziere, die diese Überfälle lenken, vor dem nächsten Angriff ausschalten."},{t="Hauptmann Melraches Stellung",b="Hauptmann Melrache befehligt das nördliche Lager mit zwei eingeschworenen Leibwächtern, die stets an seiner Seite bleiben. Vom Turm aus überwacht der Scharlachrote Kreuzzug die Küstenstraßen und die nahen Wälder. Tötet Melrache, und die Angreifer nahe Brill verlieren ihre Führung. Sein Fall beseitigt eine direkte Bedrohung für Fürstin Sylvanas' junges Königreich und treibt die Fanatiker zu stärkeren Befestigungen weiter im Osten."}},faq={{q="Wer ist Hauptmann Melrache?",a="Hauptmann Melrache befehligt ein Überfalllager des Scharlachroten Kreuzzugs in einem verfallenen Turm im nördlichen Tirisfal, jenseits von Faols Ruheplatz. Mit seinen persönlichen Leibwächtern führt er Überfälle auf die Ländereien der Verlassenen an.",al={"melrache","hauptmann melrache hintergrund","wer ist der scharlachrote hauptmann"}},{q="Wo liegt der verfallene Turm?",a="Der verfallene Turm steht im nördlichen Tirisfal, gleich hinter dem Friedhof Faols Ruheplatz, und überblickt die Nordküste.",al={"melraches standort","wo ist der turm","turm bei faols ruheplatz"}},{q="Warum will Exekutor Zygand Melrache tot sehen?",a="Melraches Truppen führen von ihrem Turm aus Überfälle durch, bedrängen Truppen der Verlassenen und bedrohen Brill und Unterstadt. Exekutor Zygand befiehlt Melraches Tod, um die örtliche Offensive des Scharlachroten Kreuzzugs zu brechen.",al={"warum melrache töten","zygands beweggrund"}},{q="Wie hängt dieser Kampf mit dem größeren Krieg gegen Arthas zusammen?",a="Exekutor Zygand sieht im Scharlachroten Kreuzzug eine gefährliche Ablenkung. Die Beseitigung seiner angriffslustigen Offiziere ermöglicht den Verlassenen, ihre Herrschaft über Tirisfal zu festigen und Kräfte für die Rache am Lich King zu sparen.",al={"verbindung zu arthas","warum arthas erwähnen"}},{q="Vertreibt Melraches Tod den Scharlachroten Kreuzzug aus Tirisfal?",a="Nein. Melraches Tod zerschlägt eine unmittelbar gefährliche Gruppe von Angreifern und mindert den Druck auf Brill, doch der Scharlachrote Kreuzzug hält weiterhin nahe Festungen, darunter das Scharlachrote Kloster im Osten.",al={"ist der scharlachrote kreuzzug besiegt","verlassen sie tirisfal"}},{q="Was ist Faols Ruheplatz?",a="Faols Ruheplatz ist eine abgelegene Begräbnisstätte im nördlichen Tirisfal. Melraches Turm steht in den zerklüfteten Hügeln dahinter.",al={"faols ruheplatz","faols ruhestätte"}}},fx={["515f522a"]={q="Warum schickt Exekutor Zygand einen Abenteurer anstelle seiner eigenen Wachen?",a="Die Garnison von Brill ist bereits durch die Bewachung der Stadt und die Aufrechterhaltung von Patrouillen gegen ständige Einfälle überlastet. Ein Schlag tief in die nördliche Wildnis hinter Faols Ruheplatz, um einen von Feinden gehaltenen, zerstörten Turm zu stürmen, erfordert chirurgische Präzision anstelle eines plumpen Truppeneinsatzes. Zygand verlässt sich auf fähige, unabhängige Champions, die ihre Rücksichtslosigkeit bereits bewiesen haben, um das feindliche Kommando im Stillen auszuschalten.",al={"warum schickt ihr mich","warum nicht wachen einsetzen","warum nicht die königliche schreckenswache"}}},fp="31,173,24.300.0,23.363.0,24.188.0,34.119.0,44.194.0,60.208.0,62.185.0,20.114.0"}
P.entries["quest:373"] = {n="Der nie verschickte Brief",s="Ein versiegelter Brief von Edwin van Cleef wartet auf Baros Alexston, Sturmwinds Stadtarchitekten. Seine Übergabe bringt ihre gemeinsame Vergangenheit ans Licht.",h="Ein versiegelter Brief von Edwin van Cleef wartet auf Baros Alexston, Sturmwinds Stadtarchitekten.",kw={"baros alexston","kathedralenplatz","rathaus","die todesminen","defias","edwin van cleef","steinmetze","nie verschickter brief"},ang={["class:Rogue"]="Als Schurke könnt Ihr erkennen, wie van Cleefs Geschick als Kämpfer und Organisator einer selbstmörderischen Besessenheit wich.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr erkennen, wie der Brief die Bedrohung durch die Defias mit Sturmwinds Stadtverwaltung verknüpft. Er offenbart einen Rachefeldzug, der über einen regionalen Aufstand von Gesetzlosen hinausgeht.",["race:Human"]="Als Mensch aus Sturmwind könnt Ihr die Wunden erkennen, die der Wiederaufbau des Königreichs hinterlassen hat. Politischer Verrat innerhalb der Hauptstadt ließ das Banditentum in Westfall entstehen."},sec={{t="Eine Botschaft aus dem Grab",b="Ein versiegelter Brief steckt in Edwin van Cleefs Kleidung an Bord seines Schlachtschiffs unter Mondbruch. Frisch verfasst, trägt er den Namen von Baros Alexston. Van Cleef wählte den Stadtarchitekten, keinen kriminellen Leutnant oder Finanzier."},{t="Architekten von einst",b="Bringt den Brief zum Rathaus auf dem Kathedralenplatz. Baros Alexston arbeitete beim Wiederaufbau Sturmwinds nach dem Zweiten Krieg an der Seite von Edwin van Cleef. Die Nachricht von van Cleefs Tod lässt ihn ungläubig zurück, und die wahllose Gewalt des Banditenanführers entsetzt ihn.\n\nAlexston versteht den Groll hinter van Cleefs erbittertem Kreuzzug. Van Cleef war ein kompromissloser Idealist, vom Verrat zerfressen. Sein Groll war berechtigt, doch er schlug in zerstörerischen Wahnsinn um."}},faq={{q="Wo finde ich den nie verschickten Brief?",a="Ihr findet den nie verschickten Brief bei Edwin van Cleef an Bord seines gepanzerten Schiffs in den Todesminen, tief in Westfall.",al={"nie verschickter brief beute","wie den nie verschickten brief erhalten","wer lässt den nie verschickten brief fallen"}},{q="Wer ist Baros Alexston?",a="Baros Alexston ist Sturmwinds Stadtarchitekt. Er lebt im Rathaus am nordöstlichen Rand des Kathedralenplatzes.",al={"baros alexston standort","wo ist baros alexston","stadtarchitekt sturmwind"}},{q="Warum schrieb Edwin van Cleef an den Stadtarchitekten?",a="Edwin van Cleef und Baros Alexston waren Steinmetzkollegen, die Sturmwind nach dem Zweiten Krieg wiederaufbauten. Selbst als Bandit sah van Cleef in Alexston einen früheren Weggefährten, verbunden mit der Arbeit der Steinmetze und dem Verrat an ihnen.",al={"warum an baros schreiben","beziehung zwischen van cleef und baros","brief an den architekten"}},{q="Was verrät der Brief über van Cleef?",a="Alexston sieht in van Cleef einen Idealisten und Romantiker bis zum Ende, vergiftet von Rachsucht. Van Cleef hielt seinen Krieg gegen das Königreich für gerechtfertigt, weil der herrschende Adel sich weigerte, die Steinmetze zu bezahlen.",al={"van cleefs beweggrund","was steht im brief","hintergrundgeschichte des briefs"}},{q="Muss ich die Hauptquestreihe der Bruderschaft der Defias abschließen, bevor ich den Brief abgebe?",a="Nein. Jeder Abenteurer der Allianz, der van Cleef besiegt, kann den Brief an sich nehmen, unabhängig vom bisherigen Fortschritt in der Geschichte der Bruderschaft der Defias.",al={"questvoraussetzung","nie verschickten brief früh erledigen","defias-questreihe nötig"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Nachdem Ihr den Brief überbracht habt, schickt Alexston Euch ins Verlies, um Bazil Thredd zu befragen, einen inhaftierten Defiasanführer, der mehr über van Cleefs Pläne wissen könnte.",al={"nächste quest nach dem nie verschickten brief","lescovar-questreihe","was folgt auf baros alexston"}}},fp="17,134,24.212.0,17.455.1,34.105.0,22.114.0,53.216.0,43.202.0,77.135.0,36.160.1"}
P.entries["quest:374"] = {n="Todesbeweis",s="In Brill schickt Todesbeweis Soldaten gegen den Scharlachroten Kreuzzug in ganz Tirisfal aus. Varimathras, Sylvanas Windläufers Schreckenslord und Leutnant, befiehlt den Feldzug, um ihre Reihen auszudünnen und die Treue zur Sache der Verlassenen zu prüfen. Rekruten müssen gefallenen Kreuzzüglern Siegelringe als Beweis abnehmen.",h="In Brill schickt Todesbeweis Soldaten gegen den Scharlachroten Kreuzzug in ganz Tirisfal aus.",kw={"brill","dunkle fürstin","todeswache burgess","exekutor zygand","todesbeweis","scharlachroter kreuzzug","scharlachroter insignienring","tirisfal","varimathras"},ang={["faction:Horde"]="Dieser Auftrag offenbart den Geist rücksichtsloser, totaler Kriegsführung, der Sylvanas' Herrschaft im Norden prägt und zum Teil vom Schreckenslord Varimathras gelenkt wird.",["race:Undead"]="Für die Verlassenen bedeutet jeder nach Brill gebrachte Kreuzzüglerring einen Fanatiker weniger, der geschworen hat, Lordaeron von Untoten mit freiem Willen zu säubern."},sec={{t="Ein Auftrag des Schreckenslords",b="Im gesamten nördlichen Tirisfal führen die Verlassenen einen koordinierten Krieg gegen die Lebenden. Varimathras kapitulierte und stellte seine Klinge in den Dienst von Sylvanas Windläufer. Er überwacht viele der offensiven Militärmanöver der Verlassenen.\n\nSeine Befehle gehen an Befehlshaber wie Exekutor Zygand und dann an Frontoffiziere wie Todeswache Burgess. Burgess spricht den Befehl klar aus: Menschen sind Ungeziefer, das aus Lordaeron getilgt werden muss, und die nahen Kreuzzügler sind das unmittelbare Ziel."},{t="Zeichen des Gemetzels",b="In Brill genügen den Befehlshabern Worte allein nicht. Soldaten müssen erschlagenen Eiferern Scharlachrote Siegelringe von den Fingern nehmen, um der Dunklen Fürstin und ihrem Leutnant Gehorsam zu beweisen. Die Ringe tragen das Zeichen des Scharlachroten Kreuzzugs und weisen ihre Träger als geschworene Feinde der Verlassenen aus.\n\nBringt diese Trophäen zurück, und der Tod der Kreuzzügler ist bewiesen. Die Ringe zeigen auch die Treue eines Soldaten zur Führung der Verlassenen."}},faq={{q="Wer erteilt den Auftrag, diese Ringe zu sammeln?",a="Todeswache Burgess, ein Wächter der Verlassenen in Brill, erteilt den Befehl. Er handelt auf Grundlage der Berichte von Exekutor Zygand und verfolgt die militärischen Ziele, die Varimathras vorgibt.",al={"wer vergibt todesbeweis","questgeber","todeswache burgess quest"}},{q="Warum verlangt Burgess ausgerechnet Scharlachrote Siegelringe?",a="Scharlachrote Siegelringe liefern einen handfesten Beweis dafür, dass ein Kreuzzügler erschlagen wurde. Die Eiferer tragen sie als persönliche Zeichen, wodurch sie eindeutige Trophäen sind, die die Treue eines Soldaten zur Führung der Verlassenen bestätigen.",al={"warum ringe","zweck der scharlachroten ringe","was sind siegelringe"}},{q="Wer ist Varimathras, und warum wird er erwähnt?",a="Varimathras ist ein Schreckenslord, der sich mit Königin Sylvanas Windläufer verbündete, nachdem sich die Verlassenen vom Lich King befreit hatten. Er ist nun ihr oberster Leutnant in Unterstadt und lenkt die militärische Strategie gegen die verbliebenen menschlichen Enklaven in Lordaeron, darunter den Scharlachroten Kreuzzug.",al={"wer ist varimathras","schreckenslord in unterstadt","warum varimathras"}},{q="Wo befinden sich die scharlachroten Kreuzzügler für diesen Auftrag?",a="Scharlachrote Eiferer halten mehrere bewaffnete Lager in ganz Tirisfal. Sie sammeln sich um Wachtürme, Garnisonen und Außenposten in den nördlichen und östlichen Wäldern.",al={"wo ist der scharlachrote kreuzzug","standorte scharlachroter kreuzzügler","kreuzzüglerlager in tirisfal"}},{q="Wie hängt das mit den Befehlen von Exekutor Zygand zusammen?",a="Exekutor Zygand überwacht von Brill aus den gesamten Feldzug gegen den Scharlachroten Kreuzzug. Er schickt Rekruten gegen die Truppen der Kreuzzügler im Feld, während Burgess persönliche Trophäen als Beweis des Gehorsams gegenüber Varimathras und der Dunklen Fürstin verlangt.",al={"verbindung zu exekutor zygand","verbindung zu im krieg mit dem scharlachroten kreuzzug"}},{q="Warum steht die Führung der Verlassenen dem Scharlachroten Kreuzzug so feindselig gegenüber?",a="Der Scharlachrote Kreuzzug erklärt alle Untoten zu Monstrositäten, die im heiligen Feuer brennen sollen, und unterscheidet nicht zwischen der willenlosen Geißel und den Verlassenen mit freiem Willen. Seine Mitglieder jagen die Verlassenen entlang ihrer Grenzen, weshalb Sylvanas und ihre Offiziere die Kreuzzügler als gefährliche Bedrohung ansehen, die vernichtet werden muss.",al={"warum den scharlachroten kreuzzug bekämpfen","verlassene gegen scharlachroten kreuzzug","warum hassen verlassene menschen"}}},fx={ad9b8a55={q="Warum möchte Todeswache Burgess, dass der Scharlachrote Kreuzzug getötet wird?",a="Todeswache Burgess dient Varimathras und der Dunklen Fürstin direkt an der Front von Brill. In Tirisfal stellt der Scharlachrote Kreuzzug eine unmittelbare, fanatische Bedrohung direkt vor den Toren der Unterstadt dar. Burgess will ihre Präsenz auslöschen, um das Gebiet zu sichern, und verlangt greifbare Beweise ihrer Niederlage, um Eure Loyalität gegenüber der Sache der Verlassenen zu messen.",al={"burgess beweggrund","warum scharlachroten kreuzzug töten burgess","warum todesbeweis"}},a6764d6a={q="Wer sind die Scharlachroten Kreuzzügler, die in dieser Mission das Ziel sind?",a="Ihr werdet gegen die eifrigen Mitglieder des Scharlachroten Kreuzzugs ausgesandt, die Lager in ganz Tirisfal besetzt halten. Diese fanatischen Menschen betrachten alle Untoten als Abscheulichkeiten, die vollständig ausgelöscht werden müssen, und führen aktiv einen Feldzug, um Lordaeron zurückzuerobern und die Verlassenen auszulöschen.",al={"wer ist das ziel scharlachroter kreuzzug","todesbeweis ziel","wen töte ich todesbeweis"}}},fp="15,293,28.457.0,19.421.0,44.154.0,60.204.0,43.278.0,54.155.0,50.238.0,65.300.0"}
P.entries["quest:3741"] = {n="Hilarys Halskette",s="An den Docks von Seenhain verliert Hilary die Halskette, die ihr Vater ihr geschenkt hat. Shawn bittet Euch, sie im Immerruhsee zu suchen, in dem ihre Eltern ihnen das Schwimmen verbieten.",h="An den Docks von Seenhain verliert Hilary die Halskette, die ihr Vater ihr geschenkt hat.",kw={"effsee","glitzernder schlamm","hilary","der immerruhsee","seenhain","halskette","nida","rotkammgebirge","shawn"},ang={["faction:Alliance"]="Als Reisender der Allianz helft Ihr den bedrängten Bürgern von Seenhain durch persönliche Nöte. Eure Fürsorge für die einfachen Stadtbewohner zählt ebenso wie die Verteidigung gegen größere Bedrohungen."},sec={{t="Ein Tag an den Docks",b="Hilary und Shawn angeln an den Docks von Seenhain und suchen einen gewöhnlichen Tag inmitten der Bedrohungen rund um das Rotkammgebirge. Dann gleitet Hilarys geliebte Halskette in den Immerruhsee. Sie suchen die Stege und das Ufer ab, finden aber nichts. Shawn bittet Euch um Hilfe."},{t="Gefahren des Immerruhsees",b="Ihre Eltern verbieten Hilary und Shawn, im Immerruhsee zu schwimmen. Unter der Oberfläche lauern aggressive Murlocs und hungrige Threshedons. Die Halskette liegt in glitzerndem Schlamm am Seegrund, außerhalb der Reichweite der Kinder. Deshalb bittet Shawn Euch, das Geschenk zu bergen."}},faq={{q="Wer hat die Halskette verloren?",a="Hilary, ein junges Mädchen in Seenhain, hat die Halskette verloren, die ihr Vater ihr geschenkt hat. Sein Geschenk bedeutet ihr sehr viel.",al={"wer ist nida","wer hat sie verloren","besitzer der halskette","wer ist hilary"}},{q="Warum können Shawn oder Hilary nicht selbst hinabtauchen und sie holen?",a="Ihre Eltern verbieten ihnen, im Immerruhsee zu schwimmen, wo aggressive Murlocs und räuberische Threshedons unter der Oberfläche lauern.",al={"warum nicht selbst holen","warum schwimmen die kinder nicht"}},{q="Wo ist die Halskette gelandet?",a="Die Halskette glitt von den Docks und sank in einen Haufen glitzernden Schlamms auf dem westlichen Grund des Immerruhsees.",al={"fundort der halskette","wo ist die halskette","wohin ist sie gefallen"}},{q="Wer ist Effsee?",a="Effsee ist Hilarys kleine Hauskatze in Seenhain. Sie leistet Hilary Gesellschaft und dankt mit ihr den Reisenden, die die Halskette bergen.",al={"effsee","nida katze","hilarys katze"}},{q="Wer bittet darum, die Halskette zu finden?",a="Shawn, Hilarys Freund, war mit ihr an den Docks angeln. Er bittet Euch um Hilfe, weil er weiß, wie viel ihr das Geschenk ihres Vaters bedeutet.",al={"wer gibt die quest","shawns rolle"}},{q="Warum ist diese Aufgabe für Seenhain wichtig?",a="Das Andenken wiederzufinden, bringt den Familien von Seenhain Trost und ein wenig Normalität, während sie unter ständiger Bedrohung um ein friedliches Leben ringen.",al={"bedeutung für seenhain","warum den kindern helfen"}}},fx={ce1ad253={q="Warum möchte Shawn, dass Ihr die Halskette findet?",a="Shawn versucht lediglich, auf seinen Freund aufzupassen. Die beiden verbrachten den ganzen Tag mit Angeln an den Docks, und Hilary war am Boden zerstört, als ihr wertvolles Schmuckstück verschwand. Als Shawn sah, wie sehr sie darunter litt, suchte er überall an Land, bis ihm klar wurde, dass es in den Immerruhsee gefallen sein musste.",al={"warum kümmert sich shawn","shawns grund für die halskette","warum hilary helfen"}},["186564aa"]={q="Was ist Hilarys Halskette?",a="Es ist ein geschätztes Andenken, das der junge Hilary von ihrem Vater geschenkt bekam. Für Abenteurer hat es kaum materiellen Wert, doch für ein verängstigtes Kind, dessen Familie unter den wachsenden Spannungen in Seenhain leidet, bedeutet es die ganze Welt.",al={"was ist die halskette","bedeutung von hilarys halskette","wer gab hilary die halskette"}}},fp="17,154,18.252.0,24.252.0,22.109.0,58.129.0,30.114.0,14.130.0,44.136.0,39.137.0"}
P.entries["quest:375"] = {n="Die Kälte des Todes",s="In Brill lastet die Kälte des Todes auf Gretchen Dedmar, während sie gegen die Kälte des Untodes kämpft. Die Schneiderin der Verlassenen fürchtet, ihren Verstand zu verlieren und Fürstin Sylvanas nicht mehr dienen zu können, und bittet deshalb um Materialien für eine warme Decke.",h="In Brill lastet die Kälte des Todes auf Gretchen Dedmar, während sie gegen die Kälte des Untodes kämpft.",kw={"brill","die kälte des todes","grober faden","dämmerfledermausfell","gretchen dedmar","geistlosenzustand","seuche des untodes","tirisfal"},ang={["profession:Tailoring"]="Als Schneider könnt Ihr sehen, wie sich Gretchens Näharbeiten verändert haben: von Leichensäcken für Sylvanas' Armee zu einer Decke aus Fellen.",["race:Undead"]="Als Verlassener erinnert Euch Gretchens Kampf daran, dass die Freiheit vom Lich King weder den körperlichen Verfall noch die drohende Geistlosigkeit aufhält."},sec={{t="Ein schleichender Frost",b="Gretchen Dedmar spürt die Seuche des Untodes wie eine eisige Schlange, die sich durch ihren Körper windet. Die Kälte raubt ihren Gliedmaßen die Wärme und droht, sie geistlos zurückzulassen, wie die umherirrenden Leichen in Tirisfal. Ihre zitternden Hände erschweren selbst gewöhnliche Arbeiten."},{t="Dienst an der Dark Lady",b="Gretchen will ihre Pflicht gegenüber dem Reich der Verlassenen nicht aufgeben. Als Sylvanas Windläufer die befreiten Toten erstmals um sich scharte, nähte Gretchen Leichentücher und Leichensäcke für gefallene Soldaten. Robuste Dämmerfledermausfelle und Grober Faden können ihr helfen, eine Decke anzufertigen. Deren Wärme könnte ihre Hände so weit beruhigen, dass sie der Sache der Verlassenen weiter dienen kann."}},faq={{q="Wer ist Gretchen Dedmar?",a="Gretchen Dedmar ist eine Schneiderin der Verlassenen, die in Brill lebt. Einst nähte sie Leichensäcke für die gefallenen Soldaten von Fürstin Sylvanas.",al={"gretchen dedmar","wer ist gretchen","brill schneiderin questgeberin"}},{q="Was ist der „Geistlosenzustand“, den Gretchen fürchtet?",a="Der Geistlosenzustand ist der geistige und körperliche Verfall, der manche Untote befällt, wenn ihr Wille und ihre nekrotischen Energien versagen. Sie werden zu wilden, schlurfenden Kreaturen wie jenen, die vor Brill und Todesend umherirren.",al={"was ist der geistlosenzustand","warum verliert gretchen ihren verstand","verlassene werden geistlos"}},{q="Warum friert Gretchen, wenn sie tot ist?",a="Gretchen spürt die Seuche in ihren Adern als eisige Kälte. Sie lässt ihre Gelenke erstarren und ihre Hände zittern, obwohl sie untot ist.",al={"können untote kälte spüren","warum sind untote kalt","die kälte des todes bedeutung"}},{q="Warum braucht sie Dämmerfledermausfelle und Faden?",a="Gretchen braucht fünf Dämmerfledermausfelle und Groben Faden, um eine dicke Decke zu nähen. Sie hofft, dass deren Wärme ihre Hände beruhigt, damit sie weiterarbeiten kann.",al={"warum dämmerfledermausfelle","wofür ist die decke"}},{q="Wo findet man Dämmerfledermäuse?",a="Dämmerfledermäuse haben ihre Schlafplätze in den Wäldern und offenen Lichtungen um Brill und im nördlichen Tirisfal.",al={"wo sind dämmerfledermäuse","dämmerfledermausfell fundort"}},{q="Hängt diese Quest mit anderen Aufgaben in Brill zusammen?",a="Gretchens Hilfsbedarf ist ihr eigenes Anliegen unter den Bewohnern von Brill. Er zeigt die stillen, persönlichen Kämpfe der erst kürzlich befreiten Verlassenen.",al={"die kälte des todes folgequest","gretchen dedmar questreihe"}}},fp="18,214,16.264.0,24.326.0,23.116.0,44.212.0,43.134.0,43.143.0,28.79.0,53.144.0"}
P.entries["quest:376"] = {n="Die Verdammten",s="Neue Verlassene in Todesend suchen bei Novize Elreth Kleidung und Schlachtfeldverbände. Sie tauscht geborgene Rüstung gegen die Materialien zu deren Herstellung.",h="Neue Verlassene in Todesend suchen bei Novize Elreth Kleidung und Schlachtfeldverbände.",kw={"todesend","nachtsaugerflügel","verlassene","novize elreth","aasfressertatze","schattenpriester sarvis","die verdammten","tirisfal"},ang={["profession:Tailoring"]="Als Schneider seht Ihr, wie sich Verlassene in Lordaeron mit Flughäuten und geborgenen Fellen behelfen, wo sauberes Tuch knapp ist.",["race:Undead"]="Als frisch erweckter Verlassener seht Ihr die harte Arbeit des Überlebens: Gefallene Vorgänger hinterlassen Ausrüstung, während das verseuchte Land liefert, was sonst noch benötigt wird."},sec={{t="Ein pragmatischer Handel",b="Novize Elreth versorgt die frisch erweckten Verlassenen in Todesend. Sie hilft Schattenpriester Sarvis, kümmert sich um geschundene Soldaten und flickt ihre Kleidung. Wenn die Vorräte knapp werden, schickt sie Euch in die umliegenden Lichtungen, um Dämmerfledermäuse und Aasfresserwölfe zu jagen. Ihre Felle, Flügel und Sehnen helfen bei der Versorgung des Lagers, und Elreth bietet dafür geborgene Rüstung an."},{t="Geerbter Schutz",b="Elreths Rüstung gehörte Verlassenen, die ihr Erwachen nicht überlebt haben. Sie hofft, dass sie Euch bessere Dienste leistet als ihrem früheren Besitzer. In Tirisfal findet jedes Stück Leder und jede verrostete Kette Verwendung."}},faq={{q="Wer ist Novize Elreth?",a="Novize Elreth ist eine Akolythin in der Kapelle von Todesend und eine Gehilfin von Schattenpriester Sarvis. Sie versorgt verwundete Verlassene, flickt Kleidung und rüstet Neuankömmlinge aus.",al={"novize elreth","wer vergibt die quest die verdammten","elreth"}},{q="Warum braucht Elreth Aasfresserpfoten und Dämmerfledermausflügel?",a="Elreth braucht Aasfresserpfoten und Dämmerfledermausflügel, um Material für Reparaturen und Verbände zu gewinnen. Da in Todesend kaum etwas übrig ist, greift sie auf die Tierwelt von Tirisfal zurück.",al={"warum fledermausflügel","warum aasfresserpfoten","elreth materialien"}},{q="Woher stammt die Rüstung als Belohnung?",a="Die Rüstung stammt von Verlassenen, die ihr Erwachen nicht überlebt haben. Elreth birgt brauchbare Ausrüstung, um Neuankömmlinge zu schützen.",al={"woher kommt die rüstung","elreth rüstung herkunft"}},{q="Wo sind die Kreaturen zu finden?",a="Young Scavengers und Dämmerfledermäuse leben gleich südlich von Todesend. Stärkere Exemplare streifen im Osten in Richtung des Außenpostens des Scharlachroten Kreuzzugs umher.",al={"wo aasfresser finden","wo sind dämmerfledermäuse","fundorte der dämmerfledermäuse"}},{q="Wie trägt diese Aufgabe zur Verteidigung von Todesend bei?",a="Elreth hilft dabei, frisch erweckte Verlassene auf die nahen Bedrohungen vorzubereiten, darunter hirnlose Untote und der Scharlachrote Kreuzzug. Schattenpriester Sarvis erwartet, dass sie für Gefahren gerüstet sind.",al={"warum diese quest erledigen","verteidigung von todesend"}},{q="Was folgt, nachdem Ihr Novize Elreth geholfen habt?",a="Nachdem Ihr Elreth geholfen habt, könnt Ihr weitere Aufgaben rund um Todesend übernehmen: Marlas letzten Wunsch erfüllen, die Spinnen im Nachtwebergrund bekämpfen und überall in der Siedlung Vorräte bergen.",al={"nächste quests nach die verdammten","was kommt nach die verdammten"}}},fx={["9d3a6da0"]={q="Warum benötigt Novize Elreth Aasfresserpfoten und Dämmerfledermausflügel?",a="Novize Elreth ist damit betraut, Rüstungen und Kleidung für die Verteidiger von Todesend zu schneidern, neben der Versorgung der Verwundeten und der Unterstützung von Schattenpriester Sarvis. Natürliche Materialien wie das Leder und die Felle, die von Aasfresserpfoten und Dämmerfledermausflügeln geerntet werden, dienen als essenzieller Rohstoff. Ohne frische Vorräte kann Elreth die zerlumpten Kleidungsstücke, die von frisch auferstandenen Verlassenen getragen werden, die in die Schlacht ziehen, nicht ordnungsgemäß verstärken.",al={"wozu sind die aasfresserpfoten","verwendung von dämmerfledermausflügeln","warum pfoten und flügel"}},["1b3259f3"]={q="Warum bittet Novize Elreth Euch anstelle der Wachen von Todesend?",a="Novize Elreth trägt bereits eine erdrückende Last bei der Pflege der geschundenen Soldaten, der Versorgung mit Schneidereimaterialien und der Unterstützung von Schattenpriester Sarvis. Die etablierten Wachen von Todesend können ihre Posten nicht verlassen, während die Geißel und der Scharlachrote Kreuzzug vorrücken. Als frisch auferlegter Verlassener, der vor einem sofortigen Einsatz gegen The Mindless Ones steht, dient das Sammeln Eurer eigenen Schutzausrüstung sowohl den Bedürfnissen der Siedlung als auch Eurem eigenen Überleben.",al={"warum ich elreth","warum holt elreth die pfoten nicht selbst","warum keine wachen schicken"}}},fp="10,140,17.347.0,20.209.0,21.156.0,54.170.0,37.118.0,30.119.0,54.174.0,41.190.0"}
P.entries["quest:3765"] = {n="Verderbnis in der Fremde",s="In Sturmwind sucht Argos Nachtraunen Abenteurer, die seinem Bruder im nördlichen Kalimdor helfen. Gershala erforscht einen sich ausbreitenden Verfall an der Dunkelküste, wo er weitere Helfer braucht.",h="In Sturmwind sucht Argos Nachtraunen Abenteurer, die seinem Bruder im nördlichen Kalimdor helfen.",kw={"argos","auberdine","verderbnis","dunkelküste","gershala","nachtraunen","sturmwind"},ang={["faction:Alliance"]="Dieser Ruf zeigt die noch jungen Bande zwischen den Nachtelfen Kalimdors und dem Menschenkönigreich Sturmwind jenseits des Meeres.",["race:Human"]="Eure Reise zur Dunkelküste gewährt einen ersten Einblick in die uralte Kultur der Kaldorei, fernab von Elwynns steinernen Burgen.",["race:NightElf"]="Argos erinnert Euch an die Nöte der angestammten Wälder im nördlichen Kalimdor, während Ihr fern der Heimat seid."},sec={{t="Ein Gesandter in der Menschenhauptstadt",b="Sturmwind kämpft mit inneren Wirren und Unruhen in den umliegenden Regionen. Dennoch wandeln Gesandte aus den fernen Ländern der Kaldorei durch seine steinernen Straßen. Argos Nachtraunen sucht erfahrene Streiter, die bereit sind, über die Grenzen der Menschen hinauszublicken. Die Kaldorei sind noch recht neue Verbündete der Östlichen Königreiche, und offizielle militärische Hilfe ist rar. Daher werben Familien und Forscher unabhängige Streiter an, die dem Ruf folgen."},{t="Der Ruf der Dunkelküste",b="Argos weist Euch den Weg nach Auberdine, einem nebligen Hafen an der nebelverhangenen Küste der Dunkelküste. Sein Bruder Gershala erforscht ein unheilvolles Leiden, das die heimische Tier- und Pflanzenwelt befällt. Ihn zu erreichen bedeutet eine lange Überfahrt vom Hafen von Sturmwind über das große Meer. Es ist die erste wahre Reise eines Wanderers in Kalimdors uralte Wildnis."}},faq={{q="Wer ist Argos Nachtraunen?",a="Argos Nachtraunen ist ein Nachtelf, der sich als Besucher in Sturmwind aufhält. Als Gesandter seiner Familie wirbt er erfahrene Abenteurer der Allianz an, um das Meer zu überqueren und seinem Bruder Gershala an der Dunkelküste zu helfen.",al={"argos","argos nachtraunen","wer vergibt verderbnis in der fremde"}},{q="Wo befindet sich Gershala Nachtraunen?",a="Gershala Nachtraunen befindet sich in Auberdine, einer Küstensiedlung der Nachtelfen am westlichen Ufer der Dunkelküste im nördlichen Kalimdor.",al={"gershalas standort","wo ist gershala","verderbnis in der fremde abgeben"}},{q="Warum braucht Gershala Hilfe?",a="Gershala untersucht eine unnatürliche Verderbnis, die sich in der Wildnis der Dunkelküste ausbreitet. Sie befällt die heimische Tierwelt, Wasserquellen und Pflanzen, und er braucht erfahrene Streiter, um Proben zu sammeln und ihre Ursache zu untersuchen.",al={"warum gershala helfen","was stimmt an der dunkelküste nicht"}},{q="Wie komme ich von Sturmwind nach Auberdine?",a="Geht am südlichsten Anleger des Hafens von Sturmwind an Bord des Schiffes. Es fährt über das große Meer nach Auberdine an der Dunkelküste.",al={"wie auberdine erreichen","von sturmwind zur dunkelküste reisen"}},{q="Kann ich diese Quest annehmen, wenn ich schon an der Dunkelküste war?",a="Wenn Ihr Auberdine bereits besucht und Gershalas Quest „Researching the Corruption“ direkt bei ihm begonnen habt, könnt Ihr Argos' einleitenden Ruf nicht mehr annehmen oder abschließen.",al={"verderbnis in der fremde verpasst","ist verderbnis in der fremde noch möglich"}},{q="In welcher Beziehung stehen Argos und Gershala zueinander?",a="Argos und Gershala Nachtraunen sind Brüder. Gershala bleibt an vorderster Front und erforscht die Verderbnis an der Dunkelküste, während Argos das Meer überquert, um in Sturmwind fähige Verbündete zu suchen.",al={"argos und gershala","sind argos und gershala verwandt"}}},fx={c6dfa232={q="Warum benötigt Argos Nachtraunen Euch, damit Ihr geht, anstatt selbst zu gehen?",a="Argos hat die beschwerliche Reise über die Meere unternommen, speziell um fähige Verbündete aus den Östlichen Königreichen zu rekrutieren. Sein Bruder Gershala steht vor wachsenden Problemen in der Dunkelküste, die erfahrene Hände erfordern, und Argos bleibt in der geschäftigen Hauptstadt zurück, um weiterhin um Hilfe zu bitten und fähige Reisende zu finden, die bereit sind, die lange Reise zurück über den Ozean anzutreten.",al={"warum schickt ihr mich","warum kann argos nicht gehen","warum braucht argos einen abenteurer"}}},fp="21,168,29.404.0,21.328.0,26.199.0,39.125.0,28.225.0,41.118.0,51.179.0,52.180.0"}
P.entries["quest:377"] = {n="Verbrechen und Strafe",s="In Dunkelhain beginnt Verbrechen und Strafe mit einem Urteil, das die Hauptstadt aufgehoben hat. Ratsherr Mühlenstein sucht Dextren Ward, der im Verlies von Sturmwind einsitzt, nachdem das Haus der Adligen ihn vor Dunkelhains Todesurteil bewahrt hat. Ward war beim Grabraub für den Nekromanten Morbent Fel ertappt worden.",h="In Dunkelhain beginnt Verbrechen und Strafe mit einem Urteil, das die Hauptstadt aufgehoben hat.",kw={"dunkelhain","dextren ward","dämmerwald","grabräuber","haus der adligen","mühlenstein","morbent fel","verlies"},ang={["class:Rogue"]="Mühlensteins Forderung verlangt einen dreisten politischen Mord. Dafür muss man heimlich in das Hochsicherheitsgefängnis der Krone eindringen, um einen königlichen Erlass zu umgehen.",["faction:Alliance"]="Dieser Auftrag offenbart schwere Spannungen im Kernland der Allianz. Dunkelhains bedrängtes Grenzland steht den fernen, arroganten Bürokraten des Hauses der Adligen gegenüber.",["race:Human"]="Als Mensch aus den südlichen Königreichen müsst Ihr Eure Treue zur fernen Krone in Sturmwind gegen die verzweifelten Siedler abwägen, die im Dämmerwald die Stellung halten."},sec={{t="Verweigerte Gerechtigkeit im Dämmerwald",b="Der Dämmerwald leidet bereits unter schleichendem Grauen und der Gleichgültigkeit der Hauptstadt. Dextren Ward wurde dabei ertappt, wie er frische Leichen auf dem Friedhof von Dunkelhain ausgrub. Er verkaufte sie an Morbent Fel, einen Nekromanten.\n\nLord Ello Schwarzhaupt verurteilte Ward zur Enthauptung. Bevor das Beil fallen konnte, beanspruchte das Haus der Adligen ihn als kaiserlichen Gefangenen. Es ließ ihn in die Hochsicherheitszellen des Verlieses von Sturmwind überstellen."},{t="Eine Beleidigung der Toten",b="Für Ratsherr Mühlenstein und Dunkelhains trauernde Bürger war Wards Verschonung eine unerträgliche Beleidigung. Die Adligen in ihrer sicheren Stadt missachteten die Familien im Grenzland völlig, deren tote Angehörige Fels dunklem Handwerk zugeführt worden waren.\n\nFrustriert über Sturmwinds Einmischung heuert Mühlenstein wagemutige Söldner an, um das von Aufständen erschütterte Verlies zu infiltrieren. Sie sollen Ward in seiner Zelle ermorden und seine Hand als Beweis für die Hinrichtung abtrennen."},{t="Eine Botschaft an die Krone",b="Dextren Wards Tötung verschafft den Geschädigten Genugtuung und ist zugleich ein politischer Akt. Indem der Rat von Dunkelhain die Ermordung eines wichtigen Gefangenen hinter Schloss und Riegel der Krone anordnet, sendet er eine trotzige Botschaft nach Sturmwind. Wenn der Adel sich weigert, den Dämmerwald zu verteidigen oder seine örtlichen Gesetze zu achten, wird die Stadt ihre eigene Grenzlandjustiz unter der Nase des Regenten durchsetzen."}},faq={{q="Warum will Ratsherr Mühlenstein Dextren Ward tot sehen?",a="Ward wurde dabei ertappt, wie er Dunkelhains Friedhof plünderte und frisch begrabene Leichen an den Nekromanten Morbent Fel verkaufte. Lord Ello Schwarzhaupt verurteilte ihn zur Enthauptung, doch das Haus der Adligen brachte ihn stattdessen ins Verlies.",al={"warum dextren ward töten","was hat dextren ward getan","mühlensteins beweggründe"}},{q="Wo befindet sich Dextren Ward?",a="Dextren Ward wird tief im Inneren des Dungeons Sturmwind Stockade in Sturmwind gefangen gehalten. Seine Zelle liegt im äußersten linken Korridor des Gefängniskomplexes.",al={"dextren wards aufenthaltsort","wo ist ward","wie dextren ward finden"}},{q="Warum hat Sturmwind Dextren Ward nicht einfach hingerichtet?",a="Das Haus der Adligen beanspruchte aus nicht näher genannten Gründen die Gerichtsbarkeit über Ward. Es hob Dunkelhains Urteil auf und erzürnte die Bewohner des Dämmerwalds, die sich von der Hauptstadt im Stich gelassen fühlen.",al={"warum wurde ward eingesperrt","warum verlies statt hinrichtung"}},{q="Warum verlangt Mühlenstein Wards Hand?",a="Ratsherr Mühlenstein verlangt Wards Hand als greifbaren Beweis dafür, dass das Urteil entgegen dem Willen des Hauses der Adligen vollstreckt wurde. Sie verschafft auch den geschädigten Familien des Dämmerwalds Genugtuung.",al={"hand von dextren ward","warum hand als beweis"}},{q="Wer ist Morbent Fel?",a="Morbent Fel ist ein mächtiger Nekromant, der den Dämmerwald heimsucht. Er erweckt die Toten und verwendet Leichen, die ihm Leute wie Dextren Ward liefern, für dunkle Rituale.",al={"wer ist fel","morbent fels geschichte"}},{q="Was verrät diese Quest über das Verhältnis zwischen dem Dämmerwald und Sturmwind?",a="Sie offenbart tiefe politische Verbitterung. Der Dämmerwald fühlt sich vom Thron vernachlässigt und schutzlos gelassen, und die Bereitschaft des Rates, Attentäter ins Gefängnis der Hauptstadt zu schicken, zeigt, wie angespannt diese Treue inzwischen ist.",al={"dunkelhain und sturmwind politik","verbitterung im dämmerwald"}}},fx={["9b93eafe"]={q="Wer ist Dextren Ward und warum ist er im Verlies?",a="Dextren Ward ist ein Grabräuber, der Leichen vom Friedhof im Dämmerwald ausgegraben und an den Nekromanten Morbent Fel verkauft hat. Obwohl Lord Schwarzhaupt ihn wegen der Schändung der Toten zum Tode verurteilte, intervenierte das Haus der Adligen und brachte ihn stattdessen nach Sturmwind, wo sie ihn im Verlies einsperrten.",al={"wer ist dextren ward","warum ist dextren ward im gefängnis","dextren ward verbrechen"}},["444df616"]={q="Warum benötigt Millstipe Euch, um Ward zu töten, anstatt die lokalen Behörden zu nutzen?",a="Ward ist tief im Gefängnis der Hauptstadt unter der offiziellen Gerichtsbarkeit von Sturmwind eingesperrt. Die Nachtwache von Dunkelhain ist vollauf damit beschäftigt, die Stadt vor eindringenden Schrecken zu verteidigen, und lokale Beamte können nicht offen Truppen schicken, um ein königliches Verlies zu stürmen, ohne Verrat zu begehen. Sie benötigen einen unabhängigen Agenten, um ihre Art von Gerechtigkeit im Stillen zu vollstrecken.",al={"warum können dunkelhain wachen ward nicht töten","warum einen abenteurer anheuern um ward zu ermorden","warum braucht dunkelhain mich"}}},fp="20,297,26.410.0,21.429.0,22.368.1,53.217.0,30.137.0,47.182.0,38.186.0,19.147.0,73.211.0"}
P.entries["quest:378"] = {n="Tief empfundener Zorn",s="Motley Garmason sinnt auf Rache an Kam Tiefenzorn, der in Sturmwinds Verlies gefangen sitzt. Tiefenzorn plante den Angriff auf den Thandol-Übergang, bei dem Verteidiger der Bronzebärte starben, darunter der Bruder von Langzopf dem Grimmigen. Sturmwind hält Tiefenzorn als politischen Gefangenen fest, deshalb bittet Motley einen Abenteurer, zwergische Gerechtigkeit walten zu lassen.",h="Motley Garmason sinnt auf Rache an Kam Tiefenzorn, der in Sturmwinds Verlies gefangen sitzt.",kw={"krieg der dunkeleisenzwerge","tiefenzorn","dun modr","langzopf","motley garmason","roggo","verlies","thandol-übergang"},ang={["faction:Alliance"]="Als Mitglied der Allianz erlebt Ihr die Spannungen zwischen Sturmwinds pragmatischer Rechtsprechung und Eisenschmiedes Forderung nach unmittelbarer Rache in Kriegszeiten.",["race:Dwarf"]="Für die Zwerge der Bronzebärte begleicht Tiefenzorns Tod eine Blutschuld und ehrt die Clangefährten, die bei der Verteidigung des Thandol-Übergangs starben.",["race:Human"]="Als Mensch seid Ihr mit den diplomatischen Entscheidungen Eures Königreichs konfrontiert, wenn Ihr Sturmwinds Gefängnisregeln übergeht, um dem Gerechtigkeitsverständnis Eurer zwergischen Verbündeten zu entsprechen."},sec={{t="Ein Groll über Kontinente",b="Die nördlichen Gebiete des Sumpflands werden weiterhin von Kämpfen zwischen den Verteidigern der Bronzebärte bei Dun Modr und aufständischen Dunkeleisenzwergen erschüttert. Als der Thandol-Übergang angegriffen wurde, tötete Sabotage mehrere Zwerge, darunter den Bruder von Langzopf dem Grimmigen. Roggo beschaffte Informationen, die belegten, dass Kam Tiefenzorn den Angriff geplant hatte. Statt an der Front hingerichtet zu werden, wurde Tiefenzorn als politischer Gefangener in Sturmwinds Verlies gebracht und nicht wegen Mordes hingerichtet."},{t="Zwergische Vergeltung gegen Menschenrecht",b="Motley Garmason ist in Dun Modr stationiert und will nicht zulassen, dass Sturmwinds politisches Kalkül einen Kriegsverbrecher schützt. Für ihn stellt das Recht der Menschen den Anstand über Blutschulden. Da Motley an Langzopfs Seite im Sumpfland bleiben muss, schickt er vertrauenswürdige Recken in das von Aufständen erschütterte Verlies unter der Menschenhauptstadt. Sie sollen Tiefenzorns Kopf holen und die offene Rechnung des Clans begleichen."}},faq={{q="Wer ist Kam Tiefenzorn?",a="Kam Tiefenzorn ist ein Dunkeleisenzwerg, der den Angriff auf den Thandol-Übergang plante. Sein Plan tötete Zwerge aus Eisenschmiede, die den Übergang bewachten, und die Überlebenden in Dun Modr haben ihn als Ziel auserkoren.",al={"tiefenzorn","kam tiefenzorn hintergrund","wer ist tiefenzorn"}},{q="Warum ist Kam Tiefenzorn in Sturmwind statt in Eisenschmiede eingesperrt?",a="Sturmwinds Behörden nahmen Kam Tiefenzorn gefangen und halten ihn aus politischen Gründen, die sie nicht offengelegt haben, im Verlies fest. Die Zwerge von Dun Modr sehen darin Bürokratie, die ihnen sofortige Gerechtigkeit verwehrt.",al={"warum ist tiefenzorn im verlies","warum gefangener im verlies"}},{q="Warum jagt Motley Garmason Tiefenzorn nicht selbst?",a="Motley Garmason ist an der Seite von Langzopf dem Grimmigen in Dun Modr stationiert, wo sie anhaltenden Vorstößen der Dunkeleisenzwerge im nördlichen Sumpfland gegenüberstehen. Seine Ehre und seine militärische Pflicht hindern ihn daran, die Verteidigungslinie zu verlassen und nach Sturmwind zu gehen.",al={"warum bleibt motley","warum geht motley nicht"}},{q="Was geschah am Thandol-Übergang?",a="Der Dunkeleisenclan griff die Brücke am Thandol-Übergang an, die das Sumpfland mit dem Arathihochland verbindet. Bei dem Angriff starben mehrere Verteidiger der Bronzebärte, darunter Langzopfs Bruder.",al={"angriff auf den thandol-übergang","was geschah am thandol-übergang"}},{q="Wer deckte Tiefenzorns Rolle beim Angriff auf den Thandol-Übergang auf?",a="Ein Zwerg namens Roggo beschaffte Informationen, die Kam Tiefenzorn mit der Planung und Durchführung des Angriffs auf den Thandol-Übergang in Verbindung brachten. Roggo gab Motley die Beweise, die er brauchte, um Vergeltung zu fordern.",al={"wer fand tiefenzorn","roggos informationen"}},{q="Weiß Sturmwinds Führung von dem Mordanschlag in ihrem Gefängnis?",a="Motleys Auftrag ist eine nicht genehmigte zwergische Blutfehde. Er umgeht das Recht der Menschen, weil er glaubt, König Magnis Soldaten hätten das Recht, den Saboteur während der Aufstände im Verlies hinzurichten.",al={"weiß sturmwind vom mordanschlag","ist tiefenzorns tötung genehmigt"}}},fx={["323f2e11"]={q="Warum möchte Motley Garmason, dass Kam Tiefenzorn getötet wird?",a="Motley Garmason sucht Vergeltung für den Angriff der Dunkeleisenzwerge auf The Thandol Span, der das Leben von König Magnis Untertanen und des Bruders von Kommandant Longbraid forderte. Obwohl Kam Tiefenzorn gefangen genommen und im Verlies inhaftiert wurde, weigert sich Motley, zuzulassen, dass menschliche Diplomatie und Bürokratie den Verschwörer vor der zwergischen Gerechtigkeit schützen. Er möchte, dass Tiefenzorn hingerichtet wird, damit die Gefallenen endlich gerächt werden und ihre Angehörigen ihren Frieden finden können.",al={"warum tiefenzorn töten","motley garmason beweggrund","warum will motley tiefenzorn tot sehen"}},e14999ea={q="Wozu ist Tiefenzorns Kopf gut?",a="Motley Garmason verlangt den abgetrennten Kopf von Kam Tiefenzorn als unwiderlegbaren Beweis dafür, dass der verräterische Verschwörer der Dunkeleisenzwerge sein Ende gefunden hat. Da er weiß, dass die Wachen von Sturmwind nur beabsichtigen, Tiefenzorn als politisches Druckmittel festzuhalten, wird Motley nicht ruhen, bis er physische Beweise dafür sieht, dass die Gerechtigkeit für Longbraids Familie und die Verteidiger von Dun Modr vollzogen wurde.",al={"warum tiefenzorns kopf mitnehmen","verwendung von tiefenzorns kopf","wozu wird tiefenzorns kopf gebraucht"}}},fp="18,316,26.450.0,33.366.0,20.182.0,65.203.0,55.220.0,34.193.0,57.182.0,73.185.0"}
P.entries["quest:379"] = {n="Durstlöscher",s="In Gadgetzan braucht Chefingenieur Bilgewhizzle fünf Wastewander Water Pouches, bevor er die 4711-FTZ-Energiequelle für Euer Set liefern kann. Die Wastewander-Nomaden östlich der Stadt tragen sie bei sich.",h="In Gadgetzan braucht Chefingenieur Bilgewhizzle fünf Wastewander Water Pouches, bevor er die...",kw={"4711-ftz","bilgewhizzle","gadgetzan","energiequelle","tanaris","wastewander","wasserbeutel"},sec={{t="Ein Getränk für eine Energiequelle",b="Chefingenieur Bilgewhizzle in Gadgetzan kann Euch nach Into the Field mit der Energiequelle helfen, die Euer Set benötigt. Zuerst bittet er Euch um fünf Wastewander Water Pouches. Die Wastewander-Nomaden leben östlich von Gadgetzan, und Bilgewhizzle schlägt vor, zu einem hinzugehen und ihn um Wasser zu bitten. Er möchte hören, wie es ausgeht."},{t="Begrenzte Energie",b="Die 4711-FTZ-Energiequelle wurde nicht für ein Wissenschaftsset hergestellt. Sobald Ihr die Beutel übergebt, könnt Ihr sie verwenden, doch Eure gesammelten Daten bleiben höchstens zwei Stunden erhalten. Bringt die Quelle zu Bilgewhizzle zurück, wenn Ihr habt, was Ihr braucht, damit er sie ordnungsgemäß abschalten kann. Wenn die Zeit abläuft, könnt Ihr eine weitere Quelle bekommen, müsst sie aber kaufen."}},faq={{q="Wer bittet um die Wasserbeutel?",a="Chefingenieur Bilgewhizzle in Gadgetzan bittet um fünf Wastewander Water Pouches im Tausch gegen die 4711-FTZ-Energiequelle.",al={"wer vergibt durstlöscher","bilgewhizzle quest","gadgetzan ingenieur wasser"}},{q="Wo findet Ihr die Wastewander Water Pouches?",a="Ihr könnt Wastewander Water Pouches von den Wastewander-Nomaden östlich von Gadgetzan bekommen.",al={"wo sind wastewander water pouches","nomaden wasser tanaris","wastewander beutel fundort"}},{q="Welche Energiequelle bietet Chefingenieur Bilgewhizzle an?",a="Bilgewhizzle bietet die 4711-FTZ-Energiequelle für Euer Set an.",al={"welchen gegenstand gibt bilgewhizzle","4711 ftz energiequelle","name der energiequelle"}},{q="Was kam vor diesem Schritt?",a="Into the Field kommt vor diesem Schritt.",al={"durstlöscher voraussetzung","vorherige quest für durstlöscher","into the field verbindung"}}},fp="17,187,26.301.0,20.328.1,31.121.0,48.84.0,57.59.0,27.38.0"}
P.entries["quest:38"] = {n="Westfalleintopf",s="Auf ihrem Hof in Westfall kocht Salma Saldean Westfalleintopf aus dem, was das Grenzland bietet. Seine Zutaten spiegeln wider, wie die Siedler Banditen, Hungersnöten und gefährlichen Bestien trotzen.",h="Auf ihrem Hof in Westfall kocht Salma Saldean Westfalleintopf aus dem, was das Grenzland bietet.",kw={"goretuskschnauze","murlocauge","okraschote","saldean farm","salma saldean","geierfleisch","westfall","westfalleintopf"},ang={["faction:Alliance"]="Sturmwinds Hof genießt edlen Wein und erlesen zubereitetes Geflügel, während Außenposten der Allianz im Grenzland auf einfache Gerichte wie dieses angewiesen sind, um die Verteidigung gegen örtliche Bedrohungen aufrechtzuerhalten.",["profession:Cooking"]="Salmas Rezept zeigt, wie Köche im Grenzland aus zähem Wild, streng riechenden Schnauzen und ungewöhnlichen Funden vom Ufer eine stärkende Mahlzeit bereiten.",["race:Human"]="Für Menschen jenseits von Elwynns schützenden Mauern erzählt Westfalleintopf von der Zähigkeit und Ausdauer, die das Leben in der vergessenen Kornkammer des Königreichs erfordert."},sec={{t="Was Siedler zum Leben brauchen",b="Westfalls Siedler kämpfen mit Banditen, Hungersnöten und wütenden Bestien, weit entfernt von Sturmwinds üppigen Vorratskammern. Familien wie die Saldeans kommen mit dem aus, was das Land hergibt. Salma Saldean verwandelt Zutaten, die viele Stadtbewohner wohl als Ungeziefer oder Reste bezeichnen würden, in eine Mahlzeit, die ihre Landarbeiter kräftigt."},{t="Die Zutaten des Überlebens",b="Salmas Rezept vereint heimische Okraschoten, faseriges Fleisch von kreisenden Geiern und Schnauzen wilder Goretusks, die durch die Ebenen streifen. Dazu gehören auch frische Murlocaugen, die von Plünderern an der Küste stammen. Solche Kost mag empfindlichen Mägen in Elwynn zusetzen, doch Westfalls Köche schwören, dass diese Mischung eine gehaltvolle, stärkende Mahlzeit ergibt."}},faq={{q="Warum enthält das Rezept Murlocaugen?",a="Westfalls Bauern leiden unter Versorgungsengpässen und häufigen Murlocüberfällen entlang der Küste und an den Flussufern. Salma Saldean gibt frische Murlocaugen für Flüssigkeit und Geschmack in die Brühe und macht so aus einer Bedrohung Nahrung.",al={"murlocaugen im essen","warum murlocs essen","murloceintopf"}},{q="Wer ist Salma Saldean?",a="Salma Saldean ist eine Siedlerin der Allianz, die mit ihrem Mann, Bauer Saldean, auf der Saldean Farm im Norden Westfalls lebt. Sie versorgt Reisende und Landarbeiter mit Essen, obwohl Banditentum und Chaos die Region bedrängen.",al={"salma","salma saldean hintergrund","wer kocht westfalleintopf"}},{q="Woher stammen die Okraschoten?",a="Die Okraschoten stammen aus den wenigen widerstandsfähigen Gemüsekulturen, die auf Westfalls notleidenden Höfen noch geerntet werden. Beim Kochen geben die Schoten Säfte ab, die den Brühen des Grenzlands Bindung verleihen.",al={"wo okra finden","saldean okra","okra herkunft"}},{q="Gilt Westfalleintopf als gutes Essen?",a="Sturmwinds Adlige mögen gekochte Goretuskschnauzen und Murlocaugen abscheulich finden. Für Westfalls arme Bauern und müde Wanderer ist der Eintopf eine warme, sättigende Wohltat.",al={"schmeckt westfalleintopf gut","ist westfalleintopf eklig"}},{q="Warum brauchen die Saldeans Abenteurer, um die Zutaten zu sammeln?",a="Westfall ist gefährlich, denn wilde Goretusks, angriffslustige Geier und feindselige Murlocs streifen über seine Felder und Strände. Die Nahrungssuche bringt gewöhnliche Bauern in Gefahr, während sie zurückbleiben, um ihre Höfe zu verteidigen.",al={"warum zutaten sammeln","warum salma hilfe braucht"}},{q="Welches Tier liefert das Fleisch für den Eintopf?",a="Der Eintopf enthält faseriges Geierfleisch von Aasvögeln, die über Westfall kreisen, sowie Schnauzen wilder Goretusks, die in den Ebenen gejagt werden.",al={"welches fleisch ist im westfalleintopf","westfalleintopf fleisch"}}},fx={["43c10890"]={q="Warum möchte Bauer Saldean, dass dies erledigt wird?",a="Salma Saldean versucht, ihre Familie und ihren Haushalt trotz der harten Zeiten in ganz Westfall zu ernähren. Zwischen grassierendem Banditentum und unbestelltem Land sind tägliche Vorräte schwer zu bekommen. Die Zubereitung einer großen, herzhaften Portion Westfall-Eintopf streckt alle lokalen Zutaten, die man zusammenkratzen kann, zu einer nahrhaften Mahlzeit für die Farm.",al={"warum westfall-eintopf zubereiten","motiv von salma saldean","warum braucht salma eintopf"}},acee3b52={q="Wozu ist das zähe Geierfleisch gut?",a="Das zähe Geierfleisch dient als eine der Hauptproteinquellen für den Eintopf. Obwohl es für sich genommen zäh und mager ist, macht langsames Kochen in der Brühe das Fleisch zart, was es Salma ermöglicht, die Aasfresser, die über den Ebenen kreisen, gut zu nutzen.",al={"verwendung von geierfleisch","warum zähes geierfleisch","wozu ist geierfleisch gut"}},["939a3557"]={q="Wozu ist die Goretusk-Schnauze gut?",a="Goretusk-Schnauzen verleihen dem Kessel einen reichen, fettigen Geschmack und Textur. Salma betrachtet sie als einen köstlichen Grundbestandteil des Gerichts, der der herzhaften Brühe Substanz verleiht, die magereres Fleisch einfach nicht erreichen kann.",al={"verwendung von goretusk-schnauzen","warum goretusk-schnauzen","wozu sind schnauzen gut"}}},fp="13,176,25.279.0,27.311.0,36.191.0,21.217.0,30.154.0,38.164.0,63.206.0,43.140.0"}
P.entries["quest:380"] = {n="Nachtwebergrund",s="Nordwestlich von Todesend überrennen Spinnen eine Goldmine, die die Verlassenen brauchen. Exekutor Arren schickt frisch auferstandene Rekruten in die Höhle, um ihre Reihen zu lichten. Rohstoffe sind knapp, und der Reichtum der Mine könnte die Siedlung und die Kriegsanstrengungen der Verlassenen unterhalten.",h="Nordwestlich von Todesend überrennen Spinnen eine Goldmine, die die Verlassenen brauchen.",kw={"todesend","exekutor arren","verlassene","goldmine","spinne im nachtwebergrund","nachtwebergrund","tirisfal","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass gesicherte Rohstoffquellen in Tirisfal den Verlassenen helfen, sich als verlässliche Bastion im Norden zu etablieren.",["profession:Mining"]="Als Bergarbeiter wisst Ihr, dass dichte Netze und räuberische Spinnen die Erzsuche in dieser Höhle gefährlich machen, einer der wenigen Goldquellen nahe Todesend.",["race:Undead"]="Als Untoter steht Ihr im zurückeroberten Lordaeron einer harten Wirklichkeit gegenüber: Überleben bedeutet, alltägliche Bedürfnisse wie Metall und Münzen zu sichern, neben der Rache an den Lebenden und der Geißel."},sec={{t="Ein Volk braucht Gold",b="In Todesend beaufsichtigt Exekutor Arren die frisch auferstandenen Verlassenen bei ihrem Kampf ums Überleben. Die Geißel und die Kreuzfahrer des Scharlachroten Kreuzzugs bedrohen sie, doch die Verteidigung ist nur ein Teil der Arbeit. Eine junge Gesellschaft braucht auch Rohstoffe. Edelmetalle wie Gold waren im nördlichen Lordaeron selbst dann knapp, als die Allianz noch stark war. Arren weiß, dass die Verlassenen Reichtum brauchen, um sich zu bewaffnen, auszurüsten und ihre Gesellschaft aufzubauen."},{t="Die verseuchte Mine",b="Nordwestlich des Friedhofs von Todesend verläuft eine Goldader durch die natürliche Höhle namens Nachtwebergrund. Monströse Spinnen haben ihre Tunnel überrannt und die Tiefen mit dichten Netzen und tödlichem Gift gefüllt. Arren hat zu wenige erfahrene Truppen für eine vollständige Säuberung, also dezimieren frische Rekruten die jungen und ausgewachsenen Spinnen. Sobald die Gefahr eingedämmt ist, können Bergarbeiter die Netze wegbrennen und das Erz abbauen."}},faq={{q="Warum brauchen die Untoten eine Goldmine?",a="Die Verlassenen brauchen Gold, um ihre Kriegsanstrengungen zu finanzieren, Vorräte zu kaufen und Siedlungen in ganz Tirisfal wiederaufzubauen. Lordaeron mangelte es schon immer an natürlichen Ressourcen, und ein neues Reich, unabhängig von Allianz und Geißel, braucht wertvolle Währung für Handel und Ausrüstung.",al={"warum brauchen verlassene gold","warum gold in todesend","goldmine der untoten"}},{q="Wer ist Exekutor Arren?",a="Exekutor Arren ist der ranghöchste militärische Befehlshaber in Todesend. Er organisiert die frisch auferstandenen Untoten und sichert die unmittelbare Umgebung, indem er Rekruten anweist, Überreste der Geißel zu jagen, Vorräte zu sammeln und örtliche Rohstoffquellen zu erschließen.",al={"geschichte von exekutor arren","wer vergibt nachtwebergrund","arrens rolle"}},{q="Wo liegt der Nachtwebergrund?",a="Nordwestlich der Hauptsiedlung und des Friedhofs von Todesend liegt der Nachtwebergrund zwischen felsigen Anhöhen in einem abgeschiedenen Tal in Tirisfal.",al={"wo liegt der nachtwebergrund","spinnenhöhle todesend","standort der mine im nachtwebergrund"}},{q="Können die Verlassenen unmittelbar nach diesem Auftrag Gold abbauen?",a="Nicht sofort. Arren sagt, dass die Ausrottung der Spinnen wochen- oder monatelange unablässige Anstrengungen erfordern wird. Dann müssen Arbeiter die allgegenwärtigen Netze mit Fackeln wegbrennen, bevor Bergleute die Adern gefahrlos abbauen können.",al={"ist die mine gesäubert","bekommen sie das gold","was geschieht mit den spinnen"}},{q="Warum schickt Arren keine ganze Abteilung Soldaten, um die Höhle zu säubern?",a="Todesends Garnison ist ausgelastet: Sie wehrt hirnlose Angehörige der Geißel ab, die am Ortsrand umherstreifen, und hält nach Spähern des Scharlachroten Kreuzzugs Ausschau. Arren hat nicht genug freie Kräfte, um einen regulären Trupp gegen die Spinnen einzusetzen, also säubern frisch auferstandene Rekruten die Mine Stück für Stück.",al={"warum rekruten schicken","warum keine wachen aus todesend einsetzen","arrens mangel an truppen"}},{q="Kann Spinnengift den Untoten schaden?",a="Ätzendes Spinnengift kann konserviertes Fleisch verätzen und wiederbelebte Gliedmaßen schwächen, obwohl die Verlassenen nicht wie die Lebenden bluten oder atmen. Arren warnt Rekruten, auf ein stechendes Brennen zu achten und sich behandeln zu lassen, wenn sie betroffen sind.",al={"schadet gift den untoten","verlassene spinnengift","sind verlassene immun gegen gift"}}},fx={["9452aa4f"]={q="Warum will Exekutor Arren, dass der Nachtwebergrund gesäubert wird?",a="Todesend und die aufstrebenden Kriegsanstrengungen der Verlassenen benötigen dringend natürliche Ressourcen, um zu überleben und ihre Ländereien zu befestigen. Gold war in Tirisfal selbst auf dem Höhepunkt der Herrschaft der alten Allianz knapp, was die lokale Mine in der Höhle zu einem unverzichtbaren Gut macht. Die darin nistenden Spinnen machen den Abbau jedoch unmöglich. Arren will die Plage ausgemerzt sehen, damit die Verlassenen das Edelmetall schließlich sichern und abbauen können.",al={"warum will arren dies erledigen","warum nachtwebergrund säubern","motiv von exekutor arren"}},a97ddab4={q="Welche Nachtweberspinnen befallen die Mine?",a="Das Ziel Eurer Mission ist die Brut der Nachtweberspinnen und ihre Jungen, die die alte Goldmine überrannt haben. Im Zuge des Falls von Lordaeron und der Plage breitete sich räuberische Tierwelt aggressiv in verlassenen sterblichen Siedlungen und unterirdischen Höhlen aus. Die Spinnen haben sich aggressiv in den Minentunneln eingenistet, Netze gesponnen und alle Bergleute vertrieben, die versuchten, die Ader anzuzapfen.",al={"was sind nachtweberspinnen","gegen wen werden wir geschickt","warum sind spinnen im nachtwebergrund"}}},fp="18,252,24.416.0,17.389.0,35.278.0,22.219.0,36.140.0,68.200.0,71.258.0,33.233.0"}
P.entries["quest:381"] = {n="Der Scharlachrote Kreuzzug",s="In Tirisfal bedroht ein Lager des Scharlachroten Kreuzzugs Todesend von Südosten her. Exekutor Arren schickt die neu erwachten Verlassenen gegen dessen Fanatiker, die zu ihren fanatischsten und hartnäckigsten Feinden zählen.",h="In Tirisfal bedroht ein Lager des Scharlachroten Kreuzzugs Todesend von Südosten her.",kw={"todesend","exekutor arren","scharlachrote armbinden","scharlachrote konvertiten","scharlachroter kreuzzug","scharlachrote novizen","tirisfal"},ang={["class:Priest"]="Als Priester der Verlassenen erlebt Ihr, wie das Heilige Licht, das Ihr einst in Lordaeron verehrt habt, zu fanatischem Hass verdreht wurde.",["faction:Horde"]="Die unerbittliche Aggression des Scharlachroten Kreuzzugs erklärt mit, warum die Verlassenen in der Horde gegenseitige Verteidigung und Schutz suchten.",["race:Undead"]="Als neu auferstandener Verlassener lernt Ihr früh, dass die Lebenden Euch ungeachtet Eures freien Willens als ein Monster sehen, das ausgerottet werden muss."},sec={{t="Eine fanatische Bedrohung",b="Nachdem die Nachtweber erledigt sind, wendet sich Exekutor Arren einer Gefahr zu, die Todesend näher rückt. Eine Abteilung des Scharlachroten Kreuzzugs hat sich unmittelbar südöstlich der Siedlung festgesetzt. Ihre Fanatiker sehen keinen Unterschied zwischen der geistlosen Geißel und den Verlassenen mit freiem Willen. Ihre Anwesenheit an der Grenze von Todesend bedroht die neu auferstandenen Toten."},{t="Vorbeugende Vergeltung",b="Exekutor Arren befiehlt einen Angriff, bevor vom Lager aus ein organisierter Angriff auf Todesend erfolgen kann. Ihr streckt Scharlachrote Konvertiten und Scharlachrote Novizen nieder und kehrt dann mit ihren karmesinroten Armbinden als Beweis zurück. Die heiligen Fanatiker betrachten alles tote Fleisch als Gräuel, also müssen die Verlassenen ihr Überleben mit Gewalt erkämpfen."}},faq={{q="Wer ist der Scharlachrote Kreuzzug?",a="Der Scharlachrote Kreuzzug ist eine religiöse Bewegung, die die Untoten ausrotten will. Trauer und religiöser Eifer nach dem Fall Lordaerons trieben seine Mitglieder in den Wahnsinn. Sie sehen keinen Unterschied zwischen der geistlosen Geißel und den Verlassenen mit eigenem Bewusstsein und wollen beide ausmerzen.",al={"geschichte des scharlachroten kreuzzugs","was ist der scharlachrote kreuzzug","scharlachrote fanatiker"}},{q="Warum lagert der Scharlachrote Kreuzzug nahe Todesend?",a="In Todesend werden neue Verlassene erweckt und versammelt. Der Scharlachrote Kreuzzug hat einen kleinen Außenposten errichtet, um die Gegend auszukundschaften, neu auferstandene Untote zu überrumpeln und Truppen gegen die junge Siedlung zu sammeln.",al={"warum sind scharlachrote in todesend","scharlachrotes lager todesend"}},{q="Warum greifen die Verlassenen zuerst an, statt zu reden?",a="Exekutor Arren sagt, die Kreuzfahrer seien von ihrem Eifer geblendet und sähen alle Untoten als Gräuel, die ausgelöscht werden müssen. Sie lassen nicht mit sich reden und verhandeln nicht mit den Toten, also greifen die Verlassenen zu ihrer Verteidigung zuerst an.",al={"können verlassene mit dem scharlachroten kreuzzug verhandeln","warum scharlachrote angreifen"}},{q="Welchen Rang haben die Kreuzfahrer in diesem Lager?",a="Das Lager ist größtenteils mit Rekruten und Anwärtern besetzt: Scharlachroten Konvertiten und Scharlachroten Novizen. Obwohl sie in den Reihen des Kreuzzugs weit unten stehen, macht ihr Eifer sie für neu auferstandene Verlassene gefährlich.",al={"wer ist im lager","scharlachrote konvertiten novizen"}},{q="Was folgt auf den Abschluss dieser Mission?",a="Exekutor Arrens Vorgesetzte in Brill berichten, dass ein Bote des Kreuzzugs vom Scharlachroten Kloster ins Lager gekommen ist. Arren schickt Euch los, um den Red Messenger abzufangen und dessen Schlachtpläne aufzudecken.",al={"welche quest folgt danach","questreihe nach dem scharlachroten kreuzzug"}},{q="Wer ist Exekutor Arren?",a="Exekutor Arren befehligt das Militär von Todesend und wacht über die Verteidigung der Siedlung. Er schickt frisch erwachte Verlassene gegen Bedrohungen in der Nähe.",al={"arrens rolle","wer vergibt die quest"}}},fx={e81ecc24={q="Warum will Exekutor Arren, dass das Lager von The Scarlet Crusade eliminiert wird?",a="Todesend ist die zerbrechliche Wiege der neu erwachten Verlassenen, und ein feindlicher menschlicher Außenposten direkt vor der Haustür stellt eine unmittelbare Überlebensbedrohung dar. The Scarlet Crusade weigert sich, zwischen der geistesgesteuerten Geißel und den freien Verlassenen zu unterscheiden, und hat geschworen, jeden Untoten zu vernichten, dem sie begegnen. Da die Mine kürzlich gesichert wurde, besteht Exekutor Arren darauf, präventiv zuzuschlagen, bevor diese Abteilung Stärke sammeln oder einen Angriff auf die Siedlung starten kann.",al={"motiv von arren","warum scharlachroten kreuzzug töten","warum scharlachrotes lager angreifen"}},d772c2c9={q="Wozu ist die Scharlachrote Armbinde gut?",a="Die Scharlachrote Armbinde dient als unbestreitbarer physischer Beweis dafür, dass Ihr das Lager aufgerieben und ihre Reihen dezimiert habt. Jedes Armband wird von den gefallenen Eiferern abgestreift – Konvertiten und Initiaten, die ihre leuchtend roten Farben mit blindem Fanatismus tragen. Wenn Ihr zwölf davon zurückbringt, bestätigt dies Exekutor Arren, dass der unmittelbare Übergriff in der Nähe von Todesend zerschlagen wurde.",al={"verwendung von scharlachroter armbinde","warum armbinden sammeln","scharlachrote armbinde"}}},fp="19,199,18.349.0,22.300.0,28.245.0,51.207.0,50.205.0,47.187.0,42.195.1,22.132.0"}
P.entries["quest:382"] = {n="Der Rote Bote",s="Exekutor Arren schickt Euch einem Kurier hinterher, der zum Lager außerhalb von Todesend unterwegs ist. Der Kurier wurde vom Scharlachroten Kloster entsandt und bringt dem Lager die Nachricht des Kreuzzugs. Dieser Vorstoß sichert Informationen, bevor die Eiferer ihren Einfluss im Tal festigen können, während die Verlassenen ihre junge Zuflucht verteidigen.",h="Exekutor Arren schickt Euch einem Kurier hinterher, der zum Lager außerhalb von Todesend unterwegs ist.",kw={"brill","todesend","exekutor arren","meven korgal","roter bote","scharlachroter kreuzzug","scharlachrote dokumente","das scharlachrote kloster","tirisfal"},ang={["class:Rogue"]="Als neu erwachter Schurke führt Ihr einen verdeckten Einsatz aus, indem Ihr das Lager des Kreuzzugs infiltriert, Meven Korgal tötet und seine Depeschen stehlt.",["faction:Horde"]="Als neuer Rekrut der Horde helft Ihr, die Unternehmungen der Scharlachroten am Nordrand des neu errichteten Stützpunkts der Horde in den Östlichen Königreichen zu zerschlagen.",["race:Undead"]="Ihr schlagt gegen Eiferer zu, die Euch erneut töten wollen, bevor Ihr in Lordaeron Fuß gefasst habt."},sec={{t="Augen im Osten",b="Exekutor Arren erfährt von seinen Vorgesetzten in Brill von dem scharlachroten Kurier. Der Scharlachrote Kreuzzug hat einen Abgesandten von seiner Festung im Scharlachroten Kloster nach Westen gen Todesend geschickt. Kreuzzügler rücken überall in Lordaeron vor. Ein Kurier am Rand der Erwachungsstätten der Verlassenen deutet auf einen organisierten Versuch hin, die neu Erweckten zu vernichten, bevor sie ihre Verteidigung vorbereiten können."},{t="Den Kurier abfangen",b="Meven Korgal, der Kurier, hat sich ohne auffällige Wappen unter die Scharlachroten im kleinen Lager östlich von Todesend gemischt. Exekutor Arren befiehlt einen gezielten Angriff, um Korgal zu töten und seine Depesche an sich zu bringen. Die Wegnahme der Schreiben unterbindet die weitere taktische Abstimmung zwischen den örtlichen Eiferern und ihrem Hauptquartier im Osten."},{t="Entscheidende Depeschen",b="Die sichergestellten Dokumente des Scharlachroten Kreuzzugs enthalten Propaganda, Spähberichte und direkte Befehle an die Eiferer, ihr Lager nahe der zerstörten Hauptstadt auszubauen. Sie enthalten auch eine strategische Karte, auf der Feldkommandanten und Agenten in ganz Tirisfal verzeichnet sind. Die Karte ist wertvoll genug, um eine sofortige Übergabe an höhere Stellen in Brill zu rechtfertigen."}},faq={{q="Wer ist der Rote Bote?",a="Meven Korgal ist ein menschlicher Kurier im Dienst des Scharlachroten Kreuzzugs. Er wurde vom Scharlachroten Kloster entsandt, um den Eiferern nahe Todesend strategische Befehle zu überbringen.",al={"meven korgal","wer ist meven korgal","wer ist der bote","identität des scharlachroten boten"}},{q="Woher kam der Bote?",a="Der Bote kam aus dem Scharlachroten Kloster, dem gewaltigen, befestigten Hauptquartier des Scharlachroten Kreuzzugs im Nordosten von Tirisfal.",al={"woher kam korgal","herkunft des boten","herkunft des scharlachroten kuriers"}},{q="Welche Informationen wurden in den Dokumenten gefunden?",a="Die Depeschen enthalten Spähberichte, Befehle zum Ausbau der Befestigungen der Kreuzzügler nahe der zerstörten Stadt Lordaeron und eine strategische Karte mit den Positionen der Feldkommandanten und Agenten des Kreuzzugs.",al={"inhalt der scharlachroten dokumente","wie lauten die befehle","was trug korgal bei sich"}},{q="Wohin gelangen diese Informationen als Nächstes?",a="Exekutor Arren leitet die Karte und die gesammelten Informationen sofort an seine Vorgesetzten in Brill weiter. Dadurch erhält das gesamte Militär der Verlassenen konkrete Angriffsziele in ganz Tirisfal.",al={"was geschieht mit den dokumenten","wohin die scharlachroten papiere bringen","quest vital intelligence"}},{q="Warum dringt der Scharlachrote Kreuzzug so nah an Todesend heran?",a="Der Scharlachrote Kreuzzug will alle untoten Monstrositäten unterschiedslos auslöschen. In Todesend erheben sich frisch befreite Untote erstmals aus ihren Gräbern, weshalb Eiferer den Ort ins Visier nehmen, um die Verlassenen vor ihrer Organisierung zu vernichten.",al={"warum sind scharlachrote in todesend","kreuzzug in todesend","warum sind die eiferer hier"}},{q="Wer gab Exekutor Arren den Hinweis auf den Boten?",a="Die Führung der Verlassenen in Brill fing die Nachricht vom Aufbruch des Kuriers aus dem Kloster ab und leitete sie an Arren weiter, damit seine örtlichen Truppen ihn abfangen konnten.",al={"wer warnte arren","wer schickte arren den bericht","woher wussten die verlassenen davon"}}},fx={["266afb7b"]={q="Warum möchte Exekutor Arren, dass dies erledigt wird?",a="Todesend ist das junge Zufluchtsort der Verlassenen, und der Scharlachrote Kreuzzug hat dreist direkt an seiner Schwelle ein Lager aufgeschlagen. Nachrichten von Arrens Vorgesetzten in Brill warnten, dass ein feindlicher Kurier direkt aus dem Scharlachroten Kloster mit wichtiger Korrespondenz eingeschlüpft sei. Das Abfangen dieser Depeschen ermöglicht es den Verlassenen, die Bewegungen des Kreuzzugs vorherzusehen und den Angriff der Eiferer abzustumpfen, bevor ihr Stützpunkt Todesend vollständig ersticken kann.",al={"motiv von arren","warum den boten töten","warum will arren scharlachrote dokumente"}},f56377a4={q="Warum schickt Euch Exekutor Arren anstelle seiner Wachen?",a="Die Garnison von Todesend ist bereits überlastet, nur um die Linie gegen Überreste der Geißel, streunende Bestien und aggressive Scharlachrote Patrouillen um den Zufluchtsort herum zu halten. Da Ihr Euren Mut bereits bewiesen habt, indem Ihr die Kreuzfahrer in ihrem Lager dezimiert habt, betrachtet Exekutor Arren Euch als den fähigsten verfügbaren Operativen, um an ihrem Perimeter vorbeizuschleichen und den Kurier niederzustrecken.",al={"warum schickt ihr mich wegen rotem boten","warum keine todesend-wachen benutzen","warum ich arren"}}},fp="17,315,16.359.0,24.309.0,16.334.1,25.157.0,34.132.0,44.194.1,37.169.1,62.236.0,52.153.0"}
P.entries["quest:3821"] = {n="Schreckensfels",s="In der Brennenden Steppe ist Sha'nis Zug seit mehr als drei Wochen verschwunden. Thal'trak Proudtusk kann seinen Posten nicht verlassen und bittet Euch, herauszufinden, was aus seiner Frau geworden ist.",h="In der Brennenden Steppe ist Sha'nis Zug seit mehr als drei Wochen verschwunden.",kw={"ödland","brennende steppe","schreckensfels","firegut-oger","goretooth","sha'ni proudtusk","thal'trak proudtusk"},sec={{t="Ein Ehemann ohne Nachricht",b="Sha'ni ging in die Brennende Steppe, um seltsame Rituale unter den Firegut-Ogern zu untersuchen. Mehr als drei Wochen sind vergangen, und Goretooth hat nichts von ihrem Zug gehört. Er sagt Thal'trak, er solle die Sache hinter sich lassen und weiter seine Pflicht erfüllen. Doch Sha'ni ist seine Frau, und Thal'trak will das nicht hinnehmen. An seinen Posten gebunden, bittet er Euch, nach ihr zu suchen."},{t="Sha'nis Worte",b="Sha'ni spricht voller Mitleid von Thal'trak. Sie hatten geplant, nach Ablauf ihrer Dienstzeiten bei ihrer Mutter und ihrem Vater im Hinterland zu leben. Nun sind diese Pläne zunichtegemacht."}},faq={{q="Wen sucht Thal'trak?",a="Thal'trak sucht seine Frau, Sha'ni Proudtusk. Sie wurde in die Brennende Steppe geschickt, um seltsame Rituale unter den Firegut-Ogern zu untersuchen, und niemand hat von ihr gehört.",al={"wer wird vermisst","thaltraks frau","sha'ni proudtusk"}},{q="Warum ging Sha'ni in die Brennende Steppe?",a="Sha'ni wurde vor mehr als drei Wochen in die Brennende Steppe geschickt, um Berichten über seltsame Rituale unter den Firegut-Ogern nachzugehen.",al={"shanis auftrag","ritual der firegut-oger","warum ging shani fort"}},{q="Warum hat Thal'trak nicht selbst nach ihr gesucht?",a="Thal'trak kann seinen Posten nicht verlassen, deshalb bittet er Euch, an seiner Stelle nach Sha'ni zu suchen.",al={"warum kann thaltrak nicht gehen","warum wartet thaltrak"}},{q="Was sagt Goretooth über den vermissten Zug?",a="Goretooth hat von niemandem aus Sha'nis Zug etwas gehört. Er rät Thal'trak, die Sache hinter sich zu lassen und weiter seine Pflicht zu erfüllen.",al={"goretooths antwort","was sagt goretooth"}}},fp="14,171,22.355.0,14.164.1,29.175.0,41.131.0,46.82.0,50.132.0"}
P.entries["quest:383"] = {n="Entscheidende Informationen",s="In Tirisfal trägt ein frisch auferstandener Verlassener erbeutete Dokumente des Scharlachroten Kreuzzugs von Todesend nach Brill. Exekutor Zygand erwartet den Boten dort.",h="In Tirisfal trägt ein frisch auferstandener Verlassener erbeutete Dokumente des Scharlachroten Kreuzzugs von...",kw={"brill","coldhearth-anwesen","todesend","dokumente","exekutor arren","exekutor zygand","scharlachroter kreuzzug","tirisfal","entscheidende informationen"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr den Verlassenen, ihre Herrschaft über Tirisfal zu festigen und den nördlichen Zugang zur Unterstadt vor Vorstößen des Scharlachroten Kreuzzugs zu schützen.",["race:Undead"]="Als Untoter markiert die Beförderung dieser abgefangenen Pläne Euren Übergang von Todesend in den größeren Krieg um Lordaeron. Ihr habt Euch nach Eurer Auferstehung aus dem Grab bewährt."},sec={{t="Abschied von Todesend",b="Exekutor Arren schickt Euch mit erbeuteten Dokumenten des Scharlachroten Kreuzzugs aus Todesend fort. Ihr habt örtliche Bedrohungen bekämpft und einen Boten des Scharlachroten Kreuzzugs abgefangen, und nun erwarten Euch umfassendere Aufgaben. Verlasst Todesend durch die geschützte Schlucht und folgt der Straße nach Osten in Richtung Brill, vorbei am Coldhearth-Anwesen."},{t="Ein entscheidender Schlag",b="In Brill studiert Exekutor Zygand die erbeutete Korrespondenz. Die Dokumente nennen aktive Kommandanten des Scharlachroten Kreuzzugs in ganz Tirisfal und führen ihre Aufträge auf. Zygand plant gezielte Tötungen, um die Führung und die Moral der Fanatiker zu brechen."}},faq={{q="Welche Informationen enthalten die Dokumente des Scharlachroten Kreuzzugs?",a="Die erbeuteten Dokumente nennen Offiziere des Scharlachroten Kreuzzugs, die in ganz Tirisfal stationiert sind, und führen ihre Aufträge auf. Exekutor Zygand plant schnelle Schläge, um die örtliche Führung auszuschalten und den Kreuzzug zu demoralisieren.",al={"was sind die scharlachroten dokumente","inhalt der dokumente des scharlachroten kreuzzugs","welche informationen wurden gesammelt"}},{q="Wo befindet sich Exekutor Zygand?",a="Exekutor Zygand wartet in Brill, direkt vor dem Rathaus von Brill neben dem Hauptplatz des Ortes.",al={"wo ist zygand","exekutor zygand finden","standort von exekutor zygand"}},{q="Wie komme ich von Todesend nach Brill?",a="Folgt der Straße nach Norden aus Todesend hinaus. Nehmt an der Weggabelung ins übrige Tirisfal den östlichen Weg am Coldhearth-Anwesen vorbei und überquert dann die überdachte Brücke nach Brill.",al={"weg nach brill","wie nach brill gelangen","wegbeschreibung nach brill"}},{q="Warum markiert diese Quest das Ende von Todesend?",a="Todesend ist die erste Bewährungsstätte für neu erwachte Verlassene. Nachdem Ihr geholfen habt, den Weiler zu sichern und nützliche Informationen über den Scharlachroten Kreuzzug zu sammeln, schickt Euch Exekutor Arren zu höherrangigen Kommandanten in Brill.",al={"mit todesend fertig","warum todesend verlassen","ist dies die letzte quest in todesend"}},{q="Wer ist Exekutor Arren?",a="Exekutor Arren ist der Offizier der Verlassenen, der die Einsätze und die Sicherheit in Todesend überwacht. Er begleitet auch die ersten Schritte frisch auferstandener Untoter in ihrer neuen Gemeinschaft.",al={"wer ist arren","arrens geschichte"}},{q="Was geschieht nach der Übergabe dieser Dokumente?",a="Mit der Übergabe der Dokumente werdet Ihr Teil der umfassenderen militärischen Unternehmungen der Verlassenen mit Sitz in Brill. Von dort aus richten sich Aufträge in ganz Tirisfal gegen örtliche Lager des Scharlachroten Kreuzzugs und Überreste der Geißel.",al={"what comes next","nächste quest nach entscheidende informationen"}}},fx={f3a0a7d2={q="Warum möchte Exekutor Arren, dass die Dokumente nach Brill geliefert werden?",a="Exekutor Arren weiß, dass die geborgenen Dokumente wichtige Informationen über die Führung des Scharlachroten Kreuzzugs in Tirisfal enthalten. Todesend ist lediglich ein Bereitstellungsraum für die neu Erstandenen, daher fallen taktische Entscheidungen auf regionaler Ebene an seinen Vorgesetzten, Exekutor Zygand in Brill. Arren will die Papiere sofort in Zygands Händen sehen, damit das Militärkommando der Verlassenen einen entscheidenden, moralisch zerstörerischen Schlag gegen die Eiferer koordinieren kann.",al={"warum dokumente an zygand liefern","motiv von exekutor arren","warum dokumente nach brill schicken"}},["5664ce4f"]={q="Warum schickt Euch Exekutor Arren anstelle seiner eigenen Todeswachen?",a="Todesend wird ständig von den Gedankenlosen, Überresten der Geißel und Scharlachroten Eiferern belagert, was dazu führt, dass Exekutor Arren seine Todeswachen nicht von ihren Verteidigungsposten abziehen kann. Ihr hingegen habt Eure Kompetenz bereits bewiesen, indem Ihr den Scharlachroten Boten abgefangen und die Informationen gesichert habt. Arren erkennt, dass Ihr dem geschützten Tal von Todesend entwachsen seid, und sieht diese Mission sowohl als einen wesentlichen Kurierlauf als auch als eine Einführung in die breiteren Kriegsanstrengungen der Verlassenen unter Exekutor Zygand.",al={"warum mich zu zygand schicken","warum keine wachen für dokumente nutzen","warum vertraut mir arren"}}},fp="18,151,18.298.0,17.242.1,57.211.0,33.91.0,38.170.0,49.219.0,22.150.0,46.201.0"}
P.entries["quest:384"] = {n="Eberrippchen in Biersauce",s="In der Brauerei Donnerbräu in Kharanos verlangen die Gäste nach Ragnar Donnerbräus berühmten Rippchen. Sein Stammlieferant ist der Armee des Königs beigetreten, daher braucht Ragnar frische Klippeneberrippchen und Rhapsody-Malzbier, damit sie auf der Speisekarte bleiben.",h="In der Brauerei Donnerbräu in Kharanos verlangen die Gäste nach Ragnar Donnerbräus berühmten Rippchen.",kw={"eberrippchen in biersauce","klippeneber","dun morogh","kharanos","ragnar donnerbräu","rhapsody-malzbier","brauerei donnerbräu"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr sehen, wie die Kriegsanstrengungen selbst die Wirtshäuser von Kharanos erreichen. Die einheimischen Bergbewohner geben ihr Handwerk auf, um dem Ruf zu den Waffen zu folgen.",["profession:Cooking"]="Wenn Ihr gern am Herd kocht, könnt Ihr von einem der berühmten Braumeister Dun Moroghs lernen, Malzbier mit Wildfleisch zu verbinden.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass kräftiges Bier und gebratener Eber das Herzstück der Gastfreundschaft in den Bergen sind. Die Vorräte der Brauerei aufzufüllen, ist eine Frage des örtlichen Stolzes."},sec={{t="Ein Wirtshaus in Not",b="Gastwirt Ragnar Donnerbräu hat hungrige Gäste, doch seine Speisekammer ist leer. Der einheimische Jäger, der frisches Fleisch lieferte, trat der Armee des Königs bei, um die Front der Allianz zu verstärken. Nun hat Ragnar keine frischen Rippchen mehr für die Gäste, die sie so schätzen."},{t="Die geheime Zutat",b="Klippeneber durchstreifen die verschneiten Vorgebirge rund um Kharanos, und ihr Fleisch ist zäh. Ragnars Rezept verlangt außerdem frisches Rhapsody-Malzbier, direkt aus den Zapfhähnen der Brauerei. Das Malzbier macht das Wildfleisch zart und daraus ein herzhaftes Festmahl, das selbst einem Zwerg Lob entlockt."}},faq={{q="Warum fehlt Ragnar Donnerbräu frisches Fleisch?",a="Ragnars gewohnter Fleischlieferant war ein einheimischer Fallensteller aus den Bergen, der Kharanos verließ, um der Armee des Königs beizutreten. Der Fallensteller zog fort, um Einsätze der Allianz in der Fremde zu unterstützen, wodurch dem Wirtshaus die regelmäßige Versorgung mit Wildfleisch fehlt.",al={"warum braucht ragnar eberrippchen","was geschah mit ragnars fleischlieferanten","wer liefert die rippchen"}},{q="Woher kommt Rhapsody-Malzbier?",a="Rhapsody-Malzbier wird in der Brauerei Donnerbräu in Kharanos gebraut und ausgeschenkt. Ragnar zapft es direkt am Schanktresen des Wirtshauses.",al={"woher rhapsody-malzbier bekommen","wie malzbier für ragnar bekommen","wer verkauft rhapsody-malzbier"}},{q="Von welchen Ebern stammen die Rippchen?",a="Die Rippchen stammen von Klippenebern, die durch die Hügel, Schneewehen und gefrorenen Täler rund um Kharanos in Dun Morogh streifen.",al={"welche eber lassen rippchen fallen","wo eberrippchen in dun morogh finden","klippeneber dun morogh"}},{q="Was ist das Geheimnis von Ragnars Rippchenrezept?",a="Ragnar übergießt zähe Eberrippchen beim Braten mit Rhapsody-Malzbier. Das Malzbier macht das Wild aus den kalten Landen zart und verleiht ihm den kräftigen Geschmack zwergischer Braukunst.",al={"geheimnis der rippchen in biersauce","eberrippchen in biersauce geheimnis"}},{q="Wer kämpft für die Armee des Königs an vorderster Front?",a="Zwergische Rekruten treten der Armee des Königs bei, die fortwährend gegen Troggs, gegen Einfälle der dark iron und an weiteren Fronten in den Östlichen Königreichen kämpft.",al={"warum trat der fallensteller der armee bei","welchen krieg führt die armee des königs","allianz frontlinien fünfundzwanzig adp"}},{q="Wo liegt die Brauerei Donnerbräu?",a="Die Brauerei Donnerbräu ist das wichtigste Wirtshaus und Gasthaus von Kharanos, an der Hauptstraße durch das Zentrum von Dun Morogh.",al={"wo liegt die brauerei donnerbräu","wo ist ragnar donnerbräu","gasthaus kharanos standort"}}},fx={["44c418cd"]={q="Wozu sind die Eberrippchen gut?",a="Ragnar benötigt diese Rippchen, um das Spezialgericht seiner Taverne, Beer Basted Boar Ribs, zuzubereiten. Die lokalen Gäste verlangen danach, aber sein regulärer Fleischlieferant ist der Armee des Königs beigetreten, um an der Front zu kämpfen, wodurch die Brauerei Donnerbräu völlig ohne frischen Vorrat dasteht.",al={"verwendung von eberrippchen","warum rippchen","wozu sind eberrippchen gut"}},ba894b88={q="Warum braucht Ragnar einen Abenteurer, um die Zutaten zu sammeln?",a="Ragnar ist damit beschäftigt, die Brauerei Donnerbräu zu leiten und durstige Tavernengäste in Kharanos zu bedienen. Da sein üblicher Lieferant in der Armee des Königs kämpft, muss er sich auf durchreisende Abenteurer wie Euch verlassen, um die lokalen Crag Boars zu jagen und Zutaten vom Gastwirt im Inneren zu holen.",al={"warum ich ragnar","warum kann ragnar keine rippchen besorgen","warum fragt ihr mich ragnar"}}},fp="21,224,16.240.0,21.254.0,40.215.0,35.123.0,36.108.0,42.138.0,55.155.0,44.112.0"}
P.entries["quest:3841"] = {n="Waise sucht Zuhause",s="Kindal Mondweber hat nach Darnassus Neuigkeiten für Euch: Das Nest wurde gerettet, doch die Mutter starb. Die Jungen werden bald schlüpfen, und Kindal bietet Euch ein Ei an, um das Ihr Euch kümmern könnt. Quentin wartet an den Rennstrecken in der Schimmernden Ebene von Tausend Nadeln.",h="Kindal Mondweber hat nach Darnassus Neuigkeiten für Euch: Das Nest wurde gerettet, doch die Mutter starb.",kw={"ei","feralas","kindal mondweber","quentin","die schimmernde ebene","grimmlingflitzer","tausend nadeln"},sec={{t="Ein Nest ohne Mutter",b="Kindal Mondweber begrüßt Euch nach Eurer Rückkehr aus Darnassus. Das Nest wurde gerettet, doch die Mutter starb, bevor Hilfe sie erreichen konnte. Die Jungen stehen kurz vor dem Schlüpfen und brauchen einen guten Pfleger. Kindal bietet Euch eines als Haustier an. Bringt das Ei zu Quentin an den Rennstrecken in der Schimmernden Ebene, wenn Ihr Euch darum kümmern möchtet. Quentin kann Euch mehr erzählen."},{t="Quentin in der Ebene",b="Quentin wartet in Tausend Nadeln, doch die Rennen sind nicht der Grund für seinen Aufenthalt. Er untersucht, ob neuer, fruchtbarer Boden das Land wiederherstellen kann. Er hofft, in der Nähe eine Wasserquelle zu finden. Der Übergang von Feralas nach Tausend Nadeln erscheint ihm seltsam. Quentin sagt, dass seltsame Magie am Werk war, als es dazu kam."},{t="Was Quentin vom Ei hält",b="Quentin erkennt das Ei als ein Grimmlingflitzerei, fast ausgereift und in bemerkenswert gutem Zustand. Er staunt, dass Ihr eines gefunden habt. Grimmlingflitzer sieht man heutzutage selten in Feralas, und Quentin hat gehört, dass Wilderer sie aus verschiedenen Gründen jagen, um sie zu fangen oder zu töten. Er findet das bedauerlich. Ausgewachsene Grimmlingflitzer sind wunderschön. Wie seid Ihr an einen solchen Fund gelangt?"}},faq={{q="Woher stammt das Ei?",a="Während Ihr in Darnassus wart, retteten Kindal Mondweber und andere ein Nest voller Eier. Die Mutter starb, bevor sie sie erreichen konnten.",al={"woher stammt das ei","herkunft des eis","geschichte des grimmlingflitzereis"}},{q="Wo ist Quentin zu finden?",a="An den Rennstrecken in der Schimmernden Ebene von Tausend Nadeln.",al={"quentins standort","wo ist quentin","quentin schimmernde ebene"}},{q="Warum ist Quentin in der Schimmernden Ebene?",a="Quentin untersucht, ob neuer, fruchtbarer Boden das Land wiederherstellen kann, und hofft, in der Nähe eine Wasserquelle zu finden. Wegen der Rennen ist er nicht dort.",al={"warum ist quentin an der rennstrecke","was macht quentin","quentins forschung"}}},fp="28,235,23.347.0,20.298.0,29.371.1,28.129.0,27.63.0,39.134.0"}
P.entries["quest:3842"] = {n="Kurz vor dem Schlüpfen",s="In Tausend Nadeln wartet Quentin, während das Grimmlingflitzerei kurz vor dem Schlüpfen steht. Die Moonweavers haben Euch das Ei gegeben, und Quentin bittet um zwei Elixiere der Seelenstärke, um seinen Zustand zu prüfen und es zu schützen.",h="In Tausend Nadeln wartet Quentin, während das Grimmlingflitzerei kurz vor dem Schlüpfen steht.",kw={"elixier der seelenstärke","feralas","illusionenrennbahn","moonweavers","quentin","grimmlingflitzerei","tausend nadeln"},ang={["profession:Alchemy"]="Als Alchemist könnt Ihr die Elixiere der Seelenstärke brauen, um die Quentin bittet."},sec={{t="Schutz für das Ei",b="Quentin findet es faszinierend, dass die Moonweavers sich um das Ei gekümmert haben, und hält beide für fähig. Da sie Euch das Ei gegeben haben, könnt Ihr die Verantwortung dafür übernehmen, solange Ihr möchtet. Es scheint fast bereit zum Schlüpfen zu sein, aber Quentin möchte zuerst seinen Zustand prüfen und sicherstellen, dass es unbeschädigt ist.\n\nEin kleiner Zauber wird das Ei schützen. Quentin hat alle Komponenten außer zwei Elixieren der Seelenstärke. Während er wartet, gibt er zu, dass ihn die Rennen zunehmend locken. Sobald er weiß, dass das Ei gesund ist, wird er es Euch zurückgeben, damit Ihr es behalten könnt."}},faq={{q="Wer bittet um die Elixiere?",a="Quentin wartet in Tausend Nadeln bei der Illusionenrennbahn und bittet um zwei Elixiere der Seelenstärke.",al={"wer vergibt diese quest","questgeber","quentins standort"}},{q="Was geschah unmittelbar zuvor?",a="Ihr habt Quentin das Ei in An Orphan Looking For a Home gebracht. Die Moonweavers haben es Euch gegeben.",al={"vorherige quest","woher stammt das ei","voraussetzung"}},{q="Was wird benötigt, um den Zauber zu vollenden?",a="Quentin benötigt zwei Elixiere der Seelenstärke für den Zauber. Die anderen Komponenten hat er bereits.",al={"was muss mitgebracht werden","benötigte gegenstände","benötigte elixiere"}},{q="Warum möchte Quentin die Elixiere?",a="Das Ei ist fast bereit zum Schlüpfen, und Quentin möchte sicherstellen, dass es gesund und unbeschädigt ist. Die Elixiere sind Teil eines kleinen Zaubers, der es schützen soll.",al={"warum elixier der seelenstärke","zweck der tränke"}}},fp="18,198,18.527.0,30.94.0,32.95.0,35.90.0,34.146.0"}
P.entries["quest:3843"] = {n="Das neueste Mitglied der Familie",s="Nur eine Stunde bleibt, um das zerbrechliche Ei zu Agnar Beastamer am Nistgipfel zu bringen, bevor der Schlüpfling darin stirbt.",h="Nur eine Stunde bleibt, um das zerbrechliche Ei zu Agnar Beastamer am Nistgipfel zu bringen, bevor der...",kw={"nistgipfel","agnar beastamer","feralas","zerbrechliches ei","hinterland","quentin","grimmlingflitzer"},sec={{t="Eilt zum Nistgipfel",b="Quentin bezeichnet das Grimmlingflitzerei als prachtvolles Exemplar. Wenn es überlebt, wird es ein gesundes Haustier abgeben. Er schickt Euch zum Nistgipfel im Hinterland, wo Agnar Beastamer die letzten Schritte des Ausbrütens anleiten kann. Der Zwerg ist ein meisterhafter Tierführer, und das Ei hält ohne Pflege nicht lange durch. Findet Agnar innerhalb einer Stunde, sonst stirbt der Schlüpfling darin. Er lebt in Burg Wildhammer."},{t="Agnars Urteil",b="Agnar Beastamer hat seit Ewigkeiten keine solche Kreatur mehr gesehen. Er bezeichnet sie als einen Feendrachen von der Art der Grimmlingflitzer. Das Kleine braucht Nahrung, um zu schlüpfen und kräftig zu werden. Agnar ist froh, dass Ihr rechtzeitig eingetroffen seid."}},faq={{q="Wer schickt Euch zu Agnar Beastamer?",a="Quentin schickt Euch nach A Short Incubation mit dem zerbrechlichen Ei zum Nistgipfel im Hinterland.",al={"questgeber","wer startet das neueste mitglied der familie","questgeber für das ei"}},{q="Wer muss das Ei erhalten?",a="Agnar Beastamer, ein Zwerg und meisterhafter Tierführer, muss das Ei am Nistgipfel erhalten. Er lebt in Burg Wildhammer.",al={"wohin mit dem ei","wer ist agnar beastamer","wer bekommt das ei"}},{q="Wie viel Zeit bleibt, um das Ei abzuliefern?",a="Eine Stunde. Wenn Ihr das Ei in dieser Zeit nicht zu Agnar bringt, stirbt der Schlüpfling darin.",al={"zeitlimit für das ei","wie viel zeit bleibt","zeitbegrenzung beim ei"}},{q="Wo gehört dieser Schritt in die Questreihe?",a="Dieser Schritt folgt auf A Short Incubation und schickt Euch mit dem Ei zu Agnar Beastamer am Nistgipfel.",al={"questreihe","what comes next","fortschritt der questreihe"}}},fp="31,113,19.382.0,15.195.1,33.97.0,25.116.0,42.87.0,38.92.0"}
P.entries["quest:385"] = {n="Krokiliskenjagd",s="In der Weitschreiter-Lodge sucht Marek Eisenherz Fährtenleser für die Jagd auf Loch Modans Krokilisken. Ihre Häute und ihr Fleisch sorgen für stetigen Handel, doch die Jagd an den Seeufern und auf den felsigen Inselchen ist gefährlich.",h="In der Weitschreiter-Lodge sucht Marek Eisenherz Fährtenleser für die Jagd auf Loch Modans Krokilisken.",kw={"krokiliskenjagd","krokiliskenfleisch","krokiliskenhaut","zwergenjäger","die weitschreiter-lodge","loch modan","marek eisenherz","der loch"},ang={["class:Hunter"]="Als Jäger könnt Ihr in der Weitschreiter-Lodge Euren Mut an den Gefahren in Loch Modans Gewässern erproben.",["profession:Cooking"]="Als Koch könnt Ihr aus zähem, magerem Krokiliskenfleisch herzhafte Eintöpfe und Braten zubereiten.",["race:Dwarf"]="Als Zwerg könnt Ihr stolz darauf sein, Loch Modans Wildnis zu zähmen und mit der Krokiliskenjagd Euren ehrlichen Lebensunterhalt zu verdienen."},sec={{t="Eine einträgliche Beute",b="Krokilisken lauern in den Untiefen und an den schlammigen Ufern und machen das Durchqueren und Fischen gefährlich. In ganz Khaz Modan suchen Handwerker und Schneider ihre Häute für robuste Rüstungen und Lederwaren. Urige Tavernen zahlen gut für das magere Schwanzfleisch."},{t="Kiefer in den Untiefen",b="Loch Modans Krokilisken sammeln sich vor allem um die felsigen Inselchen. Ihre zermalmenden Kiefer und scharfen Zähne machen sie zu gefährlicher Jagdbeute. Zwergische Veteranen wie Marek Eisenherz tragen Narben davon, diese Bestien im Ringkampf bezwungen zu haben. Er warnt, dass ein Fehltritt im Wasser ein Gliedmaß kosten kann. Einen Krokilisken zu häuten und zu zerlegen, erfordert Geduld, widerstandsfähigen Stahl und die Bereitschaft, sein Jagdrevier zu betreten."}},faq={{q="Warum werden Krokilisken in Loch Modan gejagt?",a="Händler und Handwerker schätzen Krokiliskenhäute für strapazierfähige Kleidung und Lederrüstungen, während örtliche Köche das Fleisch schätzen. Die Weitschreiter-Lodge handelt mit diesen Waren, um Händler zu versorgen, die durch Khaz Modan reisen.",al={"warum krokilisken jagen","krokiliskenfleisch häute verwendung","warum marek krokilisken will"}},{q="Wo sind die Krokilisken gewöhnlich zu finden?",a="Krokilisken leben in Loch Modans schlammigen Untiefen und entlang seiner Ufer, besonders um die felsigen Inseln in der Mitte des Sees.",al={"krokilisken fundort","wo krokilisken in loch modan finden","wo sind krokilisken"}},{q="Wer ist Marek Eisenherz?",a="Marek Eisenherz ist ein erfahrener zwergischer Gebirgsjäger und Jäger, der in der Weitschreiter-Lodge im Südosten von Loch Modan stationiert ist. Er handelt mit Materialien von heimischen Wildtieren und erzählt von knappen Begegnungen mit den wildesten Bestien des Lochs.",al={"marek eisenherz","wer vergibt krokiliskenjagd","questgeber marek"}},{q="Was macht die Jagd auf sie so gefährlich?",a="Loch Modans Krokilisken sind aggressive, revierverteidigende Raubtiere mit kräftigen Kiefern und scharfen Zähnen. Jäger treten ihnen im tiefen Wasser oder auf abgelegenen Inselchen gegenüber, wo das Gelände plötzliche Angriffe der Reptilien begünstigt.",al={"sind krokilisken gefährlich","gefahr durch krokilisken","warum sind krokilisken schwer zu jagen"}},{q="Ist Krokiliskenfleisch tatsächlich unbedenklich und essbar?",a="Ja. Fachgerecht zerlegt und gebraten, wird Krokiliskenfleisch von Köchen im Grenzland und Tavernengästen in allen Zwergenlanden für seine feste Beschaffenheit und seinen kräftigen Geschmack geschätzt.",al={"kann man krokilisken essen","krokiliskenfleisch essbar","krokilisk geschmack"}},{q="Was ist die Weitschreiter-Lodge?",a="Die Weitschreiter-Lodge ist ein Außenposten im Südosten von Loch Modan. Sie bietet Jägern, Fährtenlesern und Gebirgsjägern der Allianz Zuflucht und einen Ort, um sich auf die Wacht über die Wildnis des Tals vorzubereiten.",al={"was ist die weitschreiter-lodge","weitschreiter-lodge zweck","wo ist die weitschreiter-lodge"}}},fx={["148d1050"]={q="Warum möchte Marek Eisenherz, dass Krokilisken gejagt werden?",a="Marek Eisenherz betreibt aus der Weitschreiter-Lodge stetigen Handel mit Händlern, die gutes Geld für Krokiliskenhäute und -fleisch zahlen. Die wilden Reptilien halten die Inseln im Loch besetzt, was die Jagd gefährlich macht, aber Qualitätsexemplare erzielen einen zuverlässigen Gewinn bei Handwerkern und eifrigen Käufern.",al={"motiv von marek eisenherz","warum krokilisken jagen","warum will marek krokilisken"}},["2fb1eb6c"]={q="Wozu ist das Krokiliskenfleisch gut?",a="Marek sammelt Krokiliskenfleisch, um es an besuchende Händler und Reisende zu verkaufen. Obwohl der Kampf gegen die wilden Bestien gefährlich ist, genießen bestimmte abenteuerlustige Gäste und Händler den Geschmack und zahlen gut für frische Stücke.",al={"verwendung von krokiliskenfleisch","warum krokiliskenfleisch sammeln","wozu wird krokiliskenfleisch verwendet"}},["31a07b3d"]={q="Wozu ist die Krokiliskenhaut gut?",a="Die Häute werden von Händlern und Gerbern für die Herstellung von strapazierfähiger Kleidung und robuster Lederrüstung geschätzt. Marek verkauft die Häute, die Ihr mitbringt, um den Handel der Lodge mit vorbeikommenden Käufern aufrechtzuerhalten.",al={"verwendung von krokiliskenhaut","warum krokiliskenhäute sammeln","wozu ist krokiliskenhaut gut"}},["0bb4b9c6"]={q="Warum sind die Krokilisken in Loch Modan zu finden?",a="Die Krokilisken sind wilde heimische Raubtiere, die sich hauptsächlich auf den Inseln und an den Ufern von Loch Modan festgesetzt haben. Ihre dicken Häute und wilden Kiefer machen sie zu einer bestimmenden Gefahr des Süßwassersees.",al={"ursprung der krokilisken im loch modan","warum sind krokilisken hier","wer sind die krokilisken"}}},fp="17,195,18.227.0,20.374.0,40.200.0,39.125.0,23.213.0,37.209.0,43.159.0,29.179.0"}
P.entries["quest:386"] = {n="Verbrechen lohnt sich nicht",s="In Seenhain drängt Wache Berton auf die Hinrichtung von Targorr dem Schrecklichen. Der Schwarzfelsorc bleibt trotz seines Todesurteils im Verlies von Sturmwind, während politische Verzögerungen die Gerechtigkeit in weite Ferne rücken.",h="In Seenhain drängt Wache Berton auf die Hinrichtung von Targorr dem Schrecklichen.",kw={"berton","blackrock","henker","gath'ilzogg","seenhain","rotkammgebirge","verlies","targorr"},ang={["class:Paladin"]="Als Paladin steht Ihr im Konflikt zwischen geschriebenem Recht und moralischer Gerechtigkeit, wenn Ihr einen korrupten juristischen Aufschub umgeht, um einen reuelosen Folterer zu bestrafen.",["faction:Alliance"]="Für die Allianz offenbart dies die Kluft zwischen Grenzgarnisonen wie Seenhain und der eigennützigen Politik an Sturmwinds Adelshöfen.",["race:Human"]="Als Mensch aus diesem Königreich könnt Ihr persönliche Rechnungen für die Gräueltaten begleichen, die Targorr während der Blackrock-Invasion an Stadtwachen und Milizionären des Rotkammgebirges beging."},sec={{t="Ein Schlächter in der Schwebe",b="Targorr der Schreckliche machte sich im Rotkammgebirge einen Namen. Er diente als oberster Henker unter General Gath'Ilzogg, dem Häuptling der Schwarzfelsorcs auf Burg Steinwacht. Selbst unter den Invasoren war seine Grausamkeit berüchtigt. Er beaufsichtigte die Folter und Hinrichtung vieler Verteidiger des Rotkammgebirges. Nach seiner Gefangennahme schickte Sturmwind ihn in sein Hochsicherheitsgefängnis, das Verlies von Sturmwind, und verurteilte ihn wegen seiner Verbrechen gegen das Reich zum Tode."},{t="Korruption in hohen Kreisen",b="Ein ungenannter Adliger aus dem Adelshaus von Sturmwind griff ein, und Targorrs Hinrichtung wurde trotz seines Todesurteils ausgesetzt. Wache Berton, der im gefährdeten Seenhain stationiert ist, vermutet finstere Machenschaften oder Bestechung, um den Unhold freizubekommen. Er wirbt vertrauenswürdige Abenteurer an, die das von Aufständen erschütterte Gefängnis betreten und den Befehl ohne bürokratische Einmischung vollstrecken sollen."}},faq={{q="Wer ist Targorr der Schreckliche?",a="Targorr der Schreckliche ist ein Schwarzfelsorc, der als oberster Henker unter General Gath'Ilzogg im Rotkammgebirge diente. Vor seiner Gefangennahme und Inhaftierung im Verlies von Sturmwind folterte er gefangene menschliche Soldaten.",al={"targorr","wer ist targorr","targorr hintergrundgeschichte"}},{q="Warum hat Sturmwind Targorr noch nicht hingerichtet?",a="Ein Adliger in Sturmwind verzögerte Targorrs Hinrichtung trotz seines Todesurteils. Wache Berton vermutet Korruption oder finstere Machenschaften, um den orkischen Kriegsherrn zu verschonen oder für eigene Zwecke zu nutzen.",al={"warum lebt targorr noch","hinrichtungsaufschub durch adligen"}},{q="Wer vergibt die Quest Verbrechen lohnt sich nicht?",a="Wache Berton vergibt sie. Er ist in Seenhain im Rotkammgebirge stationiert, wo er die Stadt vor Überfällen der Schwarzfelsorcs schützt.",al={"questgeber","wo gibt es die quest"}},{q="Wo ist Targorr der Schreckliche zu finden?",a="Targorr wird im Verlies von Sturmwind im Kanalviertel von Sturmwind festgehalten. Meist ist er in einer Zelle im mittleren Zellenblock des Gefängnisses zu finden.",al={"targorr aufenthaltsort","wo ist targorr"}},{q="Wer ist General Gath'Ilzogg?",a="General Gath'Ilzogg befehligt die Schwarzfelsorcs, die Burg Steinwacht im östlichen Rotkammgebirge besetzen. Targorr diente unter ihm als Henker.",al={"gath'ilzogg","blackrock general rotkammgebirge"}},{q="Warum nimmt Wache Berton die Sache selbst in die Hand?",a="Berton sah, wie Soldaten aus dem Rotkammgebirge unter Targorrs Klingen litten und starben. Angewidert davon, dass Sturmwinds Politiker einen skrupellosen Mörder als politischen Spielball behandeln, umgeht er die offiziellen Wege, um für Gerechtigkeit zu sorgen.",al={"bertons beweggrund","warum adlige umgehen"}}},fx={["98ed3ebd"]={q="Warum möchte Wache Berton Targorrs Kopf?",a="Wache Berton benötigt Targorrs Kopf als unbestreitbaren Beweis dafür, dass der Schreckensfels-Henker tot ist. Da ein korrupter oder sich einmischender Adliger die rechtmäßige Hinrichtung von Targorr stoppte, kann sich Berton nicht auf offizielle Gefängnisberichte oder bürokratische Mundpropaganda verlassen. Das Zurückbringen des Kopfes nach Seenhain bestätigt, dass die Gerechtigkeit außerhalb der politischen Spiele von Sturmwind geübt wurde.",al={"zweck von targorrs kopf","warum targorrs kopf sammeln","wozu ist targorrs kopf gut"}},["8d124546"]={q="Warum braucht Wache Berton einen Abenteurer, anstatt es selbst zu erledigen?",a="Wache Berton ist in Seenhain stationiert, um das Rotkammgebirge zu verteidigen, gebunden an militärische Pflichten und die Befehlskette. Er kann seinen Posten nicht verlassen oder offen das Verlies betreten, um einen Gefangenen hinzurichten, dessen Urteil offiziell vom Adel von Sturmwind ausgesetzt wurde. Ein unabhängiger Abenteurer kann in das Gefängnis schlüpfen, politische bürokratische Hürden umgehen und die Tat ausführen, ohne die Stadtwache zu kompromittieren.",al={"warum schickt ihr mich wegen targorr","warum tötet berton targorr nicht","warum braucht mich berton"}}},fp="20,189,23.439.0,25.340.1,25.209.0,42.162.0,41.137.0,37.144.0,27.135.0,54.200.0"}
P.entries["quest:3861"] = {n="GLUCK!",s="In Westfall antwortet Euch vielleicht ein Huhn, wenn Ihr es ruft und füttert. Folgt seiner gescharrten Botschaft zur Familie Saldean, und vielleicht erhaltet Ihr ein warmes Ei zum Ausbrüten.",h="In Westfall antwortet Euch vielleicht ein Huhn, wenn Ihr es ruft und füttert.",kw={"huhn","hühner-ei","gluck","geflügel","saldean","saldean farm","spezial-hühnerfutter","westfall huhn"},ang={["faction:Alliance"]="Auf dem Saldean Farmstead in Westfall ist dieses seltsame Hühnerritual unter jungen Abenteurern der Allianz, die das leidgeprüfte ländliche Königreich erkunden, zu einer vertrauten Geschichte geworden.",["profession:Cooking"]="Das Spezial-Hühnerfutter des Huhns ist essbar, doch die meisten Köche heben das grobe Getreide für die Vögel auf."},sec={{t="Eine seltsame Verbundenheit",b="Überall in Azeroth streifen gewöhnliche Hühner über Gehöfte, doch die meisten Reisenden gehen achtlos an ihnen vorbei. Ahmt die Bewegungen und das Gackern eines Huhns nach, und vielleicht hört es auf zu picken und mustert Euch. In diesem kurzen Moment scharrt es Buchstaben in die Erde und weist Euch zu dem Bauern, der ihm das gewünschte Futter geben kann."},{t="Das Futter des Bauern",b="Der Vogel verlangt nach Spezial-Hühnerfutter, das die Familie Saldean in Westfall für ihre Hühnerschar bereithält. Bietet ihm das Getreide an und feuert das Huhn beim Fressen an. Im Gegenzug legt es ein warmes Ei, aus dem Ihr einen gefiederten Begleiter heranziehen könnt."}},faq={{q="Wie bietet ein Huhn eine Quest an?",a="Ahmt ein Huhn mit wiederholten Rufen oder flatternden Bewegungen nach. Schließlich hält es inne, um Euch zu mustern, und scharrt eine Botschaft über seinen Hunger in die Erde.",al={"hühnerquest starten","mit huhn sprechen","gluck quest freischalten"}},{q="Was schreibt das Huhn in die Erde?",a="Das Huhn scharrt S-A-L-D-E-A-N in den Boden. Der Name verweist auf Bauer Saldean und seine Frau auf der Saldean Farm im Herzen Westfalls, wo sie das gewünschte Getreide verkaufen.",al={"gescharrte hühnerwörter","was schreibt das huhn","saldean huhn"}},{q="Wo bekommt Ihr das Spezial-Hühnerfutter?",a="Bauer Saldean hält auf der Saldean Farm in Westfall Spezial-Hühnerfutter bereit.",al={"hühnerfutter händler","wo hühnerfutter kaufen","saldean futter"}},{q="Funktioniert das mit jedem Huhn auf der Welt?",a="Gewöhnliche Hofhühner in besiedelten Gebieten können auf die Geste reagieren. Am häufigsten findet man sie bei menschlichen Bauernhöfen, etwa denen in Westfall.",al={"welche hühner funktionieren","funktioniert jedes huhn","wo huhn finden"}},{q="Wie schließt Ihr die Quest ab, sobald Ihr das Futter habt?",a="Tragt Spezial-Hühnerfutter bei Euch und sucht ein Huhn. Feuert es beim Fressen an, und es legt unter sich ein Ei, das Ihr einsammeln könnt.",al={"gluck abgeben","huhn füttern ei","gluck quest abgeben"}},{q="Was bekommt Ihr für den Abschluss der Quest?",a="Das gefütterte Huhn legt ein Farm Chicken Egg zu seinen Füßen ab. Sammelt es ein, um ein Hühner-Ei zu erhalten, mit dem Ihr ein treues Huhn aus Westfall beschwören könnt, das Euch auf Euren Reisen folgt.",al={"gluck quest belohnung","hühner-ei haustier","westfall huhn belohnung"}}},fx={["034f7049"]={q="Warum braucht das Huhn Eure Hilfe, anstatt sich selbst Futter zu besorgen?",a="Als gewöhnliches Nutztier fehlt es ihm an Gold, Sprache und Händen, um Bauer Saldeans Getreide selbst zu kaufen. Nur ein Abenteurer, der geduldig genug ist, das hektische Gegacker und die in den Boden gekratzten Botschaften zu interpretieren, kann den Kauf tätigen und das Futter zurückbringen.",al={"warum kann huhn kein futter bekommen","warum braucht huhn mich","warum ich huhn"}},dbdbc3c2={q="Warum möchte das Huhn Spezial-Hühnerfutter?",a="Der Vogel hungert einfach nach einer bestimmten Leckerei. Nachdem Ihr genug Zeit damit verbracht habt, seine Gluckser und Flügelschläge nachzuahmen, erkennt es Euch als einen sympathischen Geist und kratzt den Namen von Bauer Saldean in den Dreck. Es will nichts weiter als eine Portion von Saldeans Spezial-Hühnerfutter und wartet hungrig darauf, dass Ihr zurückkehrt, um seinen Appetit zu stillen.",al={"warum hühnerfutter","warum will das huhn dies","motiv des huhns"}}},fp="6,150,19.288.0,17.230.0,33.145.0,44.176.0,42.74.0,46.140.0,53.124.0,40.165.0"}
P.entries["quest:387"] = {n="Niederschlagung des Aufstandes",s="Unter Sturmwind ruft Aufseher Thelwasser um Hilfe, als im Verlies ein Aufstand ausbricht. Defias-Gefangene haben die Zellenblöcke besetzt, und er will den Aufstand niederschlagen lassen, bevor die Stadtführung erfährt, wie gründlich das Gefängnis versagt hat.",h="Unter Sturmwind ruft Aufseher Thelwasser um Hilfe, als im Verlies ein Aufstand ausbricht.",kw={"sträflinge","defias","aufständische","niederschlagung des aufstandes","verlies","sturmwind","aufstand","aufseher thelwasser"},ang={["class:Paladin"]="Als Paladin müsst Ihr bei der Wiederherstellung der Ordnung unter der Stadt die Grenze zwischen rechtschaffener Gerechtigkeit und verzweifelter, tödlicher Vergeltung an rebellischen Bürgern ausloten.",["faction:Alliance"]="Unter Sturmwinds Straßen tobt die Rebellion im Verlies, ein schweres Sicherheitsversagen im Herzen des wichtigsten Königreichs der Allianz.",["race:Human"]="Viele Defias-Insassen in den Zellen sind ehemalige Steinmetze des Königreichs und einfache Leute, die zur Rebellion getrieben wurden. Ihr blutiger Aufstand ist für Sturmwinds Bevölkerung ein schmerzhafter innerer Konflikt."},sec={{t="Ein Gefängnis in Gefangenenhand",b="Das Verlies beherbergt Verbrecher, Verschwörer und Gesetzlose, die das Königreich Sturmwind bedrohen. Nun haben Defias-Mitglieder plötzlich gewaltsam rebelliert und den Wachen die Zellenblöcke entrissen. Bewaffnete Gefangene drängen sich in den Gängen, und die Ordnung ist zusammengebrochen. Die Wachen verlassen sich auf durchreisende Champions, die sich durch den Aufruhr kämpfen und das Gefängnis zurückerobern sollen."},{t="Verzweiflung und Vertuschung",b="Aufseher Thelwasser befiehlt, Defias-Gefangene bei Sichtkontakt zu töten. Verzweifelt und um seine Stellung besorgt, vermutet er übles Spiel hinter der koordinierten Meuterei. Er fürchtet, seinen Posten zu verlieren, wenn das Haus der Adligen oder der übrige Adel erfährt, dass das Verlies außer Kontrolle ist. Er hofft, dass die Todesstrafe für Aufruhr den Willen der Insassen bricht und die Rebellion niederschlägt, bevor die Nachricht über die Kanaltore hinausdringt."}},faq={{q="Warum bittet Aufseher Thelwasser Abenteurer, den Aufstand niederzuschlagen?",a="Defias-Insassen haben die inneren Zellen des Verlieses unter ihre Kontrolle gebracht, und die Wachen können sie nicht in Schach halten. Aufseher Thelwasser fürchtet um seinen Posten, falls Sturmwinds Führung das volle Ausmaß des Desasters erfährt, und heuert deshalb fähige Söldner an, die die Rädelsführer töten und rasch die Kontrolle wiederherstellen sollen.",al={"warum abenteurer anheuern","thelwassers beweggründe","warum die quest im verlies"}},{q="Welche Insassen beteiligen sich am Aufstand im Verlies?",a="Gefangene Mitglieder der Bruderschaft der Defias bilden den Kern des Aufstands. Unter ihnen sind gewöhnliche Gefangene, abgebrühte Sträflinge und organisierte Aufständische, die eingesperrt wurden, während die Bruderschaft ihren geheimen Krieg in Westfall und im Wald von Elwynn führte.",al={"wer rebelliert","defias-gefangene verlies","wer ist ausgebrochen"}},{q="Glaubt Thelwasser, dass der Aufstand von innen organisiert wurde?",a="Ja. Aufseher Thelwasser vermutet übles Spiel und glaubt, dass eine so plötzliche und umfassende Revolte nicht zufällig entstehen konnte, ohne Einmischung von außen oder untergrabene Sicherheitsvorkehrungen innerhalb der Stadt.",al={"war es verrat","übles spiel im verlies","gefängnisaufstand von innen organisiert"}},{q="Wo findet dieser Aufstand statt?",a="Der Aufstand findet im Verlies statt, einem unterirdischen Hochsicherheitsgefängnis an den Kanälen im Magierviertel von Sturmwind.",al={"wo ist das verlies","eingang zum verlies","lage des gefängnisses"}},{q="Was geschieht, nachdem diese aufständischen Defias getötet wurden?",a="Die Tötung der Aufständischen schwächt die Meuterer, doch bei Eurer Rückkehr räumt Aufseher Thelwasser ein, dass die Krise tiefer reicht als ein bloßes Handgemenge. Weitere Angriffe auf bedeutende Anführer tiefer in den Zellen sind nötig.",al={"wird das gefängnis sicher","nach niederschlagung des aufstandes"}},{q="Ist tödliche Gewalt gegen alle entflohenen Sträflinge erlaubt?",a="Aufseher Thelwasser erklärt den sofortigen Tod zur Strafe für aktive Beteiligung am Aufstand während der Gefängnisübernahme. Er befiehlt Champions, Gefangene, Sträflinge und Aufständische auf der Stelle hinzurichten, in der Hoffnung, die Überlebenden zur Unterwerfung zu zwingen.",al={"warum sie töten","strafe für aufruhr","ist das töten von gefangenen erlaubt"}}},fx={["2ef5cefa"]={q="Warum will Aufseher Thelwasser, dass der Aufstand niedergeschlagen wird?",a="Aufseher Thelwasser versucht verzweifelt, die Ordnung wiederherzustellen, bevor die städtischen Behörden erkennen, wie vollständig er die Kontrolle verloren hat. Sollte sich im restlichen Sturmwind herumsprechen, dass das Verlies vollständig von randalierenden Defias-Gefangenen überrannt wurde, riskiert er, seinen Posten und seine Existenzgrundlage zu verlieren. Abgesehen davon, dass er seinen eigenen Job retten will, befürchtet er, dass der gewaltsame Aufstand aus dem Gefängnis ausbrechen und die Bürger von Sturmwind direkt bedrohen wird.",al={"warum will thelwasser dies erledigt haben","thelwasser motiv quell the uprising","warum will der aufseher sie tot sehen"}}},fp="18,227,28.343.0,24.391.0,64.292.0,44.233.0,50.183.0,36.136.0,51.214.0,56.223.0"}
P.entries["quest:388"] = {n="Die Farbe von Blut",s="Nikova Raskol trauert um ihren jungen Enkel Mac, der im Gefängnis von Sturmwind getötet wurde. Zorn verzehrt sie, und sie schickt Abenteurer ins Verlies, um der Defias-Bande als Vergeltung ihre roten Bandanas abzunehmen.",h="Nikova Raskol trauert um ihren jungen Enkel Mac, der im Gefängnis von Sturmwind getötet wurde.",kw={"die farbe von blut","bruderschaft der defias","mac raskol","nikova raskol","rotes wollkopftuch","verlies","sturmwind"},ang={["faction:Alliance"]="Mac Raskols Tod zeigt die Belastung von Sturmwinds Heimatverteidigung und den bitteren Preis dafür, erfahrene Soldaten weit von der Hauptstadt fortzuschicken.",["race:Human"]="Als Mensch teilt Ihr Sturmwinds Leid durch die Gewalt der Defias auf den umliegenden Feldern und innerhalb der Stadtmauern."},sec={{t="Ein Junge auf der Gefängnismauer",b="Mac Raskol war vierzehn, als er im Verlies als Wache zu den Waffen griff. Sturmwinds reguläre Soldaten waren an ferne Fronten gezogen, also übernahmen Freiwillige und die Jugend der Stadt die örtliche Verteidigung. Mac bewachte abgebrühte Verbrecher und meuternde Mitglieder der Bruderschaft der Defias. Das Gefängnis war weitaus gefährlicher, als seine Erfahrung ihn darauf hätte vorbereiten können."},{t="Zeichen des Trotzes",b="Die gefangenen Defias zerrissen ihre wollenen Gefängnisdecken und fertigten aus den Fetzen rote Bandanas. Die Farbe zeigte ihre Treue zur Bruderschaft, selbst hinter Gefängnismauern. Mac wies sie zurecht und versuchte, Disziplin durchzusetzen. Die Gefangenen stachen ihm in den Rücken, und er starb auf dem Steinboden."},{t="Trauer und Vergeltung",b="Nach Macs sinnlosem Tod wendet sich Nikova Raskol von den offiziellen Wegen ab und sucht kalte Rache. Sie schickt Euch ins Verlies, um die aufständischen Gefangenen zu bezwingen und zehn ihrer geschätzten roten Bandanas zurückzubringen. Gefärbt in der Farbe des vergossenen Blutes ihres Enkels, bieten diese Zeichen einer gebrochenen Familie einen düsteren Abschluss."}},faq={{q="Wer ist Nikova Raskol?",a="Nikova Raskol ist eine ältere Einwohnerin von Sturmwind, deren vierzehnjähriger Enkel Mac kürzlich getötet wurde, als er im Verlies Wache hielt.",al={"nikova raskol","questgeber","wer vergibt die farbe von blut"}},{q="Warum bewachte ein Vierzehnjähriger gefährliche Gefangene?",a="Sturmwind entsandte einen Großteil seiner regulären Streitkräfte an ferne Fronten, also übernahmen Freiwillige und Jugendliche die örtliche Verteidigung, einschließlich der Wachposten im Verlies.",al={"warum war mac eine wache","mac alter","kind als wache"}},{q="Warum tragen die gefangenen Defias rote Wollbandanas?",a="Gefangene Defias fertigten rote Bandanas aus ihren wollenen Gefängnisdecken, um hinter Gittern ihre Treue zur Bruderschaft zu zeigen.",al={"warum rote bandanas","wollbandanas hintergrund","defias rote halstücher"}},{q="Wie starb Mac Raskol?",a="Mac ertappte die Gefangenen dabei, wie sie ihre Wolldecken zerrissen, um Defias-Bandanas anzufertigen, und wies sie zurecht. Sie stachen der vierzehnjährigen Wache in den Rücken.",al={"wie starb mac","wer hat mac getötet","was geschah mit mac"}},{q="Was macht Nikova mit den Bandanas?",a="Nikova behält die Bandanas als Beweis der Vergeltung. Sie starrt auf die zerrissenen Wollstücke und betrauert den sinnlosen Tod ihres Enkels, findet aber Frieden in dem Wissen, dass seine Mörder ihrer gerechten Strafe zugeführt wurden.",al={"was geschieht mit den bandanas","nikova bandanas"}},{q="Wo spielt diese Aufgabe?",a="Ihr betretet das Verlies, Sturmwinds Hochsicherheitsgefängnis im Kanalviertel, wo sich gefangene Defias in offenem Aufruhr befinden.",al={"woher kommen die bandanas","die farbe von blut ort"}}},fx={["04f6762b"]={q="Warum möchte Nikova Raskol, dass dies erledigt wird?",a="Nikova wird von Trauer und dem Verlangen nach Rache verzehrt. Ihr vierzehnjähriger Enkel, Mac, meldete sich freiwillig als Wache im Verlies, als die reguläre Armee an die Front geschickt wurde. Als Mac erwischte, wie Defias-Häftlinge ihre Wolldecken zerschredderten, um Gangfarben daraus zu machen, wies er sie zurecht und sie stachen ihm in den Rücken. Die Defias-Bandanas zu fordern, ist ihre Art, Gerechtigkeit und blutige Vergeltung für Macs sinnlosen Mord zu suchen.",al={"warum will nikova rache","nikova raskol motiv","warum defias im verlies töten"}},c39081cf={q="Gegen wen kämpft Ihr für diese Quest im Verlies?",a="Ihr werdet gegen die Defias-Häftlinge ausgesandt, die im Verlies randalieren. Diese Diebe, Wegelagerer und abtrünnigen Steinmetze wurden wegen ihres gewaltsamen Aufstands gegen die Krone unter Sturmwind inhaftiert. Nachdem die Garnison der Stadt zu fernen Fronten abmarschiert war, waren sie nur noch leicht bewacht, woraufhin die Sträflinge rebellierten, die Kontrolle über die Gefängniszellen übernahmen und die jungen Milizionäre, die dort Wache hielten, brutal abschlachteten.",al={"wer hat die roten wollbandanas","gegen wen kämpft man","the color of blood ziele"}},bfcf62d8={q="Warum bittet Nikova einen Abenteurer und nicht die Stadtwachen?",a="Die regulären Streitkräfte von Sturmwind wurden an ferne Fronten entsandt, was die Stadt mit einem Mangel an erfahrenen Soldaten zurückließ. Die lokale Miliz und unerfahrene Rekruten – wie der junge Mac Raskol – waren bereits überfordert, als die Gefangenen revoltierten und die Kontrolle über das Verlies komplett verloren ging. Da die verbleibende Stadtwache damit ausgelastet ist, die Straßen außerhalb des Gefängnisses zu sichern, muss sich Nikova an fähige, unabhängige Abenteurer wenden, die bereit sind, die Zellen zu stürmen und ihre Rache zu vollstrecken.",al={"warum kümmert sich die stadtwache nicht darum","warum ich the color of blood","warum braucht nikova mich"}}},fp="18,208,24.343.0,18.298.0,19.309.0,21.139.0,57.155.0,51.126.0,23.152.0,38.181.0,33.127.0"}
P.entries["quest:389"] = {n="Bazil Thredd",s="Unter Sturmwind weiß ein Defias-Gefangener womöglich, was die Bruderschaft noch vorhat. Nachdem ein nie abgeschickter Brief in den Todesminen gefunden wurde, schickt Euch Stadtarchitekt Baros Alexston ins Verlies, um Antworten zu finden.",h="Unter Sturmwind weiß ein Defias-Gefangener womöglich, was die Bruderschaft noch vorhat.",kw={"baros alexston","bazil thredd","defias","edwin van cleef","steinmetzgilde","sturmwind","das verlies","nie abgeschickter brief","aufseher thelwasser"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass Thredd für den abgebrühten, organisierten Unterweltzweig der Defias steht. Dessen Mitglieder tauschten Bauhämmer gegen improvisierte Messer und Straßengewalt.",["faction:Alliance"]="Als Held der Allianz steht Ihr einer Bedrohung durch die Defias gegenüber, die durch die ungesicherten Zellen des Verlieses bis in die Hauptstadt reicht, obwohl Edwin van Cleef erschlagen wurde.",["race:Human"]="Als Mensch seht Ihr, dass der Aufstand der Steinmetzgilde den tiefen politischen Graben zwischen Sturmwinds herrschendem Adel und den einfachen Leuten offenlegte, die die Stadt eigenhändig erbauten."},sec={{t="Eine bittere Vergangenheit",b="Baros Alexston und Edwin van Cleef führten einst die Steinmetzgilde an. Die Steinmetze bauten Sturmwind nach dem Ersten und Zweiten Krieg wieder auf. Doch als die weißen Mauern und Türme vollendet waren, weigerte sich der Adel, die versprochenen Löhne zu zahlen. Einige hochrangige Steinmetze erhielten Regierungsposten, um sie ruhigzustellen. Van Cleef wollte die einfachen Arbeiter nicht im Stich lassen. Er führte einen gewaltsamen Aufstand aus der Stadt hinaus an und gründete die Bruderschaft der Defias."},{t="Der Weg ins Verlies",b="Baros Alexston schickt Euch zu Bazil Thredd, um zu erfahren, was die Bruderschaft weiterhin gegen Sturmwind plant. Thredd war van Cleefs oberster Leutnant während des Aufstands der Steinmetze. Sturmwind nahm ihn gefangen und sperrte ihn im Gefängnis unter den Kanälen des Magierviertels ein. An den Toren warnt Aufseher Thelwasser, dass die Insassen rebelliert haben. Das Verlies ist ein Kriegsgebiet."}},faq={{q="Wer ist Bazil Thredd?",a="Bazil Thredd war Edwin van Cleefs oberster Leutnant in der Steinmetzgilde und während des frühen Aufstands der Defias. Sturmwind nahm ihn gefangen und sperrte ihn tief im Verlies ein.",al={"bazil thredd geschichte","wer ist thredd","thredd vorgeschichte"}},{q="Warum schickt Baros Alexston Euch zu Thredd?",a="Nachdem Baros Alexston den nie abgeschickten Brief aus den Todesminen untersucht hat, erkennt er eine Bedrohung für Sturmwind, die über die Todesminen hinausreicht. Er glaubt, dass Thredd als van Cleefs ehemalige rechte Hand die inneren Abläufe und verbliebenen Pläne der Bruderschaft besser kennt als jeder andere.",al={"warum mit thredd sprechen","baros alexston beweggrund","warum ins verlies gehen"}},{q="Warum wurde die Steinmetzgilde verraten?",a="Nachdem die Steinmetze Sturmwind nach dem Zweiten Krieg wieder aufgebaut hatten, weigerte sich das House of Nobles, seine finanziellen Vereinbarungen einzuhalten. Die Arbeiter erhielten keinen Lohn und blieben mittellos zurück. Van Cleef lehnte heimliche Bestechungsgelder ab und führte einen Aufstand aus den Stadttoren hinaus an.",al={"warum wurden die steinmetze nicht bezahlt","defias beweggrund","grund für den aufstand der steinmetze"}},{q="Wo liegt das Verlies?",a="Der Eingang zum Verlies liegt an den Kanälen im nordöstlichen Magierviertel von Sturmwind. Aufseher Thelwasser steht gleich hinter dem Eingang und versucht, fliehende Gefangene aufzuhalten.",al={"wo ist das verlies","verlies eingang","wie aufseher thelwasser finden"}},{q="Was geschieht im Verlies, wenn Ihr eintrefft?",a="Als Ihr eintrefft, haben Bazil Thredd und die anderen Insassen die Wachen überwältigt, die Gefängniszellen aufgeschlossen und die unteren Hallen eingenommen. Aufseher Thelwasser kämpft darum, den Aufstand daran zu hindern, auf die Straßen von Sturmwind überzugreifen.",al={"warum ist thelwasser wütend","krise im verlies","was ist im verlies geschehen"}},{q="Wie vermied Baros Alexston den Beitritt zu den Defias?",a="Van Cleef entschied sich für den bewaffneten Aufstand, während Baros Alexston zu den hochrangigen Handwerkern der Gilde gehörte, die eine Anstellung bei der Regierung annahmen. Alexston wurde schließlich Stadtarchitekt.",al={"ist baros ein defias","baros alexston steinmetz"}}},fx={["6cadb033"]={q="Warum bittet Euch Baros Alexston anstelle der Stadtwache um Hilfe?",a="Baros Alexston bekleidet das offizielle Amt des Stadtarchitekten von Sturmwind, doch das Geheimnis hinter The Unsent Letter und den Machenschaften von Edwin van Cleef ist heikel und persönlicher Natur. Die reguläre Stadtwache einzubeziehen, könnte unter den Adligen Panik auslösen oder Defias-Infiltratoren innerhalb der Stadt alarmieren. Da Ihr ihm den Brief gebracht habt und außerhalb der verstrickten Bürokratie der Stadt agiert, seid Ihr in der besten Position, um Van Cleefs inhaftierten Leutnant unauffällig zu verhören.",al={"warum ich bazil thredd","warum einen abenteurer ins das verlies schicken","warum braucht mich baros"}}},fp="12,200,16.429.0,22.357.1,20.174.0,54.254.0,39.242.0,30.162.0,54.220.0,48.168.0"}
P.entries["quest:39"] = {n="Zustellung von Thomas' Bericht",s="Im Osten Elwynns meldet Wache Thomas zwei tote Wachen und wachsende Gefahr. Er bittet Euch, den Bericht zu Marschall Dughan nach Goldhain zu bringen, wo nur wenige Kräfte zur Verteidigung der Straßen bleiben.",h="Im Osten Elwynns meldet Wache Thomas zwei tote Wachen und wachsende Gefahr.",kw={"wald von elwynn","goldhain","wache thomas","malakai","marschall dughan","murlocs","bericht","rolf"},ang={["class:Warrior"]="Als Krieger im Dienst des Reiches seht Ihr am Tod von Malakai und Rolf den Preis des Grenzdienstes: Sie wurden von unerbittlichen Feinden getötet.",["faction:Alliance"]="Thomas' Bericht zu überbringen zeigt, wie verwundbar das zentrale Königreich der Allianz geworden ist. Selbst die Straßen vor der Hauptstadt entgleiten der Kontrolle der Garnison.",["race:Human"]="Als Mensch spürt Ihr diese Verluste in Eurer Heimat, wo zu wenige Verteidiger immer mehr feindlichen Vorstößen gegenüberstehen."},sec={{t="Schlechte Nachrichten aus dem Osten",b="Wache Thomas bewacht die Brücken ins östliche Elwynn, wo der Flussverkehr auf die Wildnis trifft. Aggressive Murlocstämme haben die Wachen Malakai und Rolf getötet. Thomas hat zu wenige Wachen übrig, um sie einzudämmen, also schickt er Euch mit einem dringenden Bericht die Straße entlang nach Goldhain."},{t="Eine Garnison am Limit",b="Marschall Dughan erhält Thomas' Bericht in Goldhain, wo er bereits Mühe hat, die Straßen weiter patrouillieren zu lassen. Kobolde haben die Gegend befallen, Defias-Banditen bedrohen Reisende, und Sturmwind hat keine Verstärkung geschickt. Der Tod zweier erfahrener Wachen vergrößert seine Bürde. Murlocs könnten bald Goldhain selbst bedrohen, während die Verteidigung der Region immer weiter ausgedünnt wird."}},faq={{q="Wer sind Malakai und Rolf?",a="Malakai und Rolf waren Wachen aus Sturmwind, die unter Wache Thomas im östlichen Elwynn stationiert waren. Murlocstämme überwältigten und töteten sie, als sie nahe den Flüssen und Seen patrouillierten.",al={"malakai und rolf","wer ist gestorben","tote wachen"}},{q="Warum bittet Wache Thomas einen Abenteurer, den Bericht zu überbringen?",a="Wache Thomas hat zu wenige Truppen, um jemanden entbehren zu können. Wenn er seinen Posten verlässt oder einen seiner wenigen überlebenden Wachposten schickt, bleiben die östlichen Brücken unverteidigt.",al={"warum wache thomas hilfe braucht","warum ein bote","kann thomas keine wache schicken"}},{q="Welche Gefahr stellen die Murlocs für Goldhain dar?",a="Murlocstämme entlang der östlichen Flüsse breiten sich nach Westen aus. Marschall Dughan fürchtet, dass sie noch diese Woche die Außenbezirke Goldhains erreichen könnten, und er hat zu wenige Wachen, um die Verteidigungslinie zu halten.",al={"bedrohung durch murlocs","werden murlocs goldhain angreifen","wie gefährlich sind murlocs"}},{q="Warum schickt Sturmwind keine Verstärkung nach Elwynn?",a="Sturmwinds militärische Mittel sind auf mehrere Fronten verteilt. Das Verschwinden von König Varian Wrynn hat die Hauptstadt politisch gelähmt, sodass abgelegene Siedlungen und Grenzbrücken weitgehend den örtlichen Stadtwachen und angeheuerten Abenteurern überlassen bleiben.",al={"warum keine armee aus sturmwind","wo sind die truppen","warum ist die verteidigung so schwach"}},{q="Was geschieht, nachdem Marschall Dughan den Bericht gelesen hat?",a="Marschall Dughan weiß, dass seiner Garnison die Stärke fehlt, um die Murlocs direkt aufzuhalten. Er kümmert sich darum, Vorräte und Rüstungen für jene zu beschaffen, die bereit sind, die Stellung zu halten.",al={"nächste quest","was macht dughan","questreihe nach dem bericht"}},{q="Wo ist Wache Thomas stationiert?",a="Wache Thomas ist im östlichen Wald von Elwynn stationiert und bewacht Brücken über die Flüsse zwischen dem Herzen des Waldes und den wilderen Grenzgebieten nahe dem Rotkammgebirge.",al={"standort von wache thomas","wo ist thomas","standort von thomas"}}},fx={a496bd3c={q="Warum möchte Wache Thomas, dass sein Bericht an Marschall Dughan überbracht wird?",a="Wache Thomas kann die Murlocs, die sich im östlichen Wald von Elwynn ausbreiten, mit der Handvoll Männer an den Flussbrücken nicht aufhalten. Nachdem er gerade den Tod seiner Wachmänner Rolf und Malakai bestätigt hat, muss er dringend erreichen, dass Marschall Dughan versteht, dass die Ostgrenze zusammenbricht. Ohne Verstärkung oder Hilfe aus Goldhain werden die Murloc-Einfälle ungehindert in das Herz des Waldes vordringen.",al={"warum bericht überbringen","wache thomas bericht motiv","warum an dughan berichten"}}},fp="22,188,25.271.0,33.363.0,25.173.0,63.150.0,45.182.0,57.252.0,51.158.0,32.168.0"}
P.entries["quest:3901"] = {n="Klappernde Skelette",s="In Todesend stellen sich neu erwachte Verlassene den Klapperkäfigskeletten und einer Prüfung ihrer Freiheit. Schattenpriester Sarvis schickt sie aus, zwölf Skelette zu vernichten und zu beweisen, dass sie das Errungene verteidigen können.",h="In Todesend stellen sich neu erwachte Verlassene den Klapperkäfigskeletten und einer Prüfung ihrer Freiheit.",kw={"todesend","verlassene","klapperkäfig","sarvis","geißel","skelette","tirisfal","untoter"},ang={["class:Priest"]="Als neu auferstandener Priester erhaltet Ihr durch die Arbeit für Schattenpriester Sarvis einen frühen Einblick in den rücksichtslosen Pragmatismus, der den spirituellen Weg der Verlassenen prägt.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, neue Soldaten der Verlassenen zu Kämpfern zu formen, die ihre junge Fraktion verteidigen und Tirisfal sichern können.",["race:Undead"]="Als Verlassener zeigen Euch die Klapperkäfige, was Euch erwartet, wenn Euer Verstand nachlässt. Ihre geistlose Knechtschaft steht Eurer hart errungenen Selbstbestimmung gegenüber."},sec={{t="Eine Prüfung der Entschlossenheit",b="Nachdem sie die geistlosen Zombies in Todesend dezimiert haben, stehen neu auferstandene Verlassene vor einer härteren Prüfung. Schattenpriester Sarvis schickt Rekruten gegen die Klapperkäfigskelette, die am Rand der Siedlung umherstreifen. Die belebten Knochen besitzen weder Verstand noch Selbstbeherrschung, doch sie schlagen härter zu und kämpfen erbitterter als die verwesenden Leichen in der Nähe. Ihre klappernden Hinterhalte zu überleben zeigt Sarvis, dass ein Rekrut unmittelbarem Druck standhalten kann."},{t="Die neu gewonnene Freiheit verteidigen",b="Die Vernichtung der Skelette schützt Todesend vor dem anhaltenden Griff des Lichkönigs und prüft, welche Rekruten im Kampf bestehen können. Wer versagt oder zögert, läuft Gefahr, wie die geistlosen Elenden zu werden, die durch die Wälder irren. Der Sieg über die Klapperkäfige beweist Sarvis, dass Ihr die nötige Stärke besitzt, um einer Welt zu trotzen, die Eure Existenz verabscheut."}},faq={{q="Was sind Klapperkäfigskelette?",a="Klapperkäfigskelette sind geistlose Untote, die noch immer unter der Kontrolle des Lichkönigs stehen. Ohne Fleisch und bewussten Willen streifen sie am Rand von Todesend umher und greifen jeden an, der ihren Weg kreuzt.",al={"klapperkäfige","was sind klapperkäfigskelette","wer sind die skelette"}},{q="Warum will Schattenpriester Sarvis die Skelette vernichten lassen?",a="Sarvis prüft die Kampffertigkeit und Willenskraft neu erwachter Verlassener unter Druck. Die aggressiven Skelette zu dezimieren hilft auch dabei, Todesend davor zu bewahren, von der Geißel überrannt zu werden.",al={"warum skelette töten","sarvis absicht","grund für klappernde skelette"}},{q="Wo sind die Klapperkäfigskelette zu finden?",a="Klapperkäfigskelette streifen an den nördlichen und nordöstlichen Grenzen des Tals von Todesend umher, gleich hinter dem Dorf, in dem geistlose Zombies wandern.",al={"klapperkäfig fundort","wo klapperkäfigskelette finden","skelett spawnpunkte todesend"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Sarvis betrachtet Eure erste Ausbildung als abgeschlossen und erklärt, dass Ihr Euch Eurer Freiheit würdig erwiesen habt. Er schickt Euch zu anderen Anführern in Todesend, um die umfassenderen Unternehmungen der Verlassenen zu unterstützen.",al={"nächste quest nach klappernde skelette","was danach tun","sarvis nächster schritt"}},{q="Warum sind manche Untote frei, während diese Skelette geistlos bleiben?",a="Als die telepathische Kontrolle des Lichkönigs nach dem Dritten Krieg ins Wanken geriet, befreiten sich einige Untote, erlangten ihr Bewusstsein zurück und bildeten die Verlassenen. Konstrukte und einfache belebte Knochen wie die Klapperkäfige bewahrten weder Persönlichkeit noch Willen, weshalb sie an die Geißel gebunden blieben.",al={"warum sind skelette geistlos","verlassene gegen geißel freier wille","wie sind verlassene erwacht"}},{q="Wer ist Schattenpriester Sarvis?",a="Schattenpriester Sarvis beaufsichtigt die Verlassenen in der Kapelle von Todesend. Er beurteilt neu erweckte Untote, begleitet sie durch ihr Erwachen und stellt sicher, dass sie stark genug sind, um als freie Wesen zu überleben.",al={"wer ist sarvis","sarvis hintergrundgeschichte","schattenpriester sarvis rolle"}}},fx={["421a2867"]={q="Warum schickt Euch Schattenpriester Sarvis anstelle der Wachen von Todesend?",a="Sarvis testet Euren Mut und Eure Eignung, um Lady Sylvanas zu dienen. Die etablierten Beschützer von Todesend sind bereits damit beschäftigt, die Grenzen der Siedlung gegen die unaufhaltsame Geißel zu bewachen. Als ein neu erweckter Verlassener müsst Ihr beweisen, dass Ihr über den Fokus und die kriegerische Entschlossenheit verfügt, mit gefährlichen Feinden umzugehen, bevor Euch erlaubt wird, Euch in das weitere Königreich zu wagen.",al={"warum ich sarvis","warum nicht die wachen nutzen","warum testet sarvis euch"}}},fp="24,198,17.420.0,27.331.0,30.180.0,59.183.0,41.144.0,41.188.0,63.274.0,28.204.0"}
P.entries["quest:3902"] = {n="Beutesuche in Todesend",s="In Todesend sammeln frisch erwachte Verlassene Vorräte für Rekruten, die aus nahen Gräbern steigen. Todeswache Saltain schickt sie durch die verseuchte Siedlung, um verlassene Kisten und Kästen nach allem zu durchsuchen, was sie zum Überleben brauchen.",h="In Todesend sammeln frisch erwachte Verlassene Vorräte für Rekruten, die aus nahen Gräbern steigen.",kw={"todeswache saltain","todesend","vorräte der verlassenen","aufgestöberte waren","beutesuche in todesend","tirisfal","anfangsquest der untoten"},ang={["faction:Horde"]="Die Verlassenen sind mit der Horde jenseits des Meeres verbündet. Doch Außenposten wie Todesend müssen ihren täglichen Bedarf durch verzweifelte Beutesuche vor Ort decken statt durch Hilfe aus der Ferne.",["race:Undead"]="Als Untoter lernt Ihr die harten Bedingungen Eures neuen Lebens kennen. Niemand in Azeroth gewährt Mitleid oder Almosen, also müssen die Verlassenen ihre Zukunft aus dem Dreck bergen."},sec={{t="Eine pragmatische Auferstehung",b="Frisch erweckte Verlassene erwachen in Todesend und besitzen kaum etwas. Todeswache Saltain schickt sie los, um Kleidung und Waffen für Rekruten zu sammeln, die noch aus ihren Gräbern steigen. Jedes brauchbare Stück hilft, die frisch Erstandenen auszurüsten."},{t="Überleben in Tirisfal",b="In Todesend finden sich Hinterlassenschaften der einstigen menschlichen Bewohner und Vorräte, die beim Fall des Königreichs an die Geißel zurückgelassen wurden. Todeswachen schicken frisch erwachte Verlassene los, um Kisten und Kästen zu durchsuchen, die im ganzen Ort verstreut sind. Die Lebenden geben keine Almosen, also müssen die Verlassenen aus eigener Kraft überleben."}},faq={{q="Warum braucht Todeswache Saltain aufgestöberte Waren?",a="Todeswache Saltain sammelt Ausrüstung für frisch erwachte Verlassene, die auf dem nahen Friedhof aus ihren Gräbern steigen. Aufgestöberte Kleidung, Stiefel und Werkzeuge helfen zu verhindern, dass neue Rekruten unbewaffnet und wehrlos durch die verseuchten Hügel irren.",al={"warum waren aufstöbern","saltains aufgabe","warum nach kisten suchen"}},{q="Wo sind die aufgestöberten Waren zu finden?",a="Die Waren liegen in Stapeln von Kisten und Kästen in ganz Todesend, nahe verlassener Gebäude und in stillen Winkeln der Siedlung.",al={"wo sind kisten","fundorte aufgestöberter waren","kisten in todesend"}},{q="Wer ist Todeswache Saltain?",a="Saltain ist eine in Todesend stationierte Todeswache, die neue untote Rekruten beurteilt und ihnen Arbeit zuweist. Mit strenger Disziplin setzt er Ordnung und das zum Überleben Nötige durch.",al={"wer ist saltain","geschichte von todeswache saltain"}},{q="Warum haben die Verlassenen hier keine regulären Militärvorräte?",a="Die Verlassenen sind ein junges, bedrängtes Volk, dem feindselige Lebende und die gedankenkontrollierte Geißel gegenüberstehen. In Todesend sind die Vorräte knapp, also bergen sie, was in den Ruinen zurückblieb, und verwenden es erneut.",al={"warum keine ausrüstung","versorgungsmangel der verlassenen","ausrüstung in todesend"}},{q="Was geschieht nach Abschluss dieser Aufgabe?",a="Saltain gibt dem Rekruten ein geborgenes Rüstungsteil aus dem gemeinsamen Vorrat. Es kennzeichnet den Übergang des Rekruten von einer unbewährten Leiche zu einem einsatzfähigen Soldaten der Dark Lady.",al={"nächste quest","belohnung für die beutesuche"}},{q="Warum erheben sich gerade jetzt so viele neue Untote in Todesend?",a="Während der Griff des Lich King um seine Diener schwächer wird, befreien sich einige Tote Lordaerons und behalten dabei ihren Verstand. Verwirrt steigen sie aus ihren Gräbern und brauchen sofortige Anleitung.",al={"warum erheben sie sich","neue rekruten in todesend","warum neue untote"}}},fx={e568b68b={q="Wofür werden die aufgestöberten Waren verwendet?",a="Die aufgestöberten Waren sind geborgene Ausrüstung und Vorräte, die dazu bestimmt sind, die neu erweckten Rekruten der Verlassenen auszustatten, die in Todesend auferstehen. Da Vorräte knapp sind und es keine Hilfe von außen gibt, müssen die Verlassenen jegliche weggeworfene Ausrüstung bergen, die sie finden können, um sicherzustellen, dass neue Soldaten bekleidet und bewaffnet sind.",al={"wofür sind aufgestöberte waren","aufgestöberte waren nutzung","warum aufgestöberte waren sammeln"}},aa140ef7={q="Warum braucht Todeswache Saltain Rekruten zum Aufstöbern, anstatt es selbst zu tun?",a="Todeswache Saltain und die anderen erfahrenen Wachen haben die Aufgabe, den Umkreis von Todesend zu halten und den Zustrom neu auferstandener Untoter zu bewältigen. Das Aufstöbern in der zerstörten Siedlung ist eine Arbeit mit geringem Risiko, die sowohl als praktische Methode zur Beschaffung von Vorräten dient als auch als Test, ob neue Rekruten in der Lage sind, Befehle zu befolgen.",al={"warum braucht saltain mich","warum rekruten zum aufstöbern schicken","warum nicht todeswachen aufstöbern lassen"}}},fp="21,224,24.225.0,23.303.0,49.216.0,36.128.0,26.163.0,60.201.0,40.179.0,58.180.0"}
P.entries["quest:3903"] = {n="Milly Geltmark",s="Deputy Willem schickt Euch über das Gelände der Abtei von Nordhain, um seiner Freundin Milly Geltmark zu helfen. Ihr Wagen und ihr Lebensunterhalt sind in Gefahr, und Willems Wachen können das Abteigelände nicht verlassen, um zu helfen.",h="Deputy Willem schickt Euch über das Gelände der Abtei von Nordhain, um seiner Freundin Milly Geltmark zu...",kw={"deputy willem","wald von elwynn","ernte","milly geltmark","abtei von nordhain","ställe","wagen"},ang={["faction:Alliance"]="In Nordhain seht Ihr, wie die überlasteten Wachen der Allianz auf vorbeiziehende Abenteurer angewiesen sind, um die Einwohner vor aufkommenden Bedrohungen zu schützen.",["race:Human"]="Als junger Mensch in Nordhain könnt Ihr Willem helfen und den Gemeinschaftssinn zeigen, der Elwynn zusammenhält."},sec={{t="Ein verlässliches Paar Hände",b="Nachdem Ihr die ins Nordhaintal vordringenden Diebe der Defias zurückgedrängt habt, vertraut Deputy Willem Euch einen persönlichen Gefallen an. Seine Freundin Milly Geltmark ist eine Zivilistin, die in die Unruhen im Tal geraten ist, und ihr zu helfen liegt außerhalb seiner Wachpflichten."},{t="Ärger bei den Ställen",b="Milly wartet neben ihrem Wagen bei den Ställen auf der anderen Seite der Abtei von Nordhain. Deputy Willem bleibt auf seinem Posten, um die Abtei zu verteidigen. Da die Garnison der Wache überlastet ist, erhält Milly bei ihren Schwierigkeiten im Tal keine Hilfe."}},faq={{q="Wer schickt Euch zu Milly Geltmark?",a="Deputy Willem schickt Euch zu Milly, nachdem Ihr Euch im Kampf gegen die Banditen der Defias als zuverlässig erwiesen habt.",al={"wer vergibt milly geltmark","questgeber milly geltmark","wo beginnt die quest milly geltmark"}},{q="Wo ist Milly Geltmark zu finden?",a="Milly wartet neben ihrem Wagen auf der anderen Seite der Abtei von Nordhain, nahe den Ställen und den Weinbergen im Südosten.",al={"milly geltmark standort","wo ist milly","wo ist milly geltmark"}},{q="Warum kann Deputy Willem Milly nicht selbst helfen?",a="Willems Wachpflichten halten ihn an der Abtei von Nordhain. Banditen und Ungeziefer bedrängen das Tal, sodass der Garnison zu wenige Leute bleiben, um sich um private Sorgen der Zivilisten zu kümmern.",al={"warum hilft willem nicht","willems pflichten","warum milly helfen"}},{q="Welche Voraussetzungen gelten für diese Quest?",a="Ihr müsst Brotherhood of Thieves für Deputy Willem abschließen, bevor er Euch zutraut, Milly zu helfen.",al={"milly geltmark voraussetzungen","folgequest von brotherhood of thieves","wie wird die quest milly geltmark freigeschaltet"}},{q="Wobei braucht Milly Hilfe?",a="Milly hat inmitten der örtlichen Unruhen Schwierigkeiten mit ihrer Ernte und ihrem Wagen. Ihre Ernte muss vor Bedrohungen aus dem umliegenden Tal geschützt werden.",al={"was will milly","millys problem","millys erntesorgen"}},{q="In welchem Verhältnis steht Milly Geltmark zu Deputy Willem?",a="Willem bezeichnet Milly als eine Freundin in Not aus der Gemeinschaft von Nordhain. Er kümmert sich um sie, während er an seinen Posten gebunden ist.",al={"willem und milly","ist milly mit willem verwandt","woher kennt willem milly"}}},fx={c87a8d77={q="Warum möchte Deputy Willem Milly Osworth helfen?",a="Deputy Willem betrachtet Milly als eine liebe persönliche Freundin und weiß, dass sie in der Nähe der Ställe in Schwierigkeiten geraten ist. Obwohl ihm ihr Wohlergehen sehr am Herzen liegt, hält ihn sein offizieller Posten als Deputy an die Abtei von Nordhain gebunden. Einen fähigen, vertrauenswürdigen Abenteurer wie Euch zu schicken, ist sein bester Weg, um sicherzustellen, dass sie den Schutz und die Hilfe bekommt, die sie dringend benötigt.",al={"warum milly osworth helfen","willem motiv milly","warum kümmert sich deputy willem"}}},fp="13,181,26.237.0,22.223.0,42.85.0,33.118.0,43.154.0,45.97.0,31.125.0,38.112.0"}
P.entries["quest:3904"] = {n="Millys Ernte",s="Briganten der Defias haben Milly Osworth aus den Weinbergen von Nordhain vertrieben. Ihre gesammelten Trauben stehen noch in Eimern und Kisten zwischen den besetzten Rebzeilen und drohen gestohlen zu werden oder zu verderben.",h="Briganten der Defias haben Milly Osworth aus den Weinbergen von Nordhain vertrieben.",kw={"kisten","defias","wald von elwynn","trauben","milly osworth","millys ernte","abtei von nordhain","weinberge von nordhain"},ang={["faction:Alliance"]="Die Bergung von Millys Ernte gibt jungen Rekruten der Allianz einen ersten Einblick in die Bedrohung durch die Defias, nur wenige Meilen von Sturmwind entfernt.",["race:Human"]="Wenn Ihr als Mensch Eure Reise in Nordhain beginnt, gehört der Schutz von Kleinbauern wie Milly zur Verteidigung der arbeitenden Bevölkerung Elwynns."},sec={{t="Eine zurückgelassene Ernte",b="Milly Osworth floh von den südöstlichen Feldern des Nordhaintals, als Briganten der Defias die Weinberge überrannten. Die Trauben, die sie gesammelt hatte, stehen noch in Eimern und Kisten zwischen den besetzten Rebzeilen. Die Garnison von Nordhain ist überlastet, und Milly fürchtet, dass Stiefel und Kämpfe alle Früchte zerquetschen werden, die die Banditen zurücklassen."},{t="Nordhain unter Druck",b="Banditen der Defias besetzen nun bewirtschaftete Weinberge, ein Zeichen dafür, wie wenig Sicherheit Nordhain bieten kann. Sturmwinds Aufmerksamkeit gilt anderen Orten, und das Tal hat zu wenige Wachen. Deshalb sind Bauern wie Milly auf Rekruten und Wanderer angewiesen, um ihren Besitz zu schützen und die Lebensmittel und den Wein für die Abtei zu sichern."}},faq={{q="Wer ist Milly Osworth?",a="Milly Osworth bewirtschaftet die Weinberge von Nordhain. Sie pflegt und erntet die Trauben des Tals, doch die anrückende Bruderschaft der Defias vertrieb sie von ihren Feldern.",al={"milly osworth","wer ist milly","traubenfrau"}},{q="Warum können die Wachen von Nordhain die Ernte nicht bergen?",a="Die Wachen des Nordhaintals sind zu wenige und mit der weitverbreiteten Bedrohung durch Banditen und dem Koboldbefall beschäftigt. Milly fürchtet außerdem, dass ein militärischer Vorstoß ihre Trauben in den Schlamm treten könnte.",al={"warum helfen die wachen nicht","wachen von nordhain","faule wachen"}},{q="Was machen die Defias in den Weinbergen?",a="Die Bruderschaft der Defias drang ins Nordhaintal ein, um die regionale Produktion zu stören, die Einheimischen zu drangsalieren und Ressourcen direkt unter den Augen von Sturmwinds Wachen zu beschlagnahmen.",al={"warum defias in den weinbergen","defias trauben","defias nordhain"}},{q="Wo befinden sich die Kisten?",a="Die Eimer und Kisten mit der Ernte stehen in den Weinbergen von Nordhain verstreut auf dem Boden, gleich südöstlich der Abtei von Nordhain, zwischen Briganten der Defias, die durch die Rebzeilen patrouillieren.",al={"standorte der kisten","wo trauben finden","wo ist die ernte"}},{q="Was geschieht, nachdem Milly ihre Trauben zurückbekommen hat?",a="Sobald ihre Ernte in Sicherheit ist, bittet Milly Euch, ihre Traubenliste zu Bruder Neals in der Abtei von Nordhain zu bringen. Dann kann der Ertrag erfasst und zu Wein verarbeitet werden.",al={"nächste quest","nach millys ernte","was kommt als nächstes"}},{q="Warum sind Trauben für die Abtei von Nordhain wichtig?",a="Das Nordhaintal erzeugt berühmten Wein und versorgt die geistliche Gemeinschaft in der Abtei. Millys Ernte sichert den örtlichen Handel und füllt die Weinkeller, die von der Brotherhood of Northshire unterhalten werden.",al={"wein aus nordhain","warum trauben wichtig sind"}}},fx={["23083d02"]={q="Warum muss Milly Osworth, dass Ihr ihre Ernte zurückholt?",a="Milly war gerade dabei, Trauben zu pflücken, als die Defias-Bande die Weinberge überrannte. Sie fürchtet, dass die Wachen der Abtei im Chaos des Kampfes unweigerlich die Kisten zertrampeln werden, falls die Diebe nicht mit den Früchten entkommen. Ihre Lebensgrundlage hängt davon ab, diese Eimer zu bergen, bevor sie ruiniert sind.",al={"warum braucht milly die ernte","warum trauben retten","milly osworth motiv"}}},fp="15,172,18.308.0,25.300.0,21.152.0,53.183.0,43.154.0,29.170.0,46.171.1,45.183.0"}
P.entries["quest:3905"] = {n="Traubenliste",s="Milly Osworth braucht Euch, um ihre Liste zu Bruder Neals in der Abtei von Nordhain zu bringen. Sie hilft der Bruderschaft, ihre Weinvorräte aufzufüllen.",h="Milly Osworth braucht Euch, um ihre Liste zu Bruder Neals in der Abtei von Nordhain zu bringen.",kw={"bruder neals","defias","elwynn","traubenliste","ernte","milly osworth","abtei von nordhain","weinberg","wein"},ang={["class:Priest"]="Als Priester wisst Ihr, dass Wein in der Abtei von Nordhain zur Gastfreundschaft und zu heiligen Riten gehört, wo die Landwirtschaft den Gottesdienst der Bruderschaft trägt.",["faction:Alliance"]="Die Sicherung von Nordhains Lebensmittelvorräten hilft Sturmwinds wichtigstem Ort für Rekrutierung und Erholung, sich weiterhin selbst zu versorgen.",["race:Human"]="Als Mensch am Anfang Eurer Reise schützt Ihr mit Eurer Hilfe für Milly und Bruder Neals eine der geschätzten ländlichen Traditionen des Königreichs."},sec={{t="Der Wein des Tals",b="Diebe der Defias und andere Räuber besetzten die östlichen Felder. Die Abtei verlor ihre Lebensmittel und ihre Trauben. Milly hat die Ernte zurückgeholt und jeden Scheffel in ihrer Liste erfasst, auch den Ertrag der besetzten Felder."},{t="Ein Schluck im Glockenturm",b="Bruder Neals ist in der Abtei von Nordhain für Speis und Trank zuständig. Er ist dafür bekannt, in der Stille des Glockenturms Nordhains Weine zu verkosten. Noch immer bedrohen Räuber die Tore, doch frische Trauben geben der Bruderschaft einen Moment, um auf das Licht anzustoßen und Mut zu schöpfen."}},faq={{q="Was ist die Traubenliste?",a="Milly Osworth erfasst in der Traubenliste ihre Ernte, die sie von den Dieben der Defias zurückerlangt hat. Das Verzeichnis hilft dem Proviantmeister der Abtei, ihre Keller wieder aufzufüllen.",al={"traubenliste gegenstand","was ist die liste","millys liste"}},{q="Wer ist Bruder Neals?",a="Bruder Neals ist ein Mönch in der Abtei von Nordhain und für Speis und Trank zuständig. Er verkostet die Weine oft im Glockenturm.",al={"bruder neals","wer ist neals","mönch im glockenturm"}},{q="Wo finde ich Bruder Neals?",a="Bruder Neals befindet sich in der Abtei von Nordhain, im Glockenturm mit Blick über das Gelände.",al={"neals aufenthaltsort","wo ist bruder neals","bruder neals finden"}},{q="Warum ist Nordhains Traubenernte so wichtig?",a="Nordhains Trauben liefern berühmten Wein und frische Nahrung für die örtlichen Geistlichen und Soldaten. Eine verlorene Ernte gefährdet die täglichen Vorräte und den Messwein der Abtei in ganz Elwynn.",al={"warum trauben wichtig sind","nordhains weingeschichte","millys ernte bedeutung"}},{q="Wer bedrohte Millys Ernte?",a="Räuber der Defias besetzten die östlichen Felder des Nordhaintals, vertrieben Milly Osworth und versteckten ihre in Kisten verpackte Ernte überall in den Weinbergen. Abenteurer drängten sie zurück.",al={"wer stahl die trauben","traubendiebe","banditen in den weinbergen"}},{q="Was geschieht, nachdem Bruder Neals die Liste erhalten hat?",a="Bruder Neals spendet seinen Segen im Namen des Lichts. Er ist überglücklich, dass die Keller der Abtei trotz der Banditenplage im ganzen Tal frischen Wein erhalten werden.",al={"folgen der quest","stellt neals wein her","was folgt auf die traubenliste"}}},fx={["7b371529"]={q="Warum möchte Milly Osworth, dass dies erledigt wird?",a="Nachdem ihre Ernte endlich vor den Defias-Banditen gerettet wurde, die ihre Weinberge überrannten, muss Milly die Abtei von Nordhain wissen lassen, dass frische Vorräte überlebt haben. Bruder Neals beaufsichtigt alle Lebensmittel und Getränke für das Tal, und diese Liste dokumentiert offiziell, dass ihre Trauben für die Weinkeller der Abtei bereit sind.",al={"milly osworth traubenliste motiv","warum traubenliste senden","warum muss milly das geliefert haben"}}},fp="14,139,20.218.0,22.252.0,27.150.0,21.125.0,30.84.0,44.179.0,36.166.0,53.168.0"}
P.entries["quest:391"] = {n="Aufstand im Verlies",s="An Sturmwinds Gefängnistoren schickt Euch Aufseher Thelwasser in den Aufstand im Verlies, um Eure Treue gegenüber den Stadtwachen zu beweisen. Der Aufstand hat das Gefängnis erfasst, und er befiehlt Euch, dessen Rädelsführer Bazil Thredd zu finden und hinzurichten.",h="An Sturmwinds Gefängnistoren schickt Euch Aufseher Thelwasser in den Aufstand im Verlies, um Eure Treue...",kw={"bazil thredd","defias","hamhock","aufstand im verlies","sturmwind","das verlies","aufseher thelwasser"},ang={["class:Rogue"]="Als Schurke könnt Ihr sehen, wie weit das geheime Untergrundnetzwerk der Bruderschaft der Defias gehen kann, wenn es jede Zurückhaltung verliert.",["faction:Alliance"]="Eine umfassende Revolte unter dem Magierviertel bedroht Sturmwinds Stabilität, während der König weiterhin vermisst wird und die Kräfte des Königreichs kaum ausreichen.",["race:Human"]="Als Mensch wisst Ihr, dass viele Aufständische Agenten der Defias und verbitterte Steinmetze sind, die sich nach dem Streit um den Wiederaufbau gegen ihr Königreich wandten."},sec={{t="Blut auf dem Stein",b="Unter dem Kopfsteinpflaster des Magierviertels ist das Verlies der Gesetzlosigkeit verfallen. Verbrecher, Aufständische der Defias und gewalttätige Halsabschneider sind ausgebrochen und haben die Zellentrakte eingenommen. Das Gefängnis ist nun ein undurchdringliches Kriegsgebiet. Aufseher Thelwasser und seine Wachen halten verzweifelt den Eingang, unfähig, ins Innere vorzudringen und mit gewöhnlichen Mitteln die Ordnung wiederherzustellen."},{t="Der Preis des Vertrauens",b="Aufseher Thelwasser misstraut jedem, der sich nach Bazil Thredd erkundigt. Er verlangt einen Beweis Eurer Treue und befiehlt Euch, durch die aufständischen Zellentrakte vorzudringen und Thredd in seiner Zelle zu töten. Dann sollt Ihr mit dem abgetrennten Kopf des Rebellenführers zurückkehren. Nur indem ein Außenstehender die Galionsfigur des Aufstands tötet, kann er beweisen, dass er nicht heimlich mit der Rebellion verbündet ist."},{t="Ein durchtrennter Faden",b="Bazil Thredd führt den Aufstand an, und sein Tod versetzt dessen Organisation einen entscheidenden Schlag. Er bringt auch alle direkten Antworten zum Schweigen, die Thredd über die Verschwörung hätte geben können, die Sturmwind im Griff hat.\n\nAls Aufseher Thelwasser Thredds Kopf sieht, ist er überrascht und räumt ein, dass das Gefängnis wieder beherrschbar werden könnte. Er gibt auch Hinweise auf Thredds geheime Kontakte vor dem Aufstand."}},faq={{q="Wer vergibt die Quest Aufstand im Verlies?",a="Aufseher Thelwasser vergibt sie gleich im Eingangstunnel des Verlieses in Sturmwinds Magierviertel.",al={"wer vergibt aufstand im verlies","aufstand im verlies questgeber","wo aufstand im verlies beginnen"}},{q="Was muss ich tun, um die Quest abzuschließen?",a="Betretet das Gefängnis, findet den Rädelsführer Bazil Thredd im östlichen Zellentrakt, tötet ihn und bringt seinen abgetrennten Kopf zu Aufseher Thelwasser zurück.",al={"aufstand im verlies questziel","wie aufstand im verlies abschließen"}},{q="Wo befindet sich Bazil Thredd im Verlies?",a="Folgt vom Eingang aus dem nördlichen Gang bis zur T-Kreuzung und nehmt dann den östlichen Zellentrakt. Bazil Thredd befindet sich in der mittleren Zelle eines Bereichs aus drei Räumen, der vom Oger Hamhock bewacht wird.",al={"wo ist thredd","bazil thredd fundort","wie thredd finden"}},{q="Warum will Aufseher Thelwasser Bazil Thredd tot sehen?",a="Bazil Thredd ist der oberste Rädelsführer des Aufstands. Aufseher Thelwasser glaubt, dass die Wachen nur durch seinen Tod die Kontrolle über die aufständischen Zellentrakte zurückerlangen können. Damit wird auch geprüft, ob Ihr heimlich mit den Rebellen zusammenarbeitet.",al={"warum thredd töten","warum thelwasser thredd tot sehen will"}},{q="Was geschieht nach Abschluss von Aufstand im Verlies?",a="Nachdem Ihr Thredds Kopf zurückgebracht habt, schickt Euch Aufseher Thelwasser los, um einer geheimnisvollen Gestalt nachzugehen, die das Gefängnis vor dem Aufstand besucht hat. Der nächste Abschnitt heißt The Curious Visitor.",al={"aufstand im verlies folgequest","was kommt nach aufstand im verlies"}},{q="Können Spieler der Horde diese Quest annehmen?",a="Nein. Das Verlies liegt tief in Sturmwind, der Hauptstadt der Allianz, weshalb Spieler der Horde diese Quest nicht annehmen können.",al={"aufstand im verlies nur für die allianz","horde aufstand im verlies"}}},fx={["324bbcda"]={q="Wozu dient der Kopf von Bazil Thredd?",a="Aufseher Thelwasser verlangt den abgetrennten Kopf von Bazil Thredd als absoluten Beweis für dessen Ableben und Eure Loyalität. Da er zutiefst misstrauisch gegenüber jedem ist, der eine Audienz mit dem Anführer des Aufstands sucht, macht Thelwasser deutlich, dass die Rückkehr mit Thredds Kopf die einzige Möglichkeit ist, das Gefängnis zu verlassen, ohne als Verräter gebrandmarkt und zusammen mit den rebellischen Sträflingen hingerichtet zu werden.",al={"nutzen kopf von bazil thredd","warum thredds kopf abtrennen","kopf von bazil thredd"}},["3413d34a"]={q="Wer ist Bazil Thredd und warum ist er im Verlies?",a="Bazil Thredd ist ein hochrangiges Mitglied der The Defias Brotherhood, das unter den Straßen von Sturmwind gefangen gehalten wird. Thredd hat innerhalb der Gefängnismauern Unruhen angezettelt und die Insassen zu einem offenen, bewaffneten Aufstand organisiert, wobei er die Kontrolle über Zellentrakte übernommen hat und die Einrichtung gegen die Wachen des Aufsehers als Geisel hält.",al={"wer ist bazil thredd","hintergrundgeschichte bazil thredd","warum ist thredd inhaftiert"}},["16764756"]={q="Warum schickt Aufseher Thelwasser Euch anstelle seiner eigenen Wachen?",a="Das Verlies ist von einem totalen Aufstand ergriffen, und die bedrängten Wachen des Aufsehers sind überlastet bei dem Versuch, den gewaltsamen Ausbruch am Eingang einzudämmen. Da Ihr eigens gekommen seid, um mit Thredd zu sprechen, bezweifelt Thelwasser Eure Loyalität; Euch in das Getümmel zu schicken, ist für die Garnison ohne Risiko und bietet gleichzeitig eine einfache Prüfung – entweder Ihr erledigt den Rädelsführer, um Eure Unschuld zu beweisen, oder Ihr sterbt zusammen mit den Aufrührern.",al={"warum in das verlies schicken","warum schickt thelwasser keine wachen","warum ich aufstände das verlies"}}},fp="18,225,18.356.0,18.348.1,16.377.1,39.97.0,43.132.0,50.192.0,49.229.0,49.183.1,36.103.0"}
P.entries["quest:392"] = {n="Der seltsame Besucher",s="Nach dem Aufstand im Verlies hat Aufseher Thelwasser eine beunruhigende Verbindung zu Bazil Thredd entdeckt. Monatelang vor dem Aufruhr besuchte ein Mann namens Maelik Thredd mit Papieren, die jeder Prüfung standhielten.",h="Nach dem Aufstand im Verlies hat Aufseher Thelwasser eine beunruhigende Verbindung zu Bazil Thredd entdeckt.",kw={"baros alexston","bazil thredd","seltsamer besucher","defias","maelik","verlies","steinmetze","aufseher thelwasser"},ang={["class:Rogue"]="Als Schurke erkennt Ihr, welches Geschick nötig ist, um mit ordnungsgemäßen Papieren jede Gefängniskontrolle zu bestehen.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, wie wichtig es ist, Bazil Thredds geheimnisvollen Kontakt zu finden, um Defias-Sympathisanten aus der Hauptstadt zu vertreiben.",["race:Human"]="Als Mensch erkennt Ihr, wie gefälschte oder genehmigte Zutrittspapiere tiefgreifende Schwächen und mögliche Korruption in der Regierung des Königreichs Sturmwind offenbaren."},sec={{t="Ein Verstoß gegen die Vorschriften",b="Nach dem Aufruhr erfuhr Aufseher Thelwasser, dass Bazil Thredds frühere Kameraden ihn nicht im Stich gelassen hatten. Monatelang traf sich ein stiller Besucher ein- oder zweimal pro Woche mit Thredd. Er bestand jede Kontrolle, führte autorisierte Papiere bei sich und gab seinen Namen als Maelik an. Thelwasser vermutet, dass diese Besuche halfen, den blutigen Aufstand zu koordinieren. Er schickt Euch mit einer Personenbeschreibung zu Stadtarchitekt Baros Alexston, in der Hoffnung, die Identität des Besuchers zu erfahren."},{t="Verbindungen zu den Steinmetzen",b="Vor ihrer Rebellion arbeitete Baros Alexston eng mit Edwin van Cleef und der Steinmetzgilde zusammen. Maeliks Name sagt ihm nichts, und die Beschreibung könnte auf unzählige ehemalige Handwerker zutreffen. Dennoch hatte der Besucher eine gültige Genehmigung, das Verlies zu betreten. Das deutet auf mehr hin als Verbrecher, die an Wachen vorbeischlüpfen: Sympathisanten und Agenten der Defias sind weiterhin tief in Sturmwinds städtischen Behörden verwurzelt."}},faq={{q="Wer ist der seltsame Besucher, der in der Quest erwähnt wird?",a="Der Besucher gab seinen Namen als Maelik an. Monatelang vor dem Aufruhr im Verlies besuchte er Bazil Thredd ein- oder zweimal pro Woche mit Papieren, die rechtmäßig erschienen.",al={"wer ist maelik","thredds besucher","identität des seltsamen besuchers"}},{q="Warum schickt Aufseher Thelwasser Euch zu Baros Alexston?",a="Aufseher Thelwasser schickt Euch zu Baros Alexston, Sturmwinds Stadtarchitekten, der einst mit Edwin van Cleef und der Steinmetzgilde zusammenarbeitete. Da die Defias ihren Ursprung unter den Steinmetzen hatten, hofft Thelwasser, dass Alexstons frühere Gildenverbindungen ihm helfen könnten, den Besucher zu erkennen.",al={"warum baros alexston","wer ist baros","bei baros abgeben"}},{q="Wie gelangte Maelik ins Verlies, ohne erwischt zu werden?",a="Maelik betrat das Verlies mit rechtmäßigen Papieren, die den Sicherheitskontrollen des Gefängnisses standhielten. Die Wachen hatten keinen rechtlichen Grund, ihm den Zutritt zu verweigern, was auf einen Verwaltungsfehler oder korrupte Beamte in der Verwaltung des Königreichs hindeutet.",al={"wie kam der besucher hinein","maeliks papiere","sicherheitsversagen im verlies"}},{q="Welche Rolle spielte Bazil Thredd bei den Gefängnisaufständen?",a="Bazil Thredd war ein im Verlies inhaftierter Anführer der Bruderschaft der Defias. Er organisierte und führte den gewaltsamen Aufstand der Gefangenen, den er wahrscheinlich durch Maeliks Besuche koordinierte.",al={"wer ist bazil thredd","was hat thredd getan"}},{q="Was geschieht, nachdem Baros Alexston die Beschreibung gelesen hat?",a="Baros Alexston kann weder mit dem Namen Maelik noch mit Thelwassers Beschreibung etwas anfangen. Er erklärt sich bereit, weiter zu ermitteln, da der Besucher Verbindungen in der Stadt haben muss.",al={"erkennt baros maelik","was passiert als nächstes"}},{q="Warum ist der Besucher für die Ermittlungen gegen die Defias wichtig?",a="Die regelmäßigen Besuche zeigen, dass der Aufruhr im Verlies ein geplanter Komplott der Defias war, kein spontaner Ausbruch gesetzloser Wut. Jemand mit Zugang zu Sturmwinds amtlichen Papieren auf höchster Ebene half dabei, ihn zu ermöglichen.",al={"verschwörung der defias","warum ist der besucher wichtig"}}},fx={["3d9e03e1"]={q="Warum möchte Aufseher Thelwasser, dass dies erledigt wird?",a="Bazil Thredd saß jahrelang ohne einen einzigen Besucher im Verlies, anscheinend verlassen von The Defias Brotherhood. Das änderte sich vor Monaten, als ein stiller Fremder, der sich Maelik nannte, begann, ihn regelmäßig mit gültigen Papieren zu besuchen. Jetzt, da Thredd einen gewaltsamen Gefängnisaufstand angezettelt hat, erkennt Thelwasser, dass diese Besuche Teil einer umfassenderen Verschwörung waren. Er muss den mysteriösen Besucher identifizieren, um aufzudecken, wer von außerhalb geholfen hat, den Aufstand zu organisieren.",al={"thelwasser motiv","warum besucherbeschreibung senden","warum interessiert sich thelwasser für maelik"}},["156adb5f"]={q="Warum schickt Aufseher Thelwasser Euch anstelle seiner eigenen Wachen?",a="Das Verlies wurde gerade von einem massiven Aufstand auseinandergenommen und die Garnison des Gefängnisses ist völlig überlastet, um die Folgen einzudämmen und die verbleibenden Zellen zu sichern. Da Maeliks Besuchspapiere zudem rechtmäßig genehmigt wurden, kann sich Thelwasser nicht sicher sein, wie tief die Korruption oder Nachlässigkeit in seinen eigenen Reihen reicht. Da Ihr Eure Loyalität und Fähigkeit bewiesen habt, indem Ihr Thredd niedergeschlagen habt, seid Ihr ein Außenseiter, dem er sicher vertrauen kann.",al={"warum mich schicken","warum keine wachen schicken","warum kann thelwasser keine wache schicken"}}},fp="19,188,20.425.0,23.390.1,50.156.0,53.272.0,55.231.0,52.189.0,56.167.0,64.206.0"}
P.entries["quest:3921"] = {n="Wenikee Kübelbolz",s="Nahe dem Mor'shan-Schutzwall braucht Stotterspritter Wenikee Kübelbolz, um ein zerbrochenes Samophlang zu reparieren. Er beschädigte es nach seiner Bergung aus dem Schlickermoor, und nun hängen seine Behauptungen gegenüber seinen Kollegen in Undermine von der Reparatur ab.",h="Nahe dem Mor'shan-Schutzwall braucht Stotterspritter Wenikee Kübelbolz, um ein zerbrochenes Samophlang zu...",kw={"zerbrochenes samophlang","der mor'shan-schutzwall","samophlange","das schlickermoor","stotterspritter","brachland","undermine","wenikee kübelbolz"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Wenikees Lager im Schatten des Mor'shan-Schutzwalls liegt, eines befestigten Engpasses, der Hordengebiet im nördlichen Brachland vor Einfällen aus Eschental schützt.",["profession:Engineering"]="Als Ingenieur könnt Ihr verstehen, warum das Samophlang solche Neugier weckt. Weder Stotterspritter noch Wenikee kennen seinen ursprünglichen Zweck, doch sein komplexes Räderwerk lädt zum Erforschen ein."},sec={{t="Ein empfindliches Missgeschick",b="Stotterspritters Behauptungen gegenüber seinen Ingenieurskollegen in Undermine hängen an einer kaputten Maschine. Ein Abenteurer barg das geheimnisvolle Samophlang aus der Steuerkonsole der Venture Company im Schlickermoor. Stotterspritter konnte nicht widerstehen, damit anzugeben, und seine Bastelei beschädigte die empfindliche Apparatur. Nun braucht er jemanden mit mehr technischem Geschick, um den Fehler zu finden und das Gerät zu reparieren."},{t="Die Tüftlerin am Schutzwall",b="Wenikee Kübelbolz lagert an der Straße direkt südlich des Mor'shan-Schutzwalls, der das nördliche Brachland von Eschental trennt. Ihr neugieriger Geist fühlt sich von komplizierten Maschinen angezogen, und das zerbrochene Samophlang erregt rasch ihre Aufmerksamkeit. Sein inneres Räderwerk fasziniert sie, also macht sie sich daran, herauszufinden, wie es wieder aufgebaut werden kann."}},faq={{q="Warum ist das Samophlang kaputt?",a="Stotterspritter beschädigte das Samophlang beim Untersuchen und Herumbasteln, nachdem es aus der Steuerkonsole im Schlickermoor geborgen worden war.",al={"warum kaputt","wie ging es kaputt","stotterspritter hat es beschädigt"}},{q="Wer ist Wenikee Kübelbolz?",a="Wenikee Kübelbolz ist eine erfinderische Goblintüftlerin, die direkt südlich des Mor'shan-Schutzwalls an der Grenze zwischen dem nördlichen Brachland und Eschental lagert. Sie versteht sich auf komplexe Maschinen.",al={"wer ist wenikee","kübelbolz standort","wo ist wenikee"}},{q="Warum liegt Stotterspritter so viel an der Reparatur?",a="Stotterspritter prahlte vor seinen Kollegen in Undermine damit, dass er das Gerät beschafft habe. Kann er kein funktionierendes Samophlang abliefern, leiden sein Ruf und sein berufliches Ansehen.",al={"warum samophlang reparieren","stotterspritter undermine","warum ist es ihm wichtig"}},{q="Weiß Wenikee, was ein Samophlang eigentlich tut?",a="Nein. Als Wenikee das Samophlang zum ersten Mal sieht, fragt sie, was es ist. Sein kompliziertes Räderwerk fasziniert sie, und sie will es reparieren, um herauszufinden, was es tut.",al={"weiß sie was es ist","was ist ein samophlang für sie"}},{q="Wo liegt der Mor'shan-Schutzwall?",a="Der Mor'shan-Schutzwall ist ein befestigter Außenposten der Horde am Nordrand des Brachlands, der den Pass nach Eschental bewacht.",al={"mor'shan-schutzwall standort","wo ist der schutzwall","brachland eschental grenze"}},{q="Was geschieht, nachdem Wenikee das kaputte Gerät untersucht hat?",a="Wenikee erklärt sich bereit, das Samophlang zu reparieren, fasziniert von seiner Bauweise. Sie braucht bestimmte mechanische Teile, um das Räderwerk wieder in Gang zu bringen, zunächst Schraubnieten aus Werkzeugeimern der Venture Company im Schlickermoor.",al={"was kommt als nächstes","schraubnieten","samophlang nächster schritt"}}},fp="18,222,17.368.0,27.318.0,30.130.0,26.190.0,51.179.0,51.150.0,38.120.0,54.224.1"}
P.entries["quest:3922"] = {n="Schraubnieten",s="Im Schlickermoor sucht Wenikee Boltbucket Teile für einen Samophlansch, den sie geborgen hat. Sie schickt Euch zu den nahen Arbeitstrupps der Venture Company, um Ersatzteile zu beschaffen.",h="Im Schlickermoor sucht Wenikee Boltbucket Teile für einen Samophlansch, den sie geborgen hat.",kw={"brachland","schraubnieten","samophlange","das schlickermoor","werkzeugeimer","venture company","wenikee boltbucket"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Arbeit der Venture Company im Schlickermoor den Sümpfen schadet. Ihre Vorräte zu stehlen gibt Euch einen Grund, zurückzuschlagen.",["profession:Engineering"]="Als Ingenieur erkennt Ihr vielleicht die Warnzeichen goblinischer Handwerkskunst, bevor Wenikees hastige Reparaturen in einer Explosion enden."},sec={{t="Wenikees technischer Bedarf",b="Wenikee Boltbucket hat einen Samophlansch geborgen und will verstehen, wie seine komplizierten Mechanismen ineinandergreifen. Die Goblinmaschine braucht passgenaue Teile, also schickt sie Euch zu den Arbeitstrupps der Venture Company im Schlickermoor. In ihren schweren Werkzeugeimern liegen die Schraubnieten des Kalibers siebzehn Komma fünf, die sie braucht."},{t="Ein explosiver Durchbruch",b="Ihr sammelt fünfzehn Schraubnieten, während die Bediener und Holzfäller der Venture Company im Sumpf östlich der Straße arbeiten. Als Ihr mit den Teilen zurückkehrt, stellt Wenikee den Samophlansch auf den Boden und beginnt sofort, ihn einzustellen. Unpassende Teile und eine überstürzte Montage führen zu einer plötzlichen Explosion. Wenikee ist erschüttert, doch ihr Wille zum Tüfteln bleibt ungebrochen."}},faq={{q="Was ist eine Schraubniete?",a="Eine Schraubniete ist ein kleines Befestigungsteil aus Metall oder ein Munitionsbestandteil, der in der goblinischen Ingenieurskunst verwendet wird. Wenikee braucht Schraubnieten des Kalibers siebzehn Komma fünf für die empfindlichen Zahnräder in ihrem Samophlansch.",al={"schraubniete","schraubnieten","was sind schraubnieten"}},{q="Wer ist Wenikee Boltbucket?",a="Wenikee Boltbucket ist eine unabhängige Tüftlerin, die neben dem Hauptweg im nördlichen Brachland lagert. Komplizierte Maschinen faszinieren sie, besonders Samophlansche, trotz der Gefahren, die sie bergen.",al={"wenikee","wer ist wenikee","wenikee boltbucket"}},{q="Wo findet man die Schraubnieten?",a="Ihr findet Schraubnieten in Werkzeugeimern im Schlickermoor, einem Lager der Venture Company östlich von Wenikees kleinem Lager am Wegesrand. Die Firma schlägt dort Holz und fördert Öl.",al={"wo sind werkzeugeimer","schraubnieten finden","schlickermoor eimer"}},{q="Was geschieht, wenn Wenikee den Samophlansch repariert?",a="Als Wenikee den Samophlansch mit den von Euch gebrachten Teilen einstellt, überlastet die Maschine und explodiert vor ihr. Ihre mangelhafte Kalibrierung erweist sich als gefährlich.",al={"funktioniert der samophlansch","samophlansch explosion","wenikee explosion"}},{q="Warum ist die Venture Company im Schlickermoor?",a="Die Venture Company betreibt im Schlickermoor Tagebau, um die Sümpfe des Brachlands auszubeuten und Öl sowie andere natürliche Rohstoffe zu gewinnen. Ihre Bohranlagen und Raffinerien verschmutzen die umliegende Landschaft.",al={"warum venture company im schlickermoor","schlickermoor zweck","venture company brachland"}},{q="Schaltet diese Quest weitere Aufgaben frei?",a="Nachdem der Reparaturversuch schiefgegangen ist, schickt Wenikee Euch nach Orgrimmar, um Rilli Greasygob aufzusuchen, einen ehemaligen Ingenieur der Venture Company. Sie nennt die nächste Aufgabe Rilli Greasygob.",al={"what comes next","folgequest","nach schraubnieten"}}},fx={af90a96f={q="Warum möchte Wenikee Boltbucket Schraubnieten?",a="Wenikee Boltbucket ist eine eifrige Tüftlerin, die entschlossen ist, den mysteriösen Samophlange zu reparieren, der von der Konsole der Venture Company geborgen wurde. Um die komplexe Maschine zum Laufen zu bringen, benötigt sie 17,5-Gauge-Schraubnieten, eine spezifische mechanische Komponente, die ihr fehlt. Allein durch Neugier und den unwiderstehlichen Drang getrieben, an komplizierten Maschinen zu basteln, möchte sie das Gerät wieder in funktionstüchtigen Zustand versetzen, um zu sehen, was es tatsächlich tut.",al={"warum braucht wenikee nugget slugs","wenikee boltbucket motiv","warum samophlange reparieren"}},["8f6d1935"]={q="Warum werdet Ihr ausgesandt, um bei Das Schlickermoor von der Venture Company zu stehlen?",a="Die Venture Company errichtete im Schlickermoor einen umfassenden Ölbohrbetrieb, komplett mit Bohrtürmen und schweren mechanischen Werkstätten. Aufgrund ihres industriellen Maßstabs halten ihre Arbeiter Werkzeugeimer bereit, die mit den präzisen 17,5-Gauge-Schraubnieten gefüllt sind, die Wenikee benötigt. Anstatt ihre eigenen herzustellen oder mit den feindseligen Betreibern zu handeln, schickt sie Euch, um die Komponenten direkt von deren Arbeitsplätzen aufzustöbern.",al={"warum das schlickermoor","warum venture company","wer hat nugget slugs"}}},fp="12,156,27.294.0,23.329.1,22.185.0,26.196.0,33.167.0,50.148.1,45.187.0,41.171.1"}
P.entries["quest:3923"] = {n="Rilli Schmierklump",s="Wenikee Boltbucket schickt einen beschädigten Samophlang zu Rilli Schmierklump in Orgrimmar. Sie hofft, dass sein Wissen über dessen Herkunft aus der Venture Company das Gerät erklären wird.",h="Wenikee Boltbucket schickt einen beschädigten Samophlang zu Rilli Schmierklump in Orgrimmar.",kw={"zerbrochenes und ramponiertes samophlang","nogg's machine shop","orgrimmar","rilli schmierklump","samophlange","tal der ehre","venture company","wenikee boltbucket"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr sehen, wie Orgrimmars Werkstätten erbeutete Maschinen gegen Syndikate einsetzen, die Kalimdor ausbeuten.",["profession:Engineering"]="Als Ingenieur wisst Ihr, wann es Zeit ist, den Schraubenschlüssel beiseitezulegen. Wenikee Boltbuckets zusätzliche Regler würden alles nur verschlimmern, also greift sie auf das Fachwissen eines ehemaligen Firmeningenieurs zurück."},sec={{t="Wenn Tüfteln scheitert",b="Wenikee Boltbucket untersuchte den Samophlang, der von der Bohrstelle der Venture Company im Brachland geborgen worden war. Ihre zusätzlichen Messgeräte zeigten, dass er kurz vor dem Zusammenbruch stand. Weitere Hebel und Regler könnten ihn zerstören, also hörte sie auf und überließ das Problem jemandem, der seine Bauweise kannte."},{t="Ein ehemaliger Firmenmann",b="Wenikee schickt Euch zu Nogg's Machine Shop im Tal der Ehre von Orgrimmar. Rilli Schmierklump arbeitet dort als Ingenieur und erlernte sein Handwerk einst bei der Venture Company. Er erkennt die Maschine sofort und staunt, dass überhaupt jemand die Erkundung der umkämpften Betriebe des Unternehmens im Brachland überlebt hat."}},faq={{q="Wer ist Rilli Schmierklump?",a="Rilli Schmierklump arbeitet als Gobliningenieur bei Nogg's Machine Shop im Tal der Ehre von Orgrimmar. Er arbeitete einst für die Venture Company und kennt ihre Technik aus eigener Erfahrung, darunter Geräte wie den Samophlang.",al={"rilli schmierklump","wer ist rilli","nogg's machine shop rilli"}},{q="Warum konnte Wenikee Boltbucket den Samophlang nicht selbst reparieren?",a="Wenikee Boltbuckets zusätzliche Messgeräte zeigten, dass der Samophlang kurz davor war, auseinanderzufallen. Sie fürchtete, weiteres Tüfteln würde ihn ruinieren, und suchte deshalb jemanden mit unmittelbarer Erfahrung mit den Maschinen der Venture Company.",al={"warum zu rilli schicken","boltbuckets scheitern","wenikee kann es nicht reparieren"}},{q="Wo befindet sich Rilli Schmierklump?",a="Rilli Schmierklump arbeitet in Nogg's Machine Shop im Tal der Ehre von Orgrimmar, im nordöstlichen Stadtbezirk.",al={"rilli schmierklump standort","wo ist schmierklump","rilli finden"}},{q="Welche Rolle spielt die Venture Company dabei?",a="Der Samophlang stammt aus dem Tagebaubetrieb der Venture Company im Schlickermoor im nördlichen Brachland. Es handelt sich um firmeneigene Spezialtechnik, und ehemalige Mitarbeiter wie Rilli Schmierklump wissen, wie man sie wartet und ihre Funktionsweise deutet.",al={"verbindung zur venture company","warum venture company","wer hat den samophlang gebaut"}},{q="Was geschieht, nachdem Rilli den Samophlang erhalten hat?",a="Rilli Schmierklump erkennt das Gerät, braucht aber die offizielle Betriebsanleitung der Venture Company, um es zu bedienen oder nachzubauen. Ihr werdet losgeschickt, um das Samophlanghandbuch zu beschaffen.",al={"wie geht es nach rilli weiter","samophlang questreihe fortsetzung"}},{q="Was ist überhaupt ein Samophlang?",a="Keiner der Beteiligten scheint genau zu wissen, was ein Samophlang ist. Das Gerät der Venture Company ist kompliziert und voller Zahnräder. Selbst Wenikee Boltbucket musste fragen, was es war, und Rilli braucht das Handbuch des Unternehmens, um es zu verstehen.",al={"was ist ein samophlang","samophlang erklärt"}}},fx={["322883d5"]={q="Warum braucht Wenikee Boltbucket, dass Ihr den Samophlange nach Orgrimmar bringt?",a="Wenikee hat versucht, den beschädigten Samophlange zu kalibrieren, aber seine Integrität ist auf einem historischen Tiefstand. Sie befürchtet, dass weiteres Basteln die Dinge verschlimmern könnte, und bittet Euch, ihn zu dem ehemaligen Ingenieur der Venture Company, Rilli Greasygob, nach Orgrimmar zu bringen.",al={"warum ich wenikee","warum braucht wenikee mich","warum mich mit samophlange schicken"}}},fp="15,159,20.266.0,20.299.0,23.213.0,60.207.0,33.117.0,43.224.0,51.181.1,29.217.0"}
P.entries["quest:3924"] = {n="Samophlanghandbuch",s="In Orgrimmar braucht Rilli Greasygob Hilfe mit einem defekten Samophlang. Der Gobliningenieur schickt Euch zurück ins Brachland, um die Betriebsanleitung zu holen, die sein früherer Rivale von der Venture Company besitzt.",h="In Orgrimmar braucht Rilli Greasygob Hilfe mit einem defekten Samophlang.",kw={"brachland","boss copperplug","felsadermine","handbuch","orgrimmar","rilli greasygob","samophlange","stotterspritter","venture company"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr Goblinspezialisten in Orgrimmar, wertvolle technische Teile zu bergen und gegen die ausbeuterischen Aktivitäten der Venture Company in der Nähe zurückzuschlagen.",["profession:Engineering"]="Als Ingenieur könnt Ihr sehen, wie Goblins die Erfindungen ihrer Firmen hüten. Sie reißen komplexe Baupläne auseinander und horten die Teile, damit Kollegen sie nicht kopieren können."},sec={{t="Firmenrivalitäten und Betriebsgeheimnisse",b="Rilli Greasygob arbeitete einst an der Seite von Boss Copperplug bei der Venture Company. Copperplug war für das Innenleben des Samophlangs zuständig und hütete dessen Geheimnisse sorgsam. Er gab Rilli kein Handbuch. Stattdessen händigte Copperplug einzelne Seiten nur Untergebenen aus, denen er vertraute, und ließ seinen Ingenieurskollegen ohne das nötige Wissen zurück, um das Gerät zu verstehen."},{t="Infiltration von Boulder Lode",b="Rilli schickt Euch zur Felsadermine im nordöstlichen Brachland, um die Anleitung für den von dort gebrachten Apparat zu holen. Boss Copperplug ist irgendwo in der Mine, und die von ihm verteilten Seiten sind im Minenbetrieb verstreut. Ihr müsst sie sammeln und zu einer vollständigen Anleitung für die Reparatur des Geräts zusammenfügen."}},faq={{q="Was ist das Samophlanghandbuch?",a="Das Samophlanghandbuch erklärt die Mechanik des Geräts und wie man es repariert. Die Venture Company nutzt diese komplexe, eigenwillige Maschine.",al={"was ist das handbuch","samophlanghandbuch gegenstand","bedienungsanleitung"}},{q="Wer ist Boss Copperplug?",a="Boss Copperplug leitet die Felsadermine der Venture Company im nordöstlichen Brachland. Er war einst Rilli Greasygobs Rivale und behielt die Betriebsgeheimnisse des Samophlangs und die Handbuchseiten für sich.",al={"copperplug","wer ist copperplug","boss copperplug"}},{q="Wo liegt die Felsadermine?",a="Die Felsadermine liegt im nordöstlichen Brachland, nördlich vom Wegekreuz und westlich der Küste.",al={"boulder lode lage","wo ist boulder lode","felsadermine finden"}},{q="Warum braucht Rilli Greasygob das Handbuch?",a="Rilli glaubt, dass er das defekte Samophlang aus dem Brachland reparieren und bedienen kann. Seine verwickelte Konstruktion erfordert die offizielle Anleitung.",al={"warum will rilli das handbuch","warum samophlang reparieren"}},{q="Welche Rolle spielt Stotterspritter bei dieser Aufgabe?",a="Stotterspritter ist ein Geschäftspartner in Ratschet, der zuerst nach Informationen über das Gerät suchte und mit Rilli in Verbindung bleibt. Stotterspritter schickt Dank und eine Vergütung für die Beschaffung der Baupläne der Maschine.",al={"stotterspritter verbindung","ratschet goblin stotterspritter"}},{q="Was geschieht, nachdem das Handbuch zurückgebracht wurde?",a="Rilli studiert eifrig das Handbuch und hofft, die Maschine zum Laufen zu bringen. Die Reparatur eines solch rätselhaften Apparats bleibt ein fortwährendes mechanisches Rätsel.",al={"questabschluss","repariert rilli es"}}},fp="18,193,37.337.0,28.315.1,31.136.0,23.203.0,39.98.0,41.148.0,41.201.0,42.143.0"}
P.entries["quest:393"] = {n="Schatten der Vergangenheit",s="In Schatten der Vergangenheit führt die Spur eines Verliesgefangenen zu Sturmwinds verborgenen Machenschaften. Baros Alexston schickt Euch zu Mathias Shaw, nachdem ein geheimnisvoller Besucher mit Bazil Thredd gesprochen hat.",h="In Schatten der Vergangenheit führt die Spur eines Verliesgefangenen zu Sturmwinds verborgenen Machenschaften.",kw={"baros alexston","bazil thredd","gregor lescovar","maelik","marzon","mathias shaw","schatten der vergangenheit","si:7","sturmwind"},ang={["class:Rogue"]="Als Schurke erlebt Ihr die hohe Kunst der Geheimdienstarbeit und politischen Überwachung der Allianz, wenn Ihr Euch bei Mathias Shaw in der Altstadt meldet.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie die Ermittlungen eine Verbindung zwischen dem Banditentum der Defias und Sturmwinds Adel aufdecken.",["race:Human"]="Als Mensch aus Sturmwind seht Ihr, wie die herrschende Klasse des Königreichs während der Abwesenheit von König Varian Wrynn gespalten ist."},sec={{t="Eine Spur im Schatten",b="Baros Alexston kann den Besucher, der mit Bazil Thredd, dem Hauptgefangenen des Verlieses, gesprochen hat, nicht benennen. Der Bericht von Aufseher Thelwasser führte die Ermittler zu Sturmwinds Stadtarchitekten, doch er kann ihnen keinen Namen nennen. Also verweist Baros Euch an Meister Mathias Shaw. Shaw leitet SI:7 und macht es sich zur Aufgabe, Sturmwinds Geheimnisse zu kennen."},{t="Den Besucher entlarven",b="Im Hauptquartier von SI:7 in der Altstadt studiert Mathias Shaw die versiegelte Beschreibung und durchschaut den Decknamen des Besuchers, Maelik. Die Merkmale deuten auf einen professionellen Mörder hin, der Namen so leicht ablegt wie Umhänge. Shaw kennt ihn als einen Auftragsmörder, der oft Marzon genannt wird."},{t="Verrat im Adel",b="Mathias Shaw sagt, dass Marzon für Lord Gregor Lescovar arbeitet, einen für seine Falschheit bekannten Adligen aus Sturmwind. Die Verbindung reicht über den Aufstand der Bruderschaft der Defias in Westfall hinaus. Sie führt in die Adelshallen von Sturmwind."}},faq={{q="Wer schickt Euch zu Mathias Shaw?",a="Baros Alexston, Sturmwinds Stadtarchitekt, schickt Euch zu Mathias Shaw, weil er den Besucher in den Aufzeichnungen des Verliesaufsehers nicht identifizieren kann. Baros sagt, Shaw schulde ihm einen persönlichen Gefallen.",al={"wer vergibt diese quest","questgeber schatten der vergangenheit"}},{q="Wo befindet sich Meister Mathias Shaw?",a="Mathias Shaw befindet sich im Hauptquartier von SI:7 in der Altstadt von Sturmwind. Die geheime Nachrichtenzentrale dient den Schurken, Spähern und Geheimdienstoffizieren der Krone.",al={"mathias shaw standort","wo ist shaw","mathias shaw finden"}},{q="Wer war der geheimnisvolle Besucher im Verlies?",a="Der Besucher nannte sich Maelik. Baros kann ihn nicht identifizieren, also schickt er die versiegelte Beschreibung an Mathias Shaw.",al={"wer ist maelik","wer ist thredds besucher","wer ist der auftragsmörder"}},{q="Warum ist Lord Gregor Lescovar verwickelt?",a="Baros erwähnt Lord Gregor Lescovar nicht. Mathias Shaw enthüllt Lescovars Rolle, nachdem er die Beschreibung des Besuchers gelesen hat.",al={"für wen arbeitet marzon","lescovars verbindung"}},{q="Wofür steht SI:7?",a="SI:7 bedeutet Sturmwind Intelligence. Der Geheimdienst sammelt Informationen und führt im In- und Ausland verdeckte Operationen für das Königreich Sturmwind durch.",al={"was ist si7","si:7 bedeutung"}},{q="Warum hat Baros Alexston Einfluss bei SI:7?",a="Baros sagt, Mathias Shaw schulde ihm einen Gefallen, erklärt aber nicht, wofür.",al={"warum schuldet shaw baros einen gefallen","verbindung zwischen baros und shaw"}}},fx={["31db03ee"]={q="Warum schickt Euch Baros Alexston zu Mathias Shaw?",a="Baros Alexston kann die mysteriöse Gestalt, die Bazil Thredd im Verlies besucht hat, beim besten Willen nicht identifizieren. Als Stadtarchitekt von Sturmwind weiß er jedoch, wer jeden illegalen Komplott in der Stadt verfolgt. Meister Mathias Shaw schuldet ihm einen Gefallen, was den Anführer von SI:7 zur besten Person macht, um die Verkleidungen des Besuchers zu durchschauen und aufzudecken, welche dunklen Pläne unter der Nase des Adels geschmiedet werden.",al={"warum an shaw schicken","baros alexston motiv","warum mathias shaw"}}},fp="18,191,21.329.0,21.258.1,25.223.1,30.187.0,37.155.0,47.113.1,37.126.1,25.142.0,44.79.0"}
P.entries["quest:394"] = {n="Der Kopf des Ganzen",s="In Sturmwind führt Euch Der Kopf des Ganzen von Elling Trias zu Meister Mathias Shaw in der Altstadt. Euer Bericht über Lord Gregor Lescovars Tod bestätigt Euren Platz in Sturmwinds verdecktem Geheimdienstnetzwerk.",h="In Sturmwind führt Euch Der Kopf des Ganzen von Elling Trias zu Meister Mathias Shaw in der Altstadt.",kw={"elling trias","der kopf des ganzen","lescovar","mathias shaw","die altstadt","si:7","sturmwind"},ang={["class:Rogue"]="Als Schurke bestätigt Ihr durch Euren direkten Bericht an Mathias Shaw Eure Zuverlässigkeit gegenüber dem Anführer von Sturmwinds bedeutendster Schattenorganisation.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, das Reich zu stabilisieren, indem Ihr während der zutiefst destabilisierenden Abwesenheit von King Varian Wrynn korrupte Aristokraten aus Sturmwind beseitigt."},sec={{t="Eine Angelegenheit erledigt",b="Elling Trias schickt Euch vom Tatort in die Altstadt, nachdem Lord Lescovar niedergestreckt wurde. Sein Tod beendet die unmittelbare Gefahr für Sturmwinds Anführer. Trias ist Käsehändler und ein erfahrener Geheimdienstagent. Er warnt Euch davor, Euch von höfischem Lob ablenken zu lassen."},{t="Bericht beim Spionagemeister",b="Meister Mathias Shaw lenkt Sturmwinds verdeckten Apparat über den SI:7 aus verborgenen Kammern in der Altstadt. Als Ihr Lescovars Tod meldet, erkennt Shaw Euer Geschick und Eure Skrupellosigkeit an. Er lobt Eure Effizienz und dankt Euch für Euren Dienst am Volk von Sturmwind."}},faq={{q="Was ist das Ziel dieser Quest?",a="Ihr reist von Elling Trias zu Meister Mathias Shaw in Sturmwinds Altstadt. Dort bestätigt Ihr, dass Lord Gregor Lescovar getötet wurde.",al={"der kopf des ganzen quest","was ist bei der kopf des ganzen zu tun"}},{q="Wer ist Mathias Shaw?",a="Mathias Shaw leitet von der Altstadt aus den SI:7, Sturmwinds geheim operierenden Nachrichtendienst und seine Meuchelmördergilde.",al={"shaw","meister shaw","si7 anführer"}},{q="Warum schickt Elling Trias Euch zu Shaw statt zur Palastwache?",a="Elling Trias arbeitet tief in Sturmwinds Geheimdienstapparat. Lescovar war ein prominenter Adliger, der Hochverrat beging, weshalb Geheimhaltung hilft, einen öffentlichen Skandal unter der Palastwache zu vermeiden.",al={"warum shaw statt wachen","warum shaw berichten"}},{q="Welche Gefahr stellte Lescovar für Sturmwind dar?",a="Lord Gregor Lescovar schmiedete mit umstürzlerischen Agenten Pläne gegen die Krone und die Sicherheit der Hauptstadt. Er verriet das Reich aus den Reihen des Adels heraus.",al={"lescovars bedrohung","was hat lescovar getan"}},{q="Was geschieht nach der Meldung von Lescovars Tod?",a="Mathias Shaw bereitet sich darauf vor, die Akte über die Verschwörung zu schließen. Er schickt Euch weiter, um die Bedrohung, die über Sturmwind schwebt, endgültig zu beenden.",al={"nächste quest nach der kopf des ganzen","what comes next"}},{q="Wo ist Mathias Shaw zu finden?",a="Mathias Shaw ist im Kommandogebäude des SI:7 in der Altstadt zu finden, in den östlichen Vierteln von Sturmwind.",al={"shaw standort","wo ist mathias shaw"}}},fx={c9b52599={q="Warum möchte Elling Trias, dass dies erledigt wird?",a="Elling Trias mag wie ein einfacher Käsehändler erscheinen, aber er unterhält tiefe Verbindungen zu Mathias Shaw und dem Geheimdienstnetzwerk von Sturmwind. Nachdem er geholfen hat, Lord Lescovars Verrat aufzudecken, möchte Trias, dass der Untergang des abtrünnigen Adligen offiziell durch die verdeckten Kanäle von SI:7 registriert wird, anstatt durch die königliche Bürokratie, um sicherzustellen, dass die Schattenbeschützer des Königreichs wissen, dass die Bedrohung beendet ist, während der Adel auf Distanz gehalten wird.",al={"warum kümmert sich elling trias","elling trias motiv","warum an mathias shaw schicken"}}},fp="21,211,17.258.1,26.265.0,34.139.0,20.103.0,67.191.0,43.145.0,46.137.0,32.110.0"}
P.entries["quest:395"] = {n="Das Ende der Bruderschaft",s="In Burg Sturmwind bleiben nach dem Tod von Lord Gregor Lescovar Fragen offen. Meister Mathias Shaw schickt Euch zu Stadtarchitekt Baros Alexston und mahnt Euch, die Identität des Täters geheim zu halten.",h="In Burg Sturmwind bleiben nach dem Tod von Lord Gregor Lescovar Fragen offen.",kw={"baros alexston","das ende der bruderschaft","defias","elling trias","gregor lescovar","mathias shaw","si:7","burg sturmwind"},ang={["class:Rogue"]="Als Schurke hört Ihr Mathias Shaws Warnung und die unausgesprochene Regel des SI:7: Vollstreckt die Gerechtigkeit des Königreichs im Stillen, ohne öffentliche Anerkennung für das Blut eines Adligen.",["faction:Alliance"]="Die Aufdeckung der Verschwörung der Defias in Burg Sturmwind zeigt, dass dem Königreich sowohl Umsturz aus den eigenen Adelshallen als auch Gefahr durch Banditen auf dem Land droht.",["race:Human"]="Als Mensch aus Sturmwind erlebt Ihr, wie dieser Auftrag den Aufstand der Stonemasons abschließt, der vor Jahren in den Straßen der Stadt begann, und Gerechtigkeit sichert, ohne das Königreich zu zerreißen."},sec={{t="Offene Fragen im Schatten",b="Nachdem Lord Gregor Lescovar und sein Kontakt zu den Defias, Marzon the Silent Blade, getötet wurden, mahnt Meister Mathias Shaw zur Vorsicht. Der Tod eines Adligen in der königlichen Burg könnte politische Unruhen auslösen, obwohl Lescovar tief in Hochverrat verstrickt war. Shaw bittet Euch, Baros Alexston die groben Züge der Verschwörung der Defias mitzuteilen. Verschweigt Eure Rolle bei der Tötung und die Beteiligung des Schurken und Käsehändlers Elling Trias."},{t="Ein erleichtertes Aufatmen",b="Baros Alexston, der Stadtarchitekt, der als Steinmetz beim Wiederaufbau von Sturmwind half, ist erleichtert, dass Lescovar tot ist. Edwin van Cleef hatte Alexston und andere führende Beteiligte des Wiederaufbaus für seine Rache ausersehen, nachdem die Stonemasons ohne Bezahlung vertrieben worden waren. Da Lescovar zum Schweigen gebracht und die Verschwörung durchkreuzt wurde, glaubt Alexston, dass die unmittelbare Bedrohung für die Architekten und Adligen des Königreichs vorüber ist."}},faq={{q="Was geschieht in Das Ende der Bruderschaft?",a="Nachdem Ihr Lord Gregor Lescovar in Burg Sturmwind getötet habt, erstattet Ihr Meister Mathias Shaw beim SI:7 Bericht. Shaw schickt Euch zu Stadtarchitekt Baros Alexston, der wissen möchte, ob der Plan der Defias gegen die Stadtführung vereitelt wurde.",al={"was ist das ende der bruderschaft","das ende der bruderschaft questüberblick","das ende der bruderschaft zusammenfassung"}},{q="Warum sagt Shaw Euch, Ihr sollt die Tötung Lescovars nicht zugeben?",a="Lord Gregor Lescovar war ein hochrangiger Adliger im House of Nobles von Sturmwind. Obwohl seine Zusammenarbeit mit den Defias erwiesen war, könnte seine Tötung in der königlichen Burg einen politischen Skandal und Nachforschungen auslösen. Shaw rät, den Täter ungenannt zu lassen.",al={"warum lescovars tod verheimlichen","warum über lescovar lügen","shaws rat zu lescovar"}},{q="Warum sollte niemand Elling Trias erwähnen?",a="Elling Trias gibt sich im Handelsdistrikt als Käsehändler aus, ist aber ein erfahrener Agent mit vielen Kontakten in den Schatten der Stadt. Seine Rolle bei der Aufdeckung der Verschwörung preiszugeben, könnte seine Tarnung auffliegen lassen und sein Untergrundnetzwerk gefährden.",al={"warum trias verbergen","trias geheimnis","verkauf trias käsehändler"}},{q="Warum war Baros Alexston persönlich wegen der Defias besorgt?",a="Baros Alexston gehörte der Stonemasons Guild an und half an der Seite von Edwin van Cleef beim Wiederaufbau von Sturmwind. Als das House of Nobles den Arbeitern die Bezahlung verweigerte, wurden die Steinmetze zu Banditen. Alexston blieb im Dienst der Stadt und wurde zum Ziel von van Cleefs Rache.",al={"warum kümmert es alexston","baros alexston van cleef","alexstons verbindung zu den defias"}},{q="Markiert diese Quest das Ende der Bedrohung durch die Defias?",a="Die Tötung von Edwin van Cleefs wichtigstem Sympathisanten im House of Nobles beseitigt die Defias nicht. Lescovars Ausschaltung versetzt ihren Bestrebungen innerhalb der Regierung von Sturmwind einen entscheidenden Schlag und wendet einen unmittelbar bevorstehenden Umsturz innerhalb der Stadtmauern ab.",al={"sind die defias vernichtet","sind die defias jetzt tot","beendet das ende der bruderschaft die defias"}},{q="Wohin führen diese Ermittlungen als Nächstes?",a="Erleichtert über Euren Erfolg gegen die Verschwörer verfasst Baros Alexston einen Bericht über die Bruderschaft der Defias für den König. Er bittet Euch, ihn bei einer Audienz in Burg Sturmwind zu überbringen, in An Audience with the King.",al={"welche quest kommt als nächstes","was folgt auf das ende der bruderschaft","wer ist als nächstes aufzusuchen"}}},fx={["7fb09cca"]={q="Warum schickt Meister Mathias Shaw Euch zu Baros Alexston?",a="Nachdem Lord Gregor Lescovar erledigt und die unmittelbare Verschwörung zerschlagen war, kam Baros Alexston direkt auf der Suche nach Euch. Als Stadtarchitekt, der für den Wiederaufbau von Sturmwind nach dem Ersten Krieg verantwortlich ist, lebt Alexston unter der ständigen Bedrohung durch Edwin van Cleefs Vendetta gegen den Adel. Shaw möchte, dass der Adelsrat über die Defias-Bedrohung durch offizielle bürgerliche Kanäle informiert wird, während SI:7s verdeckte Beteiligung und nicht sanktionierte Attentate vor königlicher Prüfung geschützt bleiben.",al={"shaw motiv","warum mit alexston sprechen","warum schickt shaw euch"}}},fp="17,187,25.404.1,18.411.0,34.231.0,56.232.0,39.245.1,61.268.0,50.238.0,40.213.1"}
P.entries["quest:396"] = {n="Eine Audienz beim König",s="In Burg Sturmwind kommt der Bericht über die Defias vor die Krone. Nach langen Ermittlungen in Westfall und den Todesminen bringt Ihr die Erkenntnisse von Stadtarchitekt Baros Alexston in die Hauptstadt.",h="In Burg Sturmwind kommt der Bericht über die Defias vor die Krone.",kw={"eine audienz beim könig","baros alexston","brotherhood's end","defias-bericht","edwin van cleef","katrana prestor","burg sturmwind","varian wrynn"},ang={["class:Rogue"]="Wenn Ihr als Schurke am Sitz der Macht von van Cleefs Sturz berichtet, zeigt sich, wie schmal der Grat zwischen einem königlichen Agenten und einem geächteten Gildenmeister sein kann.",["faction:Alliance"]="Für die Allianz beendet die Übergabe dieses Berichts eine der größten inneren Krisen, die ihr wichtigstes Menschenkönigreich bedroht haben.",["race:Human"]="Für Euch als Menschen aus Sturmwind bedeutet diese Audienz Vergeltung für den Terror in ganz Westfall und offenbart, wie zerbrechlich das königslose Reich geworden ist."},sec={{t="Eine königliche Vorladung",b="Edwin van Cleef ist gefallen, und die Verschwörung unter Mondbruch ist zerschlagen. Stadtarchitekt Baros Alexston verfasst einen offiziellen Bericht für die Krone. Er meint, Ihr solltet dafür geehrt werden, dass Ihr dem kriminellen Treiben der Gilde ein Ende gesetzt habt. So tragt Ihr die Erkenntnisse über Sturmwinds prächtige Kanäle zur Burg Sturmwind und erwartet, dem Herrscher des Reiches zu begegnen."},{t="Ein leerer Thron",b="Lady Katrana Prestor nimmt den Bericht am königlichen Hof entgegen, doch König Varian Wrynn ist abwesend. Sie sagt, er befinde sich auf einer längeren diplomatischen Mission und könne Euch nicht persönlich gratulieren. Prestor nimmt die Erkenntnisse entgegen und lobt Euch dafür, Sturmwind vor van Cleefs Machenschaften bewahrt zu haben. Dann bietet sie Euch im Namen des Königs eine Belohnung an. Die Wahrheit über den Aufstand bleibt hinter ihrer Erklärung für die Abwesenheit des Königs verborgen."}},faq={{q="Warum überbringe ich diesen Bericht anstelle von Baros Alexston?",a="Baros Alexston glaubt, dass Ihr Euch diese Ehre durch Euren Einsatz vor Ort verdient habt. Ihr habt die Verschwörung der Defias durch Westfall verfolgt und die Todesminen gestürmt, daher bittet er Euch, die Erkenntnisse vorzulegen und die Anerkennung der Krone entgegenzunehmen.",al={"warum bericht überbringen","baros alexston bericht","audienz beim könig übergabe"}},{q="Wo ist König Varian Wrynn?",a="König Varian Wrynn ist nicht in Burg Sturmwind. Der Hof erklärt, er befinde sich auf einer geheimen diplomatischen Mission, während sein junger Sohn Anduin unter der Regentschaft von Hochlord Bolvar Fordragon auf dem Thron sitzt.",al={"wo ist der könig","warum ist varian nicht hier","wo ist varian wrynn","verschwundener könig"}},{q="Wer nimmt den Bericht über die Defias tatsächlich entgegen?",a="Lady Katrana Prestor nimmt den Bericht am königlichen Hof entgegen. Die oberste Beraterin des Throns nimmt Baros Alexstons Erkenntnisse entgegen, lobt Euch für den Sieg über Edwin van Cleef und belohnt Euch im Namen der Krone.",al={"wer schließt die quest ab","ansprechpartner in der burg","wer nimmt den bericht entgegen"}},{q="Beendet diese Quest die Questreihe der Bruderschaft der Defias?",a="Ja. Der Bericht bringt die Geschichte der Defias, von den Anfängen in Westfall bis zu den Todesminen, zu ihrem offiziellen politischen Abschluss.",al={"ende der defias-questreihe","ist dies die letzte defias-quest","nachwirkungen der todesminen"}},{q="Warum scheint Lady Katrana Prestor die Abwesenheit des Königs so abzutun?",a="Lady Katrana Prestor bleibt am königlichen Hof gelassen. Sie sagt, König Varian erledige ferne Staatsgeschäfte, und zerstreut damit die Sorge um den Verbleib des Königs.",al={"warum ist prestor gelassen","prestor diplomatische mission","prestors ausrede"}},{q="Was geschieht danach mit der Bruderschaft der Defias?",a="Edwin van Cleef ist tot, und das gewaltige Kriegsschiffprojekt der Bruderschaft wurde vereitelt, wodurch ihre Führung zerschlagen ist. Verstreute Räuber und verbliebene Mitglieder suchen weiterhin Westfall, das Rotkammgebirge und Sturmwinds Gassen heim.",al={"sind die defias verschwunden","was geschieht jetzt mit den defias","ist die bruderschaft zerschlagen"}}},fx={eac00c4f={q="Warum möchte Baros Alexston, dass der Bericht an den König überbracht wird?",a="Baros Alexston muss die Krone formell darüber informieren, dass die Defias-Verschwörung zerschlagen und Edwin van Cleef getötet wurde. Die Komplotte der Bruderschaft bedrohten Sturmwind selbst, und Alexston glaubt, dass die höchste Autorität des Reiches eine vollständige, direkte Abrechnung der abgewendeten Gefahr erhalten – und demjenigen, der alles riskierte, um sie zu stoppen, eine offizielle königliche Belobigung aussprechen muss.",al={"warum bericht überbringen","baros alexston bericht an könig","warum bericht über defias"}}},fp="25,184,15.339.0,15.405.1,58.230.0,27.192.0,37.216.0,53.119.0,71.159.0,50.212.0"}
P.entries["quest:397"] = {n="Ihr habt uns gut gedient",s="Unter dem Slaughtered Lamb haben Sturmwinds Hexenmeister einen Zufluchtsort gesichert. Sie unterstehen Zardeth der Schwarzen Klaue, dessen Kabale die Stadtwache und neugierige Adlige auf Abstand gehalten hat.",h="Unter dem Slaughtered Lamb haben Sturmwinds Hexenmeister einen Zufluchtsort gesichert.",kw={"a noble brew","schwarze klaue","wichtel","lord wishock","sturmwind","the slaughtered lamb","zardeth","zggi"},ang={["class:Warlock"]="Als Hexenmeister erfahrt Ihr, mit welchen skrupellosen Mitteln Sturmwinds Zirkel sein Überleben sichert. Er tötet neugierige Adlige, bevor sie die Stadtwache gegen ihn aufbringen können.",["faction:Alliance"]="Als Mitglied der Allianz lebt Ihr unter Sturmwinds makellosen Türmen und inmitten frommer Hingabe. Verborgene Hexenmeister töten hochgeborene Unruhestifter, um ihre Anwesenheit zu schützen."},sec={{t="Mit Schatten erkauftes Schweigen",b="Unter dem Slaughtered Lamb praktizieren Sturmwinds Hexenmeister ihre dunklen Künste, bislang von den Behörden geduldet. Lord Wishock droht, ihre geheimen Studien aufzudecken oder ihnen ein Ende zu setzen. Deshalb verabreicht ihm der Zirkel einen vergifteten Trunk, und sein Tod bewahrt ihren Zufluchtsort unter dem Gasthaus."},{t="Die Gabe des Meisters",b="Zardeth der Schwarzen Klaue erfährt, dass Lord Wishock seinen letzten Trunk genommen hat, und hält die Gefahr für gebannt. Um dem treuen Praktizierenden zu danken, der die Stadtwache und neugierige Standesgenossen fernhielt, schickt Zardeth seinen winselnden Wichteldiener Zggi mit einem dunklen Zeichen des Dankes."}},faq={{q="Wer ist Zardeth der Schwarzen Klaue?",a="Zardeth der Schwarzen Klaue ist ein bedeutender Hexenmeister, der heimlich in Sturmwind wirkt. Er schützt die verborgenen dunklen Zauberwirker der Stadt vor der Entdeckung durch örtliche Adlige und geht skrupellos gegen jeden vor, der ihre verbotenen Künste erforscht.",al={"wer ist zardeth","zardeths rolle","anführer der schwarzen klaue"}},{q="Was geschah mit Lord Wishock?",a="Sturmwinds verborgene Hexenmeister verabreichten Lord Wishock ein eigens zubereitetes giftiges Gebräu. Nach seinem Tod wird sein Adelshaus die Praktizierenden unter den Straßen der Stadt nicht länger ausforschen oder stören.",al={"ist wishock gestorben","wozu diente das gebräu","lord wishocks schicksal"}},{q="Wer ist Zggi?",a="Zggi ist ein Wichtel, der an den Dienst für Zardeth der Schwarzen Klaue gebunden ist. Missgünstig und habgierig will Zggi die Schätze des Meisters behalten, fürchtet jedoch die Strafe dafür, Zardeth offen zu trotzen.",al={"wer ist der wichtel zggi","zggi diener"}},{q="Warum nahmen die Hexenmeister Lord Wishock ins Visier?",a="Die Hexenmeister nahmen Wishock ins Visier, weil er drohte, Sturmwinds Zirkel zu stören und aufzudecken. Sie töteten ihn, um ihre Arbeit in der Dämonologie und mit Shadow Magic vor der Einmischung des Adels zu schützen.",al={"warum wishock töten","wishocks bedrohung"}},{q="Wo endet diese Questreihe?",a="Die Reihe endet bei Zggi, nahe Zardeth der Schwarzen Klaue im Hexenmeistersanktum unter dem Slaughtered Lamb in Sturmwinds Magierviertel.",al={"wo ihr habt uns gut gedient abgeben","zggi aufenthaltsort"}},{q="Warum ist diese Aufgabe ausschließlich Hexenmeistern vorbehalten?",a="Das Vorgehen umfasst die Machtpolitik der Kabale und einen rechtswidrigen Meuchelmord. Nur bewährten Hexenmeisterschülern wird diese tödliche Täuschung anvertraut, sodass die übrigen Behörden der Allianz nichts davon erfahren.",al={"nur für hexenmeister","warum hexenmeisterquest"}}},fx={["7c2d3142"]={q="Warum schickt Euch Zardeth zu Zggi?",a="Da Lord Wishock vergiftet ist und die Hexenmeister vor seinen neugierigen Blicken sicher sind, hat Zardeth eine besondere Belohnung für Eure Dienste für den Zirkel vorbereitet. Anstatt sie Euch selbst zu überreichen, schickt er Euch nach unten zu seinem Diener Zggi, der seine Schätze bewacht und die Befehle seines Meisters ausführt.",al={"warum mit zggi sprechen","warum schickt euch zardeth zu zggi","zardeth geschenk zggi"}}},fp="23,178,27.288.0,17.264.1,33.243.0,30.191.1,12.174.0,46.196.0,37.137.0,49.186.0"}
P.entries["quest:398"] = {n="GESUCHT: Madenauge",s="In Brill haben die Verlassenen ein Kopfgeld auf Madenauges Tod ausgesetzt. Der berüchtigte Gnoll plündert nahegelegene Friedhöfe und Höfe und liefert der Geißel des Lichkönigs Leichen. Exekutor Zygand verlangt einen Beweis für seinen Tod, um die Ländereien rund um Garrens Schlupfwinkel zu sichern.",h="In Brill haben die Verlassenen ein Kopfgeld auf Madenauges Tod ausgesetzt.",kw={"kopfgeld","brill","exekutor zygand","garrens schlupfwinkel","gnoll","grabräuber","lichkönig","madenauge","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde braucht Ihr sichere Grenzen im Norden von Tirisfal, um Lordaeron gegen die Überreste der Geißel zu halten.",["race:Undead"]="Als Untoter wisst Ihr, dass jede Leiche, die Madenauge stiehlt, ein gefallenes Geschwisterteil ist, das der Lichkönig erneut versklavt. Ihn aufzuhalten verteidigt die Verlassenen und vergilt ein persönlich erlittenes Unrecht."},sec={{t="Ein schweres Verbrechen",b="In Tirisfal ruhen die Toten nicht in Frieden. Madenauge droht eine harte Strafe, weil er dem Lichkönig hilft. Gnolle sind gewöhnlich wilde Unholde, die von Hunger getrieben werden. Doch Madenauge gräbt Leichen aus und sammelt Überreste, um die Armee der Geißel zu stärken."},{t="Gerechtigkeit in Brill",b="Die Verlassenen kämpfen darum, sich von der Kontrolle des Lichkönigs zu befreien. Ihre toten Angehörigen der Geißel zuzuführen, zählt zu den schwersten Vergehen. Exekutor Zygand wacht in Brill darüber, dass die Befehle des Militärs durchgesetzt werden. Er ließ das Kopfgeld aussetzen, um die Grabräubereien nahe Garrens Schlupfwinkel zu beenden. Bringt Madenauges Tatze, um die Belohnung einzufordern und zu beweisen, dass die Bestie Tirisfal nicht länger heimsuchen kann."}},faq={{q="Wer ist Madenauge?",a="Madenauge ist ein berüchtigter Gnoll, der im Norden von Tirisfal umherstreift. Er überfällt Höfe nahe Garrens Schlupfwinkel und sammelt Leichen für die Geißel, was ihn selbst unter seinesgleichen abscheulich macht.",al={"madenauge hintergrundgeschichte","wer ist madenauge","madenauge gnoll"}},{q="Warum wollen die Verlassenen seinen Tod?",a="Die Verlassenen haben Madenauge zum Tode verurteilt, weil er die Geißelarmee des Lichkönigs mit geraubten Leichen versorgt. Der Geißel Soldaten und Ressourcen vorzuenthalten, ist für das Überleben der Verlassenen entscheidend.",al={"warum madenauge töten","madenauges verbrechen","warum kopfgeld auf madenauge"}},{q="Wo ist Madenauge gewöhnlich zu finden?",a="Madenauge lauert in einer alten, verfallenen Hütte in Garrens Schlupfwinkel, einem verwüsteten Gehöft nördlich von Brill.",al={"madenauge aufenthaltsort","wo ist madenauge","madenauge finden"}},{q="Wer zahlt das Kopfgeld aus?",a="Exekutor Zygand im Zentrum von Brill nimmt den Beweis für seinen Tod entgegen und zahlt im Auftrag der Militärführung der Verlassenen die Belohnung der Stadt aus.",al={"bei wem madenauge abgeben","madenauge quest abgeben","wer zahlt kopfgeld in brill"}},{q="Warum will Exekutor Zygand seine Tatze?",a="Exekutor Zygand verlangt Madenauges Tatze als eindeutigen Beweis für dessen Tod, bevor das Kopfgeld ausgezahlt wird.",al={"warum madenauges tatze","tatze als beweis","madenauges tatze"}},{q="Sind Gnolle mit der Geißel verbündet?",a="Gnolle handeln gewöhnlich aus eigenem Antrieb, getrieben von Hunger und Gier. Doch Madenauge liefert der Geißel Leichen und macht sich damit zu einem gefährlichen Helfershelfer.",al={"gnolle und geißel","arbeiten gnolle für den lichkönig","geißel gnolle"}}},fx={aae6cd91={q="Warum benötigt Brill einen Abenteurer, um sich um Madenauge zu kümmern?",a="Die Verlassenen in Brill sind vollauf damit beschäftigt, die Ordnung aufrechtzuerhalten und Tirisfal vor aktiven Überfällen der Geißel und den Bedrohungen des Scharlachroten Kreuzzugs zu schützen. Anstatt ihre Stadtwache durch die Entsendung von Soldaten zur Suche nach marodierenden Plünderern zu schwächen, setzen Exekutor Zygand und die Stadtführung Belohnungen aus. Indem sie fähige Reisende und aufstrebende Helden zur Hilfe rufen, kann Brill regionale Bedrohungen beseitigen, ohne die örtliche Garnison zu schwächen.",al={"warum ich madenauge","warum töten wachen madenauge nicht","warum abenteurer für madenauge anheuern"}}},fp="18,245,13.245.0,16.357.0,18.175.0,34.183.0,34.91.0,35.139.0,38.96.0,35.147.0"}
P.entries["quest:399"] = {n="Ein bescheidener Anfang",s="Am Kathedralenplatz bittet Baros Alexston Euch, den niedergebrannten Bauernhof seiner Familie in Westfall zu durchsuchen. Diebe halten die Ruinen besetzt, und er hofft, den Kompass zurückzubekommen, den er als Junge so schätzte.",h="Am Kathedralenplatz bittet Baros Alexston Euch, den niedergebrannten Bauernhof seiner Familie in Westfall zu...",kw={"alexstons bauernhof","baros alexston","kathedralenplatz","ein bescheidener anfang","späherkuppe","einfacher kompass","sturmwind","westfall"},ang={["faction:Alliance"]="Wenn Ihr Euch für die Menschen in der Hauptstadt nach Westfall wagt, verlasst Ihr Sturmwinds sichere Straßen und betretet nahe gelegene, schutzlose Grenzlande.",["race:Human"]="Das Schicksal von Alexstons Bauernhof spiegelt den Niedergang der freien Bauern von Westfall wider. Generationen menschlicher Bauern wurden durch die Gesetzlosigkeit vor Sturmwinds Toren von ihrem Land vertrieben."},sec={{t="Die Wurzeln eines Baumeisters",b="Baros Alexston bestellte einst die Felder von Westfall. Heute ist er der versierte Architekt von Sturmwind und berät in Fragen des Mauerwerks und der städtischen Bauten. Nur wenige im Königreich haben einen solchen Weg vom Bauernhof in die Stadt zurückgelegt. Doch Baros bleibt den bescheidenen Anfängen verbunden, die ihn geprägt haben."},{t="Tragödie in Westfall",b="Gesetzlosigkeit breitete sich in Westfall aus und erreichte Alexstons Bauernhof. Banditen und Landstreicher brannten das Haus nieder und beraubten Baros' Vater seiner Lebensgrundlage. Familienerbstücke blieben inmitten von Feuer und Besetzung zurück. Nun bittet Baros Euch, den zerstörten, von Banditen besetzten Bauernhof westlich der Späherkuppe nach seinem ersten Kompass zu durchsuchen, der vor dem Untergang des Hauses versteckt wurde."}},faq={{q="Wer ist Baros Alexston?",a="Baros Alexston ist der Stadtarchitekt von Sturmwind und wohnt nahe dem Kathedralenplatz. Er wuchs als Bauernsohn in Westfall auf und verließ dann das Land, um das Bauhandwerk zu erlernen.",al={"baros alexston","wer ist baros","stadtarchitekt"}},{q="Wo liegt Alexstons Bauernhof?",a="Alexstons Bauernhof liegt westlich der Späherkuppe im Herzen von Westfall. Diebe und Schurken, die mit dem Defias-Gesindel verbündet waren, brannten ihn nieder und übernahmen das Anwesen.",al={"alexstons bauernhof lage","wo ist der bauernhof","alexstons bauernhof"}},{q="Warum ist der Kompass für Baros wichtig?",a="Der Kompass ist Baros wegen seines ideellen Wertes wichtig. Er war sein erstes Navigationsinstrument als Junge auf dem Bauernhof und erinnert an seinen Weg vom Landarbeiter zum Bauplaner. In seinem heutigen Handwerk hat er keinen Nutzen, bleibt aber ein unersetzliches Andenken an seine Vergangenheit.",al={"warum kompass","was ist der kompass","einfacher kompass"}},{q="Wer hat Alexstons Bauernhof niedergebrannt?",a="Diebe und Gesetzlose, die Westfall terrorisierten, machten den Bauernhof dem Erdboden gleich. Sturmwinds Truppen waren weit verstreut und konnten abgelegene Gehöfte nicht schützen, sodass Banditen das Land an sich rissen und die Familie Alexston vertrieben.",al={"wer hat den bauernhof niedergebrannt","warum wurde der bauernhof zerstört","westfall bauernhof niedergebrannt"}},{q="Wo auf dem Bauernhof ist der Kompass zu finden?",a="Baros' Kompass wurde versteckt, bevor die Familie floh. Ihr könnt ihn in einer kleinen Truhe inmitten der verkohlten Ruinen des Haupthauses finden.",al={"kompass fundort","wo ist der kompass","versteckter kompass"}},{q="Was geschah mit Baros' Vater?",a="Baros' Vater überlebte den Überfall und floh vom Bauernhof. Er konnte ihren Besitz nicht durch die Flammen und an den Banditen vorbeitragen, erinnerte sich aber daran, wo die Familie wertvolle Andenken versteckt hatte.",al={"baros vater","alexston vater","wer ist baros vater"}}},fx={["64f512b7"]={q="Warum muss Baros Alexston seinen Kompass durch Euch zurückholen lassen?",a="Baros ist der Stadtarchitekt von Sturmwind und fest an seine Pflichten auf dem Kathedralenplatz gebunden, während Westfall völlig im Chaos versunken ist. Der Alexstons Bauernhof wurde von Defias-Dieben niedergebrannt und überrannt, was weit außerhalb der Reichweite seines alternden Vaters oder der vernachlässigten regionalen Behörden liegt. Als einfacher Stadtbeamter kann Baros nicht einfach selbst in das Banditengebiet marschieren, weshalb er auf einen fähigen Abenteurer angewiesen ist, der den Ruinen trotzt und sein Andenken zurückbringt.",al={"warum kann baros seinen kompass nicht holen","warum schickt man mich für den kompass","baros alexston warum ich"}}},fp="17,175,17.272.0,19.352.0,22.181.0,40.164.0,38.260.0,34.198.0,43.129.0,32.183.0"}
P.entries["quest:40"] = {n="Gefahr aus dem Wasser",s="Im östlichen Elwynn fürchtet Remy \"Zweifach\", dass sich eine Gefahr ausbreitet. Der Fischfang leidet und Reisende werden angegriffen, doch er bezweifelt, dass die Wache die Lage versteht.",h="Im östlichen Elwynn fürchtet Remy \"Zweifach\", dass sich eine Gefahr ausbreitet.",kw={"gefahr aus dem wasser","wald von elwynn","further concerns","goldhain","marschall dughan","murloc","remy zweifach"},ang={["faction:Alliance"]="Für die Allianz zeigt diese Warnung, wie überlastet Sturmwinds Heimatwache ist und wie sehr die Ortschaft auf unabhängige Abenteurer angewiesen ist, um Gerüchten nachzugehen.",["race:Human"]="Als Mensch erlebt Ihr, wie die östlichen Wasserwege nahe Eurer Heimat zu gefährlichen Jagdgründen für Wasserbestien werden."},sec={{t="Eine Bitte aus dem Osten",b="Auf der Suche nach Geschäften in Goldhain wird Remy unruhig, als Murlocs die Bäche hinauf und in seichte Binnengewässer schwimmen. Er bittet Vorübergehende, die Ortschaft zu warnen, bevor sich die Bedrohung weiter ausbreitet."},{t="Eine überlastete Garnison",b="Marschall Dughan hört den Bericht, zweifelt jedoch daran. Seine Garnison ist überlastet, und ohne bestätigte Erkenntnisse wird er seine wenigen Männer keinen Gerüchten über Fischmenschen in den östlichen Bächen nachschicken."}},faq={{q="Wer vergibt die Quest Gefahr aus dem Wasser?",a="Remy \"Zweifach\", ein Händler aus dem Rotkammgebirge, bittet Euch, seine Warnung in Goldhain im Wald von Elwynn zu überbringen.",al={"questgeber gefahr aus dem wasser","wer startet gefahr aus dem wasser","remy quest"}},{q="Warum ist Remy \"Zweifach\" wegen der Murlocs besorgt?",a="Remy hat gesehen, wie Murlocs die Flüsse im östlichen Elwynn hinaufschwimmen. Sie vertreiben die heimischen Fische und greifen Reisende entlang der Wasserwege an.",al={"warum hat remy angst","murlocproblem elwynn","gefahr aus dem wasser hintergrundgeschichte"}},{q="Warum schickt Marschall Dughan nicht sofort Truppen?",a="Marschall Dughan hält die Berichte für unbestätigt. Seine Garnison ist mit Gnollangriffen und organisiertem Banditentum beschäftigt, daher kann er ohne offizielle Späherberichte keine Soldaten entsenden.",al={"warum ignoriert dughan murlocs","marschall dughans reaktion","warum keine truppen im osten"}},{q="Wohin führt diese Quest als Nächstes?",a="Marschall Dughan sucht in Further Concerns nach verlässlicher Bestätigung durch Späher, bevor er königliche Mittel im Osten einsetzt.",al={"was folgt auf gefahr aus dem wasser","nächste quest nach gefahr aus dem wasser","further concerns quest"}},{q="Wo wird Gefahr aus dem Wasser abgegeben?",a="Ihr überbringt den Bericht Marschall Dughan direkt vor dem Gasthaus \"Zur Höhle des Löwen\" in Goldhain.",al={"wo gefahr aus dem wasser abgeben","gefahr aus dem wasser abgabe","dughan standort"}},{q="Zu welcher größeren Bedrohung gehören die Murlocs in Elwynn?",a="Murlocs wirken primitiv und unberechenbar, doch ihre Ausbreitung in Binnenseen wie Stonecairn Lake und den Kristallsee bedroht neben Gnoll- und Banditenangriffen den ländlichen Handel und die Landwirtschaft.",al={"murlocs in elwynn","sind murlocs in elwynn gefährlich"}}},fx={["3afc8cff"]={q="Warum schickt Remy einen Abenteurer, anstatt selbst mit Marschall Dughan zu sprechen?",a="Remy hat Marschall Dughan bereits direkt gewarnt, doch der Marschall tat seine Warnungen als Händlergerüchte ab. Da sich Dughan voll und ganz auf die Überfälle der Gnolle und die Defias-Banditen konzentriert, braucht Remy eine externe Stimme – einen unabhängigen Abenteurer –, um die Gefahr zu unterstreichen und die Garnison davon zu überzeugen, Truppen nach Osten zu entsenden.",al={"warum ich a fishy peril","warum kann remy nicht mit dughan sprechen","warum braucht remy mich"}}},fp="13,162,20.175.0,19.191.0,34.105.0,46.128.0,49.173.0,32.121.0,44.88.0,53.187.0"}
P.entries["quest:400"] = {n="Werkzeuge für Stahlrost",s="In Kharanos schickt Tharek Schwarzstein Euch mit Werkzeugen für Beldin Stahlrost im Depot nach Nordosten. Die Straße führt vom Ort zu den Mechanikern und Kriegsmaschinen, die sich dort versammelt haben.",h="In Kharanos schickt Tharek Schwarzstein Euch mit Werkzeugen für Beldin Stahlrost im Depot nach Nordosten.",kw={"bogenlichtschraubenschlüssel","beldin stahlrost","dun morogh","fangratsche","kharanos","pilot steinsegel","belagerungsmaschine","stahlrosts depot","tharek schwarzstein"},ang={["profession:Engineering"]="Beldin verlässt sich auf Präzisionswerkzeuge wie Bogenlichtschraubenschlüssel und Fangratschen. Ihre Belastung zeigt, wie sehr die mechanisierte Kriegsführung handwerklich gefertigte Werkzeuge beansprucht.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Eisenschmiedes Panzertruppen auf Feldwerkstätten wie Stahlrosts Depot angewiesen sind, damit Belagerungsmaschinen die gefrorenen Pässe durchqueren können.",["race:Gnome"]="Als Gnom erkennt Ihr Beldins Bogenlichtschraubenschlüssel und ausgeklügelte Ratschen als Präzisionsinstrumente, die von gnomischer Ingenieurskunst geprägt und an zwergische Panzerplatten angepasst wurden."},sec={{t="Ein Meister mit Werkzeugverschleiß",b="In ganz Dun Morogh gilt Beldin Stahlrost als der gewiefteste Belagerungsmaschinenmechaniker der Berge. Seine grobe Arbeitsweise zerbricht Bogenlichtschraubenschlüssel und andere Werkzeuge schneller, als die Lieferanten in Kharanos sie ersetzen können. Tharek Schwarzstein hat eine frische Ladung strapazierfähiger Ausrüstung bereitgestellt, also trägt ein Reisender auf dem Weg nach Nordosten die schwere Kiste zum Depot."},{t="Die Maschinen am Laufen halten",b="Stahlrosts Depot ist voller stillstehender Kriegsmaschinen und militärischer Reparaturaufträge. Zu Beldins aufgelaufenen Aufträgen gehören dringende Arbeiten an der Belagerungsmaschine von Pilot Steinsegel. Nur wenige Stunden vor Eurer Ankunft hat er seine letzte Fangratsche zerbrochen. Die Kiste wird gebraucht, um Eisenschmiedes gepanzerte Kettenfahrzeugflotte am Laufen zu halten."}},faq={{q="Wohin bringe ich die Werkzeuge?",a="Bringt die Werkzeuge von Kharanos aus nach Nordosten, die Straße entlang in Richtung Eisenschmiede. Beldin Stahlrost arbeitet in Stahlrosts Depot zwischen abgestellten Belagerungsmaschinen und Panzern.",al={"wo ist stahlrost","wo werkzeuge abliefern","beldin stahlrost standort"}},{q="Wer ist Beldin Stahlrost?",a="Beldin Stahlrost ist ein renommierter zwergischer Mechaniker, der sich auf Belagerungsmaschinen spezialisiert hat und Stahlrosts Depot in Dun Morogh betreibt. Er beaufsichtigt Reparaturen, Umbauten und Wartungsarbeiten für erfahrene Piloten im Dienst von Eisenschmiedes Panzertruppen.",al={"wer ist beldin","beldin hintergrund","belagerungsmaschinentechnik"}},{q="Warum zerbricht Beldin so viele Werkzeuge?",a="Belagerungsmaschinen sind gewaltige Kriegsmaschinen mit schwerer Panzerung und übergroßen Eisenbeschlägen. Ihre verstärkten Rümpfe erfordern Hebelwirkung und Kraft, wobei bei dringenden Reparaturen oft Bogenlichtschraubenschlüssel und Fangratschen zerbrechen.",al={"warum zerbrochene werkzeuge","bogenlichtschraubenschlüssel zerbrechen","stahlrost werkzeuge"}},{q="Wessen Belagerungsmaschine repariert Beldin?",a="Beldin repariert die Belagerungsmaschine von Pilot Steinsegel, einem erfahrenen zwergischen Piloten, der im Depot stationiert ist.",al={"pilot steinsegel panzer","welche maschine ist kaputt","steinsegel belagerungsmaschine"}},{q="Was ist Stahlrosts Depot?",a="Stahlrosts Depot ist eine Freiluftwerkstatt und ein Bereitstellungsplatz nordöstlich von Kharanos. Erfahrene Belagerungsmaschinenpiloten und Panzerbesatzungen kommen dort zusammen, um ihre gepanzerten Kettenfahrzeuge zu testen, einzustellen und zu reparieren.",al={"was ist das depot","zweck des depots","stahlrost werkstatt"}},{q="Warum bittet Tharek Schwarzstein einen Abenteurer, sie zu tragen?",a="Tharek Schwarzstein hat Stahlrosts jüngste Werkzeugbestellung zusammengestellt und braucht einen Reisenden auf dem Weg nach Nordosten, der die schwere Kiste trägt. Er bietet ein wenig Geld und stellt den Überbringer den erfahrenen Piloten weiter die Straße hinauf vor.",al={"warum mich fragen","tharek liefergrund"}}},fx={fd264fde={q="Warum möchte Tharek Schwarzstein, dass diese Werkzeuge geliefert werden?",a="Tharek betreibt den Versorgungshandel von Kharanos und hat gerade die neueste Bestellung von Beldin Stahlrost zusammengestellt. Beldin ist der beste Belagerungsmaschinentechniker in Dun Morogh, aber seine rauen Hände verschleißen empfindliche Ausrüstung wie Bogenlichtschraubenschlüssel in erschreckendem Tempo. Die Versorgung von Beldin stellt sicher, dass die zwergischen Belagerungsmaschinen, die die Straßen und Berge sichern, voll einsatzbereit bleiben.",al={"tharek schwarzstein beweggrund","warum werkzeuge für stahlrost liefern","warum stahlrost werkzeuge schicken"}}},fp="20,172,26.333.0,27.277.0,26.155.0,25.231.0,36.210.0,36.114.0,27.188.0,59.201.0"}
P.entries["quest:401"] = {n="Wartet, bis Sirra fertig ist",s="Im Rathaus von Dunkelhain schreibt Sirra Von'Indi, während er Calvinius' kryptische Notiz entschlüsselt. Beklemmende Furcht legt sich über den Raum, und die Worte des Einsiedlers deuten auf Gefahr hin.",h="Im Rathaus von Dunkelhain schreibt Sirra Von'Indi, während er Calvinius' kryptische Notiz entschlüsselt.",kw={"calvinius","dunkelhain","dämmerwald","ello schwarzhaupt","sirra von'indi","übersetzung"},ang={["class:Mage"]="Als Magier erkennt Ihr den dunklen, anhaltenden Nachhall einer verfluchten Botschaft, während ihr Inhalt enthüllt wird.",["faction:Alliance"]="Als Reisender der Allianz wisst Ihr, dass Dunkelhains zerbrechliche Sicherheit an einem seidenen Faden hängt."},sec={{t="Ein Augenblick der Übersetzung",b="Sirra Von'Indi hat die Notiz, die Calvinius aus seiner Abgeschiedenheit geschickt hat. Er unterstützt die Nachtwache und die Führung von Dunkelhain und braucht nur kurz, um die Botschaft zu entschlüsseln. Noch weiß er nicht, welche Schrecken die Worte verbergen."},{t="Ein unheilvoller Schauer",b="Als Sirra die Niederschrift beendet, erfüllt eine plötzliche Schwere den Raum, als fiele ein schwarzer Vorhang über die Region. Die Notiz warnt vor großer Gefahr für Dunkelhain. Calvinius' scheinbar harmlose Botengänge dienten einem finsteren, rachsüchtigen Plan."}},faq={{q="Wer ist Sirra Von'Indi?",a="Sirra Von'Indi ist ein Gelehrter im Rathaus von Dunkelhain. Er hilft Bürgermeister Ello Schwarzhaupt und den örtlichen Behörden, alte Schriften, seltsame Dokumente und verschlüsselte Botschaften aus der düsteren Wildnis des Dämmerwalds zu übersetzen.",al={"sirra von'indi","wer ist sirra","sirra dämmerwald"}},{q="Welche Notiz übersetzt Sirra?",a="Calvinius, der Einsiedler in einer Hütte nahe dem westlichen Rand des Dämmerwalds, hat die Notiz geschrieben. Ihr habt eine Reihe von Botengängen für ihn erledigt, bevor sie Sirra zur Übersetzung erreichte.",al={"was ist die notiz","calvinius notiz","was hat calvinius geschrieben"}},{q="Warum fühlt sich die Luft so schwer an, als er fertig ist?",a="Die Schwere ist ein Vorzeichen drohenden Unheils. Die Notiz bringt düstere Nachrichten für Dunkelhain, und ihre volle Bedeutung wird klar, sobald die Übersetzung Lord Ello Schwarzhaupt erreicht.",al={"warum wird die luft schwer","schwarzer vorhang über dem land","dämmerwald düstere luft"}},{q="Wer soll den übersetzten Brief als Nächstes erhalten?",a="Nach der Übersetzung bittet Sirra Euch, die schaurigen Worte quer durch den Raum zu Bürgermeister Ello Schwarzhaupt zu bringen, damit die Nachtwache sich auf das Kommende vorbereiten kann.",al={"wohin mit der übersetzung","wer bekommt die notiz als nächstes","nächster schritt nach sirra"}},{q="Ist Calvinius tatsächlich ein Feind von Dunkelhain?",a="Calvinius gibt sich als harmloser, zurückgezogen lebender alter Mann aus, der Hilfe zum Überleben braucht. Die Furcht, die sich ausbreitet, als Sirra fertig ist, deutet auf düstere Nachrichten für Dunkelhain hin, und die volle Bedeutung der Notiz wird klar, sobald sie Lord Ello Schwarzhaupt erreicht.",al={"ist calvinius böse","einsiedler feind","calvinius hintergrundgeschichte"}},{q="Warum müsst Ihr auf ihn warten?",a="Sirra braucht Zeit und Konzentration, um alte Geheimschriften zu übersetzen. Er entschlüsselt die Handschrift und die verschlüsselten Formulierungen des Einsiedlers, bevor er eine lesbare Niederschrift für den Bürgermeister anfertigt.",al={"warum auf sirra warten","wie lange warten","sirra warten"}}},fx={a1bfeb31={q="Warum übersetzt Sirra Von'Indi Calvinius' Notiz?",a="Sirra Von'Indi ist ein Gelehrter, der die Nachtwache und die Stadtführung bei Angelegenheiten unterstützt, die über gewöhnliche Patrouillen hinausgehen. Als Ihr ihm Calvinius' kryptisches Pergament brachtet, erforderte dessen seltsame Schrift eine sorgfältige Entzifferung. Er möchte es übersetzen, um die wahren Absichten des Hermit aufzudecken und festzustellen, ob eine anhaltende Gefahr Dunkelhain und seine leidgeprüften Bewohner bedroht.",al={"sirra von'indi motiv","warum calvinius' notiz übersetzen","warum hilft sirra beim übersetzen"}}},fp="24,159,23.219.0,16.242.1,22.218.0,31.165.1,45.169.2,46.164.0,46.240.2,32.164.0"}
P.entries["quest:4021"] = {n="Gegenangriff!",s="An Regthar Deathgates Außenposten westlich vom Wegekreuz rächen Kolkarkrieger ihre gefallenen Anführer. Verstärkung aus Desolace ist unter Kriegsfürst Krom'zar eingetroffen.",h="An Regthar Deathgates Außenposten westlich vom Wegekreuz rächen Kolkarkrieger ihre gefallenen Anführer.",kw={"brachland","bunker","zentauren","gegenangriff","das wegekreuz","desolace","kolkar","kromzar","regthar deathgate","kriegsfürst krom'zar"},ang={["class:Warrior"]="Als Krieger steht Ihr mit den Grunts des Außenpostens gegen wiederholte Zentaurenangriffe. Die Verteidigung verlangt Ausdauer an der Front und Disziplin im Kampf.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Bunker zu verteidigen und das Gebiet der Horde im zentralen Brachland zu sichern. Die Verteidigung schützt die Versorgungslinien zwischen Durotar, Mulgore und dem Wegekreuz.",["race:Tauren"]="Als Tauren helft Ihr, die Zentaurenbedrohung zurückzudrängen, die Euer Volk seit Generationen verfolgt. Krom'zars Niederlage bringt den Ebenen mehr Sicherheit."},sec={{t="Vergeltung aus Desolace",b="Die Kolkar wurden im Brachland gedemütigt. Barak Kodobane, Verog the Dervish und Hezrul Bloodmark sind tot und haben die verbliebenen Zentauren zerschlagen und führungslos zurückgelassen. Die Nachricht ihrer Niederlage gelangt über die Berge nach Desolace, in ihre angestammte Heimat. Dort sammeln sich abgehärtete Kolkarkrieger, statt sich im Buschland zu zerstreuen. Nach Blut und Vergeltung dürstend, ziehen sie ins Brachland und marschieren gegen die jungen Lager der Horde."},{t="Verteidigung der Bunker",b="Kolkarkrieger greifen die Hordebunker westlich vom Wegekreuz an, wo Regthar Totenfurt die Verteidigung befehligt. Wellen von Eindringlingen prallen auf die dort stationierten Grunts der Horde. Kriegsfürst Krom'zar führt die Kriegsschar an, und sein Banner vereint die Zentauren beim Angriff. Die Verteidiger müssen die Stellung halten, Krom'zar töten und sein Banner niederreißen, um die Zentaurenbedrohung in den zentralen Ebenen zu brechen."}},faq={{q="Warum greifen die Kolkar gerade diesen Außenposten an?",a="Regthar Totenfurt veranlasste die Tötung der Kolkaranführer rund um die Oasen des Brachlands. Durch den Fall ihrer Häuptlinge gedemütigt, marschieren die Zentauren gegen seine befestigten Bunker westlich vom Wegekreuz, um den verantwortlichen Kommandoposten der Horde anzugreifen.",al={"warum regthar angreifen","warum werden bunker im brachland angegriffen","grund für den gegenangriff der zentauren"}},{q="Woher kam diese Zentaurenverstärkung?",a="Die Verstärkung kommt über die westlichen Gebirgspässe aus Desolace, der rauen Heimat der meisten Zentaurenklans.",al={"woher kommen die kolkar","herkunft der kolkarverstärkung","zentauren aus desolace"}},{q="Wer ist Kriegsfürst Krom'zar?",a="Kriegsfürst Krom'zar führt die Kriegsschar der Kolkar aus Desolace an. Unter seinem Kriegsbanner stürmt er gegen Regthars Bunker. Die Verteidiger der Horde töten ihn und reißen es nieder.",al={"wer ist kromzar","krom'zars geschichte","kriegsfürst kromzar"}},{q="Erfährt Thrall von dieser Schlacht?",a="Ja. Regthar Totenfurt verspricht, Kriegshäuptling Thrall in Orgrimmar direkt einen offiziellen Bericht über die Schlacht zu senden. Er würdigt die Verteidigung des Brachlands.",al={"thrall gegenangriff","erfährt thrall davon","belohnung des kriegshäuptlings"}},{q="Was wird nach dieser Schlacht aus den Kolkar in der Region?",a="Krom'zars Niederlage zerschlägt die letzte organisierte Streitmacht der Kolkar im zentralen Brachland. Die Handelsrouten rund um das Wegekreuz sind gesichert, während die verbliebenen Stämme zersplittert und führungslos zurückbleiben.",al={"sind die kolkar besiegt","schicksal der zentauren im brachland","ende der kolkarquestreihe"}},{q="Wofür wird der Teil von Krom'zars Flagge verwendet?",a="Ein abgerissener Teil von Krom'zars Flagge beweist, dass der Kriegsfürst tot ist. Er kennzeichnet auch den Zusammenbruch der Zentaureninvasion.",al={"kromzars banner","bannerteil questgegenstand","warum das banner mitnehmen"}}},fx={f1fed609={q="Warum möchte Regthar Totenfurt, dass dies erledigt wird?",a="Eure unermüdliche Kampagne gegen die Kolkar-Anführer hat die Zentauren an den Rand des Abgrunds getrieben und eine Vergeltungsinvasion direkt aus Desolace provoziert. Regthar Totenfurt weiß, dass, wenn diese Rachestreitmacht die vorderen Bunker westlich vom Wegekreuz überrennt, der Stützpunkt der Horde im nördlichen Brachland fallen könnte. Den Gegenangriff niederzuschlagen und ihren Kriegsherrn zu töten, beendet ihre organisierte Bedrohung ein für alle Mal, sichert das Gebiet für die Horde und stellt sicher, dass Eure früheren Siege nicht umsonst waren.",al={"warum muss regthar das erledigen","regthar deathgate beweggrund","warum den kolkar-gegenangriff stoppen"}}},fp="14,176,23.443.0,22.390.1,51.237.0,49.110.0,24.154.0,36.145.1,54.197.1,48.120.0"}
P.entries["quest:403"] = {n="Das bewachte Fass mit Donnerbier",s="In Kharanos lagert das Bier der Familie Thunderbrew bewacht im Brauereikeller. Jarven wacht über die Vorräte.",h="In Kharanos lagert das Bier der Familie Thunderbrew bewacht im Brauereikeller.",kw={"dun morogh","zwergisches gebräu","das bewachte fass mit donnerbier","jarven donnerbräu","kharanos","donnerbier","brauerei donnerbräu"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass ein heimlicher Diebeszug im Keller schwieriger wird, wenn ein wachsamer Zwerg das Fass im Auge behält.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass es sich lohnt, das geheime Gebräu einer Familie mit Leib und Leben zu verteidigen. Jarvens beharrliche Wache im Keller liegt ihm im Blut."},sec={{t="Ein bewachter Keller",b="Jarven Donnerbräu bewacht die reifenden Fässer unter der Brauerei Donnerbräu in Kharanos. Wachen stehen neben den Fässern und schützen das Gebräu vor unbefugten Eingriffen oder Diebstahl."},{t="Familienstolz und Rivalitäten",b="Die Thunderbrews hüten ihre Rezepte streng, besonders das für das starke Donnerbier. Zwerge widmen dem Brauen dieselbe Sorgfalt wie dem Schmieden und dem Bergbau. Troggs schleichen in der Nähe umher, und rivalisierende Brauer wetteifern in der gesamten Allianz miteinander. So hält Jarven Wache, bis das Bier der Familie bereit zum Anstechen ist."}},faq={{q="Warum kann ich dieses Fass nicht öffnen?",a="Jarven Donnerbräu hält im Keller Wache. Solange er die Fässer bewacht, darf sich niemand an den Vorräten der Familie Thunderbrew zu schaffen machen.",al={"fass lässt sich nicht öffnen","warum darf ich das bier nicht anrühren","jarven bewacht fass"}},{q="Wer ist Jarven Donnerbräu?",a="Jarven Donnerbräu gehört zum Clan Thunderbrew und ist im Brauereikeller von Kharanos stationiert. Er bewacht die besten Biere der Familie und hält Diebe und Unruhestifter davon ab, sich daran zu schaffen zu machen.",al={"wer ist jarven","jarvens geschichte","zwerg im keller"}},{q="Wo befindet sich dieses Fass?",a="Das Fass lagert im Keller unter der Brauerei Donnerbräu in Kharanos, Dun Morogh.",al={"wo ist das bewachte fass","lage des kellers","thunderbrew keller"}},{q="Warum bewachen die Thunderbrews ihr Bier so streng?",a="Die Thunderbrews bewachen ihr Bier, weil das Brauen für Zwerge ein hochgeschätztes Handwerk und ein Familienerbe ist. Rivalisierende Brauer, Diebe, Troggs und Lepragnome bedrohen Fässer mit seltenen Jahrgängen des Donnerbiers.",al={"warum bier bewachen","bedeutung des biers der thunderbrews"}},{q="Gehört das zu einer anderen Quest?",a="Ja. Ihr helft Marleth Gerstenbräu bei Bitter Rivals, indem Ihr ein Fass mit Gerstenbräu zwischen die Donnerbierfässer der Thunderbrews schmuggelt.",al={"thunderbrew questreihe","für welche quest ist das"}},{q="Könnt Ihr Jarven ablenken oder weglocken?",a="Ja. Jarven hat den Befehl, die Vorräte nicht anzurühren, obwohl er zugibt, dass er nur zu gern Donnerbier kosten würde. Bringt ihm eines, und seine Aufmerksamkeit wendet sich von den Fässern ab.",al={"wie an jarven vorbeikommen","jarven ablenken"}}},fp="26,118,20.177.0,26.273.0,29.134.0,26.202.0,29.90.0,51.194.0,30.144.0,32.158.0"}
P.entries["quest:404"] = {n="Eine eitrige Aufgabe",s="Todeswache Dillinger schickt Euch von Brill nach Westen, um die alte Brücke gegen die Geißel zu verteidigen. Bringt Beweise für die Vernichtung der Toten zurück, damit Tirisfals Verteidiger die Straße frei halten können.",h="Todeswache Dillinger schickt Euch von Brill nach Westen, um die alte Brücke gegen die Geißel zu verteidigen.",kw={"eine eitrige aufgabe","brill","todeswache dillinger","eitrige klaue","verwüsteter leichnam","verrottende tote","geißel","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, Brill zu sichern und ihren Stützpunkt in den Östlichen Königreichen vor der Geißel zu schützen.",["race:Undead"]="Als Angehörige der Verlassenen nehmt Ihr persönlich Rache, wenn Ihr die Geißel vernichtet, jene Macht, die einst Euren Geist gefangen hielt."},sec={{t="Die Brücke halten",b="Brill bewacht eine Wegkreuzung im östlichen Tirisfal, wo die Geißel den Stützpunkt der Verlassenen bedroht. Die Toten ziehen westwärts über die Wasserläufe und sammeln sich um die baufällige alte Steinbrücke. Ohne Patrouillen, die sie zurückdrängen, könnten sie den Weg zwischen Brill und den westlichen Gehöften versperren."},{t="Groll gegen die Geistlosen",b="Für die Verlassenen ist die Geißel an ihren Grenzen mehr als eine Bedrohung, der sie sich stellen müssen. Jeder geistlose Ghul und jeder verrottende Leichnam erinnert an die Knechtschaft und die Qualen, denen sie unter Fürstin Sylvanas Windläufer entkamen. Todeswachen wie Dillinger empfinden grimmige Genugtuung dabei, ihre einstigen Peiniger zu zerschmettern. Abgetrennte Klauen beweisen, dass die geistlosen Toten endgültig zur Ruhe gebettet wurden."}},faq={{q="Wer vergibt diese Quest?",a="Todeswache Dillinger, ein Offizier der Wache der Verlassenen, erteilt den Auftrag am westlichen Ausgang von Brill in Tirisfal.",al={"questgeber","wo beginnt eine eitrige aufgabe","todeswache dillinger quest"}},{q="Warum will Todeswache Dillinger eitrige Klauen?",a="Die Klauen beweisen, dass die umherstreifenden Kreaturen der Geißel vernichtet und nicht bloß von der Hauptstraße vertrieben wurden.",al={"warum eitrige klauen","grund für klauen"}},{q="Wo sind die verrottenden Toten zu finden?",a="Die verrottenden Toten streifen durch die überwucherten Felder und an den Flussufern direkt westlich von Brill umher und sammeln sich um die alte Steinbrücke.",al={"verrottende tote fundort","wo sind die ghule","alte brücke standort"}},{q="Warum gibt es Geißel in Tirisfal?",a="Die Verlassenen entrissen der Geißel Lordaerons Hauptstadt und die umliegenden Lichtungen. Seitdem sind immer wieder Kreaturen der Geißel nach Tirisfal eingesickert und haben das Land westlich von Brill nahe der alten Brücke befallen.",al={"warum geißel hier","geißel in tirisfal"}},{q="Was geschieht nach Abschluss dieser Aufgabe?",a="Sobald die Brücke frei ist, führen Euch Schwierigkeiten auf den nahen Gehöften weiter nach Westen, um die überrannten Mühlen zu untersuchen.",al={"nächste quest","was folgt auf eine eitrige aufgabe"}},{q="Sind die Verlassenen und die Geißel nicht dasselbe?",a="Nein. Die Verlassenen sind Untote mit freiem Willen, die sich der telepathischen Kontrolle durch den Lich King entrissen haben und für ihre Freiheit kämpfen. Die Geißel bleibt eine Schar geistloser Knechte, gebunden an den Iron Will des Frozen Throne.",al={"unterschied zwischen verlassenen und geißel","sind nicht alle untot"}}},fx={["63865879"]={q="Warum möchte Todeswache Dillinger, dass dies erledigt wird?",a="Todeswache Dillinger ist damit beauftragt, Brill zu verteidigen und die umliegenden Zugangswege für die Verlassenen zu sichern. Gedankenlose Geißel-Kreaturen sind nach Tirisfal eingedrungen und haben sich an der alten Brücke westlich der Stadt versammelt. Wenn man sie nicht aufhält, bedrohen diese schlurfenden Leichen Reisende auf der Straße und testen die äußeren Grenzen der Siedlung, was ihre Vernichtung zu einer dringenden Frage der regionalen Verteidigung macht.",al={"dillinger beweggrund","warum verrottende tote töten","warum die geißel bei brill beseitigen"}},["53a3556c"]={q="Gegen wen werdet Ihr an der alten Brücke ausgesandt?",a="Ihr werdet gegen die verrottenden Toten und geschundenen Leichen ausgesandt, die das Gebiet in der Nähe der alten Brücke westlich von Brill befallen. Im Gegensatz zu den Verlassenen, die sich aus dem Griff des Lichkönigs befreit haben, um ihren freien Willen zurückzugewinnen, sind diese Kreaturen gedankenlose Überreste der Geißel-Seuche, die durch die Wälder wandern und jeden angreifen, der ihren Weg kreuzt.",al={"ziel verrottende tote","geschundene leichen alte brücke","wer ist die geißel bei brill"}},c7fe240d={q="Warum benötigt Dillinger Euch anstelle der Stadtwache?",a="Die Todeswachen, die in Brill stationiert sind, sind an ihre Wachtposten gebunden und bewachen die Tore des Dorfes, Nebengebäude und Versorgungswege gegen plötzliche Überfälle. Da die Geißel auf den westlichen Straßen umherzieht und feindliche Kräfte anderswo Druck ausüben, kann Dillinger seinen Posten nicht verlassen, um die Brücke zu patrouillieren, was fähige Rekruten erfordert, um die Invasoren im Feld zu jagen.",al={"warum schickt mich dillinger","warum töten wachen die geißel nicht","warum kann dillinger es nicht tun"}}},fp="13,187,18.296.0,29.351.0,21.115.0,48.96.0,33.118.0,41.198.0,40.107.1,52.201.0"}
P.entries["quest:4041"] = {n="Das Videre-Elixier",s="Bringt Gregan Brewspewer eine Evowurzel, und er kann das Videre-Elixier brauen. Er prahlt mit seinem Wissen über Kräuter und Alchemie.",h="Bringt Gregan Brewspewer eine Evowurzel, und er kann das Videre-Elixier brauen.",kw={"alchemie","evowurzel","feralas","gregan brewspewer","miblon","videre-elixier"},sec={{t="Eine Evowurzel für den Brauer",b="Gregan Brewspewer braucht eine Evowurzel, bevor er Euer Videre-Elixier brauen kann. Er prahlt damit, sehr viel über Kräuter und Alchemie zu wissen, und beginnt dann eine Geschichte darüber, wie er den fürs Mittagessen gedachten Käse in Gold verwandelte. Als Ihr weggeht, fragt er, wohin Ihr geht. Fragt Gregan, wo eine Evowurzel zu finden ist."},{t="Wenn die Evowurzel eintrifft",b="Wenn Ihr mit der Evowurzel zurückkehrt, begrüßt Euch Gregan mit einer Behauptung: Ihr hättet den alten Miblon übers Ohr gehauen."}},faq={{q="Wer braut das Videre-Elixier?",a="Gregan Brewspewer kann das Videre-Elixier brauen, sobald Ihr ihm eine Evowurzel bringt.",al={"wer gibt das videre-elixier","wo gibt es das videre-elixier"}},{q="Welche Zutat wird für das Elixier benötigt?",a="Gregan braucht eine Evowurzel, um das Elixier herzustellen. Fragt ihn, wo eine zu finden ist.",al={"zutaten für das videre-elixier","was braucht gregan"}},{q="Womit prahlt Gregan Brewspewer?",a="Gregan prahlt damit, sehr viel über Kräuter und Alchemie zu wissen. Er beginnt eine Geschichte darüber, wie er einen Käse fürs Mittagessen in Gold verwandelte.",al={"gregan brewspewer prahlt","gregan kräuter und alchemie"}}},fp="17,119,25.299.0,24.102.1,28.75.0,47.70.0,40.133.0"}
P.entries["quest:405"] = {n="Der abtrünnige Lich",s="In Unterstadt sucht Bethor Eismacht einen Agenten für eine Angelegenheit um einen abtrünnigen Lich. Nach Eurem Einsatz gegen Überreste der Geißel und Moderfellgnolle in Brill schickt Euch Magistrat Sevren mit Befehlen nach Süden.",h="In Unterstadt sucht Bethor Eismacht einen Agenten für eine Angelegenheit um einen abtrünnigen Lich.",kw={"bethor eismacht","brill","magieviertel","magistrat sevren","der abtrünnige lich","sevrens befehle","tirisfal","unterstadt"},ang={["class:Mage"]="Als Magier erstattet Ihr Bethor Eismacht Bericht, einem der mächtigsten Meister der Arkan- und Frostmagie unter den Verlassenen.",["faction:Horde"]="Als Mitglied der Horde stärkt Ihr durch die Gewinnung ungebundener oder mächtiger nekromantischer Kräfte die unsichere Herrschaft der Verlassenen über Lordaerons Ruinen gegen gemeinsame Feinde.",["race:Undead"]="Als Untoter führen Euch Eure ersten direkten Befehle aus der Hauptstadt vom örtlichen Milizdienst in Brill zur Umsetzung der umfassenderen Ziele von Unterstadt."},sec={{t="Ruf in die Hauptstadt",b="Euer Dienst in Brill hat Euch Magistrat Sevrens Vertrauen für größere Aufgaben im Dienste der Verlassenen eingebracht. Er schickt Euch zu Bethor Eismacht, einem mächtigen Magier im Magieviertel von Unterstadt. Bethor verlangt einen im Kampf gegen die Geißel erprobten Agenten, und Sevren gibt Euch offizielle Befehle für die Gänge der Verlassenenhauptstadt unter den Ruinen von Lordaeron."},{t="Ein abtrünniger Lich",b="Magistrat Sevren kennt nicht alle Einzelheiten, doch die Befehle betreffen die Suche nach einem abtrünnigen Lich und dessen Anwerbung. Liche gehören zu den tödlichsten Zauberwirkern der Geißel, weshalb der Umgang mit einem von ihnen gefährlich ist. Ihr bringt Bethor die Befehle oben auf seinem arkanen Sanktum. Der eisige Magier will sehen, ob Brills Magistrat jemanden geschickt hat, der stark genug ist, eine solch gefährliche Beute aufzuspüren."}},faq={{q="Wer schickt mich auf diese Mission?",a="Magistrat Sevren, der als Amtsträger der Verlassenen Brill in Tirisfal verwaltet, schickt Euch mit schriftlichen Befehlen zu Bethor Eismacht.",al={"wer vergibt der abtrünnige lich","questgeber der abtrünnige lich","sevrens befehle"}},{q="Wo finde ich Bethor Eismacht?",a="Bethor Eismacht hält sich im Magieviertel von Unterstadt auf, oben auf dem erhöhten Bauwerk in der Mitte, das von arkanen Energien umgeben ist.",al={"wo ist bethor","bethor eismacht aufenthaltsort","bethor finden"}},{q="Welche Mission wird in den Befehlen erwähnt?",a="Bethor beabsichtigt, einen umherwandernden, abtrünnigen Lich anzuwerben. Zunächst braucht er einen Agenten, der Hinweisen auf die Identität und den Aufenthaltsort des Lichs nachgehen kann.",al={"was ist die lichmission","wer ist der abtrünnige lich","zweck von der abtrünnige lich"}},{q="Warum verlangt Bethor einen im Kampf gegen die Geißel erprobten Agenten?",a="Liche beherrschen nekromantische Frost- und Todesmagie und waren ursprünglich an den Lich King gebunden. Wer einem Lich mit freiem Willen oder einem Einzelgänger unter ihnen gegenübertritt, muss bewiesen haben, dass er die Untoten der Geißel überleben kann.",al={"warum kampferfahrung gegen die geißel","warum braucht bethor einen agenten"}},{q="Welche Voraussetzung muss vor Erhalt dieser Quest erfüllt sein?",a="Bevor Ihr diese Befehle erhaltet, müsst Ihr Magistrat Sevrens früheren Auftrag „Graverobbers“ abschließen und Garrens Schlupfwinkel von Moderfellgnollen und Grabräubern befreien.",al={"vorquest zu der abtrünnige lich","der abtrünnige lich freischalten"}},{q="Was folgt nach der Meldung bei Bethor?",a="Nachdem Ihr Sevrens Befehle überbracht habt, bietet Bethor „The Lich's Identity“ an. Er schickt Euch los, um Artefakte und Hinweise zu untersuchen, die enthüllen könnten, wer dieses geheimnisvolle Wesen zu Lebzeiten war.",al={"was folgt auf der abtrünnige lich","folgequest zu der abtrünnige lich"}}},fx={a06b4328={q="Warum möchte Magistrat Sevren, dass dies erledigt wird?",a="Magistrat Sevren handelt auf direkten Befehl von Bethor Eismacht, einem mächtigen Magier, der in der Unterstadt wohnt. Bethor forderte ausdrücklich einen fähigen Agenten mit nachgewiesener Erfahrung im Kampf gegen die Geißel, um eine heikle und gefährliche Angelegenheit bezüglich eines abtrünnigen Lichs zu behandeln. Als zivile Autorität in Brill stellt Sevren sicher, dass die Befehle der Unterstadt prompt ausgeführt werden, indem er seinen fähigsten Streiter entsendet.",al={"warum sevren befiehlt","sevren beweggrund","warum schickt man mich zu bethor"}},["41da8612"]={q="Warum wählt Magistrat Sevren Euch für diese Mission aus?",a="Bethor Eismacht forderte ausdrücklich einen Agenten, der seinen Wert und seine Tapferkeit gegen die Geißel bereits unter Beweis gestellt hat. Anstatt normale Stadtwachen oder unerprobte Rekruten zu entsenden, wählte Sevren Euch, weil Eure jüngsten Aktionen um Brill gezeigt haben, dass Ihr sowohl die Widerstandsfähigkeit als auch die Fähigkeit besitzt, jeden gefährlichen Auftrag zu überleben, den Bethor geplant hat.",al={"warum ich der verlorene lich","warum wählt mich sevren aus","warum nicht die königliche wache"}}},fp="17,205,22.341.0,14.372.0,26.132.0,32.124.0,44.135.0,60.195.0,64.168.0,37.173.0"}
P.entries["quest:4062"] = {n="Aufstieg der Maschinen",s="In der Brennenden Steppe trugen die Maschinen Zeichen, die Euch nun zu Lotwil Veriatus führen.",h="In der Brennenden Steppe trugen die Maschinen Zeichen, die Euch nun zu Lotwil Veriatus führen.",kw={"ödland","brennende steppe","elementarsplitter-probe","g.l.a.","lotwil veriatus","der aufstieg der maschinen","theodora mulvadania"},sec={{t="Zeichen auf den Splittern",b="Die Splitter tragen die Aufschrift G.L.A., darunter eine Rangmarkierung. Die Maschinen, die Ihr in der Brennenden Steppe zerstört habt, trugen Rang IV, den Theodora für einen niedrigen Rang hält. Daher schickt Hierophantin Theodora Mulvadania Euch mit einem Probesplitter zu Lotwil Veriatus, der unter Gelehrten der Elementarwissenschaften hohes Ansehen genießt. Lotwil ist in einem Lager im Osten stationiert, wo er, so hofft Theodora, bei der Suche helfen kann."},{t="Was Lotwil sieht",b="Lotwil Veriatus wird kreidebleich, als Ihr ihm den Splitter zeigt. Er kennt die Zeichen."}},faq={{q="Wer schickt Euch zu Lotwil Veriatus?",a="Hierophantin Theodora Mulvadania schickt Euch mit einem Probesplitter der in der Brennenden Steppe zerstörten Maschinen zu Lotwil, damit er ihn untersucht.",al={"wer vergibt diese quest","questgeber","theodora mulvadania"}},{q="Wo befindet sich Lotwil Veriatus?",a="Lotwil Veriatus ist in einem Lager im Osten stationiert.",al={"wo ist lotwil","lotwil aufenthaltsort","lotwil veriatus lager"}},{q="Welche Markierungen befinden sich auf den Elementarsplittern?",a="Die Splitter tragen die Aufschrift G.L.A., darunter eine Rangmarkierung. Die zerstörten Maschinen trugen Rang IV.",al={"splitter-initialen","was bedeutet gla","rang iv"}},{q="Warum möchte Theodora, dass Lotwil den Splitter untersucht?",a="Lotwil genießt unter Gelehrten der Elementarwissenschaften hohes Ansehen, und Theodora hofft, dass er bei der Suche helfen kann.",al={"warum lotwil","warum lotwil befragen"}}},fp="24,85,19.382.0,16.79.1,33.134.0,33.51.0,42.89.0,51.104.0"}
P.entries["quest:407"] = {n="Felder des Kummers",s="In Brill erprobt Apotheker Johaan eine Waffe aus Kürbissen. Er tränkt sie mit seinem neuesten alchemistischen Gebräu und schickt Euch, einem gefangenen Scharlachroten Kreuzfahrer einen davon zu verfüttern.",h="In Brill erprobt Apotheker Johaan eine Waffe aus Kürbissen.",kw={"apotheker johaan","brill","gefangener scharlachroter zelot","felder des kummers","taverne zur galgenschlinge","getränkter kürbis","königliche apothekervereinigung","tirisfal"},ang={["faction:Horde"]="Als Mitglied der Horde mögt Ihr die biochemische Forschung der Königlichen Apothekervereinigung für die neuen Verbündeten der Verlassenen beunruhigend finden. Dennoch bleibt sie entscheidend dafür, Tirisfal für die Horde zu sichern.",["race:Undead"]="Als Verlassene seht Ihr die rücksichtslosen Maßnahmen, die Euer Volk zum Überleben ergreift, mit sterblichen Zeloten im Süden und den Armeen des Lich Kings im Norden."},sec={{t="Eine erfindungsreiche Waffe",b="Die Verlassenen stehen der Geißel im Norden und Vorstößen der Menschen im Süden gegenüber, weshalb Apotheker Johaan glaubt, dass sie jeden Vorteil nutzen müssen. Die Königliche Apothekervereinigung blickt über Klingen und dunkle Zauberei hinaus. Sie sucht unter den gewöhnlichen Erzeugnissen des Landes nach Waffen. Johaan hat Kürbisse vergiftet, die bei den sterblichen Bauern auf Sollidens Bauernhof gesammelt wurden. Er will beweisen, dass gewöhnliche Feldfrüchte im Dienste der Dunklen Fürstin tödlich gemacht werden können."},{t="Der Versuch im Keller",b="Unter der Taverne Zur Galgenschlinge in Brill wartet ein gefangener Scharlachroter Zelot in Ketten. Hunger hat den Gefangenen geschwächt, doch der Zelot trotzt den Verlassenen noch immer und ruft das Heilige Licht an, die Untoten zu läutern. Als ihm ein Kürbis angeboten wird, hält der Gefangene ihn für Nahrung und verschlingt ihn. Johaans Rezeptur verformt den Zeloten bald zu einem verrottenden Ghul, der leblos im Dreck zusammenbricht."}},faq={{q="Warum verwendet Apotheker Johaan einen Kürbis für sein Gift?",a="Johaan will beweisen, dass gewöhnliche Feldfrüchte zu Waffen gegen die Lebenden werden können. Die Königliche Apothekervereinigung versetzt Erzeugnisse von nahe gelegenen Bauernhöfen der Menschen mit alchemistischen Mischungen und nutzt so den Nahrungsbedarf ihrer sterblichen Feinde gegen sie.",al={"warum ein kürbis","warum kürbis vergiften","getränkter kürbis hintergrund"}},{q="Wer ist der Gefangene im Keller der Taverne?",a="Der Gefangene ist ein Gefangener Scharlachroter Zelot, ein Fanatiker des Scharlachroten Kreuzzugs, den Truppen der Verlassenen in Tirisfal gefangen genommen haben. Hunger und Isolation haben den Zeloten geschwächt, doch sein religiöser Eifer hält an, bis Nahrung auftaucht.",al={"wer ist der gefangene zelot","zelot in der galgenschlinge","brill keller gefangener"}},{q="Was geschieht mit dem Scharlachroten Zeloten, nachdem er den Kürbis gegessen hat?",a="Johaans Rezeptur wirkt fast augenblicklich und verformt den hungernden Zeloten zu einem verrottenden Ghul, der leblos im Dreck zusammenbricht.",al={"was geschieht mit dem zeloten","verwandlung des zeloten","wird der zelot zum ghul"}},{q="Wo liegt der Keller der Taverne Zur Galgenschlinge?",a="Der Keller liegt unter der Taverne Zur Galgenschlinge in Brill. Eine Rampe hinter dem vorderen Tresen führt zum Bereich, in dem Wachen der Verlassenen Gefangene festhalten.",al={"wie den keller finden","wo befindet sich der zelot","galgenschlinge kellereingang"}},{q="Was versucht die Königliche Apothekervereinigung hier zu erreichen?",a="Unter Fürstin Sylvanas Windläufer entwickelt die Königliche Apothekervereinigung biologische und alchemistische Wirkstoffe, um die Geißel und sterbliche Bedrohungen wie den Scharlachroten Kreuzzug zu vernichten. Ihre kleinen Experimente an Gefangenen in Brill dienen dazu, diese Gebräue zu erproben.",al={"ziel der apothekervereinigung","warum die seuche testen","königliche apothekervereinigung tirisfal"}},{q="Warum ist der Scharlachrote Kreuzzug in Tirisfal aktiv?",a="Der Scharlachrote Kreuzzug betrachtet alle Untoten als Abscheulichkeiten, die ausgerottet werden müssen, ob willenlose Geißel oder Verlassene mit freiem Willen. Seine Lager und Garnisonen im gesamten ehemaligen Königreich Lordaeron versuchen, das Land mit heiligem Feuer zurückzuerobern.",al={"scharlachroter kreuzzug tirisfal","warum sind die scharlachroten hier","präsenz des kreuzzugs in brill"}}},fx={["5c6a869b"]={q="Warum möchte Apotheker Johaan, dass dies erledigt wird?",a="Apotheker Johaan betrachtet den Zustand der Untoten der Verlassenen als eine wirksame Waffe gegen ihre Feinde. Zwischen der aus dem Norden marschierenden Geißel und den aus dem Süden eindringenden menschlichen Streitkräften gefangen, benötigen die Verlassenen rücksichtslose Methoden zum Überleben. Indem er einen tödlichen, chemisch veränderten Kürbis an einen gefangenen Feind liefert, will Johaan sein neuestes Gebräu im Feld testen und beweisen, dass selbst gewöhnliche landwirtschaftliche Erzeugnisse im Dienste der Dunklen Fürstin als Waffen eingesetzt werden können.",al={"johaan beweggrund","warum will johaan den kürbis geliefert haben","warum den kürbis testen"}}},fp="15,171,21.427.0,15.376.1,56.217.0,41.213.0,60.130.1,40.153.0,60.240.0,53.223.0"}
P.entries["quest:408"] = {n="Die Familiengruft",s="Die Streitkräfte der Geißel bedrängen die Verlassenen bei Agamands Mühlen. Von Brill aus entsendet Magistrat Sevren Agenten gegen die Untoten in der Familiengruft.",h="Die Streitkräfte der Geißel bedrängen die Verlassenen bei Agamands Mühlen.",kw={"gruft der familie agamand","agamands mühlen","brill","captain dargol","magistrat sevren","faulender ahne","geißel","die familiengruft","tirisfal","wehklagender ahne"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, Tirisfal zu sichern, die Präsenz der Horde in den Östlichen Königreichen zu festigen und unmittelbare Bedrohungen ihrer nördlichen Bastion zu beseitigen.",["race:Undead"]="Als Verlassener seht Ihr in Captain Dargol die Verkörperung der Knechtschaft unter dem Willen des Lichkönigs, der Euer Volk sich zu entziehen erkämpft hat. Die auferstandenen Ahnen niederzustrecken schützt die Verlassenen und hilft, ihre Heimat aus dem Griff der Geißel zu lösen."},sec={{t="Ein Foxtrott in Tirisfal",b="Die Verlassenen halten Tirisfal, doch die Geißel beherrscht noch immer weite Teile des Umlands. Agamands Mühlen mahlten einst Mehl für Lordaeron. Nun bieten die Mühlen der Geißel Unterschlupf. In Brill beobachtet Magistrat Sevren mit großer Sorge, wie sich der Feind sammelt. Jeder Landstrich, der an die Untoten verloren geht, schwächt die Unabhängigkeit der Verlassenen."},{t="Die Schändung der Gruft",b="Captain Dargol, ein skelettierter Kommandant, hat die Gruft der Familie Agamand zu seinem Hauptquartier gemacht. Mit Nekromantie erweckt er Generationen verstorbener Agamands als faulende und wehklagende Ahnen und verstärkt so seine Reihen. Magistrat Sevren entsendet Agenten der Verlassenen, um die Gruft zu säubern und ihre aufgeschreckten Toten wieder zur Ruhe zu betten. Er verlangt auch Dargols Kopf, um die Streitkräfte der Geißel im nördlichen Tirisfal zu schwächen."}},faq={{q="Wer ist Captain Dargol?",a="Captain Dargol ist ein skelettierter Offizier der Geißel mit Sitz in der Gruft der Familie Agamand. Er befehligt die örtlichen Streitkräfte der Geißel und erweckt mit Nekromantie die Ahnen der Agamands zum Kampf gegen die Verlassenen.",al={"captain dargol","wer ist dargol","dargols geschichte"}},{q="Warum sind Agamands Mühlen für Magistrat Sevren von Bedeutung?",a="Agamands Mühlen sind ein bedeutender Stützpunkt der Geißel nahe Brill und der Unterstadt. Captain Dargols wachsende Streitmacht aus auferstandenen Ahnen bedroht die Siedlungen der Verlassenen.",al={"warum es brill kümmert","sevren agamand","agamands bedeutung"}},{q="Wer sind die wehklagenden und faulenden Ahnen?",a="Die wehklagenden und faulenden Ahnen sind verstorbene Vorfahren der wohlhabenden Familie Agamand. Captain Dargols Nekromantie hat sie verdorben und an die Geißel gebunden.",al={"wehklagende ahnen","faulende ahnen","agamands ahnen"}},{q="Was geschieht nach Dargols Tod?",a="Wenn Ihr Captain Dargols Schädel zu Magistrat Sevren bringt, verliert die Geißel ihre zentrale Führung bei den Mühlen. Sevren preist den Sieg als entscheidenden Schlag für die Verlassenen und als frühen Schritt, um Lordaeron vom Einfluss des Lichkönigs zu befreien.",al={"folgen der gruft","ende der agamand-questreihe","dargol besiegt"}}},fx={["6458ecfa"]={q="Warum möchte Magistrat Sevren den Schädel von Dargol?",a="Magistrat Sevren verlangt den Schädel von Kapitän Dargol als unbestreitbaren Beweis dafür, dass der Geißel-Kommandant eliminiert wurde. Die Gruft der Familie Agamand dient als primäre Festung der Geißel im westlichen Tirisfal, und Sevren kann es sich nicht leisten, nur Gerüchte über Dargols Niederlage zu haben. Seinen abgetrennten Schädel nach Brill zurückzubringen, bestätigt, dass die Führung des Nekromanten zerschlagen und sein rituelles Erwecken der Agamand-Vorfahren gestoppt wurde.",al={"zweck dargols schädel","warum dargols schädel nehmen","wofür ist dargols schädel"}}},fp="16,136,21.330.0,17.375.0,22.181.0,56.159.0,42.161.0,36.253.1"}
P.entries["quest:409"] = {n="Treuebeweis",s="Gunther Arkanus prüft, ob Ihr den Verlassenen mit freiem Willen oder dem Lichkönig dient. Er schickt Euch aus, um Lillith Nefara herbeizurufen und zu vernichten, eine Agentin der Geißel nahe seiner Insel.",h="Gunther Arkanus prüft, ob Ihr den Verlassenen mit freiem Willen oder dem Lichkönig dient.",kw={"bethor eismacht","blendwassersee","kerze des heranlockens","gunther arkanus","lillith nefara","treuebeweis","altar der geißel","tirisfal"},ang={["class:Mage"]="Als Magier kennt Ihr die arkanen und nekromantischen Talente von Bethor Eismacht und Gunther Arkanus. Wenn Ihr Euer eigenes Können zeigt, gewinnt Ihr den Respekt eines mächtigen Magierkollegen.",["race:Undead"]="Als Verlassene habt Ihr ein persönliches Interesse daran, Gunthers Isolation zu beenden. Es zeigt einem Bruder im Untod, dass keiner von Euch der Geißel oder den Lebenden allein gegenübertreten muss."},sec={{t="Der Argwohn eines Einsiedlers",b="Gunther Arkanus lebt seit seiner Erweckung zum Untod auf einer Insel im Blendwassersee. Er verteidigt seine Freiheit erbittert. Bethor Eismacht verzauberte Gunthers Zauberbuch und fand am Abgesandten keinen Makel der Geißel. Doch weder Worte noch Zauber können Gunthers Argwohn besänftigen. Bevor er einem Außenstehenden vertraut, muss dieser durch entschlossene Gewalt seine Feindseligkeit gegenüber den Dienern des Lichkönigs beweisen."},{t="Der Tod Lillith Nefaras",b="Südlich von Gunthers Zuflucht kennzeichnet ein blutbefleckter Ritualaltar Lillith Nefaras Aufenthaltsort in Tirisfal. Sie ist eine furchterregende Agentin der Geißel. Eine Kerze des Heranlockens lockt sie aus den Schatten in den offenen Kampf. Ihre Niederlage widerlegt Gunthers lang gehegte Überzeugung, dass er allein unter den Untoten der Kontrolle des Lichkönigs entkommen sei."}},faq={{q="Warum braucht Gunther Arkanus einen Beweis?",a="Gunther hat als unabhängiger Untoter überlebt, indem er niemandem vertraute. Umgeben von der Geißel, dem Scharlachroten Kreuzzug und anderen Bedrohungen in Tirisfal verdächtigt er jeden untoten Besucher, dem Lichkönig zu dienen, bis dieser Geißelblut vergießt.",al={"warum zweifelt gunther an mir","gunthers vertrauen"}},{q="Wer ist Lillith Nefara?",a="Lillith Nefara ist eine mächtige Agentin der Geißel, die am Südufer des Blendwassersees tätig ist. Sie dient dem Lichkönig von einem uralten, blutigen Altar nahe Gunthers Insel aus.",al={"wer ist lillith","lillith nefara hintergrund"}},{q="Was ist die Kerze des Heranlockens?",a="Die Kerze des Heranlockens ist ein Ritualgegenstand aus einer Kiste auf Gunthers Insel. Stellt sie auf den blutigen Altar und entzündet sie, um Lillith Nefara von ihrer Ruhestätte herbeizurufen und Euch ihr im Kampf zu stellen.",al={"kerze des heranlockens","wie lillith herbeirufen"}},{q="Zu welcher Erkenntnis gelangt Gunther nach Lilliths Niederlage?",a="Lilliths Niederlage lässt Gunther einsehen, dass er nicht einzigartig ist. Bis dahin glaubte er, der einzige Untote in Lordaeron zu sein, der sich aus der telepathischen Herrschaft des Lichkönigs befreit hatte.",al={"gunthers reaktion","gunthers erkenntnis"}},{q="Wo findet diese Konfrontation statt?",a="Die Konfrontation findet an einem Altar am Seeufer unmittelbar vor der Südküste von Gunthers Insel im Blendwassersee im Osten Tirisfals statt.",al={"wo ist der altar","lilliths aufenthaltsort"}},{q="Was geschieht nach Eurem Treuebeweis?",a="Sobald Gunthers Zweifel ausgeräumt sind, erklärt er sich bereit, die Abgesandten Unterstadts anzuhören und sein einsames Exil zu überdenken. Dies ebnet den Weg für seine förmliche Aufnahme in die Reihen von Lady Sylvanas' Verlassenen.",al={"was kommt nach treuebeweis","nach lilliths tod"}}},fx={["74408c95"]={q="Warum braucht Gunther Euch, um Lillith zu zerstören, anstatt es selbst zu tun?",a="Gunther Arkanus bittet nicht nur darum, ein lästiges Insekt zu beseitigen; er stellt Eure Loyalität auf die Probe. Er hat in Isolation gelebt und glaubte, die einzige untote Seele zu sein, die den eisernen Griff des Lichkönigs gebrochen hat. Während Ihr behauptet, dass Ihr und die Verlassenen diese Unabhängigkeit teilen, reichen Worte und magische Schutzzauber allein ihn nicht zufrieden. Euch damit zu beauftragen, einen aktiven Geißel-Kommandanten zu beschwören und zu vernichten, zwingt Euch dazu zu demonstrieren, dass Ihr wirklich gegen den Lichkönig steht, bevor er seine Deckung senkt.",al={"warum ich gunther","warum tötet gunther lillith nicht","warum schickt man mich zur beweisprüfung"}}},fp="18,170,22.392.0,29.322.1,36.232.0,22.169.0,32.191.0,60.178.1,41.155.0,43.190.1"}
P.entries["quest:410"] = {n="Der Schlummernde Schatten",s="An Gunthers Zufluchtsort im Blendwassersee ruft ein dunkler Ritus nach Lillith Nefara. Stellt eine mystische Kerze auf den alten, blutgetränkten Tisch, um die Geißelagentin zu beschwören und Gunther Arkanus zu beweisen, dass Ihr Euch dem Lichkönig widersetzt.",h="An Gunthers Zufluchtsort im Blendwassersee ruft ein dunkler Ritus nach Lillith Nefara.",kw={"blutiger tisch","kerze des heranlockens","schlummernder schatten","ritual der verlassenen","lillith nefara","proving allegiance","tirisfal"},ang={["class:Priest"]="Als Priester erkennt Ihr den schattenhaften Ruf der Kerze, der eine verweilende Seele zurück in den Kampf zieht.",["class:Warlock"]="Als Hexenmeister wisst Ihr, wie Geister an blutgetränkte Altäre gebunden werden können. Dieser Ritus prüft Eure Macht über die Grenze zwischen Leben und Tod.",["race:Undead"]="Als Verlassener vollzieht Ihr einen düsteren Ritus über einem blutigen Altar in Tirisfal, wo Tod und dunkle Magie Eure neue Existenz und Treue zur Dark Lady prägen."},sec={{t="Ein grausiger Altar",b="An Gunthers Zufluchtsort, einer Insel im Blendwassersee, steht ein ramponierter, blutbefleckter Esstisch. Er ist kein verlassenes Möbelstück. Dunkle Beschwörungsmagie sammelt sich um die grobe Platte, auf der getrocknetes Blut den Ort von Tod und Magie kennzeichnet."},{t="Die Kerze des Heranlockens",b="Stellt die Kerze des Heranlockens auf den blutigen Tisch und entzündet sie. Lillith Nefaras Geist antwortet von jenseits des Todes. Die Flamme ruft die Geißelagentin aus ihrer Ruhe und macht sie zur Prüfung für jene, die ihre Treue beweisen wollen."}},faq={{q="Welchen Zweck hat es, die Kerze auf dem Tisch zu entzünden?",a="Das Entzünden der Kerze des Heranlockens auf dem ramponierten, blutigen Tisch beschwört Lillith Nefara, einen gefährlichen Schatten, den Ihr besiegen müsst.",al={"warum kerze entzünden","ziel des schlummernden schattens","tischritual"}},{q="Wer wird durch dieses Ritual beschworen?",a="Das Ritual beschwört Lillith Nefara, einen untoten Geist und eine Geißelagentin, die an Gunthers Zufluchtsort im Blendwassersee in Tirisfal spukt.",al={"wer erscheint","schlummernder schatten geist","wer ist der schatten"}},{q="Wie hängt dies mit dem Treuebeweis gegenüber den Verlassenen zusammen?",a="Lillith Nefara zu beschwören und zu besiegen beweist dem zurückgezogen lebenden Gunther Arkanus, dass Ihr Euch der Geißel widersetzt und nicht den Zwecken des Lichkönigs dient.",al={"verbindung zu proving allegiance","warum lillith töten","prüfung der verlassenen"}},{q="Wo findet dieses Ritual statt?",a="Das Ritual findet an Gunthers Zufluchtsort statt, Gunther Arkanus' Insel im Blendwassersee in Tirisfal. Ein ramponierter, mit getrocknetem Blut befleckter Esstisch steht direkt vor der Südküste der Insel.",al={"standort des tisches","wo ist der tisch","lilliths esstisch"}},{q="Kann jeder die Kerze entzünden?",a="Jeder, der die Kerze des Heranlockens besitzt und sich den Treueprüfungen der Verlassenen stellt, kann sie auf dem Altar entzünden.",al={"wer kann das ritual durchführen","klassenanforderungen","kerzenritual"}},{q="Spukt es von Natur aus an dem Tisch?",a="Der Tisch ist ein alter, blutiger Altar, den die Geißelagentin Lillith Nefara nutzt. Die Kerze des Heranlockens dort zu entzünden weckt sie aus ihrer Ruhe.",al={"ist der tisch magisch","warum der blutige tisch"}}},fx={["7957b0ef"]={q="Wofür wird die Kerze des Heranlockens verwendet?",a="Die Kerze des Heranlockens ist ein verzauberter Gegenstand, der speziell dafür geschaffen wurde, den Schleier zu überbrücken und den ruhenden Geist herbeizurufen, der um Gunthers Zufluchtsort am Blendwassersee verweilt. Wenn sie auf den blutverschmierten Esstisch gestellt und angezündet wird, fungiert ihre dunkle Flamme als Leuchtfeuer, das den ruhelosen Schatten von Lillith Nefara in die physische Welt ruft, damit Ihr Euch ihr stellen könnt.",al={"nutzen kerze des heranlockens","was macht die kerze des heranlockens","zweck der lockkerze"}}},fp="17,216,16.239.0,23.237.1,56.121.0,31.138.0,59.145.0,34.201.0,28.113.0,31.139.0"}
P.entries["quest:411"] = {n="Die Rückkehr des abtrünnigen Lichs",s="In Unterstadt bringt Ihr Bethor Eismacht einen Netheredelstein, nachdem Ihr Gunther Arkanus' Vertrauen gewonnen und sein Grimoire wiederhergestellt habt.",h="In Unterstadt bringt Ihr Bethor Eismacht einen Netheredelstein, nachdem Ihr Gunther Arkanus' Vertrauen...",kw={"arkanus","bethor","blendwassersee","gunther","eismacht","lich","netheredelstein","abtrünnig","unterstadt"},ang={["class:Mage"]="Bethors Zwiesprache mit Gunther verbindet die traditionelle Zauberkunst Dalarans mit der dunklen Nekromantie, die im Magieviertel von Unterstadt praktiziert wird.",["faction:Horde"]="Die Anwerbung eines unabhängigen Meisternekromanten wie Gunther stärkt die magische Stellung der Horde in den Östlichen Königreichen.",["race:Undead"]="Gunthers Freiheit ohne die Hilfe der Banshee Queen zeigt, welche Willenskraft die Gefallenen Lordaerons aufbringen können."},sec={{t="Eine seltene Versöhnung",b="Gunther Arkanus verbrachte Jahre allein auf einer Insel im Blendwassersee. Allein durch Willenskraft entkam er der Kontrolle des Lichkönigs, ohne zu wissen, dass Sylvanas Windläufer Lordaeron befreit hatte. Verbittert und argwöhnisch misstraute er den Abgesandten aus Unterstadt. Ein Abenteurer brachte sein Zauberbuch zurück und zeigte ihm seine Feindseligkeit gegenüber der Geißel. Überzeugt, dass der Besucher kein Feind war, vertraute Gunther ihm einen Netheredelstein an, um seinen früheren Kollegen zu kontaktieren."},{t="Zwiesprache im Magieviertel",b="Ihr bringt den Netheredelstein zu Bethor Eismacht ins Magieviertel von Unterstadt. Bethor kanalisiert seine Macht und ruft Gunthers ätherisches Antlitz ins Sanktum. Durch ihre magische Zwiesprache erklärt sich Gunther förmlich bereit, sich der Sache der Verlassenen anzuschließen. Ein Nekromant von seiner unabhängigen Meisterschaft stärkt das junge Königreich der Dunklen Fürstin und dessen magische Verteidigung gegen die Geißel und die Lebenden."}},faq={{q="Wer ist Gunther Arkanus?",a="Gunther Arkanus ist ein mächtiger Nekromant, der sich aus eigener Kraft von der geistigen Herrschaft des Lichkönigs befreite. Er lebte zurückgezogen im Exil auf einer Insel im Blendwassersee und hielt andere Untote für willenlose Sklaven, bis Abenteurer ihn vom Gegenteil überzeugten.",al={"gunther arkanus hintergrund","wer ist der prodigal lich","gunther unterstadt"}},{q="Wer ist Bethor Eismacht?",a="Bethor Eismacht ist ein hochrangiger Magier und Gelehrter, der im Magieviertel von Unterstadt lebt. Als alter Kollege von Gunther Arkanus koordinierte er die Bemühungen, ihn zu finden und für die Verlassenen zu gewinnen.",al={"bethor hintergrund","wer ist bethor","eismacht unterstadt"}},{q="Was bewirkt der Netheredelstein?",a="Gunther Arkanus gab Bethor Eismacht den Netheredelstein, ein verzaubertes Artefakt. Wenn Bethor arkane Macht hinein kanalisiert, lässt der Edelstein ein geisterhaftes Abbild Gunthers erscheinen, damit die Zauberwirker über große Entfernungen miteinander sprechen können.",al={"was ist der netheredelstein","gunther edelstein"}},{q="Warum schließt sich Gunther den Verlassenen an?",a="Gunther fürchtete jahrelang, der einzige Untote Lordaerons mit freiem Willen zu sein. Überzeugt, dass Sylvanas' Verlassene frei von der Geißel sind und den Lichkönig bekämpfen, schwört er freiwillig die Treue und erneuert die Verbindung zu seinen früheren Gefährten.",al={"warum den verlassenen beitreten","gunther treue"}},{q="Warum bezeichnet die Quest Gunther als einen „Lich“?",a="Gunther sieht aus wie jeder andere Verlassene, statt wie ein schwebender, frostumhüllter Lich der Geißel, doch die Verlassenen nennen ihn so. Zu Lebzeiten ein Schüler der Kirin Tor und fähiger Nekromant, wurde er im Dritten Krieg durch die Seuche auferweckt und befreite sich später selbst vom Lichkönig.",al={"ist gunther ein echter lich","gunther lichgestalt"}},{q="Was geschieht, wenn Ihr den Netheredelstein abgebt?",a="Wenn Ihr den Netheredelstein überbringt, aktiviert Bethor ihn und beschwört Gunther's Visage im Magieviertel. Die Projektion bewegt sich auf Bethor zu, um ihr lang ersehntes Wiedersehen einzuleiten, und verblasst dann.",al={"netheredelstein abgabe ereignis","was geschieht bei bethor"}}},fx={["5e5e694d"]={q="Warum benötigt Gunther Arkanus Euch, um den Netheredelstein zu überbringen?",a="Gunther Arkanus bleibt isoliert auf seiner Insel im Blendwassersee und wahrt seine vorsichtige Zurückgezogenheit, während er wieder Kontakt zur Außenwelt aufnimmt. Als ein Abgesandter, der seine Loyalität durch das Wiederbeschaffen seines Zauberbuchs und die Vernichtung seiner nekromantischen Feinde bewiesen hat, habt Ihr Euch sein Vertrauen verdient. Indem er Euch den Netheredelstein übergibt, kann er seinen alten Kameraden Bethor Eismacht kontaktieren und über dessen Treue verhandeln, ohne seinen Zufluchtsort verlassen oder direkt in die Unterstadt marschieren zu müssen.",al={"warum spieler netheredelstein schicken","warum braucht gunther mich","warum den edelstein liefern"}}},fp="25,125,21.428.0,30.388.1,23.248.0,23.194.0,28.218.0,44.226.1,41.267.0,45.188.1"}
P.entries["quest:412"] = {n="Operation Rekombobulationsgerät",s="In Kharanos suchen Razzle Flinkspross und Ozzie Wechselvolt nach einem Heilmittel für ihre Artgenossen. Ihr experimenteller Rekombobulator benötigt Teile von feindseligen Lepragnomen vor Gnomeregan.",h="In Kharanos suchen Razzle Flinkspross und Ozzie Wechselvolt nach einem Heilmittel für ihre Artgenossen.",kw={"dun morogh","gnomeregan","gyromechanische getriebeteile","kharanos","lepragnom","ozzie wechselvolt","razzle flinkspross","rekombobulator","restabilisationszahnrad"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr Razzles unorthodoxe Arbeit mit Restabilisationszahnrädern, crank-o-ratchets und zähflüssigem electrogum gel zur Beeinflussung biophysikalischer Strahlung würdigen.",["race:Gnome"]="Für Gnome bietet diese Arbeit eine verzweifelte Hoffnung, Angehörige und Freunde zu retten, die beim Fall ihrer Hauptstadt zu gewalttätigen Hüllen ihrer selbst wurden."},sec={{t="Ein Heilmittel gegen die Katastrophe",b="Razzle und Ozzie bauen eine Maschine, die ihren erkrankten Artgenossen Gesundheit und Verstand zurückgeben soll. Strahlung verwandelte die meisten Gnome von Gnomeregan in kränkliche, geistig verwirrte Lepragnome. Die Erfinder hoffen, dass ihr Rekombobulator diese Verwandlung rückgängig machen kann."},{t="Bergung bei den Erkrankten",b="Razzle benötigt Restabilisationszahnräder und Gyromechanische Getriebeteile für den empfindlichen Prototyp. Die Teile müssen von feindseligen Lepragnomen vor Gnomeregans versiegelten Toren stammen. Trümmerteile von ihren verwandelten Artgenossen könnten helfen, ihre gemeinsame Tragödie rückgängig zu machen."}},faq={{q="Was soll der Rekombobulator bewirken?",a="Razzle Flinkspross und Ozzie Wechselvolt haben den Rekombobulator entwickelt, um die Auswirkungen von Gnomeregans Strahlung rückgängig zu machen und Lepragnome zu heilen.",al={"was ist der rekombobulator","zweck des rekombobulators","bedeutung von rekombobulieren"}},{q="Wer sind Razzle Flinkspross und Ozzie?",a="Razzle Flinkspross und Ozzie Wechselvolt sind gnomische Erfinder, die in Kharanos in Dun Morogh arbeiten. Seit Gnomeregans Fall setzen sie ihre Fähigkeiten dafür ein, Wege zur Rettung ihres vertriebenen, verstrahlten Volkes zu finden.",al={"wer ist razzle","wer ist ozzie wechselvolt","geschichte von razzle flinkspross"}},{q="Warum gibt es Lepragnome vor Gnomeregan?",a="Die während der Trogginvasion freigesetzte Strahlung konnte die Troggs nicht töten. Stattdessen trieb sie viele überlebende Gnome in den Wahnsinn und verwandelte sie in feindselige Lepragnome.",al={"warum sind gnome leprakrank","wie entstanden lepragnome","gnomeregans strahlung"}},{q="Woher stammen die Teile für den Rekombobulator?",a="Die Teile stammen von Lepragnomen vor Gnomeregans Eingang im Westen von Dun Morogh. Die erkrankten Gnome tragen noch immer geborgene mechanische Bauteile an ihren Körpern.",al={"woher zahnräder und getriebeteile bekommen","herkunft der restabilisationszahnräder","gyromechanische getriebeteile"}},{q="Funktioniert der Rekombobulator tatsächlich?",a="Razzle sagt, die richtigen Teile, hydrolubricant und Anpassungen am electrogum gel würden die Gnome wieder in ihren normalen Zustand versetzen. Gnomische Ingenieurskunst kann unberechenbar sein, und es bleibt ungewiss, ob die Maschine die Folgen giftiger Strahlung rückgängig machen kann.",al={"hat der rekombobulator sie geheilt","können lepragnome geheilt werden","erfolg des rekombobulators"}}},fx={["8df716ac"]={q="Warum möchte Razzle Flinkspross, dass dies erledigt wird?",a="Der Fall von Gnomeregan hat die Stadt nicht nur mit Troggs überflutet; die bei der Katastrophe freigesetzte Strahlung hat die große Mehrheit der gnomischen Bevölkerung in gedankenlose, feindselige verseuchte Gnome verwandelt. Razzle Flinkspross und sein Partner Ozzie weigern sich zu akzeptieren, dass ihr Volk für immer verloren ist. Sie glauben, dass ihre Erfindung, der Rekombobulator, die schrecklichen Leiden des Fallout umkehren und die gnomische Rasse in ihren ursprünglichen Zustand zurückversetzen kann.",al={"warum will razzle das","razzle beweggrund","warum den rekombobulator bauen"}},ed729e1a={q="Wofür sind die Restabilisierungsk Zahnräder und gyromechanischen Zahnräder?",a="Diese Präzisionskomponenten sind essentielle mechanische Teile, die benötigt werden, um den Bau des Rekombobulationsgeräts gemäß Ozzies komplizierten Schaltplänen abzuschließen. Sobald sie neben Hydroschmiermittel, Kurbel-o-ratschen und Elektrogummi-Gel in den Apparat eingebaut sind, werden die Zahnräder und Getriebe die Maschinerie ausbalancieren und regulieren, die dazu entwickelt wurde, die Strahlung rückgängig zu machen, die die verseuchten Gnome korrumpiert hat.",al={"was sind restabilisierungsk zahnräder","nutzen gyromechanische zahnräder","wofür sind die teile"}},c92cc687={q="Gegen wen werdet Ihr bei Gnomeregan ausgesandt?",a="Ihr werdet ausgesandt, um die verseuchten Gnome zu jagen, die vor den Eingangstoren von Gnomeregan herumschleichen. Früher gewöhnliche Bürger, wurden ihre Geister und Körper durch die giftige Strahlung verzerrt, die eingesetzt wurde, um die Trogg-Invasion zu säubern. Verrückt geworden, tragen sie nun die geplünderten Maschinen, Getriebe und Zahnräder aus der zerstörten Stadt, während sie jeden gewaltsam angreifen, der sich nähert.",al={"gegen wen kämpfe ich","feinde operation rekombobulation","ziel gnomeregan"}}},fp="25,184,23.239.0,29.233.0,42.140.0,38.212.0,46.159.0,52.164.0,38.227.0"}
P.entries["quest:4120"] = {n="Die Kraft der Verderbnis",s="Im Camp Mojache schickt Euch Talo Thornhoof nach Norden in den Teufelswald, um die Stärke seiner verderbten Bestien einzuschätzen.",h="Im Camp Mojache schickt Euch Talo Thornhoof nach Norden in den Teufelswald, um die Stärke seiner verderbten...",kw={"wutprankengrizzly","camp mojache","teufelsverderbnis","teufelspfotenverheerer","teufelswald","feralas","talo thornhoof"},sec={{t="Kennt Euren Feind",b="Talo Thornhoof jagt, indem er die Stärken seiner Feinde studiert. Er glaubt, dass die Kenntnis eines Feindes eine Schlacht zu Euren Gunsten wenden kann. Der Teufelswald liegt nördlich des Eschentals, wo Teufelsenergie die Kreaturen verdorben hat. Talo fürchtet, dass seine wahnsinnigen Bären und Wölfe stärker geworden sind. Stellt Euch dort zwölf Wutprankengrizzlys und zwölf Teufelspfotenverheerern. Von Teufelsenergie berührte Kreaturen leuchten in einem seltsamen Grün. Talo spürt, dass Teufelsenergie böse und doch sehr mächtig ist."},{t="Was Talo hört",b="Nachdem er Euren Bericht gehört hat, erkennt Talo geistlose Wildheit in den Bestien. Er mahnt Euch, wachsam zu bleiben und mehr über die Verderbnis zu erfahren. Einen Feind sollte man stets kennen."}},faq={{q="Wer schickt Euch in den Teufelswald?",a="Talo Thornhoof, ein Jäger im Camp Mojache in Feralas, schickt Euch in den Teufelswald.",al={"questgeber","wer vergibt die kraft der verderbnis","talo thornhoof standort"}},{q="Warum will Talo Thornhoof, dass Ihr Euch den Bestien des Teufelswalds stellt?",a="Talo glaubt, dass die Kenntnis eines Feindes eine Schlacht wenden kann, und will Euch herausfinden lassen, ob die teufelsverderbten Kreaturen des Teufelswalds so stark sind wie angenommen.",al={"warum die bären und wölfe töten","zweck von die kraft der verderbnis","talo thornhoof beweggrund"}},{q="Welche Kreaturen sind im Teufelswald die Ziele?",a="Ihr stellt Euch im Teufelswald zwölf Wutprankengrizzlys und zwölf Teufelspfotenverheerern.",al={"welche bestien","ziele im teufelswald","welche monster bekämpfen"}},{q="Was sagt Talo über Teufelsenergie?",a="Talo spürt, dass Teufelsenergie böse, aber sehr mächtig ist, und die Kreaturen, die sie berührt, leuchten in einem seltsamen Grün.",al={"was ist die verderbnis","grünes leuchten teufelswald","was ist teufelsenergie"}}},fp="26,103,15.412.0,15.168.1,25.74.0,57.139.0,40.74.0,29.98.0"}
P.entries["quest:4124"] = {n="Der vermisste Kurier",s="In der Mondfederfeste sucht Latronicus Moonspear Hilfe, nachdem ein Kurier verschwunden ist. Der Kurier und seine Pakete sind seit etwa einer Woche verschwunden, und die Suche der Feste blieb erfolglos. Latronicus hat ihn für im Einsatz vermisst erklärt und schickt Euch zu Ginro Hearthkindle.",h="In der Mondfederfeste sucht Latronicus Moonspear Hilfe, nachdem ein Kurier verschwunden ist.",kw={"kurier","mondfederfeste","feralas","ginro hearthkindle","gnolle","latronicus moonspear","pakete","raschal"},sec={{t="Ein verschwundener Kurier",b="Latronicus Moonspear hat die Suchmöglichkeiten der Feste nach einem Kurier und seinen Paketen ausgeschöpft. Beide werden seit etwa einer Woche vermisst, und Latronicus hat den Kurier für im Einsatz vermisst erklärt.\n\nGinro Hearthkindle, ein Bekannter von Latronicus, sucht in der Mondfederfeste nach Hilfe, vielleicht in seinen Gemächern. Latronicus bittet Euch, mit Ginro zu sprechen, falls Ihr Zeit und Mittel erübrigen könnt."},{t="Ginros ermüdende Suche",b="Ginro Hearthkindle weiß, dass Latronicus Moonspear Euch geschickt hat, auch wenn Ginro ihn Latro nennt. Ginro hält die Suche für aussichtslos, nimmt aber jede angebotene Hilfe an und sehnt sich danach, die Angelegenheit abzuschließen.\n\nJeden Tag sucht Ginro in Feralas nach Spuren von Raschal. Jede Nacht kehrt er nur mit Gnollzähnen und Enttäuschung zurück."}},faq={{q="Wer ist verschwunden?",a="Ein Kurier und die Pakete, die er bei sich trug, werden seit etwa einer Woche vermisst. Die Suche der Mondfederfeste blieb erfolglos, und der Kurier wurde für im Einsatz vermisst erklärt.",al={"wer ist der kurier","wer ist verschwunden","name des vermissten kuriers"}},{q="Wo ist Ginro Hearthkindle zu finden?",a="Ginro Hearthkindle ist in der Mondfederfeste, vielleicht in seinen Gemächern.",al={"ginro hearthkindle aufenthaltsort","wo ist ginro","ginro finden"}},{q="Wer beginnt die Suche nach dem Kurier?",a="Latronicus Moonspear in der Mondfederfeste schickt Euch zu Ginro Hearthkindle, um Hilfe zu leisten.",al={"wer vergibt der vermisste kurier","latronicus moonspear quest","wer beginnt der vermisste kurier"}}},fp="19,269,22.383.0,20.323.1,21.174.0,38.73.0,38.90.0"}
P.entries["quest:4125"] = {n="Der vermisste Kurier",s="Ginro Hearthkindle sucht an Feralas' Küste nach Raschal, der seit etwa einer Woche vermisst wird. Raschal brach nach Thalanaar auf und wollte die Küste hinabrudern. Ginro konnte das Boot nicht finden und bittet Euch, am Ufer nach einem Hinweis zu suchen.",h="Ginro Hearthkindle sucht an Feralas' Küste nach Raschal, der seit etwa einer Woche vermisst wird.",kw={"mondfederfeste","feralas","die vergessene küste","ginro hearthkindle","raschal","ruderboot","thalanaar"},sec={{t="Eine Route die Küste hinab",b="Ginro Hearthkindle glaubt, dass Raschal die Küste hinab in Richtung Thalanaar rudern wollte. Raschal brach vor etwa einer Woche auf und kennt Feralas gut. Raschal dient bei den Expeditionstruppen, seit General Feathermoon sie hierherführte.\n\nDie Route führt durch das südliche Feralas, fern vom Lager der Horde. Ginro konnte das Boot nicht finden, also ist es vielleicht versteckt oder gesunken. Es könnte einen Hinweis auf Raschals Aufenthaltsort enthalten. Auf dem Festland erstreckt sich die Vergessene Küste vom Bootssteg nach Süden."},{t="Am Ufer",b="Durch das schlammige Wasser ist ein zerstörtes Ruderboot zu erkennen, dessen eine Seite von klaffenden Löchern übersät ist. Es ist fast bis auf sein Holzgerüst zerfetzt. Was auch immer das Boot getroffen hat, scheint versucht zu haben, es in zwei Hälften zu spalten.\n\nAuf der anderen Seite ist ein kleines Wappen der Mondfederfeste aufgemalt. Im Schlamm am Boden des Bootes schimmert etwas Metallisches."}},faq={{q="Wer ist Raschal?",a="Raschal ist der vermisste Kurier. Raschal kennt Feralas gut und dient bei den Expeditionstruppen, seit General Feathermoon sie hierherführte.",al={"wer ist raschal","identität des vermissten kuriers","wer wird vermisst"}},{q="Wohin war Raschal unterwegs?",a="Raschal war nach Thalanaar unterwegs. Der Plan war, die Küste hinabzurudern und dann das südliche Feralas zu durchqueren, um das Lager der Horde zu umgehen.",al={"raschals ziel","wohin war er unterwegs","route des kuriers"}},{q="Wie lange wird Raschal schon vermisst?",a="Raschal wird seit etwa einer Woche vermisst, seit dem Aufbruch nach Thalanaar.",al={"wann brach raschal auf","wie lange fort"}},{q="Wo begann diese Suche?",a="Ihr habt die Suche begonnen, nachdem Ihr mit Ginro Hearthkindle über den vermissten Kurier gesprochen hattet.",al={"vorheriger schritt","wie begann diese quest"}}},fp="19,220,22.464.0,12.324.1,15.144.0,26.122.0,34.71.0,28.86.0"}
P.entries["quest:4127"] = {n="Havarie",s="Vor der Küste birgt die Havarie einen Hinweis für Ginro Hearthkindle in der Mondfederfeste. Ein gut gepflegtes Messer liegt im Schlamm, und Ihr spürt noch etwas anderes im Wasser.",h="Vor der Küste birgt die Havarie einen Hinweis für Ginro Hearthkindle in der Mondfederfeste.",kw={"havarie","discarded knife","mondfederfeste","feralas","ginro hearthkindle","missing courier","raschal","ruderboot"},sec={{t="Ein Messer im Schlamm",b="Nahe dem zerstörten Boot tastet Ihr durch den Schlamm und findet ein gut gepflegtes Messer. Wer auch immer an Bord war, könnte es verloren haben, als das große Stück aus dem Boot gerissen wurde. Ihr bringt das Messer zu Ginro Hearthkindle in der Mondfederfeste. Ginro hat Euch gebeten, jeden gefundenen Hinweis zurückzubringen, doch noch immer ist etwas anderes mit Euch im Wasser."},{t="Eine Frage an Euch",b="Ginro glaubt, dass das Messer Raschal gehörte, und fragt, ob Ihr es auf dem Grund neben seinem Boot gefunden habt. Das Messer allein stellt vielleicht keine Verbindung zwischen dem Boot und Raschals Verschwinden her. Ginro kennt einen anderen Weg, mehr zu erfahren: Psychometrie. Habt Ihr davon gehört?"}},faq={{q="Wo wird das Messer entdeckt?",a="Das Messer liegt im Schlamm neben dem zerstörten Ruderboot, im Wasser vor der Küste.",al={"fundort des messers","wo ist discarded knife","wo ist das messer zu finden"}},{q="Wer möchte den Hinweis zurückgebracht haben?",a="Ginro Hearthkindle in der Mondfederfeste hat Euch gebeten, jeden gefundenen Hinweis zurückzubringen.",al={"wer schickt zum boot","wer will das messer","havarie abgeben"}},{q="Was für ein Messer ist es?",a="Das Messer ist gut gepflegt und liegt im Schlamm neben dem zerstörten Boot. Wer auch immer an Bord war, könnte es verloren haben.",al={"wem gehört das messer","wem gehört die klinge"}},{q="Was kommt unmittelbar vor der Untersuchung der Havarie?",a="Sie folgt auf den zweiten Teil von Missing Courier, in dem Ihr gebeten wurdet, das Boot des Kuriers zu finden.",al={"vorherige quest","was führt zur havarie"}}},fp="13,174,18.326.0,18.238.1,30.82.0,32.88.0,25.109.0,54.98.0"}
P.entries["quest:4129"] = {n="Das wieder aufgetauchte Messer",s="Ginro Hearthkindle schickt Euch mit dem Messer zu Quintis Jonespyre, um dessen Vergangenheit deuten zu lassen. Ginro sagt, die Deutung werde Quintis' Spielschulden beim Kalimdor Hold 'Em begleichen.",h="Ginro Hearthkindle schickt Euch mit dem Messer zu Quintis Jonespyre, um dessen Vergangenheit deuten zu lassen.",kw={"weggeworfenes messer","mondfederfeste","ginro hearthkindle","kalimdor hold em","psychometrie","quintis jonespyre","raschal"},sec={{t="Die Schulden eines Druiden",b="Nach Boat Wreckage schickt Euch Ginro Hearthkindle mit dem Messer zu Quintis Jonespyre. Quintis ist der ansässige Druide der Mondfederfeste und lebt dort in einem kleinen Baumhaus.\n\nIndem Quintis einen Gegenstand berührt, kann er dessen Vergangenheit erfahren. Ginro nennt diese Psychometrie eine Magie, die er weder versteht noch verstehen möchte, obwohl er sie schon hat wirken sehen. Quintis hat bei Ginro Spielschulden aus Kalimdor Hold 'Em, und Ginro sagt, die Deutung des Messers werde sie begleichen."},{t="König der Bad Beats",b="Quintis sagt, psychometrische Deutungen zehren an der Psyche, ähnlich wie Verluste beim Kalimdor Hold 'Em. In der Feste nennt man ihn den König der Bad Beats. Er hat Pech beim Kartenspiel, doch Glück mit den Geheimnissen der Natur.\n\nQuintis willigt ein, das Messer zu deuten. Er hofft, es werde den nötigen Durchbruch bringen, um Raschals Schicksal aufzudecken."},{t="Vor der Deutung",b="Quintis dankt Euch und sagt, Psychometrie sei keine exakte Kunst. Er hat damit Licht in Situationen gebracht, die andere als aussichtslos abgetan hatten. Das Messer könnte einen Einblick darin gewähren, was mit Raschal geschehen ist.\n\nDie Deutung dauert nur einen Augenblick, verlangt einem Zaubernden jedoch einiges ab. Quintis bittet Euch um etwas Geduld."}},faq={{q="Wer ist Quintis Jonespyre?",a="Quintis Jonespyre ist der ansässige Druide der Mondfederfeste. Er lebt dort in einem kleinen Baumhaus und kann die Vergangenheit eines Gegenstands durch Berührung erfahren.",al={"quintis","wer ist quint","druide in feathermoon"}},{q="Was ist Psychometrie?",a="Psychometrie ist die Kunst, die Vergangenheit eines Gegenstands durch Berührung zu erfahren. Quintis sagt, ihre Deutungen zehren an der Psyche.",al={"wie funktioniert psychometrie","das messer deuten","quintis psychometrie"}},{q="Warum hilft Quintis mit dem Messer?",a="Quintis hat bei Ginro Hearthkindle Spielschulden aus Kalimdor Hold 'Em, und Ginro sagt, eine Deutung des Messers werde sie begleichen. Quintis hofft auch, damit Raschals Schicksal aufdecken zu können.",al={"warum hilft quintis","ginro schulden","kalimdor hold em"}},{q="An welcher Stelle der Ermittlungen geschieht das?",a="Die Ermittlungen erreichen diesen Punkt nach Boat Wreckage, wo das Messer gefunden wurde.",al={"welche quest kommt davor","welche quest kommt danach","das wieder aufgetauchte messer questreihe"}}},fp="18,165,14.445.0,21.309.0,18.304.1,25.146.0,20.111.0,37.166.0,44.84.0"}
P.entries["quest:413"] = {n="Schimmerstarkbier",s="In Bräuhall schickt Rejold Gerstenbräu seinem Bruder Wellart Schimmerstarkbier. Der Wächter bewacht den Pass nach Loch Modan, wo ein starker Trunk auf einem kalten Posten willkommen ist.",h="In Bräuhall schickt Rejold Gerstenbräu seinem Bruder Wellart Schimmerstarkbier.",kw={"dun morogh","kharanos","gebirgsjäger gerstenbräu","rejold gerstenbräu","schimmerstarkbier","südtorpass","wellart"},ang={["faction:Alliance"]="Als Reisender der Allianz helft Ihr, die Gebirgsjäger zu versorgen, während sie die Straße zwischen Dun Morogh und Loch Modan bewachen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass das Teilen von Bier mit der Familie ebenso wichtig ist wie das Bewachen der Gebirgspässe. Diese Lieferung gehört zum Grenzleben in Eisenschmiede."},sec={{t="Ein Familienrezept an der Grenze",b="Rejold Gerstenbräu hat Schimmerstarkbier mit schimmernden Wedeln verfeinert, die von den eisigen Felsen Dun Moroghs stammen. Seine Familie kümmert sich in Bräuhall um Bottiche und Fässer, während sein Bruder Wellart das Leben eines Gebirgsjägers gewählt hat. Rejold weiß, wie einsam der Wachdienst an der Grenze sein kann, und gibt durchreisenden Reisenden ein frisches Fass mit. Es ist eine Gefälligkeit unter Brüdern und eine Gelegenheit, das Gebräu zu erproben."},{t="Der südliche Wachturm",b="Wellart Gerstenbräu bewacht vom südlichen Turm aus den Südtorpass nach Loch Modan. Hoch oben im Pass trotzen Gebirgsjäger eisigen Winden und gelegentlichen Angriffen von Bestien, während sie über Reisende auf der Bergstraße wachen. Wellart gehen die Getränke aus, und er sehnt sich nach Aufregung. Wie er feststellt, hat Schimmerstarkbier es ordentlich in sich und scheint seine Sicht in der düsteren Bergnacht aufzuhellen."}},faq={{q="Wer ist Gebirgsjäger Gerstenbräu?",a="Gebirgsjäger Wellart Gerstenbräu ist Rejold Gerstenbräus Bruder. Während seine Verwandten in Bräuhall Bier brauen, dient Wellart bei den Dun Morogh Mountaineers und bewacht den hohen Pass zwischen Dun Morogh und Loch Modan.",al={"wer ist wellart gerstenbräu","wellart gerstenbräu","gebirgsjäger gerstenbräu geschichte"}},{q="Wo steht der südliche Wachturm?",a="Der südliche Turm steht an Dun Moroghs Ostgrenze und bewacht den Südtorpass durch die Berge nach Loch Modan.",al={"wo steht der südliche wachturm","gebirgsjäger gerstenbräu standort","wo ist wellart"}},{q="Was macht Schimmerstarkbier besonders?",a="Schimmerstarkbier wird mit besonderen schimmernden Wedeln gebraut, die in der verschneiten Wildnis gesammelt werden. Wellart sagt, es helle seine Sicht auf und gebe ihm das Gefühl, durch die Dunkelheit sehen zu können.",al={"was bewirkt schimmerstarkbier","schimmerstarkbier wirkung"}},{q="Was geschieht, nachdem Wellart das Starkbier getrunken hat?",a="Wellart schmeckt das Gebräu, und er bittet Reisende, ein weiteres Fass nach Loch Modan zu Gebirgsjäger Kadrell zu bringen, der auf der Straße durch Thelsamar patrouilliert.",al={"was kommt nach schimmerstarkbier","nächste quest nach schimmerstarkbier"}}},fx={cd95a50e={q="Warum möchte Rejold Gerstenbräu, dass dies erledigt wird?",a="Rejold ist begierig darauf, die Früchte seines Handwerks mit seinem Bruder, Gebirgsjäger Wellart Gerstenbräu, zu teilen. Da er gerade sein neues Rezept für Shimmer Stout in der Familienbrennerei perfektioniert hat, weiß Rejold, dass Wellart zwar das Brauereigewerbe aufgegeben hat, um die Grenzen zu patrouillieren, aber im Herzen ein wahrer Zwerg geblieben ist, der ein herzhaftes Getränk liebt. Die Lieferung eines frischen Fasses ist sowohl eine Geste brüderlichen Stolzes als auch eine Möglichkeit, ein ehrliches Urteil über sein neuestes Gebräu von einem durstigen Soldaten im Feld zu bekommen.",al={"warum shimmer stout schicken","rejold gerstenbräu beweggrund","warum das stout liefern"}}},fp="13,181,31.379.0,26.381.0,30.217.0,42.130.0,33.181.0,44.144.1"}
P.entries["quest:4130"] = {n="Psychometrie-Sitzung",s="Nach der Psychometrie-Sitzung ist Quintis Jonespyre noch immer unsicher auf den Beinen. Seine Vision zeigt Raschal und die Woodpaw-Gnolle, und Quintis bittet Euch, Ginro Hearthkindle in der Mondfederfeste davon zu berichten.",h="Nach der Psychometrie-Sitzung ist Quintis Jonespyre noch immer unsicher auf den Beinen.",kw={"mondfederfeste","ginro hearthkindle","psychometrie-sitzung","quintis jonespyre","raschal","wasserelementare","woodpaw"},sec={{t="Was Quintis sah",b="Quintis Jonespyre ist unsicher auf den Beinen, aber seine Vision könnte helfen. Raschal holt zwei große Lederrucksäcke aus dem Boot, geht landeinwärts und kehrt dann zum Boot zurück. Gnollskalps tauchen auf, und Quintis glaubt, dass Raschal Woodpaw-Gnollen begegnet ist. Raschal ist sehr besorgt, fast schon verängstigt, und bemerkt nicht, wie sich hinter ihm Wasserelementare bilden. Dann enden die Bilder. Quintis braucht Ruhe, also bittet er Euch, Ginro davon zu berichten, der Bescheid wissen muss."},{t="Ginros Antwort",b="Ginro Hearthkindle dankt Euch dafür, dass Ihr Quintis' Visionen überbracht habt. Raschal versteht sich auf den Kampf, und Gnolle würden ihm keine Sorgen bereiten, geschweige denn Angst einjagen. Dennoch hofft Ginro, dass Ihr und Eure Gefährten diesen Hinweisen nachgehen und den dringend benötigten Durchbruch erzielen könnt."}},faq={{q="Wer hat eine Vision mitzuteilen?",a="Quintis Jonespyre hat eine Vision mitzuteilen. Nach dem Lesen des Messers ist er noch wackelig auf den Beinen und bittet Euch, Ginro davon zu berichten.",al={"wer vergibt psychometrie-sitzung","questgeber psychometrie-sitzung"}},{q="Was sah Quintis in seiner Vision?",a="Raschal brachte zwei große Lederrucksäcke vom Boot ins Landesinnere und kehrte dann zum Boot zurück. Quintis sah Gnollskalps und glaubte, die Gnolle seien Woodpaw gewesen. Er sah auch, dass Raschal sehr besorgt, fast schon verängstigt war, während sich hinter ihm Wasserelementare bildeten.",al={"was war quintis' vision","was geschah mit raschal in der vision"}},{q="Wohin muss dieser Bericht gebracht werden?",a="Bringt den Bericht zu Ginro Hearthkindle in der Mondfederfeste.",al={"wo die vision überbringen","mit wem für psychometrie-sitzung sprechen"}}},fp="20,197,16.412.0,14.248.1,28.122.0,35.240.0,34.64.0"}
P.entries["quest:4131"] = {n="Die Waldpfotengnolle",s="Im südlichen Feralas durchsucht Ihr die Lager der Waldpfoten nach Raschal, dem Kurier. Nach Quintis' Vision schickt Ginro Hearthkindle Euch los, um ihn oder seine Habseligkeiten zu finden, obwohl Ginro bezweifelt, dass die Gnolle sein Verderben waren.",h="Im südlichen Feralas durchsucht Ihr die Lager der Waldpfoten nach Raschal, dem Kurier.",kw={"mondfederfeste","feralas","ginro hearthkindle","lederrucksäcke","die untere wildnis","quintis jonespyre","raschal","waldpfotengnolle"},sec={{t="Wo die Suche beginnt",b="Ginro Hearthkindle räumt ein, dass die Waldpfoten, die Ginro „Freunde“ nennt, Raschal vielleicht doch den Garaus gemacht haben. Dennoch hat Ginro das Gefühl, dass die Gnolle nicht verantwortlich waren, und ihre Lager sind der beste Ausgangspunkt. Ginro hat keinen genaueren Plan, als sie zu durchsuchen.\n\nGnolle behalten, was sie erbeuten, und streiten sich darum, also haben sie vielleicht die Rucksäcke gefunden, die Quintis erwähnt hat. Ginro mied bei früheren Suchen offene Kämpfe. Nun leitet Euch die Vision, und Ginro sagt, Ihr sollt über sie herfallen. Die Lager liegen im südlichen Feralas."},{t="Bei den Lagern",b="In der Unteren Wildnis sind zwei große Lederrucksäcke an einen nahe gelegenen Baum geheftet. Jeder trägt auf der Vorderseite ein kleines Abzeichen der Mondfederfeste."}},faq={{q="Nach wem wird gesucht?",a="Ginro Hearthkindle sucht nach Raschal, dem Kurier. Ginro will Hinweise auf Raschal oder seine Habseligkeiten finden.",al={"wer wird vermisst","waldpfotengnolle gesuchte person","wer ist raschal"}},{q="Warum die Lager der Waldpfotengnolle durchsuchen?",a="Ginro sagt, die Lager der Waldpfoten seien der beste Ausgangspunkt. Gnolle behalten, was sie erbeuten, und streiten sich darum, also haben sie vielleicht die Rucksäcke gefunden, die Quintis erwähnt hat.",al={"warum waldpfotengnolle","warum gnolle töten","warum gnolllager durchsuchen"}},{q="Woher kam der Hinweis auf die Rucksäcke?",a="Quintis Jonespyre erwähnte die Rucksäcke in seiner Vision, in der Raschal zwei große Lederrucksäcke aus dem Boot nahm.",al={"wer erwähnte rucksäcke","quint vision rucksäcke","woher weiß ginro von den rucksäcken"}},{q="Wo sind die Lager der Waldpfoten?",a="Die Lager der Waldpfoten liegen im südlichen Feralas.",al={"waldpfotengnolle standort","wo sind gnolllager in feralas","waldpfotenlager karte"}}},fp="18,204,22.511.0,12.144.1,26.108.0,35.163.0,49.116.0,28.42.0"}
P.entries["quest:4135"] = {n="Die verwundene Tiefe",s="In der Gewundenen Tiefe untersucht Raschal eine ernste Gefahr für Feralas. Eure Suche nach ihm führt Euch dorthin.",h="In der Gewundenen Tiefe untersucht Raschal eine ernste Gefahr für Feralas.",kw={"feathermoon","feralas","kokon","raschal","thalanaar","woodpaw","die gewundene tiefe","zukk'ash"},sec={{t="Die Notiz in den Rucksäcken",b="Die Rucksäcke enthalten ein Paket für Thalanaar und eine hastig verfasste Notiz ohne benannten Empfänger. Raschal of Feathermoon schrieb sie, nachdem er in der Gewundenen Tiefe südlich der Gnolllager insektenartige Kreaturen entdeckt hatte. Er fürchtete, dass sie ganz Feralas bedrohten, also ging er los, um sie selbst zu untersuchen. Seine Notiz zeigt, wohin er gegangen ist."},{t="Was unten wartet",b="Unterhalb der Gewundenen Tiefe findet Ihr einen großen, fremdartigen Kokon. Seine schleimige Oberfläche trägt verhärtete Wucherungen, und er ist breit und hoch genug, um eine Person zu fassen. Durch seine Haut könnt Ihr im Inneren die schwachen Umrisse eines Humanoiden erkennen."}},faq={{q="Wer ist Raschal?",a="Raschal of Feathermoon schrieb die Notiz, die in den Rucksäcken gefunden wurde. Er ging los, um insektenartige Kreaturen zu untersuchen, die er entdeckt hatte, und Eure Suche nach ihm geht weiter.",al={"raschal hintergrundgeschichte","wer ist raschal","raschal feathermoon"}},{q="Wo liegt die Gewundene Tiefe?",a="Raschals Notiz zufolge liegt die Gewundene Tiefe südlich der Gnolllager der Woodpaw.",al={"gewundene tiefe lage","wo ist die gewundene tiefe","wie die gewundene tiefe finden"}},{q="Warum ging Raschal in die Gewundene Tiefe?",a="Raschal schrieb, dass er dort heimtückische insektenartige Kreaturen gefunden hatte und das Gefühl hatte, sie selbst untersuchen zu müssen. Er fürchtete, dass sie ganz Feralas bedrohten.",al={"warum raschal zum schwarm ging","raschals beweggründe","warum die gewundene tiefe"}},{q="Was kommt vor dieser Suche?",a="Die Suche folgt auf „The Woodpaw Gnolls“, den vorherigen Schritt.",al={"gewundene tiefe voraussetzung","welche quest kommt zuerst"}}},fp="17,113,21.310.0,16.229.1,15.157.0,35.73.0,40.149.0,30.58.0"}
P.entries["quest:414"] = {n="Starkbier für Kadrell",s="Ein Fass von Rejold Gerstenbräus neuem Shimmer Stout geht ostwärts zu Gebirgsjäger Kadrell in Loch Modan. Ihr tragt es von Dun Moroghs frostigen Höhen ins wärmere Tal.",h="Ein Fass von Rejold Gerstenbräus neuem Shimmer Stout geht ostwärts zu Gebirgsjäger Kadrell in Loch Modan.",kw={"bier","gerstenbräu","fass","dun morogh","kadrell","loch modan","rejold","shimmer stout","thelsamar"},ang={["faction:Alliance"]="Als Reisender der Allianz folgt Ihr der Straße von Dun Moroghs verschneiten Weiten in das weitläufigere Grenzland von Loch Modan.",["race:Dwarf"]="Als Zwerg tragt Ihr Bergbier über Gebietsgrenzen hinweg und verbindet so die Brauer von Bräuhall mit den Patrouillen, die Khaz Modan bewachen."},sec={{t="Ein Geschmack jenseits der Berge",b="Vom östlichen Grenzposten Dun Moroghs aus wacht Gebirgsjäger Gerstenbräu über die Bergpässe und seine Verwandten, die benachbarte Lande bewachen. Die Patrouillen der Gebirgsjäger können kalt und beschwerlich sein, und ein starkes Herz verlangt nach einem starken Trunk. Rejolds neues Shimmer Stout ist zu gut, um es in Dun Morogh zu behalten. Gerstenbräu möchte die ehrliche Meinung eines anderen Wachgängers hören, also schickt er ein Fass mit Reisenden ostwärts nach Loch Modan."},{t="Der Weg nach Thelsamar",b="Für junge zwergische und gnomische Abenteurer ist der Weg nach Loch Modan ein Übergangsritus nach ihren ersten Tagen in Dun Moroghs verschneiten Felsen. Ihr zieht nach Südosten durch den Südtoraußenposten und folgt dann langen Tunneln, die durch das Felsgestein des Gebirges gehauen wurden. Dahinter liegt das wärmere, bewaldete Becken von Loch Modan. Gebirgsjäger Kadrell patrouilliert auf der Straße durch Thelsamar. Er hält inne, um das Fass anzustechen, und stellt fest, dass Gerstenbräus neue Rezeptur eine erstaunliche Durchschlagskraft hat."}},faq={{q="Wer ist Gebirgsjäger Kadrell?",a="Gebirgsjäger Kadrell ist ein zwergischer Verteidiger in Loch Modan. Er patrouilliert auf der Hauptstraße durch Thelsamar.",al={"kadrell","wer ist kadrell","gebirgsjäger kadrell standort"}},{q="Was ist Shimmer Stout?",a="Shimmer Stout ist ein starkes Bier, das Rejold Gerstenbräu in der Brennerei von Bräuhall im Westen Dun Moroghs braut. Seine Stärke lässt den Kopf schwirren und spendet belebende Wärme.",al={"was ist shimmer stout","shimmer stout","rejolds gebräu"}},{q="Wie erreiche ich Loch Modan von Dun Morogh aus?",a="Zieht von Dun Moroghs östlichen Wachposten nach Südosten durch die Gebirgstunnel an South Gate vorbei. Folgt in Loch Modan der Straße, die nach Nordosten in Richtung Thelsamar am See abzweigt.",al={"wie nach loch modan gelangen","weg nach thelsamar","dun morogh nach loch modan"}},{q="Warum soll Kadrell das Bier für Gerstenbräu probieren?",a="Gebirgsjäger Gerstenbräu und Gebirgsjäger Kadrell gehören beide den zwergischen Gebirgsjägern an. Beeindruckt vom neuen Rezept seines Bruders möchte Gerstenbräu seinen Kameraden im benachbarten Tal davon kosten lassen.",al={"warum starkbier an kadrell schicken","verbindung gerstenbräu kadrell"}},{q="Was hält Kadrell von dem Gebräu?",a="Kadrell ist von der Stärke des Starkbiers erstaunt. Er schwört bei Magnis Bart, dass es ihm den Kopf verdreht und seine Glieder so leicht macht, dass er glaubt, fliegen zu können.",al={"kadrells reaktion","ist shimmer stout gut"}},{q="Führt diese Quest zu weiteren Aufgaben?",a="Die Lieferung des Fasses schließt die in Dun Morogh begonnene Questreihe um Shimmer Stout ab. Sie führt Reisende nach Thelsamar, wo in ganz Loch Modan viele Aufgaben warten.",al={"starkbier für kadrell folgequest","what comes next"}}},fx={["46258ba9"]={q="Warum benötigt Gebirgsjäger Gerstenbräu Euch, um das Fass zu liefern?",a="Gerstenbräu ist bei der Wache am Südtoraußenposten im Dienst und hat die Aufgabe, die östlichen Grenzen von Dun Morogh zu bewachen und Reisende zu überwachen. Als Gebirgsjäger im Dienst kann er seinen Posten nicht einfach verlassen, um einen Drink zu teilen, weshalb er auf vorbeikommende Abenteurer angewiesen ist, die in Richtung Südosten nach Thelsamar reisen, um das Fass zu Kadrell zu bringen.",al={"warum kann gerstenbräu das stout nicht liefern","warum braucht gerstenbräu mich","warum einen abenteurer nach thelsamar schicken"}}},fp="16,172,28.411.0,21.456.0,27.103.0,22.181.0,42.188.0,49.201.0,36.150.0,38.151.0"}
P.entries["quest:415"] = {n="Rejolds neues Gebräu",s="Zurück in Bräuhall hat Rejold Gerstenbräu sein neues Rezept vollendet. Er möchte, dass Ihr, sein treuer Freund, der das Schimmerkraut beschafft hat, es kostet.",h="Zurück in Bräuhall hat Rejold Gerstenbräu sein neues Rezept vollendet.",kw={"bier","gebräu","bräuhall","dun morogh","pilot bellfiz","rejold gerstenbräu","shimmer stout","schimmerkraut","tharek schwarzstein"},ang={["faction:Alliance"]="Als Abenteurer der Allianz wisst Ihr, dass kräftige zwergische Biere die Garnisonen überall in den Östlichen Königreichen bei Laune halten, selbst an rauen Grenzposten wie Dun Morogh.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass es kaum eine größere Ehre gibt, als von einem angesehenen Braumeister zum ersten Schluck aus einem frischen Fass gerufen zu werden."},sec={{t="Ein Ruf nach Bräuhall",b="Tharek Schwarzstein und Pilot Bellfiz schicken Euch zurück nach Bräuhall. Rejolds experimentelle Sude sind fertig vergoren, und er ist bereit, sie mit Euch zu teilen. Ihr habt Schimmerkraut von den bitterkalten Hängen beschafft, und nun kann er Euch die Früchte dieser Mühen anbieten."},{t="Die Früchte der Arbeit kosten",b="Rejold Gerstenbräu hat heimische Kräuter in seine Maische gemischt, um Shimmer Stout zu brauen. Bevor er Fässer an benachbarte Außenposten und durstige Gäste in Loch Modan verschickt, gewährt er Euch die Ehre des ersten Schlucks. Ihr habt für die Kräuter Kopf und Kragen riskiert, und die erste Kostprobe gebührt Euch."}},faq={{q="Wer schickt mich zurück zu Rejold Gerstenbräu?",a="Eure Verbündeten in Dun Morogh, darunter Tharek Schwarzstein und Pilot Bellfiz, berichten Euch, dass Rejold Euch wieder in Bräuhall sehen möchte.",al={"wer startet rejolds neues gebräu","questgeber","wo gibt es die quest"}},{q="Wo liegt Bräuhall?",a="Bräuhall liegt im Westen von Dun Morogh, am Ufer des zugefrorenen Eiswellensees.",al={"wo liegt bräuhall","bräuhall standort","rejold gerstenbräu standort"}},{q="Woraus besteht Rejolds neues Getränk?",a="Rejold hat sein neues Getränk gebraut, indem er seinem traditionellen Bierrezept Schimmerkraut hinzufügte, eine Wildpflanze von den eisigen Felsen Dun Moroghs.",al={"was ist im gebräu","was hat rejold gebraut","schimmerkraut rezept"}},{q="Was geschieht, nachdem ich mit Rejold gesprochen habe?",a="Rejold bietet Euch eine Kostprobe seiner neuen Kreation an und bittet Euch dann, seinem Bruder Wellart ein Fass Shimmer Stout zu bringen, einem Gebirgsjäger, der im südlichen Wachturm an der Grenze zu Loch Modan stationiert ist.",al={"nächste quest","what comes next","rejold questreihe"}},{q="Warum möchte Rejold ausgerechnet mich kosten lassen?",a="Ihr habt Rejold geholfen, das seltene Schimmerkraut für sein experimentelles Rezept zu beschaffen, daher gebietet es für ihn die zwergische Höflichkeit, Euch zuerst kosten zu lassen.",al={"warum will rejold mich","wer hat das bier probiert"}},{q="Wie heißt das fertige Getränk?",a="Die experimentelle Mischung heißt Shimmer Stout, benannt nach der wichtigsten Zutat, die ihr ihren unverwechselbaren Pfiff verleiht.",al={"welches getränk hat er gebraut","name des getränks","rejolds bier"}}},fx={["4916bbae"]={q="Warum schickt Euch der Questgeber zu Rejold Gerstenbräu?",a="Rejold Gerstenbräu hat sich aktiv und ganz gezielt nach Euch erkundigt. Die Nachricht erreichte Außenposten wie Stahlrosts Depot, und egal ob Tharek Schwarzstein oder Pilot Bellfiz davon Wind bekommen haben, sie geben die Nachricht einfach weiter. Rejold benötigt Eure Hilfe beim Testen eines vielversprechenden neuen Rezepts, und soweit es Eure Informanten betrifft, könnte Euch die Antwort auf seinen Ruf eine Kostprobe von kostenlosem Bier einbringen.",al={"warum schickt mich tharek zu rejold","warum schickt mich pilot bellfiz zu brewnall","warum zu rejold zurückkehren"}}},fp="17,148,21.265.0,26.272.0,39.127.0,26.85.0,35.126.0,37.203.1,47.153.0,39.105.0"}
P.entries["quest:416"] = {n="Rattenfang",s="In den westlichen Ausläufern machen Tunnelrattenkobolde die Straßen nach Thelsamar unsicher. Gebirgsjäger Kadrell ruft Reisende auf, sie zurückzudrängen und zum Beweis für ihre Dezimierung Trophäen gegen ein Kopfgeld abzuliefern.",h="In den westlichen Ausläufern machen Tunnelrattenkobolde die Straßen nach Thelsamar unsicher.",kw={"kopfgeld","kobold","loch modan","gebirgsjäger kadrell","rattenfang","thelsamar","tunnelratte","tunnelrattenohren"},ang={["faction:Alliance"]="Gebirgsjäger Kadrell spricht für die örtlichen Zwergenbehörden von Loch Modan. Er bietet Reisenden der Allianz Kopfgelder an, wenn sie bereit sind, die Siedlungen der Zwerge zu schützen.",["race:Dwarf"]="Als Verteidiger von Khaz Modan haben die Zwerge ein unmittelbares Interesse daran, die Ausläufer rund um Thelsamar von Ungeziefer und unterirdischen Eindringlingen freizuhalten."},sec={{t="Ungeziefer in den Ausläufern",b="Westlich von Thelsamar haben Tunnelrattenkobolde Baue in den Ausläufern von Loch Modan angelegt. Sie beschmutzen das umliegende Gelände und machen die Straßen unsicher, die in die Stadt führen. Ihre Baue bedrohen die Sicherheit und Sauberkeit dieser Straßen."},{t="Das Kopfgeld eines Gebirgsjägers",b="Gebirgsjäger Kadrell hat ein Kopfgeld auf die Tunnelrattenkobolde ausgesetzt. Er bittet vorbeiziehende Reisende, ihre abgetrennten Ohren als Beweis für die Dezimierung mitzubringen. Dann zahlt er Münzen und eine Entlohnung, auch wenn die Trophäen bei der Begutachtung widerlich sind."}},faq={{q="Wer vergibt die Quest Rattenfang?",a="Gebirgsjäger Kadrell bietet das Kopfgeld in Thelsamar an. Er bittet Reisende, das Ungeziefer zu dezimieren, das vom nahe gelegenen Berghang kommt.",al={"wer vergibt rattenfang","wo gibt es rattenfang","kadrell quest"}},{q="Was sind Tunnelrattenkobolde?",a="Tunnelrattenkobolde sind eine Art von Kobolden, die in den westlichen Ausläufern nahe Thelsamar Baue gegraben haben. Sie beschmutzen den Berghang.",al={"was sind tunnelratten","kobolde in loch modan","tunnelrattenkobold"}},{q="Wo sind die Tunnelrattenkobolde zu finden?",a="Tunnelrattenkobolde und ihre Baue sind unmittelbar westlich von Thelsamar zu finden, verstreut am Berghang und in den Ausläufern.",al={"wo sind die tunnelratten","rattenfang ort","baue westlich von thelsamar"}},{q="Warum verlangt Kadrell Tunnelrattenohren?",a="Gebirgsjäger Kadrell verlangt Tunnelrattenohren als Beweis für die Tötung, bevor er das Kopfgeld der Stadt auszahlt.",al={"warum ohren sammeln","warum will kadrell ohren","tötungsnachweis loch modan"}},{q="Warum bereitet der Koboldbefall dem Gebirgsjäger Sorgen?",a="Die Kobolde haben sich in den Ausläufern vor Thelsamar angesiedelt, wo sie Baue anlegen und das umliegende Zwergenland beschmutzen. Kadrell will sie vertreiben lassen, um das Gebiet zu sichern.",al={"warum tunnelratten beseitigen","thelsamar rattenproblem","warum kobolde in loch modan töten"}},{q="Führt Rattenfang zu einer größeren Questreihe?",a="Dies ist ein örtliches Kopfgeld, um Schädlinge rund um Thelsamar zu beseitigen. Kadrell zahlt, sobald die Ohren abgeliefert sind.",al={"hat rattenfang eine folgequest","rattenfang questreihe","quest nach rattenfang"}}},fp="12,178,23.224.0,22.216.0,33.125.0,28.129.0,42.113.0,41.98.0,62.171.0,45.97.0"}
P.entries["quest:4161"] = {n="Rezept der Kaldorei",s="In Dolanaar lehrt Zarrin junge Köche, aus Teldrassils Wäldern nur zu nehmen, was sie brauchen. Seine Lektion beginnt mit Nahrung und Wald, nicht mit dem Schlachtfeld.",h="In Dolanaar lehrt Zarrin junge Köche, aus Teldrassils Wäldern nur zu nehmen, was sie brauchen.",kw={"kochen","dolanaar","kaldorei","rezept der kaldorei","spinnen-schaschlik","teldrassil","zarrin"},ang={["profession:Cooking"]="Wenn Ihr in Teldrassil kochen lernt, erhaltet Ihr das Rezept für Kaldorei Spider Kabobs.",["race:NightElf"]="Als Nachtelf lernt Ihr die Lebensweise der Kaldorei: Wahrt durch Zurückhaltung den Einklang mit der Natur und nehmt nur, was Ihr braucht."},sec={{t="Kinder der Sterne",b="Hinter dem Gasthaus in Dolanaar hütet Zarrin einen brodelnden Kessel und lehrt junge Abenteurer die Traditionen seines Volkes. Nachtelfen nannten sich einst die Kaldorei, oder Kinder der Sterne. Zarrin beginnt mit ihrer Verbindung zur Nahrung und zu Teldrassils Ästen und lässt das Schlachtfeld beiseite."},{t="Nur das Nötige nehmen",b="Außerhalb von Laubschattental bittet Zarrin Euch, genau sieben kleine Spinnenbeine von Spinnentieren des Waldes zu sammeln. Die Kaldorei suchen Einklang mit der Natur, indem sie nur nehmen, was sie brauchen, und der Wildnis mit Güte begegnen. Selbst in unruhigen Zeiten ist dieses Gleichgewicht wichtig. Ein Spinnen-Schaschlik macht die Lektion deutlich."}},faq={{q="Wer ist Zarrin?",a="Zarrin ist ein Nachtelf, der hinter dem Gasthaus in Dolanaar einen Kessel hütet. Er lehrt junge Abenteurer, nach den Traditionen der Kaldorei zu kochen.",al={"zarrin","wer ist zarrin","koch dolanaar","kochlehrer dolanaar"}},{q="Warum besteht Zarrin darauf, genau sieben Spinnenbeine zu sammeln?",a="Zarrin verlangt genau sieben Spinnenbeine, um zu lehren, dass die Kaldorei nur nehmen, was sie brauchen, und im Einklang mit der Natur leben. Die Lektion verlangt Respekt vor dem lebendigen Wald und seinem Gleichgewicht.",al={"warum sieben beine","warum nur sieben","nicht mehr als sieben nehmen"}},{q="Was bedeutet das Wort „Kaldorei“?",a="Kaldorei bedeutet in der Sprache Darnassian Kinder der Sterne. Es ist der uralte Name, den die Nachtelfen seit Tausenden von Jahren für sich verwenden.",al={"was bedeutet kaldorei","kaldorei bedeutung","kinder der sterne"}},{q="Wo werden die Spinnenbeine gesammelt?",a="Sammelt die Beine von webwood spiders in Teldrassils Wäldern, außerhalb der schützenden Grenzen von Laubschattental.",al={"wo lassen spinnen beine fallen","spinnenbeine fundort","welche spinnen"}},{q="Was bereiten Nachtelfen aus Spinnenbeinen zu?",a="Zarrin lehrt junge Abenteurer, Kaldorei Spider Kabobs zuzubereiten, ein traditionelles Wildnisgericht aus Waldspinnenfleisch für eine nahrhafte Mahlzeit unterwegs.",al={"was ist das rezept","kaldorei spider kabob","spinnennahrung"}},{q="Liefern alle Spinnen in Teldrassil die benötigten Beine?",a="Nein. Junge Spinnen in Laubschattental liefern nicht die passenden Beine für Zarrins Rezept. Sammelt sie von Spinnen, die durch Teldrassils weitere Wälder streifen.",al={"eignen sich spinnen aus laubschattental","laubschattental spinnenbeine"}}},fx={["214de26a"]={q="Welche Spinnen jagt Ihr in Teldrassil?",a="Ihr werdet ausgesandt, um die wilden Webholzspinnen zu jagen, die in den Wäldern außerhalb des Laubschattentals umherstreifen. Obwohl Spinnen ein natürlicher Teil der Äste von Teldrassil sind, bittet Euch Zarrin nur das zu erlegen, was Ihr benötigt, damit Ihr die Harmonie des Waldes respektiert, anstatt wahllos zu schlachten.",al={"welche spinnen lassen beine fallen","welche spinnen jagen","teldrassil spinnen"}}},fp="22,159,21.292.0,26.292.0,14.144.0,63.194.0,35.146.0,35.101.0,45.163.0,51.143.0"}
P.entries["quest:417"] = {n="Pilotenrache",s="Hildelves Suche endet in den Felsen von Dun Morogh, wo Pilot Hammerfuß’ Suchtrupp ihn erfroren neben seinem Tagebuch findet. Seine letzten Worte fordern Rache.",h="Hildelves Suche endet in den Felsen von Dun Morogh, wo Pilot Hammerfuß’ Suchtrupp ihn erfroren neben seinem...",kw={"dun morogh","hammerfuß","hildelve","eisklauenbär","belagerungsbrigade von eisenschmiede","mangeclaw","rache"},ang={["class:Hunter"]="Als Jäger stellt Ihr Eure Überlebensfähigkeiten im Gebirge auf die Probe, indem Ihr ein ungewöhnlich bösartiges Alphatier wie Mangeclaw durch Dun Moroghs eisige Winde verfolgt.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die Piloten von Eisenschmiede für die Verteidigung der Zwerge und der Allianz unverzichtbar sind. Vermisste Piloten zu bergen, ist eine wesentliche Pflicht.",["race:Dwarf"]="Als Zwerg ehrt Ihr Hildelves Andenken, indem Ihr Euren gefallenen Kameraden aus der Belagerungsbrigade von Eisenschmiede rächt und seinen Mörder bestraft."},sec={{t="Ein letzter Eintrag",b="Hildelves Tagebuch berichtet von seinem erbitterten Kampf mit Mangeclaw, dem riesigen Eisklauenbären. Zunächst vertrieb er die Bestie, doch seine Wunden waren schwer. Mangeclaw kehrte zurück und tötete ihn."},{t="Der letzte Wunsch eines Piloten",b="Hildelves letzte Bitte fordert Rache an Mangeclaw. Bringt sein Tagebuch und eine der Bestie entrissene Klaue zu Pilot Hammerfuß. Die düstere Nachricht gibt der Belagerungsbrigade von Eisenschmiede Gewissheit und ehrt ihren verlorenen Kameraden."}},faq={{q="Wer war Hildelve?",a="Pilot Hildelve war ein zwergischer Belagerungsmaschinenpilot in der Belagerungsbrigade von Eisenschmiede. Als seine Maschine ausfiel, machte er sich zu Fuß in die Berge von Dun Morogh auf. Sein Freund Pilot Hammerfuß schickte einen Suchtrupp los, der Hildelves Überreste im Schnee fand.",al={"hildelve","wer ist der tote zwerg","vermisster pilot"}},{q="Was ist Mangeclaw?",a="Mangeclaw ist ein außergewöhnlich großer und wilder Eisklauenbär, der an den Hängen von Dun Morogh umherstreift. Der Bär überfiel Pilot Hildelve und verwundete ihn tödlich. Dann kehrte Mangeclaw zurück und tötete ihn.",al={"mangeclaw","eisklauenbär","wer hat hildelve getötet"}},{q="Wer ist Pilot Hammerfuß?",a="Pilot Hammerfuß ist ein erfahrener Belagerungsmaschinenpilot, der in Dun Morogh stationiert ist und der Belagerungsbrigade von Eisenschmiede angehört. Aus Sorge um seinen vermissten Freund Hildelve schickt er Euch in die Wildnis, um herauszufinden, was geschehen ist.",al={"hammerfuß","pilot hammerfuß"}},{q="Warum ist Hildelves Tod für Eisenschmiede von Bedeutung?",a="Die Belagerungsbrigade von Eisenschmiede ist auf ausgebildete Piloten und Maschinen angewiesen, um das Bergland rund um die Hauptstadt auszukundschaften und zu verteidigen. Hildelves Tod ist ein schwerer Schlag für ihre Reihen.",al={"warum ist hildelve wichtig","bedeutung der belagerungsbrigade"}},{q="Wo beginnt diese Questreihe?",a="Pilot Hammerfuß leitet die Reise ein, indem er Euch in „The Lost Pilot“ bittet, seinen vermissten Freund zu finden. Der Fund von Hildelves Leiche beginnt „Pilotenrache“.",al={"wie beginnt pilotenrache","questreihe des vermissten piloten"}},{q="Welchen Beweis müsst Ihr Hammerfuß bringen?",a="Bringt Hildelves Tagebuch von der Leiche des Piloten und eine Räudige Klaue von Mangeclaws Kadaver. Gemeinsam beweisen sie, dass die Bestie erschlagen wurde.",al={"mangeclaw beweis","welche gegenstände werden benötigt"}}},fx={["5ec072c3"]={q="Warum gibt Euch die Zwergenleiche diesen Auftrag?",a="Die Leiche ist die von Pilot Hildelve, der seine letzten Momente in seinem wiedergefundenen Tagebuch festhielt. Obwohl er anfangs den massiven Frostklauenbären Mangeclaw abwehrte, kehrte die Bestie zurück, um ihm den Rest zu geben. Sein Tagebuch macht seinen letzten Wunsch deutlich: Er wollte Rache an der Bestie, die sein Leben in den gefrorenen Felsklippen beendete.",al={"warum die quest mit der zwergenleiche","hildelves beweggrund","warum rache an mangeclaw"}},b9e5721c={q="Warum kann Eisenschmiede Mangeclaw nicht selbst erledigen?",a="Pilot Hammerfuß ist in dem abgelegenen Lager stationiert und wartet auf Nachricht von seinem vermissten Kameraden, ohne von Hildelves Schicksal zu wissen, bis Ihr den Körper entdeckt. Da Hildelve tot im Schnee liegt und keine Patrouille in der Nähe ist, die über sein Tagebuch stolpern könnte, seid Ihr die Einzigen vor Ort, die seinen letzten Wunsch erfüllen können.",al={"warum muss ich mangeclaw töten","warum ich eine rache des piloten","warum tötet hammerfuß mangeclaw nicht"}}},fp="17,160,13.182.0,20.217.0,17.248.0,18.196.0,24.213.0,46.181.0,34.163.0,46.145.0"}
P.entries["quest:418"] = {n="Blutwurst aus Thelsamar",s="Im Gasthof Zum Starkbier-Lager in Thelsamar bringt Vidra Ofenglut Blutwurst aus Thelsamar auf den Tisch. Sie ist in ganz Loch Modan beliebt und braucht frische Zutaten aus dem Tal.",h="Im Gasthof Zum Starkbier-Lager in Thelsamar bringt Vidra Ofenglut Blutwurst aus Thelsamar auf den Tisch.",kw={"bärenfleisch","blutwurst","eberdärme","kochen","loch modan","spinnensekret","thelsamar","vidra ofenglut"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr helfen, Thelsamars Arbeiter zu verköstigen, während sie wichtige Infrastruktur instand halten und in ganz Loch Modan uralte Ruinen ausgraben.",["profession:Cooking"]="Sammelt Zutaten für Vidra, und angehende Köche können das Rezept für Blutwurst erlernen, um deftige Feldrationen zuzubereiten.",["race:Dwarf"]="Als Zwerg ist Euch Blutwurst eine vertraute, wohltuende Speise, geprägt vom derben Geschmack der Bergklans von Khaz Modan."},sec={{t="Deftiges aus dem Hochland",b="Hungrige Kinder und Bergleute, die von der Eisenschacht-Ausgrabung zurückkehren, füllen Thelsamars Taverne. Vidra Ofenglut steht am Herd und bereitet Würste zu, die in ganz Loch Modan bekannt sind. Ihr Rezept nutzt Wildtiere aus dem zerklüfteten Gebirgspass."},{t="Ungewöhnliche Gewürze",b="Vidra verwendet Eberdärme als Wursthüllen und Bärenfleisch für die Füllung. Spinnensekret verleiht den Würsten ihre scharfe, beißende Note. Das Sammeln der Innereien und der giftigen Flüssigkeit erfordert einen robusten Magen, doch Reisende lernen diese regionale Spezialität zu schätzen."}},faq={{q="Wer ist Vidra Ofenglut?",a="Vidra Ofenglut kocht im Gasthof Zum Starkbier-Lager in Thelsamar. Sie ist stolz darauf, die hart arbeitenden Bewohner von Loch Modan zu verköstigen, besonders die Arbeiter der nahen Ausgrabungsstätten.",al={"vidra","wer ist vidra","köchin in thelsamar"}},{q="Warum verwendet das Rezept Spinnensekret?",a="Vidra fügt Spinnensekret hinzu, um ihren Blutwürsten einen scharfen, beißenden Geschmack zu verleihen.",al={"spinnensekret in wurst","warum spinnensekret","spinnengewürz"}},{q="Wer isst Blutwurst aus Thelsamar?",a="Thelsamars Stadtbewohner, Kinder und erschöpfte Arbeiter, die von ihren Schichten bei der Eisenschacht-Ausgrabung zurückkehren, essen die Würste.",al={"wer isst blutwurst","warum wurst herstellen"}},{q="Wo findet man die Zutaten?",a="Schwarzbären, Bergeber und Waldlauererspinnen durchstreifen Loch Modans Wildnis und die bewaldeten Hügel rund um den See.",al={"wo bärenfleisch bekommen","wo eberdärme bekommen","fundorte der zutaten"}},{q="Welche Hülle wird für die Würste verwendet?",a="Vidra verwendet gereinigte Därme heimischer Bergeber als Hüllen, die Bärenfleisch und gewürzte Füllung über dem Feuer zusammenhalten.",al={"wursthüllen","eberdärme","rezept für wursthüllen"}},{q="Lernen Reisende, diese Würste zuzubereiten?",a="Ja. Bringt Vidra die Zutaten, und sie teilt das Rezept mit Reisenden, die kochen können.",al={"kann man blutwurst kochen","wurstrezept","kochrezept"}}},fx={afb643f5={q="Warum muss Vidra Ofenglut diese Zutaten sammeln lassen?",a="Thelsamar wimmelt von hungrigen Einheimischen, von lärmenden Kindern, die durch die Straßen rennen, bis hin zu erschöpften Arbeitern, die von der nahegelegenen Ausgrabungsstätte zurückkehren. Vidra ist sehr stolz darauf, jeden mit den berühmten Blutwürsten der Stadt zu versorgen, aber mit der endlosen Nachfrage Schritt zu halten erfordert eine stetige Versorgung mit frischem lokalem Wild.",al={"warum blutwurst herstellen","vidra ofengluts beweggrund","warum braucht vidra essen"}},["97b761ee"]={q="Wofür wird das Bärenfleisch im Rezept verwendet?",a="Bärenfleisch liefert den herzhaften, sättigenden Kern von Thelsamars berühmten Blutwürsten. Die Bären in Loch Modan streifen zahlreich durch die umliegende Wildnis und bieten dichtes, reichhaltiges Fleisch, das den anspruchsvollen Appetit der hart arbeitenden Zwergenbergleute und Arbeiter stillen kann.",al={"warum bärenfleisch","bärenfleischrezept","wofür ist das bärenfleisch"}},c89e7412={q="Warum bittet Vidra einen Reisenden, die Zutaten zu sammeln, anstatt sie selbst zu besorgen?",a="Vidra betreibt eine geschäftige Küche und erwartet von jedem in der Stadt, dass er seinen Teil dazu beiträgt. Wie sie es sieht, müssen sich selbst reisende Abenteurer ihren Unterhalt verdienen, anstatt ein leichtes Alm ausschlagen zu erwarten, was das Jagen von Wild in den Hügeln zu einem fairen Tausch für eine Kostprobe ihrer berühmten Kochkünste macht.",al={"warum braucht vidra mich","warum kann vidra kein fleisch besorgen","warum einen reisenden fragen"}}},fp="24,168,22.226.0,21.254.0,25.168.0,37.75.0,34.119.0,32.115.0,37.115.0,42.96.0"}
P.entries["quest:419"] = {n="Der vermisste Pilot",s="Am Wrack bangt Pilot Hammerfuß um Mori Hildelve in den zerklüfteten Höhen von Dun Morogh. Hildelve zog zu Fuß los, um seltenes Erz für wirksames Sprengpulver zu suchen, doch Tage sind vergangen, und Brüllen hallt durch die Gipfel.",h="Am Wrack bangt Pilot Hammerfuß um Mori Hildelve in den zerklüfteten Höhen von Dun Morogh.",kw={"sprengpulver","brigadier vest","dun morogh","der vermisste pilot","mori hildelve","pilot hammerfuß","belagerungsmaschine"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, dass die Zwerge unablässig nach instabilen Mineralien suchen, um sie zu wirksamen Sprengstoffen und Sprengpulver zu verarbeiten.",["race:Dwarf"]="Als Zwerg geht Euch der Verlust eines erfahrenen Belagerungsmaschinenführers durch wilde Bestien besonders nahe. Selbst die vertrauten Hügel von Khaz Modan bergen tödliche Gefahren."},sec={{t="Eine jäh beendete Suche",b="Pilot Mori Hildelve steuerte seine Belagerungsmaschine die steilen Grate von Dun Morogh hinauf, auf der Suche nach seltenem Erz für hochwertiges Sprengpulver. Die Maschine ging am Hang kaputt. Er ließ Pilot Hammerfuß im Lager zurück, um das Wrack zu bewachen, und stieg dann zu Fuß höher in die gefrorene Wildnis hinauf."},{t="Echos im Schnee",b="Tage vergingen, und Hildelve kehrte nicht ins Lager zurück. Nachts hallte wildes Knurren von den zerklüfteten Felsen wider. Hammerfuß' Ungeduld wich der Angst. Hildelve war zäh, doch ohne seine Maschine oder schwere Unterstützung boten die eisigen Höhen kaum Schutz vor umherstreifenden Raubtieren."},{t="Ein grausiger Fund",b="Mori Hildelves Spur endet in den zerklüfteten Höhen. Seine Überreste liegen den Elementen ausgesetzt, von Aasfressern des Gebirges zerfleischt und abgenagt. Seine leblose Hand umklammert hastig hingekritzelte Notizen. Eine Brigadier's Vest liegt noch immer über seinem zerschundenen Körper und zeugt vom gewaltsamen Ende des Belagerungsingenieurs."}},faq={{q="Warum war Pilot Hildelve allein in der Wildnis unterwegs?",a="Hildelve zog in die Wildnis, um seltenes Erz für hochwertiges zwergisches Sprengpulver zu suchen. Als seine Belagerungsmaschine an einem steilen Hang kaputtging, setzte er seinen Weg zu Fuß in die zerklüfteten Höhen fort, statt die Suche aufzugeben.",al={"warum hildelve aufbrach","was hildelve tat","pilot hildelves auftrag"}},{q="Wer schickt Euch auf die Suche nach Hildelve?",a="Pilot Hammerfuß, Hildelves Freund und ebenfalls Belagerungsmaschinenführer, bittet Euch, der Sache nachzugehen. Hildelve ließ Hammerfuß zurück, um ihre beschädigte Maschinerie zu bewachen, während er vorausging und das Gelände erkundete.",al={"wer die quest vergibt","questgeber der vermisste pilot"}},{q="Was geschah mit Hildelves Belagerungsmaschine?",a="Hildelve beschädigte die Mechanik der Belagerungsmaschine, als er sie auf der Suche nach Erz einen steilen, vereisten Hang hinaufsteuerte. Die Maschine blieb im Schnee liegen.",al={"kaputte belagerungsmaschine","warum die maschine kaputtging"}},{q="Was hat Pilot Hildelve getötet?",a="Hammerfuß hat tierisches Knurren in den Hügeln gehört und bangt um Hildelve. Wer der Spur des Piloten folgt, erfährt sein Schicksal.",al={"hildelves mörder","wie der pilot starb","wer hildelve getötet hat"}},{q="Welche Beweise finden sich bei Hildelves Überresten?",a="Hildelves Hand umklammert hastig hingekritzelte Notizen, und eine gut erhaltene Brigadier's Vest liegt noch immer um seinen Körper.",al={"hildelve beweise","gegenstände bei hildelves leiche","todesbeweis"}},{q="Was geschieht nach der Entdeckung von Hildelves Leiche?",a="Der Fund Hildelves offenbart, was während seiner Suche geschah. Die dort gefundenen Beweise führen die Untersuchung weiter.",al={"wie weiter der vermisste pilot","rachequest"}}},fx={da1c7c00={q="Warum möchte Pilot Hammerfuß, dass Ihr Hildelve findet?",a="Pilot Hammerfuß und Mori Hildelve sind enge Freunde und Kameraden als Belagerungsmaschinenpiloten, die gemeinsam in die Hügel zogen, um nach seltenem Erz zu suchen. Mori machte sich vor Tagen zu Fuß auf den Weg, nachdem er seine Maschine zerstört hatte, und ließ Hammerfuß zurück. Da er seitdem jede Nacht wütendes Grollen durch die Berge hallen hört, ist Hammerfuß zutiefst besorgt um das Überleben seines Kameraden und verzweifelt darauf bedacht, sein Schicksal zu erfahren.",al={"warum möchte hammerfuß hildelve","pilot hammerfuß beweggrund","warum nach hildelve suchen"}},["120a5684"]={q="Warum sucht Pilot Hammerfuß nicht selbst nach Hildelve?",a="Bevor Hildelve sich allein in die schneebedeckten Gipfel wagte, beauftragte er Hammerfuß ausdrücklich damit, ihre wertvollen Belagerungsmaschinen zu bewachen. Mit einer beschädigten Maschine und beiden gestrandet in der rauen Wildnis von Dun Morogh, kann Hammerfuß seinen Posten nicht verlassen, um eine einsame Suche zu starten, ohne die schwere Maschinerie von Eisenschmiede schutzlos umherstreifenden Bestien und Plünderern zu überlassen.",al={"warum kann hammerfuß nicht suchen","warum braucht hammerfuß mich","warum einen abenteurer schicken"}}},fp="14,195,18.266.0,18.273.0,16.281.1,51.200.0,35.183.0,41.148.0,27.118.1,42.123.1,49.116.1"}
P.entries["quest:420"] = {n="Senirs Beobachtungen",s="Grelin Weißbarts Bericht erreicht seinen Bruder Senir in Kharanos mit Neuigkeiten aus dem Coldridgetal. Seine Ankunft bringt Senir dazu, wieder feindliche Kräfte auf den Schneefeldern zu beobachten.",h="Grelin Weißbarts Bericht erreicht seinen Bruder Senir in Kharanos mit Neuigkeiten aus dem Coldridgetal.",kw={"das coldridgetal","dun morogh","grelin weißbart","grelins bericht","senat von eisenschmiede","kharanos","gebirgsjäger thalos","senir weißbart","troggs"},ang={["faction:Alliance"]="Abgestimmte Erkundung hilft, Dun Morogh zu sichern, während Sturmwind in innere Unruhen verstrickt ist und seinen nördlichen Verbündeten keine Hilfe entbehren kann.",["race:Dwarf"]="Als Zwerg verlasst Ihr das geschützte Ausbildungstal in Richtung Kharanos und macht einen ersten Schritt in die Verteidigung von Khaz Modan. Dort treffen die Sorgen der Feldspäher auf die Vorsicht des Senats von Eisenschmiede.",["race:Gnome"]="Als Gnom reist Ihr durch den Pass nach Kharanos und kommt den wichtigsten Zentren Dun Moroghs und den Bemühungen zur Unterstützung Eurer zwergischen Gastgeber näher."},sec={{t="Durch den Tunnel nach Kharanos",b="Gebirgsjäger Thalos bewacht das Tor aus dem Coldridgetal. Er vertraut vorbeikommenden Reisenden Grelins Botschaft an. Jenseits des Tors lauern gewalttätige Troggs allen auf, die den Tunnel durchqueren, und machen den Weg nach Kharanos gefährlich. Hinter dem Tunnel führt die Hauptstraße durch das zentrale Dun Morogh in den Ort."},{t="Mürrischer Empfang und Senatspolitik",b="In der Brauerei Donnerbräu wärmt sich Senir Weißbart bei Getränken auf, als Grelins Bericht eintrifft. Er schmunzelt über die nachdrücklichen Worte seines Bruders. Grelin berufe sich auf König Magni Bronzebart, um rasches Handeln einzufordern, sagt Senir, und das werde den sturen Senat von Eisenschmiede aufbringen.\n\nDie bittere Kälte hat Senir davon abgehalten, seine eigenen Beobachtungen einzureichen. Grelins Botschaft bringt ihn dazu, wieder feindliche Kräfte auf den Schneefeldern zu beobachten."}},faq={{q="Warum lässt Gebirgsjäger Thalos den Bericht von einem Reisenden überbringen?",a="Gebirgsjäger Thalos bewacht den Tunnel des Coldridgetals gegen aggressive Troggs und kann seinen Posten nicht verlassen. Kommt ein Reisender vorbei, vertraut er ihm Grelins Botschaft für Kharanos an.",al={"warum thalos um hilfe bittet","thalos kurier","wer vergibt diese quest"}},{q="Wer ist Senir Weißbart?",a="Senir Weißbart ist ein zwergischer Späher und Grelin Weißbarts Bruder. Er ist in Kharanos stationiert und sammelt für das Oberkommando von Eisenschmiede Berichte aus dem Feld über örtliche Bedrohungen.",al={"wer ist senir","senir weißbart kharanos","senirs hintergrund"}},{q="Was steht in Grelins Bericht?",a="Grelins Bericht hält seine Erkenntnisse über die Aktivitäten und Vorstöße der Frostmähnentrolle im Coldridgetal fest. Er beruft sich auf die Autorität von König Magni Bronzebart, um die Verantwortlichen zu Verstärkung und Aufmerksamkeit zu drängen.",al={"was steht im bericht","grelins bericht inhalt","grelins bericht hintergrundgeschichte"}},{q="Warum sagt Senir, dass Grelins Bericht im Senat für Unmut sorgen wird?",a="Grelin beruft sich nachdrücklich auf König Magnis Namen, um Handeln einzufordern. Das kann die Autorität und den Stolz des Senats von Eisenschmiede herausfordern und Mitglieder verärgern, die förmliche Beratungen bevorzugen.",al={"unmut im senat","senir senat von eisenschmiede","warum ist der senat verärgert"}},{q="Warum ist der Tunnel zwischen dem Coldridgetal und Kharanos gefährlich?",a="Rockjaw-Troggs sind aus tiefen unterirdischen Spalten hervorgekommen und haben den Bergtunnel besetzt. Sie greifen zwergische Reisende, Händler und Boten an, die hindurchwollen.",al={"coldridgetal tunnel gefährlich","trogg tunnel dun morogh","warum sind troggs im tunnel"}},{q="Wohin führt der Weg nach der Übergabe dieser Botschaft?",a="Kharanos führt Reisende in die umfassendere Verteidigung Dun Moroghs ein. Senir Weißbart sucht Hilfe bei der Untersuchung der Bedrohungen durch Frostmähnentrolle und Troggs, während die Ortsvorsteher Unterstützung nach Bräuhall, Eisenschmiede und zu den entlegenen Höfen lenken.",al={"wie weiter nach senir","nächste quest nach senirs beobachtungen","wohin führt kharanos"}}},fx={bc98cde7={q="Warum möchte Gebirgsjäger Thalos, dass dieser Bericht übermittelt wird?",a="Gebirgsjäger Thalos ist stationiert, um den gefährlichen Pass aus dem Coldridgetal zu bewachen, und kann seinen Posten nicht verlassen. Grelin Weißbarts Aufklärung über die Trogg- und Trollbedrohungen sind wichtige Informationen, die für seinen Bruder Senir bestimmt sind, der umfassendere Verteidigungsberichte für Eisenschmiede koordiniert. Sicherzustellen, dass der Bericht Senir in Kharanos erreicht, ist entscheidend, um den Rest von Dun Morogh vor den aufkommenden Gefahren zu warnen.",al={"warum grelins bericht senden","thalos beweggrund","warum den bericht an senir liefern"}}},fp="20,181,30.294.0,36.428.0,63.192.0,24.168.0,27.205.0,70.174.0,66.162.0,55.218.0"}
P.entries["quest:421"] = {n="Wertbeweis",s="Am Grabmal läuft Dalar Morgenwebers Feldzug gegen die Worgen des Silberwalds. Die Verlassenen suchen einen Weg nach Süden durch die Länder der Menschen und Zwerge, doch wilde Worgen bedrohen die Straße. Ihre Anwesenheit geht auf Erzmagier Arugal zurück.",h="Am Grabmal läuft Dalar Morgenwebers Feldzug gegen die Worgen des Silberwalds.",kw={"arugal","dalar morgenweber","moonrage whitescalps","wertbeweis","das grabmal","burg shadowfang","silberwald","worgen"},ang={["class:Mage"]="Als Magier erkennt Ihr in Dalar Morgenwebers Auftrag und Arugals Unheil die Gefahr leichtfertiger Beschwörungen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, eine freie Militärstraße durch den Silberwald ins südliche Lordaeron zu sichern.",["race:Undead"]="Als Verlassener helft Ihr, den Silberwald zu säubern, um die Grenzen von Unterstadt zu sichern und Bedrohungen durch Dalarans Versagen zu beseitigen."},sec={{t="Den südlichen Korridor sichern",b="Fürstin Sylvanas Windläufer und ihr Schreckenslord-Leutnant Varimathras wollen die Gebiete südlich von Tirisfal sichern. Dort liegen Enklaven der Menschen und Zwerge. Der Silberwald liegt auf ihrem Weg, doch die Route ist gefährlich. Wilde Moonrage-Worgen durchstreifen seine kiefernbewachsenen Hügel und bedrohen die Nachschublinien und vorgeschobenen Stützpunkte der Verlassenen."},{t="Arugals Verderben",b="Dalar Morgenweber sagt, Arugal habe die Worgen in den Silberwald gebracht. Einst war Arugal ein Magier von Dalaran, doch er fiel in Ungnade. Während der Invasion der Geißel ließ er Worgen aus einer anderen Welt auf den Wald los. Nun hat er Burg Shadowfang für sich beansprucht, während seine wilden Schöpfungen die Wälder durchstreifen. Bevor Dalar Soldaten damit betraut, Arugals Zauberei weiter zu untersuchen, müssen Rekruten ihr Kampfgeschick gegen die nächstgelegenen Moonrage Whitescalps beweisen."}},faq={{q="Wer ist Dalar Morgenweber?",a="Dalar Morgenweber ist ein Magier der Verlassenen am Grabmal. Er leitet den Kampf gegen magische Bedrohungen im Silberwald, besonders gegen Erzmagier Arugal und sein wildes Worgenrudel.",al={"dalar morgenweber","wer vergibt wertbeweis","questgeber am grabmal"}},{q="Wo befinden sich die Moonrage Whitescalps?",a="Die Moonrage Whitescalps durchstreifen die Wälder und verfallenen Gehöfte im mittleren Silberwald. Sie befinden sich unweit der Hauptstraße, den Hügel vom Grabmal hinab.",al={"wo sind whitescalps","moonrage whitescalps fundort","whitescalps farmen"}},{q="Warum interessieren die Worgen im Silberwald die Horde?",a="Die Horde braucht den Silberwald als Weg von Unterstadt in die südlichen Gebiete. Fürstin Sylvanas und Varimathras suchen einen sicheren Weg nach Süden, und Worgenrudel bedrohen diese Route.",al={"warum worgen töten","worgenproblem der verlassenen","warum den silberwald säubern"}},{q="Welche Verbindung hat Arugal zu diesen Kreaturen?",a="Erzmagier Arugal beschwor die Worgen aus einer anderen Dimension, um die Geißel zu bekämpfen, während er Dalaran diente. Die Bestien verwilderten, und Schuldgefühle trieben Arugal in den Wahnsinn. Er zog sich nach Burg Shadowfang zurück, um den Fluch zu nähren.",al={"wie kamen die worgen hierher","verbindung zwischen arugal und worgen","wer beschwor die worgen"}},{q="Was geschieht, nachdem Ihr Dalar Euren Wert bewiesen habt?",a="Nachdem Ihr Euer Kampfgeschick durch das Töten der Whitescalps bewiesen habt, nimmt Dalar Morgenweber Euch in seinen Feldzug gegen Arugals Einfluss auf. Dieser führt durch die mehrteilige Questreihe namens Arugal's Folly.",al={"nächste quest","was folgt auf wertbeweis","arugal's folly beginn"}},{q="Ist die Allianz an dieser Quest beteiligt?",a="Nein. Dalar Morgenweber vergibt diese Quest an die Horde am Grabmal, einem Außenposten der Verlassenen.",al={"kann die allianz wertbeweis machen","allianz silberwald"}}},fx={["8fc519da"]={q="Warum möchte Dalar Morgenweber, dass dies erledigt wird?",a="Lady Sylvanas beauftragte Varimathras mit der Eroberung der Menschen- und Zwergengebiete im Süden, was den Silberwald zu einem wesentlichen strategischen Korridor für die Verlassenen macht. Jedoch haben die rücksichtslosen Beschwörungen des Magiers Arugal die Wälder mit wilden Worgen überrannt. Bevor Dalar sich einer Kampagne gegen Arugals Fluch verschreiben und die Region sichern kann, benötigt er fähige Kämpfer, die die umliegende Wildnis säubern und mit den wilden Bestien fertigwerden können.",al={"dalar morgenwebers beweggrund","warum prove your worth","warum möchte dalar, dass weißskalpe getötet werden"}},dab3177e={q="Was sind Mondzorn-Weißskalpe?",a="Mondzorn-Weißskalpe sind wilde Worgen, die durch die Hügel und Wälder in der Nähe des Grabmals streifen. Sie wurden durch die rücksichtslose Magie von Erzmagier Arugal auf den Silberwald losgelassen und sind bösartige, räuberische Bestien, die die Expansion und Kontrolle der Verlassenen über den gesamten Wald bedrohen.",al={"mondzorn-weißskalpe","wer sind die weißskalpe","was töten wir"}}},fp="16,232,30.330.0,15.418.0,24.163.0,43.151.0,51.179.0,47.202.0,47.185.0,39.86.0"}
P.entries["quest:422"] = {n="Arugals Torheit",s="Im Grabmal schickt Dalar Morgenweber Agenten der Verlassenen zu einem nahen Gehöft, um Arugals früheste Zauberbücher zu bergen. Die Verlassenen müssen die Magie hinter dem Worgenfluch verstehen, um sie gegen Arugal zu wenden und den Silberwald zu sichern. Die Arznei des Arugal ist der erste Schritt, um die Bedrohung aus Burg Shadowfang zu ergründen.",h="Im Grabmal schickt Dalar Morgenweber Agenten der Verlassenen zu einem nahen Gehöft, um Arugals früheste...",kw={"arugal","dalar morgenweber","staubige zauberbücher","kirin tor","arznei des arugal","das grabmal","silberwald","worgen"},ang={["class:Mage"]="Als Magier der Verlassenen könnt Ihr Arugals Werk als Warnung vor der Gefahr studieren, die Magie ohne Disziplin oder Weitsicht birgt.",["faction:Horde"]="Als Mitglied der Horde steht Ihr wilden Bestien gegenüber, die Eure Anwesenheit im Silberwald bekämpfen. Arugal auszuschalten ist entscheidend, um stabile Nachschublinien aus Lordaeron aufzubauen.",["race:Undead"]="Als Untoter wisst Ihr, dass der Silberwald der westliche Schutzschild von Unterstadt ist. Ihn von wilden Worgen zurückzuerobern ist entscheidend, um die Grenzen der Dark Lady zu sichern."},sec={{t="Der Spott eines Magiers",b="In den Krypten des Grabmals verachtet Dalar Morgenweber, ein ehrgeiziger Magier der Verlassenen, Erzmagier Arugal. Er hält ihn für einen gewöhnlichen Magier, dessen Platz in den Kirin Tor unverständlich ist und dessen Verständnis der Magie laienhaft wirkt. Doch die monströsen Bestien, die den Silberwald durchstreifen, lassen sich nicht ignorieren. Um Arugals Herrschaft über die Region zu brechen, will Morgenweber die Zauber zerlegen, die die Worgen auf Lordaeron losließen."},{t="Überreste auf dem Gehöft",b="Bevor Arugal Burg Shadowfang einnahm, lebte er auf einer abgelegenen Weizenfarm knapp nördlich der Flussbrücke. Todespirscher-Späher fanden zurückgelassene Zauberbücher im Obergeschoss des Bauernhauses, doch noch immer umherstreifende Bestien hinderten sie daran, die Schriften zu bergen. Durchsucht die staubigen Folianten, um die Arznei des Arugal zu entdecken, eine Beschwörung, die entscheidende Einblicke in den unnatürlichen Fluch des Silberwalds gewährt."}},faq={{q="Wer ist Dalar Morgenweber?",a="Dalar Morgenweber ist ein ehrgeiziger Magier der Verlassenen im Grabmal im Silberwald. Sylvanas Windläufer ergeben, will er Arugals Magie zerlegen und ihr entgegenwirken, damit die Verlassenen das Gebiet für sich beanspruchen können.",al={"dalar morgenweber","wer vergibt arugals torheit","magier im grabmal"}},{q="Was ist die Arznei des Arugal?",a="Die Arznei des Arugal ist ein Zauber in Arugals zurückgelassenen Büchern aus der Zeit, als er auf der Farm nördlich der Brücke lebte. Dalar Morgenweber braucht die Beschwörung, um die arkanen Grundlagen von Arugals Werk zu studieren.",al={"arznei des arugal","was ist das buch"}},{q="Wo befinden sich Arugals alte Zauberbücher?",a="Arugals staubige Zauberbücher liegen im Obergeschoss eines verlassenen Bauernhauses auf der Weizenfarm knapp nördlich des Brückenübergangs im nördlichen Silberwald.",al={"wo sind die bücher","fundort der staubigen zauberbücher","bücher im bauernhaus"}},{q="Warum blickt Morgenweber auf Arugal herab?",a="Morgenweber hält Arugal für einen minderwertigen Zauberer mit einem oberflächlichen Verständnis des Arkanen. Er versteht nicht, warum die Kirin Tor Arugal in Dalaran in ihre Reihen aufgenommen haben.",al={"warum hasst morgenweber arugal","morgenwebers meinung über arugal"}},{q="Warum ist diese Aufgabe für die Verlassenen wichtig?",a="Arugals Worgen schlachten die Truppen der Verlassenen ab und bedrohen ihre Herrschaft über den Silberwald. Indem sie seine Zauber studieren, hoffen die Verlassenen, die Bedrohung aufzuhalten und die Region für die Dark Lady zu sichern.",al={"interesse der verlassenen an arugal","warum interessiert arugal die verlassenen"}},{q="Was geschieht, wenn Ihr die staubigen Zauberbücher berührt?",a="Wer die staubigen Folianten berührt, alarmiert einen Moonrage-Worgen, der sich im Bauernhaus versteckt. Er greift jeden an, der Arugals zurückgelassene Forschungen stört.",al={"zauberbuchfalle","angriff von moonrage darkrunner"}}},fp="14,332,17.415.0,25.397.1,24.207.0,29.212.0,42.150.0,40.164.0,43.189.0,49.138.0"}
P.entries["quest:423"] = {n="Arugals Torheit",s="Im Silberwald suchen Agenten der Verlassenen nach Fesseln, die Moonrage-Worgen tragen. Dalar Morgenweber studiert Arugals Notizen, um zu erfahren, wie der abtrünnige Magier seine instabile Magie verstärkte. Die Fesseln könnten den Verlassenen helfen, die Bedrohung durch die Worgen zu bannen.",h="Im Silberwald suchen Agenten der Verlassenen nach Fesseln, die Moonrage-Worgen tragen.",kw={"arugal","dalar morgenweber","dalaran","darksoul","glutton","kirin tor","das grabmal","fesseln","silberwald","worgen"},ang={["class:Mage"]="Als Magier der Verlassenen könnt Ihr Dalars hartes fachliches Urteil nachvollziehen: Arugal glich mangelndes arkanes Können aus, indem er Macht durch verzauberte Fesseln leitete.",["faction:Horde"]="Als Mitglied der Horde braucht Ihr sichere Wälder im Silberwald, um auf der Heerstraße von Tirisfal in die weiter südlich gelegenen Länder zu reisen.",["race:Undead"]="Als Verlassene müsst Ihr den Silberwald vor wilden Worgen sichern, um Tirisfals südliche Grenze zu schützen und Königin Sylvanas' Herrschaftsgebiet zu stärken."},sec={{t="Die Abkürzung eines Stümpers",b="Dalar Morgenweber studiert Arugals geborgene Forschungsaufzeichnungen und spricht mit offener Verachtung über seinen einstigen Kollegen. Er sagt, Arugal sei ungeeignet gewesen, Dalaran zu dienen, geschweige denn in der dunkelsten Stunde des Königreichs hohe Zauberkunst auszuüben. Mangels Talent griff Arugal auf verzauberte Relikte und Gerätschaften zurück, um die von ihm beschworenen Worgen zu stärken und zu binden. Dalar braucht Proben, um die Magie zu untersuchen, die die Bestien bindet."},{t="Die Moonrage-Fesseln",b="Moonrage-Worgen durchstreifen den Silberwald und tragen Fesseln, die von Arugals Bindungsverzauberungen gezeichnet sind. Moonrage Gluttons und Moonrage Darksouls streifen nördlich und östlich des Grabmals umher. Ihre schweren Metallfesseln enthalten arkane Restenergie. Dawnweaver hofft, mithilfe dieser Energie einen Weg zu finden, Burg Shadowfang entgegenzutreten."}},faq={{q="Warum will Dalar Morgenweber Worgenfesseln?",a="Dalar will anhand der Fesseln untersuchen, wie Arugal sein schwaches magisches Talent mit verzauberten Gegenständen ausglich. Er hofft, ihre Magie werde zeigen, wie Arugal seine Bestien befehligt.",al={"warum fesseln sammeln","zweck der worgenfesseln","dalar morgenwebers plan"}},{q="Wer war Arugal, bevor er im Silberwald wahnsinnig wurde?",a="Arugal war ein Magier aus Dalaran. Dalar Morgenweber nennt ihn ein mittelmäßiges Talent der Kirin Tor, doch im Dritten Krieg entfesselte Arugal durch verbotene Beschwörungen von jenseits dieser Welt Worgen gegen die Geißel.",al={"arugals vorgeschichte","wer ist arugal","arugal dalaran"}},{q="Wo sind die Moonrage Gluttons und Darksouls zu finden?",a="Moonrage Gluttons und Moonrage Darksouls durchstreifen den Silberwald nördlich und östlich des Grabmals, nahe alten Ruinen und bewaldeten Pfaden.",al={"wo gluttons finden","darksoul fundort","worgen fundorte silberwald"}},{q="Warum bereitet Arugal den Verlassenen solche Sorgen?",a="Arugals Worgen bedrohen das Grabmal und die Herrschaft der Verlassenen südlich von Tirisfal. Die Verlassenen wollen seine Magie brechen und das nördliche Königreich sichern.",al={"verlassene worgenbedrohung","warum arugal bekämpfen"}},{q="Was hält Dalar Morgenweber von Dalaran?",a="Dalar verachtet seine einstigen Kollegen in Dalaran zutiefst. Er hält sie für Narren, weil sie Arugal Aufgaben anvertrauten, die seine Fähigkeiten überstiegen.",al={"dalars meinung zu dalaran","dalar über kirin tor"}},{q="Arbeitet Arugal mit der Geißel zusammen?",a="Nein. Arugal beschwor die Worgen, um Dalaran gegen die Geißel zu verteidigen. Die Bestien verwilderten und trieben ihn in den Wahnsinn, und er beanspruchte Burg Shadowfang als sein eigenes Herrschaftsgebiet.",al={"arugal geißel bündnis","gehört arugal zur geißel"}}},fx={["044c53be"]={q="Wofür werden die Fesseln der Völlerei und der Dunkelseelen verwendet?",a="Diese verzauberten Metallbänder wurden von Erzmagier Arugal geschmiedet, um seine ansonsten schwache Zauberkunst zu verstärken und sein Kommando über die Worgen zu verankern. Weil Arugal die angeborene Macht fehlte, die in den Silberwald beschworenen wilden Bestien zu kontrollieren, band er sie mit diesen magischen Fesseln. Dalar Morgenweber benötigt sie, um ihre Verzauberungen zu untersuchen und ihre verbleibenden Energien zu extrahieren, in der Hoffnung, Arugals rohe Magie zu entschlüsseln und einen Weg zu finden, die Worgenbedrohung zu neutralisieren.",al={"nimmersattfessel","dunkelseelenfessel","arugals fesseln verwendung"}},["1eff7283"]={q="Was sind Mondzorn-Völlerer und -Dunkelseelen?",a="Es sind bösartige Worgen, die durch die Wälder im nördlichen und östlichen Silberwald streifen. Einst in diese Welt beschworen von Arugal, um die Geißel abzuwehren, entglitten die monströsen Bestien schnell seiner Kontrolle und überrannten die lokalen Gebiete. Gebunden durch verzauberte Fesseln, die Arugals rohe Magie kanalisieren, durchstreifen diese korrumpierten Raubtiere jetzt den Wald und terrorisieren sowohl überlebende Einheimische als auch Kundschafter der Verlassenen, die durch die Region reisen.",al={"mondzorn-worgen","wer sind mondzornvöllerer","mondzorndunkelseelen"}}},fp="14,233,17.379.0,21.307.0,47.170.0,48.211.0,52.130.0,46.155.0,44.130.0,35.158.0"}
P.entries["quest:424"] = {n="Arugals Torheit",s="Worgen halten die Tiefenfelsmine in den südöstlichen Hügeln des Silberwalds und verwehren den Verlassenen das Erz für Varimathras' Streitkräfte. Dalar Morgenweber schickt Euch, ihren verderbten Vorarbeiter Grimson the Pale zu töten und seinen Kopf zum Grabmal zu bringen.",h="Worgen halten die Tiefenfelsmine in den südöstlichen Hügeln des Silberwalds und verwehren den Verlassenen das...",kw={"arugals torheit","dalar morgenweber","tiefenfelsmine","grimson the pale","das grabmal","silberwald","varimathras"},ang={["class:Mage"]="Als Magier erkennt Ihr die Gefahr, die von Arugals außer Kontrolle geratenen Beschwörungen und Verwandlungen ausgeht, deren Magie in die Minen sickert.",["profession:Mining"]="Als Bergmann könnt Ihr die reichen Erzadern der Tiefenfelsmine aufsuchen, sobald ihre verderbten Arbeiter beseitigt sind.",["race:Undead"]="Als Untoter helft Ihr, Metall für die Verlassenen zu sichern, damit sie ihre junge Nation gegen die Lebenden und die Geißel befestigen können."},sec={{t="Die Tiefen sichern",b="Dalar Morgenweber erfährt von den Darkstalkers der Verlassenen, dass Worgen die Tiefenfelsmine in den südöstlichen Hügeln des Silberwalds erreicht haben. Ihre wilde Zauberei breitete sich von Burg Shadowfang aus, wo Erzmagier Arugal dunkle Verzauberungen über den gesamten Wald entfesselte. Erz aus der Mine wird benötigt, um Unterstadt zu bewaffnen. Doch nun hausen Worgen in ihren Schächten, und die Mine ist unbrauchbar."},{t="Der abgetrennte Kopf",b="Grimson the Pale führt die Worgen durch die verseuchten Schächte der Mine. Dalar Morgenweber befiehlt Euch, den verderbten Vorarbeiter zu töten und seinen Kopf zum Grabmal zu bringen. Ohne Grimson verlieren die Worgen ihren Anführer, und Arbeiter der Verlassenen können die Mine für Lord Varimathras beanspruchen."}},faq={{q="Wer ist Grimson the Pale?",a="Grimson the Pale ist der Vorarbeiter der Tiefenfelsmine. Wie viele Arbeiter und Bewohner im südlichen Silberwald wurde er durch die Magie aus Erzmagier Arugals Experimenten verderbt. Nun beaufsichtigt er einen von Worgen überrannten Unterschlupf.",al={"grimson","wer ist grimson","vorarbeiter der tiefenfelsmine"}},{q="Wo liegt die Tiefenfelsmine?",a="Die Tiefenfelsmine liegt in den zerklüfteten Hügeln südöstlich des Grabmals im Silberwald. Ihre Stollen führen tief in den Hang hinein und wimmeln von Worgen.",al={"lage der tiefenfelsmine","wo ist die tiefenfelsmine","wo ist grimson zu finden"}},{q="Warum interessiert sich Varimathras für einen Bergbaubetrieb?",a="Varimathras leitet den strategischen Ausbau der Macht der Verlassenen. Die reichen Eisen- und Steinvorkommen der Mine sind unerlässlich, um Truppen zu bewaffnen und Festungen in ganz Lordaeron zu verstärken.",al={"warum will varimathras die mine","varimathras' interesse"}},{q="Was geschieht nach Grimsons Tod?",a="Dalar Morgenweber nimmt Grimsons Kopf als Beweis für den Sieg entgegen. Dann richtet er seine Aufmerksamkeit auf Arugals wachsenden Einfluss und bereitet einen Schlag gegen dessen Ursprung vor.",al={"nach arugals torheit drei","was kommt danach","nächste quest"}},{q="Welche Art von Magie hat die Mine verderbt?",a="Erzmagier Arugal entfesselte wilde Magie aus einer anderen Welt und Worgenflüche über den gesamten Silberwald. Diese Magie erreichte die Tiefenfelsmine, verdarb ihren Vorarbeiter Grimson the Pale und ließ die Schächte von Worgen überrannt zurück.",al={"arugals magie in der mine","was hat die tiefenfelsmine verderbt","fluch der mine"}},{q="Wer sind die Darkstalkers, die Dalar Morgenweber erwähnt?",a="Die Darkstalkers sind die geheime Nachrichten- und Aufklärungsabteilung des Militärs der Verlassenen. Von Außenposten wie dem Grabmal aus beobachten sie feindliche Truppenbewegungen und ungewöhnliche Vorkommnisse in der Region.",al={"darkstalkers","wer sind die darkstalkers"}}},fx={["8e7515d1"]={q="Warum möchte Dalar Morgenweber, dass Grimson der Bleiche getötet wird?",a="Während Dalar Arugals dunkle Verzauberungen studiert, muss er sich auch vor Varimathras verantworten, der die Tiefenfelsmine fordert, um den militärischen Vormarsch der Verlassenen durch den Silberwald anzutreiben. Arugals sich ausbreitende Magie verunreinigte die Mine und korrumpierte ihren Vorarbeiter, Grimson den Bleichen. Wenn Grimson erschlagen wird, wird sein Griff über die Stätte brechen, was eine kritische Quelle für Erz und Metall für die Verlassene sichert und Dalar gleichzeitig bei dem Schreckenslord in gutem Ansehen hält.",al={"warum grimson töten","dalar morgenwebers beweggrund","warum möchte dalar die mine"}},["49f6b035"]={q="Wofür ist Grimsons Kopf?",a="Dalar Morgenweber benötigt Grimsons abgetrennten Kopf als unbestreitbaren Beweis dafür, dass der verunreinigte Vorarbeiter tot ist. Da Varimathras schnelle Ergebnisse für seine Kampagne fordert, kann Dalar es sich nicht leisten, dass irgendein Zweifel daran besteht, dass die Tiefenfelsmine von ihrem korrumpierten Aufseher gesäubert wurde und bereit ist, beansprucht zu werden.",al={"warum grimsons kopf nehmen","zweck von grimsons kopf","grimson kopf quest"}}},fp="14,239,19.372.0,16.281.0,24.210.0,36.149.0,51.176.0,36.155.0,38.205.0,55.176.0"}
P.entries["quest:425"] = {n="Ivar der Verfaulte",s="Auf dem Ivar-Feld im nördlichen Silberwald bewacht Rane ihren schwer zugerichteten Bruder, während Ivar der Verfaulte in der Nähe umherstreift. Sie bittet Reisende der Horde, den wilden Ghul zu töten, damit Quinn sich erholen kann und sie ihren Bericht an Hochexekutor Hadrec abschließen können.",h="Auf dem Ivar-Feld im nördlichen Silberwald bewacht Rane ihren schwer zugerichteten Bruder, während Ivar der...",kw={"deathstalkers","ghul","hadrec","ivar","das ivar-feld","ivar der verfaulte","quinn yorick","rane yorick","das grabmal"},ang={["class:Rogue"]="Als Schurke kennt Ihr die Gefahr heimlicher Aufklärung, wenn Euch gefräßige Schrecken der Geißel unversehens überfallen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Versorgungslinien und strategischen Stellungen der Verlassenen in Lordaeron zu schützen, indem Ihr Überreste der Geißel wie Ivar beseitigt.",["race:Undead"]="Als Untoter kennt Ihr die Gefahr, der die Todespirscher ausgesetzt sind. Späher der Verlassenen, die hinter feindlichen Linien festsitzen, müssen auf Champions vertrauen, die des Weges kommen."},sec={{t="Eine vereitelte Mission",b="Die Todespirscher Rane und Quinn Yorick wurden ausgesandt, um den nördlichen Silberwald für Hochexekutor Hadrec im Grabmal zu erkunden. Ihre Arbeit fand auf einem Gehöft ein gewaltsames Ende, als Ivar der Verfaulte ihnen auflauerte."},{t="Die Bedrohung in der Scheune",b="Rane und Quinn entkamen, doch Quinn wurde schwer zugerichtet. Ein alchemistisches Heilmittel aus Waldtieren hat geholfen, doch er ist noch immer zu schwach zum Reisen. Ivar streift durch die nahe gelegene Scheune und wartet darauf, dass Ranes Wachsamkeit nachlässt. Sie bittet Reisende der Horde, hineinzugehen und ihn zu töten, damit das Gehöft gesichert werden kann."}},faq={{q="Wer ist Ivar der Verfaulte?",a="Ivar der Verfaulte ist ein Ghul der Geißel, der im nördlichen Silberwald lauert. Das Ivar-Feld war einst sein Bauernhof, und er sowie die meisten seiner Angehörigen und Arbeiter fielen der Geißel zum Opfer. Nun lauert er Vorbeiziehenden auf und greift Späher der Verlassenen auf dem Feld an.",al={"wer ist ivar","ivar der verfaulte hintergrund","was ist ivar der verfaulte"}},{q="Wo ist Ivar der Verfaulte zu finden?",a="Ivar lauert in der Scheune auf dem Ivar-Feld, gleich nördlich des verfallenen Bauernhauses, in dem Rane und Quinn Yorick Zuflucht gefunden haben.",al={"ivar standort","wo ist ivar","ivar der verfaulte scheune"}},{q="Wer sind Rane und Quinn Yorick?",a="Rane und Quinn Yorick sind Geschwister, eine Schwester und ein Bruder, und gehören den Verlassenen und den Todespirschern an. Hochexekutor Hadrec schickte sie aus, um feindliche Aktivitäten im Silberwald auszukundschaften, wo Ivar ihnen auflauerte.",al={"wer ist rane yorick","yorick brüder","wer ist quinn yorick"}},{q="Warum bittet Rane einen Abenteurer, Ivar zu töten?",a="Quinn wurde bei ihrer ersten Begegnung schwer zugerichtet und erholt sich noch immer. Rane muss ihren Bruder vor plötzlichen Angriffen der Geißel schützen, deshalb kann sie Ivar nicht selbst jagen.",al={"warum ivar töten","warum kämpft rane nicht"}},{q="Wer erhält den Bericht über Ivars Tod?",a="Hochexekutor Hadrec, der militärische Befehlshaber im Grabmal im Silberwald, erhält die Aufklärungsberichte der Späher. Rane verspricht, die Hilfe des Abenteurers darin lobend zu erwähnen.",al={"wer ist hadrec","wer hat die yoricks geschickt"}},{q="Was geschieht nach Ivars Tod?",a="Der Tod von Ivar dem Verfaulten beendet die Qualen der Geschwister auf dem Ivar-Feld. Da die unmittelbare Gefahr gebannt ist, hat Quinn Zeit, zu genesen, bevor sie ihre Erkundung des Waldes abschließen.",al={"wie weiter nach ivar","quest nach ivar"}}},fx={["494849b1"]={q="Wofür ist Ivars Kopf?",a="Abgetrennte Köpfe zu Eurem Kommandanten oder Auftraggeber zurückzubringen, ist Standardprotokoll an der wilden Grenze von Lordaeron. Rane Yorick verlangt Ivars Kopf als unbestreitbaren Beweis dafür, dass der bösartige Ghul dauerhaft zerstört wurde. Da Quinn in ihrem provisorischen Unterschlupf außer Gefecht gesetzt und verwundbar ist, kann Rane es sich nicht leisten, dem Wort von irgendjemandem zu vertrauen: Nur der enthauptete Kopf der Kreatur garantiert, dass sein Bruder die Zeit hat, die er benötigt, um sicher zu genesen.",al={"ivars kopf","warum ivars kopf","wofür ist ivars kopf"}},["2febd219"]={q="Warum benötigt Rane Yorick einen Abenteurer, um Ivar zu töten?",a="Rane kann die Seite ihres Bruders nicht verlassen. Der Ghul hat Quinn bei ihrem ersten Erkundungsgang schwer verstümmelt, was ihn bettlägerig und abhängig von heilenden Tränken machte, um seinen gebrochenen Körper zu heilen. Da Ivar in der nahegelegenen Scheune lauert und darauf wartet, dass Ranes Wachsamkeit nachlässt, würde es Quinn, wenn sie ihn auch nur kurz allein ließe, völlig schutzlos gegen einen zweiten Angriff machen. Fernab von Verstärkungen aus der Unterstadt oder den Patrouillen vom Grabmal ist ein externer Söldner ihre einzige Rettungsleine.",al={"warum kann rane ivar nicht töten","warum ich ivar the foul","warum ivar nicht selbst töten"}}},fp="13,247,18.220.0,22.291.0,21.236.0,33.124.0,30.189.0,45.165.0,40.181.0,33.168.1"}
P.entries["quest:426"] = {n="Die überrannte Mühle",s="Die Geißel sammelt sich bei Agamands Mühlen in Tirisfal, nahe den Siedlungen der Verlassenen. Todeswache Dillinger entsendet Soldaten aus Brill, um ihre Reihen zu zerschlagen, bevor die verfallenen Mühlen zur Basis für Angriffe tiefer nach Tirisfal werden.",h="Die Geißel sammelt sich bei Agamands Mühlen in Tirisfal, nahe den Siedlungen der Verlassenen.",kw={"agamands mühlen","geschwärzte schädel","brill","darkeye bonecaster","todeswache dillinger","gekerbte rippen","geißel","die überrannte mühle","tirisfal"},ang={["class:Warrior"]="Als Krieger steht Ihr bei Agamands Mühlen gepanzerten Skeletten gegenüber. Sie empfinden keinen Schmerz und kennen keine Gnade.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, ihren einzigen Stützpunkt im Norden Lordaerons zu sichern, indem Ihr Tirisfal haltet. Die Aufmarschorte der Geißel zu zerstören, hat taktische Priorität.",["race:Undead"]="Als Verlassene helft Ihr, Eure neuen Ländereien zu schützen, indem Ihr die Geißel aus Agamands Mühlen vertreibt. Ihr schlagt gegen die verstandlosen Sklaven des Lichkönigs zu, die Euch einst in Knechtschaft hielten."},sec={{t="Drohende Gefahr bei den Mühlen",b="Agamands Mühlen waren einst das Herz der Landwirtschaft von Tirisfal. Seit dem Dritten Krieg sammeln sich Streitkräfte der Geißel unter ihren Windmühlen, geknechtet vom Lichkönig. Diese verstandlosen Untoten bedrohen die jungen Besitzungen der Verlassenen. Wenn sie die Mühlen einnehmen, haben sie eine Basis für Angriffe tiefer nach Tirisfal und gegen seine Siedlungen."},{t="Beweise der Vernichtung",b="Todeswache Dillinger hilft bei der Befestigung von Brill und patrouilliert im Gebiet. Er schickt Rekruten gegen Rattlecage- und Cracked-Skull-Soldaten sowie Darkeye Bonecaster los. Dillinger verlangt gekerbte Rippen und geschwärzte Schädel als Beweis dafür, dass die Skelettreihen zerschlagen und vor Beginn ihrer Offensive in Richtung der Pestländer zurückgedrängt wurden."}},faq={{q="Warum sammelt sich die Geißel bei Agamands Mühlen?",a="Die Geißel sammelt sich, um im Westen von Tirisfal einen Aufmarschort zu errichten. Von Agamands Mühlen aus kann sie tiefer nach Tirisfal vorstoßen und Siedlungen der Verlassenen wie Brill bedrohen.",al={"warum agamands mühlen","geißel bei den mühlen","warum die mühlen"}},{q="Wer ist Todeswache Dillinger?",a="Todeswache Dillinger ist ein Wachposten der Verlassenen, der in Brill stationiert ist. Er koordiniert Angriffe gegen Gefahren in Tirisfal, darunter die Geißel und feindliche Gnollrudel, die die Straße bedrohen.",al={"todeswache dillinger hintergrund","wer ist dillinger","dillinger brill"}},{q="Wo liegen Agamands Mühlen?",a="Agamands Mühlen liegen nördlich der westlichen Hauptstraße in Tirisfal. Überquert von Brill aus die Flussbrücke im Westen und folgt dann der nördlichen Abzweigung zu den verfallenen Windmühlen.",al={"wo liegen agamands mühlen","lage der mühlen","weg zu den mühlen"}},{q="Warum will Dillinger Rippen und Schädel?",a="Dillinger verlangt Rippen und Schädel als Beweis dafür, dass die Frontlinie der Geißel durchbrochen wurde. Skelettierte Fußsoldaten tragen gekerbte Rippen, während Knochenwirker geschwärzte Schädel hinterlassen.",al={"gekerbte rippen geschwärzte schädel","warum rippen und schädel"}},{q="In welchem Verhältnis stehen die Verlassenen und die Geißel hier zueinander?",a="Die Verlassenen sind Untote, die sich von der geistigen Herrschaft des Lichkönigs befreit haben. Die Geißel bleibt seinem Willen als verstandlose Sklaven unterworfen und will die Verlassenen vernichten und Lordaeron für ihren Meister zurückerobern.",al={"verlassene gegen geißel","warum andere untote bekämpfen"}},{q="Was geschieht, nachdem diese Streitkräfte der Geißel beseitigt wurden?",a="Die Fußsoldaten zurückzudrängen ist nur ein erster Schlag gegen die Geißel bei Agamands Mühlen. Dillinger und die Deathguards dringen immer tiefer in das Mühlengelände vor, gegen die dort verschanzten Befehlshaber und dunklen Mächte.",al={"what comes next","nach die überrannte mühle"}}},fx={e729259a={q="Warum möchte Todeswache Dillinger, dass dies erledigt wird?",a="Todeswache Dillinger ist damit beauftragt, Brill zu verteidigen und Tirisfal für die Verlassenen zu sichern. Die Geißel versucht, eine vorgeschobene Operationsbasis in den Agamands Mühlen zu errichten, was es den gedankenlosen Schergen des Lichkönigs ermöglichen würde, tiefer in Tirisfal einzudringen und den Umkreis der Unterstadt zu bedrohen. Sie zu zerschlagen, bevor sie ihren Stützpunkt festigen, ist entscheidend, um die Region zu halten.",al={"warum agamands mühlen säubern","dillingers beweggrund","warum die geißel bei den mühlen zerstören"}}},fp="17,219,29.338.0,20.335.0,47.172.0,28.190.0,36.172.0,40.167.0,67.196.0,42.211.0"}
P.entries["quest:4265"] = {n="Flucht aus dem Schwarmbau",s="In der Gewundenen Tiefe lebt Raschal noch, doch der Zukk'ash-Schwarmbau hat ihn schwer betäubt zurückgelassen. Er braucht jemanden, der Ginro Hearthkindle in der Mondfederfeste benachrichtigt.",h="In der Gewundenen Tiefe lebt Raschal noch, doch der Zukk'ash-Schwarmbau hat ihn schwer betäubt zurückgelassen.",kw={"kurier","mondfederfeste","feralas","ginro hearthkindle","kokon","raschal","die gewundene tiefe","zukk'ash"},sec={{t="Aus dem Kokon",b="Ihr helft einem Nachtelfen aus dem Kokon herunter, und er beginnt sich zu regen. Er stellt sich als Raschal vor und sagt, die Insekten hätten ihn überwältigt und gelähmt im Inneren zurückgelassen. Obwohl er gesund aussieht, ist er noch immer schwer betäubt. Er fragt, ob die Feste Euch geschickt hat."},{t="Nachricht für die Mondfederfeste",b="Ginro Hearthkindle wartet in der Mondfederfeste. Sagt ihm, dass Raschal lebt und wohlauf ist."},{t="Zurück in der Feste",b="Raschal hat die Feste erreicht und Ginro erzählt, was geschehen ist. Ginro sagt, die ganze Feste könne Euch gar nicht genug danken. Raschal wäre ohne Euer rechtzeitiges Eintreffen gestorben, und Ihr habt keinen Söldnerlohn verlangt. Ginro nennt Euch einen wahren Helden und für immer seinen Freund."}},faq={{q="Wer ist im Zukk'ash-Kokon gefangen?",a="Raschal, ein Nachtelf und der vermisste Kurier, ist im Zukk'ash-Kokon gefangen. Die Insekten haben ihn überwältigt und gelähmt im Inneren zurückgelassen.",al={"wer ist im kokon","wer ist raschal","flucht aus dem schwarmbau gefangener elf"}},{q="Wem soll ich Bescheid geben, sobald Raschal frei ist?",a="Sagt Ginro Hearthkindle in der Mondfederfeste, dass Raschal lebt und wohlauf ist.",al={"wo flucht aus dem schwarmbau abgeben","mit wem nach raschals befreiung sprechen","ginro hearthkindle standort"}},{q="Was kam bei der Suche davor?",a="Die Suche schließt an die Gewundene Tiefe an, wo Ihr den Kokon gefunden habt.",al={"welche quest kommt vor flucht aus dem schwarmbau","flucht aus dem schwarmbau voraussetzungen","vorherige quest"}}},fp="19,155,14.240.0,31.87.0,22.267.1,39.137.0,35.81.0,36.62.0"}
P.entries["quest:4266"] = {n="Der Empfang eines Helden",s="Generalin Shandris Mondfeder hat darum gebeten, Euch persönlich zu sehen. Ginro Hearthkindle glaubt, dass sie Euch für Eure Hilfe für die Mondfederfeste danken und über die Zukk'ash-Insekten sprechen möchte, denen Ihr und Raschal im südlichen Feralas begegnet seid.",h="Generalin Shandris Mondfeder hat darum gebeten, Euch persönlich zu sehen.",kw={"der empfang eines helden","mondfederfeste","feralas","ginro hearthkindle","bau","raschal","shandris mondfeder","zukk'ash"},sec={{t="Eine Vorladung",b="Ginro Hearthkindle sagt, dass Generalin Shandris Mondfeder im Hauptquartier der Mondfederfeste wartet. Die Berichte über die Zukk'ash-Insekten machen ihm Angst."},{t="An der Seite der Generalin",b="Generalin Shandris Mondfeder dankt Euch herzlich für Eure Hilfe für die Mondfederfeste und überreicht Euch ein Geschenk. Sie sagt, Eure Tapferkeit angesichts einer überwältigenden Übermacht verdiene tausendmal mehr. In Feralas wurde ein Bau der Zukk'ash entdeckt, weshalb sie Euch erneut um Hilfe bittet. Sie hält Euch für die beste Wahl."}},faq={{q="Warum möchte Generalin Mondfeder mich sehen?",a="Ginro vermutet, dass Generalin Shandris Mondfeder Euch für Eure Hilfe danken und über die Zukk'ash-Insekten sprechen möchte, denen Ihr und Raschal im südlichen Feralas begegnet seid.",al={"warum shandris treffen","shandris vorladung","der empfang eines helden warum"}},{q="Wer schickt Euch zu Shandris Mondfeder?",a="Ginro Hearthkindle sagt, dass Generalin Shandris Mondfeder Euch persönlich sehen möchte.",al={"wer beginnt der empfang eines helden","questgeber empfang eines helden","ginro hearthkindle quest"}},{q="Wo befindet sich Generalin Shandris Mondfeder?",a="Generalin Shandris Mondfeder wartet im Hauptquartier der Mondfederfeste.",al={"wo ist shandris","mondfederfeste generalin standort","shandris mondfeder finden"}},{q="Was ist an den Zukk'ash-Insekten beunruhigend?",a="Ginro findet die Berichte über die Zukk'ash-Insekten beängstigend, und Generalin Shandris Mondfeder möchte mit Euch darüber sprechen.",al={"was sind zukk'ash","warum sind zukk'ash gefährlich","insektenbau feralas"}}},fp="16,216,9.159.0,21.289.1,44.149.0,49.80.0,46.87.0,47.128.0"}
P.entries["quest:4267"] = {n="Aufstieg der Silithid",s="In Darnassus ist eine Abschrift von Raschals Bericht für Gracina Spiritmight bestimmt. Generalin Shandris Mondfeder übergibt sie Euch im Vertrauen auf das Wissen der Priesterin über solche Kreaturen.",h="In Darnassus ist eine Abschrift von Raschals Bericht für Gracina Spiritmight bestimmt.",kw={"darnassus","mondfederfeste","feralas","gracina spiritmight","raschal","shandris mondfeder","silithiden","tempel des mondes"},sec={{t="Eine Abschrift fürs Protektorat",b="Generalin Shandris Mondfeder vertraut Euch eine Abschrift von Raschals Bericht für Gracina Spiritmight an, eine Verbündete des Protektorats. Der Hauptbericht wurde in Darnassus hinterlegt, wo Gracina als Priesterin im Tempel des Mondes lebt. Shandris glaubt, dass ihr umfassendes Wissen über solche Kreaturen allen zugutekommen wird, die den Bericht erhalten. Sie schickt Euch mit guten Wünschen und einem Gebet weiter, dass Elune über alle wachen möge."},{t="Das Wissen der Priesterin",b="Gracina Spiritmight heißt Euch im gesegneten Tempel des Mondes willkommen. Die Nachtelfen kennen den Schrecken, den Raschal beschreibt, bereits, sagt sie. Die Silithiden werden Feralas rasch verschlingen und zu den größten Gefahren zählen, denen sich jemals jemand stellen muss. Doch sie sind nur Werkzeuge einer der schwerwiegendsten Bedrohungen, denen die Horde und die Allianz jemals gegenüberstehen werden. Gracina betet darum, dass sich die Entschlossenheit findet, sie zu besiegen, bevor sie uns vernichten."}},faq={{q="Wer schickt Euch mit diesem Bericht nach Darnassus?",a="Generalin Shandris Mondfeder übergibt Euch eine Abschrift von Raschals Bericht für Gracina Spiritmight in Darnassus.",al={"wer startet aufstieg der silithid","questgeber aufstieg der silithid","wer vergibt aufstieg der silithid"}},{q="Wer ist Gracina Spiritmight?",a="Gracina Spiritmight ist eine Priesterin, die im Tempel des Mondes in Darnassus lebt. Shandris Mondfeder nennt sie eine Verbündete des Protektorats mit umfassendem Wissen über die Kreaturen in Raschals Bericht.",al={"wer ist gracina","gracina spiritmight hintergrundgeschichte","wo ist gracina spiritmight"}},{q="Wovon handelt Raschals Bericht?",a="Raschals Bericht handelt vom Befall im südöstlichen Feralas.",al={"was ist raschals bericht","was hat raschal gefunden","inhalt von raschals bericht"}},{q="Was ging dieser Übergabe voraus?",a="Dies folgt auf A Hero's Welcome, wo Ihr Generalin Mondfeder in der Stronghold begegnet seid.",al={"aufstieg der silithid voraussetzung","welche quest kommt vor aufstieg der silithid"}}},fp="20,175,27.418.0,24.405.1,44.104.0,27.203.0,31.67.0,31.83.0"}
P.entries["quest:427"] = {n="Im Krieg mit dem Scharlachroten Kreuzzug",s="In Tirisfal schickt Euch Exekutor Zygand gegen den Scharlachroten Kreuzzug. Exekutor Arren hat Informationen beschafft, und Euer erstes Ziel sind Scharlachrote Krieger an einem Turm westlich von Sollidens Bauernhof. Dieser Angriff eröffnet den Feldzug der Verlassenen, um die Kreuzfahrer von ihren Grenzen zu vertreiben.",h="In Tirisfal schickt Euch Exekutor Zygand gegen den Scharlachroten Kreuzzug.",kw={"brill","todeswache","scharlachroter kreuzzug","scharlachrote krieger","sollidens bauernhof","sylvanas","tirisfal","zygand"},ang={["faction:Horde"]="Als Mitglied der Horde braucht Ihr eine sichere Grenze um Tirisfal und Unterstadt. Sie verschafft der Horde einen dauerhaften Stützpunkt in den Östlichen Königreichen.",["race:Undead"]="Als Verlassene steht Ihr lebenden ehemaligen Landsleuten gegenüber, die Euch Ungeheuer nennen und Eure Vernichtung anstreben, statt Lordaerons tragischen Untergang zu betrauern."},sec={{t="Ein Zweifrontenkrieg",b="Die Verlassenen von Fürstin Sylvanas Windläufer sind an mehreren Fronten bedroht. Die Todeswache beobachtet die wachsenden Armeen des Lichkönigs, während der Scharlachrote Kreuzzug die Herrschaft der Verlassenen über ihre einstige Heimat anficht. Der Kreuzzug erklärt alle Untoten zu Monstrositäten, die mit Feuer und Schwert ausgemerzt werden müssen. Seine Fanatiker erkennen nicht, dass sich die Verlassenen von der Kontrolle der Geißel befreit haben."},{t="Angriff auf den Westaußenposten",b="In Todesend stellte Exekutor Arren Dokumente sicher, die zeigen, wo in ganz Tirisfal Lager und Außenposten des Scharlachroten Kreuzzugs liegen. Die Todeswache ist mit der Eindämmung der Geißel beschäftigt, deshalb greifen unabhängige Champions der Verlassenen die Fanatiker direkt an. Ihr erstes Ziel ist ein Wachturm westlich von Sollidens Bauernhof. Dort sammeln sich Scharlachrote Krieger und bedrohen die westlichen Zugangswege nach Brill."}},faq={{q="Warum ist der Scharlachrote Kreuzzug den Verlassenen feindlich gesinnt?",a="Der Scharlachrote Kreuzzug ist ein extremistischer Menschenorden, der sich der Vernichtung der Untoten verschrieben hat. Er unterscheidet nicht zwischen der willenlosen Geißel unter dem Lichkönig und den Verlassenen mit freiem Willen, die Fürstin Sylvanas treu ergeben sind. Für den Kreuzzug ist jeder Untote ein seuchenverseuchtes Ungeheuer, das verbrannt werden muss.",al={"warum scharlachrote untote hassen","beweggründe des scharlachroten kreuzzugs","warum greifen sie an"}},{q="Wer ist Exekutor Zygand?",a="Exekutor Zygand ist der ranghöchste Offizier der in Brill stationierten Todeswache der Verlassenen. Er leitet Truppenentsendungen, verteidigt die Zufahrtsstraßen zur Hauptstadt und beaufsichtigt Angriffe gegen nahe Truppen des Scharlachroten Kreuzzugs und der Geißel.",al={"wer ist zygand","brill questgeber exekutor","zygands geschichte"}},{q="Wie erhielten die Verlassenen Informationen über die Stellungen des Scharlachroten Kreuzzugs?",a="Rekruten im Dienst von Exekutor Arren beschafften taktische Dokumente in Todesend. Die Papiere beschrieben Patrouillenrouten, Außenposten und Lager des Scharlachroten Kreuzzugs in ganz Tirisfal. Exekutor Zygand nutzte diese Informationen, um gezielte Gegenangriffe zu planen.",al={"dokumente des scharlachroten kreuzzugs","arrens informationen","wie fanden sie den turm"}},{q="Wo befinden sich die Scharlachroten Krieger?",a="Scharlachrote Krieger halten einen Wehrturm westlich von Sollidens Bauernhof, im Westen der ländlichen Gebiete von Tirisfal.",al={"standort scharlachroter krieger","wo ist der turm","sollidens bauernhof turm"}},{q="Warum geht die Todeswache nicht direkt gegen den Kreuzzug vor?",a="Die Reihen der Todeswache sind durch die Überwachung der Geißel stark beansprucht, deren Truppen unter dem Einfluss des Lichkönigs jede Nacht zahlreicher werden. Da die regulären Soldaten mit ihrer Eindämmung beschäftigt sind, setzt Zygand auf unabhängige Champions der Verlassenen, um die Kreuzfahrer anzugreifen.",al={"warum spieler schicken","wo ist die todeswache","warum zygand helfen"}},{q="Beendet diese Mission die Präsenz des Scharlachroten Kreuzzugs in Tirisfal?",a="Nein. Der Angriff auf den westlichen Wachturm ist der erste Schlag in einem vierteiligen Feldzug. Exekutor Zygand leitet ihn, um die Führung und die Außenposten des Scharlachroten Kreuzzugs in der gesamten Region zu zerschlagen.",al={"ist dies die letzte quest des scharlachroten kreuzzugs","questreihe des scharlachroten kreuzzugs"}}},fx={["3cb6349f"]={q="Warum möchte Exekutor Zygand, dass die Scharlachroten Krieger getötet werden?",a="Da geborgene Informationen Scharlachrote Kreuzzug-Lager in ganz Tirisfal offenbaren, sieht Exekutor Zygand eine wichtige Gelegenheit, gegen diese Eiferer zurückzuschlagen. Der Kreuzzug versucht, alle Untoten auszurotten, was sie zu einer tödlichen Bedrohung für Brill und die Grenzen der Verlassenen macht, wenn sie nicht kontrolliert werden.",al={"warum scharlachrote krieger töten","zygands beweggrund","warum den scharlachroten kreuzzug angreifen"}},["82f56bdf"]={q="Wer sind die Scarlet Warriors am Turm?",a="Sie sind militante Eiferer des Scharlachroten Kreuzzugs, die im Wachturm westlich von Sollidens Bauernhof stationiert sind. Getrieben von fanatischem Hass betrachten sie alle Verlassene als gedankenlose Monster der Geißel, die ausgerottet werden müssen, und führen einen unerbittlichen Krieg, um Lordaeron von den Untoten zurückzuerobern.",al={"wer sind die scarlet warriors","scarlet warriors tirisfal","wen töte ich"}}},fp="31,281,15.361.0,28.372.0,55.278.0,23.233.0,59.238.0,39.114.0,55.252.0,55.173.0"}
P.entries["quest:428"] = {n="Die verlorenen Todespirscher",s="Im nördlichen Silberwald werden seit Wochen zwei Späher der Verlassenen vermisst. Hochexekutor Hadrec schickte Rane und Quinn Yorick, um die verlassenen Höfe zu beobachten, und nun sucht Ihr nach Nachricht von ihnen.",h="Im nördlichen Silberwald werden seit Wochen zwei Späher der Verlassenen vermisst.",kw={"deathstalkers","hadrec","quinn yorick","rane yorick","aufklärung","geißel","das grabmal","silberwald"},ang={["class:Rogue"]="Als Schurke kennt Ihr die Yoricks als Mitstreiter aus den Schatten. Ihre Notlage zeigt, dass selbst erfahrene Todespirscher durch Verstohlenheit nicht immer vor den Gefahren des Nordens geschützt sind.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass der Silberwald einen sicheren Korridor zwischen Unterstadt und dem südlichen Lordaeron sichert. Aufklärung hilft, diesen Weg zu schützen.",["race:Undead"]="Als Verlassener wisst Ihr, dass jeder vermisste Agent eine Lücke in der fragilen Verteidigung des Silberwalds hinterlassen kann. Eure Angehörigen zu finden hilft, das Grabmal vor plötzlichen Angriffen zu schützen."},sec={{t="Schweigen aus dem Norden",b="Im Grabmal hat Hochexekutor Hadrec seit Wochen nichts von Rane und Quinn Yorick gehört. Er schickte die beiden in den nördlichen Silberwald, um die verlassenen Höfe zu beobachten und feindliche Bewegungen zu verfolgen. Die Todespirscher sind die verborgenen Späher und Mörder der Verlassenen. Sie dienen Fürstin Sylvanas, und Hadrec fürchtet, dass die Geißel oder eine andere Bedrohung sie niedergestreckt hat."},{t="Die Gefahr im Norden",b="Der nördliche Silberwald liegt zwischen Lordaerons verfallenen Anwesen und den schattigen Grenzen von Tirisfal. Dort streifen Untote umher, Bestien lauern, und wilde Worgen machen Reisen selbst für erfahrene Schurken gefährlich. Durchsucht die verfallenden Gehöfte, wo Rane und Quinn Yorick ihre Erkundung begannen. Alle Informationen, die sie gesammelt haben, könnten entscheidend sein, sofern die Gefahr sie nicht vorher ereilt hat."},{t="Gefangen in den Schatten",b="Rane und Quinn Yorick leben, sitzen aber auf einem Bauernhof fest und versuchen verzweifelt zu entkommen. Sie flohen vor einem Angriff des Ghuls Ivar the Foul, doch Quinn wurde schwer zugerichtet. Ivar lauert in der Nähe und hält die beiden Todespirscher in die Enge getrieben. Ihre Rettung zieht die Verlassenen tiefer in den Kampf gegen die wilden Bedrohungen jenseits der Straße."}},faq={{q="Wer sind Rane und Quinn Yorick?",a="Rane und Quinn Yorick sind Späher der Verlassenen bei den Todespirschern, dem Spionage- und Meuchelmordzweig der Verlassenen. Sie sollten die Gehöfte des Silberwalds erkunden und verschwanden dann.",al={"wer sind die yoricks","wer sind die verlorenen todespirscher","geschichte von rane und quinn"}},{q="Warum sorgt sich Hochexekutor Hadrec um sie?",a="Hochexekutor Hadrec leitet vom Grabmal aus die Militäreinsätze der Verlassenen. Da zwei Späher vermisst werden, fehlen den Verlassenen Berichte über feindliche Aktivitäten entlang ihrer nördlichen Grenzen, wo die Geißel noch immer lauert.",al={"warum sorgt sich hadrec","wer schickte die yoricks","hadrecs vermisste späher"}},{q="Wo verschwanden die Yoricks?",a="Die Yoricks verschwanden bei der Erkundung des nördlichen Silberwalds. Ihr Weg führte durch die verfallenden Gehöfte nördlich des Grabmals.",al={"wo sind die deathstalkers","yoricks aufenthaltsort","wo sind rane und quinn zu finden"}},{q="Welchen Bedrohungen begegnen die Todespirscher im nördlichen Silberwald?",a="Überreste der Geißel, aggressive Raubtiere und wilde Worgen bedrohen Späher im nördlichen Silberwald. Jede dieser Gefahren kann Alleinreisende das Leben kosten.",al={"was ist ihnen passiert","gefahren im silberwald","warum verschwanden sie"}},{q="Was geschieht, nachdem die vermissten Todespirscher gefunden wurden?",a="Wenn Ihr Rane Yorick findet, helft Ihr den verletzten Spähern im Rahmen von Wild Hearts, sich zu erholen. Dabei tretet Ihr örtlichen Bedrohungen wie Ivar the Foul entgegen.",al={"was ist die nächste quest","nach den verlorenen todespirschern","questreihe nach yorick"}},{q="Was sind die Todespirscher für eine Organisation?",a="Die Todespirscher sind das Korps der Spione, Späher und Meuchelmörder der Verlassenen. Sie dienen der Dark Lady als ihre geheime Vorhut in ganz Lordaeron.",al={"was sind deathstalkers","orden der deathstalkers","meuchelmörder der verlassenen"}}},fp="18,181,24.353.0,18.367.0,22.313.1,30.192.0,49.215.0,32.138.0,62.133.0,53.146.1,45.146.0"}
P.entries["quest:4281"] = {n="Thalanaar-Lieferung",s="In den Lagern der Woodpaw wartet noch ein Paket für Thalanaar auf seinen Empfänger. Der handgeschriebene Name könnte Euch dorthin führen.",h="In den Lagern der Woodpaw wartet noch ein Paket für Thalanaar auf seinen Empfänger.",kw={"falfindel wegeshut","mondfederfeste","feralas","raschal","thalanaar","unzustellbares paket","woodpaw"},sec={{t="Ein verloren gegangenes Paket",b="Ihr findet Waren für Thalanaar in den Gnolllagern der Woodpaw. Die kleine Wegstation liegt im Südosten von Feralas. Ein handgeschriebener Name auf dem Paket weist Euch zu der Person, die die Waren erwartet: Falfindel Wegeshut."},{t="Nachricht an der Wegstation",b="Falfindel Wegeshut preist Elune, als die Lieferung aus der Mondfederfeste endlich eintrifft. Falfindel fürchtet, dass Raschal, dem üblichen Kurier, ein Unglück widerfahren ist. Etwas südlich der Woodpaw hat sie in Aufruhr versetzt, und Falfindel vermutet, dass Raschal dort der Wildnis zum Opfer fiel. Gebt auf Euren Reisen acht."}},faq={{q="Wer ist Falfindel Wegeshut?",a="Falfindel Wegeshut ist der handgeschriebene Name auf dem Paket. Falfindel ist die Person, die Ihr in Thalanaar finden sollt.",al={"falfindel","wer ist falfindel","falfindel wegeshut thalanaar"}},{q="Wo ist Thalanaar?",a="Thalanaar ist eine kleine Wegstation im Südosten von Feralas. Dorthin sollte das Paket gelangen.",al={"thalanaar ort","wo ist thalanaar"}},{q="Wo wurde das Paket gefunden?",a="Ihr habt das Paket in den Gnolllagern der Woodpaw gefunden.",al={"woher kam das paket","herkunft des pakets","herkunft des unzustellbaren pakets"}},{q="Was ist mit dem Boten geschehen?",a="Das Schicksal des Kuriers ist unbekannt. Die Lieferung ist noch nicht abgeschlossen, und das Paket muss Thalanaar noch erreichen.",al={"wer war der bote","name des vermissten boten","wer trug das paket"}}},fp="18,118,20.213.0,23.305.1,27.113.0,19.99.0,27.48.0,29.110.0"}
P.entries["quest:429"] = {n="Wilde Herzen",s="Im Silberwald sucht Rane Yorick Hilfe, während ihr Bruder Quinn schwer verwundet darniederliegt. Sie braucht verfärbte Worgherzen für Apotheker Renferrel im Grabmal, dessen Alchemie Quinn bei der Genesung helfen könnte.",h="Im Silberwald sucht Rane Yorick Hilfe, während ihr Bruder Quinn schwer verwundet darniederliegt.",kw={"apotheker renferrel","verfärbtes worgherz","ivar the foul","maldens obsthain","quinn yorick","rane yorick","das grabmal","silberwald","wilde herzen"},ang={["class:Rogue"]="Als Schurke seht Ihr erfahrene Todespirscher, die ein wilder Ghul niedergerungen hat. Ihr Schicksal zeigt, wie viel Heimlichkeit und Geschick nötig sind, um in Lordaerons Wildnis zu überleben.",["race:Undead"]="Als Untoter wisst Ihr, dass die Verlassenen durch rücksichtslosen Pragmatismus überleben. Selbst Brüderlichkeit kann von zusammengesuchten Organen und kalter Alchemie abhängen statt von Divine Grace."},sec={{t="Die Verzweiflung eines Bruders",b="Rane Yorick bleibt bei ihrem schwer verwundeten Bruder Quinn, nachdem die verheerende Mission der Todespirscher sie auf einem Bauernhof im nördlichen Silberwald festgesetzt hatte. Der wilde Ghul Ivar the Foul hat ihn übel zugerichtet, und er erholt sich nicht. Gewöhnliche Ruhe kann einen untoten Körper nicht heilen, der so grausam zerfleischt wurde. Deshalb wendet sich Rane an die Royal Apothecary Society und ihre finsteren Künste, um ihren Bruder wieder zusammenzuflicken."},{t="Alchemie der geißelverseuchten Wildnis",b="Die Worgs des Silberwalds tragen die Verderbnis in sich, die sich im nördlichen Lordaeron ausbreitet. Ihre Herzen sind verfärbt und enthalten mächtige Essenzen. Die Royal Apothecaries können diese verseuchten Organe zu Gebräuen destillieren, die verdorrtes Fleisch der Verlassenen wiederherstellen."},{t="Renferrels kalte Pflicht",b="Apotheker Renferrel arbeitet im Grabmal, wo er Ranes Bitte mit Verärgerung statt Mitgefühl begegnet. Fürstin Sylvanas Windläufer hat ihn mit dringenden Forschungen beauftragt, und es missfällt ihm, dass die Royal Apothecary Society als Feldsanitäter für ungeschickte Späher herhalten muss. Dennoch nimmt er die grausigen Zutaten entgegen und bereitet einen Trank zu, um die Agenten der Dunklen Fürstin einsatzbereit zu halten."}},faq={{q="Warum braucht Quinn Yorick Worgherzen, um zu genesen?",a="Die Körper der Verlassenen brauchen besondere alchemistische Hilfe, um zu heilen. Ivar the Foul hat Quinn schwer verwundet, und die Royal Apothecary Society braut aus verdorbenen, verfärbten Worgherzen aus dem Silberwald Stärkungsmittel für untotes Gewebe.",al={"warum worgherzen","quinn heilen","heiltrankrezept"}},{q="Wo sind die verfärbten Worgherzen zu finden?",a="Sucht verfärbte Worgherzen bei den Worgs, die den mittleren Silberwald durchstreifen, besonders zwischen der Straße, an der die Yorick-Geschwister festsitzen, und Maldens Obsthain im Osten.",al={"wo sind die worgs","worgfundorte silberwald","worgherzen farmen"}},{q="Wer ist Ivar the Foul?",a="Ivar the Foul ist ein gefährlicher Ghul auf dem Bauernhof, auf dem die Yoricks Zuflucht suchten. Er griff Rane und Quinn an, als sie dort auf Erkundung waren. Beide entkamen, doch Quinn wurde übel zugerichtet.",al={"wer ist ivar","ivar the foul hintergrundgeschichte","ghul ivar"}},{q="Warum ärgert sich Apotheker Renferrel über die Aufgabe?",a="Apotheker Renferrel arbeitet im Grabmal, wo ihn die Dunkle Fürstin mit ernsten Aufgaben betraut hat. Er betrachtet die gescheiterte Erkundungsmission der Todespirscher als Blamage und als Ablenkung von seinen bedeutenderen alchemistischen Experimenten.",al={"warum ist renferrel verärgert","renferrel dialog","renferrels haltung"}},{q="Was geschieht, nachdem die Herzen Renferrel übergeben wurden?",a="Nachdem Renferrel die verfärbten Herzen verarbeitet hat, schickt er Euch mit einem stärkenden Trank zurück zu Rane und Quinn Yorick. Er kann Quinn helfen, sich so weit zu erholen, dass er Rache nehmen kann.",al={"nächste quest nach wilde herzen","was mit dem trank tun"}},{q="Warum brauchen die Todespirscher Hilfe von einem Abenteurer?",a="Rane Yorick kann Quinn nicht von der Seite weichen, solange er schwer verletzt ist, und umherstreifende Geißeltruppen und Bestien drohen mit einem weiteren Hinterhalt. Sie ist auf vorbeiziehende Reisende der Horde angewiesen, die die Organe sammeln und ihre Bitte zum Grabmal tragen.",al={"warum kann rane die herzen nicht holen","versagen der deathstalkers"}}},fx={a9c32125={q="Warum möchte Rane Yorick, dass Ihr Worg-Herzen sammelt?",a="Rane Yorick ist verzweifelt und will ihren Bruder Quinn retten, der bei einem katastrophalen Scharmützel gegen den mächtigen Ghul Ivar the Foul schwer verletzt wurde. Da sie weiß, dass normale Ruhe nicht ausreichen wird, um Quinns beschädigten Körper als Untoter zu heilen, sucht Rane nach einem Gebräu eines Apothekers aus lokalen Worg-Herzen, um ihn wiederherzustellen, bevor er seinen Wunden erliegt.",al={"warum will rane worg-herzen","rane yorick beweggrund","warum quinn yorick helfen"}}},fp="11,195,23.401.0,36.243.0,21.376.1,47.207.0,46.179.0,21.170.0,48.217.0,50.168.1,54.217.0"}
P.entries["quest:4297"] = {n="Essen für das Baby",s="Agnar Beastamer kümmert sich um Euer Ei, bis es schlüpft. Grimmlingflitzer fressen Fleisch und Pflanzen, und ihre Jungen bevorzugen rohe, saftige Flanken. Agnar möchte Silvermane stalker flanks für das Jungtier haben.",h="Agnar Beastamer kümmert sich um Euer Ei, bis es schlüpft.",kw={"agnar beastamer","ei","elune","flanken","hinterland","allesfresser","silvermane stalker","grimmlingflitzer"},sec={{t="Die erste Mahlzeit",b="Agnar Beastamer sagt, dass Grimmlingflitzer Fleisch und Pflanzen fressen. Ihre Jungen bevorzugen rohe, saftige Flanken. Agnar kümmert sich um das Ei, bis es schlüpft, und möchte Silvermane stalker flanks für das Jungtier haben. Ohne eine gute erste Mahlzeit könnte das Neugeborene seine erste Woche nicht überleben."},{t="Elunes Plan",b="Agnar hat nie erfahren, warum Grimmlingflitzer Fleisch fressen. Agnar weiß nur, dass es mit Elunes Plan für die Elfen zusammenhängt. Vielleicht waren sie als Beschützer gedacht, überlegt Agnar, kann es aber nicht mit Sicherheit sagen. Agnar gibt auch zu, neidisch darauf zu sein, dass Ihr das Ei bekommen habt."},{t="Zurück mit den Flanken",b="Als Ihr mit den Flanken zurückkehrt, befindet Agnar sie für gut genug. Das Ei sieht aus, als würde es jeden Moment schlüpfen. Agnar neckt Euch damit, dass Ihr bald Mutter oder Vater werdet, obwohl Ihr mit dieser Art von Verantwortung nicht gerechnet habt."}},faq={{q="Was frisst ein Grimmlingflitzer?",a="Grimmlingflitzer fressen Fleisch und Pflanzen. Agnar Beastamer sagt, dass rohe, saftige Flanken für die Jungen geeignet sind.",al={"grimmlingflitzer ernährung","was fressen grimmlingflitzer","sprite dragon futter"}},{q="Wo kümmert sich Agnar Beastamer um das Ei?",a="Agnar kümmert sich im Hinterland um das Ei, wohin das Fleisch gebracht wird.",al={"agnar beastamer aufenthaltsort","wo ist agnar"}},{q="Welches Fleisch möchte Agnar haben?",a="Agnar möchte fünf Silvermane stalker flanks für das Jungtier haben.",al={"welches fleisch besorgen","essen für das baby fleisch","stalker flanks"}},{q="Was verbindet Elune mit den Grimmlingflitzern?",a="Agnar hat nie erfahren, warum Grimmlingflitzer Fleisch fressen, nur, dass es mit Elunes Plan für die Elfen zusammenhängt. Agnar fragt sich, ob sie als Beschützer gedacht waren.",al={"elune grimmlingflitzer","warum fleisch elune"}},{q="Was passiert, wenn das Jungtier keine gute erste Mahlzeit bekommt?",a="Ohne eine gute erste Mahlzeit könnte das Jungtier seine erste Woche nicht überleben, warnt Agnar.",al={"jungtier ohne futter","wird das baby überleben"}}},fp="13,194,24.275.0,12.253.0,20.214.1,30.99.0,44.70.0,26.61.0,41.151.0,53.92.0"}
P.entries["quest:4298"] = {n="Elternfreuden",s="Im Hinterland hat Agnar Beastamer Neuigkeiten: Das Ei ist weiter entwickelt als erwartet. Er möchte mit Euch sprechen.",h="Im Hinterland hat Agnar Beastamer Neuigkeiten: Das Ei ist weiter entwickelt als erwartet.",kw={"agnar beastamer","elternfreuden","ei","food for baby","freedom for all creatures","hinterland","haustier"},sec={{t="Früher als erwartet",b="Das Ei ist weiter entwickelt, als Agnar Beastamer erwartet hat. Ihr habt Nahrung für den Schlüpfling gebracht. Sprecht nun mit Agnar im Hinterland."},{t="Gewissermaßen ein Elternteil",b="Agnar Beastamer gibt Euch das Ei, damit es sich an Euch bindet und Euch als sein Elternteil ansieht. Er gratuliert Euch dazu, gewissermaßen ein Elternteil geworden zu sein."}},faq={{q="Wer hat Neuigkeiten über das Ei?",a="Agnar Beastamer hat Neuigkeiten über das Ei. Er hat sich im Hinterland darum gekümmert.",al={"wer startet elternfreuden","elternfreuden questgeber","agnar beastamer quest"}},{q="Wo finde ich Agnar Beastamer?",a="Agnar Beastamer ist im Hinterland.",al={"elternfreuden ort","wo ist agnar beastamer"}},{q="Was kam vor diesem Schritt?",a="Zuvor habt Ihr in Food for Baby Fleisch für den Schlüpfling gesammelt.",al={"elternfreuden voraussetzung","vorherige quest elternfreuden"}}},fp="17,116,20.141.0,19.142.1,27.88.0,32.38.0,27.66.0"}
P.entries["quest:430"] = {n="Rückkehr zu Quinn",s="Auf dem Ivar-Feld wartet Quinn Yorick auf einen Trank, der ihm vielleicht erlaubt, wieder zu reisen. Apotheker Renferrel schickt Euch mit dem Gemisch vom Grabmal los, während Quinn verwundet in gefährlichem Gebiet ausharrt.",h="Auf dem Ivar-Feld wartet Quinn Yorick auf einen Trank, der ihm vielleicht erlaubt, wieder zu reisen.",kw={"apotheker renferrel","todespirscher erland","deathstalkers","das ivar-feld","quinn yorick","quinns trank","das grabmal","silberwald"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie gefährlich Erkundungen sein können, wenn in Rudeln jagende Raubtiere die Agenten der Todespirscher unvorbereitet erwischen.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass gestrandete Späher Hilfe brauchen, um den Stützpunkt der Horde im Silberwald gegen wilde Worgenrudel zu sichern.",["race:Undead"]="Als Untoter seht Ihr, wie die stärkenden Gemische der Royal Apothecary Society den Spähern der Dark Lady helfen, in feindlichem Gelände weiter ihren Dienst zu tun."},sec={{t="Ein bitterer Trank",b="Nachdem Ihr Herzen wilder Bestien für die Royal Apothecary Society gesammelt habt, braut Apotheker Renferrel am Grabmal einen stärkenden Trank für Quinn Yorick. Er überreicht ihn Euch und kehrt dann zu seinen geheimen alchemistischen Forschungen zurück. Ihr tragt das Gemisch zurück in die Wildnis."},{t="Atempause auf dem Ivar-Feld",b="Auf dem verfallenen Ivar-Feld sucht Quinn Yorick neben seiner Schwester, Deathstalker Rane Yorick, Schutz. Der Ghul Ivar the Foul hat ihn so schwer verwundet, dass er feindliches Gebiet nicht durchqueren kann. Quinn trinkt den Trank, sobald Ihr eintrefft. Er gibt ihm genug Kraft zurück, um mit der Zeit wieder reisen zu können, doch das Gehöft bleibt von Gefahren umgeben und Ivar lauert in der Nähe."}},faq={{q="Wo befindet sich Quinn Yorick?",a="Quinn Yorick sucht auf dem verlassenen Ivar-Feld im nördlichen Silberwald Schutz, weit nördlich des Grabmals.",al={"wo ist quinn","quinn yorick aufenthaltsort","ivar-feld lage"}},{q="Wer hat den Trank für Quinn gebraut?",a="Apotheker Renferrel hat Quinns Trank am Grabmal für die Royal Apothecary Society gebraut und dafür Herzen wilder Bestien aus dem Wald verwendet.",al={"wer hat den trank gebraut","apotheker renferrel trank"}},{q="Warum konnte Quinn nicht aus eigener Kraft weiterziehen?",a="Quinn wurde vom Ghul Ivar the Foul schwer zugerichtet, als er mit seiner Schwester auf Erkundung war. Ohne Ranes Hilfe und Medizin konnte er sich nicht fortbewegen.",al={"warum sitzt quinn fest","quinn yorick verletzt"}},{q="Was geschieht, nachdem Quinn den Trank erhalten hat?",a="Der Trank gibt Quinn genug Kraft zurück, um wieder reisen zu können. Er kann sich darauf vorbereiten, gegen Ivar the Foul zurückzuschlagen, der ihre Stellung bedroht.",al={"wie weiter nach rückkehr zu quinn","nächste quest nach quinn"}},{q="Wer ist Quinns Schwester?",a="Quinns Schwester ist Deathstalker Rane Yorick. Sie blieb auf dem Ivar-Feld an seiner Seite, um ihn zu beschützen und ihnen beiden beim Überleben zu helfen.",al={"quinn yorick schwester","quinn schwester"}},{q="Kümmert Apotheker Renferrel Quinns Schicksal?",a="Renferrel zeigt wenig persönliche Anteilnahme an Quinns Schicksal. Er gibt Euch den Trank und kehrt dann zu seinen geheimen Forschungen für die Royal Apothecary Society zurück.",al={"kümmert es renferrel","renferrel einstellung"}}},fx={fec360eb={q="Warum schickt Euch Apotheker Renferrel zu Quinn zurück, anstatt selbst zu gehen?",a="Apotheker Renferrel betrachtet das Schicksal von Quinn Yorick als nicht viel mehr als eine Unannehmlichkeit, die seine wahre Forschung für die Royal Apothecary Society unterbricht. Da er den stärkenden Trank aus den Wolfsherzen, die Ihr geliefert habt, zusammengemischt hat, ist Renferrel begierig darauf, sofort zu seinen alchemistischen Experimenten zurückzukehren, und hält Botengänge für unter seiner Würde. Die Übergabe einem Abenteurer anzuvertrauen, erlaubt ihm, seine Studien fortzusetzen, ohne weitere Zeit zu verschwenden.",al={"warum ich","warum rennferrel nicht die lieferung","renferrel warum ich"}}},fp="15,200,16.268.0,25.339.0,30.114.0,30.141.0,40.133.0,43.141.1,22.121.0,50.146.0"}
P.entries["quest:431"] = {n="Kerze des Heranlockens",s="In Tirisfal sind Kerzen von Gunthers Insel für eine düstere Prüfung bestimmt. Gunther Arkanus bewahrt sie für eine Treueprüfung auf.",h="In Tirisfal sind Kerzen von Gunthers Insel für eine düstere Prüfung bestimmt.",kw={"kerze des heranlockens","kiste mit kerzen","verlassene","okkult","ritualkerze","tirisfal","unterstadt"},ang={["class:Priest"]="Als Priester versteht Ihr, welche Sorgfalt Gegenstände erfordern, die ruhelose Geister anrufen und unsichtbare Wesen herbeirufen sollen.",["class:Warlock"]="Als Hexenmeister erkennt Ihr den Talg und die magische Resonanz, die beim rituellen Heranlocken verwendet werden.",["race:Undead"]="Als Verlassener bergt Ihr in Tirisfal okkulte Gerätschaften zum Überleben und zum Studium und haltet gefährliche Artefakte von feindlichen Händen fern."},sec={{t="Talg und dunkle Riten",b="Gunther bittet Euch, eine Kerze aus der Kiste auf Gunthers Zufluchtsort zum alten, blutigen Altar vor der Südküste der Insel zu bringen. Zündet sie dort an, und Lillith Nefara, die Agentin der Geißel, wird Euch gegenübertreten."},{t="Ein zurückgewonnenes Relikt",b="Auf Gunthers Zufluchtsort, der Insel im Blendwassersee, auf der Gunther Arkanus lebt, liegen die Kerzen in einer Kiste. Für seine Prüfung in Proving Allegiance genügt eine Kerze. Auf dem alten, blutigen Altar vor der Südküste der Insel entzündet, erweckt sie Lillith Nefara, die Agentin der Geißel."}},faq={{q="Welchen Zweck hat die Kerze des Heranlockens?",a="Zündet eine Kerze des Heranlockens auf dem blutigen Altar nahe Gunthers Zufluchtsort an, um Lillith Nefara für Gunthers Treueprüfung zu erwecken.",al={"was ist die kerze des heranlockens","zweck der kerzen","was bewirken kerzen"}},{q="Wo sind diese Kerzen zu finden?",a="Die Kerzen werden in einer Kiste mit Kerzen auf Gunthers Zufluchtsort aufbewahrt, Gunther Arkanus' Insel im Blendwassersee in Tirisfal.",al={"wo kerze des heranlockens finden","fundort der kerzenkiste","kiste mit kerzen"}},{q="Wer hat diese Kerzen hergestellt?",a="Ein Hersteller wird nicht genannt. Gunther bewahrt auf seiner Insel eine Kiste mit Kerzen für die Prüfung auf, die er in Proving Allegiance stellt.",al={"wer hat die kerze des heranlockens hergestellt","hersteller der kerzen","wer hat die kiste hergestellt"}},{q="Warum wollen die Horde oder die Verlassenen sie haben?",a="Gunther Arkanus braucht eine Kerze für seine Prüfung in Proving Allegiance. Auf dem blutigen Altar vor der Südküste seiner Insel entzündet, erweckt sie Lillith Nefara, die Agentin der Geißel. Ihre Vernichtung beweist, dass Ihr ein Feind des Lich Kings seid.",al={"warum brauchen verlassene kerzen","warum kerzen bergen","warum kerzen für die horde"}},{q="Kann jeder die Kerze benutzen?",a="Für Gunthers Prüfung müsst Ihr die Kerze des Heranlockens auf Lilliths blutigen Esstisch stellen und anzünden, um sie zu beschwören.",al={"kann ich sie anzünden","wie kerze benutzen","kerze des heranlockens benutzen"}},{q="Sind die Kerzen mit der Geißel verbunden?",a="Eine Kerze des Heranlockens erweckt Lillith Nefara, eine mächtige Agentin der Geißel. Gunther bittet Euch, sie zu vernichten, um zu beweisen, dass Ihr ein Feind des Lich Kings seid.",al={"ist das magie der geißel","gehören die kerzen zur geißel","kultkerzen der geißel"}}},fp="20,130,21.198.0,17.275.0,48.129.0,30.129.0,26.109.0,41.220.0,31.120.0,38.143.0"}
P.entries["quest:432"] = {n="Diese verfluchten Troggs!",s="Im Steinbruch Gol'Bolar verwüsten Troggs die Anlagen, während Großknecht Steinbraue um Hilfe ruft. Sie haben seine Ausrüstung und Pulverfässer zerstört. Seine nachlassende Treffsicherheit hindert ihn daran, selbst gegen sie zu kämpfen, also bittet er willige Kämpfer, die Reihen der Schädelbrecher auszudünnen.",h="Im Steinbruch Gol'Bolar verwüsten Troggs die Anlagen, während Großknecht Steinbraue um Hilfe ruft.",kw={"dun morogh","gol'bolar","pulver","steinbruch","rockjaw","schädelbrecher","steinbraue","troggs"},ang={["profession:Mining"]="Als Bergarbeiter kennt Ihr Gol'Bolar für seine Steinmetzarbeiten und seinen Mineralabbau. Die Eindringlinge zu vertreiben ist der erste Schritt, damit die Spitzhacken wieder schwingen.",["race:Dwarf"]="Als Zwerg trifft Euch die Invasion der Troggs in Khaz Modan in der eigenen Heimat. Die Steinmetze wurden aus Gol'Bolar vertrieben, wodurch Rache in der Grube zur persönlichen Angelegenheit wird."},sec={{t="Chaos im Steinbruch",b="Troggs haben die unteren Terrassen des Steinbruchs Gol'Bolar im östlichen Dun Morogh überrannt. Sie durchbrachen das Grundgestein und strömten in die Tunnel, wodurch die ertragreichen Tage der zwergischen Ausgrabungsstätte endeten. Jetzt zertrümmern sie Gerüste und sprengen Pulverfässer, sodass der Steinbruch in Trümmern liegt."},{t="Steinbraues brodelnder Zorn",b="Vom Kamm aus sieht Großknecht Steinbraue zu, wie sein Lebenswerk zerfällt. Das Alter hat seine Hände geschwächt und seine Treffsicherheit verschlechtert, also verlässt er sich auf vorbeiziehende Wanderer und Rekruten der Allianz, die an seiner Stelle kämpfen. Er will die Reihen der stämmigen Rockjaw-Schädelbrecher ausdünnen lassen. Nur ihre vollständige Vernichtung würde seinen Zorn stillen."}},faq={{q="Wo liegt der Steinbruch Gol'Bolar?",a="Der Steinbruch Gol'Bolar liegt im östlichen Dun Morogh, südlich der Hauptstraße, die nach Osten zu den Toren von Loch Modan führt. Großknecht Steinbraue steht am Rand oberhalb der Ausgrabungsgruben.",al={"gol'bolar lage","wo ist der steinbruch","steinbraue standort"}},{q="Warum greifen die Troggs den Steinbruch an?",a="Troggs leben überall in Khaz Modan tief unter der Erde. Zwergische Ausgrabungen stoßen oft in die Höhlen vor, in denen Troggs nisten, und diese drängen an die Oberfläche, um betriebene Minen zu überrennen.",al={"warum troggs hier","grund der trogginvasion"}},{q="Wer ist Großknecht Steinbraue?",a="Großknecht Steinbraue beaufsichtigt den Steinbruch Gol'Bolar. Verbittert und jähzornig schickt er willige Kämpfer los, um die Troggs zu vertreiben, weil seine Kampffertigkeiten nachlassen.",al={"steinbraue","wer gibt die quest"}},{q="Was ist ein Rockjaw-Schädelbrecher?",a="Rockjaw-Schädelbrecher sind brutale Kämpfer an vorderster Front des Troggstamms im Steinbruch Gol'Bolar. Sie setzen rohe Kraft und primitive Keulen ein, um Eindringlinge niederzuknüppeln.",al={"schädelbrecher"}},{q="Warum kann Steinbraue den Steinbruch nicht selbst räumen?",a="Steinbraue sagt, seine Sehkraft und Treffsicherheit hätten seit seiner Jugend nachgelassen. Wegen seines Alters droht er in den Steinbruchgruben überwältigt zu werden, also heuert er Abenteurer an, die dort kämpfen.",al={"warum kämpft steinbraue nicht"}},{q="Was zerstören die Troggs im Steinbruch?",a="Troggs zerstören schweres Gerät und stören den Bergbau im Steinbruch. Sie sprengen außerdem Vorräte, darunter Fässer mit zwergischem Sprengpulver.",al={"verwüstung durch troggs","was zerstören die troggs"}}},fx={dd6a776f={q="Warum möchte Großknecht Steinbraue, dass die Troggs getötet werden?",a="Großknecht Steinbraue ist außer sich vor Wut, während er mit ansehen muss, wie sein Lebenswerk zerstört wird. Die eindringenden Troggs haben Steinbruch Gol'Bolar überrannt, die Ausrüstung zerschmettert und sein wertvolles Sprengpulver zur Explosion gebracht. Da ihm nichts als Stress und kochende Wut geblieben sind, will Steinbraue reine Rache: Er möchte sehen, wie jeder einzelne Trogg dort unten vernichtet wird, damit sich sein Blutdruck beruhigen und die Ordnung schließlich an den Ort zurückkehren kann.",al={"stonebraue beweggrund","warum troggs töten","stonebraue steinbruch rache"}}},fp="21,245,19.272.0,24.300.0,26.167.0,40.179.0,25.159.0,31.158.0,45.167.0,45.153.0"}
P.entries["quest:433"] = {n="Im Dienste des Volkes",s="Am Steinbruch Gol'Bolar bittet Senator Mehr Steingunst um Hilfe gegen Troggs, die den Bergbau in Dun Morogh zum Erliegen gebracht haben. Er will die Knochenknacker der Felskiefer vertreiben lassen, damit die Bergleute wieder arbeiten können.",h="Am Steinbruch Gol'Bolar bittet Senator Mehr Steingunst um Hilfe gegen Troggs, die den Bergbau in Dun Morogh...",kw={"knochenknacker","dun morogh","gol'bolar","steinbruch","felskiefer","senat","steingunst","trogg"},ang={["faction:Alliance"]="Als Mitglied der Allianz seid Ihr auf die Ressourcen von Eisenschmiede angewiesen. Die Sicherheit der Steinbrüche von Dun Morogh ist für die Versorgung der Allianz von Bedeutung.",["profession:Mining"]="Als Bergmann wisst Ihr, was die Schließung von Gol'Bolar kostet. Troggs halten nun die Steinvorkommen und Erzadern des Steinbruchs besetzt.",["race:Dwarf"]="Als Zwerg seht Ihr, wie der Troggdurchbruch bei Gol'Bolar die Industrie Eurer Heimat bedroht. Tiefe Grabungen können Gefahren aus dem Erdreich heraufbeschwören."},sec={{t="Ein Senator vor Ort",b="Mehr Steingunst sitzt im Senat von Eisenschmiede und gehört der Forscherliga an. Er ist zum Steinbruch Gol'Bolar gekommen, um die Gegenmaßnahmen selbst zu leiten. Dort heuert er Reisende und Söldner an, um die Eindringlinge aus der Mine zu vertreiben."},{t="Das Unglück von Gol'Bolar",b="Tiefe Grabungen im Steinbruch Gol'Bolar brachen in verschlossene unterirdische Hohlräume durch. Troggs der Felskiefer strömten in die Gruben, zerstörten Bergbauausrüstung und vertrieben die Arbeiter. Steingunst will die Knochenknacker der Felskiefer beseitigen lassen, damit die Bergwacht den Steinbruch sichern und der Bergbau wieder aufgenommen werden kann."}},faq={{q="Wer ist Senator Mehr Steingunst?",a="Mehr Steingunst sitzt im Senat von Eisenschmiede und gehört der Forscherliga an. Er ist zum Steinbruch Gol'Bolar gekommen, um die Gegenmaßnahmen zur Bedrohung durch die Troggs zu leiten.",al={"steingunst","senator steingunst","wer ist der senator"}},{q="Warum ist der Steinbruch Gol'Bolar von Troggs überrannt?",a="Bergleute gruben unter dem Steinbruch Gol'Bolar zu tief und brachen in Höhlen durch, die von Troggs der Felskiefer bewohnt waren. Die Kreaturen strömten in die Gruben, zerstörten Ausrüstung und vertrieben die Arbeiter.",al={"warum sind troggs bei gol bolar","steinbruch troggs","was ist mit dem steinbruch passiert"}},{q="Was sind Knochenknacker der Felskiefer?",a="Knochenknacker der Felskiefer sind erbitterte Kämpfer unter den Troggs der Felskiefer. Sie setzen primitive Waffen und rohe Gewalt gegen zwergische Bergleute und Verteidiger ein.",al={"knochenknacker der felskiefer","knochenknacker","knochenknacker troggs"}},{q="Was ist nach der Vertreibung der Troggs geplant?",a="Sobald die Troggs vertrieben sind, will Senator Steingunst die Bergwacht aus Eisenschmiede herbeiholen. Sie soll den Steinbruch sichern, die beschädigte Ausrüstung wieder aufbauen und den Bergbau wieder aufnehmen.",al={"steingunst plan","wie geht es weiter gol bolar"}},{q="Warum ist die Forscherliga hier beteiligt?",a="Senator Steingunst gehört der Forscherliga an. Ihre Mitglieder untersuchen uralte Ausgrabungsstätten, unterirdische Ruinen und Troggvorstöße im gesamten Gebirge von Khaz Modan.",al={"forscherliga bergbau","warum ist die liga hier"}},{q="Wo liegt der Steinbruch Gol'Bolar?",a="Der Steinbruch Gol'Bolar liegt im Südosten von Dun Morogh, in den verschneiten Hügeln südlich der Straße zwischen Kharanos und South Gate Richtung Loch Modan.",al={"gol bolar lage","wo ist der steinbruch"}}},fx={["78fbc7a2"]={q="Warum möchte Senator Mehr Steingunst, dass die Troggs getötet werden?",a="Senator Steingunst betrachtet die Räumung von Steinbruch Gol'Bolar als seine bürgerliche Pflicht als Gelehrter der Explorers' League und als Mitglied des Senats von Eisenschmiede. Der plötzliche Trogg-Aufstand hat lebenswichtige Bergbau-Maschinen zerstört und die zwergischen Arbeiter vertrieben. Die Ausrottung der Schädlinge ist der wesentliche erste Schritt zur Rückgewinnung des Standorts, zur Reparatur der Infrastruktur und dazu, die Bergleute wieder unter Tage zu bringen.",al={"warum troggs töten","mehr steingunst beweggrund","warum gol'bolar räumen"}},b5671d80={q="Warum braucht Senator Steingunst einen Abenteurer anstelle der Mountaineers?",a="Die Militärstreitkräfte von Eisenschmiede sind in ganz Dun Morogh damit beschäftigt, Trogg-Invasionen und Frostmane-Trollüberfälle zu bewältigen. Senator Steingunst hat persönlich die Leitung der Situation im Steinbruch Gol'Bolar übernommen, aber die Mountaineers können nicht sicher einen Verteidigungsring aufbauen, bis die erste Frontlinie der gewalttätigen Rockjaw-Troggs von willigen Reisenden ausgedünnt wurde.",al={"warum braucht mich mehr","warum keine mountaineers","warum ein abenteurer"}}},fp="18,188,22.226.0,25.278.0,32.159.0,44.181.0,30.143.0,47.172.0,43.171.0,34.141.0"}
P.entries["quest:434"] = {n="Der Angriff!",s="Tyrion und Elling Trias locken einen Verräter zu einem Treffen im Garten von Burg Sturmwind. Ihr Plan bringt seinen Kontakt zu den Defias in ihre Reichweite.",h="Tyrion und Elling Trias locken einen Verräter zu einem Treffen im Garten von Burg Sturmwind.",kw={"defias","elling trias","lescovar","marzon","silent blade","burg sturmwind","der angriff","tyrion"},ang={["class:Rogue"]="Als Schurke seht Ihr, wie Geschäfte der Unterwelt bis in Sturmwinds Politik reichen können, selbst über einen Käseladen und einen ruhigen Garten.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie ein Verbündeter der Defias aus Burg Sturmwind beseitigt wird, während die Gefahr für die Führung des Königreichs fortbesteht.",["race:Human"]="Als Mensch aus Sturmwind erfahrt Ihr, dass Adlige im königlichen Palast heimlich die Banditenkrise in Westfall und im Rotkammgebirge schüren."},sec={{t="Ein Gast trifft ein",b="In Burg Sturmwind bringt ein als Priestess Tyriona getarnter Automat Nachricht in die Bibliothek: Lescovars Gast ist eingetroffen. Lord Gregor Lescovar schickt seine Wachen fort und begibt sich in den ruhigen Garten. Der Gast ist Marzon the Silent Blade, ein Attentäter mit Verbindungen zur Bruderschaft der Defias. Doch Tyrion, ein Spion, der mit dem Käsehändler Elling Trias zusammenarbeitet, hat Marzon mit falschen Informationen versorgt und ihn so in ihre Reichweite gelockt."},{t="Verrat in der Burg",b="In der Nähe verborgen hören Ermittler, wie Lescovar und Marzon ihren Verdacht bestätigen: Adlige aus Sturmwind unterstützen die Verschwörung der Defias gegen das Königreich. Als ihr verräterisches Gespräch endet, schnappt die Falle zu. Lescovar und the Silent Blade müssen im Hof rasch getötet werden, bevor die königlichen Wachen zurückkehren und einen toten Adligen auf dem Kopfsteinpflaster finden. Der Schlag beseitigt einen der tiefsten Stützpunkte der Defias in Sturmwinds Machtzentrum."},{t="Schattenspiele",b="Elling Trias erfüllt es mit Genugtuung, seine persönliche Rechnung mit Marzon zu begleichen, auch wenn es ihn wurmt, dass seine privaten Pläne zugleich Mathias Shaw und SI:7 helfen. Lescovars Tod beweist, dass die Korruption den Hof erreicht hat. Die Bruderschaft der Defias hatte Hilfe, und jemand aus dem Adel ließ sie wachsen."}},faq={{q="Wer ist Lord Gregor Lescovar?",a="Lord Gregor Lescovar ist ein angesehener Adliger, der in Burg Sturmwind lebt. Er arbeitete heimlich mit der Bruderschaft der Defias zusammen und nutzte seinen Rang und Einfluss, um das Reich vom Palast aus zu untergraben.",al={"lescovar","wer ist lescovar","gregor lescovar"}},{q="Wer ist Marzon the Silent Blade?",a="Marzon the Silent Blade ist ein Attentäter der Bruderschaft der Defias. Er verbindet die Gesetzlosen mit Lord Lescovar, überbringt Nachrichten und schmiedet Pläne, bis Tyrion ihn in die Falle im Garten lockt.",al={"marzon","silent blade","wer ist marzon"}},{q="Warum liegt Elling Trias dieser Einsatz am Herzen?",a="Elling Trias ist ein Käsehändler und ein einflussreicher Schurke mit Verbindungen zu Sturmwinds Unterwelt. Marzon hatte es auf Menschen abgesehen, die ihm nahestanden, also plante Trias den Untergang des Attentäters, auch wenn dies zugleich Mathias Shaw und SI:7 half.",al={"trias rolle","warum ist der käsetyp beteiligt","elling trias warum"}},{q="Wie gelingt es Tyrion, Lescovar nach draußen zu locken?",a="Tyrion schickt einen konstruierten Automaten, der als Priestess Tyriona getarnt ist, in die Bibliothek, um Lescovar mitzuteilen, dass sein Gast eingetroffen ist. Lescovar schickt seine Wachen fort und geht in den Garten. Tyrion hatte Marzon bereits zu einem erneuten Treffen aufgefordert und ihn mit falschen Informationen versorgt.",al={"spionagebot tarnung","tyriona","wie wird lescovar angelockt"}},{q="Warum verteidigen die Wachen Lescovar nicht sofort?",a="Lescovar schickt seine Wachen vor dem Treffen fort, um seine Geschäfte mit den Defias geheim zu halten. Das gibt den Ermittlern kurz Gelegenheit, Lescovar und Marzon aufzulauern, bevor die königlichen Wachen eingreifen.",al={"warum helfen die wachen lescovar nicht","wachen lescovar"}},{q="Was geschieht nach Lescovars Tod?",a="Nach dem Tod von Lescovar und Marzon schickt Elling Trias Euch in „The Head of the Beast“ in die Altstadt, um Meister Mathias Shaw von SI:7 zu berichten, dass die Bedrohung beseitigt ist.",al={"was folgt nach dem angriff","head of the beast"}}},fx={["2fdb68e4"]={q="Warum möchte Tyrion, dass Lord Lescovar und Marzon getötet werden?",a="Tyrion hat beträchtliche Mühe darauf verwendet, die Korruption in Burg Sturmwind aufzuspüren, und entdeckt, dass Lord Gregor Lescovar tief in die The Defias Brotherhood verstrickt ist. In Zusammenarbeit mit Elling Trias inszenierte Tyrion einen aufwendigen Fang, bei dem falsche Gerüchte und eine mechanische Verkleidung verwendet wurden, um Lescovar und seinen Kontaktmann der Defias, Marzon the Silent Blade, aus der Reserve zu locken. Um die Verschwörung zu zerschlagen, die die Stadt von innen heraus bedroht, müssen beide Verschwörer eliminiert werden, bevor ihr verräterischer Plan weiter voranschreiten kann.",al={"warum will tyrion das","tyrion beweggrund der angriff","warum lescovar töten tyrion"}},["70ac8295"]={q="Warum benötigt Tyrion Euch, um den Angriff auszuführen, anstatt die Wachen?",a="Lord Lescovar ist ein hochrangiger Adliger am königlichen Hof, und die Wachen von Sturmwind sind pflichtgemäß verpflichtet, ihm zu gehorchen und ihn zu schützen. Bis harter Verrat ausgesprochen wird, würden die Wachen jeden verhaften oder niederschlagen, der unbewiesene Anschuldigungen gegen einen Lord erhebt. Tyrion ist zudem damit beschäftigt, seine mechanische Verkleidung zu verwalten, um Lescovar herauszulocken, was Euch als den diskreten Agenten von außerhalb übrig lässt, der benötigt wird, um ihr Geständnis mitzuerleben und schnell zuzuschlagen, bevor die Wachen zurückkehren.",al={"warum nutzt tyrion keine wachen","warum ich der angriff","warum keine königlichen wachen für lescovar"}}},fp="11,132,15.424.0,19.434.1,12.284.2,28.197.2,31.194.1,48.224.1,48.254.2,50.200.1,37.164.1"}
P.entries["quest:435"] = {n="Eskorte für Erland",s="Im Silberwald versucht Todespirscher Erland, seinen Partner Rane Yorick zu erreichen. Wölfe halten ihn in einem Unterschlupf gefangen, und der Weg zu Rane führt durch ihr Jagdgebiet.",h="Im Silberwald versucht Todespirscher Erland, seinen Partner Rane Yorick zu erreichen.",kw={"todespirscher erland","bericht der deathstalkers","das ivar-feld","rane yorick","silberwald","wölfe"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr abgeschnittenen Todespirscher, entscheidende Aufklärungsergebnisse für die Truppen zu sammeln, die vom Grabmal aus vorrücken.",["race:Undead"]="Als Verlassener wisst Ihr, dass Todespirscher auf Zusammenarbeit und Heimlichkeit setzen. Dass Erland von Bestien festgesetzt wird, zeigt, welche Gefahr die Wildnis des Silberwalds für die frisch Erweckten birgt."},sec={{t="Von Wölfen umzingelt",b="Todespirscher Erland wird von hungrigen Wölfen in einem Unterschlupf festgehalten. Selbst ein erfahrener Späher der Verlassenen kann der Wildnis des Silberwalds unterliegen. Wölfe umkreisen die verfallene Zuflucht, angelockt von dem wenigen Fleisch, das an Erlands ausgemergeltem Körper verblieben ist. Allein kann er ihr Rudel nicht durchbrechen."},{t="Ein gefährlicher Weg",b="Todespirscher Erland muss seinen Partner Rane Yorick nahe dem Ivar-Feld erreichen. Wölfe durchstreifen das Gelände zwischen ihnen. Sobald Ihr Erland am Rudel vorbeigeführt habt, läuft er das letzte Stück zu Rane Yoricks Außenposten. Dort können die Späher ihre Erkenntnisse für Unterstadt zusammentragen."}},faq={{q="Warum jagen die Wölfe einen untoten Späher?",a="Die Wölfe sind womöglich so hungrig, dass sie selbst einen ausgedörrten Leichnam der Verlassenen als Nahrung betrachten. Die wilden Tiere des Silberwalds greifen alles an, was ihr Revier durchquert.",al={"warum wölfe untote angreifen","warum untote fressen","erland wölfe"}},{q="Wem erstattet Todespirscher Erland Bericht?",a="Todespirscher Erland erstattet seinem Späherpartner Deathstalker Rane Yorick Bericht. Rane hält bei einem nahe gelegenen Bauernhaus am Ivar-Feld Wache, wo die beiden für die Verlassenen Bedrohungen in den Wäldern beobachten.",al={"wer ist rane yorick","wem erstattet erland bericht","erlands partner"}},{q="Wohin führt die Eskorte?",a="Die Eskorte führt Erland von seiner Zuflucht zum Bauernhof nahe dem Ivar-Feld, wo er Rane Yorick Bericht erstattet. Nach dem Gespräch mit Rane geht Erland hinein und nach oben, um nach dem verletzten Quinn Yorick zu sehen.",al={"ziel der eskorte","wohin geht erland","erlands route"}},{q="Was geschieht nach Erlands Rettung?",a="Sobald Erland wieder sicher bei Rane Yorick ist, bereiten die beiden Späher ihre Erkenntnisse auf. Rane vertraut Euch an, ihren zusammengetragenen Bericht zum Grabmal zurückzubringen, wie in „The Deathstalkers' Report“ beschrieben.",al={"was kommt nach eskorte für erland","quest the deathstalkers' report","was folgt auf erlands eskorte"}},{q="Begegnet man während der Eskorte weiteren Bedrohungen?",a="Die größte Gefahr sind Wölfe, die das offene Gelände zwischen Erlands Zuflucht und dem Bauernhof nahe dem Ivar-Feld durchstreifen.",al={"gegner während der eskorte","was greift erland an","was ist auf dem weg"}},{q="Welche Rolle spielen die Todespirscher im Silberwald?",a="Die Todespirscher sind Schurken, Späher und Meuchelmörder der Verlassenen. Im Silberwald operieren sie vor den Hauptgarnisonen, um versprengte Geißeltruppen, Worgeneinfälle, wilde Bestien und Bewegungen der Allianz aufzuspüren.",al={"was sind deathstalkers","rolle der deathstalkers","geschichte der deathstalkers"}}},fx={ef1632bd={q="Warum möchte Todespirscher Erland eine Eskorte?",a="Erland ist in seinem Unterschlupf von einem Rudel gefräßiger Wölfe aus dem Silberwald gefangen, die direkt vor der Tür herumstreifen. Abgeschnitten von seinem Späherkollegen Rane Yorick kann er seine Späherbeobachtungen nicht abliefern oder seine Mission für die Verlassenen erfüllen, während er allein in die Enge getrieben ist. Um durch die umliegenden Bestien zu brechen und die Sicherheit zu erreichen, benötigt er verzweifelt Euren bewaffneten Schutz.",al={"warum braucht erland eine eskorte","erland eskorte warum","warum braucht todespirscher erland hilfe"}},fbccd737={q="Warum benötigt Erland Eure Hilfe anstelle anderer Todespirscher?",a="Todespirscher operieren als isolierte Aufklärungsagenten in feindlichem Grenzgebiet und nicht in großen Bataillonen. Erland und Rane Yorick sind weit entfernt von der Sicherheit der Verstärkungen aus der Unterstadt stationiert, was Erland ohne Wachen oder Kollegen in der Nähe, die ihn ablösen könnten, in der Klemme lässt. Ihr seid der einzige fähige Verbündete in Reichweite, um die Belagerung zu brechen.",al={"warum braucht erland mich","warum können wachen erland nicht helfen","warum fragt erland mich"}}},fp="16,167,18.266.0,22.282.0,43.147.0,40.199.0,27.201.0,37.209.1,54.111.0,46.201.0"}
P.entries["quest:436"] = {n="Eisenbands Ausgrabungsstätte",s="Jern Hornhelm hat Euch aus Thelsamar geschickt, um herauszufinden, warum Eisenbands Ausgrabungsstätte so wenig Fortschritte macht. Vorräte erreichen das Team von Ausgrabungsleiter Eisenband, und Jern vertraut auf dessen Fleiß, doch die Arbeit geht weiterhin langsam voran.",h="Jern Hornhelm hat Euch aus Thelsamar geschickt, um herauszufinden, warum Eisenbands Ausgrabungsstätte so...",kw={"ausgrabung","forscherliga","fellhew","hornhelm","eisenband","loch modan","thelsamar","troggs"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Loch Modan zu sichern, indem Ihr seine Handelsstraßen und Forschungsstätten von Troggstämmen aus der Tiefe freihaltet.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass jede Ausgrabung in Khaz Modan hilft, die Wahrheit über die Abstammung der Zwerge und ihr Titanenerbe aufzudecken. Eisenschmiede ist darauf angewiesen, dass Eisenbands Mannschaft in Sicherheit bleibt."},sec={{t="Stockende Arbeit im Hügelland",b="Jern Hornhelm wacht von Thelsamar aus darüber, wie Proviant und Werkzeuge durch Loch Modan zur Forscherliga gelangen. Die Lieferungen treffen regelmäßig ein, doch die Ausgrabung macht kaum Fortschritte. Jern vermutet, dass etwas die Arbeit stört. Er braucht Euch, um herauszufinden, was das Team aufhält."},{t="Die Troggplage",b="Bei der Ausgrabung in den östlichen Hügeln berichtet Forscher Magmar Fellhew, dass gewalttätige Troggs die Stätte überrannt haben. Sie bedrängen die Zwergenmannschaft und verstreuen ihre Funde. Solange die Eindringlinge nicht zurückgedrängt sind, kann die Liga die uralten Steine nicht untersuchen."}},faq={{q="Wer schickt Euch zu Eisenbands Ausgrabungsstätte?",a="Jern Hornhelm in Thelsamar bittet Euch, bei der Ausgrabung nach dem Rechten zu sehen. Die Lieferungen gehen weiter, doch die Arbeit kommt nur langsam voran, und er möchte, dass Ihr den Grund herausfindet.",al={"questgeber","wer vergibt die quest","jern hornhelms rolle"}},{q="Wo liegt die Ausgrabungsstätte?",a="Die Ausgrabung liegt im Hügelland östlich des Lochs. Umrundet von Thelsamar aus das südliche Ende des Gewässers und folgt dann dem Pfad nach Osten in die Hügel.",al={"lage der ausgrabungsstätte","wo ist eisenbands ausgrabungsstätte","weg zur ausgrabung"}},{q="Wer ist Magmar Fellhew?",a="Magmar Fellhew ist ein Forscher, der Ausgrabungsleiter Eisenband bei der Ausgrabung unterstützt. Er beaufsichtigt die tägliche Arbeit und die Logistik und erklärt Boten aus Thelsamar die Lage.",al={"fellhew","wer ist magmar fellhew","npc zur questabgabe"}},{q="Warum ist die Ausgrabung ins Stocken geraten?",a="Aggressive Troggs haben die Expedition zum Stillstand gebracht. Sie drangen in die Ruinen ein, störten die Ausgrabung und zwangen die Liga, sich zu verteidigen.",al={"warum so langsam","grund der verzögerung","was ist mit der ausgrabung passiert"}},{q="Wie geht es nach Abschluss dieser Quest weiter?",a="Magmar Fellhew fordert Euch auf, dem Team zu helfen, das Verlorene zurückzuholen. Die Arbeit geht mit Gathering Idols weiter, während Ihr Relikte zurückholt, die von den Troggs gestohlen wurden.",al={"nächste quest","folgequest","quest gathering idols"}},{q="Wonach sucht die Forscherliga hier?",a="Die Expedition von Ausgrabungsleiter Eisenband sucht unter Loch Modan nach uralten Relikten und Steinbauten. Die Entdeckungen könnten Licht auf die Geschichte der Zwerge und ihre längst vergessenen Ursprünge werfen.",al={"zweck der ausgrabung","grund der zwergenausgrabung","uralte ruinen loch modan"}}},fx={["47b557b9"]={q="Warum schickt Euch Jern Hornhelm zu Ironband's Excavation?",a="Jern hat stetig Versorgungslieferungen an die Ausgrabungsstätte von Ausgrabungsleiter Eisenband östlich des Lochs geschickt, aber der Fortschritt ist erschreckend ins Stocken geraten. Da er weiß, dass Eisenband ein stämmiger, verlässlicher Zwerg ist, der stolz auf seine Ergebnisse ist, befürchtet Jern, dass böse Kräfte die Ausgrabung stören. Er schickt Euch, um mit Magmar Fellhew zu untersuchen und herauszufinden, was sie aufhält.",al={"warum kümmert sich jern","jern hornhelm grund","warum zur ausgrabung schicken"}}},fp="21,210,27.264.0,21.253.1,39.142.0,37.149.0,22.170.0,36.139.0,44.151.0,47.166.0"}
P.entries["quest:437"] = {n="Das Todesfeld",s="Im nördlichen Silberwald stehen Truppen der Verlassenen am Todesfeld einer Bedrohung durch die Geißel gegenüber. Hochexekutor Hadrec entsendet Champions vom Grabmal gegen die Rotkammgnolle und die Banshee, die sie schützt.",h="Im nördlichen Silberwald stehen Truppen der Verlassenen am Todesfeld einer Bedrohung durch die Geißel...",kw={"banshee","todesfeld","hadrec","nightlash","rotkamm","geißel","das grabmal","silberwald"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, den Reiseweg zwischen Unterstadt und Lordaerons südlichen Gebieten zu schützen, indem Ihr die Herrschaft der Geißel über den nördlichen Silberwald brecht.",["race:Undead"]="Als Verlassener versetzt Ihr der Geißel mit Nightlashs Vernichtung einen Schlag und erinnert Euch an die geisterhaften Qualen, denen Sylvanas und ihre Banshees entkamen."},sec={{t="Eine Seuche auf den Feldern",b="Nördlich des Grabmals überrennen Rotkammgnolle ein verlassenes Gehöft. Einst standen gewöhnliche Bauernhöfe auf diesen Feldern. Nun verseuchen seuchengeplagte Aasfresser das Umland im Silberwald. Hochexekutor Hadrec sandte kleine Stoßtrupps aus, um sie zu vertreiben, doch jeder Angriff scheiterte an einem seltsamen magischen Widerstand."},{t="Im Griff der Banshee",b="Nightlash, eine Banshee der Geißel, befehligt die Rotkammgnolle. Wenn den Gnollen eine Niederlage droht, zerstreut sie die Plänkler der Verlassenen mit dunkler Zauberei. Hadrec entsendet Champions der Horde, um die Gnolle niederzustrecken und Nightlash hervorzulocken. Er verlangt ihre spektrale Essenz als Beweis ihrer Vernichtung."}},faq={{q="Wo liegt das Todesfeld?",a="Das Todesfeld liegt nördlich des Grabmals im Silberwald. Rotkammgnolle überrennen das verlassene, verfallende Gehöft.",al={"todesfeld lage","wo ist das todesfeld","wo liegt das todesfeld"}},{q="Wer ist Nightlash?",a="Nightlash ist eine Banshee der Geißel, die die Rotkammgnolle am Todesfeld befehligt und schützt. Ihre dunkle Magie hat Angriffstrupps der Verlassenen vertrieben.",al={"wer ist nightlash","nightlash geschichte","banshee nightlash"}},{q="Warum arbeiten Gnolle mit einer Banshee zusammen?",a="Die Rotkammgnolle des Silberwalds sind von der Seuche des Untodes verdorben. Die Geißel schickt diese tollwütigen Kreaturen als Fußsoldaten ihrer Vorhut gegen die Verlassenen, angeführt von Gestalten wie Nightlash.",al={"warum rotkammgnolle bei der geißel","verbindung zwischen gnollen und geißel","rotkammgnolle geschichte"}},{q="Wie lockt Ihr Nightlash hervor?",a="Nightlash bleibt verborgen, solange die Gnolle unter ihrem Schutz noch zahlreich sind. Tötet genügend Rotkammgnolle, und sie erscheint auf dem Feld, um ihr Gebiet zu verteidigen.",al={"wie nightlash hervorrufen","wo ist nightlash","nightlash nicht da"}},{q="Wer vergibt die Quest „Das Todesfeld“?",a="Hochexekutor Hadrec, der militärische Befehlshaber der Verlassenen am Grabmal, schickt Euch gegen die Bedrohung durch die Geißel aus, um die Region zu sichern.",al={"wer vergibt das todesfeld","todesfeld questgeber","hadrec quest"}},{q="Was geschieht nach Nightlashs Vernichtung?",a="Nightlashs Essenz beweist Hochexekutor Hadrec, dass die Geißel eine wichtige Präsenz im nördlichen Silberwald verloren hat. Anschließend schickt er Euch zur Verfallenen Fähre östlich des Grabmals.",al={"todesfeld folgequest","was kommt nach dem todesfeld"}}},fx={["1fb911a7"]={q="Warum möchte Hochexekutor Hadrec, dass Nightlash zerstört wird?",a="Die Rot Hide-Gnolle haben sich auf einem alten Bauernhof namens The Dead Fields verschanzt und bedrohen die Operationen der Verlassenen im gesamten Silberwald. Frühere Angriffe, die von Hochexekutor Hadrec ausgesandt wurden, scheiterten, weil die Banshee Nightlash eingriff und ihre dunkle Zauberei nutzte, um das Blatt zu wenden und seine Streitkräfte in die Flucht zu schlagen. Bis Nightlash eliminiert ist, kann Hadrec das Lager der Rot Hide-Gnolle nicht aufbrechen oder die Region für die Dunkle Fürstin sichern.",al={"warum nightlash töten","hadrec beweggrund the dead fields","warum the dead fields angreifen"}},["4cfc66ca"]={q="Wofür wird die Essenz von Nightlash verwendet?",a="Nach ihrer Niederlage löst sich Nightlash in verweilenden Staub auf. Ihr sammelt diesen Rückstand nicht als magische Zutat, sondern als unwiderlegbaren physischen Beweis für Hochexekutor Hadrec, dass die Banshee wirklich zerstört wurde und die Rot Hide-Gnolle nicht weiter verstärken kann.",al={"zweck der essenz von nightlash","warum nightlash essenz sammeln","nachtseeles essenz"}}},fp="15,199,24.307.0,19.288.0,34.123.0,17.151.0,38.202.0,30.151.0,36.142.0,42.186.1"}
P.entries["quest:438"] = {n="Die verfallene Fähre",s="An der Verfallenen Fähre sammelt sich die Geißel am Ufer des Lordameresees. Hochexekutor Hadrec schickt Champions der Verlassenen nach Osten, um herauszufinden, was sie dorthin zieht.",h="An der Verfallenen Fähre sammelt sich die Geißel am Ufer des Lordameresees.",kw={"mit leichen beladenes boot","die verfallene fähre","insel fenris","hochexekutor hadrec","der lordameresee","moderfell","das grabmal","silberwald"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Versorgungslinien durch den Silberwald zu schützen, indem Ihr das Gebiet um den Lordameresee gegen Geißeleinfälle aus dem Norden sichert.",["race:Undead"]="Als Mitglied der Verlassenen steht Ihr einer direkten Bedrohung für die Grenzen von Tirisfal und für Unterstadt gegenüber, sobald die Geißel im Silberwald Fuß fasst."},sec={{t="Blicke über den See",b="Nachdem die Präsenz der Geißel in den Dead Fields zurückgedrängt wurde, richtet Hochexekutor Hadrec seine Aufmerksamkeit nach Osten. Die verfallene Fähre liegt zwischen den östlichen Wasserwegen des Silberwalds, wo einst das Festland von Lordaeron mit den Inselanwesen des Lordameresees verbunden war. Nun sammeln sich Untote an ihren verrotteten Stegen. Hadrec schickt Späher aus, um herauszufinden, was die Diener des Lichkönigs dorthin zieht."},{t="Eine grausige Fracht",b="An der Fähre patrouillieren Moderfelle an den sumpfigen Ufern. Ein vollgesogenes Ruderboot liegt neben dem Anleger, seine Fracht besteht aus sorgfältig eingewickelten und konservierten Leichen. Durch den Nebel über dem Lordameresee zeigen die Anleger auf der Insel Fenris, wohin die Leichen gebracht werden: zur Inselfeste."}},faq={{q="Wer schickt Euch zur Verfallenen Fähre?",a="Hochexekutor Hadrec, der militärische Befehlshaber der Verlassenen am Grabmal im Silberwald, schickt Euch nach Osten, nachdem Ihr geholfen habt, die Dead Fields zu säubern.",al={"wer vergibt die quest die verfallene fähre","hadrec quest fähre","questgeber verfallene fähre"}},{q="Wo liegt die Verfallene Fähre?",a="Die verfallene Fähre liegt östlich des Grabmals am Westufer des Lordameresees, wo Bäche aus dem Landesinneren ins offene Wasser münden.",al={"verfallene fähre standort","wo ist die fähre im silberwald","wie die verfallene fähre finden"}},{q="Welche Kreaturen besetzen die Verfallene Fähre?",a="Untote der Geißel besetzen das Gebiet, vor allem Moderfellgnolle und wiederbelebte Skelette, die am Ufer und auf den Stegen patrouillieren.",al={"gegner an der verfallenen fähre","welche gegner sind an der fähre","verfallene fähre monster"}},{q="Was entdeckt Ihr an der Fähre?",a="An der Fähre findet Ihr ein mit Leichen beladenes Boot, das zur Hälfte aus dem Wasser gezogen wurde. Eingewickelte Leichen warten darauf, über den See zur Insel Fenris verschifft zu werden.",al={"was ist an der fähre","fähre questabgabe objekt","was ist im boot"}},{q="Warum ist die Fähre für die Geißel von Bedeutung?",a="Die Fähre bietet der Geißel eine Verbindung über den Lordameresee, über die frische Leichen direkt zu ihrer Festung auf der Insel Fenris gelangen.",al={"warum ist die geißel an der verfallenen fähre","fähre geißel zweck"}},{q="Welche Quest folgt auf Die verfallene Fähre?",a="Die Untersuchung des mit Leichen beladenen Bootes führt zu Rot Hide Clues, wo Ihr die Aktivitäten der Gnolle und ihre Verbindung zur Insel Fenris untersucht.",al={"nächste quest nach die verfallene fähre","verfallene fähre folgequest"}}},fx={["2d3f81d3"]={q="Warum möchte Hochexekutor Hadrec, dass Ihr Die verfallene Fähre untersucht?",a="Die Verlassenen halten den Silberwald nur unsicher unter Kontrolle, und das plötzliche Auftauchen eines neuen Geißel-Bienenstocks so nahe am Grabmal bedroht ihre Sicherheit. Hochexekutor Hadrec kann eine organisierte feindliche Konzentration direkt östlich seiner Basis nicht ignorieren. Er muss aufdecken, welcher Zweck die Rot Hide-Gnolle und Untoten an das Ufer von Der Lordameresee bringt, bevor sie einen Angriff gegen die Verlassenen starten können.",al={"hadrec beweggrund the decrepit ferry","warum zur the decrepit ferry schicken","warum the decrepit ferry untersuchen"}},e09d24e5={q="Gegen wen werdet Ihr an Die verfallene Fähre geschickt?",a="Die verfallene Fähre wurde von der Geißel überrannt, insbesondere von Rudeln von Rot Hide-Gnollen und wandelnden Toten. Sie wandern nicht nur umher; sie patrouillieren aktiv die ruinierten Docks und sichern den Ort, um eingewickelte Leichen auf Boote zu laden, die über Der Lordameresee zur Insel Fenris bestimmt sind.",al={"feinde the decrepit ferry","wer kontrolliert the decrepit ferry","ziele the decrepit ferry"}}},fp="18,157,20.379.0,12.253.1,36.145.0,36.121.0,41.112.0,34.145.0,42.125.0,38.131.0"}
P.entries["quest:439"] = {n="Auf den Spuren der Moderfelle",s="„Auf den Spuren der Moderfelle“ beginnt am Lordameresee mit einem gravierten Ring an der Hand einer kürzlich verstorbenen Frau. Als Ihr Hochexekutor Hadrec im Grabmal den grausigen Fund meldet, erkennt er, dass Gnolle der Moderfelle Leichen aus Tirisfals Massengräbern zur Insel Fenris bringen.",h="„Auf den Spuren der Moderfelle“ beginnt am Lordameresee mit einem gravierten Ring an der Hand einer kürzlich...",kw={"corpse laden boat","deliah","deliahs ring","insel fenris","hadrec","auf den spuren der moderfelle","gnolle der moderfelle","das grabmal"},ang={["faction:Horde"]="Hadrec koordiniert vom Grabmal aus die Einsätze der Horde, um den Silberwald gegen wachsende Monsterlager zu sichern. Das Rudel der Moderfelle hält die Insel Fenris besetzt.",["race:Undead"]="Die Schändung von Tirisfals Massengräbern trifft die Verlassenen besonders schwer. Ihre gefallenen Angehörigen und noch nicht auferstandenen Brüder werden als Rohmaterial für die alchemistischen Schrecken der Gnolle fortgeschafft."},sec={{t="Eine grausige Fracht",b="Späher der Verlassenen finden am Ufer des Lordameresees eine mit Leichen beladene Fähre. Unter den Toten liegt die unbandagierte, von der Seuche gezeichnete Hand einer kürzlich getöteten Frau. Ein schlichter Ring daran trägt die Worte „Für Deliah“. Die Fähre deutet darauf hin, dass die Toten gezielt abtransportiert werden, statt wahllos fressenden Aasfressern zum Opfer zu fallen."},{t="Plünderer der Gräber",b="Hochexekutor Hadrec setzt die Hinweise zusammen, als Deliahs Ring ihn im Grabmal erreicht. Er schließt daraus, dass ein so kürzlich begrabener Leichnam aus den Massengräbern jenseits der Grenze in Tirisfal stammt. Gnolle der Moderfelle im Silberwald graben systematisch menschliche Leichen aus und verschiffen sie über das Wasser zur Insel Fenris. Niemand weiß, warum."}},faq={{q="Was ist das Corpse Laden Boat?",a="Es ist eine alte Fähre, die am Ufer des Lordameresees im Silberwald vertäut liegt. Gnolle der Moderfelle bringen damit ausgegrabene menschliche Leichen über das Wasser zu ihrer Festung auf der Insel Fenris.",al={"leichenboot","verfallene fähre boot","boot auf dem see"}},{q="Wer war Deliah?",a="Deliah war ein menschliches Seuchenopfer und wurde kürzlich in den Massengräbern von Tirisfal bestattet. Gnolle der Moderfelle stahlen ihren Leichnam und ließen ihren gravierten Ring als Hinweis zurück.",al={"deliah hintergrund","wer ist deliah","für deliah ring"}},{q="Warum sammeln Gnolle Leichen?",a="Die Moderfelle sind untote Gnolle, die der Geißel dienen. Sie plündern Tirisfals Massengräber und verschiffen die Leichen zur Festung der Geißel auf der Insel Fenris, statt sie zu fressen.",al={"warum wollen gnolle leichen","moderfelle leichen","insel fenris leichen"}},{q="Wer ist Hochexekutor Hadrec?",a="Hochexekutor Hadrec befehligt die Streitkräfte der Verlassenen, die im Grabmal im Silberwald stationiert sind. Er leitet die Verteidigung gegen Bedrohungen der Region, darunter wilde Gnolle der Moderfelle, Zauberer aus Dalaran und die Worgen.",al={"hadrec","grabmal kommandant","exekutor hadrec"}},{q="Woher stammen die Leichen auf dem Boot?",a="Hadrec schließt daraus, dass die Leichen aus den Massengräbern im nahen Tirisfal ausgegraben wurden. Dort wurden Opfer der Geißel und der Seuche hastig bestattet.",al={"herkunft der bootsleichen","tirisfal gräber boot"}},{q="Was geschieht, nachdem Hadrec dieser Hinweis gemeldet wurde?",a="Hadrec entsendet Agenten, um der Bedrohung durch die Moderfelle auf der Insel Fenris entgegenzutreten und Proben der fauligen Wundflüssigkeit zu beschaffen, die die Gnolle veredeln. Seine Maßnahmen führen außerdem dazu, dass Deliahs Identität untersucht und ihr Ring zurückgebracht wird.",al={"nach auf den spuren der moderfelle","deliahs ring fortsetzung"}}},fp="14,287,16.303.0,21.342.1,30.188.0,15.163.0,37.172.1,28.211.0,44.153.0,49.224.1"}
P.entries["quest:440"] = {n="Der gravierte Ring",s="Hochexekutor Hadrec schickt Euch mit einem Ring, der Deliahs Namen trägt, über die Grenze nach Brill. Magistrat Sevren durchsucht die Stadtaufzeichnungen, um herauszufinden, wer sie war und woher der Ring stammt.",h="Hochexekutor Hadrec schickt Euch mit einem Ring, der Deliahs Namen trägt, über die Grenze nach Brill.",kw={"brill","deliah","deliahs ring","gnolle","hochexekutor hadrec","magistrat sevren","massengrab","rot hide","silberwald","der gravierte ring"},ang={["faction:Horde"]="Als Mitglied der Horde habt Ihr Grund, die Rot Hide-Gnolle daran zu hindern, Gräber im von der Horde kontrollierten Tirisfal zu schänden, zur Sicherung des Gebiets und als Vergeltung.",["race:Undead"]="Als Verlassener könnt Ihr in Deliahs Ring eine stille Verbindung zwischen einer lebendigen Vergangenheit und Lordaerons düsterer, kalter Gegenwart sehen."},sec={{t="Ein Andenken im Silberwald",b="Späher, die im nördlichen Silberwald nach den Rot Hide-Gnollen suchten, fanden Deliahs Ring. Magistrat Sevren führt Tirisfals Bürgerakten und Begräbnisregister, doch Hadrec bezweifelt, dass sich unter den Verlassenen noch jemand um solche Andenken schert."},{t="Aus der Erde geraubt",b="Magistrat Sevren bestätigt, dass Deliah in Brill lebte und im Massengrab der Stadt beigesetzt wurde. Ihr Ring bei den Rot Hides deutet auf einen grausigen Raub hin: Die von der Seuche entstellten Gnolle plündern Massengräber und bringen Leichen für Experimente der Geißel nach Süden. Sevren will die Gnolle auslöschen lassen."}},faq={{q="Wer war Deliah?",a="Deliah ist der Name, der in den geborgenen Ring eingraviert ist. Hadrec schickt Euch zu den Aufzeichnungen von Magistrat Sevren in Brill, um herauszufinden, wer sie war.",al={"wer ist deliah","deliahs geschichte","deliahs ring"}},{q="Warum wurde Deliahs Ring im Silberwald gefunden?",a="Der Ring tauchte bei der Untersuchung der Rot Hide-Gnolle auf. Sevrens Aufzeichnungen könnten enthüllen, wessen Andenken er war und wie er in den Silberwald gelangte.",al={"warum haben gnolle den ring","rot hide ring","wie kam der ring in den silberwald"}},{q="Warum bezweifelt Hochexekutor Hadrec, dass der Ring von Bedeutung ist?",a="Hadrec sagt, dass der Untod oft die Bindungen aus dem sterblichen Leben auslöscht. Er nimmt an, dass Deliahs Geliebter tot ist oder, falls er als Verlassener auferstanden ist, sterblichen Schwüren und Erinnerungen gleichgültig gegenübersteht.",al={"hadrecs dialog","warum ist hadrec zynisch","gefühle der verlassenen"}},{q="Welche Rolle spielt Magistrat Sevren bei dieser Quest?",a="Magistrat Sevren führt Brills Stadtaufzeichnungen und Totenregister. Er kann Deliahs Identität und ihre Grabstätte bestätigen.",al={"sevren brill","rolle von magistrat sevren","wer ist sevren"}},{q="Sind die Rot Hide-Gnolle mit der Geißel verbündet?",a="Ja. Die Seuche der Geißel hat die Rot Hide-Gnolle im Silberwald infiziert. Dunkle Einflüsse lenken sie, während sie Leichen für nekromantische Zwecke sammeln.",al={"gehören die rot hides zur geißel","gnolle geißel","silberwald gnolle"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Magistrat Sevren durchsucht Brills Aufzeichnungen nach Deliahs Identität. Was er herausfindet, liefert die nächste Spur für die Untersuchung.",al={"was kommt nach dem gravierten ring","nächste quest","deliah fortsetzung"}}},fp="17,187,24.228.0,20.284.1,15.129.0,49.148.1,53.158.0,52.127.1,48.150.1,40.119.1"}
P.entries["quest:441"] = {n="Raleigh und Unterstadt",s="In Brill und Unterstadt zieht ein Ring Raleigh in eine alte Tragödie hinein. Magistrat Sevren schickt Euch, um Deliahs Ring ihrem verwitweten Mann zurückzubringen, nachdem er bei ihrer gestohlenen Leiche auf dem Weg zur Insel Fenris gefunden wurde.",h="In Brill und Unterstadt zieht ein Ring Raleigh in eine alte Tragödie hinein.",kw={"a husband's revenge","brill","deliah","deliahs ring","raleigh","sevren","handwerksviertel","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde tragt Ihr Zeugnisse des alten Lordaerons durch die Tore von Unterstadt. Sie zeigen die düstere Gestalt des Lebens unter Euren verbündeten Verlassenen.",["race:Undead"]="Für Euch als Untoten spiegelt Raleighs kalte Reaktion das gemeinsame Leid der Verlassenen wider. Ihre Bindungen aus dem Leben sind bitterem Zorn gewichen."},sec={{t="Ein tragisches Erbstück",b="In Brill hat Magistrat Sevren Hinweise zu einer gestohlenen Leiche und einem gravierten Ring zusammengetragen. Der Ring gehörte Deliah, und Sevren hofft, seine Herkunft zu erfahren und ihn ihrer Familie zurückzugeben. Er schickt Euch nach Unterstadt, um Raleigh zu finden, Deliahs hinterbliebenen Ehemann."},{t="Kalte Herzen, bittere Rache",b="Im Handwerksviertel von Unterstadt erkennt Raleigh Andrean den Ring seiner früheren Frau sofort. Wie viele Verlassene kann er durch den Untod weder um Deliahs Tod noch um die Schändung ihrer sterblichen Überreste trauern. Doch der Durst nach Vergeltung brennt noch immer in ihm. Raleigh plant Rache an jenen, die ihre letzte Ruhe gestört haben."}},faq={{q="Wer vergibt diese Quest?",a="Magistrat Sevren schickt Euch von Brill in Tirisfal aus los, nachdem Ihr ihm Deliahs Ring zurückgebracht habt.",al={"wo gibt es raleigh und unterstadt","questgeber","magistrat sevren quest"}},{q="Wo befindet sich Raleigh Andrean?",a="Raleigh Andrean befindet sich im Handwerksviertel von Unterstadt, zwischen den dortigen Händlern und Handwerkern.",al={"raleigh standort","wo ist raleigh","handwerksviertel raleigh"}},{q="Wessen Ring wird überbracht?",a="Der Ring gehörte Deliah, einer Frau aus Brill, die vor dem Fall Lordaerons Raleigh Andreans Ehefrau war.",al={"deliahs ring","wer war deliah","wessen ring ist das"}},{q="Warum trauert Raleigh nicht um seine tote Frau?",a="Als einer der Verlassenen sagt Raleigh, dass Trauer und Liebe in seinem untoten Herzen erkaltet sind. Geblieben ist die Rache.",al={"raleighs reaktion","ist es raleigh wichtig","warum ist raleigh kalt"}},{q="Was geschieht nach dieser Quest?",a="Wenn Ihr den Ring übergebt, schickt Raleigh Euch los, um die Schändung seiner Frau zu rächen.",al={"nächste quest","folgequest zu raleigh","was kommt danach"}},{q="Wie wurde Deliahs Ring ursprünglich gefunden?",a="Deliahs Ring wurde ihr zwischen den eingewickelten Leichen auf einem Boot an der Verfallenen Fähre im Silberwald von der Hand genommen.",al={"herkunft des rings","woher kam der ring"}}},fx={a3ed960c={q="Warum möchte Magistrat Sevren, dass Deliahs Ring zu Raleigh gebracht wird?",a="Als The Engraved Ring geborgen wurde, erinnerte sich Magistrat Sevren daran, dass einst eine Frau namens Deliah mit ihrem Ehemann Raleigh in Brill lebte. Raleigh lebt nun unter den Verlassenen in der Unterstadt. Sevren schickt Euch, um das Andenken zu überbringen, damit Raleigh bestätigen kann, ob das Erbstück tatsächlich seiner früheren Frau gehörte, was ihm Gewissheit über das Schicksal seiner verlorenen Familie verschafft.",al={"warum ring zu raleigh schicken","motiv von magistrat sevren","warum deliahs ring überbringen"}}},fp="25,202,17.277.0,29.326.1,22.96.0,33.87.0,30.101.0,40.124.0,30.80.1,38.117.0"}
P.entries["quest:442"] = {n="Sturm auf die Insel Fenris",s="Hochexekutor Hadrec entsendet Agenten der Verlassenen zur Insel Fenris. Sie sollen Burg Fenris stürmen und den Kopf von Thule Rabenklaue holen, dem Nekromanten, der die Inselfestung im Lordameresee befehligt.",h="Hochexekutor Hadrec entsendet Agenten der Verlassenen zur Insel Fenris.",kw={"insel fenris","hadrec","der lordameresee","geißel","das grabmal","silberwald","thule ravenclaw"},ang={["class:Mage"]="Als Magier teilt Ihr vielleicht das Interesse von Bethor Eismacht und Apotheker Renferrel an den magischen Nachwirkungen von Thules Tod und der gewaltsamen Auflösung seiner nekrotischen Zaubergewebe.",["faction:Horde"]="Als Mitglied der Horde verlasst Ihr Euch darauf, dass die Verlassenen den Silberwald und Tirisfal gegen rivalisierende Mächte und die umherstreifende Geißel sichern.",["race:Undead"]="Als Verlassener habt Ihr persönliche Gründe, Vergeltung an Thule Rabenklaue zu suchen. Die Zerschlagung von Außenposten der Geißel beweist, dass Euer Volk sich vom Willen des Lichkönigs befreit hat."},sec={{t="Säuberung des Lordameresees",b="Die Verlassenen halten die westlichen Straßen und haben am Grabmal ihre Präsenz gezeigt. Doch die Geißel bleibt in Burg Fenris verschanzt, auf einer Insel im Lordameresee östlich des Silberwalds. Ihre Streitkräfte bedrohen den Wald und die südlichen Wasserwege, die zur Unterstadt führen. Hochexekutor Hadrec sieht in Thule Ravenclaws Experimenten eine Gefahr für die Herrschaft der Verlassenen über den Silberwald. Von der Burg aus befehligt Thule die Geißel nahe dem Ufer der Verlassenen."},{t="Thule Ravenclaws Fall",b="Rotfellgnolle und schlurfende Untote bewachen den Weg durch Burg Fenris zu Thule Rabenklaue. Der Nekromant verflucht seine Angreifer und entzieht ihnen Lebenskraft, um seine eigenen Schläge zu verstärken. Wenn er fällt, dient sein abgetrennter Kopf als Beweis für seinen Tod. Magische Schockwellen erreichen das Grabmal, wo Apotheker Renferrel sie wahrnimmt."}},faq={{q="Warum will Hochexekutor Hadrec Thule Rabenklaue tot sehen?",a="Thule Rabenklaue führt die Geißel auf der Insel Fenris an. Seine Streitkräfte bedrohen den Stützpunkt der Verlassenen am Grabmal und die Wasserwege über den Lordameresee. Hadrec fordert Thules Kopf als Beweis dafür, dass die regionale Befehlsgewalt der Geißel gebrochen ist.",al={"warum thule töten","hadrecs beweggründe","bedrohung durch die insel fenris"}},{q="Wo befindet sich Thule Rabenklaue?",a="Thule Rabenklaue haust tief in der verfallenen Burg auf der Insel Fenris, mitten im Lordameresee östlich des Silberwalds. Er hält in der unteren Gemeinschaftshalle der Burg Hof, bewacht von untoten Gefolgsleuten und entstellten Dienern.",al={"thule ravenclaw aufenthaltsort","wo ist thule","thule finden"}},{q="Was geschieht, wenn Thule Rabenklaue stirbt?",a="Thules Tod schickt eine gewaltige Welle dunkler nekromantischer Energie durch die Region. Am Grabmal spürt Apotheker Renferrel die sich auflösende Magie, und Hochexekutor Hadrec würdigt den Schlag als strategischen Triumph für die Verlassenen.",al={"reaktion auf thules tod","was geschieht nach thules tod"}},{q="Wer kontrolliert die Insel Fenris vor diesem Angriff?",a="Die Geißel hält die Insel Fenris besetzt. Thule Rabenklaue nutzt ihre Burg als Aufmarschgebiet und befehligt wiedererweckte Untote und durch die Seuche entstellte Rotfellgnolle, um die Gewässer des Lordameresees zu terrorisieren.",al={"wer hält die insel fenris","insel fenris fraktion","gehört die insel fenris der geißel"}},{q="Warum war Bethors Trank für diese Mission wichtig?",a="Thule wirkt Hex of the Ravenclaw, einen Fluch, der seine Gegner schwächt und seine eigene Macht verstärkt. Bethor Eismacht lieferte Gegenzauber, die Apotheker Renferrel bei früheren Einsätzen zu einem Trank braute, um den nekrotischen Fluch zu neutralisieren.",al={"hex of the ravenclaw aufheben","bethors trank thule","thules fluch entgegenwirken"}},{q="Welche strategische Bedeutung hat die Insel Fenris für die Verlassenen?",a="Die Insel Fenris liegt im Lordameresee und grenzt an den Silberwald und das Vorgebirge des Hügellands. Die Sicherung oder Neutralisierung der Insel beseitigt einen feindlichen Außenposten, der den Silberwald angreifen kann, und vertreibt eine starke Präsenz der Geißel von Lordaerons Grenzen.",al={"warum die insel fenris wichtig ist","bedeutung der insel fenris"}}},fx={["3fc2276d"]={q="Wofür ist Thules Kopf?",a="Hochexekutor Hadrec verlangt Thules Kopf als unwiderlegbaren Beweis dafür, dass der Nekromant endlich zerstört wurde. Insel Fenris ist eine befestigte Hochburg der Geißel, und Hadrec wird sich nicht dazu verpflichten, den Sieg im Silberwald zu beanspruchen, bis er physische Beweise dafür sieht, dass der Griff ihres Anführers auf die Region gebrochen ist.",al={"verwendung von thules kopf","warum thules kopf nehmen","beweis von thules tod"}},["8bb87601"]={q="Wer ist Thule Rabenklaue?",a="Thule Rabenklaue ist ein mächtiger Nekromant der Geißel, der die untoten Streitkräfte befehligt, die auf der Insel Fenris verschanzt sind. Von der Festung in der Mitte von Der Lordameresee aus leitet er die Operationen der Geißel im gesamten Silberwald, was eine unmittelbare Bedrohung für die Präsenz der Verlassenen am Grabmal darstellt.",al={"wer ist thule","thule ravenclaw lore","warum ist thule auf der insel fenris"}}},fp="22,194,22.464.0,27.317.1,56.239.0,33.229.0,39.235.1,45.188.0,51.252.0,66.237.0"}
P.entries["quest:443"] = {n="Moderfellsekret",s="Im Silberwald sucht Hochexekutor Hadrec nach Moderfellsekret, bevor die Verlassenen die Insel Fenris angreifen. Er will die Flüssigkeit untersuchen lassen, um die Gnolle zu verstehen, die die Insel heimsuchen.",h="Im Silberwald sucht Hochexekutor Hadrec nach Moderfellsekret, bevor die Verlassenen die Insel Fenris...",kw={"apotheker renferrel","insel fenris","hochexekutor hadrec","der lordameresee","moderfellgnolle","moderfellsekret","das grabmal","silberwald"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Insel Fenris am östlichen Rand des Silberwalds liegt. Bleibt sie unbeobachtet, stellt sie eine taktische Gefahr für die Truppen dar, die das Umland sichern.",["race:Undead"]="Als Verlassene wisst Ihr, dass die Erforschung biologischer Schrecken und künstlich geschaffener Krankheiten zum Überleben gehört. Die Königliche Apothekervereinigung untersucht die Flüssigkeit der Moderfelle, um herauszufinden, ob die Infektion die Ansprüche der Verlassenen in Lordaeron bedroht."},sec={{t="Unnatürliche Biologie",b="Die Moderfellgnolle auf der Insel Fenris verwesen und kämpfen mit einer Raserei, die gewöhnlichen wilden Humanoiden fremd ist. Sie halten strategisch wichtige Stellungen jenseits des Lordameresees. Hochexekutor Hadrec glaubt, dass die seltsame Flüssigkeit in ihren Adern ihre unnatürliche Widerstandskraft erklären könnte. Er braucht Proben, bevor die Verlassenen Soldaten in einen verlustreichen Angriff schicken."},{t="Apothekeranalyse",b="Die Königliche Apothekervereinigung arbeitet vom Grabmal aus, wo Apotheker Renferrel biologische und chemische Anomalien untersucht. Bringt ihm Proben der fauligen Flüssigkeit. Die Verlassenen hoffen herauszufinden, woher die Gnolle stammen, wer sie erschafft und welche Schwächen sie im Kampf haben."}},faq={{q="Was ist Moderfellsekret?",a="Moderfellsekret ist eine faulige Flüssigkeit, die durch die Körper der Moderfellgnolle auf der Insel Fenris fließt. Es erhält ihren untotenähnlichen, verwesenden Zustand und verleiht ihnen ungewöhnliche Widerstandskraft.",al={"was ist das sekret","moderfellflüssigkeit","gnollsekret"}},{q="Warum will Hochexekutor Hadrec Proben des Sekrets?",a="Hochexekutor Hadrec will die Proben untersuchen lassen, bevor die Verlassenen die Insel Fenris angreifen. Apotheker Renferrel kann womöglich herausfinden, wer die Moderfelle erschaffen hat, und eine ausnutzbare Schwäche entdecken.",al={"warum sekret sammeln","hadrecs ziel","warum hadrec sekret will"}},{q="Wo befinden sich die Moderfellgnolle?",a="Die Moderfellgnolle leben auf der Insel Fenris, von der Verfallenen Fähre im Silberwald aus östlich jenseits des Lordameresees. Moderfellschläger, Seuchenwirker und andere Arten überrennen ihre Ufer, Lager und Ruinen.",al={"wo sind moderfelle zu finden","fundort der moderfellgnolle","fenrisgnolle"}},{q="Wer ist Apotheker Renferrel?",a="Apotheker Renferrel ist ein Forscher der Königlichen Apothekervereinigung, der vor der Gruft im Grabmal stationiert ist. Er untersucht für die Verlassenen örtliche Seuchen, Plagen und seltsame biologische Gefahren im gesamten Silberwald.",al={"wer ist renferrel","rolle von apotheker renferrel"}},{q="Was geschieht, nachdem Renferrel das Sekret erhalten hat?",a="Nachdem er die Proben erhalten hat, untersucht Renferrel die chemische Zusammensetzung der Flüssigkeit, um den Ursprung der Moderfelle zu ergründen. Seine Arbeit führt zu Rot Hide Origins.",al={"nächste quest nach moderfellsekret","folgequest von moderfellsekret"}},{q="Warum interessieren sich die Verlassenen für Gnolle?",a="Die Moderfellgnolle halten die Insel Fenris, einen wichtigen Stützpunkt im Lordameresee an der Grenze zum Gebiet der Verlassenen. Ihr verwesender Zustand und ihre seuchenartigen Fähigkeiten deuten auf fremde Eingriffe hin und könnten die Sicherheit von Unterstadt bedrohen.",al={"warum verlassenen gegen gnolle kämpfen","bedrohung durch gnolle im silberwald"}}},fx={c47d3478={q="Wer sind die Rot Hide-Gnolle auf der Insel Fenris?",a="Die Rot Hide-Gnolle sind ein aggressiver Stamm von Gnollen, die die Insel Fenris auf Der Lordameresee bewohnen. Im Gegensatz zu gewöhnlichen Gnollen sind sie sichtbar korrumpiert und verrottend und tragen unnatürliche Seuchen und Schmutz. Die Verlassenen betrachten sie als gefährliche Plage direkt an der Grenze des Silberwalds, was Hochexekutor Hadrec dazu veranlasst, eine Offensive gegen ihre Hochburg vorzubereiten.",al={"wer sind die rot hides","insel fenris gnolle","was sind rot hide-gnolle"}}},fp="14,177,17.317.0,19.284.0,23.178.0,56.176.0,38.209.0,28.220.0,48.144.0,38.228.0"}
P.entries["quest:444"] = {n="Die Ursprünge der Moderfelle",s="Im Silberwald tragen die Moderfelle eine Magie in sich, die Renferrel durch Alchemie allein nicht erklären kann. Er schickt eine Probe zu Bethor Eismacht in Unterstadt, wo arkanes Wissen ihren Ursprung enthüllen könnte.",h="Im Silberwald tragen die Moderfelle eine Magie in sich, die Renferrel durch Alchemie allein nicht erklären...",kw={"apotheker renferrel","bethor eismacht","magieviertel","moderfellsekret","die ursprünge der moderfelle","sekretprobe","silberwald","unterstadt"},ang={["class:Mage"]="Als Magier wisst Ihr, dass arkane Wahrsagerei und gelehrte Zauberkunst dunkle Geheimnisse aufdecken können, die über gewöhnliche Alchemie hinausgehen.",["class:Warlock"]="Als Hexenmeister erkennt Ihr Teufelsmagie und Hexenmeistermagie, die sich im Moderfellsekret mit Nekromantie vermischen. Solche verbotene Zauberkunst wirkt in der Wildnis des Silberwalds.",["race:Undead"]="Als Untoter seht Ihr, wie die Königliche Apothekervereinigung und die arkanen Meister von Unterstadt zusammenarbeiten und Wissenschaft mit Zauberei verbinden, um Lordaeron zu schützen."},sec={{t="Ein Gebräu aus Tod und Teufelsmagie",b="Apotheker Renferrel hat Flüssigkeit von den Moderfellen des Silberwalds in ihre Grundbestandteile zerlegt. Seine ersten Untersuchungen zeigen, dass das Sekret sowohl Nekromantie als auch Hexenmeistermagie enthält. Alchemie kann die dahinterliegende Zauberei nicht erklären, also bereitet er eine Probe für einen Experten in Unterstadt vor."},{t="Audienz beim Magier",b="Bethor Eismacht, ein Magier der Verlassenen im Magieviertel von Unterstadt, untersucht die Probe. Er gehört nicht der Königlichen Apothekervereinigung an, kennt sich aber mit arkanen und dunklen Künsten aus. Die Phiole enthält alte, mächtige Verzauberungen, die er seit Jahren nicht mehr gesehen hat. Bethor beginnt einen Wahrsagezauber, um herauszufinden, wer die Magie gewoben hat."}},faq={{q="Wer schickt den Spieler auf diese Quest?",a="Apotheker Renferrel von der Königlichen Apothekervereinigung schickt Euch vom Grabmal im Silberwald aus los. Er hat Sekret untersucht, das von Moderfellen aus der Umgebung stammt.",al={"wer startet die ursprünge der moderfelle","wo beginnt die ursprünge der moderfelle"}},{q="Warum schickt Renferrel die Probe zu Bethor Eismacht?",a="Renferrel findet nekromantische Magie und Hexenmeistermagie im Moderfellsekret. Da Alchemie die Verzauberungen nicht erklären kann, schickt er die Probe zur arkanen Untersuchung zu Bethor Eismacht in Unterstadt.",al={"warum bethor eismacht","warum dem magier die probe geben"}},{q="Wo befindet sich Bethor Eismacht?",a="Bethor Eismacht lebt im Magieviertel von Unterstadt, inmitten arkaner Forscher und Lehrer.",al={"bethors standort","wo ist bethor eismacht"}},{q="Was sind die Moderfelle?",a="Moderfelle sind untote Gnolle, die im Silberwald umherstreifen. Ihr verwesender Zustand ist das Ergebnis finsterer magischer Experimente.",al={"was sind moderfelle","moderfellgnolle silberwald"}},{q="Was geschieht, wenn Ihr Bethor die Probe überbringt?",a="Bethor erkennt alte, mächtige Magie in der Flüssigkeit, Zauber, denen er seit sehr langer Zeit nicht mehr begegnet ist. Er beginnt einen Wahrsagezauber, um ihren Ursprung aufzuspüren.",al={"was macht bethor","bethor eismachts reaktion"}},{q="Welche Quest folgt als Nächstes?",a="Nach Bethors Wahrsagezauber schickt er Euch in „Thule Rabenklaue“ los, um den abtrünnigen Magier zu untersuchen, der die Gnolle verdirbt.",al={"nächste quest nach die ursprünge der moderfelle","folgequest zu die ursprünge der moderfelle"}}},fp="16,193,29.275.0,22.290.1,35.150.0,54.189.0,33.99.0,23.116.0,51.144.0,22.114.1"}
P.entries["quest:4449"] = {n="Eingesperrt!",s="In der Sengenden Schlucht ruft jemand aus einem verschlossenen Plumpsklo um Hilfe. Die Stimme darin bittet Euch, acht Dunkeleisengeologen eine Lektion zu erteilen und fünfzehn Stück Seidenstoff zu bringen, nennt aber keinen Grund.",h="In der Sengenden Schlucht ruft jemand aus einem verschlossenen Plumpsklo um Hilfe.",kw={"eingesperrt","dunkeleisengeologen","sengende schlucht","seidenstoff","hölzernes plumpsklo"},sec={{t="Eingesperrt",b="Die Person floh vor den Dunkeleisenzwergen und versteckte sich im Plumpsklo. Sie glaubt, die Geologen hätten sie hineinhuschen sehen und die Tür mit ihrer Magie verschlossen, bevor sie entkommen konnte."},{t="Zwei Gefallen",b="Die eingesperrte Person bittet Euch, acht Dunkeleisengeologen eine Lektion zu erteilen und fünfzehn Stück Seidenstoff zu bringen. Als Ihr nach dem Grund fragt, gerät sie ins Stammeln und sagt dann, es sei für nichts Bestimmtes."}},faq={{q="Wer ist im Plumpsklo eingesperrt?",a="Eine namenlose Person, die vor den Dunkeleisenzwergen floh, ist im Plumpsklo eingesperrt, nachdem sie sich dort versteckt hat.",al={"wer ist im plumpsklo","wer ist im plumpsklo eingesperrt","kerl im plumpsklo"}},{q="Warum will die Person Seidenstoff?",a="Die Person bittet um fünfzehn Stück Seidenstoff, gerät dann bei der Begründung ins Stammeln und sagt, es sei für nichts Bestimmtes.",al={"warum seidenstoff","wofür ist die seide","warum will der kerl im plumpsklo seide"}},{q="Wer hat die Tür des Plumpsklos verschlossen?",a="Die Person glaubt, die Dunkeleisengeologen hätten gesehen, wie sie sich versteckte, und die Tür des Plumpsklos mit ihrer Magie verschlossen.",al={"wer hat die tür verschlossen","wer hat den kerl eingesperrt","welche dunkeleisenzwerge"}},{q="Wie viele Geologen müssen getötet werden?",a="Die Person bittet Euch, Euch um acht Dunkeleisengeologen zu kümmern.",al={"wie viele geologen","anzahl der geologen"}}},fp="7,209,9.179.0,10.203.0,35.96.0,38.123.0,29.108.0,34.62.0"}
P.entries["quest:445"] = {n="Lieferung in den Silberwald",s="Ihr bringt Apotheker Johaans Erkenntnisse aus Brill zu Renferrel im Grabmal im Silberwald. Die Königliche Apothekervereinigung braucht sie für ihre Arbeit an der New Plague.",h="Ihr bringt Apotheker Johaans Erkenntnisse aus Brill zu Renferrel im Grabmal im Silberwald.",kw={"brill","lieferung in den silberwald","johaan","new plague","renferrel","königliche apothekervereinigung","das grabmal","silberwald"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die nördlichen Gebiete zu sichern, indem Ihr Nachrichten entlang der Straße durch den Silberwald überbringt, selbst wenn die alchemistische Forschung der Verlassenen bei Euren Verbündeten Befremden auslöst.",["race:Undead"]="Als Untoter überbringt Ihr diese Forschungsergebnisse im Dienste von Fürstin Sylvanas und für das Überleben der Verlassenen. Damit helft Ihr, das zentrale Vorhaben der Königlichen Apothekervereinigung voranzutreiben."},sec={{t="Ein gemeinsames Ziel",b="Fürstin Sylvanas Windläufer befehligt die Königliche Apothekervereinigung, die nach einer New Plague sucht, die die Lebenden und die Geißel auslöschen kann. Ihre Laboratorien sind über das Gebiet der Verlassenen verstreut, daher teilen die Forscher ihre Erkenntnisse, um die Arbeit voranzubringen. In Brill hat Apotheker Johaan Versuchsergebnisse für andere Forscher vor Ort gesammelt. Ihr bringt sie nach Süden zu Renferrel im Grabmal."},{t="Außenposten im Süden",b="Der Silberwald ist das nächste Grenzgebiet für die Ausbreitung und Forschung der Verlassenen. Apotheker Renferrel arbeitet vom Grabmal aus und beaufsichtigt biochemische Tests inmitten der Bedrohung durch Mondzorn-Worgen, abtrünnige Menschen und die verbliebene Geißel. Er erhält Johaans Notizen aus Tirisfal und bezieht ihre alchemistischen Erkenntnisse in seine eigenen Experimente ein, um den Plan der Vereinigung voranzutreiben."}},faq={{q="Warum schickt Apotheker Johaan diese Dokumente?",a="Die Königliche Apothekervereinigung erwartet von ihren Mitgliedern, Entdeckungen zu teilen und die Erschaffung der New Plague zu beschleunigen. Johaan schickt seine neuesten Erkenntnisse aus Tirisfal, damit andere Forscher darauf aufbauen können.",al={"warum erkenntnisse überbringen","johaans notizen","warum forschung schicken"}},{q="Wo liegt das Grabmal?",a="Das Grabmal ist der wichtigste Außenposten der Verlassenen im Silberwald. Es liegt südlich der Grenze zu Tirisfal und südwestlich von Unterstadt, an der Hauptstraße durch den Wald.",al={"wo ist das grabmal","renferrel finden","lage des grabmals"}},{q="Wer ist Apotheker Renferrel?",a="Apotheker Renferrel ist ein bedeutendes Mitglied der Königlichen Apothekervereinigung und im Grabmal stationiert. Er leitet Feldversuche und untersucht exotische Zutaten aus dem gesamten Silberwald, dann erstattet er den Anführern der Vereinigung in Unterstadt Bericht.",al={"renferrels rolle","wer ist renferrel","renferrel silberwald"}},{q="Was ist die New Plague, die Johaan erwähnt?",a="Die New Plague ist eine alchemistische Seuche, die die Königliche Apothekervereinigung auf Befehl von Fürstin Sylvanas Windläufer entwickelt. Sie soll lebende Feinde und die untoten Diener des Lich King ausrotten.",al={"new plague","sylvanas seuche","welche seuche"}},{q="Was ist die Necropolis, die Renferrel erwähnt?",a="Renferrel sagt, er müsse Proben an „die Necropolis“ schicken, doch aus diesem Austausch geht nicht hervor, welche Nekropole er meint.",al={"necropolis renferrel","renferrels proben","proben zur necropolis"}},{q="Warum einen Abenteurer statt offizieller Boten einsetzen?",a="Die Kuriere der Verlassenen müssen gefährliche Straßen mit wilden Worgen, angriffslustigen Wildtieren und feindseligen menschlichen Überlebenden passieren. Ein kräftiger Abenteurer kann die empfindlichen alchemistischen Notizen sicher zum Grabmal bringen und bei der Arbeit in der Region helfen.",al={"warum ich als kurier","warum abenteurer als bote"}}},fp="29,175,26.386.0,20.369.0,49.200.0,31.179.0,28.250.0,43.206.0,42.127.0,53.231.0"}
P.entries["quest:4450"] = {n="Geschäftsbuch aus Tanaris",s="In der Sengenden Schlucht wartet nun ein kleiner Auftrag aus Tanaris auf Euch. Krinkle Goodsteel aus Gadgetzan möchte einige Dinge hier und andernorts sammeln und dann zu sich bringen lassen.",h="In der Sengenden Schlucht wartet nun ein kleiner Auftrag aus Tanaris auf Euch.",kw={"beezils wrack","düstermarschen","gadgetzan","glassweb spiders","jarquia","krinkle goodsteel","geschäftsbuch aus tanaris","sengende schlucht","sümpfe des elends","hölzernes plumpsklo"},sec={{t="Ein Auftrag aus Tanaris",b="Der Person im hölzernen Plumpsklo wurde geholfen, und sie erinnert sich an einen kleinen Auftrag aus Tanaris. Krinkle Goodsteel aus Gadgetzan möchte einige Dinge sammeln lassen, manche in der Sengenden Schlucht und andere weiter entfernt. Das Geschäftsbuch wird unter der Tür durchgeschoben. Bringt es zusammen mit allem, was darin aufgeführt ist, zu Goodsteel in Tanaris."},{t="Was im Geschäftsbuch steht",b="Goodsteels Geschäftsbuch verlangt zwanzig feste Kristallbeinschäfte von den Glassweb Spiders der Sengenden Schlucht. Es führt auch ein überfälliges Paket beim abgestürzten Zeppelin bei Beezils Wrack in den Düstermarschen auf. Der dritte Gegenstand ist Goodsteels ausbalancierte Flammenberge. Jarquia, ein Murloc an der Ostküste der Sümpfe des Elends, hat sie."}},faq={{q="Wo beginnt das?",a="Es beginnt beim hölzernen Plumpsklo in der Sengenden Schlucht, nachdem Ihr der darin eingesperrten Person geholfen habt.",al={"questbeginn","wer vergibt geschäftsbuch aus tanaris","plumpsklo standort"}},{q="Wer ist Krinkle Goodsteel?",a="Krinkle Goodsteel ist in Gadgetzan in Tanaris. Er sagt, er sei schrecklich beschäftigt, da viele Kunden seine Dienste in Anspruch nehmen möchten.",al={"wer ist krinkle goodsteel","krinkle goodsteel gadgetzan","wo ist krinkle goodsteel"}},{q="Was steht im Geschäftsbuch?",a="Das Geschäftsbuch führt zwanzig feste Kristallbeinschäfte, ein überfälliges Paket und Goodsteels ausbalancierte Flammenberge auf.",al={"welche gegenstände werden benötigt","gegenstandsliste im geschäftsbuch","goodsteels geschäftsbuch gegenstände"}},{q="Wo ist das überfällige Paket?",a="Das überfällige Paket liegt beim abgestürzten Zeppelin bei Beezils Wrack in den Düstermarschen.",al={"überfälliges paket fundort","wo ist das überfällige paket","beezils wrack paket"}},{q="Wer hat Goodsteels ausbalancierte Flammenberge?",a="Jarquia, ein Murloc an der Ostküste der Sümpfe des Elends, hat Goodsteels ausbalancierte Flammenberge.",al={"ausbalancierte flammenberge fundort","wer lässt die flammenberge fallen","jarquia sümpfe des elends"}},{q="Was kam davor?",a="Caught! kam davor, beim selben hölzernen Plumpsklo.",al={"vorherige quest","vorausgesetzte quest","questreihe vor geschäftsbuch aus tanaris"}}},fp="19,163,18.300.0,21.327.0,22.91.0,25.117.0,22.106.0,29.88.0,40.103.0,22.54.0"}
P.entries["quest:4451"] = {n="Der Schlüssel zur Freiheit",s="In der Sengenden Schlucht habt Ihr einen kleinen Messingschlüssel, dessen Bestimmung unbekannt ist. Sein Kopf trägt die Inschrift Dunkeleisen Outhouse und warnt davor, ihn nachzumachen.",h="In der Sengenden Schlucht habt Ihr einen kleinen Messingschlüssel, dessen Bestimmung unbekannt ist.",kw={"dunkeleisen outhouse","schlüssel für grimesilt-nebengebäude","locheed","sengende schlucht","der schlüssel zur freiheit","hölzernes nebengebäude"},sec={{t="Ein gekennzeichneter Schlüssel",b="Der kleine Messingschlüssel trägt die Inschrift Dunkeleisen Outhouse und eine Warnung, ihn nicht nachzumachen. Wohin er führt, bleibt unbekannt. Sucht in der Sengenden Schlucht nach einem Ort, an dem er passt."},{t="Ein unterbrochener Besuch",b="Aus dem hölzernen Nebengebäude ertönt ein Husten. Jemand fragt verärgert über die Störung, wer da sei. Locheed ist hocherfreut, dass Ihr den Schlüssel gefunden habt. Die Dunkeleisen haben ihn versteckt, nachdem sie Locheed darin eingesperrt hatten."}},faq={{q="Was steht auf dem Schlüssel für Grimesilt-Nebengebäude?",a="Der Kopf des Schlüssels trägt die Inschrift Dunkeleisen Outhouse und warnt davor, ihn nachzumachen.",al={"schlüsselinschrift","was steht auf dem schlüssel","inschrift auf dem nebengebäudeschlüssel"}},{q="Wohin führt dieser Schlüssel?",a="Ihr könnt noch nicht sagen, wohin der Schlüssel führt. Seine Inschrift weist auf ein Nebengebäude der Dunkeleisen hin, irgendwo in der Sengenden Schlucht.",al={"wo schlüssel benutzen","standort des nebengebäudes","der schlüssel zur freiheit abgeben"}}},fp="18,135,12.167.0,20.190.1,46.69.0,25.107.0"}
P.entries["quest:446"] = {n="Thule Rabenklaue",s="In Unterstadt bringt ein Kurier Bethor Eismacht seltsames Moderfellsekret. Bethor erkennt darin das Werk von Thule Rabenklaue, seinem verräterischen ehemaligen Kollegen, und bereitet Gegenbeschwörungen vor, damit die Verlassenen den Gnollen widerstehen können.",h="In Unterstadt bringt ein Kurier Bethor Eismacht seltsames Moderfellsekret.",kw={"apotheker renferrel","bethor eismacht","insel fenris","moderfell","geißel","das grabmal","silberwald","thule rabenklaue"},ang={["class:Mage"]="Der Konflikt zwischen Bethor und Thule offenbart die Spaltung unter Lordaerons einstigen Magiern. Einige verfielen der Nekromantie, während andere ihre arkane Disziplin auch im Untod bewahrten.",["faction:Horde"]="Die Überreste der Geißel aus Lordaeron zu vertreiben, hilft dabei, den einzigen Stützpunkt der Horde in den Östlichen Königreichen zu sichern.",["race:Undead"]="Für die Verlassenen ist es wichtig, Thule Rabenklaue aufzuhalten, denn seine Herrschaft über die Insel Fenris bedroht das Grabmal und die westlichen Zugänge zu Capital City."},sec={{t="Ein Kollege wird zum Verräter",b="Bethor Eismacht untersucht die Probe des Kuriers im Magieviertel von Unterstadt und entdeckt eine arkane Signatur. Thule Rabenklaue hat das Destillat hergestellt. Vor dem Dritten Krieg war Thule ein begabter junger Magier und Bethors Kollege. Als der Lichkönig an die Macht kam, verriet Thule seine Gefährten und schwor der Geißel die Treue. Als Lordaeron fiel, gab er seine Menschlichkeit auf."},{t="Der Herr der Insel Fenris",b="Bethor erfährt, dass Thule den Krieg überlebt hat und nun Burg Fenris auf der Insel Fenris im Lordameresee beherrscht. Thule befehligt die Moderfellgnolle, erfüllt sie mit finsterer Magie und schickt sie gegen die Grenzen der Verlassenen. Dank seiner genauen Kenntnis von Thules Magie verfasst Bethor eine Rolle, um den Flüchen und Schutzzaubern des Magiers entgegenzuwirken."},{t="Alchemistische Gegenmaßnahmen",b="Ein Kurier bringt Bethors Rolle zum Grabmal, zu Apotheker Renferrel von der Königlichen Apothekervereinigung. Renferrel studiert die mächtigen Beschwörungen des Magiers aus Unterstadt und verbindet dann hohe Zauberkunst mit den alchemistischen Gebräuen der Vereinigung. Die Mischung soll gezielt Rabenklaues Flüche brechen und macht den Weg für einen Angriff auf Burg Fenris frei."}},faq={{q="Wer ist Thule Rabenklaue?",a="Bevor die Geißel ihn für sich gewann, war Thule Rabenklaue ein vielversprechender menschlicher Magier, der in Dalaran ausgebildet wurde und mit Bethor Eismacht studierte. Er verriet seine Gefährten, um der Geißel zu dienen, als der Lichkönig Verderbnis in Lordaeron verbreitete, und übernahm später von der Insel Fenris aus den Befehl über die Moderfellgnolle.",al={"thule hintergrund","wer ist thule","thule rabenklaue vorgeschichte"}},{q="Warum kennt Bethor Eismacht Thules Magie?",a="Bethor und Thule waren vor dem Fall Lordaerons Kollegen und wirkten gemeinsam als Zauberwirker. Durch ihre gemeinsamen Studien war Bethor mit Thules bevorzugten Zaubern, seiner magischen Theorie und seinen Flüchen bestens vertraut.",al={"bethor und thule","woher kennt bethor thule","bethor eismacht verbindung"}},{q="Wozu dient Bethors Rolle?",a="Bethors Rolle enthält Gegenbeschwörungen, die Thules Zauber auflösen sollen. Apotheker Renferrel nutzt sie, um einen Trank zu brauen, der die Streiter der Verlassenen vor Rabenklaues Flüchen schützt.",al={"bethors rolle","zweck der rolle","was bewirkt die rolle"}},{q="Warum sind die Moderfellgnolle eine Bedrohung im Silberwald?",a="Thule Rabenklaue nutzt die Nekromantie der Geißel, um die Moderfellgnolle zu lenken und zu stärken. Von der Insel Fenris aus führen sie im ganzen Silberwald organisierte Angriffe auf Siedlungen und Patrouillen der Verlassenen durch.",al={"moderfellgnolle","warum gegen gnolle kämpfen","insel fenris gnolle"}},{q="Wo spielt diese Quest?",a="Die Reise beginnt bei Bethor Eismacht im Magieviertel von Unterstadt und endet bei Apotheker Renferrel am Grabmal im Silberwald.",al={"thule rabenklaue abgeben","wo thule rabenklaue abgeben","abgabeort der rolle"}},{q="Was geschieht, nachdem Renferrel die Rolle erhalten hat?",a="Nachdem Renferrel den Gegentrank entwickelt hat, schickt er Euch zu Hochexekutor Hadrec, um vor einem Großangriff auf die Insel Fenris Bericht zu erstatten, der Thule Rabenklaue ausschalten und die Insel zurückerobern soll.",al={"was geschieht als nächstes","nach der quest thule rabenklaue","angriff auf die insel fenris"}}},fx={bea76ce7={q="Warum möchte Bethor Eismacht, dass die Rolle an Renferrel geliefert wird?",a="Bei der Untersuchung des Ichors war Bethor schockiert festzustellen, dass sein ehemaliger Kollege Thule Rabenklaue nicht nur den Krieg überlebt hatte, sondern auch sein Volk verriet, um der Geißel zu dienen und die Fäulnisnarbengnolle gegen die Verlassenen anzuführen. Bethor ist mit Thules magischem Repertoire bestens vertraut. Indem er diese verzauberte Rolle an Apotheker Renferrel schickt, liefert er die arkanen Beschwörungsformeln, die benötigt werden, um einen Trank zu brauen, der in der Lage ist, Thules abscheuliche Flüche zu neutralisieren.",al={"warum bethors rolle liefern","bethor eismacht beweggrund","warum rolle an renferrel senden"}}},fp="15,228,26.363.0,25.325.1,26.342.1,23.286.0,44.192.0,33.184.0,51.195.0,33.148.0,49.184.1"}
P.entries["quest:447"] = {n="Rezept für den Tod",s="Im Silberwald werden für „Rezept für den Tod“ Reagenzien für die New Plague der Verlassenen gesammelt. Vom Grabmal aus schickt Apotheker Renferrel Bärenherzen und Spinnenblut zu Apothekermeister Faranell in Unterstadt.",h="Im Silberwald werden für „Rezept für den Tod“ Reagenzien für die New Plague der Verlassenen gesammelt.",kw={"faranell","new plague","renferrel","königliche apothekervereinigung","silberwald","das huschdunkel","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie die Apotheker der Verlassenen mit virulenten Mixturen nach dem Sieg streben, eine düstere Art der Kriegsführung unter den neuesten Verbündeten der Horde.",["race:Undead"]="Als Untoter könnt Ihr der Apothekervereinigung helfen, ihre Seuche zu entwickeln, um das Reich der Verlassenen gegen die Geißel und die Menschheit zu verteidigen."},sec={{t="Eine Waffe gegen zwei Feinde",b="Im Silberwald sieht Apotheker Renferrel zwei Feinde auf Sylvanas' Volk vorrücken. Arthas' Legionen bedrängen es, während die Überreste der Menschheit weiterhin seine Feinde sind. Konventionelle Kriegsführung bietet den Verlassenen wenig Hoffnung. Sie streben nach einer New Plague, die lebende Menschen und die untote Geißel gleichermaßen verrotten lassen kann.\n\nRenferrels Feldforschung hat eine virulente Grundlage für die Seuche ergeben. Spinnengift aus dem Huschdunkel bildet zusammen mit Giftstoffen in den Herzen einheimischer Bären diese Grundlage."},{t="Sendung an das Apothekarium",b="Bärenherzen und Spinnenblut aus der Wildnis des Silberwalds gelangen unter Lordaerons Ruinen zum Apothekarium in Unterstadt. Apothekermeister Faranell überwacht das Vorhaben der Königlichen Apothekervereinigung.\n\nFaranell nimmt Renferrels Proben entgegen, um ihre kontaminierenden Eigenschaften zu prüfen und Formeln zu verfeinern. Diese Arbeit könnte die Vorherrschaft der Verlassenen auf dem gesamten Kontinent sichern."}},faq={{q="Wozu werden Bärenherzen und Spinnenblut gesammelt?",a="Renferrel fand heraus, dass Spinnengift aus dem Huschdunkel mit Giftstoffen in Grizzlybärenherzen eine tödliche Reaktion hervorruft. Zusammen liefern sie der Königlichen Apothekervereinigung Material, um die New Plague zu erproben und zu entwickeln.",al={"warum bärenherzen","warum spinnenblut","wozu dient dieses rezept"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell leitet die Königliche Apothekervereinigung im Apothekariumsviertel von Unterstadt. Er überwacht die Erforschung der New Plague im Auftrag von Fürstin Sylvanas Windläufer.",al={"faranells geschichte","wer ist faranell","apothekermeister"}},{q="Warum wollen die Verlassenen eine New Plague erschaffen?",a="Die Verlassenen stehen der Geißel und dem Hass der lebenden Menschen gegenüber und haben zu wenige Soldaten für einen langen konventionellen Krieg. Ihre New Plague soll sowohl lebende Feinde als auch die untote Geißel töten und so das Überleben und die Eigenständigkeit der Verlassenen sichern.",al={"warum new plague entwickeln","beweggründe der verlassenen für die seuche","geschichte der new plague"}},{q="Wo befindet sich Apotheker Renferrel?",a="Apotheker Renferrel betreibt seine Forschungen vom Grabmal im Silberwald aus.",al={"renferrels standort","wo ist renferrel"}},{q="Wo liegt das Huschdunkel?",a="Das Huschdunkel liegt nordwestlich des Grabmals im Silberwald. Riesige Spinnen haben diese Wildnis befallen, und Renferrel braucht ihr Blut.",al={"lage des huschdunkels","wo gibt es spinnen im silberwald"}},{q="Wird diese Quest fortgesetzt?",a="Ja. Apothekermeister Faranell verwendet die Reagenzien für weitere Experimente. Anschließend wird im Apothekarium weiter daran gearbeitet, die tödliche Mischung zu verfeinern und zu erproben.",al={"rezept für den tod folgequest","gibt es einen zweiten teil"}}},fx={dca2eeef={q="Warum möchte Apotheker Renferrel, dass Ihr diese Reagenzien sammelt?",a="Apotheker Renferrel widmet sich dem großen Ziel der Royal Apothecary Society, eine A New Plague zu erschaffen. Angesichts der überwältigenden Armeen der Geißel und verbliebener menschlicher Enklaven glaubt Renferrel, dass konventionelle Kriegsführung das Überleben der Verlassenen nicht sichern kann. Er versucht, Apothekermeister Faranell mit lebensfähigen biologischen Zutaten zu versorgen, um eine Seuche zu brauen, die sowohl untote als auch lebende Feinde gleichermaßen auslöschen kann.",al={"warum braucht renferrel das","renferrel beweggrund","warum apotheker renferrel helfen"}},["922f4213"]={q="Gegen wen werdet Ihr geschickt, um die Zutaten zu sammeln?",a="Ihr werdet in die Wildnis des Silberwalds geschickt, um Grizzlybären und die giftigen Spinnentiere zu jagen, die das Huschdunkel befallen. Diese ungezähmten Bestien durchstreifen die uralten Kiefernwälder, gedeihen inmitten des kriechenden verpesteten Verfalls, und ihr Gift und ihre widerstandsfähigen Organe liefern die wirksamen natürlichen Toxine, die die Royal Apothecary Society benötigt.",al={"ziele a recipe for death","was töte ich für a recipe for death","gegen wen kämpfe ich für a recipe for death"}}},fp="18,205,25.469.0,28.366.0,63.207.0,34.178.0,48.225.0,38.83.0,29.144.0,33.152.0"}
P.entries["quest:448"] = {n="Meldung bei Hadrec",s="Im Silberwald schickt Renferrel Euch zu Hadrec, während die Bedrohung durch die Geißel wächst. Renferrel und Bethor Eismacht haben die Präsenz der Geißel im Lordameresee untersucht, und Hochexekutor Hadrec leitet nun die Vorbereitungen gegen die Insel Fenris.",h="Im Silberwald schickt Renferrel Euch zu Hadrec, während die Bedrohung durch die Geißel wächst.",kw={"fenris","hadrec","eismacht","ravenclaw","renferrel","das grabmal","silberwald","thule"},ang={["faction:Horde"]="Das Grabmal koordiniert die westliche Verteidigung der Horde in Lordaeron. Es sichert die Zugänge zu den Ruinen von Capital City gegen Vorposten der Geißel und menschliche Überlebende.",["race:Undead"]="Als Verlassene steht Ihr in Thule Rabenklaue dem versklavenden Willen des Lich Kings gegenüber, der Eurer Heimat bedrohlich nahe kommt. Ihn zu vernichten ist für das Überleben Eures Volkes entscheidend."},sec={{t="Eskalation im Silberwald",b="Apotheker Renferrel und Bethor Eismacht haben die Gefahr durch Thule Rabenklaue, einen abtrünnigen Nekromanten, untersucht. Doch Forschung allein kann die wachsende Hochburg der Geißel auf der Insel Fenris nicht brechen. Ravenclaw bindet dort die rastlosen Toten an sich, und Renferrel erkennt, dass Alchemie und Magie nicht ausreichen werden. Das Militär der Verlassenen muss seinen Stahl und seine Disziplin zum Einsatz bringen, also schickt Renferrel Euch zu dessen Kommandanten."},{t="Das Arsenal des Hochexekutors",b="Hochexekutor Hadrec leitet aus den Krypten des Grabmals die strategischen Operationen im Silberwald für die Dunkle Fürstin. Bethors Warnungen vor Ravenclaw erreichen ihn, und Hadrec weiß, dass ein am Westufer des Lordameresees verschanzter Nekromant die Flanke von Unterstadt bedroht. Er öffnet die Waffenkammer der örtlichen Garnison, um die Vorhut auszurüsten, bevor er sie gegen die Inselfestung schickt."}},faq={{q="Wer ist Hochexekutor Hadrec?",a="Hochexekutor Hadrec befehligt die im Grabmal stationierten Truppen der Verlassenen. Er überwacht die Verteidigung und die Angriffsoperationen im gesamten Silberwald und untersteht der Führung von Unterstadt.",al={"hadrec","wer ist hadrec","kommandant des grabmals"}},{q="Warum schickt Apotheker Renferrel Euch zu Hadrec?",a="Apotheker Renferrel schickt Euch zu Hadrec, weil er und Bethor Eismacht entdeckt haben, dass Thule Rabenklaue eine gefährliche Streitmacht der Geißel auf der Insel Fenris versammelt hat. Ein verschanzter Nekromant erfordert militärische Stärke und angemessene Ausrüstung, also wendet sich Renferrel an den Kommandanten der Garnison.",al={"warum meldung bei hadrec","verbindung zwischen renferrel und hadrec"}},{q="Wo liegt das Grabmal?",a="Das Grabmal ist eine befestigte Siedlung der Verlassenen mit einer Grabanlage im mittleren Silberwald. Es ist der wichtigste Stützpunkt und das Aufmarschgebiet der Horde für Operationen in der Region.",al={"wo liegt das grabmal","lage des grabmals"}},{q="Wer ist Thule Rabenklaue?",a="Thule Rabenklaue ist ein mächtiger Nekromant der Geißel, der Burg Fenris auf der Insel Fenris im Lordameresee eingenommen hat. Er erweckt die Toten, um vor der Ostküste des Silberwalds einen aktiven Brückenkopf aufzubauen.",al={"thule ravenclaw","thules geschichte"}},{q="Was geschieht nach der Meldung bei Hadrec?",a="Hadrec gibt Euch Vorräte aus der Waffenkammer des Grabmals und befiehlt einen sofortigen Angriff auf die Insel Fenris. Der Angriff soll Thule Rabenklaue ausschalten und die Herrschaft der Geißel über den Lordameresee brechen.",al={"was kommt nach hadrec","nächste quest nach hadrec"}},{q="Wer ist Bethor, den Hadrec erwähnt?",a="Bethor Eismacht ist ein Magier der Verlassenen, der im Magieviertel von Unterstadt lebt. Seine magischen Weissagungen halfen dabei, das Wesen und die Gefahr von Thule Ravenclaws Ritualen aufzudecken.",al={"wer ist bethor","bethor eismacht"}}},fp="16,232,24.400.0,27.369.0,28.190.0,49.277.0,31.171.0,23.186.0,39.191.0,34.169.0"}
P.entries["quest:449"] = {n="Der Bericht der Todespirscher",s="Nahe der nördlichen Wildnis haben die Todespirscher unerwartet Truppen der Geißel entdeckt. Die Verlassenen hatten dort nicht mit ihnen gerechnet. Ihr bringt den Bericht der verwundeten Späher zu Hochexekutor Hadrec im Grabmal und übermittelt, dass im Silberwald eine größere Bedrohung lauert, als die Führung glaubte.",h="Nahe der nördlichen Wildnis haben die Todespirscher unerwartet Truppen der Geißel entdeckt.",kw={"todespirscher","erland","hadrec","quinn","rane yorick","bericht","geißel","das grabmal","silberwald","unterstadt"},ang={["class:Rogue"]="Als Schurke überbringt Ihr lebenswichtige Depeschen für die führenden Spione der Verlassenen. Eure Arbeit verbindet Euch mit den Schattenagenten der Dunklen Fürstin.",["faction:Horde"]="Als Mitglied der Horde helft Ihr den Verlassenen, den Silberwald gegen die Geißel zu sichern. Ihre Kontrolle dort stärkt den Einfluss der Horde im gesamten nördlichen Lordaeron.",["race:Undead"]="Als Untoter überbringt Ihr Erkenntnisse, die die Ausbreitung von Unterstadt unterstützen. Damit beweist Ihr Hochexekutor Hadrec und dem Netzwerk der Todespirscher Eure Zuverlässigkeit."},sec={{t="Nachrichten von der Front",b="Die Todespirscher kundschaften für die Dunkle Fürstin voraus und dringen vor den Hauptstreitkräften in die Wildnis vor. Nahe der Grenze zwischen Tirisfal und dem Silberwald stieß eine Patrouille auf heftigen Widerstand, als sie feindliche Bewegungen verfolgte.\n\nDeathstalker Quinn überlebte seine Verletzungen nur knapp, während Erland sich den Weg in Sicherheit erkämpfte. Dennoch sammelte ihre Patrouille Informationen, die die Verlassenen brauchen, um den Silberwald zu halten."},{t="Der Faktor Geißel",b="Hochexekutor Hadrec liest den versiegelten Bericht und erfährt, dass die Geißel im Silberwald stärker vertreten ist, als die Strategen aus Unterstadt erwartet hatten. Ihre Truppen sind aktiver und angriffslustiger, als die Führung glaubte.\n\nDie Verlassenen hatten geplant, verlassene Menschensiedlungen zu sichern und wilde Bestien zu vertreiben. Nun muss sich die Führung im Grabmal auf organisierten Widerstand der Geißel vorbereiten, während sie um die Region kämpft."}},faq={{q="Was ist der Todespirscherbericht?",a="Deathstalker Rane Yorick verfasste den Feldbericht für ihre verwundete Spähergruppe. Er hält die beobachteten Bedrohungen fest, darunter unerwartete Aktivitäten der Geißel im nördlichen Silberwald, und übermittelt diese Erkenntnisse dem regionalen Befehlshaber im Grabmal.",al={"todespirscherbericht","was ist der bericht","was hat yorick mir gegeben"}},{q="Wer ist Hochexekutor Hadrec?",a="Hochexekutor Hadrec befehligt die Einsätze der Verlassenen im Silberwald. Vom Grabmal aus koordiniert er Späher, Verteidigung und den Feldzug gegen die Geißel und feindlich gesinnte Menschen in der Region.",al={"hadrec","hochexekutor hadrec","befehlshaber im grabmal"}},{q="Warum überraschten Hadrec die Informationen des Berichts?",a="Die Führung der Verlassenen glaubte, die Geißel im Silberwald sei versprengt und zahlenmäßig gering im Vergleich zu den Kämpfen in Tirisfal und den Plaguelands. Die Verluste und Entdeckungen der Todespirscher zeigen, dass die Diener des Lich King auch so weit im Süden noch fest verschanzt und gefährlich sind.",al={"warum überrascht","hadrecs reaktion","geißel im silberwald"}},{q="Wer sind die Todespirscher?",a="Die Todespirscher sind ein Eliteorden der Verlassenen aus Meuchelmördern, Spionen und Vorhutspähern unter dem Befehl von Fürstin Sylvanas Windläufer. Sie durchstreifen umkämpfte Gebiete, um Bedrohungen aufzuspüren, bevor das reguläre Heer vorrückt.",al={"deathstalkers","geschichte der todespirscher","schurken der verlassenen"}},{q="Wo liegt das Grabmal?",a="Das Grabmal liegt im mittleren Silberwald, unmittelbar westlich der Hauptstraße, die von Norden nach Süden führt. Es dient als Gruft und Basislager für die Truppen der Verlassenen in der gesamten Provinz.",al={"wo liegt das grabmal","lage des grabmals"}},{q="Was geschieht, nachdem Hadrec den Bericht gelesen hat?",a="Nachdem Hadrec den Bericht gelesen hat, schickt er Euch zu Fachleuten im Grabmal, zuerst zu Apotheker Renferrel. Sie werden helfen, Mittel gegen die Bedrohungen im Silberwald zu entwickeln.",al={"nächste quest","was nun","nach hadrec"}}},fx={df12075a={q="Warum muss Rane Yorick den Bericht so schnell übermitteln lassen?",a="Rane Yorick und ihre Gefährten deckten entscheidende Informationen über die Aktivitäten der Geißel und feindliche Bedrohungen in den Wildnissen des Silberwalds auf. Da diese Informationen sich direkt auf die Fähigkeit der Verlassenen auswirken, die Region zu sichern und zu halten, muss Hochexekutor Hadrec am Grabmal sie unverzüglich erhalten, damit das Militärkommando reagieren kann.",al={"warum will rane yorick das erledigt haben","rane yorick motivation","warum den todespirscherbericht senden"}},de251098={q="Warum bittet Rane Yorick Euch, den Bericht zu überbringen, anstatt es selbst zu tun?",a="Ranes Spähtrupp ist nicht reisefähig. Ihr Bruder und Mit-Todespirscher Quinn wurde während ihrer Mission schwer verwundet und erholt sich noch langsam unter Ranes Pflege. Da ihre Einheit bewegungsunfähig ist und der Bericht zu dringlich für eine Verzögerung ist, muss sich Rane auf einen fähigen Reisenden wie Euch verlassen, um die Depesche zum Grabmal zu bringen.",al={"warum ich rane yorick","warum kann rane nicht übermitteln","warum überbringe ich den bericht"}}},fp="25,280,22.381.0,18.411.0,32.253.0,28.195.0,54.274.0,26.212.0,31.157.0,43.186.0"}
P.entries["quest:4495"] = {n="Ein guter Freund",s="Bei Aldrassil wird Dirania Silberschein unruhig, als Iverron seinen täglichen Besuch auslässt. Sie bittet Reisende, die Hügel nahe der Schattenweberhöhle nördlich von Laubschattental nach ihm abzusuchen.",h="Bei Aldrassil wird Dirania Silberschein unruhig, als Iverron seinen täglichen Besuch auslässt.",kw={"ein guter freund","aldrassil","dirania silberschein","iverron","laubschattental","schattenweberhöhle","spinnen","teldrassil"},ang={["class:Druid"]="Als Druide erkennt Ihr in den aggressiven Webwaldspinnen nahe der Schattenweberhöhle vielleicht ein Zeichen der umfassenderen Verderbnis, die den großen Ast heimsucht.",["race:NightElf"]="Als junger Kaldorei unter Aldrassil könnt Ihr Diranias Ruf folgen und sehen, wie die wachsenden Gefahren der Lichtung ihre Bewohner treffen."},sec={{t="Ein vermisster Besucher",b="Unter Aldrassil wartet Dirania Silberschein auf Iverron, ihren Freund, der sie jeden Tag besucht. Stunden vergehen, und er kommt nicht. Also bittet sie Reisende, die nach Laubschattental unterwegs sind, nach ihm zu suchen."},{t="Gefahr an der Schattenweberhöhle",b="Iverron streift oft durch die Hügel im nördlichen Laubschattental, nahe den Webwaldspinnen der Schattenweberhöhle. Die Spinnen machen diese Hänge für Reisende gefährlich. Sucht westlich des Höhleneingangs, wo Iverron sich versteckt und Hilfe braucht."}},faq={{q="Wer ist Dirania Silberschein?",a="Dirania Silberschein ist eine Nachtelfe, die unter Aldrassil in Laubschattental lebt. Iverron besucht sie jeden Tag, weshalb sie sich Sorgen macht, als er nicht erscheint.",al={"dirania","dirania silberschein hintergrundgeschichte","wer startet ein guter freund"}},{q="Wer ist Iverron?",a="Iverron ist ein Nachtelf, der durch die Hügel nahe der Schattenweberhöhle in Laubschattental streift. Er lässt seinen täglichen Besuch bei Dirania Silberschein aus und wird auf den Klippen westlich des Höhleneingangs gefunden.",al={"iverron","wo ist iverron","wer ist der vermisste freund"}},{q="Wo ist Iverron zu finden?",a="Iverron versteckt sich am Hang unmittelbar westlich des Eingangs zur Schattenweberhöhle im nördlichen Laubschattental.",al={"iverron fundort","iverron finden","schattenweberhöhle iverron"}},{q="Warum gilt die nördliche Höhle als gefährlich?",a="Giftige Webwaldspinnen haben die Schattenweberhöhle und die umliegenden Hänge überrannt. Die Verderbnis, die sich in Teldrassil ausbreitet, hat sie aufgewühlt und macht die Gegend für allein reisende Wanderer gefährlich.",al={"warum ist die schattenweberhöhle gefährlich","spinnen in laubschattental","spinnenhöhle teldrassil"}},{q="Was geschieht, nachdem Iverron gefunden wurde?",a="Nachdem Ihr Iverron gefunden habt, erzählt er Euch, dass sein Missgeschick nahe der Spinnenhöhle ihn in große Not gebracht hat. Die Suche nach einer Behandlung beginnt mit A Friend in Need.",al={"quest nach ein guter freund","nächster schritt für iverron","a friend in need quest"}},{q="Warum machte sich Dirania so schnell Sorgen um Iverron?",a="Iverron besucht Dirania jeden Tag zur selben Stunde. Als er mehrere Stunden überfällig ist und sie weiß, dass er oft nahe den gefährlichen Spinnensenken umherstreift, fürchtet sie, ihm sei etwas zugestoßen.",al={"warum ist dirania besorgt","iverrons tagesablauf","warum fiel es dirania auf"}}},fx={["9ca4ec06"]={q="Warum benötigt Dirania Silberschein speziell meine Hilfe?",a="Dirania stellt kein formelles militärisches Ersuchen und mobilisiert nicht die Sentinels – sie bittet lediglich einen vorbeikommenden Abenteurer um einen persönlichen Gefallen. Da bekannt ist, dass Iverron häufig die gefährlichen Hügel in der Nähe der nördlichen Höhle aufsucht, hofft sie, dass jemand, der mit der lokalen Tierwelt umgehen kann, die Augen offen hält, während er in diese Richtung reist.",al={"warum bittet dirania mich","warum kann dirania nicht nach iverron suchen","warum keine wachen schicken"}}},fp="13,168,17.184.0,26.235.0,27.155.0,15.185.0,27.102.0,46.178.0,35.159.1,48.188.0"}
P.entries["quest:4496"] = {n="Dschungelei",s="In Gadgetzan erforscht Alchimist Pestlezugg die Silithiden und vergleicht sie mit Bienen. Er hält ihre Königin für die Schwachstelle und braucht Duftstoff und Erde aus dem westlich gelegenen Krater von Un'Goro.",h="In Gadgetzan erforscht Alchimist Pestlezugg die Silithiden und vergleicht sie mit Bienen.",kw={"gadgetzan","gorishi","pestlezugg","duftdrüse","silithiden","tanaris","krater von un'goro","un'goro-erde"},sec={{t="Ein Köder für die Königin",b="Alchimist Pestlezugg vergleicht die Silithiden mit Bienen. Er glaubt, dass der Rest in Verwirrung geraten wird, wenn ihre Königin vernichtet wird. Ein Köder kann sie herauslocken. Ihr sollt sie zur Strecke bringen, sobald sie erscheint."},{t="Reagenzien aus Un'Goro",b="Um den Köder herzustellen, braucht Pestlezugg Reagenzien aus dem Krater von Un'Goro. Der Bau der Silithiden liegt westlich von Gadgetzan. Er bittet Euch, eine unbeschädigte Duftdrüse von einem der Käfer und fünf Proben der dortigen Erde zu bringen."}},faq={{q="Wer bittet um die Duftdrüse und die Erde, und wo?",a="Alchimist Pestlezugg bittet in Gadgetzan darum.",al={"wer vergibt dschungelei","wo ist pestlezugg","dschungelei questgeber"}},{q="Was braucht Pestlezugg für den Köder?",a="Pestlezugg braucht eine unbeschädigte Gorishi-Duftdrüse von einem Silithidenkäfer und fünf Proben der einheimischen Un'Goro-Erde.",al={"dschungelei gegenstände","welche reagenzien braucht pestlezugg","duftdrüse und erde"}},{q="Wo liegt der Bau der Silithiden?",a="Der Bau der Silithiden liegt im Krater von Un'Goro, westlich von Gadgetzan.",al={"wo findet man eine gorishi-duftdrüse","wo liegt der bau der silithiden","wo findet man un'goro-erde"}},{q="Warum will Pestlezugg die Königin des Baus herauslocken?",a="Pestlezugg vergleicht die Silithiden mit Bienen und glaubt, dass der Rest ohne ihre Königin in Verwirrung geraten wird.",al={"warum die königin töten","pestlezuggs plan","silithiden-bienen-theorie"}}},fp="20,181,20.198.0,21.210.0,49.48.0,39.111.0,27.58.0,53.111.0"}
P.entries["quest:45"] = {n="Rolfs Schicksal",s="Wache Thomas wartet auf Nachricht von Rolf und Malakai, die nahe dem Steinhügelsee vermisst werden. Malakais halb aufgefressene Überreste und Schwimmhautabdrücke weisen auf ein Murlocdorf hin.",h="Wache Thomas wartet auf Nachricht von Rolf und Malakai, die nahe dem Steinhügelsee vermisst werden.",kw={"wald von elwynn","wache thomas","malakai","murlocs","rolf","rolf hartford","der steinhügelsee"},ang={["class:Warrior"]="Als Krieger erkennt Ihr an Rolf Hartfords Leichnam die blutige Wirklichkeit, der sich Fußsoldaten im Dienst des Reiches stellen müssen.",["faction:Alliance"]="Der Fund von Rolf zeigt, wie ungeschützt Sturmwinds ländliche Grenzgebiete sind. Der Personalmangel in den Garnisonen setzt selbst einfache Patrouillen tödlichen Angriffen aus der Wildnis aus."},sec={{t="Eine Fährte aus Schwimmhautabdrücken",b="Malakais halb aufgefressene Überreste liegen am Ufer. Schwimmhautabdrücke zeichnen sich im Schlamm ab und führen am Wasser entlang nach Osten. Sie führen geradewegs zu einem baufälligen Murloclager."},{t="Das Ende der Patrouille",b="Ihr folgt den Spuren mitten in die Murlocsiedlung an der Küste. Dort liegt ein weiterer Leichnam, von den Kreaturen gefleddert. Ein beschriftetes Medaillon um den Hals des toten Soldaten nennt seinen Namen: Fußsoldat Rolf Hartford. Keine der beiden Wachen hat den Hinterhalt überlebt."}},faq={{q="Wer war Rolf?",a="Rolf Hartford war ein Fußsoldat aus Sturmwind, der unter Wache Thomas gemeinsam mit Wache Malakai im östlichen Wald von Elwynn patrouillierte. Murlocs überwältigten und töteten beide Wachen nahe dem Steinhügelsee.",al={"wer ist rolf","fußsoldat rolf","rolf hartford"}},{q="Wo befindet sich Rolfs Leichnam?",a="Rolfs Leichnam liegt weiter östlich am Südufer des Steinhügelsees, in einem Murlocdorf nahe dem Seeufer.",al={"rolfs fundort","wo ist rolf","rolf finden"}},{q="Warum waren die Wachen nahe dem Steinhügelsee unterwegs?",a="Wache Thomas stationierte Wachen an den Flüssen und Seen im östlichen Elwynn, um nach Übergriffen von Murlocs und Gnollen Ausschau zu halten. Die Patrouillen waren unterbesetzt und anfällig für plötzliche, koordinierte Angriffe.",al={"warum verschwanden die wachen","was taten die wachen","wachenpatrouille elwynn"}},{q="Wie bestätigt Ihr, dass der Leichnam Rolf gehört?",a="Ein Metallmedaillon hängt um den Hals des zerfetzten Leichnams. Die Inschrift nennt seinen Namen: Fußsoldat Rolf Hartford.",al={"rolfs medaillon","rolf identifizieren"}},{q="Was geschieht, nachdem Ihr Rolf gefunden habt?",a="Nachdem Malakais und Rolfs Schicksal geklärt ist, erhaltet Ihr den Auftrag, nach Westen zur Brücke beim Holzfällerlager des Osttals zurückzukehren. Dort überbringt Ihr Wache Thomas die düstere Nachricht.",al={"nächste quest nach rolf","was nach rolf zu tun ist"}},{q="Sind die Murlocs im Steinhügelsee eine ungewöhnliche Bedrohung?",a="Die Murlocs in Elwynn sind ungewöhnlich aggressiv geworden und gehen koordiniert vor. Sie dringen landeinwärts in den Steinhügelsee und die Flüsse vor und bedrohen den örtlichen Handel ebenso wie vereinzelte Patrouillen.",al={"murlocbedrohung elwynn","warum greifen murlocs an"}}},fx={["51025c24"]={q="Warum den halb gefressenen Körper weiter untersuchen?",a="Der halb gefressene Körper am Fluss gehört Malakai Stone, aber sein Patrouillenpartner Rolf bleibt verschwunden. Spuren mit Schwimmhäuten, die vom Ort des Gemetzels wegführen, sind der einzige Hinweis auf Rolfs Verbleib, was Euch dazu zwingt, weiterzugehen und festzustellen, ob er entkommen konnte oder in tieferem Murloc-Gebiet ein grimmiges Ende fand.",al={"warum nach rolf suchen","halb gefressener körper motiv","warum nach hinweisen auf rolf suchen"}}},fp="20,157,24.162.0,17.246.1,13.189.1,29.125.1,46.188.0,46.103.1,32.169.1,54.176.0"}
P.entries["quest:450"] = {n="Rezept für den Tod",s="Von Unterstadt aus schickt Euch Apothekermeister Faranell in Rezept für den Tod nach Lohenscheit. Ihr sucht Apotheker Berards Notizen über die uralte Seuche, die alles Wasserleben im Lordameresee auslöschte.",h="Von Unterstadt aus schickt Euch Apothekermeister Faranell in Rezept für den Tod nach Lohenscheit.",kw={"arugal","berard","faranell","tagebuch","lordamere","loh enscheit","renferrel","das grabmal"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr der Königlichen Apothekervereinigung im Silberwald, die Grenzen der Verlassenen gegen die wilden Schrecken zu sichern, die Arugal entfesselt hat.",["race:Undead"]="Als Untoter erlebt Ihr den kalten Pragmatismus der Königlichen Apothekervereinigung. Als Berard dem Wahnsinn verfiel, stellte die Vereinigung sein tragisches Schicksal hintan, um seine tödliche Forschung zu retten."},sec={{t="Ein Geist im Schatten verloren",b="Apotheker Berard zählte einst zu den vielversprechendsten Forschern der Königlichen Apothekervereinigung. Er arbeitete in Lohenscheit und untersuchte vergangene ökologische Katastrophen für die alchemistischen Bestrebungen der Verlassenen. Dann entfesselte Erzmagier Arugal Shadow Magic im gesamten Silberwald, und Berard erlag ihrem Fluch. Sein Geist zerbrach, und er wurde an den Magier als dessen Diener gebunden."},{t="Die Geheimnisse des Lordameresees",b="Apothekermeister Faranell hält Apotheker Berard für unrettbar, doch die Königliche Apothekervereinigung braucht seine Forschung weiterhin. Berard zeichnete die Eigenschaften einer vergessenen Seuche auf, die vor langer Zeit alles Wasserleben im Lordameresee auslöschte. Sein Tagebuch liegt im Gasthaus von Lohenscheit. Ihr sollt es bergen und Apotheker Renferrel im Grabmal bringen, damit die Vereinigung die tödlichen Eigenschaften der Seuche für das Arsenal der Dunklen Fürstin nutzbar machen kann."}},faq={{q="Wer ist Apotheker Berard?",a="Apotheker Berard war einst einer der vielversprechendsten Forscher der Königlichen Apothekervereinigung im Silberwald. Erzmagier Arugals Schattenfluch zerschmetterte seinen Geist und band ihn als willenlosen Diener in Lohenscheit.",al={"berard hintergrund","wer war berard","apotheker berard lohenscheit"}},{q="Warum will die Königliche Apothekervereinigung Berards Tagebuch?",a="Berards Tagebuch beschreibt eine uralte Seuche, die alles Wasserleben im Lordameresee auslöschte. Es hält die Eigenschaften der Seuche für die Königliche Apothekervereinigung fest.",al={"warum das tagebuch holen","berards tagebuch zweck","lordameresee seuchennotizen"}},{q="Wo befindet sich Berards Tagebuch?",a="Berards Tagebuch liegt in seinem Arbeitszimmer in einem oberen Stockwerk des Gasthauses von Lohenscheit, im hinteren Teil des Dorfes. Der vom Fluch befallene Apotheker bewacht noch immer seine einstigen Gemächer.",al={"wo ist das tagebuch","berards tagebuch finden","loh enscheit gasthaus tagebuch"}},{q="Wer erhält das geborgene Tagebuch?",a="Apotheker Renferrel erhält das Tagebuch im Grabmal im Silberwald. Er leitet dort die Feldeinsätze der Königlichen Apothekervereinigung.",al={"wer gibt berards tagebuch ab","wem das tagebuch bringen","wohin das tagebuch bringen"}},{q="Was ist mit Lohenscheit geschehen?",a="Erzmagier Arugals Shadow Magic aus der nahen Burg Shadowfang verdarb Lohenscheit. Der Fluch entstellte Geist und Körper der Dorfbewohner und band sie an Arugals Willen.",al={"loh enscheit fluch","was stimmt mit lohenscheit nicht","arugal fluch lohenscheit"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell leitet die Königliche Apothekervereinigung vom Apothekarium in Unterstadt aus. Er überwacht die Herstellung von Seuchen und Giften, um die Verlassenen zu verteidigen und ihre Feinde auszurotten.",al={"faranell","wer vergibt rezept für den tod","apotheker anführer unterstadt"}}},fx={["5e9e51e7"]={q="Was ist Berards Tagebuch?",a="Berards Tagebuch enthält die Forschungsnotizen von Apotheker Berard, bevor der Fluch von Erzmagier Arugal ihm den Verstand raubte. Darin dokumentierte Berard eine uralte Seuche, die vor langer Zeit das aquatische Leben im Lordameresee ausrottete. Die Apothekervereinigung der Verlassenen hofft, seine Erkenntnisse zu studieren, um neue Seuchen für die Verlassenen zu entwickeln.",al={"berards tagebuch","was steht in berards tagebuch","berards tagebuch zweck"}},["3b951ca3"]={q="Wer bewacht Berards Tagebuch in Lohenscheit?",a="Das Tagebuch verbleibt im Gasthaus von Lohenscheit, bewacht von Berard selbst zusammen mit den verfluchten Dorfbewohnern. Einst ein vielversprechender Alchemist der Apothekervereinigung, erlag Berard Arugals Schattenmagie und dient dem wahnsinnigen Magier nun geistesabwesend als wildes Wesen, feindselig gegenüber jedem, der in sein früheres Arbeitszimmer eindringt.",al={"wer bewacht berards tagebuch","wer bewacht das tagebuch","gegen wen kämpfe ich für das tagebuch"}}},fp="18,202,21.359.0,29.444.1,25.210.0,60.160.0,34.172.0,35.147.0,34.167.0,34.200.0"}
P.entries["quest:4504"] = {n="Superkleber",s="In Gadgetzan wittert Tran'rek mit superklebrigem Kleber schnelles Gold. Er braucht Teer von Bestien nahe den Gruben im nördlichen Krater von Un'Goro und bietet einen kleinen Anteil am Gewinn.",h="In Gadgetzan wittert Tran'rek mit superklebrigem Kleber schnelles Gold.",kw={"chlorophyll","gadgetzan","kleber","superklebriger teer","tanaris","teergruben","tran'rek","krater von un'goro"},sec={{t="Eine klebrige Idee",b="Tran'rek hofft, dass seine neueste Idee schnelles Gold einbringt, und bietet Euch einen kleinen Anteil am Gewinn. Gewöhnlicher Teer ist nicht klebrig genug. Er will zwölf Proben von Kreaturen nahe den Teergruben im nördlichen Krater von Un'Goro."},{t="Warum gerade Bestien",b="Die pflanzenartigen Kreaturen rund um die Gruben haben Chlorophyll in ihrer Haut. Mit Teer vermischt ergibt es einen superklebrigen Kleber."},{t="Wenn der Teer ankommt",b="Als Tran'rek mit dem Teer hantiert, kleben seine Hände bald zusammen. Er ändert seinen Plan auf der Stelle. Mit einem Entferner für superklebrigen Teer, so beschließt er, lässt sich das große Geld verdienen."}},faq={{q="Wer verlangt nach dem klebrigen Teer?",a="Tran'rek in Gadgetzan verlangt nach dem klebrigen Teer.",al={"wer vergibt superkleber","superkleber questgeber","tran'rek quest"}},{q="Warum muss der Teer von Bestien stammen?",a="Gewöhnlicher Teer ist nicht klebrig genug. Die pflanzenartigen Kreaturen rund um die Teergruben haben Chlorophyll in ihrer Haut, das den Teer superklebrig macht.",al={"warum bestienteer","gewöhnlicher teer gegen klebrigen teer","warum teer von bestien holen"}},{q="Wo sind die Teerbestien?",a="Die Teerbestien leben bei den Teergruben im nördlichen Krater von Un'Goro.",al={"wo ist superklebriger teer","teerbestien fundort","un'goro teergruben"}},{q="Was hat Tran'rek mit dem Teer vor?",a="Tran'rek will superklebrigen Kleber herstellen, um schnelles Gold zu verdienen, und bietet jedem, der hilft, einen kleinen Anteil am Gewinn.",al={"tranrek ziel","superkleber zweck","warum will tran'rek teer"}}},fp="12,161,13.212.0,14.118.0,20.164.1,28.46.0,42.145.0,25.63.0,43.107.0"}
P.entries["quest:4507"] = {n="Bauer schlägt Dame",s="Alchimist Pestlezugg schickt Euch mit einem Köder für die Gorishi Hive Queen in den Krater von Un'Goro. Nach Bungle in the Jungle möchte er ihr Gehirn zu Forschungszwecken nach Gadgetzan gebracht haben.",h="Alchimist Pestlezugg schickt Euch mit einem Köder für die Gorishi Hive Queen in den Krater von Un'Goro.",kw={"gehirn","gadgetzan","gorishi","köder","pestlezugg","königin","silithiden","tanaris","un'goro"},sec={{t="Der Köder und der Kristall",b="Pestlezugg gibt Euch einen Köder für den Silithidenbau. Er glaubt, dass ein Kristall im Netzwerk des Baus den ganzen Schwarm aufeinander einstimmt, und die Brutstätten sind der beste Ort für die Suche. Wendet den Köder auf den Kristall an, und die Königin sollte mit mehreren Wachen an ihrer Seite hervorkommen."},{t="Das Gehirn der Königin",b="Pestlezugg möchte, dass Ihr das Gehirn der Königin nach Gadgetzan bringt. Er weiß, dass das eklig klingt, sagt aber, dass das Gehirn dringend für Untersuchungen gebraucht wird."},{t="Nach dem Fall der Königin",b="Pestlezugg vermutet, dass eine bösartige Intelligenz die Silithiden beherrschen könnte. Der Gedanke daran, was etwas so Heimtückisches befehligen könnte, lässt ihn schaudern. Als das Gehirn eintrifft, nennt er es einen beachtlichen Sieg, bezweifelt jedoch, dass dies das ganze Ausmaß der Silithidenpräsenz ist. Die Lösung erscheint ihm zu glatt."}},faq={{q="Wo ist die Gorishi Hive Queen?",a="Wendet Pestlezuggs Köder auf einen Kristall im Silithidenbau im Krater von Un'Goro an. Er erwartet, einen in den Brutstätten zu finden, wo er die Königin hervorlocken sollte.",al={"gorishi-königin fundort","wo ist die silithidenkönigin","wo gorishi-königin finden"}},{q="Wozu dient der Kristall im Bau?",a="Pestlezugg glaubt, dass ein Kristall im Netzwerk des Baus den ganzen Silithidenschwarm aufeinander einstimmt. Der Köder ist für diesen Kristall bestimmt, und die Brutstätten sind der Ort für die Suche.",al={"kristall im bau","königin köder kristall","königinnenköder verwenden"}},{q="Warum will Pestlezugg das Gehirn der Königin?",a="Pestlezugg sagt, dass das Gehirn der Königin dringend für Untersuchungen gebraucht wird, und möchte, dass Ihr es nach Gadgetzan bringt.",al={"warum gorishi-gehirn","gorishi-königin gehirn zweck","pestlezuggs forschung"}},{q="Was kommt davor?",a="Zuvor bat Pestlezugg Euch in Bungle in the Jungle um eine Duftdrüse und Un'Goro-Erde, um den Köder zu brauen.",al={"bauer schlägt dame voraussetzungen","welche quest kommt vor bauer schlägt dame","vorherige quest"}}},fp="19,169,24.257.0,17.132.0,21.296.1,32.152.0,36.161.0,43.99.0,23.110.0"}
P.entries["quest:4508"] = {n="Die Ruhe vor dem Sturm",s="Nach dem Sturz der Königin tragt Ihr die neuesten Erkenntnisse aus Un'Goro über Gadgetzan hinaus. Alchimist Pestlezugg schickt den Bericht an Gracina Spiritmight im Tempel des Mondes in Darnassus.",h="Nach dem Sturz der Königin tragt Ihr die neuesten Erkenntnisse aus Un'Goro über Gadgetzan hinaus.",kw={"darnassus","gadgetzan","gracina spiritmight","pestlezugg","silithiden","tanaris","tempel des mondes","un'goro-bericht"},sec={{t="Ein Bericht für Darnassus",b="Alchimist Pestlezugg sagt, dass Gadgetzan den Silithiden nicht allein entgegentreten kann. Die neuesten Erkenntnisse aus Un'Goro müssen jemanden erreichen, der danach handeln kann, also bringt Ihr den Bericht zu Gracina Spiritmight in Darnassus. Pestlezugg hofft, dass sie im Tempel des Mondes ist. Sie hat Freunde unter den führenden Persönlichkeiten der Allianz, und sie einzubeziehen könnte einen Weg eröffnen, dies lebend zu überstehen."},{t="Gracinas Antwort",b="Gracina Spiritmight begrüßt den Bericht, bezweifelt jedoch, dass er helfen wird. Sie sagt, wer nicht über seinen Hass auf die Horde hinwegsehen kann, sei ein Narr. Die Allianz ignoriert jede Bedrohung außer der Horde, und selbst die Anführer von Darnassus sind sich über die Silithiden uneins. Gracina sagt, Fandral Hirschhaupt glaube, dass sie nicht der uralten Gefahr gleichen, die sie in ihnen sieht. Sie kann die Gefahr nicht weiter belegen, ohne jemanden in einen Bau zu werfen. Sie mahnt Euch, weiterhin entschlossen auf den Sieg über die Silithiden hinzuarbeiten."}},faq={{q="Wer schickt Euch mit dem Bericht los?",a="Alchimist Pestlezugg schickt Euch mit dem Bericht über die neuesten Erkenntnisse aus Un'Goro von Gadgetzan aus los.",al={"wer startet die ruhe vor dem sturm","questgeber die ruhe vor dem sturm","wo beginnt die ruhe vor dem sturm"}},{q="Wo muss der Bericht abgegeben werden?",a="Bringt den Bericht zu Gracina Spiritmight in Darnassus, im Tempel des Mondes, wo sie sich nach Pestlezuggs letztem Wissensstand aufhielt.",al={"wohin mit pestlezuggs bericht","wo ist gracina spiritmight","die ruhe vor dem sturm abgeben"}},{q="Warum schickt Pestlezugg den Bericht an Gracina Spiritmight?",a="Gadgetzan kann den Silithiden nicht allein entgegentreten. Gracina hat Freunde unter den führenden Persönlichkeiten der Allianz, und sie einzubeziehen könnte einen Weg eröffnen, dies lebend zu überstehen.",al={"warum nach darnassus schicken","warum gracina spiritmight"}},{q="Was kommt unmittelbar davor?",a="Pawn Captures Queen kommt unmittelbar davor. Ihr wurdet ausgeschickt, um die Gorishi Hive Queen zu jagen.",al={"voraussetzung für die ruhe vor dem sturm","vorherige quest die ruhe vor dem sturm"}}},fp="21,184,22.362.0,16.469.1,30.98.0,35.120.0,59.155.0,32.91.0"}
P.entries["quest:4509"] = {n="Die Ruhe vor dem Sturm",s="Nach dem Fall der Königin schickt Alchimist Pestlezugg seine neuesten Erkenntnisse an jene, die handeln können. Ihr bringt seinen Bericht über Un'Goro zu Zilzibin Drumlore in Orgrimmar.",h="Nach dem Fall der Königin schickt Alchimist Pestlezugg seine neuesten Erkenntnisse an jene, die handeln...",kw={"die ruhe vor dem sturm","drag","gadgetzan","orgrimmar","pestlezugg","silithiden","tanaris","zilzibin drumlore"},sec={{t="Ein Bericht für Orgrimmar",b="Gadgetzan kann dies nicht allein bewältigen, also schickt Euch Alchimist Pestlezugg mit seinen neuesten Erkenntnissen über Un'Goro los. Er möchte sie in den Händen jener wissen, die handeln können. Pestlezugg vermutet Zilzibin Drumlore im oberen Teil der Drag in Orgrimmar. Zilzibin hat Freunde in hohen Rängen der Horde, und sie einzubeziehen könnte einen Weg eröffnen, dies lebend zu überstehen."},{t="Zilzibins Antwort",b="Zilzibin Drumlore nennt jene Narren, die nur ihren Hass auf die Allianz sehen. Er sagt, er könne ihnen die Bedrohung durch die Silithiden nicht deutlicher beweisen, ohne sie in einen Bau zu werfen. Er begrüßt den Bericht, bezweifelt aber, dass er helfen wird. Die Horde ignoriert jede Bedrohung außer der Allianz. Thrall selbst könnte handeln, wenn ihn die Fakten erreichten, doch widersprüchliche Ratschläge bedrängen ihn von allen Seiten. Zilzibin drängt Euch, weiterhin entschlossen für den Sieg über die Silithiden einzutreten."}},faq={{q="Wer schickt Euch mit dem Bericht los?",a="Alchimist Pestlezugg schickt Euch von Gadgetzan aus los.",al={"questgeber die ruhe vor dem sturm","wer vergibt die ruhe vor dem sturm","pestlezugg quest"}},{q="Wo ist Zilzibin Drumlore?",a="Zilzibin Drumlore ist in Orgrimmar. Pestlezugg vermutet ihn im oberen Teil der Drag.",al={"zilzibin drumlore aufenthaltsort","wo ist zilzibin","zilzibin drumlore orgrimmar"}},{q="Warum schickt Pestlezugg den Bericht an Zilzibin Drumlore?",a="Gadgetzan kann dies nicht allein bewältigen. Zilzibin hat Freunde in hohen Rängen der Horde, und sie einzubeziehen könnte einen Weg eröffnen, dies lebend zu überstehen.",al={"warum bericht nach orgrimmar schicken","pestlezuggs beweggrund"}},{q="Was kommt unmittelbar davor?",a="Pawn Captures Queen kommt unmittelbar davor. Ihr wurdet ausgesandt, um die Gorishi Hive Queen zu jagen.",al={"die ruhe vor dem sturm voraussetzungen","vorherige quest die ruhe vor dem sturm"}}},fp="21,159,22.333.0,17.440.1,30.46.0,27.88.0,57.131.0,32.91.0"}
P.entries["quest:451"] = {n="Rezept für den Tod",s="Über den Lordameresee schickt Euch Apotheker Renferrel, um seltene Reagenzien für die Königliche Apothekervereinigung zu sammeln. Berards Tagebuch beschreibt Moose und einen seltsamen Tumor, bestimmt für Apothekermeister Faranell in Unterstadt und seine Arbeit an einer A New Plague.",h="Über den Lordameresee schickt Euch Apotheker Renferrel, um seltene Reagenzien für die Königliche...",kw={"rezept für den tod","das apothekarium","berard","die morgeninseln","faranell","verhärteter tumor","seesucher","der lordameresee","seestreuner","new plague","renferrel","vile fin"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr den Apothekern der Verlassenen helfen, Reagenzien für ihre New Plague zu sammeln.",["race:Undead"]="Berards unvollendete Experimente als Untoter dienen der Vision der Dark Lady. Jeder Geist der Verlassenen hilft der Nation zu überleben, selbst im Tod."},sec={{t="Ein Vermächtnis der Forschung",b="Apotheker Berards Tod unter Arugals Fluch kostete die Königliche Apothekervereinigung einen fähigen Forscher. Sein Feldtagebuch blieb erhalten und bewahrte seine Erkenntnisse über das verseuchte Leben im Silberwald und im Lordameresee. Im Grabmal studierte Apotheker Renferrel die geborgenen Aufzeichnungen und fand Berards Bericht über vielversprechende Eigenschaften örtlicher Süßwasserorganismen. Nun bittet Renferrel Euch, die Arbeit fortzuführen, die sein Kollege begonnen hat."},{t="Die Gefahren des Lordameresees",b="Berards Reagenzien finden sich auf den Morgeninseln, nebelverhangenen Inseln in den östlichen Gewässern des Lordameresees. Seestreuner und Seesucher auf den Inseln tragen eigentümliche Moosarten, die in verseuchtem Wasser leben. Berard vermerkte außerdem einen verhärteten Tumor bei den wilden Vile Fin-Murlocstämmen, die entlang der Inselchen und am südlichen Seeufer nahe Mühlenbern nisten."},{t="Nachschub fürs Apothekarium",b="Apothekermeister Faranell erhält die Proben im Apothekarium in Unterstadt, ohne Umweg über das Grabmal. Er hält diese seltsamen Mutationen für unverzichtbar, um eine A New Plague herzustellen, die die Geißel und die Lebenden vernichten kann. Berards Forschung fließt nun in die Arbeit der Vereinigung an ihren Braukesseln ein und bringt die Verlassenen ihrer Waffe näher."}},faq={{q="Warum braucht die Königliche Apothekervereinigung Moos und einen Tumor?",a="Apotheker Berards Feldtagebuch beschreibt ungewöhnliche Eigenschaften von Wassermoosen auf Seebestien und verhärteten Tumoren, die an örtlichen Vile Fin-Murlocs wachsen. Apothekermeister Faranell verwendet diese seltenen, veränderten Materialien, um die New Plague der Königlichen Apothekervereinigung zu brauen und zu verfeinern.",al={"warum moos und tumor","zutaten des apothekerrezepts","wozu dient der tumor"}},{q="Wer war Berard?",a="Apotheker Berard forschte für die Königliche Apothekervereinigung im Silberwald. Arugals Fluch machte ihn zu einem willenlosen Diener, doch sein geborgenes Feldtagebuch lieferte Apotheker Renferrel und Apothekermeister Faranell die nötigen Reagenziendetails zur Fortsetzung seiner Arbeit.",al={"apotheker berard","wer ist berard","berards tagebuch"}},{q="Wo liegen die Morgeninseln?",a="Die Morgeninseln sind kleine Inseln im östlichen Lordameresee, direkt östlich des Silberwalds. Seestreuner, Seesucher und feindselige Vile Fin-Murlocstämme bevölkern sie.",al={"wo liegen die morgeninseln","lage der morgeninseln","seestreuner fundort"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell führt die Königliche Apothekervereinigung aus den Tiefen des Apothekariums in Unterstadt. Er beaufsichtigt die Erforschung chemischer Kriegsführung und biologischer Gebräue sowie die Erschaffung der New Plague für Fürstin Sylvanas Windläufer.",al={"faranell","wer ist faranell","apothekermeister faranell"}},{q="Warum wachsen Vile Fin-Murlocs verhärtete Tumore?",a="Verseuchte Fäulnis und nahe arkane Konflikte haben die Gewässer und Ufer des Lordameresees verändert. Verhärtete Tumore an den Vile Fin sind seltene, abnorme Wucherungen aus dieser verseuchten Umgebung, und die Verlassenen schätzen sie als Forschungsobjekte.",al={"warum murloc-tumor","vile fin tumor hintergrund","verhärteter tumor murlocs"}},{q="Wie hängt diese Quest mit der New Plague zusammen?",a="Die Questreihe Rezept für den Tod dient dem Sammeln von Zutaten für die New Plague. Nachwuchsapotheker wie Renferrel entschlüsseln und sammeln regionale Materialien und schicken sie dann zu Faranell, der in Unterstadt an der Seuche braut.",al={"verbindung zur new plague","a new plague questreihe","ist das die seuche"}}},fx={ba3f7fe6={q="Warum will Apotheker Renferrel, dass dies erledigt wird?",a="Apotheker Renferrel widmet sich dem Vorantreiben der Forschung der Apothekervereinigung zur Neuen Seuche. Nach dem Verlust seines Kollegen Berard entzifferte Renferrel Berards Feldtagebuch und entdeckte vielversprechende Hinweise auf einzigartige biologische Reagenzien. Indem er Euch schickt, um diese Proben zu sammeln und sie direkt an Apothekermeister Faranell in der Unterstadt zu liefern, stellt Renferrel sicher, dass Berards Opfer nicht umsonst war und ihre Arbeit für die Dunkle Fürstin ohne Verzögerung fortgesetzt wird.",al={"warum will renferrel das","renferrel motiv","warum schickt euch apotheker renferrel"}},["98d37a99"]={q="Was jagt Ihr auf den Morgeninseln?",a="Ihr werdet an den östlichen Lordameresee entsandt, um die Seeungeheuer und lokalen Murlocs zu jagen, die um die Morgeninseln herum hausen. Seeschleicher und Seekriecher liefern die lebenswichtigen Moose, die in Berards Tagebuch identifiziert wurden, während die aggressiven Stinkflossen-Murlocstämme, die an den Ufern leben, gelegentlich die seltsamen, verhärteten Wucherungen entwickeln, die Apothekermeister Faranell für seine Experimente benötigt.",al={"gegen wen werdet ihr ausgesandt","was tötet ihr in a recipe for death","ziele am lordameresee"}}},fp="18,250,20.437.0,29.362.0,24.342.1,60.280.0,15.265.0,36.172.0,34.256.0,49.224.0,46.212.0"}
P.entries["quest:4512"] = {n="Schlamm auf Abwegen",s="In Eisenschmiede sucht Laris Bummelritzel für seine Studien Schlammproben aus dem Teufelswald. Er hofft zu erfahren, warum die Royal Apothecary Society sie sammelt und was die Alchemisten von Unterstadt daran interessiert.",h="In Eisenschmiede sucht Laris Bummelritzel für seine Studien Schlammproben aus dem Teufelswald.",kw={"cursed ooze","explorers' league","teufelswald","gnomeregan","eisenschmiede","laris bummelritzel","schlamm","royal apothecary society","schleim","tainted ooze"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr aus den Sammelgewohnheiten der Royal Apothecary Society etwas über die finsteren Gebräue erfahren, die Unterstadt womöglich zusammenbraut.",["race:Dwarf"]="Als Zwerg zieht Ihr Stein und Metall vielleicht gallertartigem Schlamm vor. Die Explorers' League profitiert von Laris' ungewöhnlichem Eifer.",["race:Gnome"]="Als Gnom erkennt Ihr Laris' Bestreben, nach dem schmerzlichen Verlust Gnomeregans den Stolz und das Ansehen der Gnome wiederherzustellen."},sec={{t="Eine seltsame Besessenheit",b="Laris Bummelritzel erforscht Schlämme bei der Explorers' League. Die meisten ihrer Gelehrten suchen nach Titanenrelikten oder Zwergenstammbäumen, doch diese lebenden Pfützen entziehen sich der üblichen Einordnung. Sie kommen in Feuchtgebieten, verfluchten Wäldern und feuchten Ruinen vor. Laris hat gesehen, wie Apotheker der Verlassenen in ganz Lordaeron Schleim sammeln, und will wissen, was sie daran reizt."},{t="Das urtümliche Sekret",b="Laris glaubt, Schlämme könnten urtümliche Sekrete sein, die mit Azeroths Entstehung verbunden sind. Er hält sie weder für Ungeziefer noch für magische Nebenprodukte. Um seine Theorie zu prüfen, reist Ihr über das Meer unter das verdorbene Blätterdach des Teufelswalds. Dort sammelt Ihr Cursed Oozes und Tainted Oozes in eigens angefertigten Gläsern."},{t="Den Wert der Gnome beweisen",b="Für Laris und viele vertriebene Gnome haben diese Studien eine persönliche Bedeutung. Seit Gnomeregan an Troggs und Strahlung fiel, haben Tausende in der Großen Schmiede von Eisenschmiede Zuflucht gefunden. Eine Entdeckung für die Explorers' League könnte den Skeptikern unter den Zwergen eine Antwort geben. Sie könnte zeigen, dass die Aufnahme der Gnome in die Bergstadt zu einem dauerhaften Gewinn für die Wissenschaft der Allianz geworden ist."}},faq={{q="Wer ist Laris Bummelritzel?",a="Laris Bummelritzel ist ein gnomischer Forscher und Gelehrter in Eisenschmiede. Er arbeitet mit der Explorers' League zusammen, um die biologischen Ursprünge von Schlämmen und Schleimen in ganz Azeroth zu erforschen.",al={"laris bummelritzel","wer ist der questgeber","gnom mit schlämmen"}},{q="Warum liegt Laris so viel an Schlamm?",a="Laris vermutet, dass Schlämme urtümliche Sekrete sind, die mit Azeroths Ursprüngen verbunden sind. Weil die Royal Apothecary Society so eifrig Schleimproben sammelt, ist er entschlossen, ihre geheimen Eigenschaften vor der Horde zu ergründen.",al={"warum schleime erforschen","warum schlammgläser","schlammtheorie"}},{q="Wo sammelt Ihr die Schlammproben?",a="Ihr sammelt Proben von Cursed Oozes und Tainted Oozes in den verderbten Wäldern des Teufelswalds im Norden Kalimdors. Dafür verwendet Ihr leere Glasbehälter, die Laris Euch gibt.",al={"wo sind die schlämme","tainted ooze fundort","cursed ooze fundort"}},{q="Warum sammeln die Verlassenen Schlämme?",a="Die Royal Apothecary Society experimentiert mit Giften, Seuchen und biologischen Schrecken, um die Alchemie der Verlassenen voranzutreiben. Ihr Interesse an unverarbeiteten Schlämmen deutet darauf hin, dass diese hochansteckende oder erbgutverändernde Verbindungen enthalten könnten.",al={"unterstadt schlämme","royal apothecary society schleim","warum wollen verlassene schlamm"}},{q="Wie hängt diese Quest mit dem Fall von Gnomeregan zusammen?",a="Nachdem Gnomeregan an Troggs und Strahlung verloren war, spürte Laris die Last des Flüchtlingslebens in Eisenschmiede. Er hofft, dass ein großer wissenschaftlicher Triumph für die Explorers' League beweisen wird, dass es sich für ihre zwergischen Gastgeber gelohnt hat, den Gnomen Zuflucht zu gewähren.",al={"verbindung zu gnomeregan","beziehungen zwischen zwergen und gnomen","gnomische flüchtlinge eisenschmiede"}},{q="Was geschieht, nachdem Ihr die Proben abgeliefert habt?",a="Laris beginnt, die Proben mit seiner Laborausrüstung in Eisenschmiede zu untersuchen. Er entwickelt seine Theorien zur Einordnung der Schlämme und ihren elementaren Ursprüngen weiter.",al={"folgequest der schleimquest","was kommt nach den schlammgläsern"}}},fx={["930e16d1"]={q="Wofür sind die mit Schleim gefüllten Gläser?",a="Die Gläser enthalten frische Proben, die aus den Überresten verfluchter und verseuchter Schlammwesen aus dem Teufelswald entnommen wurden. Laris Bummelritzel benötigt sie für wissenschaftliche Experimente in Eisenschmiede. Er hofft, die wahre Natur von Schlammwesen aufzudecken und seine kontroverse Theorie zu beweisen, dass Schleime mit der ursprünglichen Schöpfung von Azeroth selbst verbunden sind.",al={"mit verfluchtem schlamm gefülltes glas","mit besudeltem schlamm gefülltes glas","wofür werden die schleimgläser verwendet","schleimproben verwendung"}},["8c5a6c23"]={q="Welche Kreaturen jagt Ihr im Teufelswald?",a="Ihr werdet losgeschickt, um die verfluchten und verseuchten Schlammwesen zu jagen, die in den korrumpierten Wildnissen des Teufelswalds lauern. Der Teufelswald wurde durch Dämonenmagie schwer verzerrt, was bizarre und instabile Mutationen hervorbringt. Laris möchte Proben von diesen speziellen Schleimen, um sie mit anderen Arten aus ganz Azeroth zu vergleichen und zu sehen, wie Umweltkorruption deren Zusammensetzung verändert.",al={"gegen was kämpfen wir","ziel verfluchter schleim","verseuchter schleim teufelswald","wen töten wir"}}},fp="30,190,20.346.0,24.280.0,21.354.0,24.170.0,39.218.0,37.154.0,38.199.0,54.247.0,43.137.0"}
P.entries["quest:4513"] = {n="Schlamm auf Abwegen",s="Laris Bummelritzel sucht in ganz Kalimdor nach reinen Schlämmen. Seine vom Teufelswald verdorbenen Proben zeigten, dass Schlämme ihre Umgebung aufnehmen und widerspiegeln. Unverdorbene Exemplare könnten ihm zeigen, wie sie sich an ihre Lebensräume anpassen.",h="Laris Bummelritzel sucht in ganz Kalimdor nach reinen Schlämmen.",kw={"teufelswald","klebriger schlamm","eisenschmiede","laris bummelritzel","schlammforschung","gefäße für reine proben","krater von un'goro"},ang={["faction:Alliance"]="Als Abenteurer der Allianz reist Ihr von Eisenschmiede in Kalimdors ungezähmte Wildnis, um die gnomische Forschung zu unterstützen.",["race:Gnome"]="Als Gnom wisst Ihr Laris' sorgfältige Methode zu schätzen. Er isoliert Variablen und sucht eine unverunreinigte Kontrollgruppe, bevor er weitreichende Schlüsse zieht."},sec={{t="Eine Frage der Reinheit",b="Laris Bummelritzel benötigt unverdorbene Proben für seine Forschung. Die verdorbenen zeigten, wie Schlämme die Eigenschaften ihrer Umgebung annehmen, ließen ihm aber keine klare Vergleichsmöglichkeit. Er sucht Proben, die von dämonischer Verderbnis und städtischem Unrat unberührt sind, um das Schlammleben für sich genommen zu untersuchen."},{t="Dem urzeitlichen Schleim auf der Spur",b="Im Krater von Un'Goro gedeihen klebrige Schlämme in einer abgeschiedenen, urzeitlichen Wildnis. Ihre Proben liefern Laris das reine Material, das er braucht, um die Wechselwirkungen zwischen Schlämmen und Azeroths lebendigen Biomen zu untersuchen."}},faq={{q="Warum benötigt Laris Bummelritzel reine Schlammproben?",a="Laris' frühere Exemplare trugen die Verderbnis des Teufelswalds in sich. Um seine Vermutung zu prüfen, dass Schleime sich ihrer Umgebung anpassen und sie widerspiegeln, benötigt er reine Vergleichsproben aus einem unverschmutzten Lebensraum.",al={"warum reiner schlamm","laris reiner schleim","was ist reiner schlamm"}},{q="Wo befinden sich die reinen Schlämme?",a="Klebrige Schlämme leben in der prähistorischen Wildnis des Kraters von Un'Goro, weit im Süden Kalimdors.",al={"wo reinen schlamm finden","fundort der gefäße für reine proben","wo sind reine schleime"}},{q="Wer ist Laris Bummelritzel?",a="Laris Bummelritzel ist ein gnomischer Forscher in Eisenschmiede. Er widmet sich der Erforschung des Wesens von Azeroths Schleimen und Schlämmen.",al={"wer ist laris","laris bummelritzel hintergrund"}},{q="Was macht Schlämme für Forscher so interessant?",a="Schlämme nehmen die magischen, umweltbedingten und verderbenden Eigenschaften ihrer Lebensräume auf und spiegeln sie wider.",al={"warum schleim erforschen","schlamm hintergrund"}},{q="Folgt dies auf eine frühere Aufgabe für Laris?",a="Ja. Laris bat zunächst um Schlämme für seine Forschung, doch diese Proben trugen die dämonische Verderbnis des Teufelswalds in sich. Nun sucht er unverdorbene Schleime.",al={"vorherige quest laris","was kam davor"}},{q="Was hat Laris mit den Proben vor?",a="Laris plant, reine Proben mit verdorbenen zu vergleichen. Er hofft zu erfahren, wie Veränderungen einer Umwelt Lebewesen und die übrige Bevölkerung Azeroths beeinflussen.",al={"laris schlammforschung","wofür wird schleim verwendet"}}},fx={d7a6aa80={q="Wofür ist das Mit einer reinen Probe gefülltes Glas?",a="Diese Gläser enthalten unverseuchten Schleim, der von Schlammwesen stammt, die in unberührter Wildnis leben. Laris Bummelritzel entdeckte, dass Schleime im Teufelswald die dämonische Verseuchung dieses Waldes annahmen, was enthüllt, dass Schlammwesen auf natürliche Weise die Eigenschaften ihrer Umgebung aufsaugen und widerspiegeln. Er benötigt Gläser mit reinem, nicht kontaminiertem Schleim, um als Grundlage für seine Forschung darüber zu dienen, wie sich diese Kreaturen anpassen und wie eine solche Verschmutzung Azeroth als Ganzes beeinflussen könnte.",al={"mit einer reinen probe gefülltes glas","zweck mit einer reinen probe gefülltes glas","wofür sind die probengläser"}},df064ff1={q="Was sind die reinen Schlammwesen, die Ihr finden sollt?",a="Ihr werdet entsandt, um Proben von glutinösen Schlammwesen zu ernten, die im urzeitlichen, ungezähmten Becken des Kraters von Un'Goro vorkommen. Anders als die Schleime im Teufelswald, die dämonische Korruption aufgenommen haben, leben die Schlammwesen von Un'Goro in einer blühenden, unberührten Wildnis. Da Schlammwesen die Essenz ihrer Umgebung annehmen, bieten diese Proben Laris den reinen, nicht verschmutzten Schleim, den er benötigt, um ihre Biologie zu verstehen, bevor äußere Fäulnis sie verändert.",al={"reine schleimwesen","welche schleimwesen sind rein","glutinöse schleimwesen"}}},fp="30,207,18.266.0,25.190.1,49.192.0,33.92.0,24.124.0,47.103.0,43.126.0,46.160.0"}
P.entries["quest:452"] = {n="Hinterhalt in Lohenscheit",s="In Lohenscheit wartet Todespirscherin Faerleia, während Arugals Rat die Verfluchten im Zaum hält. Die Verlassenen wollen seine Herrschaft über das Dorf brechen und seine Stellung in Burg Shadowfang schwächen.",h="In Lohenscheit wartet Todespirscherin Faerleia, während Arugals Rat die Verfluchten im Zaum hält.",kw={"arugal","todespirscherin faerleia","faerleia","lord mayor morrison","hinterhalt in lohenscheit","rat von lohenscheit","burg shadowfang","silberwald"},ang={["class:Rogue"]="Als Schurke kennt Ihr das Handwerk der Todespirscher: feindliche Festungen infiltrieren, auf der Lauer liegen und Befehlshaber in ihrem eigenen Machtzentrum ausschalten.",["faction:Horde"]="Als Mitglied der Horde schwächt Ihr Arugals Netzwerk und die Bedrohung für den Weg der Horde durch den Silberwald zu den südlichen Grenzen.",["race:Undead"]="Für die Verlassenen hilft die Sicherung des südlichen Silberwalds, die Grenzen von Unterstadt zu verteidigen. Arugals Speichellecker zu töten bringt sie der Einnahme von Lohenscheit näher."},sec={{t="Schlag gegen die Marionetten",b="Todespirscherin Faerleia wartet im Rathaus von Lohenscheit auf die örtlichen Anführer. Erzmagier Arugal widmet sich in Burg Shadowfang seinen finsteren Zaubereien und überlässt es dem Rat von Lohenscheit, unter den verfluchten Dorfbewohnern Ordnung zu halten. Faerleia plant, dem Rat einen Hinterhalt zu legen. Ohne dessen Vermittlung hoffen die Verlassenen, dass die Worgen in den Wäldern und auf den Dorfstraßen sich aus Arugals Kontrolle befreien."},{t="Ein Enthauptungsschlag",b="Der Hinterhalt trifft jedes amtierende Mitglied der Regierung von Lohenscheit, darunter Lord Mayor Morrison. Die Ratsmitglieder sterben beim Betreten ihres Sitzungssaals, und das Dorf verliert seine Anführer. Für Unterstadt ebnet das Gemetzel den Weg, Lohenscheit einzunehmen und Arugal in Burg Shadowfang zu belagern."}},faq={{q="Wer ist Todespirscherin Faerleia?",a="Todespirscherin Faerleia ist eine Agentin der Verlassenen bei den Todespirschern, der Spionage- und Attentätergilde der Verlassenen. Sie hat sich in Lohenscheit einen Stützpunkt geschaffen, um Angriffe gegen Arugals örtliche Unterstützer zu koordinieren.",al={"faerleia","todespirscherin faerleia","wer vergibt hinterhalt in lohenscheit"}},{q="Warum wollen die Verlassenen den Rat von Lohenscheit tot sehen?",a="Arugal verlässt sich auf den Rat, um die verfluchten menschlichen Dorfbewohner gefügig und unter Kontrolle zu halten. Die Verlassenen glauben, dass die Ermordung seiner Anführer Lohenscheit ins Chaos stürzen und die Worgen gegen Arugal aufbringen wird.",al={"warum rat von lohenscheit töten","aufgabe des rates von lohenscheit","geschichte des rates von lohenscheit"}},{q="Wer führt den Rat von Lohenscheit an?",a="Lord Mayor Morrison führt den Rat von Lohenscheit an. Vor dem Hinterhalt der Todespirscher kümmert er sich mit den Ratsherren Smithers, Thatcher und Brunswick um die Gemeindeangelegenheiten.",al={"lord mayor morrison","bürgermeister von lohenscheit","wer regiert lohenscheit"}},{q="Wo findet dieser Hinterhalt statt?",a="Der Hinterhalt findet im Rathaus von Lohenscheit im südlichen Silberwald statt, nur ein kurzes Stück die Straße von Burg Shadowfang hinab.",al={"hinterhalt in lohenscheit ort","wo ist faerleia","rathaus lohenscheit"}},{q="In welcher Beziehung steht der Rat zu Arugal?",a="Der Rat ist Arugals Sprachrohr in Verwaltungsangelegenheiten. Während er in Burg Shadowfang bleibt und finstere Experimente durchführt, verwaltet der Rat die Dorfbewohner, die sich im Schutz der Nacht in wilde Bestien verwandeln.",al={"arugals rat","arbeitet der rat für arugal","arugals kontrolle über lohenscheit"}},{q="Befreit der Tod des Rates Lohenscheit vom Fluch?",a="Nein. Der Tod des Rates beseitigt Arugals sterbliche Marionetten, hebt aber den Wolfsfluch der Dorfbewohner nicht auf. Die Verlassenen stehen danach einem Dorf voller feindseliger, unkontrollierter Monster gegenüber.",al={"ist lohenscheit geheilt","heilt der hinterhalt die worgen","fluch gebrochen lohenscheit"}}},fx={fc270bec={q="Gegen wen kämpft Ihr beim Hinterhalt in Lohenscheit?",a="Ihr kämpft gegen den Rat von Lohenscheit, angeführt von Lordbürgermeister Morrison zusammen mit Ratsmitgliedern wie Smithers, Thatcher und Brunswick. Sie regieren Lohenscheit unter dem Einfluss von Erzmagier Arugal und agieren als seine Marionettenverwalter, um die verfluchten, geistig verwirrten Dorfbewohner gefügig zu halten, während Arugal seine dunklen Machenschaften in Burg Shadowfang betreibt.",al={"mitglieder des rats von lohenscheit","wer ist das ziel hinterhalt in lohenscheit","gegen wen kämpft ihr hinterhalt in lohenscheit"}},abb7a8b1={q="Warum benötigt Todespirscherin Faerleia Eure Hilfe?",a="Todespirscherin Faerleia arbeitet tief hinter den feindlichen Linien in feindlichem Gebiet. Der Rat kehrt in Wellen zurück und bringt mehrere erfahrene Mitglieder mit, darunter Lordbürgermeister Morrison. So geschickt Faerleia auch als Attentäterin für die Dunkle Fürstin ist, sie kann es nicht mit dem gesamten Rat gleichzeitig aufnehmen, ohne überwältigt zu werden, was Euer Eintreffen entscheidend für den Erfolg des Hinterhalts macht.",al={"warum benötigt faerleia hilfe","warum ich hinterhalt in lohenscheit","warum kann faerleia es nicht allein tun"}}},fp="15,191,20.377.0,21.308.1,29.218.0,53.200.0,31.162.0,34.140.0,56.195.0,54.179.1"}
P.entries["quest:453"] = {n="Auf der Suche nach der Schattengestalt",s="Sven Yorgens Hof wurde verwüstet, und Auf der Suche nach der Schattengestalt führt nun zu dem Fremden, der von dort floh. Schankwart Smitts lenkt die Suche von Dunkelhain nach Westen in die heimgesuchten Wälder des Dämmerwalds.",h="Sven Yorgens Hof wurde verwüstet, und Auf der Suche nach der Schattengestalt führt nun zu dem Fremden, der...",kw={"dunkelhain","dämmerwald","auf der suche nach der schattengestalt","rabenflucht","scarlet raven tavern","sven yorgen","schankwart smitts"},ang={["class:Rogue"]="Als Schurke verlasst Ihr Euch auf scharfe Beobachtung und Fährtenlesen, um einem panischen Verdächtigen durch dichte, schattenverhangene Wälder zu folgen und Gerüchte von echten Spuren zu unterscheiden.",["faction:Alliance"]="Für die Allianz ist es wichtig, den Grund für Bibbers' Flucht zu erfahren, um die wachsende Finsternis zu verstehen, die die Südgrenze des Königreichs bedroht."},sec={{t="Einem Geist auf der Spur",b="Sven Yorgen fleht um Hilfe dabei, die Gestalt zu identifizieren, die von seinem verwüsteten Gehöft floh. Die Spur führt in die Scarlet Raven Tavern, wo Schankwart Smitts mehrere Hinweise gibt. Der Flüchtige war in Dunkelhain völlig fremd, nervös und zittrig und ließ die schwachen Laternen am Stadtrand hastig hinter sich. Er verschwand in der Wildnis im Westen."},{t="Bibbers entlarven",b="Bibbers wird zitternd inmitten der Gefahren des Dämmerwalds gefunden, nachdem die Spur des Fremden nach Westen führt. Als ihm das Tagebuch gezeigt wird, das auf dem verwüsteten Hof geborgen wurde, gesteht er, das zerfledderte Buch geschrieben zu haben. Bibbers ist ein verängstigter Zeuge, der vor den über die Region hereingebrochenen Schrecken floh, kein berechnender Bösewicht. Er deutet an, dass das Tagebuch nur einen Teil des Albtraums enthält."}},faq={{q="Wer ist die Schattengestalt?",a="Die Schattengestalt ist Bibbers, ein schreckhafter Wanderer, der über die düsteren Ereignisse rund um Sven Yorgens Hof schrieb, bevor er westwärts in die Wälder floh.",al={"identität der schattengestalt","wer ist bibbers","wer ist der fremde"}},{q="Wohin ging die Gestalt laut Schankwart Smitts?",a="Schankwart Smitts sagt, der Mann sei in Dunkelhain fremd und sichtlich verängstigt gewesen und nach Westen in die Wildnis geflohen.",al={"wohin ist er gegangen","wo ist bibbers","welcher weg führt nach westen"}},{q="Warum floh Bibbers von Svens Hof?",a="Bibbers wurde Zeuge der Schrecken, die Svens Hof heimsuchten, und floh um sein Leben, aus Angst, das Unheil, das Svens Familie vernichtete, würde ihn als Nächstes holen.",al={"warum floh bibbers","was geschah auf svens hof","warum hat bibbers angst"}},{q="Was ist das Buch, das auf Svens Hof gefunden wurde?",a="Das Buch, das auf Svens Hof gefunden wurde, ist ein Tagebuch, in dem Bibbers die unheilvollen Ereignisse vor dem Massaker festhielt. Bibbers gibt zu, dass es nur die halbe Geschichte erzählt.",al={"buch von svens hof","bibbers' tagebuch","was ist das tagebuch"}},{q="Wo ist Bibbers zu finden?",a="Bibbers befindet sich in der westlichen Wildnis des Dämmerwalds, nahe dem Lager von Rabenflucht, fern von Dunkelhain und den umherstreifenden Bestien des Waldes.",al={"bibbers' aufenthaltsort","wo ist bibbers im dämmerwald","bibbers' koordinaten"}},{q="Was geschieht, nachdem Bibbers gefunden wurde?",a="Nachdem Bibbers gestanden hat, das Tagebuch geschrieben zu haben, verfasst er einen vollständigen Bericht über die Geschehnisse und schickt Euch mit der Wahrheit zu Sven Yorgen zurück.",al={"was kommt als nächstes","nach dem finden von bibbers","wohin geht es als nächstes"}}},fx={["033a8771"]={q="Warum will Schankwart Smitts, dass Ihr die schattenhafte Gestalt findet?",a="Schankwart Smitts hat keine persönlichen Interessen an der Tragödie auf Svens Hof, aber er erkennt die Gefahr der Wildnis im Dämmerwald. Da er weiß, dass ein nervöser Fremder aus der Sicherheit von Dunkelhain floh und sich nach Westen in die von Bestien wimmelnden Wälder begab, hofft Smitts aufrichtig, dass der arme Kerl gefunden wird, bevor die Schrecken des Landes ihn zerfleischen.",al={"smitts motiv","warum schattenhafte gestalt finden","warum kümmert das smitts"}}},fp="26,196,23.347.0,17.349.1,26.144.2,49.113.0,41.137.1,38.152.2,27.130.0,35.146.1"}
P.entries["quest:454"] = {n="Nach dem Hinterhalt",s="Miran braucht eine Eskorte, um Sprengpulver zur südlichen Ausgrabungsstätte in Loch Modan zu bringen. Dunkeleisenzwerge haben den Versorgungstransport überfallen, und die Straße ist noch immer gefährlich.",h="Miran braucht eine Eskorte, um Sprengpulver zur südlichen Ausgrabungsstätte in Loch Modan zu bringen.",kw={"hinterhalt","sprengpulver","dunkeleisen","ausgrabung","huldar","loch modan","miran","saean"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr durch die Sicherung des Nachschubs in Loch Modan, die Forschung der League fortzuführen und die südlichen Pässe unter Kontrolle der Allianz zu halten.",["profession:Mining"]="Als Bergarbeiter wisst Ihr, dass Sprengpulver tiefe unterirdische Ausgrabungen vorantreibt, weshalb der Schutz dieser Fässer für jedes ernsthafte Bergbauvorhaben wichtig ist.",["race:Dwarf"]="Als Zwerg helft Ihr durch den Schutz von Eisenschmiedes Vorräten vor Dunkeleisensaboteuren, die Gebirgspässe und Bergbaubetriebe Eurer Heimat zu sichern."},sec={{t="Eine unterbrochene Versorgungslinie",b="Saean und seine Mitverschwörer griffen den Versorgungstransport an. Fässer wurden verstreut, und die Straße wurde gefährlich. Huldar bleibt zurück, um das dort verbliebene Pulver zu bewachen. Miran bereitet sich darauf vor, mit der nächsten Ladung weiterzuziehen, sodass die Versorgungslinie geteilt ist."},{t="Der Weg zur Ausgrabung",b="Die südliche Ausgrabungsstätte braucht Sprengpulver, um Gestein zu sprengen und Titanenrelikte freizulegen. Miran fürchtet einen weiteren Hinterhalt von den Bergrücken aus. Er sucht einen Begleiter, bevor er seine Fracht verlädt und aufbricht, vorbei an möglichen Fallen der Dunkeleisenzwerge."}},faq={{q="Wer sind Huldar und Miran?",a="Huldar und Miran sind zwergische Fuhrleute, die schwere Fässer mit Sprengpulver für örtliche Ausgrabungen durch Loch Modan transportieren.",al={"wer ist huldar","wer ist miran","pulverfuhrleute loch modan"}},{q="Warum können Huldar und Miran nicht gemeinsam reisen?",a="Huldar und Miran können nicht gemeinsam reisen, weil die Lieferung nach dem Hinterhalt ungeschützt war. Huldar blieb zurück, um die übrigen Fässer zu bewachen, während Miran mit der ersten Ladung weiterzog.",al={"warum aufteilen","warum pulver aufteilen"}},{q="Wer hat die Lieferung angegriffen?",a="Feindliche Dunkeleisenzwerge unter Saeans Führung überfielen die Fuhrleute. Sie wollen die Unternehmungen der Allianz stören und den Bergbausprengstoff erbeuten oder vernichten.",al={"wer hat sie überfallen","wer ist saean"}},{q="Wohin bringt Miran das Pulver?",a="Miran bringt die Fässer zur südlichen Ausgrabungsstätte in Loch Modan. Das Team von Ausgrabungsleiter Eisenband braucht dort Sprengpulver, um Gestein zu beseitigen und verschüttete Ruinen freizulegen.",al={"wohin kommt das pulver","mirans ziel"}},{q="Warum wird Sprengpulver in Loch Modan so streng bewacht?",a="Die Explorers' League braucht Sprengpulver für ihre Ausgrabungen, doch in den falschen Händen ist der Sprengstoff gefährlich. In der ganzen Region versuchen eingeschleuste Dunkeleisenzwerge, Vorräte zu sabotieren und Eisenschmiedes Kontrolle über das Gebiet zu schwächen.",al={"warum sprengpulver schützen","bedeutung des pulvers"}},{q="Was geschieht nach dem Gespräch mit Miran?",a="Nachdem Miran den Wagen und die Fracht überprüft hat, bittet er Euch, ihn entlang der Straße zu eskortieren, damit die Lieferung unversehrt die Ausgrabungsstätte erreicht.",al={"nächster schritt nach dem hinterhalt","was macht miran"}}},fx={f69f8c9d={q="Warum will Huldar, dass dies erledigt wird?",a="Huldar und Miran wurden beim Transport von Sprengpulver in einen Hinterhalt gelockt, was sie dazu zwang, ihre Verantwortlichkeiten aufzuteilen. Da Huldar zurückbleibt, um die verbleibenden Fässer vor weiterer Sabotage zu schützen, muss Miran die nächste Lieferung allein transportieren. Da Huldar weiß, dass Dunkeleisenzwerge aktiv die Straßen von Loch Modan belauern, weigert er sich, seinen Partner ohne Schutz in Gefahr laufen zu lassen.",al={"huldar motiv","warum miran helfen","warum miran eskortieren"}}},fp="16,166,23.237.0,19.246.0,25.119.0,43.186.0,26.145.0,33.168.0,56.232.0,36.131.0"}
P.entries["quest:4542"] = {n="Nachricht zum Freiwindposten",s="An den westlichen Zugängen zu Tausend Nadeln sendet Kriegerheld Mondhorn eine dringende Warnung zum Freiwindposten. Zentaurenüberfälle nehmen zu, und er berichtet von seltsamem Verhalten unter den Grimmtotem.",h="An den westlichen Zugängen zu Tausend Nadeln sendet Kriegerheld Mondhorn eine dringende Warnung zum...",kw={"kriegerheld mondhorn","zentauren","klippenbehüter langhorn","freiwindposten","grimmtotem","nachricht zum freiwindposten","tausend nadeln","dringende nachricht"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass der Freiwindposten die Wege durch Tausend Nadeln verbindet. Ein ungehinderter Nachrichtenaustausch zwischen den Wachen der Außenposten und den Anführern der Siedlungen hilft, die Handelswege durch die Wüste zu sichern.",["race:Tauren"]="Als Tauren kennt Ihr die Zentauren als erbitterte Erbfeinde. Mondhorns Warnung zeigt, dass sie noch immer auf Kalimdors Wegen jagen, während die Spannungen mit den zurückgezogen lebenden Grimmtotem schwelen."},sec={{t="Eine Warnung durch die Schlucht",b="Kriegerheld Mondhorn bewacht die westlichen Zugänge zu Tausend Nadeln. Die Angriffe der Zentauren haben stark zugenommen, und die Grenzwachen müssen ihre Anführer warnen. Deshalb bittet Mondhorn Euch, eine Depesche nach Südosten zu Klippenbehüter Langhorn zu bringen, dem Kommandanten der Siedlung auf dem Tafelberg am Freiwindposten."},{t="Wachsende Gefahren und Unruhe unter Verwandten",b="Klippenbehüter Langhorn bestätigt, dass Zentauren kürzlich eine Versorgungskarawane abgefangen und ihre Angehörigen niedergemetzelt haben. Der Freiwindposten muss sich verteidigen und auf den Angriff reagieren. Mondhorn warnt Euch auch davor, Euch den benachbarten Grimmtotem-Tauren zu nähern. Ihr seltsames, feindseliges Verhalten deutet auf wachsende Zwietracht in den trockenen Ebenen hin."}},faq={{q="Wer schickt die Nachricht zum Freiwindposten?",a="Kriegerheld Mondhorn, ein Späher der Tauren, bewacht den westlichen Zugang zu Tausend Nadeln und gibt Euch die dringende Nachricht zur Überbringung.",al={"questgeber","wer startet nachricht zum freiwindposten","kriegerheld mondhorn"}},{q="Wer erhält die dringende Nachricht?",a="Klippenbehüter Langhorn erhält die Nachricht am Freiwindposten, der Siedlung auf dem Tafelberg südöstlich des Großen Aufzugs.",al={"wo abgeben","klippenbehüter langhorn standort","anführer des freiwindpostens"}},{q="Was steht in der dringenden Nachricht?",a="Die Nachricht warnt davor, dass Angriffe der Zentauren und Übergriffe auf Karawanen entlang der Wege dort unten stark zugenommen haben.",al={"nachrichteninhalt","worum geht es in der nachricht"}},{q="Warum macht sich Kriegerheld Mondhorn Sorgen um die Grimmtotem?",a="Mondhorn sagt, die benachbarten Grimmtotem hätten sich seltsam verhalten und Abstand zu anderen Tauren gehalten. Er rät Euch, sie zu meiden.",al={"warnung vor den grimmtotem","warum die grimmtotem meiden"}},{q="Was geschieht, nachdem Langhorn die Nachricht gelesen hat?",a="Nachdem Klippenbehüter Langhorn erfahren hat, dass Zentauren die Angehörigen einer Versorgungskarawane niedergemetzelt haben, befiehlt er in der Folgequest Pacify the Centaur einen Gegenangriff auf sie.",al={"nächste quest","nach nachricht zum freiwindposten"}},{q="Wie erreicht Ihr den Freiwindposten vom Schluchtboden aus?",a="Folgt vom Schluchtboden aus der Hauptstraße nach Osten bis zum Fuß des nadelförmigen Tafelbergs. Nehmt dann den hölzernen Plattformaufzug hinauf zum Dorf.",al={"weg zum freiwindposten","wie zum freiwindposten hinaufkommen"}}},fx={["65381134"]={q="Warum will Kriegerheld Mondhorn, dass die Nachricht an den Freiwindposten überbracht wird?",a="Zentaurenangriffe im Canyon haben zugenommen und bringen Reisende, Karawanen und Außenposten in unmittelbare Gefahr. Kriegerheld Mondhorn, der am Großen Aufzug stationiert ist, erlebt die eskalierende Gewalt aus erster Hand und weiß, dass Klippenbehüter Langhorn und die Garnison oben auf dem Freiwindposten eine Vorwarnung benötigen, um die Verteidigung zu organisieren und lebenswichtige Versorgungswege zu schützen.",al={"warum nachricht an freiwindposten senden","kriegerheld mondhorn motiv","warum langhorn warnen"}},c67c7dfd={q="Warum benötigt Kriegerheld Mondhorn einen Abenteurer, um die Nachricht zu überbringen?",a="Kriegerheld Mondhorn ist als Wache stationiert, die die lebenswichtige Grenze am Großen Aufzug zwischen dem Brachland und Tausend Nadeln hält. Da die Zentaurenüberfälle eskalieren und der benachbarte Grimtotem-Clan sich verdächtig verhält, kann Mondhorn seinen Wachposten nicht verlassen, ohne den Aufzug ungeschützt zu lassen, was einen fähigen Reisenden zur besten Wahl macht, um die Depesche zu überbringen.",al={"warum kann mondhorn nicht übermitteln","warum ich nachricht an freiwindposten","warum benötigt mondhorn hilfe"}}},fp="24,176,25.277.0,28.299.0,39.119.0,32.109.0,36.108.0,50.128.0,46.153.0,53.134.0"}
P.entries["quest:455"] = {n="Der Algaz-Spießrutenlauf",s="Bei Dun Algaz haben Orcs den Pass zwischen Loch Modan und dem Sumpfland besetzt. Die Dragonmaw bedrohen Eisenschmiedes Verbindung zum Hafen von Menethil, weshalb Gebirgsjäger Rockgar Reisende der Allianz aussendet, sie anzugreifen und Valstag Eisenkiefer Bericht zu erstatten.",h="Bei Dun Algaz haben Orcs den Pass zwischen Loch Modan und dem Sumpfland besetzt.",kw={"dragonmaw","dun algaz","loch modan","hafen von menethil","pass","rockgar","valstag eisenkiefer","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz ist der Hafen von Menethil Euer wichtigstes Tor zwischen den Östlichen Königreichen und den westlichen Landen. Den Landweg offen zu halten, ist für die gesamte Allianz wichtig.",["race:Dwarf"]="Als Zwerg schützt Ihr durch die Befreiung von Dun Algaz die angestammten Gebirgspässe von Khaz Modan und haltet den Weg zwischen Eisenschmiede und seinem westlichen Seehafen offen."},sec={{t="Eine durchtrennte Lebensader",b="Zerklüftete Felsen trennen Loch Modan vom Sumpfland, und Dun Algaz ist der Weg hinüber. Es ist der einzige Gebirgspass auf dem Landweg zwischen ihnen, und Eisenschmiede braucht ihn für Handel, Truppenbewegungen und Nachschub zum Hafen von Menethil, dem wichtigsten Küstenhafen der Allianz in der Region.\n\nFällt der Pass, verliert Eisenschmiede seinen Zugang zu den westlichen Meeren. Auch abgelegene Außenposten wären von zwergischer Verstärkung abgeschnitten."},{t="Der Vorstoß der Dragonmaw",b="Überreste des Dragonmaw-Klans suchen seit dem Zweiten Krieg die Hügel und Ruinen des Sumpflands heim. Nun sind sie mit einem organisierten Angriff nach Dun Algaz vorgestoßen, haben die Tunnel eingenommen und den Pass mit ihren Spähern und Grunts befestigt.\n\nGebirgsjäger Rockgar bittet Reisende der Allianz, die Orcs zu töten und Valstag Eisenkiefer im Hafen von Menethil Nachricht von dem Angriff zu bringen."}},faq={{q="Warum ist Dun Algaz für die Allianz so wichtig?",a="Dun Algaz ist der einzige direkte Gebirgsweg zwischen Loch Modan und dem Sumpfland. Er verbindet das Herz von Khaz Modan mit dem Hafen von Menethil, dem wichtigsten Hafen der Allianz für Seereisen.",al={"warum dun algaz wichtig ist","bedeutung von dun algaz","warum den pass freikämpfen"}},{q="Wer sind die Orcs des Dragonmaw-Klans, die den Pass besetzen?",a="Die Dragonmaw sind Überreste der Old Horde, bekannt dafür, während des Zweiten Krieges rote Drachen versklavt zu haben. Nach ihrer Niederlage zogen sich versprengte Gruppen ins Sumpfland zurück. Nun sind sie nach Süden in den Pass vorgestoßen, um dessen strategische Engstellen einzunehmen.",al={"wer sind die dragonmaw","warum sind orcs in dun algaz","geschichte des dragonmaw-klans"}},{q="Wohin führt diese Mission?",a="Nachdem Ihr Euch durch den Pass gekämpft und die Grunts und Späher getötet habt, führt der Weg nach Norden durch das Sumpfland. Nehmt an der Weggabelung die westliche Straße zum Hafen von Menethil und erstattet Valstag Eisenkiefer Bericht.",al={"wohin nach dem algaz-spießrutenlauf","wer erhält den bericht","wo ist valstag eisenkiefer"}},{q="Warum ist Valstag Eisenkiefer von dem Bericht überrascht?",a="Die Dragonmaw bleiben gewöhnlich in verborgenen Lagern in den sumpfigen Hügeln des Sumpflands. Ihr kühner Vorstoß in die zwergischen Tunnel von Dun Algaz zeigt eine unerwartete Hinwendung zu organisierten Angriffen.",al={"valstags reaktion","warum griffen die orcs algaz an"}},{q="Wer befiehlt den Angriff auf den Pass?",a="Gebirgsjäger Rockgar, ein zwergischer Wachposten an der Nordgrenze von Loch Modan, befiehlt den Angriff. Er will verhindern, dass die Orcs ihre Stellung sichern und die Verbindung zur Küste abschneiden.",al={"wer gibt die quest","mission von gebirgsjäger rockgar"}},{q="Was folgt nach dem Abschluss dieses Spießrutenlaufs?",a="Euer Bericht an Valstag Eisenkiefer warnt die Garnison im Hafen von Menethil vor der unmittelbaren Bedrohung. Er eröffnet weitere Möglichkeiten, die zwergische Verteidigung gegen die Dragonmaw im Sumpfland zu unterstützen.",al={"nächste quest nach dem algaz-spießrutenlauf","was in menethil tun"}}},fx={["5ee6c7e9"]={q="Warum will Gebirgsjäger Rockgar, dass dies erledigt wird?",a="Gebirgsjäger Rockgar fürchtet, den lebenswichtigen Gebirgskorridor zu verlieren, der Loch Modan mit dem Sumpfland verbindet. Drachenmalorks sind aus ihrem Sumpfzufluchtsort hervorgebrochen und haben Dun Algaz besetzt, was droht, die Kommunikations- und Versorgungswege zwischen den Zwergengebieten im Landesinneren und dem Hafen von Menethil abzuschneiden. Indem er Euch schickt, um ihre Späher und Grunts niederzustrecken, hofft Rockgar, ihren Schwung zu bremsen, ihren Griff auf die Tunnel zu brechen und den Verteidigern des Hafens kritische Nachrichten über den Einfall zu übermitteln.",al={"rockgar motiv","warum dun algaz säubern","warum schickt euch rockgar"}}},fp="18,235,16.406.0,19.354.0,46.175.0,46.245.0,29.192.0,47.187.0,35.189.0,42.182.0"}
P.entries["quest:456"] = {n="Das Gleichgewicht der Natur",s="In Laubschattental ruft Konservator Ilthalaine neu erwachte Nachtelfen dazu auf, sich um Teldrassils Tierwelt zu kümmern. Junge Säblerkatzen und Disteleber sind zu zahlreich geworden, und das Gleichgewicht der Natur zu wahren erfordert Fürsorge und schwierige Entscheidungen.",h="In Laubschattental ruft Konservator Ilthalaine neu erwachte Nachtelfen dazu auf, sich um Teldrassils Tierwelt...",kw={"aldrassil","das gleichgewicht der natur","ilthalaine","kaldorei","säblerkatze","laubschattental","teldrassil","disteleber"},ang={["class:Druid"]="Als angehender Druide lernt Ihr die harten Realitäten der Cenarion-Fürsorge kennen. Die Wildnis zu schützen kann bedeuten, Blut zu vergießen, um das Ganze zu retten.",["class:Hunter"]="Als Jäger beginnt Ihr zu lernen, aggressive Wildtiere aufzuspüren und ihre Bestände auszudünnen. Dies ist eine Grundlage für die Verbundenheit mit den Tieren Kalimdors.",["race:NightElf"]="Als Nachtelf macht Ihr Euren ersten Schritt auf dem Weg zu einem erwachsenen Beschützer der Kaldorei. Das Gleichgewicht der Natur zu wahren erfordert tatkräftige Fürsorge und Respekt."},sec={{t="Eine empfindliche Harmonie",b="Heftige Frühlingsregen haben Teldrassils jungen und empfindlichen Waldkreislauf in Laubschattental unter den Ästen des Großen Baumes gestört. Einige Tierbestände sind über das hinaus angewachsen, was das Land ernähren kann. Sie drohen, das Tal seiner Ressourcen zu berauben und eine Hungersnot im Ökosystem auszulösen. Den Wald zu bewahren erfordert tatkräftige Fürsorge."},{t="Der Ruf des Konservators",b="Konservator Ilthalaine wacht über die Wälder von Laubschattental, damit kein Teil die anderen überwuchert. Um ein massenhaftes Verhungern unter den Tieren zu verhindern, schickt er junge Nachtelfen in den Hain, um Disteleber und räuberische Säblerkatzen auszudünnen. Die Arbeit ist wenig ruhmreich, aber lebenswichtig. Die Fürsorge der Kaldorei strebt durch das aktive Wahren des Gleichgewichts und schwierige Entscheidungen nach Harmonie mit der Natur."}},faq={{q="Warum müssen die Säblerkatzen und Eber getötet werden?",a="Heftige Frühlingsregen haben jungen Säblerkatzen und Distelebern geholfen, sich stark zu vermehren. Laubschattental kann nur eine begrenzte Zahl an Wildtieren ernähren. Ihre übermäßig angewachsenen Bestände drohen, die Nahrung im Hain aufzuzehren, sodass sie selbst und andere Geschöpfe verhungern.",al={"warum eber töten","warum säblerkatzen töten","grund für das gleichgewicht der natur"}},{q="Wer ist Konservator Ilthalaine?",a="Konservator Ilthalaine ist ein Wächter der Kaldorei, der in Laubschattental stationiert ist. Seine geschworene Pflicht ist es, über die Tier- und Pflanzenwelt des Hains zu wachen, damit die Harmonie der Natur gewahrt bleibt.",al={"wer ist ilthalaine","questgeber","geschichte von konservator ilthalaine"}},{q="Wo findet diese Quest statt?",a="Dies spielt im abgeschiedenen Laubschattental, einer Waldenklave zwischen Teldrassils Ästen. Teldrassil, der Weltbaum, liegt vor der Küste des nördlichen Kalimdor.",al={"questort","wo ist laubschattental","startgebiet nachtelf"}},{q="Was folgt nach Abschluss dieser Aufgabe?",a="Nach diesem ersten Teil der Bestandsausdünnung schickt Ilthalaine Euch los, um den zweiten Teil auszuführen. Er gibt Euch außerdem ein klassenspezifisches Siegel, das Euch zu Eurem ersten Lehrer in Aldrassil führt.",al={"folgequest","nächste quest in der reihe"}}},fx={["3ad6c91a"]={q="Welche Bestien sollt Ihr jagen?",a="Ihr werdet gegen die jungen Nachtsäbler und jungen Disteleber ausgesandt, die in den umliegenden Wäldern des Laubschattentals umherstreifen. Sie sind einheimische Tierwelt des großen Weltenbaums Teldrassil. Nach ungewöhnlich starken Frühlingsregen sind beide Populationen explosionsartig gewachsen, was droht, das Tal der Nahrung zu berauben und das lokale Waldgebiet ins Chaos zu stürzen.",al={"was sind nachtsäbler und eber","wen jagt ihr im laubschattental","junge nachtsäbler junge disteleber"}}},fp="21,239,18.325.0,22.356.0,51.223.0,30.173.0,33.157.0,43.181.0"}
P.entries["quest:457"] = {n="Das Gleichgewicht der Natur",s="In Laubschattental schickt Konservator Ilthalaine Verteidiger aus, um die wachsenden Tierbestände zu verringern. Ausgewachsene Disteleber und räudige Nachtsäbler bedrohen das Gleichgewicht der Lichtung.",h="In Laubschattental schickt Konservator Ilthalaine Verteidiger aus, um die wachsenden Tierbestände zu...",kw={"aldrassil","gleichgewicht der natur","bestände verringern","ilthalaine","räudiger nachtsäbler","laubschattental","teldrassil","disteleber"},ang={["class:Druid"]="Als Druide lernt Ihr, dass Harmonie harte Entscheidungen verlangt. Zu groß gewordene Rudel auszudünnen bewahrt das große Netz des Lebens.",["class:Hunter"]="Als Jäger lernt Ihr, flinke Säbler und störrische Eber aufzuspüren und ihre Bestände zu verringern. Diese Fähigkeiten helfen, die Natur im Gleichgewicht zu halten.",["race:NightElf"]="Für junge Nachtelfen ist dies eine frühe Lektion über die harten Anforderungen, die die Pflege der Wildnis auf Teldrassil mit sich bringt."},sec={{t="Die Bürde der Fürsorge",b="Erwachsene Tiere bedrohen nun Laubschattental und das Ökosystem des Weltbaums. Konservator Ilthalaine schickt junge Verteidiger tiefer in den Wald, um ausgewachsene Disteleber und ältere, räudige Nachtsäbler zu jagen. Ihr Appetit kann die begrenzten Pflanzen- und Wildbestände des Landes erschöpfen."},{t="Jäger und Beute",b="Nördlich von Aldrassil weichen jüngere Jungtiere gefleckten Nachtsäblern und aggressiven Ebern, die den Boden durchwühlen. Für die Kaldorei ist die kontrollierte Jagd eine düstere Pflicht. Sie schützt den gesamten Wald vor dem Zusammenbruch."}},faq={{q="Warum lässt Konservator Ilthalaine diese Tiere töten?",a="Ohne Eingreifen könnten die wachsenden Bestände an Distelebern und Nachtsäblern Laubschattental lebenswichtiger Ressourcen berauben. Das Land würde veröden und könnte auf Teldrassils Ästen kein Leben mehr erhalten.",al={"warum eber und säbler töten","warum gleichgewicht der natur","grund für die jagd"}},{q="Wo befinden sich die räudigen Nachtsäbler und Disteleber?",a="Räudige Nachtsäbler und Disteleber streifen durch das nördliche Laubschattental, jenseits von Aldrassils Ästen. Achtet bei den Nachtsäblern auf geflecktes Fell; jüngere Jungtiere näher am Heiligtum haben Streifen.",al={"wo sind räudige nachtsäbler","disteleber fundort","wo sie zu finden sind"}},{q="Wer ist Konservator Ilthalaine?",a="Konservator Ilthalaine kümmert sich um Laubschattental und wacht über das Wohlergehen der Lichtung, auf der die Reise auf Teldrassil beginnt. Sie leitet frisch erwachte Nachtelfen dabei an, den Wald im Gleichgewicht zu halten.",al={"wer ist ilthalaine","konservator ilthalaine hintergrundgeschichte"}},{q="Wie passt das zu den Glaubensvorstellungen der Nachtelfen über die Natur?",a="Nachtelfen ehren die Natur, und Fürsorge bedeutet, übermäßige Vermehrung einzudämmen. Wenn eine Art zu zahlreich wird und andere verdrängt und aushungert, leidet der ganze Wald. Bestände zu verringern ist eine schmerzliche, aber lebenswichtige Pflicht.",al={"naturglaube der nachtelfen","warum druiden tiere töten","kaldorei gleichgewicht"}},{q="Ist dies das Ende der Questreihe „Das Gleichgewicht der Natur“?",a="„Das Gleichgewicht der Natur“ hat in seiner ursprünglichen Questreihe einen zweiten und letzten Schritt. Weitere Aufgaben befassen sich bald mit der tiefer gehenden, widernatürlicheren Verderbnis, die Teldrassils Tierwelt plagt.",al={"geht das gleichgewicht der natur weiter","was kommt nach dem gleichgewicht der natur"}},{q="Warum werden die Nachtsäbler als räudig beschrieben?",a="Ältere, mitgenommenere Nachtsäbler streifen an den Rändern der Lichtung umher, wo ihre große Zahl Laubschattentals Nahrungsvorräte belastet. Viele werden struppig und aggressiv.",al={"warum räudig","was stimmt mit den säblern nicht"}}},fx={af153fa8={q="Warum werdet Ihr gegen räudige Nachtsäbler und Disteleber ausgesandt?",a="Diese Nachtsäbler und Disteleber bevölkern die nördlichen Ausläufer von Laubschattental. Wenn ihre Anzahl nicht kontrolliert wird, drohen sie, dem Wald seine begrenzte Nahrung zu entziehen. Konservator Ilthalaine beauftragt Euch damit, sie auszudünnen, damit die lokale Flora und andere Waldbewohner überleben können.",al={"warum nachtsäbler und eber töten","räudige nachtsäbler disteleber zweck","ziel nachtsäbler und eber"}},["2a769140"]={q="Warum bittet Konservator Ilthalaine Euch und nicht die Wächterinnen?",a="Laubschattental ist ein Zufluchtsort für die Ausbildung junger Nachtelfen in ihrem Erbe, ihrer Pflicht und ihrer Kampfkunst. Ilthalaine überträgt Euch die Aufgabe, die einheimische Tierwelt zu verwalten, nicht nur, um die Last für die Waldwächter und Wächterinnen zu verringern, sondern auch, um Eure Hingabe für den Schutz des Landes und seiner Harmonie zu prüfen.",al={"warum braucht ilthalaine mich","warum keine wächterinnen","warum abenteurer gleichgewicht der natur"}}},fp="21,156,23.260.0,17.204.0,57.194.0,58.180.0,30.171.0,54.193.0,47.168.0,43.139.0"}
P.entries["quest:458"] = {n="Die Beschützerin des Waldlandes",s="In Laubschattental hört Melithar Hirschhaupt beunruhigendes Flüstern von den Waldgeistern. Er bittet Euch, Tarindrella aufzusuchen, deren Rückkehr nach Teldrassil nach vielen Jahren fern von Kalimdors Wäldern darauf hindeutet, dass etwas nicht stimmt.",h="In Laubschattental hört Melithar Hirschhaupt beunruhigendes Flüstern von den Waldgeistern.",kw={"aldrassil","dryade","melithar hirschhaupt","laubschattental","tarindrella","teldrassil","beschützerin des waldlandes"},ang={["class:Druid"]="Als Druide schätzt Ihr Dryaden als Verwandte in der Natur hoch. Tarindrellas Anwesenheit ruft Euch früh dazu auf, auf das Gleichgewicht des Smaragdgrünen Traums und der Wälder zu achten.",["race:NightElf"]="Als junger Nachtelf, der Aldrassil verlässt, begegnet Ihr einer von Cenarius' Töchtern und übernehmt Eure erste unmittelbare Pflicht, die Harmonie in Eurem jungen Weltenbaum zu bewahren."},sec={{t="Flüstern im Tal",b="Unter Aldrassils Ästen bildet Melithar Hirschhaupt Novizen aus und vernimmt beunruhigende Omen von den Waldgeistern. Tarindrella, eine als Beschützerin der Wildnis bekannte Dryade, ist nach vielen Jahren fern von Kalimdors Wäldern nach Laubschattental zurückgekehrt. Dryaden kommen selten ohne Grund, weshalb Melithar fürchtet, dass die natürliche Ordnung aus dem Gleichgewicht geraten ist."},{t="Die Dryade suchen",b="Ein Spähbericht der Schildwachen weist neu erwachten Verteidigern den Weg südwestlich von Aldrassil in die umliegenden Wälder. Dort könnt Ihr Tarindrella finden. Cenarius' Tochter ist zurückgekehrt, um sich einer Verderbnis anzunehmen, die den Grabhügel und die nahen Lichtungen befällt."}},faq={{q="Wer vergibt diese Quest?",a="Melithar Hirschhaupt, ein Nachtelfendruide auf Aldrassils unteren Plattformen in Laubschattental, bittet neu erwachte Abenteurer um Hilfe.",al={"questgeber","wer vergibt die quest","melithars quest"}},{q="Wo kann ich Tarindrella finden?",a="Ihr findet Tarindrella an den bewaldeten Pfaden von Laubschattental, im Wald südwestlich von Aldrassil.",al={"tarindrellas standort","wo ist tarindrella","dryade finden"}},{q="Wer ist Tarindrella?",a="Tarindrella ist eine Dryade und eine von Cenarius' unsterblichen Töchtern. Dryaden werden als Beschützerinnen des Waldlandes verehrt, sind eng mit dem Wohlergehen des Waldes verbunden und greifen selten direkt ein, sofern der Natur keine erhebliche Gefahr droht.",al={"wer ist tarindrella","tarindrellas geschichte","dryade laubschattental"}},{q="Warum beunruhigt Melithar ihre Rückkehr?",a="Tarindrella war seit Jahren nicht mehr in Kalimdors Wäldern zugegen. Ihre plötzliche Rückkehr zu Teldrassils neu gewachsenen Ästen deutet darauf hin, dass im Hain etwas nicht stimmt.",al={"warum ist melithar besorgt","melithar hirschhaupts sorge"}},{q="Was geschieht, nachdem ich Tarindrella gefunden habe?",a="Ein Gespräch mit Tarindrella schließt den Botengang ab und führt zu ihrer Bitte um Hilfe. Sie bittet Euch, verderbte Pflanzen und Tiere in Laubschattental zu untersuchen.",al={"nächste quest","was kommt als nächstes","tarindrellas folgequest"}},{q="Ist Melithar Hirschhaupt mit Erzdruide Fandral Hirschhaupt verwandt?",a="Melithar trägt denselben Nachnamen wie Erzdruide Fandral Hirschhaupt, der Anführer der Nachtelfendruiden in Darnassus, doch eine Verwandtschaft zwischen ihnen ist nicht bekannt. Melithar unterweist Neulinge in Laubschattental.",al={"melithar fandral verwandtschaft","ist melithar hirschhaupt verwandt"}}},fx={["47512ade"]={q="Warum schickt Melithar Hirschhaupt einen Abenteurer, anstatt sich selbst darum zu kümmern?",a="Melithar Hirschhaupt kümmert sich um Aldrassil und die empfindsamen Geister von Laubschattental, wo seltsame Nachrichten und wachsende Unruhe die Druiden und Wächterinnen wachsam halten. Als die Nachricht eintraf, dass die zurückgezogen lebende Dryade Tarindrella plötzlich aufgetaucht war, benötigte Melithar einen fähigen, diskreten Boten, um sie südwestlich der Zweige aufzusuchen, ohne seinen Posten im Tal verlassen zu müssen.",al={"warum schickt ihr mich","warum geht melithar nicht","warum braucht melithar mich"}}},fp="22,223,20.350.0,17.237.1,22.126.0,29.97.0,19.221.0,43.180.0,39.150.0,59.198.0"}
P.entries["quest:4581"] = {n="Kayneth Stillwind",s="In Eschental schickt Schildwache Shindrell Feuerflink einen Spähbericht von Astranaar nach Osten. Druide Kayneth Stillwind braucht Hilfe dabei, die Ausbreitung der Verderbnis in den uralten Wäldern zu beobachten.",h="In Eschental schickt Schildwache Shindrell Feuerflink einen Spähbericht von Astranaar nach Osten.",kw={"eschental","astranaar","verderbnis","druide","forest song","kayneth stillwind","nightsongwälder","shindrell feuerflink"},ang={["class:Druid"]="Als Druide folgt Ihr einer Berufung, indem Ihr Kayneth Stillwind und dem Zirkel des Cenarius helft, Eschental von der sich ausbreitenden dämonischen und elementaren Verderbnis zu heilen.",["faction:Alliance"]="Als Reisender der Allianz helft Ihr, die Nachrichtenwege und die Verteidigung in Eschental aufrechtzuerhalten, von seiner Mitte bis zu den östlichen Nightsongwäldern, gegen Gefahren der Wildnis und Vorstöße der Horde.",["race:NightElf"]="Als Nachtelf teilt Ihr die Pflicht der Schildwachen, die Nachrichtenwege zwischen Astranaar und entlegenen Stützpunkten wie Forest Song offenzuhalten."},sec={{t="Eine Depesche nach Osten",b="In Astranaar wacht Schildwache Shindrell Feuerflink über das westliche Eschental. Kayneth Stillwind, ein Druide in Forest Song im östlichen Wald, hat sie gebeten, die Sicherheit der Region einzuschätzen. Veränderungen in der Tierwelt und finstere Omen entlang der Küsten und in den Wäldern beunruhigen ihn. Also versiegelt Feuerflink ihre Beobachtungen in einer Notiz und vertraut sie einem Reisenden an, der den gefährlichen mittleren Teil des Waldes durchquert."},{t="Wächter in Forest Song",b="Der Weg nach Forest Song führt durch die Nightsongwälder, wo Satyren vordringen, Wildtiere feindselig werden und die Horde von Süden her vorstößt. Am Schrein untersucht Kayneth Stillwind das Gleichgewicht der Naturgeister Eschentals. Feuerflinks Bericht bestätigt seine Befürchtung: Verderbnis breitet sich im Wald aus, weder auf einen Ort begrenzt noch rasch vorübergehend. Die Druiden brauchen mehr Hilfe, um dem Bösen entgegenzutreten, das Wurzeln schlägt."}},faq={{q="Wo befindet sich Kayneth Stillwind?",a="Kayneth Stillwind befindet sich in Forest Song, einem Heiligtum der Nachtelfen in den Nightsongwäldern, weit im Osten Eschentals und nördlich der Hauptstraße.",al={"wo ist kayneth","kayneth stillwind standort","kayneth stillwind finden"}},{q="Wer vergibt diese Quest?",a="Schildwache Shindrell Feuerflink bietet sie in Astranaar an, der Nachtelfensiedlung im westlichen Eschental.",al={"questgeber","wer startet kayneth stillwind","wo anfangen"}},{q="Was steht in Shindrells Notiz?",a="Shindrells Notiz berichtet über die Sicherheitslage entlang der Westküste Eschentals und in den Wäldern um Astranaar. Der Bericht hilft Kayneth Stillwind, die unnatürliche Verderbnis im Wald zu untersuchen.",al={"shindrells notiz inhalt","was hat shindrell geschrieben","shindrell notiz"}},{q="Warum untersucht Kayneth Stillwind den Wald?",a="Kayneth Stillwind befürchtet, dass sich Böses in Eschental ausbreitet. Als Druide bittet er um Berichte der Schildwachen, um zu erfahren, wo es Fuß fasst, und das Gleichgewicht der Natur zu bewahren.",al={"warum kümmert sich kayneth darum","kayneth stillwind beweggrund","druide verderbnis"}},{q="Ist Forest Song für Reisende der Allianz sicher?",a="Forest Song ist ein friedlicher Zufluchtsort der Allianz mit freundlichen Schildwachen und Druiden. Feindselige Tiere und verderbte Satyren bedrohen die umliegenden Nightsongwälder und machen die Reise gefährlich.",al={"ist forest song sicher","allianz siedlung forest song","forest song wachen"}},{q="Was geschieht nach der Übergabe der Notiz?",a="Nachdem er Shindrells Bericht geprüft hat, untersucht Kayneth die Verderbnis des Waldes und wirbt Reisende an, gegen die verderbten Mächte vorzugehen, die die Region bedrohen.",al={"what comes next","folgequest","kayneth fortsetzung"}}},fx={["20722aea"]={q="Warum möchte Shindrell Feuerflink, dass dieser Bericht übermittelt wird?",a="Kayneth Stillwind wandte sich an Shindrell, um einen formellen Bericht über die jüngsten Vorkommnisse entlang der Küste und in den Wäldern rund um Astranaar zu erbitten. Shindrell teilt die wachsende Sorge des Druiden, dass eine üble Verderbnis durch das Eschental kriecht. Indem sie ihre Beobachtungen zusammenstellt und an Forest Song schickt, hofft sie, Kayneth dabei zu helfen, die Quelle dieser sich ausbreitenden Bosheit zu finden.",al={"warum bericht an kayneth","shindrell feuerflink motiv","warum shindrells notiz überbringen"}}},fp="17,176,22.385.0,23.413.0,35.128.0,21.101.0,28.182.0,50.168.0,43.185.0,39.161.0"}
P.entries["quest:459"] = {n="Die Beschützerin des Waldlandes",s="Im Laubschattental sucht Tarindrella nach der Ursache für die Unruhe im Wald und das Verschwinden der Furbolgs. Grells sind aggressiv geworden, und Teufelsmoos deutet auf dunkle Magie in Teldrassils Ästen hin.",h="Im Laubschattental sucht Tarindrella nach der Ursache für die Unruhe im Wald und das Verschwinden der...",kw={"athridas bearmantle","teufelsmoos","gnarlpine","grell","grellkin","laubschattental","tarindrella","teldrassil"},ang={["class:Druid"]="Als Druide verbindet Euch ein heiliges Band mit den Geistern des Waldes und den Dryaden. Indem Ihr verderbtes Teufelsmoos untersucht, helft Ihr, die geistige Krankheit zu erkennen, die den Weltbaum befällt.",["race:NightElf"]="Als junger Kaldorei, der von Aldrassil aufbricht, lernt Ihr, dass Verderbnis Eure heilige neue Heimat von innen bedrohen kann."},sec={{t="Verderbnis in der Lichtung",b="Die stillen Wälder des Laubschattentals sind feindselig geworden. Die Furbolgs haben ihre angestammten Höhlen verlassen und sich zum Gnarlpine-Stamm zusammengeschlossen. Wilde Grells und Grellkin überrennen die Waldpfade, und Tarindrella sieht, wie sich der finstere Wandel in Teldrassil ausbreitet."},{t="Verderbter Bewuchs",b="Tarindrella vermutet, dass Verderbnis die Geschöpfe des Waldes aufwiegelt. Ihr erschlagt die Grells und bringt ihr Proben von Teufelsmoos als Beweis für dunkle Verzauberungen, die an Teldrassils Ästen haften. Nachdem die Verderbnis bestätigt ist, schickt sie junge Verteidiger nach Dolanaar, um mit dem Druiden Athridas Bearmantle zu sprechen."}},faq={{q="Wer ist Tarindrella?",a="Tarindrella ist eine Dryadenwächterin im Laubschattental und eine Tochter des Cenarius. Sie hütet die Pflanzen und Tiere der Lichtung und warnt die Beschützer der Nachtelfen, wenn Verderbnis das Gleichgewicht bedroht.",al={"tarindrella","wer ist der questgeber","dryade im laubschattental"}},{q="Was ist Teufelsmoos?",a="Teufelsmoos ist ein verderbter, von dunkler Magie berührter Bewuchs, der an den Tieren des Laubschattentals haftet. Es versetzt Geschöpfe wie Grells in Raserei und treibt sie zu unnatürlicher Aggression.",al={"teufelsmoos","was ist teufelsmoos","moos verderbnis"}},{q="Was ist mit den Furbolgs im Laubschattental geschehen?",a="Die Furbolgs des Laubschattentals verließen ihre friedlichen Behausungen und schlossen sich zum feindseligen Gnarlpine-Stamm zusammen.",al={"furbolg-rätsel","gnarlpine-stamm","wohin sind die furbolgs gegangen"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Tarindrella schickt Reisende nach Dolanaar, wo der Druide Athridas Bearmantle die Verderbnis im gesamten Weltbaum untersucht.",al={"nächste quest","wohin geht es danach","athridas bearmantle"}},{q="Was sind Grells und Grellkin?",a="Grells und Grellkin sind kleine, schelmische Waldgeister, die in Teldrassils Ästen heimisch sind. Meist sind sie ungebärdige Plagegeister, doch unter dem Einfluss von Verderbnis wie Teufelsmoos werden sie gewalttätig und aggressiv.",al={"grells","grellkin","was sind grells"}},{q="Warum gibt es Verderbnis auf Teldrassil?",a="Teldrassil wurde herangezogen, um den Nachtelfen ihre verlorene Unsterblichkeit zurückzugeben und ihnen eine neue Zuflucht zu bieten. Dunkle Energien sickern in seine Äste und Tiere und beunruhigen die Druiden und Waldgeister, die ihn hüten.",al={"warum ist teldrassil verderbt","verderbnis im laubschattental"}}},fx={["2b4aa272"]={q="Warum möchte Tarindrella, dass Ihr Teufelsmoos sammelt?",a="Tarindrella spürt einen dunklen, verderblichen Einfluss, der durch Laubschattental kriecht. Die friedlichen Furbolgs haben ihre angestammten Häuser verlassen, um sich als feindseliger Stamm der Gnarlpine zu sammeln, und Grells sind in die verlassenen Haine eingedrungen. Sie braucht einen physischen Beweis dafür, dass Teufelsmoos dafür verantwortlich ist, die lokale Tierwelt und die Geister in den Wahnsinn zu treiben, was es ihr ermöglichen würde, die Quelle der Verderbnis zu bestätigen, die den Weltenbaum bedroht.",al={"warum braucht tarindrella teufelsmoos","tarindrella motiv teufelsmoos","warum teufelsmoos sammeln"}},["84e2b96b"]={q="Gegen wen werdet Ihr ausgesandt, um zu kämpfen?",a="Ihr werdet ausgesandt, um die Grells und Grellkin zu jagen, die die Hügel befallen haben, wo einst die Furbolgs lebten. Diese kleinen, schelmischen Waldgeister stehen unter einem dunklen Zauber, der sie gegenüber den Bewohnern von Laubschattental gewalttätig werden lässt, während sie das verderbte Teufelsmoos tragen, das ihre unnatürliche Bosheit nährt.",al={"gegen wen kämpfen wir","wer hat das teufelsmoos","ziel grells und grellkin"}}},fp="22,192,21.248.0,14.296.0,19.188.0,17.167.0,44.94.0,40.119.0,29.190.0,40.201.0"}
P.entries["quest:46"] = {n="Kopfgeld auf die Murlocs",s="Im östlichen Wald von Elwynn breiten sich Murlocs aus, und die Armee von Sturmwind hat ein Kopfgeld auf sie ausgesetzt. Da die Garnison überlastet ist, bittet Wache Thomas Reisende, die Lager am Steinhügelsee und an den südlichen Wasserwegen zu räumen, bevor Murlocs nahe Höfe und Straßen überrennen.",h="Im östlichen Wald von Elwynn breiten sich Murlocs aus, und die Armee von Sturmwind hat ein Kopfgeld auf sie...",kw={"kopfgeld","wald von elwynn","flossen","murlocstreuner","wache thomas","murloclauerer","marschall dughan","murlocs","der steinhügelsee"},ang={["class:Hunter"]="Als Jäger findet Ihr rund um den Steinhügelsee sumpfige Ufer und Schilfsäume, die sich zur Pirsch auf flinke, in Schwärmen auftretende Wasserraubtiere eignen.",["faction:Alliance"]="Die Räumung der Wasserwege schützt Versorgungslinien und ländliche Wohnstätten zwischen Goldhain und der Grenze zum Rotkammgebirge.",["race:Human"]="Als Mensch seht Ihr, wie schwach Sturmwinds Schutz jenseits des Kernlands um die Hauptstadt geworden ist."},sec={{t="Gefahr an den Wasserwegen",b="Murlocs haben rund um den Steinhügelsee und an der Gabelung der südlichen Bäche Lager errichtet. Murloclauerer und Murlocstreuner greifen Reisende an und drängen auf menschliche Siedlungen vor. Was als kleines Ärgernis begann, bedroht nun den östlichen Wald von Elwynn, während die westlichen Straßen vergleichsweise sicher bleiben."},{t="Überlastete Verteidigung",b="Wache Thomas ist an der östlichen Brücke beim Rotkammgebirge stationiert. Gefahren jenseits der Brücke und Unruhen im eigenen Land fordern gleichermaßen seine Aufmerksamkeit. König Varian Wrynn ist verschollen, und die Bürokratie belastet Sturmwinds Militärführung. Die Garnisonen der Ortschaften erhalten selten die angeforderten Verstärkungen. Deshalb setzen Marschall Dughan und örtliche Offiziere öffentliche Kopfgelder aus und zahlen Münzen für Murlocflossen, um die Angriffe entlang der Wasserwege einzudämmen."}},faq={{q="Warum gibt es ein Kopfgeld auf Murlocs im Wald von Elwynn?",a="Die Lager der Murlocs am Steinhügelsee und an den südlichen Bächen im östlichen Wald von Elwynn wachsen. Ihre Streiftrupps bedrohen bei der Nahrungssuche nahe Höfe, Straßen und Reisende, weshalb die Armee von Sturmwind Reisende dafür bezahlt, ihre Zahl zu verringern.",al={"warum murlocs töten","grund für murlockopfgeld","warum kopfgeld auf murlocs"}},{q="Wer bezahlt das Kopfgeld?",a="Die Armee von Sturmwind finanziert das Kopfgeld über die Befehlsstelle in Goldhain unter Marschall Dughan. Wache Thomas ist der Ansprechpartner vor Ort am östlichen Flussübergang und bezahlt Reisende.",al={"wer belohnt diese quest","wer zahlt das kopfgeld","kopfgeld der armee von sturmwind"}},{q="Wo liegen die Siedlungen der Murlocs?",a="Im Norden säumen Murloclager die Ufer und Inseln des Steinhügelsees. Im Süden liegen sie entlang der Flussufer, wo sich der östliche Bach verzweigt.",al={"murlocfundorte im wald von elwynn","wo sind murlocs im wald von elwynn","murlocs am steinhügelsee"}},{q="Warum können sich die Wachen von Sturmwind nicht selbst darum kümmern?",a="Politische Unruhen, fehlende Führung und Banditentum überlasten Sturmwinds Militär im ganzen Königreich. Außenposten wie die Brücke von Wache Thomas haben nur eine Handvoll Männer, zu wenige, um die Angriffe auf die Stämme am Ufer fortzusetzen.",al={"warum braucht wache thomas hilfe","warum kämpfen wachen nicht gegen murlocs","wachenmangel im wald von elwynn"}},{q="Welchen Beweis für die Tötungen verlangt Wache Thomas?",a="Wache Thomas verlangt abgerissene Flossen von den Murloclauerern und Murlocstreunern an den östlichen Wasserwegen des Walds von Elwynn.",al={"wer lässt abgerissene murlocflossen fallen","questnachweis","murlocflossen"}},{q="Weiß Marschall Dughan, wie ernst das Murlocproblem ist?",a="Ja. Wache Thomas sagt, dass Marschall Dughan wegen der Murlocbedrohung im gesamten östlichen Wald von Elwynn besorgt ist. Berichte über geräumte Lager sind für die Moral vor Ort von Bedeutung.",al={"marschall dughan murlocs","weiß goldhain bescheid","dughans reaktion"}}},fx={d8a52c2e={q="Was machen die Murlocs im östlichen Wald von Elwynn?",a="Murloclauerer und -sucher sind tief in den östlichen Wald von Elwynn vorgedrungen und haben feindselige Siedlungen rund um den Steinhügelsee im Norden und entlang der südlichen Flussgabelungen errichtet. Diese primitiven, aggressiven Amphibien greifen Reisende an und dringen auf Ackerland vor, wodurch östliche Wasserwege zu gefährlichem Gebiet werden, das die Armee von Sturmwind aktiv zurückdrängen muss.",al={"warum sind murlocs in elwynn","murloc bedrohung elwynn","murloclauerer und sucher"}}},fp="17,269,25.280.0,18.432.0,43.222.0,29.169.0,41.147.0,54.228.0,49.98.0,66.144.0"}
P.entries["quest:460"] = {n="In Stücken begraben",s="Auf der Insel Fenris ruft Alarics abgetrennter Kopf aus dem Jenseits um Hilfe. Er bittet Euch, ihn quer durch Burg Fenris zu einem unmarkierten Grab nahe den Ställen zu tragen, wo sein Körper liegt.",h="Auf der Insel Fenris ruft Alarics abgetrennter Kopf aus dem Jenseits um Hilfe.",kw={"alaric","insel fenris","burg fenris","moderfell","flaches grab","silberwald","sprechender kopf","thule ravenclaw"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie Thule einen Schutzzauber in einen unausweichlichen Fluch verwandelte, der sein Opfer zerstückelt im Untod gefangen hält. Sein Zauber zeigt, wie Nekromantie arkane Magie verderben kann.",["race:Undead"]="Als Champion der Verlassenen kennt Ihr die tückische Zauberkunst von Thule Rabenklaue. Mit der Geißel verbündete Zauberer verbreiten solche grausamen Schrecken in ganz Lordaeron."},sec={{t="Ein verratener Leibwächter",b="Auf Burg Fenris im Silberwald diente Alaric Thule Rabenklaue als oberster Diener und persönlicher Leibwächter. Thule war ein mächtiger Magier, der mit der Geißel verbündet war. Als die Seuche des Untodes die Region heimsuchte, versprach er, seine Zauberei würde Alaric schützen. Stattdessen hielt der Schutzzauber ihn in endloser Qual und im Untod gefangen, während sein Bewusstsein in seinen abgetrennten Teilen erhalten blieb."},{t="Spielzeug der Moderfelle",b="Thule erschuf die Moderfellgnolle, indem er die örtlichen Rudel mit nekromantischer Fäulnis infizierte. Dann wandte er sich gegen seinen eigenen Leibwächter. Er schlug Alaric den Kopf ab und warf ihn den wilden Gnollen zur Ablenkung vor. Die Moderfelle schleiften Alarics Körper zu einem flachen Grab, das sie hastig außerhalb der Ställe der Burg ausgehoben hatten. Sie behielten seinen sprechenden Kopf als makabres Spielzeug, bis ein Außenstehender eingriff."},{t="Die Teile wieder vereinen",b="Nahe den Ställen liegt Alarics kopfloser Rumpf in einem flachen Grab. Bringt seinen abgetrennten Kopf dorthin, und seine Überreste werden wieder vereint. Thules Fluch bindet Alaric noch immer an den Untod. Doch mit seinen wieder vereinten Teilen findet er ein bitteres Maß an Erleichterung."}},faq={{q="Wer ist Alaric?",a="Alaric diente Thule Rabenklaue als oberster Diener und persönlicher Leibwächter auf Burg Fenris. Thules Zauber sollte ihn vor der Seuche des Untodes schützen, band ihn jedoch stattdessen an ewiges Unleben.",al={"alaric","wer ist der sprechende kopf","sprechender kopf silberwald"}},{q="Warum wurde Alaric enthauptet?",a="Thule Rabenklaue enthauptete Alaric, nachdem er seine Experimente zur Erschaffung der Moderfellgnolle abgeschlossen hatte. Er warf ihnen Alarics abgetrennten Kopf, der noch bei Bewusstsein war, als Spielzeug vor.",al={"warum ist alaric ein kopf","wer hat alarics kopf abgeschlagen"}},{q="Wo liegt Alarics Grab?",a="Alarics Körper liegt in einem unmarkierten, hastig ausgehobenen, flachen Grab auf der Insel Fenris, im Hof von Burg Fenris nahe den Stallgebäuden.",al={"wo ist alarics körper","flaches grab fundort","wo ist das grab fenris"}},{q="Was sind die Moderfellgnolle?",a="Die Moderfellgnolle sind örtliche Rudel auf der Insel Fenris, die durch Thule Ravenclaws nekromantische Experimente in verrottende, vom Untod berührte Schrecken verwandelt wurden.",al={"moderfelle","moderfellgnolle","insel fenris gnolle"}},{q="Wer ist Thule Rabenklaue?",a="Thule Rabenklaue ist ein menschlicher Zauberer und Nekromant der Geißel, der Burg Fenris mitten im Lordameresee an sich gerissen hat. Er nutzt sie als Labor, um die Gnolle zu verderben und den Einfluss der Geißel auszuweiten.",al={"thule","thule ravenclaw"}},{q="Was geschieht, nachdem Ihr das Grab gefunden habt?",a="Sobald seine Überreste wieder vereint sind, hilft Alaric Euch, eine verborgene Nische mit einem mächtigen Zauberstab zu finden. Ihr könnt ihn Dalarans Magus Bethor Eismacht in Unterstadt zurückbringen.",al={"wie weiter in stücken begraben","in stücken begraben fortsetzung"}}},fx={["5dad63cd"]={q="Warum möchte Alaric, dass sein Kopf zu seinem Grab gebracht wird?",a="Alaric ist in einem qualvollen Untod gefangen, der durch den verzerrten Schutzzauber von Thule Rabenklaue erschaffen wurde. Nachdem er enthauptet und den Fäulnisnagergnollen als grausames Spielzeug vorgeworfen wurde, fürchtet er, dass sein kopfloser Körper geschändet oder vernichtet wurde. Er möchte zu seinem provisorischen Grab auf der Insel Fenris zurückgebracht werden, um sich mit seinen Überresten zu vereinen und seine erniedrigende Tortur zu beenden.",al={"warum braucht der sprechende kopf hilfe","alaric motiv","warum alaric zu seinem grab bringen"}},c2c834f2={q="Warum braucht Alaric Eure Hilfe, um sein Grab zu erreichen?",a="Alaric ist lediglich ein abgetrennter, belebter Kopf. Da er sich nicht alleine bewegen kann, war er völlig hilflos, während er als Spielzeug von den Fäulnisnagergnollen, die Burg Fenris besetzen, herumgetreten wurde. Ihr seid der erste Nicht-Gnoll, dem er begegnet ist, der ihn physisch an den Kreaturen vorbeibringen und ihn ordnungsgemäß begraben kann.",al={"warum braucht alaric euch","warum kann alaric das nicht selbst","sprechender kopf warum ich"}}},fp="17,178,20.368.0,26.373.0,20.235.1,14.192.0,24.160.0,32.131.0,29.154.0,23.198.0,38.160.1"}
P.entries["quest:461"] = {n="Die versteckte Nische",s="In Burg Fenris führen Euch Alarics Erinnerungen zu einer versteckten Nische. Seine sterblichen Überreste weisen auf eine Ruhestätte hin, und dort wartet ein altes Relikt.",h="In Burg Fenris führen Euch Alarics Erinnerungen zu einer versteckten Nische.",kw={"alaric","staubiges regal","burg fenris","versteckte nische","moderfell","silberwald","thule ravenclaw"},ang={["class:Mage"]="Die versteckte Nische bewahrt das arkane Erbe von Burg Fenris durch Artefakte, die mit ehemaligen Zauberern aus Dalaran wie Thule Rabenklaue verbunden sind.",["faction:Horde"]="Als Angehöriger der Horde bergt Ihr Relikte aus dem Herzen von Burg Fenris, schwächt Thules Stellung auf der Insel Fenris und unterstützt den Feldzug der Verlassenen zur Sicherung des Silberwalds.",["race:Undead"]="Als Verlassener seid Ihr mit dem Umgang mit sprechenden Überresten vertraut. Alarics Wunsch, in menschlichen Ruinen zu ruhen, erinnert an die Ländereien, die Euer Volk geerbt hat."},sec={{t="Eine ruhelose Bitte",b="Alaric erinnert sich an Burg Fenris in besseren Tagen. Späher der Horde bargen seine Knochen aus einem flachen Grab vor der Festung, doch er will nicht stillschweigend zum Grabmal gehen. Im Gegenzug bietet er entscheidendes Wissen an: Eine versteckte Nische im südwestlichen Turm der Burg birgt einen Gegenstand, den Thule Rabenklaue und seine Magierkollegen schätzen."},{t="In den Mauern bestattet",b="Ihr tragt Alarics sterbliche Überreste durch Burg Fenris, vorbei an den Moderfellgnollen, die die Inselfestung heimsuchen. In einem oberen Stockwerk verbirgt ein staubiges Bücherregal das Fach, das er beschrieben hat. Alaric bittet Euch, ihn im uralten Mauerwerk der Burg einzuschließen. Dort verbrachte er die glücklichsten Tage seines Lebens, außerhalb der Reichweite der Gnolle."}},faq={{q="Wer ist Alaric?",a="Alaric diente Thule Rabenklaue als oberster Diener und Leibwächter auf Burg Fenris. Thule enthauptete ihn, nachdem er die Moderfellgnolle erschaffen hatte. In einem flachen Grab vor der Festung entdeckt, führt Alarics wiedererweckter Geist Reisende der Horde im Austausch für eine angemessene Ruhestätte in seiner geliebten Festung.",al={"alarics geschichte","wer ist alaric","wessen knochen sind das"}},{q="Wo befindet sich die versteckte Nische?",a="Die versteckte Nische liegt hinter einem staubigen Bücherregal in einem oberen Stockwerk des südwestlichen Turms von Burg Fenris.",al={"wo ist das staubige regal","wo ist die nische","versteckte nische fundort"}},{q="Welcher Gegenstand ist in der Nische verborgen?",a="Die Nische birgt einen alten Zauberstab, den Thule Rabenklaue und seine früheren Kollegen aus Dalaran schätzen. Sie enthält auch andere Hinterlassenschaften, die Alaric jenen überlässt, die ihm geholfen haben.",al={"was ist in der nische","burg fenris schatz","thules gegenstand"}},{q="Warum will Alaric in Burg Fenris bleiben?",a="Alaric erinnert sich an seine Jahre auf Burg Fenris als die glücklichsten seines Lebens. Im Mauerwerk zu ruhen, bringt ihm Frieden und schützt seine sterblichen Überreste vor den aasfressenden Gnollen in den Höfen.",al={"warum alaric in fenris zurücklassen","alarics ruhestätte"}},{q="Was geschieht, nachdem das Regal gefunden wurde?",a="Nachdem Alaric in der Nische eingeschlossen ist und Ihr den Zauberstab geborgen habt, kehrt Ihr nach Unterstadt zurück, um ihn Bethor Eismacht zu überbringen.",al={"quest nach der versteckten nische","was tun mit dem zauberstab"}},{q="Warum hat Alaric Euch gebeten, seine Stiefel zurückzulassen?",a="Als seine Knochen aus dem flachen Grab geborgen wurden, scherzte Alaric, dass seine alten Stiefel nie richtig gepasst hätten. Er bestand darauf, dass sie in der Erde blieben.",al={"alarics stiefel","stiefel zurücklassen"}}},fx={["8d31ac84"]={q="Warum muss Alaric, dass Ihr seine Überreste zur Nische tragt?",a="Alaric ist nicht mehr als eine zerstückelte Leiche, die in einem flachen Grab auf der Insel Fenris begraben liegt. Da er getötet und zerstückelt wurde, hat er keine physische Kraft, sich selbst zurück in die Festung zu bewegen, die er einst sein Zuhause nannte. Er verlässt sich ganz auf Euch, um seine verstreuten Überreste zu exhumieren, ihn durch die feindselige, von Gnollen befallene Burg zu tragen und ihn in der geheimen Nische abzulegen.",al={"warum braucht alaric hilfe","warum ich alaric","warum alaric überreste tragen"}}},fp="16,135,18.318.0,19.316.1,14.295.0,34.101.0,34.161.0,48.182.0,37.124.1,50.137.0"}
P.entries["quest:463"] = {n="Der Sumpfhüter",s="Vom Hafen von Menethil schickt Erster Maat Fitzsimmons Reisende der Allianz nach Nordosten in die Sümpfe des Sumpflands. Sie suchen ein geheimnisvolles Wesen, das Gerüchten zufolge unter den Bestien lebt.",h="Vom Hafen von Menethil schickt Erster Maat Fitzsimmons Reisende der Allianz nach Nordosten in die Sümpfe des...",kw={"dun modr","fitzsimmons","sumpfhüter","menethil","rethiel","tramping paws","sumpfland"},ang={["class:Druid"]="Hafenarbeiter mögen Rethiel für ein Sumpfmonster halten, doch als Druide erkennt Ihr einen uralten Wächter, der im Einklang mit dem Gleichgewicht der Natur steht.",["race:NightElf"]="Als Nachtelf fern von Kalimdor findet Ihr in den feuchten, schlammigen Böden von Khaz Modan vielleicht einen vertrauten, tröstlichen Widerhall der uralten Wächter der Natur."},sec={{t="Tavernengerüchte und Sumpfgeschichten",b="Im Hafen von Menethil erzählen sich Seeleute und Wanderer Geschichten über eine Bestie, die im Sumpf lauert. Erster Maat Fitzsimmons nennt den Sumpfhüter einen Appetit auf Beinen und jene, die ihn suchen, leichtgläubig. Verlasst die trockene Straße, warnt er, und der alte Grüne beißt Euch entzwei. Für die Leute an den Docks ist alles Riesige in den trüben Gewässern eine weitere menschenfressende Gefahr im Sumpf."},{t="Der Wächter des Sumpfes",b="Östlich der Abzweigung nach Dun Modr wacht Rethiel als Sumpfhüter über das Sumpfland. Dieser gewaltige Urahn ist an den wilden Wuchs dort gebunden, kein geistloser Fleischfresser. Aus der Ferne beobachtet er das Leid des verdorbenen Landes und ruft hilfsbereite Sterbliche dazu auf, den verseuchten Sumpf zu reinigen."}},faq={{q="Wer ist der Sumpfhüter?",a="Der Sumpfhüter ist Rethiel, ein uralter Naturwächter im Sumpfland. Seeleute an der Küste halten ihn für ein wildes Ungeheuer, doch er beschützt die Pflanzen und Tiere.",al={"wer ist der sumpfhüter","identität des sumpfhüters","wer ist rethiel"}},{q="Wo kann ich den Sumpfhüter finden?",a="Rethiel befindet sich in den Sümpfen östlich der Hauptstraße, nahe der Abzweigung nach Dun Modr im nördlichen Sumpfland.",al={"standort des sumpfhüters","wo ist rethiel","koordinaten des sumpfhüters"}},{q="Warum hält Erster Maat Fitzsimmons den Sumpfhüter für gefährlich?",a="Fitzsimmons kennt nur die Tavernengerüchte und den Aberglauben im Hafen von Menethil. Da Bestien das Sumpfland überrennen, halten Seeleute jeden Riesen unter den Krokodilen und Raubtieren für ein menschenfressendes Ungetüm.",al={"warum hat fitzsimmons angst","ist der sumpfhüter böse"}},{q="Was will Rethiel von Reisenden?",a="Rethiel sucht Streiter, die sich um das Sumpfland kümmern, das seinen Worten nach aus eiternden Wunden weint. Er trägt Reisenden auf, die Tierwelt zu schützen und Bedrohungen für das örtliche Ökosystem einzudämmen.",al={"was macht der sumpfhüter","rethiels aufgabe","warum den sumpfhüter treffen"}},{q="Was geschieht, nachdem man den Sumpfhüter gefunden hat?",a="Wenn Ihr mit Rethiel sprecht, sagt er, dass die Natur gut von Euch spricht, und gibt Euch dann Tramping Paws, um bei den Problemen im Sumpf zu helfen.",al={"nächste quest nach dem sumpfhüter","tramping paws quest"}},{q="Muss man kämpfen, um diese Quest abzuschließen?",a="Nein. Ihr müsst nur den Weg durch das Sumpfland überleben und mit Rethiel in seinem Hain im Sumpf sprechen.",al={"sumpfhüter kampf","muss man gegen den sumpfhüter kämpfen"}}},fx={e3605feb={q="Warum schickt Euch Erster Maat Fitzsimmons zum Greenwarden?",a="Fitzsimmons hat kein persönliches Interesse oder eine edle Mission; er hält Euch einfach für einen totalen Narren, weil Ihr nach der Kreatur fragt. Überzeugt davon, dass jeder, der Gerüchten über 'das Biest' nachjagt, direkt in sein Verderben rennt, weist er Euch zynisch in Richtung des Sumpfes, um Euren Todeswunsch zu befriedigen – während er scherzhaft anbietet, Euer Gold aufzubewahren, bevor Ihr in der Mitte durchgebissen werdet.",al={"fitzsimmons motiv","warum zum greenwarden schicken","warum will fitzsimmons greenwarden finden"}}},fp="15,170,27.360.0,25.287.1,23.170.0,33.107.0,67.199.0,38.173.0,43.132.0,54.105.0"}
P.entries["quest:464"] = {n="Kriegsflaggen",s="Im Hafen von Menethil schickt Hauptmann Starkfaust Champions der Allianz gegen Dragonmaw-Orcs aus, die im Sumpfland an Stärke gewinnen. Er will ihre Flaggen aus einem Lager nordöstlich der Stadt erbeuten lassen.",h="Im Hafen von Menethil schickt Hauptmann Starkfaust Champions der Allianz gegen Dragonmaw-Orcs aus, die im...",kw={"hauptmann starkfaust","dragonmaw","grim batol","hafen von menethil","nek'rosh","nekros","kriegsflaggen","sumpfland"},ang={["class:Warrior"]="Als Krieger steht Ihr in ihrem Lager kampferprobten Veteranen des Zweiten Krieges gegenüber. Sie kämpfen mit rücksichtsloser Gewalt, selbst ohne ihre Drachenreittiere.",["faction:Alliance"]="Als Champion der Allianz versteht Ihr, warum Hauptmann Starkfaust die Dragonmaw aus der Umgebung des Hafens von Menethil vertreiben will. Ihr Lager bedroht die Schifffahrtsroute, die Sturmwind, Eisenschmiede und die nördlichen Reiche verbindet.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Dragonmaw die uralte Festung Grim Batol entweihten und Krieg in die umliegenden Berge brachten. Jeder gefallene Dragonmaw-Krieger bringt ein Stück der lange überfälligen Gerechtigkeit."},sec={{t="Überreste der Dragonmaw",b="Während des Zweiten Krieges hielt der Dragonmaw-Clan den roten Drachenschwarm in Grim Batol gefangen. Als ihre Kontrolle brach, jagten die befreiten Drachen ihre Peiniger bis an den Rand der Auslöschung. Die wenigen überlebenden Orcs flohen aus Grim Batol in die hohen Berge östlich von Whelgar's Excavation, um sich vor dem Zorn des roten Schwarms zu verbergen."},{t="Ein neues Kriegslager",b="Überlebende der Dragonmaw haben sich nordöstlich vom Hafen von Menethil erneut versammelt. Sie haben ein Kriegslager errichtet und purpurrote Standarten im Marschland aufgestellt. Hauptmann Starkfaust sieht in einer bewaffneten Orc-Streitmacht so nahe an der Hafenstadt eine Gefahr. Er will ihre Reihen ausdünnen und ihre Flaggen als Beweis ihrer Niederlage niederreißen lassen."},{t="Das Vermächtnis von Nekros",b="Nek'rosh führt die neu formierten Dragonmaw-Orcs an. Er ist der Sohn von Nekros, dem Hexenmeister, der einst gefangene rote Drachen durch dunkle Zauberei beherrschte. Als diese Magie versagte, rissen die Drachen Nekros in Stücke. Nun befehligt sein Sohn die Überlebenden, verzehrt von Rachsucht gegen die gewaltigen Bestien, die seinen Vater töteten."}},faq={{q="Wer sind die Dragonmaw-Orcs im Sumpfland?",a="Die Dragonmaw-Orcs im Sumpfland sind Überlebende eines Clans, der während des Zweiten Krieges den roten Drachenschwarm versklavte. Die befreiten Drachen jagten sie und verstreuten die Überlebenden von Grim Batol in die Berge und Sümpfe.",al={"dragonmaw-orcs sumpfland","wer sind die dragonmaw","sumpfland orcs"}},{q="Warum will Hauptmann Starkfaust ihre Kriegsflaggen?",a="Hauptmann Starkfaust will ihre Flaggen als Beweis dafür, dass Soldaten der Allianz das Lager angegriffen und seine Kampfkraft geschwächt haben. Das Lager nordöstlich vom Hafen von Menethil bedroht die Stadt.",al={"warum flaggen sammeln","hauptmann starkfaust flaggen"}},{q="Was geschah mit den Drachen des Dragonmaw-Clans?",a="Als die dunkle Magie versagte, die sie gefangen hielt, wandten sich die roten Drachen gegen ihre Peiniger vom Dragonmaw-Clan. Sie jagten die Orcs durch ganz Khaz Modan und dezimierten den Clan.",al={"was geschah mit den drachen","dragonmaw drachen"}},{q="Wer führt den Dragonmaw-Clan jetzt an?",a="Nek'rosh führt die Überlebenden der Dragonmaw an. Er ist der Sohn von Nekros und hat die Orcs zur Rache gegen die roten Drachen gesammelt, die seinen Vater töteten.",al={"dragonmaw anführer","wer ist nek'rosh"}},{q="Wo versteckten sich die Dragonmaw, bevor sie dieses Lager errichteten?",a="Nach ihrer Flucht aus Grim Batol versteckten sich die überlebenden Orcs in den zerklüfteten Bergen östlich von Whelgar's Excavation. Später zogen sie in die Sümpfe des Sumpflands und errichteten ihr Lager.",al={"wo versteckten sich die dragonmaw","dragonmaw zuflucht"}},{q="Gehören diese Dragonmaw-Orcs zu Thralls Horde?",a="Nein. Die Überreste der Dragonmaw handeln außerhalb der neuen Horde von Kriegshäuptling Thrall in Kalimdor. Sie sind Abtrünnige, getrieben von Rachsucht und dem Willen zu überleben.",al={"gehören die dragonmaw zur horde","dragonmaw thrall horde"}}},fx={["33d8bd47"]={q="Wofür ist die Kriegsflagge des Drachenmals?",a="Für Hauptmann Starkfaust dienen die Kriegsflaggen als unbestreitbarer physischer Beweis dafür, dass Ihr in das Herz des Lagers der Drachenmals vorgestoßen seid. Für die Orks repräsentieren diese Standarten die erneute Einheit und den kriegerischen Trotz ihres Clans unter Nek'rosh. Sie zu entfernen demoralisiert nicht nur den wiederauferstehenden Clan, sondern bestätigt auch den Verteidigern von Hafen von Menethil, dass ihre Zahl und ihre Befestigungen einen direkten, strafenden Schlag erlitten haben.",al={"drachenmals kriegsflagge nutzen","warum flaggen sammeln","was sind die kriegsflaggen"}},["70d8988a"]={q="Gegen wen werdet Ihr bei dieser Mission ausgesandt?",a="Ihr werdet gegen die Überreste des Clans der Drachenmals ausgesandt, wilde Orks, die die Zerstörung von Grim Batol und die Rache der roten Drachen überlebt haben. Nachdem sie sich in den Bergen neu formiert haben, sind sie nach Westen in das Sumpfland vorgedrungen und haben nordöstlich von Hafen von Menethil ein befestigtes Kriegslager errichtet. Wenn ihre wachsende Zahl und ihr unerbittlicher Blutdurst nicht kontrolliert werden, stellen sie eine direkte Bedrohung für die Sumpfstraßen und den Hafen selbst dar.",al={"wen greifen wir an","lager der drachenmals ziel","gegen wen kämpfe ich"}}},fp="11,181,25.309.0,19.295.0,20.304.1,43.214.0,50.190.0,46.154.0,33.143.1,57.162.0,56.132.0"}
P.entries["quest:465"] = {n="Nek'roshs Schachzug",s="Im Hafen von Menethil rüstet sich Hauptmann Starkfaust für Nek'roshs Angriff. Der Häuptling der Dragonmaw hat Katapulte gebaut, um den Hafen zu beschießen, während Kämpfe bei Dun Algaz Verstärkung aufhalten. Ihr werdet in die Sümpfe geschickt, um die Maschinen zu zerstören, bevor sie die Stadt erreichen.",h="Im Hafen von Menethil rüstet sich Hauptmann Starkfaust für Nek'roshs Angriff.",kw={"hauptmann starkfaust","katapulte","dragonmaw","dun algaz","hafen von menethil","nek'rosh","nek'roshs schachzug","sumpfland"},ang={["class:Warrior"]="Als Krieger setzt Ihr auf aggressive Fronttaktiken und brutalen Nahkampf, um ein befestigtes feindliches Lager zu stürmen und seine schwere Belagerungsartillerie zu zerstören.",["faction:Alliance"]="Da Kämpfe Dun Algaz abriegeln, ist die Allianz auf mutige Freiwillige angewiesen, um die Kriegsmaschinerie der Dragonmaw zu stören.",["race:Dwarf"]="Als Bronzebeard-Zwerg wisst Ihr, dass der Hafen von Menethil das Tor Eures Volkes zum westlichen Meer ist. Ihn an die Belagerungswaffen der Dragonmaw zu verlieren, würde Eisenschmiedes Seeverbindungen lähmen."},sec={{t="Eine Belagerung droht",b="Zwergische Späher deckten den Plan auf, während Kämpfer der Allianz mit Plünderern der Dragonmaw zusammenstießen. Häuptling Nek'rosh hat den Bau vollwertiger Belagerungskatapulte in den Lagern des Sumpflands überwacht. Er will sie zum Hafen von Menethil bringen und dessen Festungsmauern beschießen. Der Angriff bedroht den wichtigsten Schifffahrtsknotenpunkt der Allianz an der Westküste."},{t="Abgeschnitten bei Dun Algaz",b="Kämpfe und Aktivitäten der Grünhäute versperren die Gebirgspässe bei Dun Algaz. Das Tiefland ist von den Hauptgarnisonen Eisenschmiedes abgeschnitten, sodass Hauptmann Starkfaust keine Truppen zur Bewachung des Hafenumlands entbehren kann. Ohne Hilfe aus Khaz Modan hängt Menethils Überleben davon ab, die Katapulte zu sabotieren, bevor sie gegen die Stadt eingesetzt werden können."},{t="Feuer im Lager",b="Späher tragen Zwergenzunder ins Herz des Lagers der Dragonmaw. Dort müssen sie die hölzernen Katapulte in Brand setzen und zerstören. Das wird Nek'rosh seiner Artillerie berauben und seinen Kriegern die Feuerkraft nehmen, um Menethils Verteidigung zu durchbrechen. Die Maschinen müssen zerstört werden, bevor der Kriegsherr gestellt werden kann."}},faq={{q="Wer ist Nek'rosh?",a="Nek'rosh führt die Überreste des Dragonmaw-Klans im Sumpfland an. Der skrupellose Häuptling leitet einen Feldzug, um den Hafen von Menethil zu belagern.",al={"nekrosh","häuptling nek'rosh","wer ist nek rosh"}},{q="Warum ist der Hafen von Menethil in so großer Gefahr?",a="Der Hafen von Menethil ist auf den Seehandel angewiesen und liegt fern von Eisenschmiede. Kämpfe versperren die Pässe bei Dun Algaz, verhindern Verstärkung auf dem Landweg und lassen die Stadt einer geballten Belagerung schutzlos ausgeliefert.",al={"menethil gefahr","warum hafen verwundbar","bedrohung für menethil"}},{q="Was ist das Ziel dieser Mission?",a="Ihr tragt Zwergenzunder ins Lager der Dragonmaw, um ihre Belagerungskatapulte niederzubrennen und zu zerstören, bevor sie gegen den Hafen von Menethil eingesetzt werden können.",al={"ziel des schachzugs","was ist zu tun","katapultmission"}},{q="Wer erteilt diesen Auftrag?",a="Hauptmann Starkfaust gibt die Befehle. Der zwergische Offizier koordiniert die örtliche Verteidigung des Hafens und den Feldzug gegen die Dragonmaw.",al={"questgeber","wer vergibt nekroshs schachzug","starkfausts rolle"}},{q="Was folgt auf die Zerstörung der Katapulte?",a="Sobald die Katapulte zerstört sind, muss die Bedrohung beendet werden, indem Häuptling Nek'rosh selbst aufgespürt und hingerichtet wird.",al={"nach den katapulten","nächste quest","was kommt danach"}},{q="Warum kann Eisenschmiede keine Truppen schicken, um Menethil zu helfen?",a="Die Straße von Loch Modan ins Sumpfland führt durch Dun Algaz. Feindliche Streitkräfte machen den Pass zum Kampfgebiet und legen dort Hinterhalte, sodass der Landweg nicht verlässlich nutzbar ist.",al={"blockade bei dun algaz","warum keine verstärkung","hilfe aus eisenschmiede"}}},fx={["98c43a31"]={q="Warum möchte Hauptmann Starkfaust, dass die Katapulte zerstört werden?",a="Hauptmann Starkfaust entdeckte, dass Nek'rosh Belagerungswaffen konstruiert hat, die speziell dafür gedacht sind, Hafen von Menethil zu bombardieren und zu erobern. Da die Kämpfe bei Dun Algaz den Hafen von den Verstärkungen aus Eisenschmiede abschneiden, kann die Siedlung einem organisierten Artillerieangriff nicht standhalten. Starkfaust muss diese Belagerungsmaschinen ausschalten, bevor die Drachenmals gegen die Stadt marschieren können.",al={"starkfaust motiv","warum katapulte zerstören","warum muss starkfaust das erledigen"}},["837e41fd"]={q="Was ist Euer Ziel im Lager der Drachenmals?",a="Ihr werdet in das Herz des Lagers der Drachenmals geschickt, um deren neu gebaute Katapulte ausfindig zu machen und zu verbrennen. Diese primitiven Belagerungsmaschinen stellen eine unmittelbare existenzielle Bedrohung für Hafen von Menethil dar und verleihen den Orks die zerstörerische Kraft, die Verteidigung der Stadt aus der Ferne zu zertrümmern.",al={"was sind die ziele","drachenmals katapulte ziel","gegen wen werde ich ausgesandt"}},["68f35499"]={q="Warum schickt Hauptmann Starkfaust einen Abenteurer anstatt seine Wachen?",a="Die Garnison von Hafen von Menethil ist durch die ständige Verteidigung der Stadt gegen Angriffe und natürliche Gefahren überlastet, während Verstärkungen hinter den umkämpften Pässen von Dun Algaz gefangen bleiben. Starkfaust kann keine Abteilung seiner wenigen verbleibenden Stadtwachen für einen tiefen Infiltrationsangriff in feindliches Gebiet entbehren, was einen unabhängigen Abenteurer zu seiner besten Chance macht, das Lager zu sabotieren.",al={"warum ich","warum schickt ihr mich","warum keine wachen schicken"}}},fp="17,264,15.342.0,20.332.0,22.311.0,16.141.0,38.201.0,33.148.0,27.132.0,46.117.1,49.145.0"}
P.entries["quest:466"] = {n="Auf der Suche nach Pyrophor",s="In Stahlrosts Depot sucht Pilot Steinsegel Proben von instabilem Pyrophorerz aus dem Sumpfland. Er glaubt, seine Sprengkraft könnte die zwergische Artillerie verändern, und braucht Euch, um eine abgelegene Höhle aufzusuchen und das gefährliche Mineral zurückzubringen.",h="In Stahlrosts Depot sucht Pilot Steinsegel Proben von instabilem Pyrophorerz aus dem Sumpfland.",kw={"algaz-tor","artillerie","kanonengeschosse","dun morogh","pyrophor","bergbau","erz","pilot steinsegel","stahlrosts depot","sumpfland"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, dass das Risiko explosiver Verbindungen zur Suche nach der nächsten großen Explosion gehört.",["profession:Mining"]="Als Bergmann braucht Ihr geübte Hände, um Pyrophor mit einer Spitzhacke abzubauen. Seine Instabilität macht sorgfältige Arbeit unerlässlich.",["race:Dwarf"]="Als Zwerg stammt Ihr aus einem Volk, das für die Weiterentwicklung von Schießpulver und Artillerie bekannt ist. Pyrophorgeschosse passen zu den Belagerungstraditionen von Khaz Modan."},sec={{t="Eine explosive Entdeckung",b="Belagerungsmaschinenpiloten und Mechaniker in Stahlrosts Depot haben von einem seltenen, instabilen Erz gehört. Gerüchten zufolge gibt es reiche Adern in einer Höhle nordwestlich des Algaz-Tors im Sumpfland. Unvorsichtige Bergleute riskieren dort, dass ihnen das reaktionsfreudige Mineral direkt ins Gesicht explodiert."},{t="Munition von morgen",b="Pilot Steinsegel sieht militärisches Potenzial in dem Erz. Richtig veredelt könnte es zwergische Artillerie antreiben oder als deren Sprengladung dienen. Kanonengeschosse könnten genug Sprengkraft erhalten, um befestigte Verteidigungsanlagen zu durchbrechen. Er will Rohproben, damit Forscher Verhüttungsverfahren erproben können, ohne das Depot in die Luft zu sprengen."}},faq={{q="Wofür wird Pyrophorerz verwendet?",a="Pyrophor ist ein äußerst instabiles, explosives Mineral. Pilot Steinsegel will Verhüttungsverfahren erproben, mit denen es zu schlagkräftiger Artilleriemunition für Kanonengeschosse werden könnte.",al={"pyrophor verwendung","was bewirkt pyrophor"}},{q="Wo findet man Pyrophor?",a="Das Erz liegt in einem Höhlensystem nordwestlich des Algaz-Tors, in den südlichen Bergen des Sumpflands.",al={"pyrophor fundort","wo bekommt man pyrophor"}},{q="Wer ist Pilot Steinsegel?",a="Pilot Steinsegel ist ein zwergischer Belagerungsmaschinenpilot bei der Belagerungsbrigade von Eisenschmiede. Er ist in Stahlrosts Depot in Dun Morogh stationiert, wo er mit Mechanikern und Belagerungsingenieuren daran arbeitet, zwergische Kriegsmaschinen zu verbessern.",al={"pilot steinsegel","wer vergibt diese quest"}},{q="Warum braucht man eine Spitzhacke, um dieses Erz abzubauen?",a="Pyrophor liegt in rohen Mineraladern vor, nicht lose an der Oberfläche. Bergleute brauchen eine geübte Hand mit der Spitzhacke, um das spröde, explosive Erz aus dem Gestein zu schlagen, ohne es zur Explosion zu bringen.",al={"braucht man bergbau","benötigte bergbaufertigkeit"}},{q="Ist der Umgang mit Pyrophor sicher?",a="Nein. Pyrophor ist für seine Instabilität berüchtigt und kann beim Abbau, beim Transport oder beim Verhütten explodieren.",al={"ist pyrophor gefährlich","explodiert pyrophor"}},{q="Wie hängt das mit „Stonegear's Search“ zusammen?",a="Pilot Langbart oder Gebirgsjäger Kadrell schickt Euch zu Stahlrosts Depot, nachdem Pilot Steinsegel Gerüchte über seltenes Erz gehört hat und jemanden sucht, der es findet. Dies folgt auf „Stonegear's Search“.",al={"stonegear's search folgequest","questreihe"}}},fx={["1b52d5e2"]={q="Warum möchte Pilot Steinsegel Pyrophorerz?",a="Pilot Steinsegel glaubt, dass das flüchtige Mineral ein ungenutztes militärisches Potenzial birgt. Pyrophorerz ist bekanntermaßen instabil und gefährlich in der Handhabung, aber er ist überzeugt, dass ordnungsgemäß geschmolzenes Erz verwendet werden könnte, um verheerende Kanonengeschosse herzustellen. Stationiert in Stahlrosts Depot hofft Steinsegel, Proben zu sammeln, damit Techniker aus Eisenschmiede mit dem explosiven Material experimentieren und ihre Bewaffnung verbessern können.",al={"warum will steinsegel pyrophorerz","steinsegel pyrophorerz motiv","pilot steinsegel ziel"}}},fp="22,240,20.246.0,21.285.0,33.171.0,27.97.0,23.217.0,47.174.0,30.99.0,44.182.0"}
P.entries["quest:467"] = {n="Steinsegels Suche",s="Bei Stahlrosts Depot sucht Pilot Steinsegel seltenes Erz, um die Waffen seines Panzers zu verstärken. Er bittet Euch, frischen Brennstoff für dessen Feuerkraft zu finden.",h="Bei Stahlrosts Depot sucht Pilot Steinsegel seltenes Erz, um die Waffen seines Panzers zu verstärken.",kw={"dun morogh","incendicite","kadrell","langbart","pilot steinsegel","belagerungsmaschine","stahlrosts depot","steinsegel"},ang={["profession:Engineering"]="Als Ingenieur, der mit hochexplosiven Sprengstoffen arbeitet, könnt Ihr Steinsegels Hingabe an die Steigerung der Feuerkraft seines Panzers würdigen.",["profession:Mining"]="Als Bergmann auf der Suche nach exotischer, brennbarer Erde könnten Euch Steinsegels Gerüchte über seltenes Erz unter der Erde verlockend erscheinen.",["race:Dwarf"]="Als zwergischer Gebirgsjäger oder Mechaniker könnt Ihr stolz darauf sein, einem Piloten bei Stahlrosts Depot zu helfen, das Arsenal von Khaz Modan zu verbessern.",["race:Gnome"]="Als gnomischer Erfinder könnt Ihr Pilot Steinsegels Drang schätzen, Belagerungswaffen über die üblichen Sicherheitsgrenzen hinaus zu verbessern."},sec={{t="Der Ehrgeiz eines Tüftlers",b="Pilot Langbart oder Gebirgsjäger Kadrell schicken Euch womöglich los, um Euch Steinsegels Vorschlag anzuhören. Der ehrgeizige Pilot will die Schlagkraft seiner Belagerungsmaschine erhöhen, und seine Pläne haben sich in Eisenschmiede und Loch Modan herumgesprochen."},{t="Auf zu Stahlrosts Depot",b="Auf dem Testgelände und Aufmarschplatz direkt östlich von Kharanos sucht Steinsegel Schürfer, die nach seltenem, instabilem Erz suchen sollen. Er glaubt, dass es die Feuerkraft seines Panzers erheblich steigern kann."}},faq={{q="Wer bietet diese Quest an?",a="Pilot Langbart in Eisenschmiede oder Gebirgsjäger Kadrell an der Straße in Loch Modan können Euch zu Pilot Steinsegel schicken.",al={"questgeber","wer startet steinsegels suche","wo gibt es die quest"}},{q="Wo kann ich Pilot Steinsegel finden?",a="Pilot Steinsegel befindet sich bei Stahlrosts Depot in Dun Morogh, ein kurzes Stück den Weg nordöstlich von Kharanos entlang.",al={"steinsegel standort","wo ist pilot steinsegel","stahlrosts depot steinsegel"}},{q="Was braucht Pilot Steinsegel?",a="Pilot Steinsegel tüftelt gern an seiner Belagerungsmaschine. Er sucht seltene Mineralvorkommen, um die Feuerkraft der Munition seines Panzers zu steigern.",al={"steinsegels ziel","warum sucht steinsegel hilfe","was will steinsegel"}},{q="Welche Quest folgt auf diese?",a="Nachdem Ihr Euch bei Pilot Steinsegel im Depot gemeldet habt, schickt er Euch auf die Suche nach Incendicite, einem instabilen Erz in den Feuchtgebieten.",al={"nächste quest","steinsegel folgequest","was kommt nach steinsegels suche"}},{q="Ist diese Quest nur für die Allianz?",a="Ja. Pilot Steinsegel und seine Kontakte dienen dem Militär von Eisenschmiede und der Allianz.",al={"kann die horde steinsegels suche machen","fraktionsvoraussetzung"}},{q="Warum interessiert sich das Depot für Erze aus der Wildnis?",a="Zwergische Ingenieure und Panzerpiloten experimentieren mit Brandmischungen, Pyrotechnik und instabilen Elementen. Sie suchen einen Vorteil für ihre Kriegsmaschinen im Kampf gegen Troggs, dark irons und wilde Bestien.",al={"warum erz für die belagerungsmaschine","zwerg panzer schießpulver"}}},fx={["51f66015"]={q="Warum schicken Euch die Auftraggeber zu Pilot Steinsegel?",a="Sowohl Pilot Langbart als auch Gebirgsjäger Kadrell wissen, dass Pilot Steinsegel besessen davon ist, an seiner Belagerungsmaschine herumzubasteln, und ständig versucht, deren Feuerkraft zu erhöhen. Als Gerüchte über ein seltenes, explosives Erz, das Steinsegel aufspüren möchte, zu ihnen durchdrangen, dachten sie sofort daran, einen umherstreifenden Abenteurer in seine Richtung zu weisen, anstatt seinen rastlosen Ehrgeiz unbeantwortet zu lassen.",al={"warum zu steinsegel schicken","warum will kadrell dass das getan wird","langbart motiv"}},["96f84a87"]={q="Warum brauchen sie einen Abenteurer, anstatt sich selbst darum zu kümmern?",a="Pilot Langbart hat seine eigenen Maschinen und Angelegenheiten zu betreuen, während Gebirgsjäger Kadrell damit beauftragt ist, Loch Modan zu patrouillieren und gegen Bedrohungen zu verteidigen. Die Untersuchung entfernter Gerüchte über exotisches Erz für einen Panzer-Enthusiasten erfordert jemanden mit Wanderstiefeln und Freizeit, was einen fähigen Reisenden zum idealen Späher für Steinsegels Ambitionen macht.",al={"warum schickt ihr mich","warum nicht langbart oder kadrell","warum ein abenteurer nötig"}}},fp="18,137,21.206.0,29.181.0,22.115.0,33.97.0,31.132.0,28.115.0,28.82.0,41.194.0"}
P.entries["quest:468"] = {n="Meldung bei Gebirgsjäger Felsgar",s="Bei Dun Algaz bereitet Gebirgsjäger Rockgar eine Expedition ins Sumpfland vor. Gebirgsjäger Kadrell schickt Euch von Loch Modan nach Norden zu ihm ins durchnässte Tiefland am Pass zwischen der Zwergenheimat und den nördlichen Gebieten.",h="Bei Dun Algaz bereitet Gebirgsjäger Rockgar eine Expedition ins Sumpfland vor.",kw={"dun algaz","eisenschmiede","kadrell","loch modan","gebirgsjäger","rockgar","erkundung","sumpfland"},ang={["faction:Alliance"]="Als Reisender der Allianz helft Ihr mit der Sicherung von Dun Algaz, den Landweg zum Hafen von Menethil offen zu halten. Er ist der wichtigste westliche Hafen der Allianz in den Östlichen Königreichen.",["race:Dwarf"]="Als Zwerg helft Ihr durch die Unterstützung Eurer Gebirgsjägerkameraden, die Landverbindung zwischen dem Kernland von Eisenschmiede und den zwergischen Besitzungen im Sumpfland zu erhalten."},sec={{t="Der Weg zum Nordtor",b="Dun Algaz durchquert den nördlichen Gebirgskamm zwischen Loch Modan und dem morastigen Sumpfland. Händler, Boten und Militärabteilungen nutzen diese befestigte Route zwischen Eisenschmiede und den Siedlungen der Allianz weiter nördlich. Während die Spannungen an den Grenzen zunehmen, überwacht Gebirgsjäger Kadrell die Straße und sucht zähe Freiwillige für die nördlichen Außenposten."},{t="Ein Auftrag gerät aus dem Ruder",b="Gebirgsjäger Kadrell schickt Rekruten los und erwartet eine gewöhnliche Erkundungsexpedition. Doch bei Dun Algaz bereitet sich Gebirgsjäger Rockgar auf offene Kämpfe vor, nicht auf eine friedliche Erkundung. Feindliche Truppen blockieren den Pass, und aus der Erkundung wird ein erbitterter Kampf um die Sicherung des Spießrutenlaufs."}},faq={{q="Wer gibt den Befehl, sich bei Rockgar zu melden?",a="Gebirgsjäger Kadrell gibt den Befehl. Er ist in Thelsamar gegenüber dem Gasthof Zum Starkbier-Lager auf der anderen Straßenseite stationiert und überwacht die Hauptstraße zum Gebirgspass.",al={"wer startet meldung bei gebirgsjäger felsgar","questgeber rockgar","kadrell quest"}},{q="Wo finde ich Gebirgsjäger Rockgar?",a="Gebirgsjäger Rockgar ist nördlich von Loch Modan an der Straße stationiert und bewacht den Eingang zu den Tunneln von Dun Algaz.",al={"rockgar standort","wo ist rockgar","gebirgsjäger rockgar fundort"}},{q="Warum ist dieser Auftrag durch Dun Algaz so wichtig?",a="Dun Algaz ist die wichtigste Landverbindung zwischen Loch Modan und dem Sumpfland. Diese Route freizuhalten schützt den Nachschub und militärische Nachrichten der Allianz und sichert die Reise zum Hafen von Menethil und darüber hinaus.",al={"warum nach dun algaz","dun algaz bedeutung","sumpfland route"}},{q="Was geschieht nach dem Treffen mit Gebirgsjäger Rockgar?",a="Rockgar zieht Euch sofort für Algaz Gauntlet hinzu. Die Erkundungsexpedition ist zu einem blutigen Kampf gegen feindliche Truppen geworden, die die Gebirgstunnel blockieren.",al={"was folgt auf meldung bei rockgar","rockgar folgequest","nächste quest nach rockgar"}},{q="Welche Stufe sollten Abenteurer für diesen Auftrag haben?",a="Dieser Auftrag richtet sich an erfahrene Reisende etwa auf Stufe zwanzig bis einundzwanzig. Sie schließen ihre Aufgaben in Loch Modan ab und bereiten sich darauf vor, den Gefahren des Sumpflands zu trotzen.",al={"rockgar queststufe","stufe für dun algaz","wann ins sumpfland"}},{q="Ist diese Quest für Charaktere der Horde verfügbar?",a="Nein. Die Eisenschmiede Mountaineers stehen treu zu König Magni Bronzebart und der Allianz. Nur Reisende der Allianz können den Auftrag annehmen.",al={"kann die horde diese quest machen","horde meldung bei rockgar"}}},fx={["8a14b66e"]={q="Warum möchte Gebirgsjäger Kadrell, dass dies getan wird?",a="Gebirgsjäger Kadrell ist entlang der nördlichen Straße in Loch Modan stationiert und weiß, dass Gebirgsjäger Rockgar fähige Freiwillige für eine kritische Aufklärungsmission in das Sumpfland sammelt. Indem er abgehärtete Reisende in Richtung Dun Algaz lenkt, hilft Kadrell sicherzustellen, dass die nördlichen Gebirgspässe überwacht bleiben und der Außenposten die zusätzliche Hilfe erhält, die er dringend benötigt.",al={"warum zu rockgar schicken","kadrell motiv","warum freiwilliger dun algaz"}}},fp="29,240,26.348.0,19.279.1,41.155.0,37.123.0,51.196.0,47.166.1,56.159.0,44.135.0"}
P.entries["quest:4681"] = {n="An Land gespült",s="Tote Meerestiere an der Küste der Dunkelküste haben Gwennyth Bly'Leggonde zu einer beunruhigenden Untersuchung veranlasst. Sie dient dem Tempel des Mondes in Darnassus und sucht nach der Ursache für die Strandungen und Todesfälle.",h="Tote Meerestiere an der Küste der Dunkelküste haben Gwennyth Bly'Leggonde zu einer beunruhigenden...",kw={"auberdine","gestrandetes tier","dunkelküste","darnassus","gwennyth bly'leggonde","meeresschildkröte","meeresschildkrötenüberreste","teldrassil","tempel des mondes"},ang={["class:Druid"]="Als Druide könnt Ihr das Massensterben und die ziellose Flucht der uralten Meerestiere der Dunkelküste als Zeichen von Verderbnis oder einem gestörten Gleichgewicht der Natur um Teldrassil deuten.",["class:Priest"]="Als Priester unterstützt Ihr die Priesterinnen von Elune im Tempel des Mondes. Sie wachen über das spirituelle Wohl und das Wohlergehen der Natur im Norden Kalimdors.",["race:NightElf"]="Als Nachtelf kennt Ihr Auberdine als Tor zwischen Teldrassil und dem Festland. Hinweise darauf, dass die Meeresbewohner vor Eurer neuen Heimat fliehen, sind ein beunruhigendes Omen."},sec={{t="Eine beunruhigende Flut",b="Tote Meerestiere säumen die Strände und Untiefen der Dunkelküste und stellen die Nachtelfen von Auberdine vor ein Rätsel. Gwennyth Bly'Leggonde hat bereits ein gestrandetes Tier am Strand untersucht. Nun bittet sie Euch, westlich der Docks nahe einem gesunkenen Schiff zu tauchen und die Knochen einer gewaltigen Meeresschildkröte zu untersuchen. Diese Überreste werden ihr bei ihrem Bericht an den Tempel des Mondes helfen."},{t="Flucht vom Weltbaum",b="Gwennyth Bly'Leggonde hofft, genügend materielle Beweise für einen offiziellen Bericht an die Priesterinnen von Elune in Darnassus zu sammeln. Ihre ersten Erkenntnisse deuten darauf hin, dass die Meerestiere möglicherweise vor etwas auf offener See fliehen. Die Gefahr könnte in den Gewässern um Teldrassil liegen."}},faq={{q="Warum werden an der Dunkelküste Meerestiere an Land gespült?",a="Die Ursache ist weiterhin unbekannt. Gwennyth braucht Proben der gestrandeten Tiere für einen Bericht an den Tempel des Mondes und um ihre Forschung fortzusetzen.",al={"warum sterben schildkröten","gestrandete tiere dunkelküste","warum stranden wale"}},{q="Wer ist Gwennyth Bly'Leggonde?",a="Gwennyth Bly'Leggonde ist eine Nachtelfenforscherin in Auberdine, die dem Tempel des Mondes in Darnassus Bericht erstattet. Sie dokumentiert das gehäufte Auftreten toter und gestrandeter Meerestiere entlang der Küste der Dunkelküste.",al={"gwennyth","forscherin auberdine","questgeber an land gespült"}},{q="Wo liegt das Skelett der Meeresschildkröte?",a="Das Skelett der Meeresschildkröte liegt auf dem Meeresgrund genau westlich der Docks von Auberdine, nahe dem Wrack eines gesunkenen Schiffes vor der Dunkelküste.",al={"fundort schildkrötenüberreste","wo schildkrötenskelett","knochen der meeresschildkröte"}},{q="Was hat der Tempel des Mondes damit zu tun?",a="Der Tempel des Mondes leitet die ökologischen und spirituellen Angelegenheiten der Nachtelfen. Gwennyth braucht materielle Proben für einen offiziellen Bericht an die Priesterinnen über das seltsame Massensterben.",al={"warum interessiert sich darnassus","rolle des tempels des mondes","beteiligung der priesterinnen von elune"}},{q="Gibt es noch weitere gestrandete Tiere zu finden?",a="Ja. Gwennyth sagt, dass entlang der Dunkelküste gestrandete Tiere liegen, und bittet Euch, den Sand nach Überresten weiterer gestrandeter Ungetüme abzusuchen.",al={"weitere gestrandete meerestiere","weitere quests zu meerestieren","dunkelküste gestrandetes ungetüm"}},{q="Was unterscheidet die beiden Quests „An Land gespült“?",a="In der ersten Quest „An Land gespült“ sollt Ihr ein Tier untersuchen, das an einem nahen Strand gestrandet ist. Die Folgequest schickt Euch westlich der Docks, um das Skelett einer Meeresschildkröte unter Wasser zu untersuchen.",al={"an land gespült teil eins gegenüber teil zwei","zwei quests an land gespült","questreihe an land gespült"}}},fx={["6f0a7268"]={q="Warum möchte Gwennyth Bly'Leggonde, dass die Meeresschildkrötenüberreste untersucht werden?",a="Gwennyth Bly'Leggonde untersucht die toten und gestrandeten Meerestiere entlang der Dunkelküste. Sie bittet Euch, Proben von der skelettierten Schildkröte westlich von Auberdine zu bergen, damit sie einen Bericht bei The Temple of the Moon in Darnassus einreichen kann.",al={"gwennyth bly'leggonde motiv","warum die schildkröte untersuchen","warum will gwennyth das"}},["23091480"]={q="Wozu dienen die Meeresschildkrötenüberreste?",a="Die Überreste dienen als wichtige wissenschaftliche und spirituelle Beweise für die Nachtelfen. Gwennyth Bly'Leggonde und The Temple of the Moon beabsichtigen, die Knochen auf Anzeichen von Krankheit, Verderbnis oder Trauma zu untersuchen. Diese Proben ermöglichen es Forschern in Darnassus, zusammenzusetzen, warum große Meerestiere stranden oder vor der Küste sterben, was der Priesterschaft hilft, die umfassendere ökologische Bedrohung zu verstehen, der die Küsten von nördlich Kalimdor gegenüberstehen.",al={"zweck der meeresschildkrötenüberreste","wozu dienen meeresschildkrötenüberreste","warum meeresschildkrötenüberreste"}}},fp="13,199,17.357.0,26.263.1,50.146.0,29.197.0,41.138.0,54.172.0,41.146.0,62.168.0"}
P.entries["quest:469"] = {n="Tägliche Lieferung",s="Im Sumpfland führt Tägliche Lieferung gegerbte Krokiliskenhäute zum Hafen von Menethil. Einar Steingriff bittet Reisende auf dem Weg in die Stadt, sie zu einem örtlichen Gerber zu bringen.",h="Im Sumpfland führt Tägliche Lieferung gegerbte Krokiliskenhäute zum Hafen von Menethil.",kw={"krokiliskenhäute","einar steingriff","james halloran","hafen von menethil","sida","gerber","sumpfland"},ang={["faction:Alliance"]="Als Reisender der Allianz kommt Ihr durch den Hafen von Menethil, das Tor zur See zwischen dem Herrschaftsgebiet von Eisenschmiede und den nördlichen Kontinenten. Krokiliskenleder hilft dabei, örtliche Wachen und Hafenarbeiter auszurüsten.",["race:Dwarf"]="Als Zwerg treibt Ihr Handel in den Niederungen des Sumpflands, weit entfernt von Eisenschmiede. Einars häuslicher Ärger hält ihn in den Marschen, wo er Krokilisken jagt und Reisende mit seinen Häuten losschickt."},sec={{t="Ein widerwilliger Kurier",b="Einar Steingriff jagt im Sumpfland, besonders die aggressiven Krokilisken entlang der Wasserwege. Ihre Häute sind wertvoll, doch sie zum Hafen von Menethil zu bringen bedeutet, nach Hause zu gehen. Seine Ehe mit Sida steckt in einer Krise, daher bleibt Einar lieber draußen, als ihr gegenüberzutreten. Er gibt seine Pakete Reisenden mit, die in die Stadt ziehen."},{t="Handel in Menethil",b="James Halloran gerbt Häute im Hafen von Menethil. Örtliche Jäger bringen ihm Leder für Stiefel und Waren, die sich für Händler und Seeleute eignen, die den Hafen passieren. Einar ist seit einer Woche fort, und Halloran vermutet, dass ein Streit mit Sida die Lieferung durch andere erklärt. Er fragt sich, ob seine eigene Frau eingreifen und Frieden mit ihr schließen sollte."}},faq={{q="Warum liefert Einar Steingriff die Häute nicht selbst?",a="Einar sagt, seine Frau Sida sei in letzter Zeit schlecht gelaunt. Er bleibt im Sumpfland und bittet vorbeikommende Reisende, seine Lieferungen in den Hafen von Menethil zu bringen, um ihrem Zorn zu entgehen.",al={"warum versteckt sich einar","einar ärger mit seiner frau","warum geht einar nicht nach hause"}},{q="Wer ist James Halloran?",a="James Halloran gerbt Leder im Hafen von Menethil. Er kauft rohe Felle und Häute von örtlichen Fallenstellern, gerbt sie und verkauft dann Stiefel und fertige Lederwaren.",al={"halloran gerber","wer ist james halloran"}},{q="Wer ist Sida?",a="Sida ist Einar Steingriffs Frau und lebt im Hafen von Menethil. Wegen ihrer schlechten Laune bleibt Einar in den Marschen, statt nach Hause zu gehen.",al={"einars frau","wer ist sida"}},{q="Was für Häute werden transportiert?",a="Das Bündel enthält Krokiliskenhäute von den großen Reptilien aus den Sümpfen und Wasserwegen des Sumpflands.",al={"welche häute","tägliche lieferung gegenstände"}},{q="Weiß Halloran, warum Einar den Hafen von Menethil meidet?",a="Ja. Wenn Ihr das Bündel übergebt, sagt Halloran, dass Einar seit fast einer Woche nicht mehr vorbeigekommen ist. Er vermutet Ärger mit Sida als Ursache.",al={"weiß halloran bescheid","reaktion des gerbers"}},{q="Wo findet diese Lieferung statt?",a="Die Lieferung beginnt bei Einar Steingriff an einer Straße im Sumpfland und endet in James Hallorans Werkstatt im Hafen von Menethil an der Westküste.",al={"wo abgeben","tägliche lieferung ort"}}},fp="14,162,19.337.0,20.337.0,54.182.0,22.153.0,12.136.0,41.99.0,57.132.0,36.148.0"}
P.entries["quest:47"] = {n="Tauschhandel mit Goldstaub",s="Tauschhandel mit Goldstaub ist ein frühes Kopfgeld, das von Remy \"Zweifach\" aus Goldhain angeboten wird. Der nervöse Händler bezahlt Abenteurer dafür, den Kobolden, die die Minen im Wald von Elwynn heimsuchen, rohen Goldstaub abzunehmen. Obwohl dies ehrliche Arbeit für unerfahrene Reisende bietet, deuten Remys merkwürdige Verbindungen darauf hin, dass hinter seinem Geschäft mehr steckt als bloße Metallverarbeitung.",h="Tauschhandel mit Goldstaub ist ein frühes Kopfgeld, das von Remy \"Zweifach\" aus Goldhain angeboten wird.",kw={"wald von elwynn","tiefenschachtmine","goldstaub","goldhain","jaspismine","kobold","remy zweifach"},ang={["class:Rogue"]="Remys gedämpftes Verhalten und das Abzeichen ungenannter \"Geschäftspartner\" verströmen den unverkennbaren Hauch von Untergrundsyndikaten, die unter Goldhains friedlicher Oberfläche agieren.",["faction:Alliance"]="Die Tatsache, dass Elwynns lebenswichtige Gold- und Mineralvorkommen von wilden Kobolden statt von königlichen Bergleuten gehalten werden, verdeutlicht, wie erschöpft die Streitkräfte des Königreichs wahrhaftig sind.",["profession:Mining"]="Bergleute, die die Tiefenschachtmine und die Jaspismine durchkämmen, werden feststellen, dass Kobolde direkt an den reichsten Kupferadern hängen, was ihre Beseitigung zu einer Notwendigkeit für den Erzabbau macht."},sec={{t="Ein Ort voller Taschen und Spitzhacken",b="Goldhain liegt an den Kreuzwegen des Walds von Elwynn, wo sich Händler, Stadtwachen und müde Reisende begegnen. Unter ihnen ist Remy \"Zweifach\", ein zwielichtiger Geselle, dessen anhaltende Angewohnheit, seine Worte zu wiederholen, ein scharfes Auge für Profit verbirgt. Anstatt kostspielige Bergbauteams anzuheuern, um Rohmineralien zu fördern, nutzt Remy die umherziehenden Abenteurer aus, die das Gasthaus \"Zur Höhle des Löwen\" durchqueren. Sein Vorschlag ist einfach: Holt den Goldstaub zurück, der vom Ungeziefer der Region gehortet wird, und tauscht ihn direkt gegen Münzen ein."},{t="Die Koboldbeute",b="Kobolde haben Elwynns wertvollste unterirdische Ausgrabungen völlig überrannt, namentlich die Tiefenschachtmine im Süden und die Jaspismine im Nordosten. Während sie sich auf der Suche nach ihren geliebten Kerzen und glänzenden Schmuckstücken durch die Dunkelheit hacken, sammeln diese rattenartigen Tunnelgräber Rückstände und Späne unraffinierten Erzes in ihren Beuteln an. Sie zurückzudrängen dient den Interessen des Königreichs, doch das Sammeln ihres Staubs macht die Schädlingsbekämpfung zu einem lukrativen Geschäft."},{t="Schatten hinter dem Tresen",b="Obwohl Remy behauptet, aus rein kaufmännischen Gründen erstklassige Münzen zu zahlen, enthalten seine Belohnungen subtile Warnungen. Sobald er seinen Staub erhält, steckt er seinen Helfern ein kleines Abzeichen zu, das seine \"Geschäftspartner\" repräsentiert. In einem Elwynn, das zunehmend von organisierten Banditen, unbezahlten Steinmetzen und heimlichen Netzwerken im Schatten von Sturmwind erdrückt wird, könnten Remys verschwiegene Mittelsmänner Pläne für dieses Gold haben, die weit über den gewöhnlichen Dorfhandel hinausgehen."}},faq={{q="Wer ist Remy \"Zweifach\"?",a="Remy \"Zweifach\" ist ein exzentrischer örtlicher Händler vor dem Gasthaus \"Zur Höhle des Löwen\" in Goldhain. Er ist dafür bekannt, die Enden seiner Sätze zu wiederholen, kauft wandernden Abenteurern wertvolle Materialien ab und pflegt Verbindungen zu zwielichtigen Geschäftspartnern.",al={"remy zweifach","wer vergibt tauschhandel mit goldstaub","remy in goldhain"}},{q="Woher haben Kobolde Goldstaub?",a="Kobolde verbringen ihr Leben damit, sich durch Elwynns Mineraladern zu graben, wie etwa jene in der Tiefenschachtmine und der Jaspismine. Während sie auf der Suche nach Schätzen und Kerzenwachs durch Fels kratzen und graben, sammeln sich rohe Goldflocken und Staub in ihren Taschen und Beuteln an.",al={"warum haben kobolde goldstaub","woher kommt goldstaub"}},{q="Wo finde ich die von Remy erwähnten Minen?",a="Kobolde, die Goldstaub bei sich tragen, sind vor allem in und um die Tiefenschachtmine südlich von Goldhain sowie in der Jaspismine nordöstlich nahe der Grenze zum Holzfällerlager des Osttals zu finden.",al={"wo sind die minen","wo gibt es kobolde elwynn"}},{q="Warum lässt Sturmwind zu, dass Kobolde ihre Minen kontrollieren?",a="Da König Varian Wrynn verschollen ist und das Haus der Adligen sich weigert, Truppen für die Randgebiete abzustellen, ist die Stadtwache von Sturmwind furchtbar überdehnt. Lokale Garnisonen können die Minen nicht säubern, sodass sie von Kobolden heimgesucht bleiben, während unabhängige Reisende die Kämpfe austragen.",al={"warum werden die minen nicht bewacht","warum verlor sturmwind die minen"}},{q="Wird Goldstaub für die Schmiedekunst oder zum Handel verwendet?",a="In seiner rohen Form, wie ihn die Kobolde tragen, ist Goldstaub zu fein und unrein für gewöhnliche Schmiedearbeiten. Stattdessen wird er als Rohware an Händler wie Remy verkauft, die ihn über ihre eigenen privaten Kanäle zusammenführen und raffinieren.",al={"wofür wird goldstaub verwendet","kann man goldstaub verhüttet werden"}}},fx={["9de6b9cb"]={q="Warum will Remy \"Zweifach\" Goldstaub?",a="Remy agiert als geschäftstüchtiger lokaler Opportunist, der wertvolle Ressourcen billig aufkauft. Anstatt sich selbst in die gefährlichen, von Kobolden verseuchten Tunnel zu wagen, verlässt er sich auf abenteuerlustige Reisende, um den rohen Goldstaub von dem Ungeziefer zu extrahieren. Er erzielt schnellen Gewinn durch den Handel mit Edelmetallen und nutzt die Geschäfte, um Euch mit Gold und Verbindungen zu seinen Partnern zu belohnen.",al={"warum will remy goldstaub","remy zweifach motiv","warum goldstaub remy"}},["3c82823a"]={q="Warum braucht Remy Euch, anstatt den Goldstaub selbst zu holen?",a="Remy ist ein Händler und Geschäftemacher, kein Frontkämpfer, und er zieht es eindeutig vor, sicher in Goldhain zu bleiben, anstatt in dunkle Minenschächte vorzudringen. Währenddessen ist die lokale Garnison von Sturmwind bereits überlastet damit, mit grassierenden Banditen, Gnollen und dem allgemeinen Koboldproblem fertigzuwerden, was wenig Interesse oder Arbeitskraft für das Sammeln von verstreutem Mineralstaub übrig lässt. Das macht unabhängige Mercenaries wie Euch zur idealen Lösung.",al={"warum holt remy keinen goldstaub","warum braucht remy mich","warum nicht die sturmwindwachen"}},["27e84318"]={q="Warum tragen Kobolde in den Minen von Elwynn Goldstaub?",a="Kobolde sind natürliche Höhlengräber, die verlassene und leicht verteidigte Minen in ganz Elwynn überrannt haben, einschließlich Tiefenschachtmine und Jaspismine. Getrieben von einem obsessiven Drang zu graben und glänzende Schmuckstücke zu horten, meißeln sie Tag und Nacht an den unterirdischen Adern. Der lose Goldstaub sammelt sich an ihren Pfoten, Kleidern und in ihren Beuteln, während sie durch die Schächte krabbeln.",al={"warum sind kobolde in den minen","warum haben kobolde goldstaub","kobolde tiefenschachtmine"}}},fp="18,190,27.355.0,18.319.0,26.320.1,24.201.0,31.207.0,45.178.0,56.235.0,45.205.0"}
P.entries["quest:470"] = {n="Stochern im Schlamm",s="Im Hafen von Menethil will Sida ihre Tasche von dem Schleim zurück, der sie verschlungen hat. Sie floh aus Eisenbarts Grabmal, als üble Schleime die Hügelgräber füllten.",h="Im Hafen von Menethil will Sida ihre Tasche von dem Schleim zurück, der sie verschlungen hat.",kw={"dun modr","eisenbarts grabmal","hafen von menethil","schleim","schleimbedeckte tasche","sida","sidas tasche","sumpfland"},ang={["faction:Alliance"]="Der Hafen von Menethil ist die wichtigste Versorgungsader der Allianz durch das tückische Sumpfland. Wer verängstigten Bürgern hilft, wahrt Sicherheit und Ordnung in diesem lebenswichtigen Hafen.",["race:Dwarf"]="Eisenbarts Grabmal birgt die sterblichen Überreste eines verehrten zwergischen Ahnen. Für einen Getreuen von Bronzebeard sind üble Schleime, die die Hügelgräber entweihen, ein Affront."},sec={{t="Eine panische Flucht",b="Sida lebt im Hafen von Menethil und reist oft nach Nordosten ins Sumpfland, um an Eisenbarts Grabmal ihre Ehrerbietung zu erweisen. Bei ihrem letzten Besuch füllten üble, tropfende Schleime das uralte Hügelgrab. In Panik schleuderte sie ihre Umhängetasche nach einem von ihnen. Der Schleim verschlang die Tasche im Ganzen und verschaffte Sida gerade genug Zeit, um zurück in die Hafenstadt zu fliehen. Nun bittet sie Reisende, danach zu suchen."},{t="Schlamm an Eisenbarts Grabmal",b="Nahe der umkämpften Festung Dun Modr birgt Eisenbarts Grabmal die sterblichen Überreste eines sagenumwobenen Zwergenhelden. Die Verderbnis im umliegenden Marschland zieht gestaltlose, ätzende Schleime an, die alles auf ihrem Weg verschlingen. Sida kann sich nicht erinnern, welche Kreatur ihre Habseligkeiten verschlungen hat. Durchsucht das Grabgelände und schlagt Euch durch die kriechende Fäulnis, um ihre durchnässte Umhängetasche zu finden."}},faq={{q="Wer ist Sida?",a="Sida ist eine Reisende der Allianz, die im Hafen von Menethil lebt. Sie besucht regelmäßig Eisenbarts Grabmal im Sumpfland, wo Schleime sie kürzlich in Gefahr brachten.",al={"sida","wer vergibt die quest","wer ist sida"}},{q="Wo liegt Eisenbarts Grabmal?",a="Eisenbarts Grabmal liegt im nordöstlichen Sumpfland, südlich von Dun Modr. Ätzende Sumpfschleime suchen die Gegend um das steinerne Hügelgrab heim.",al={"eisenbarts grabmal standort","wo ist ironbeard","wo sind die schleime"}},{q="Welcher Schleim hat Sidas Tasche verschlungen?",a="Sida geriet während des Angriffs in Panik und kann die Schleime nicht auseinanderhalten. Jeder Schleim, der außerhalb von Eisenbarts Grabmal umherstreift, könnte ihre Tasche verschlungen haben.",al={"welcher schleim","schleim mit tasche","wo ist die tasche"}},{q="Warum besuchte Sida Eisenbarts Grabmal?",a="Sida besucht Eisenbarts Grabmal jede Woche, um dem dort bestatteten uralten Zwerg ihren Respekt zu zollen. Schleime unterbrachen ihre friedliche Tradition.",al={"warum besucht sida das grabmal","sidas wöchentlicher besuch"}},{q="Was geschieht, nachdem die Tasche geborgen wurde?",a="Wenn Ihr die schleimige Umhängetasche zum Hafen von Menethil zurückbringt, schüttet Sida den Inhalt auf den Boden, um ihre Habseligkeiten herauszuholen. Das ruinierte Behältnis ekelt sie an, also bietet sie die vom Schleim befreite Tasche demjenigen an, der sie geborgen hat.",al={"was war in der tasche","tasche als belohnung"}},{q="Hat das mit den Zwergen von Dark Iron in der Nähe zu tun?",a="Dun Modr, unmittelbar nördlich des Grabmals, ist in einen Konflikt mit dem Klan Dark Iron verwickelt. Die Schleime an Eisenbarts Grabmal sind wilde Sumpfräuber aus den feuchten, faulenden Winkeln des Sumpflands, keine zwergischen Soldaten.",al={"verbindung zu dark iron","verbindung zu dun modr"}}},fx={["93b8c575"]={q="Warum braucht Sida ihre Tasche zurück?",a="Während ihres wöchentlichen Besuchs bei Eisenbarts Grabmal wurde Sida von üblen Schlämmen hinterhalten. In Panik warf sie ihr Bündel auf eine der Kreaturen, um sie abzulenken und ihre Flucht zu ermöglichen. Obwohl sie die Begegnung unverletzt überstand, ist der Inhalt ihrer Tasche für sie unersetzlich, weshalb sie verzweifelt versucht, ihn wiederzuerlangen, bevor die säurehaltigen Monstrositäten ihn vollständig verdaut haben.",al={"warum will sida ihre tasche","sida tasche motiv","warum sidas tasche holen"}},["11eb18cd"]={q="Was ist in Sidas Tasche?",a="Sida verrät nie offen, was genau in der Tasche aufbewahrt wurde, und besteht nur darauf, dass sie dringend den Inhalt zurückerhalten muss. Wenn Ihr sie zurückbringt, leert sie sofort den schleimigen Inhalt auf den Boden und schöpft ihn auf, während sie Euch den ruinierten, mit Schleim bedeckten Behälter als Belohnung überreicht, da sie für das verschmutzte Leder keine Verwendung mehr hat.",al={"was ist in sidas tasche","sidas tasche inhalt","wofür ist sidas tasche"}},["7f85207a"]={q="Was sind die Schlämme bei Eisenbarts Grabmal?",a="Die Schlämme, die um Eisenbarts Grabmal kriechen, sind gedankenlose, gefräßige Monstrositäten, die typisch für die feuchten, verfallenden Ecken des Sumpflandes sind. Angezogen von der versunkenen Ruine und verrottender Materie nahe Dun Modr, verzehren sie alles Organische auf ihrem Weg – einschließlich ahnungsloser Besucher wie Sida.",al={"schlämme bei eisenbarts grabmal","warum sind schlämme bei eisenbarts grabmal","eisenbarts grabmal schlämme"}}},fp="24,138,18.363.0,26.362.0,12.157.0,26.135.0,32.137.0,39.135.0,40.217.1,48.207.0"}
P.entries["quest:471"] = {n="Lehrlingspflichten",s="Im Hafen von Menethil braucht James Halloran riesige Krokiliskenhäute für sein Handwerk. Sein Lehrling wurde in den Sümpfen schwer zugerichtet, deshalb bittet Halloran Reisende, die gefährliche Jagd zu übernehmen.",h="Im Hafen von Menethil braucht James Halloran riesige Krokiliskenhäute für sein Handwerk.",kw={"lehrlingspflichten","krokilisk","riesiger krokilisk","james halloran","lederverarbeitung","hafen von menethil","murlokhütten","sumpfland","häute junger krokilisken"},ang={["class:Hunter"]="Riesige Krokilisken sind gefährliche Raubtiere der Sümpfe. Sie aufzuspüren stellt Euer Geschick auf die Probe, Euch durch trübe Gewässer und zwischen angriffslustigen Wildtieren hindurch zurechtzufinden.",["faction:Alliance"]="Der Hafen von Menethil verbindet Khaz Modan mit dem Rest der Allianz. Der Hafen ist auf die Sicherheit und Selbstversorgung seiner örtlichen Handwerker angewiesen."},sec={{t="Eine harte Lehrzeit",b="James Halloran schickte seinen jungen Lehrling in die Sümpfe des Sumpflands, um riesige Krokilisken zu häuten. Als der Junge nicht zurückkehrte, suchte Halloran nach ihm und fand ihn schwer zugerichtet. Die Handwerker im Hafen von Menethil sind auf Materialien aus dem Umland angewiesen, doch die Moore machen diese Arbeit gefährlich."},{t="Häute und Vergeltung",b="Die Hebamme des Ortes glaubt, dass Hallorans Lehrling überleben wird, obwohl ihn der Angriff ein Bein gekostet hat. Halloran braucht Häute für sein Handwerk und will Rache an den Bestien, die den Jungen zerfleischt haben, den er wie einen Sohn liebt. Er bittet Euch, der Küste nach Norden zu folgen, an den Murlokhütten vorbei, und die riesigen Krokilisken zu jagen."}},faq={{q="Wer ist James Halloran?",a="James Halloran ist Lederverarbeiter und Gerber im Hafen von Menethil. Die Häute der Wildtiere des Sumpflands liefern ihm das Material für sein Handwerk.",al={"james halloran","wer vergibt lehrlingspflichten","gerber in menethil"}},{q="Was ist mit Hallorans Lehrling geschehen?",a="Halloran schickte seinen Lehrling in den Sumpf, um riesige Krokiliskenhäute zu sammeln. Die Bestien richteten den Jungen schwer zu und rissen ihm ein Bein ab, doch die Hebamme des Ortes erwartet, dass er überlebt.",al={"was geschah mit dem lehrling","wer wurde schwer zugerichtet","bein des lehrlings"}},{q="Wo sind die riesigen Krokilisken zu finden?",a="Riesige Krokilisken durchstreifen die Sümpfe und die nördliche Küste des Sumpflands, jenseits der Murloksiedlungen an der Küste nördlich vom Hafen von Menethil.",al={"wo sind riesige krokilisken","krokilisken fundort sumpfland","riesige krokilisken fundort"}},{q="Welcher vorherige Auftrag führt zu dieser Aufgabe?",a="Halloran bat Reisende zunächst, in „Häute junger Krokilisken“ kleinere Krokilisken zu jagen. Jetzt bittet er sie, die riesige Variante zu jagen, die seinen Lehrling verwundet hat.",al={"voraussetzung für lehrlingspflichten","vorheriger auftrag","krokilisken auftragsreihe"}},{q="Warum will Halloran nach dem Unglück noch immer die Häute?",a="Halloran braucht Häute für sein Handwerk und ist wütend auf die Bestien, die den Jungen verstümmelt haben, den er wie einen Sohn liebt. Ein Reisender, der bereit ist, sie zu jagen, ist ihm willkommen.",al={"warum werden häute gebraucht","hallorans beweggründe"}},{q="Bietet Halloran Euch eine Lehrstelle an?",a="Nachdem er Eure Arbeit gesehen hat, scherzt Halloran kurz darüber, Euch als neuen Lehrling aufzunehmen, verwirft den Gedanken dann aber wieder. Ihr seid viel zu alt, sagt er, und offensichtlich für ein anderes Schicksal bestimmt.",al={"ist eine lehre möglich","angebot einer lehrstelle"}}},fx={af87185e={q="Wofür ist Riesige Krokiliskenhaut?",a="James Halloran ist ein Gerber und Lederer mit Sitz in Hafen von Menethil. Er stellt strapazierfähige Waren aus den Häuten lokaler Bestien her, und das robuste, dicke Leder, das von den riesigen Krokilisken des Sumpflandes geerntet wird, ist der Rohstoff für sein Handwerk.",al={"verwendung von riesiger krokiliskenhaut","warum häute","halloran krokiliskenhaut"}},["4e327c1e"]={q="Was sind die riesigen Krokilisken?",a="Sie sind gewaltige, räuberische Reptilien, die in den Sümpfen und Küstengewässern des Sumpflandes heimisch sind. Äußerst territorial und notorisch aggressiv, leben sie nördlich entlang der Küste hinter den Murloc-Lagern und stellen eine tödliche Gefahr für jeden Reisenden oder angehenden Kürschner dar, der zu nah heranwandert.",al={"riesige krokilisken sumpfland","was sind riesige krokilisken","krokilisken im sumpfland"}},["42f5987b"]={q="Warum braucht James Halloran Euch, anstatt es selbst zu erledigen?",a="Hallorans eigener Lehrling wurde zerfleischt und verlor ein Bein, als er versuchte, die Aufgabe zu erledigen, was bewies, dass sie für einen gewöhnlichen Handwerker viel zu gefährlich ist. Da sein Lehrling unter der Obhut der örtlichen Hebamme in kritischem Zustand ist, bleibt Halloran in Hafen von Menethil, um seinen Laden zu hüten und auf den Jungen aufzupassen, und wendet sich an einen bewaffneten Abenteurer, um die Bestien sicher auszudünnen.",al={"warum kann halloran keine häute holen","warum ich halloran","warum einen abenteurer schicken"}}},fp="19,182,22.291.0,21.305.0,22.118.0,39.165.0,39.127.0,43.157.0,57.157.0,42.187.0"}
P.entries["quest:472"] = {n="Der Fall von Dun Modr",s="Bei Dun Modr haben Streitkräfte der Dunkeleisen die nördliche Festung und ihre Garnison zerschlagen. Im Hafen von Menethil bittet ein schwer verwundeter Überlebender einen Abenteurer der Allianz, im Norden herauszufinden, ob Langzopf der Grimmige oder andere Verteidiger überlebt haben.",h="Bei Dun Modr haben Streitkräfte der Dunkeleisen die nördliche Festung und ihre Garnison zerschlagen.",kw={"dunkeleisen","dun modr","harlo barnabas","langzopf der grimmige","hafen von menethil","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Dun Modrs Fall sichere Reisen auf dem Landweg zwischen Eisenschmiede und den nördlichen Unternehmungen der Allianz im Arathihochland unterbindet. Der Korridor ist nun der Sabotage schutzlos ausgeliefert.",["race:Dwarf"]="Als Zwerg empfindet Ihr das Gemetzel an Eisenschmiedes Gebirgsjägern und die Schändung Dun Modrs durch Klanverwandte aus dem Süden womöglich als bittere persönliche Beleidigung. Blut muss mit Blut vergolten werden."},sec={{t="Ein nördliches Bollwerk fällt",b="Seit Generationen bewacht Dun Modr den Norden von Khaz Modan sowie die lebenswichtige Straße und Brücke über den Thandol-Übergang. Sie verbinden das Sumpfland mit dem Arathihochland. Nach einem Hinterhalt an der Brücke zieht sich die Garnison zurück, um sich innerhalb der Festung neu zu formieren. Bevor die Verteidiger ihre Verteidigungsanlagen wiederherstellen können, schlagen übermächtige Streitkräfte der Dunkeleisen zu und treiben sie in eine verzweifelte Flucht."},{t="Eine verzweifelte Flucht",b="Harlo Barnabas, ein junger Verteidiger, wird schwer verwundet, als ihn während des Rückzugs eine verirrte Axt im Rücken trifft. Im Glauben, er sei dem Tode geweiht, binden Langzopf der Grimmige und die verbliebenen Truppen Barnabas auf ihr letztes überlebendes Pferd und schicken ihn nach Süden zum Hafen von Menethil. Er überlebt und erwacht in der Hafentaverne, geplagt von Schuldgefühlen, weil er überlebt hat. Er weiß nicht, ob einer seiner Kameraden lebend entkommen ist."},{t="Der grimmige Rest",b="Langzopf der Grimmige lebt noch immer in den nördlichen Sümpfen nahe der eroberten Festung und hält eine angeschlagene Handvoll Überlebender zusammen. Der erfahrene Kommandant ist erleichtert zu erfahren, dass Harlo seine schwere Verwundung überlebt hat. Doch Dun Modr bleibt fest in den Händen der Dunkeleisen. Halsabschneider und Saboteure besetzen seine Hallen und bedrohen den Korridor zwischen Khaz Modan und den Menschenlanden im Norden."}},faq={{q="Was ist mit Dun Modr geschehen?",a="Dunkeleisenzwerge überrannten Dun Modr, nachdem die Garnison am nahe gelegenen Thandol-Übergang in einen Hinterhalt geraten war. Sie schlugen zu, bevor die Verteidiger die Stadt sichern konnten, und vernichteten den Großteil des Regiments.",al={"warum ist dun modr zerstört","wer hat dun modr angegriffen","dun modr geschichte"}},{q="Wer ist Harlo Barnabas?",a="Harlo Barnabas ist ein Soldat aus Eisenschmiede, der in Dun Modr stationiert war und dessen Fall nur knapp überlebte. Eine geworfene Axt traf ihn beim Rückzug im Rücken, weshalb sein Kommandant ihn auf das einzige überlebende Pferd der Garnison band und zur medizinischen Versorgung nach Süden zum Hafen von Menethil schickte.",al={"wer ist harlo","harlo barnabas geschichte","verwundeter soldat in menethil"}},{q="Wo befindet sich Langzopf der Grimmige?",a="Kommandant Langzopf der Grimmige fand Zuflucht in der Wildnis unmittelbar vor dem besetzten Dun Modr, nahe der nördlichen Hauptstraße zum Thandol-Übergang.",al={"wo ist langzopf","langzopfs aufenthaltsort","langzopf finden"}},{q="Warum ist Dun Modr strategisch wichtig?",a="Dun Modr ist die nördlichste Siedlung und Befestigung des Sumpflands. Es bewacht den südlichen Zugang zum Thandol-Übergang, der einzigen Landbrücke, die Khaz Modan mit dem Arathihochland und Lordaeron verbindet.",al={"warum ist dun modr wichtig","verbindung zum thandol-übergang"}},{q="Wer sind die Angreifer von Dun Modr?",a="Die Angreifer sind Dunkeleisenzwerge vom Dunkeleisenklan im Süden. Sie sind nach Norden ins Sumpfland vorgestoßen, um Infrastruktur wie den Thandol-Übergang zu zerstören und Eisenschmiedes Gebiet mit Angriffen zu bedrängen.",al={"wer hat dun modr erobert","dunkeleisen im sumpfland"}},{q="Was geschieht, nachdem Langzopf gefunden wurde?",a="Nachdem Ihr bestätigt habt, dass Langzopf lebt, und ihm berichtet habt, dass Barnabas überlebt hat, gewinnt Langzopf Euch für einen düsteren Rachefeldzug gegen die Streitkräfte der Dunkeleisen, die Dun Modrs Ruinen besetzen.",al={"der fall von dun modr fortsetzung","was folgt auf den fall von dun modr"}}},fx={b6379bde={q="Warum möchte Harlo Barnabas, dass Ihr Longbraid findet?",a="Harlo entkam nur knapp dem Massaker bei Dun Modr mit dem Leben, nachdem ihm ein verirrter Axtschlag in den Rücken getroffen hatte, als das Regiment den Rückzug blies. Obwohl er sicher in Hafen von Menethil aufwachte, wird er vom Schicksal seiner Kameraden gequält. Er weigert sich, die Hoffnung aufzugeben, dass sein Kommandant, Longbraid, die Flucht überlebt hat, und muss dringend wissen, ob noch ein Überrest seiner Einheit gegen die Dunkeleisen steht.",al={"warum longbraid finden","harlo barnabas motiv","warum zu dun modr schicken"}},["67f9d3fa"]={q="Warum kann Harlo Barnabas nicht selbst nach Longbraid suchen?",a="Harlos Wunden sind viel zu schwer für eine Reise. Nachdem er während der chaotischen Flucht aus Dun Modr eine Axt der Dunkeleisen in den Rücken bekommen hatte, schafften es seine überlebenden Kameraden gerade noch, ihn auf ihr letztes verbliebenes Reittier zu hieven, bevor er das Bewusstsein verlor. Er ist erst kürzlich in Hafen von Menethil aufgewacht, schwach und mitgenommen, was ihn völlig darauf angewiesen macht, dass fähige Abenteurer in seinem Auftrag in die feindseligen Sümpfe nach Norden marschieren.",al={"warum braucht harlo mich","warum kann harlo nicht gehen","warum nicht harlo barnabas"}}},fp="16,227,25.368.0,18.386.0,16.384.1,26.185.0,21.271.0,36.141.1,40.202.0,34.199.0,37.177.1"}
P.entries["quest:4722"] = {n="Gestrandete Meeresschildkröte",s="An der Dunkelküste liegt eine Gestrandete Meeresschildkröte in der Brandung, während Murlocs ihre Überreste plündern. Naturforscher aus Auberdine suchen brauchbare Proben, die sie zur Untersuchung nach Darnassus schicken können.",h="An der Dunkelküste liegt eine Gestrandete Meeresschildkröte in der Brandung, während Murlocs ihre Überreste...",kw={"auberdine","gestrandet","dunkelküste","darnassus","gwennyth bly'leggonde","murloc","überreste","meeresschildkröte"},ang={["class:Druid"]="Als Druide seht Ihr gestrandete Meereslebewesen und aasfressende Murlocs als Zeichen eines ökologischen Ungleichgewichts entlang der Dunkelküste. Das verlangt nach genauer Beobachtung und Heilung.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass unerklärliche Strandungen uralter Meeresgeschöpfe auf tiefgreifendere Störungen in Kalimdors Gewässern hindeuten. Forscher in Auberdine und Darnassus untersuchen jeden angespülten Leviathan."},sec={{t="Ein gestrandeter Leviathan",b="Tote Meeresschildkröten werden an der Dunkelküste angespült, oder sie stranden in ihrer Verwirrung. Ihre Überreste locken bald Aasfresser an. Murlocs der Greymist haben primitive Lager um das Skelett dieser Schildkröte errichtet und schneiden Fleisch und Panzer heraus. Doch Knochen, Panzer oder Gewebe können in den Überresten noch unversehrt sein."},{t="Feldforschung für Darnassus",b="Gwennyth Bly'Leggonde arbeitet in Auberdine als Feldforscherin und dokumentiert ungewöhnliche Meereslebewesen und Störungen entlang der Küste. Nachtelfen betrachten gestrandete Tiere mit Ehrfurcht und wissenschaftlicher Neugier. Geeignete Überreste werden katalogisiert und für den Versand an Gelehrte in Darnassus vorbereitet. Sie wollen herausfinden, warum so viele Riesen des offenen Meeres angespült werden."}},faq={{q="Warum gibt es an der Dunkelküste so viele gestrandete Meereslebewesen?",a="Starke Küstenströmungen und aufgewühltes Wasser treiben Treibgut und sterbende Meerestiere auf den Sand der Dunkelküste. Nachtelfische Gelehrte vermuten, dass Störungen in den Tiefen des Ozeans Meereslebewesen in flache Gewässer treiben, weshalb örtliche Naturforscher jeden angespülten Kadaver untersuchen.",al={"warum tote meeresschildkröte","dunkelküste gestrandete geschöpfe","warum gestrandet"}},{q="Wer möchte die Meeresschildkrötenüberreste haben?",a="Gwennyth Bly'Leggonde, eine nachtelfische Forscherin in Auberdine, sammelt angespülte Proben für Naturforscher und Gelehrte in Darnassus.",al={"bei wem abgeben","gwennyth auberdine","wo meeresschildkrötenüberreste abgeben"}},{q="Warum versammeln sich Murlocs um die Schildkröte?",a="Murlocs der Greymist verwerten, was an die Strände gespült wird. Eine riesige Schildkröte bietet reichlich Fleisch, zähe Haut und Knochen für Werkzeuge und Unterstände.",al={"murlocs bei schildkröte","greymist aasfresser","murloclager"}},{q="Was geschieht mit den Proben, sobald Gwennyth sie erhält?",a="Gwennyth verpackt brauchbare Gewebe- und Skelettproben für den Transport über das Meer nach Darnassus. Gelehrte und Priesterinnen untersuchen sie, um den Zustand und das Verhalten des Küstenökosystems zu überwachen.",al={"was macht darnassus mit überresten","schildkrötenproben forschung"}},{q="Ist dies das einzige gestrandete Geschöpf an der Küste?",a="Nein. An der langen Küste der Dunkelküste liegen mehrere gestrandete Meeresschildkröten und gewaltige Meeresungeheuer. Einige liefern Forschungsproben für die Gelehrten von Auberdine.",al={"andere gestrandete tiere","mehr tote schildkröten","angespülte geschöpfe"}},{q="Sind Meeresschildkröten den Nachtelfen heilig?",a="Nachtelfen verehren Kalimdors heimische Tiere als Teil des natürlichen Gleichgewichts unter Elune und den wilden Göttern. Meeresschildkröten sind keine einzelnen göttlichen Avatare, doch ihr unerwarteter Tod und ihre Strandungen warnen vor schwerwiegenden ökologischen Problemen.",al={"nachtelfen schildkröten","druiden und schildkröten"}}},fx={d6ac85f8={q="Warum will Gwennyth die Meeresschildkrötenüberreste?",a="Gwennyth Bly'Leggonde sammelt Exemplare für Gelehrte in Darnassus, die die verseuchte Küstenlinie der Dunkelküste untersuchen. Eine Flut von toten Meerestieren ist angespült worden, und durch die Untersuchung von nicht kontaminiertem Gewebe von gestrandeten Kreaturen, bevor Aasfresser sie ruinieren, hoffen Forscher herauszufinden, welche Krankheit oder Störung im Meer diese großartigen Bestien an die Küste trieb, um zu sterben.",al={"warum meeresschildkrötenüberreste mitnehmen","warum schildkrötenüberreste untersuchen","gwennyth schildkröte motiv"}}},fp="18,163,20.301.0,28.353.0,57.265.0,33.128.0,43.137.0,56.191.0,50.152.0,42.228.0"}
P.entries["quest:4723"] = {n="Gestrandete Meereskreatur",s="Am Nebelrand liegt ein riesiger Meeresdrescher gestrandet, während Murlocs von seinem Kadaver fressen. In Auberdine sammelt Gwennyth Bly'Leggonde Proben für Nachtelfenforscher in Darnassus, die herausfinden wollen, warum Tiefseeriesen an Land gespült werden.",h="Am Nebelrand liegt ein riesiger Meeresdrescher gestrandet, während Murlocs von seinem Kadaver fressen.",kw={"auberdine","gestrandet","knochen","dunkelküste","gwennyth bly'leggonde","nebelrand","murloc","meereskreatur","drescher"},ang={["class:Druid"]="Als Druide seht Ihr in dem gestrandeten Riesen womöglich ein alarmierendes Zeichen für eine Störung des natürlichen Gleichgewichts im verhüllten Meer.",["race:NightElf"]="Für Nachtelfen deuten Strandungen entlang der Dunkelküste auf Probleme in den umliegenden Gewässern hin. Naturforscher in Auberdine und Darnassus gehen der Sache nach, bevor noch mehr Meereslebewesen verenden."},sec={{t="Ein Riese im Flachwasser",b="Am Nebelrand liegen zwischen Schiffswracks und angeschwemmten Trümmern nun auch gewaltige Drescherüberreste. Das Tier stellt die Tierwelt der Untiefen der Dunkelküste weit in den Schatten. Seine Größe deutet darauf hin, dass es von jenseits des verhüllten Meeres stammt, aus Gewässern fern der ruhigen Wasser hier. Murlocs wimmeln auf dem Kadaver, doch ihnen fehlen die Kraft und die Koordination, um eine solche Kreatur zu erlegen. Etwas anderes tötete das Raubtier, bevor das Meer es an Land trug."},{t="Forschungen in Darnassus",b="In Auberdine koordiniert Gwennyth Bly'Leggonde die Bergung von Knochen und biologischen Proben der gestrandeten Meeresriesen der Dunkelküste. Nachtelfenforscher in Darnassus hoffen, die Überreste zeigen, ob Krankheit, Störungen in der Tiefsee oder arkane Verderbnis die Riesen auf die tödlichen Sandstrände treiben."}},faq={{q="Was für ein Tier wurde an den Strand gespült?",a="Ein riesiger Drescher wurde an Land gespült, weit größer als die Drescher, die gewöhnlich nahe den Stränden der Dunkelküste zu sehen sind.",al={"was ist das für eine kreatur","was ist das tote monster","welches tier liegt tot am strand"}},{q="Haben die Murlocs ihn getötet?",a="Nein. Murlocs wimmeln um den Kadaver, um davon zu fressen, doch selbst in großen Gruppen sind sie zu schwach, um ein solches Tiefseetier zu jagen.",al={"haben murlocs den drescher getötet","haben murlocs die meereskreatur getötet"}},{q="Warum stranden Meereskreaturen an der Dunkelküste?",a="Die Ursache ist unbekannt. Nachtelfenforscher vermuten, dass Störungen im Meer, Krankheiten oder ökologische Belastungen Tiefseekreaturen in die flache Brandung treiben, wo sie stranden und sterben.",al={"warum sterben drescher","warum stranden kreaturen"}},{q="Wer ist Gwennyth Bly'Leggonde?",a="Gwennyth Bly'Leggonde ist eine Nachtelfenforscherin in Auberdine. Sie sammelt Knochen und biologische Proben gestrandeter Tiere entlang der Dunkelküste zur Untersuchung in Darnassus.",al={"wer ist gwennyth","wer nimmt die knochen in auberdine"}},{q="Wohin werden die gesammelten Knochen geschickt?",a="Die gesammelten Knochen gehen an Gelehrte und Naturforscher in Darnassus, wo sie auf anatomische und magische Hinweise untersucht werden.",al={"wohin gehen die knochen","was macht auberdine mit knochen"}},{q="Wo liegt dieser Kadaver?",a="Der Kadaver liegt am Sandstrand des Nebelrands, an der Westküste der Dunkelküste.",al={"fundort des kadavers","wo ist die gestrandete meereskreatur"}}},fp="20,225,23.432.0,20.301.0,42.100.0,24.122.0,59.187.0,29.165.0,35.122.0,30.84.0"}
P.entries["quest:4725"] = {n="Gestrandete Meeresschildkröte",s="An der Dunkelküste ruht eine zerbrochene Kutsche auf dem Panzer einer Gestrandeten Meeresschildkröte. Murlocs der Greymist sammeln sich um den gewaltigen Kadaver.",h="An der Dunkelküste ruht eine zerbrochene Kutsche auf dem Panzer einer Gestrandeten Meeresschildkröte.",kw={"auberdine","gestrandet","kutsche","dunkelküste","greymist","gwennyth bly'leggonde","naga","meeresschildkröte","seltsam markierter kasten"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr den Schildwachen von Auberdine, Erkenntnisse aus gestrandeten Kreaturen zu gewinnen. Ihre Funde geben Aufschluss über Murloc-Plagen und organisierte Überfalltrupps der Naga.",["race:NightElf"]="Als Nachtelf könnt Ihr erkennen, dass Nachschubtiere der Naga an der Dunkelküste angespült werden. Die uralten Feinde Eures Volkes verstärken ihre Brückenköpfe nahe Darnassus."},sec={{t="Ein Tier im Geschirr",b="An der nebligen Küste der Dunkelküste findet Ihr eine zerbrochene Kutsche, die auf den Panzer einer riesigen Meeresschildkröte geschnallt ist. Viele Meereskreaturen wurden an dieser Küste angespült, doch diese Schildkröte trug eine Last. Ihre Treiber trieben sie auf den Strand. Nun liegt die Kutsche verlassen in der Brandung."},{t="Aasfresser im Flachwasser",b="Murlocs der Greymist umschwärmen die Überreste der Schildkröte. Zwischen verrottendem Fleisch und zusammengetragenem Holz haben sie sich einen Unterschlupf eingerichtet. Zwischen ihrem Unrat und dem zerbrochenen Kutschengestell liegt ein markierter Behälter. Die früheren Herren der Schildkröte haben ihn dort zurückgelassen."},{t="Nachschubwege der Naga",b="Nachdem Ihr den markierten Behälter zu Gwennyth Bly'Leggonde in Auberdine gebracht habt, offenbaren seine Naga-Zeichen die Wahrheit. Das Geschirr entspricht dem der Nachschubkutschen, mit denen die Naga Waffen und Kriegsmaterial aus den Tiefen des Ozeans transportieren. Die Überreste der Schildkröte zeigen, dass die Naga in den Norden der Dunkelküste vordringen. Der geborgene Behälter wird zur Untersuchung nach Darnassus geschickt."}},faq={{q="Warum befindet sich eine Kutsche auf dem Panzer der Meeresschildkröte?",a="Die Naga spannen riesige Meeresschildkröten als Lasttiere und Belagerungsbestien ein. Ihre Kutschen bringen Vorräte und Waffen aus den Tiefen an die Dunkelküste.",al={"schildkrötenkutsche","warum kutsche auf schildkröte","eingespannte schildkröte"}},{q="Was befindet sich in der Kutsche?",a="Ein Seltsam markierter Kasten liegt in der zerbrochenen Kutsche. Seine Runen kennzeichnen ihn als Eigentum der Naga, und Gelehrte in Auberdine schicken ihn zur eingehenden Untersuchung nach Darnassus.",al={"schildkrötenkasten","seltsam markierter kasten","kasten in schildkrötenkutsche"}},{q="Warum versammeln sich Murlocs um die Schildkröte?",a="Murlocs der Greymist leben entlang der Küste und durchstöbern Schiffswracks und gestrandete Kadaver. Sie haben die Überreste der Schildkröte als Nahrung und Unterschlupf in Besitz genommen.",al={"murlocs um schildkröte","murlocs der greymist schildkröte","warum fressen murlocs schildkröte"}},{q="Wer untersucht die gestrandeten Kreaturen an der Dunkelküste?",a="Gwennyth Bly'Leggonde in Auberdine leitet die Untersuchung der gestrandeten Meereskreaturen. Sie katalogisiert die Relikte und seltsamen Materialien, die zwischen ihren Überresten gefunden werden.",al={"wer untersucht gestrandete meereskreaturen","forscherin in auberdine","gwennyth bly'leggondes aufgabe"}},{q="Wie unterscheidet sich diese Schildkröte von anderen gestrandeten Kreaturen an der Dunkelküste?",a="Anders als viele Kreaturen, die krank oder in Not an Land gespült werden, war diese Schildkröte zum Transport von Fracht eingespannt. Die Naga trieben sie auf den Strand.",al={"andere gestrandete schildkröten","warum ist diese schildkröte anders","schildkrötenrätsel dunkelküste"}},{q="Was geschieht mit dem markierten Kasten nach Auberdine?",a="Gwennyth Bly'Leggonde hält die Entdeckung in Auberdine fest und schickt den Kasten der Naga nach Darnassus. Die Anführer der Elfen dort untersuchen die wachsende Bedrohung an ihren nördlichen Grenzen.",al={"wohin kommt der kasten","kasten nach darnassus geschickt","was macht auberdine mit dem kasten"}}},fx={["4b167599"]={q="Warum die markierte Kiste zu Gwennyth Bly'Leggonde bringen?",a="Im Gegensatz zu anderen Kadavern von Meerestieren, die entlang der Dunkelküste angespült werden, wurde diese Schildkröte eindeutig als Lasttier eingespannt. Der verlassene Wagen und seine seltsam markierte Fracht deuten eher auf eine organisierte, feindselige Macht hin als auf natürliche Strandungen. Das Relikt zu Gwennyth Bly'Leggonde in Auberdine zu bringen, erlaubt es den Nachtelf-Forschern, die Markierungen zu studieren, die schleichenden Bedrohungen an der Küste einzuschätzen und ihre Erkenntnisse an Darnassus weiterzuleiten.",al={"warum kiste nach auberdine bringen","warum schildkrötenkiste zu gwennyth bringen","motiv der gestrandeten schildkrötenkiste"}}},fp="18,136,18.264.0,26.227.0,17.365.1,50.149.0,28.148.0,43.143.0,47.166.0,73.134.0,47.168.0"}
P.entries["quest:4727"] = {n="Gestrandete Meeresschildkröte",s="An der Nordküste der Dunkelküste liegt eine Gestrandete Meeresschildkröte, von nahen Greymist-Murlocs unberührt. Eine Probe geht für den Tempel des Mondes an Gwennyth Bly'Leggonde in Auberdine. Naturforscher und Priesterinnen wollen erfahren, warum gewaltige Meereskreaturen angespült werden und Aasfresser sie unberührt lassen.",h="An der Nordküste der Dunkelküste liegt eine Gestrandete Meeresschildkröte, von nahen Greymist-Murlocs...",kw={"auberdine","gestrandet","kadaver","dunkelküste","greymist","gwennyth bly'leggonde","murloc","überreste","meeresschildkröte","tempel des mondes"},ang={["class:Druid"]="Als Druide beobachtet Ihr die Küste aufmerksam. Dass Murlocs die Toten unberührt lassen, könnte auf eine unnatürliche Verderbnis in den Gewässern hindeuten.",["class:Priest"]="Als Priester lasst Ihr allen Lebewesen Elunes Fürsorge zuteilwerden. Ihr untersucht Todesfälle, die das Gleichgewicht der Natur stören.",["race:NightElf"]="Als Nachtelf seht Ihr an der Dunkelküste unerklärliche Todesfälle und Aasfresser, die Meereskreaturen meiden. Diese Zeichen deuten auf ein wachsendes Ungleichgewicht in den Landen der Kaldorei hin."},sec={{t="Ein seltsames Fernbleiben",b="Greymist-Murlocs bevölkern die Nordküste der Dunkelküste und suchen nach Nahrung, die aus dem verhüllten Meer angespült wird. Doch die Knochen der gewaltigen Schildkröte liegen weitgehend unberührt da. Wer die Küste erforscht, fragt sich, ob die Murlocs sie übersehen haben oder aus einem unbekannten Grund meiden."},{t="Erforschung der Küste",b="In Auberdine sammelt Gwennyth Bly'Leggonde für den Tempel des Mondes Proben von gestrandeten Meeresschildkröten. Die Nachtelfenpriesterinnen untersuchen Störungen in den Gewässern der Dunkelküste. Skelettfragmente könnten ihnen helfen herauszufinden, ob Krankheit, Magie oder gefährliche Meeresräuber die uralten Kreaturen töten."}},faq={{q="Was ist die Gestrandete Meeresschildkröte?",a="Die Überreste einer uralten Meeresschildkröte wurden im Norden der Dunkelküste angespült. Ihr ungewöhnliches Auftauchen und das Fernbleiben von Aasfressern haben die Aufmerksamkeit der Nachtelfen geweckt.",al={"schildkrötenkadaver","meeresschildkrötenskelett","was ist diese schildkröte"}},{q="Warum meiden die Murlocs den Kadaver?",a="Greymist-Murlocs suchen gewöhnlich an Strandkadavern nach Nahrung, doch diese Überreste haben sie unberührt gelassen. Niemand weiß, ob sie die Schildkröte übersehen haben oder aus einem unbekannten Grund meiden. Gwennyth hält es für wichtig, ihr Fernbleiben bei der Untersuchung der Überreste im Gedächtnis zu behalten.",al={"warum fressen murlocs sie nicht","greymist-murlocs schildkröte","warum den kadaver meiden"}},{q="Wer ist Gwennyth Bly'Leggonde?",a="Gwennyth Bly'Leggonde ist eine Nachtelfenforscherin in Auberdine. Sie sammelt für den Tempel des Mondes Proben von Meerestieren, die an der Dunkelküste gestrandet sind.",al={"gwennyth auberdine","wer will schildkrötenüberreste","schildkrötenquest abgeben"}},{q="Warum interessiert sich der Tempel des Mondes für gestrandete Meereskreaturen?",a="Der Tempel des Mondes untersucht gestrandete Meereskreaturen, weil ungewöhnlich viele an der Dunkelküste sterben. Seine Priesterinnen untersuchen Proben, um herauszufinden, was den Meeren schadet.",al={"tempel des mondes schildkröte","warum schildkröten untersuchen","elune meerestiere"}},{q="Wo liegt diese bestimmte Meeresschildkröte?",a="Der Kadaver liegt an der Nordküste der Dunkelküste, nahe dem Gebiet, das Greymist-Murlocstämme bewohnen.",al={"wo ist die schildkröte","gestrandete meeresschildkröte fundort","schildkröte dunkelküste"}},{q="Gibt es weitere gestrandete Kreaturen an der Dunkelküste?",a="Ja. Mehrere gestrandete Meereskreaturen, darunter riesige Meeresschildkröten, liegen an den Ufern der Dunkelküste. Die Forscher von Auberdine untersuchen, warum diese Meeresriesen sterben.",al={"andere gestrandete kreaturen","weitere meeresschildkröten","beached sea creature quests"}}},fp="18,290,17.253.0,22.300.0,31.170.0,41.248.0,29.143.0,65.170.0,44.101.0,50.174.0"}
P.entries["quest:4728"] = {n="Gestrandete Meereskreatur",s="An der Dunkelküste liegt ein riesiger Meeressäuger angespült neben einer verlassenen Ausgrabungsstätte. Sein Kadaver und verstreute Werkzeuge locken Murlocs und Reisende an.",h="An der Dunkelküste liegt ein riesiger Meeressäuger angespült neben einer verlassenen Ausgrabungsstätte.",kw={"auberdine","gestrandet","knochen","dunkelküste","explorer's league","gwennyth","murloc","meereskreatur"},ang={["faction:Alliance"]="Diese Entdeckung zeigt, wie Darnassus und die Explorer's League aus Eisenschmiede zusammenarbeiten, um Kalimdors Geheimnisse zu dokumentieren.",["race:Dwarf"]="Die verlassenen Werkzeuge gehören Euren Verwandten in der Explorer's League. Einheimische Murlocs vertrieben sie von ihrer Ausgrabungsstätte.",["race:NightElf"]="Der Tempel des Mondes ist zutiefst besorgt über die unnatürlich hohe Zahl gewaltiger Meereskreaturen, die sterben und an der heiligen Dunkelküste angespült werden."},sec={{t="Eine unterbrochene Ausgrabung",b="Im Sand der Dunkelküste liegt ein riesiger Meeressäuger, teilweise ausgeweidet und vom Meer gezeichnet. Eine verrostete Schubkarre und zurückgelassene Werkzeuge markieren den Ort, an dem eine systematische Untersuchung begann. Die Forscher gingen, bevor sie ihre Arbeit abschließen konnten."},{t="Die Liga und die Murlocs",b="Zwergische Feldforscher der Explorer's League untersuchten den Kadaver in der Dunkelküste. Ihre Arbeit endete, als einheimische Murlocs die Stätte überrannten, um sich am Aas zu bedienen. In Auberdine handelt Gwennyth Bly'Leggonde im Auftrag des Tempels des Mondes. Sie nimmt geborgene Knochenproben entgegen, um die unnatürlichen Strandungen entlang der Küste zu untersuchen."}},faq={{q="Was ist das für eine Kreatur am Strand?",a="Die Überreste stammen von einem riesigen Meeressäuger, der an der Dunkelküste angespült wurde. Niemand hat seine Art bestimmt. Seine Größe hat aasfressende Murlocs und zwergische Forscher angelockt.",al={"gestrandete meereskreatur identität","was ist dieser kadaver","was ist hier gestorben"}},{q="Wer hat die Werkzeuge und die Schubkarre zurückgelassen?",a="Zwergische Mitglieder der Explorer's League haben die Werkzeuge zurückgelassen. Sie begannen, die gestrandete Kreatur zu untersuchen, doch feindselige Küstenmurlocs vertrieben sie, bevor sie ihre Arbeit abschließen konnten.",al={"wer hat die werkzeuge zurückgelassen","verlassene schubkarre dunkelküste","wer hat hier gegraben"}},{q="Warum will Gwennyth Bly'Leggonde diese Knochen?",a="Gwennyth Bly'Leggonde sammelt Proben für den Tempel des Mondes in Darnassus. Die Nachtelfen untersuchen die seltsamen Todesfälle gewaltiger Meereskreaturen, die entlang der Dunkelküste angespült werden.",al={"warum will gwennyth knochen","tempel des mondes meereskreatur","auberdine meeresknochen"}},{q="Warum schleichen Murlocs um den Kadaver herum?",a="Murlocs kamen, um Fleisch und Speck vom Kadaver zu fressen. Sie vertrieben die zwergischen Gelehrten und verteidigen die Überreste nun für sich selbst.",al={"murlocs um kadaver","warum sind hier murlocs","aasfressende murlocs"}},{q="Ist die Explorer's League hier offiziell mit Auberdine verbündet?",a="Ja. Die Explorer's League gehört zur Allianz und ist in der Dunkelküste vertreten. Sie arbeitet mit den örtlichen Nachtelfenbehörden zusammen und teilt Berichte über ihre Entdeckungen und Untersuchungen an der Küste.",al={"explorer's league auberdine","zwerge in der dunkelküste","explorer's league allianz dunkelküste"}},{q="Gibt es noch andere gestrandete Kreaturen an der Dunkelküste?",a="Ja. An den Stränden der Dunkelküste wurden gewaltige Meerestiere und Skelettreste angespült. Sie deuten auf weitverbreitete Störungen in den Gewässern vor Kalimdor hin.",al={"weitere gestrandete kreaturen","andere kadaver dunkelküste","mehrere gestrandete meereskreaturen"}}},fp="20,144,19.202.0,26.317.0,41.169.0,42.168.0,48.189.0,44.138.0,63.191.0,60.159.0"}
P.entries["quest:473"] = {n="Meldung bei Hauptmann Starkfaust",s="Im Hafen von Menethil schickt Valstag Eisenkiefer bewährte Kämpfer zu Hauptmann Starkfaust, während sich die Bedrohung durch die Dragonmaw im Sumpfland ausbreitet. Der Hafen ist ein Militärstützpunkt der Allianz, und der Hauptmann leitet seine Verteidigung von der Burg aus.",h="Im Hafen von Menethil schickt Valstag Eisenkiefer bewährte Kämpfer zu Hauptmann Starkfaust, während sich die...",kw={"hauptmann starkfaust","dragonmaw","dun algaz","hafen von menethil","burg menethil","valstag eisenkiefer","war room","sumpfland"},ang={["class:Warrior"]="Als Krieger bringt Ihr die Kampfkraft mit, die Valstag Eisenkiefer sucht, wenn er erfahrene Frontkämpfer unter den Befehl von Hauptmann Starkfaust stellt.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass der Hafen von Menethil das wichtigste Tor für Waren und Verstärkungen zwischen den südlichen Königreichen und Khaz Modan ist. Überfälle der Orcs auf der Straße würden den Handel der Allianz lähmen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Verteidigung der Handelsverbindung zwischen dem Hafen von Menethil und den Toren von Eisenschmiede für die Sicherheit von Khaz Modan entscheidend ist."},sec={{t="Eine wachsende Bedrohung",b="Seit Jahren bewachen zwergische Gebirgsjäger die engen Pässe von Dun Algaz. Nun ist der Dragonmawklan jenseits von Loch Modan zurückgekehrt. Die Orcs drängen nach außen, errichten Lager und bedrohen die Marschen. Valstag Eisenkiefer weiß, dass die Sicherung des Passes nur der erste Schritt ist, um die Straße nach Eisenschmiede zu schützen."},{t="Der War Room von Menethil",b="Hauptmann Starkfaust leitet die Verteidigung des Hafens von Menethil vom War Room in Burg Menethil aus. Saboteure der Dunkeleisenzwerge, einheimische Bestien und Sumpfmurlocs bedrohen den Hafen. Deshalb verlässt sich der Hauptmann auf fähige Freiwillige, die den Gefahren jenseits der Mauern begegnen. Valstag schickt Euch, um direkte Befehle gegen die Kriegsmaschinerie der Dragonmaw auszuführen."}},faq={{q="Wer schickt mich zu Hauptmann Starkfaust?",a="Valstag Eisenkiefer, der in Burg Menethil im Hafen von Menethil stationiert ist, schickt Euch zu Hauptmann Starkfaust, nachdem Ihr Euch gegen die örtlichen Dragonmaw-Orcs bewährt habt.",al={"wer vergibt diese quest","questgeber","valstag eisenkiefer"}},{q="Wo befindet sich Hauptmann Starkfaust?",a="Hauptmann Starkfaust befindet sich in Burg Menethil im Hafen von Menethil, einer Stadt im westlichen Sumpfland. Er studiert taktische Karten im War Room der Burg.",al={"hauptmann starkfaust standort","wo ist starkfaust","menethil war room"}},{q="Warum haben die Dragonmaw-Orcs für Burg Menethil Vorrang?",a="Die Dragonmaw halten uralte Festungen im gesamten Sumpfland und bedrohen die Handelsstraßen zwischen dem Hafen von Menethil und Eisenschmiede. Ihre Streitkräfte drängen über Dun Algaz hinaus, und die Garnison kann ihre wachsenden Lager nicht ignorieren.",al={"warum gegen dragonmaw kämpfen","bedrohung durch dragonmaw","orcs im sumpfland"}},{q="Was geschieht nach der Meldung bei Hauptmann Starkfaust?",a="Nachdem Ihr Euch bei Hauptmann Starkfaust gemeldet habt, zieht er Euch zur Offensive gegen die Dragonmaw heran. Er schickt Euch in ihre Lager, um ihre Kriegsbanner im Sumpf niederzureißen.",al={"was kommt als nächstes","folgequest","nach meldung bei starkfaust"}},{q="Wer sind die Dragonmaw-Orcs im Sumpfland?",a="Die Dragonmaw sind Überreste der alten Horde, die während des Zweiten Krieges rote Drachen in Grim Batol versklavten. Grim Batol wurde zerschlagen, doch überlebende Kriegsbanden halten sich weiterhin in den Marschen verschanzt, überfallen Reisende und widersetzen sich der Herrschaft der Allianz.",al={"geschichte der dragonmaw","wer sind die dragonmaw","sumpfland orcs"}},{q="Warum sind die Kräfte im Hafen von Menethil so überlastet?",a="Der Hafen von Menethil wird ständig von wilden Sumpftieren, vordringenden Murlocs und feindlichen Dunkeleisenzwergen bedroht, die versuchen, den Hafen zu untergraben. Da die Garnisonstruppen die Mauern und Docks bewachen, verlässt sich Hauptmann Starkfaust auf auswärtige Streiter, um entfernte Außenposten der Orcs anzugreifen.",al={"verteidigung von menethil","warum sind die truppen beschäftigt","probleme im hafen"}}},fx={["9a52d26e"]={q="Warum möchte Valstag Eisenkiefer, dass ich bei Hauptmann Starkfaust Bericht erstatte?",a="Valstag erkennt, dass die Bedrohung durch den Drachenmalklan weit über den Pass bei Dun Algaz hinausgeht. Die Orcs werden im gesamten Sumpfland kühner, und Hauptmann Starkfaust organisiert die Verteidigung von Hafen von Menethil. Valstag schickt fähige Kämpfer direkt in den War Room, damit Starkfaust bewährte Veteranen dort einsetzen kann, wo die Garnison sie am meisten braucht.",al={"warum zu starkfaust schicken","valstag motiv","warum bei hauptmann starkfaust melden"}},["8cdd6c80"]={q="Warum braucht Valstag einen Abenteurer anstelle der lokalen Wachen?",a="Die Garnison in Burg Menethil ist stark damit beschäftigt, die Stadt und wichtige Gebirgspässe an mehreren Fronten zu verteidigen. Da der Drachenmalklan jenseits von Dun Algaz aggressive Stärke zeigt, können reguläre Truppen nicht für jede offensive Operation entbehrt werden. Valstag wählt Euch aus, weil Ihr Euch bereits im Kampf gegen die Orcs bewährt habt, was Euch genau zu dem erfahrenen Freiwilligen macht, den Hauptmann Starkfaust benötigt.",al={"warum ich","warum keine wachen benutzen","warum abenteurer rekrutieren"}}},fp="27,223,17.290.0,24.322.0,34.153.0,35.142.0,56.232.0,50.174.0,43.242.0,41.269.0"}
P.entries["quest:4730"] = {n="Gestrandete Meereskreatur",s="An der Dunkelküste liegt ein großer Meeressäuger halb aufgefressen im Sand. Murlocs scharen sich um ihn, und Priesterin Gwennyth Bly'Leggonde in Auberdine sucht Knochenproben, um zu erfahren, warum sanftmütige Meeresbestien am Ufer sterben.",h="An der Dunkelküste liegt ein großer Meeressäuger halb aufgefressen im Sand.",kw={"auberdine","gestrandete meereskreatur","dunkelküste","gwennyth bly'leggonde","murloc","meereskreaturknochen","teldrassil","tempel des mondes"},ang={["class:Druid"]="Für den Zirkel des Cenarius ist jede Veränderung unter den Meeresbewohnern ein düsteres Vorzeichen einer unnatürlichen Seuche, die die Tierwelt der Küste vergiftet.",["class:Priest"]="Der Tempel des Mondes leitet diese Untersuchung und sucht göttliche Einsicht in die Verderbnis, die Kalimdors Gewässer heimsucht.",["faction:Alliance"]="Der Schutz der Küsten um Auberdine hilft, die Schifffahrtswege der Allianz zwischen der Dunkelküste, Teldrassil und den Östlichen Königreichen zu sichern.",["race:NightElf"]="Für die Kaldorei verletzen diese Strandungen ihre Ehrfurcht vor der Harmonie der Natur. Die Gewässer rund um ihre neue Heimat Teldrassil geraten zunehmend in Unruhe."},sec={{t="Grausiger Fund am Ufer",b="Weit im Norden liegt an den einsamen Stränden der Dunkelküste ein großer Meeressäuger, verwesend und halb aufgefressen. Murlocs machen sich an seinen Knochen zu schaffen, bösartiger als gewöhnlich. Zu Lebzeiten waren diese Bestien sanftmütig, und ihr Tod beunruhigt die Küste ebenso wie die verseuchten Wälder im Landesinneren."},{t="Ungewöhnliche Strandung",b="Priesterin Gwennyth Bly'Leggonde sagt, diese sanftmütigen Säuger leben in den Gewässern rund um den Fuß von Teldrassil. Anders als aggressive Drescher waren sie nie dafür bekannt, sich auf die Felsen zu treiben. Der Tempel des Mondes sammelt Knochenproben, um zu erfahren, welche Verderbnis oder Bedrohung sie aus der Tiefe treibt."}},faq={{q="Was für eine Kreatur wurde hier angespült?",a="Die Überreste stammen von einem großen, sanftmütigen Meeressäuger, der gewöhnlich in den tiefen Gewässern rund um den Fuß von Teldrassil lebt. Diese friedlichen Riesen stranden normalerweise nicht.",al={"was ist das für ein tier","was ist die gestrandete kreatur","knochen eines meeresungeheuers"}},{q="Warum ist die Meereskreatur gestrandet?",a="Niemand weiß, warum die Meereskreatur gestrandet ist. Priesterin Gwennyth Bly'Leggonde sagt, solche Strandungen seien für diese Art unnatürlich, und Nachtelfenforscher vermuten, dass eine Störung oder Verderbnis im Meer sie verwirrt oder aus ihren Heimatgewässern vertreibt.",al={"warum ist es gestrandet","warum sterben meereskreaturen","strandungen an der dunkelküste"}},{q="Wer ist Gwennyth Bly'Leggonde?",a="Gwennyth Bly'Leggonde ist eine in Auberdine stationierte Priesterin des Tempels des Mondes. Sie koordiniert eine Untersuchung der Küstenlinie und sammelt Knochen, um das Leiden zu erforschen, das den örtlichen Meeresbewohnern schadet.",al={"wer gibt diese quest ab","wer ist gwennyth","priesterin in auberdine"}},{q="Warum versammeln sich Murlocs um den Kadaver?",a="Die Murlocs haben sich um den Kadaver versammelt, um eine leichte Mahlzeit zu ergattern. Diese Gruppe ist stärker und aggressiver als die Murlocs, die näher an Auberdine leben.",al={"warum sind hier murlocs","murlocs bei den knochen","murlocs am strand"}},{q="Wo lebt diese Kreatur normalerweise?",a="Diese Meeressäuger leben in den offenen Gewässern rund um Teldrassils gewaltige Äste und Wurzeln. Unter normalen Umständen nähern sie sich nur selten der Küste des Festlands.",al={"wo leben diese tiere","lebensraum der meeressäuger","meereskreaturen bei teldrassil"}},{q="Wie hängt dies mit anderen Strandungen an der Dunkelküste zusammen?",a="An der Dunkelküste wurden verschiedene Arten von Meeresbewohnern angespült, darunter fleischfressende Drescher und riesige Meeresschildkröten. Drescher sind von Natur aus ungestüm, doch die Strandungen sanftmütiger Säuger zeigen, dass die Störung Arten im gesamten Ökosystem der Küste betrifft.",al={"andere gestrandete meereskreaturen","gestrandeter drescher","beached sea turtle"}}},fp="20,216,30.254.0,26.305.0,37.170.0,38.269.0,29.194.0,43.144.0,39.145.0,53.259.0"}
P.entries["quest:4731"] = {n="Gestrandete Meeresschildkröte",s="An der Küste der Dunkelküste liegt eine Gestrandete Meeresschildkröte tot unter dem Wagen, den sie einst zog. Ein mit seltsamen Runen markierter Kasten liegt im Wrack.",h="An der Küste der Dunkelküste liegt eine Gestrandete Meeresschildkröte tot unter dem Wagen, den sie einst zog.",kw={"eschental","auberdine","gestrandete meeresschildkröte","dunkelküste","greymist","gwennyth bly'leggonde","murloc","naga","tempel des mondes"},ang={["class:Druid"]="Als Druide seht Ihr eine edle Meeresschildkröte, die zum Tragen von Kriegswaffen gezwungen und dann zwischen Aasfressern dem Verrotten überlassen wurde. Die Naga nehmen wenig Rücksicht auf wilde Tiere.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Auberdine und Darnassus auf Versorgungsrouten der Naga aufmerksam zu machen, die das nördliche Kalimdor bedrohen.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass es die Kaldorei empört, wenn die Naga Meereslebewesen zum Transport von Kriegsgütern einsetzen. Diese Spuren helfen dem Tempel des Mondes, Bedrohungen in Richtung Eschental zu verfolgen."},sec={{t="Ein Lasttier",b="Eine tote Meeresschildkröte liegt zwischen den uralten Knochen an der Küste der Dunkelküste. Zersplitterte Wagenbretter hängen an ihrem breiten Panzer. Sie wurde beim Transport von Fracht auf die Felsen getrieben und strandete nicht durch Krankheit oder Verwirrung. Ein Behälter mit eingeritzten, fremdartigen, schlangenähnlichen Zeichen liegt im Wrack, wo Aasfresser die Überreste verzehren."},{t="Der Einfall der Naga",b="In Auberdine erkennt Gwennyth Bly'Leggonde die Machart des Kastens als Arbeit der Naga. Die Naga schicken bei ihren Angriffen vom Wasser aus große Meeresbestien mit Vorräten und Waffen an Land. Das Wrack liegt an der südlichen Küste der Dunkelküste, und Gwennyth vermutet, dass die Schildkröte Vorräte nach Eschental brachte. Ihr Ende könnte bedeuten, dass die Naga weiter in das nördliche Kalimdor vorgedrungen sind."}},faq={{q="Warum trägt diese Meeresschildkröte einen Wagen auf dem Rücken?",a="Die Naga befestigten den Wagen an der Schildkröte und nutzten riesige Meeresschildkröten als lebende Lasttiere. Sie brachten Vorräte, Waffen und Kriegsmaterial aus den Tiefen des Meeres an Land.",al={"schildkrötenwagen","warum schildkröte einen wagen trägt","meeresschildkrötengeschirr"}},{q="Wer bewohnt derzeit die Überreste?",a="Mächtige Greymist-Murlocs haben den riesigen Panzer nach dem Tod der Schildkröte übernommen. Sie nutzen ihre ausgehöhlten Überreste als befestigten Unterschlupf am Meer.",al={"wer in der schildkröte lebt","greymist-murlocs schildkröte","was die schildkröte bewacht"}},{q="Wohin gehört der Seltsam markierte Kasten?",a="Bringt den Kasten zu Gwennyth Bly'Leggonde, einer Gesandten des Tempels des Mondes, die in Auberdine stationiert ist.",al={"wohin den kasten bringen","seltsam markierter kasten","markierten kasten abgeben"}},{q="Was bedeuten die Zeichen auf dem Kasten?",a="Die Zeichen sind die Schrift der Naga. Sie zeigen, dass Kasten und Wagen zu einem Versorgungskonvoi der Naga gehörten, der vor dem Unglück die Küste entlangzog, vermutlich in Richtung Eschental.",al={"hintergrund zum schildkrötenkasten","wer den markierten kasten hergestellt hat","naga-kasten"}},{q="Warum interessiert sich der Tempel des Mondes für gestrandete Schildkröten?",a="Die Priesterinnen von Elune untersuchen Bedrohungen für die Küste der Dunkelküste, sowohl durch Umwelteinflüsse als auch durch militärische Angriffe. Geborgene Artefakte wie dieser Kasten gelangen nach Darnassus, wo Gelehrte feindliche Bewegungen auf Karten verzeichnen können.",al={"warum der tempel schildkröten will","gwennyth dunkelküste mission"}},{q="Wohin war die Schildkröte unterwegs, bevor sie starb?",a="Aufgrund der Lage des Kadavers an der Küste vermutet Gwennyth Bly'Leggonde, dass die Naga die beladene Schildkröte nach Süden lenkten, möglicherweise in Richtung Eschental.",al={"reiseziel der schildkröte","wohin die schildkröte unterwegs war"}}},fp="18,147,17.328.0,18.377.1,53.175.0,40.142.0,39.101.0,37.170.1,60.198.0,46.147.1"}
P.entries["quest:4732"] = {n="Gestrandete Meeresschildkröte",s="An der Dunkelküste werden immer mehr Überreste Gestrandeter Meeresschildkröten angespült. Ihre Knochen liefern Gwennyth Bly'Leggonde in Auberdine Proben für ihre Forschung, während Kalimdors Meeresfauna schwindet.",h="An der Dunkelküste werden immer mehr Überreste Gestrandeter Meeresschildkröten angespült.",kw={"auberdine","gestrandet","dunkelküste","graugischt","gwennyth bly'leggonde","murloc","nordrassil","meeresschildkröte","teldrassil","tempel des mondes"},ang={["class:Druid"]="Für einen Druiden sind diese uralten, am Ufer gestrandeten Meeresbewohner ein Zeichen dafür, dass die Natur nach der Schlacht am Hyjal und Teldrassils Erscheinen aus dem Gleichgewicht geraten ist.",["class:Priest"]="Als Priester helft Ihr der Sisterhood of Elune, die geistige Krankheit zu ergründen, die sich in Kalimdors Gewässern ausbreitet, indem Ihr diese Überreste bergt.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass der Tempel des Mondes die Kreaturen ehren und verstehen will, die einst unter Nordrassils Ästen spielten."},sec={{t="Ein Strand voller Knochen",b="Gewaltige Meereskreaturen und Schildkröten liegen am Ufer der Dunkelküste. Viele uralte Schildkröten treiben auf die Untiefen oder kriechen zum Sterben auf den Sand. Graugischtmurlocs sammeln sich an den Kadavern und reißen das Fleisch ab. Bald bleiben nur Panzer und Knochen neben den einfachen Lagern zurück, die sie dort errichten."},{t="Schwindendes Leben im Wasser",b="Vor dem Dritten Krieg gediehen Meeresschildkröten in den heiligen Gewässern um den Hyjal und die Wurzeln Nordrassils, des Weltbaums. Nach Nordrassils Opfer im Kampf gegen die Brennende Legion und der Pflanzung Teldrassils vor Kalimdors Nordküste brach ihr Bestand ein.\n\nGwennyth Bly'Leggonde und andere Priesterinnen Elunes untersuchen die Überreste im Auftrag des Tempels des Mondes. Sie wollen herausfinden, ob dunkle Magie, Veränderungen der Meere oder der Verlust ihrer uralten Zuflucht die Schildkröten in den Tod treiben."}},faq={{q="Warum stranden Meeresschildkröten an der Dunkelküste?",a="Die Nachtelfen wissen nicht, warum Meeresschildkröten stranden. Einst gediehen sie in den Gewässern unter Nordrassil, dem Weltbaum. Seit Nordrassils Zerstörung im Dritten Krieg und dem Aufziehen Teldrassils ist ihr Bestand eingebrochen, und viele scheinen ihr Leben freiwillig an den Untiefen der Dunkelküste zu beenden.",al={"warum sterben hier schildkröten","schildkrötenrätsel der dunkelküste","warum gestrandet"}},{q="Wer ist Gwennyth Bly'Leggonde?",a="Gwennyth Bly'Leggonde ist eine nachtelfische Gelehrte und Vertreterin des Tempels des Mondes in Auberdine. Sie katalogisiert und untersucht angespülte Meereskreaturen, um herauszufinden, warum die Tierwelt der Dunkelküste leidet.",al={"wer ist gwennyth","wo schildkrötenüberreste abgeben","forscherin in auberdine"}},{q="Warum versammeln sich Murlocs um die Schildkrötenüberreste?",a="Graugischtmurlocs suchen in den gewaltigen Kadavern nach Nahrung und Materialien. Oft errichten sie Küstensiedlungen neben gestrandeten Meeresschildkröten und anderen Meereskreaturen und nagen die Überreste dann vollständig ab.",al={"warum murlocs auf schildkröte","graugischt-aasfresser","murloclager am strand"}},{q="Welche Verbindung haben diese Schildkröten zu Nordrassil?",a="Die Nachtelfen sagen, dass Meeresschildkröten einst häufig in den unberührten Gewässern um den Hyjal und Nordrassil, den Weltbaum, vorkamen. Nordrassils gewaltsame Zerstörung störte das natürliche Gleichgewicht, und danach wurden die Schildkröten deutlich seltener gesichtet.",al={"verbindung zu nordrassil","schildkröten am hyjal","verbindung zwischen hyjal und schildkröten"}},{q="Hat Teldrassil etwas mit ihrem Rückgang zu tun?",a="Die Priesterschaft hat immer weniger Meeresschildkröten gesichtet, seit Teldrassil zu wachsen begann. Der Tempel des Mondes untersucht, ob der neue Weltbaum Küstenströmungen verändert, Wanderungen gestört hat oder eine unnatürliche Aura besitzt, die das Meeresleben beeinflusst.",al={"teldrassils einfluss auf schildkröten","warum hat teldrassil schildkröten verändert"}},{q="Gibt es mehrere gestrandete Kreaturen an der Dunkelküste?",a="Ja. An der langen Küstenlinie der Dunkelküste liegen viele gestrandete Meereskreaturen und Schildkröten. Jeder Kadaver liefert Knochen- und Gewebeproben für Gwennyth Bly'Leggondes Forschung, während sie die ökologische Katastrophe an der Küste Stück für Stück aufklärt.",al={"weitere quests zu gestrandeten kreaturen","andere gestrandete schildkröten","gestrandete meereskreaturen"}}},fx={ad0e3c15={q="Warum möchte Gwennyth Bly'Leggonde die Meeresschildkrötenüberreste?",a="Gwennyth Bly'Leggonde untersucht die Überreste im Auftrag von The Temple of the Moon in Auberdine. Meeresschildkröten gediehen einst um die Basis von Hyjal und Nordrassil, aber seit Teldrassil gepflanzt wurde, sind ihre Zahlen eingebrochen und gestrandete Kadaver haben begonnen, entlang der Dunkelküste anzuspülen. Sie sammelt diese verwertbaren Exemplare in der Hoffnung, dass biologische Studien enthüllen, warum die Kreaturen zugrunde gehen.",al={"warum meeresschildkrötenüberreste sammeln","warum will gwennyth schildkrötenknochen","zweck der meeresschildkrötenüberreste"}}},fp="18,182,17.271.0,16.493.0,53.307.0,29.202.0,51.192.0,52.235.0,55.255.0,53.230.0"}
P.entries["quest:4733"] = {n="Gestrandete Meereskreatur",s="Ein kolossaler Drescher liegt am felsigen Zwielichtufer der Dunkelküste gestrandet. Sein Tod und seine Strandung verschärfen die Probleme im Meer, die die Nachtelfen beunruhigen.",h="Ein kolossaler Drescher liegt am felsigen Zwielichtufer der Dunkelküste gestrandet.",kw={"auberdine","gestrandete meereskreatur","dunkelküste","gwennyth bly'leggonde","meereskreaturknochen","tempel des mondes","drescher","zwielichtufer"},ang={["class:Druid"]="Die Strandung großer Meeresraubtiere deutet auf ein Ökosystem in Bedrängnis hin. Der Zirkel des Cenarius teilt diese Sorge in der gesamten Dunkelküste.",["class:Priest"]="Gwennyth Bly'Leggonde erforscht das Meer im Dienst des Tempels des Mondes. Durch eingehende Untersuchung seiner Gewässer sucht sie nach Gleichgewicht und göttlicher Einsicht.",["race:NightElf"]="Der unerklärliche Rückgang und die Strandungen von Meereslebewesen nahe Teldrassil beunruhigen die Kaldorei. Sie suchen bei Elune und dem Tempel des Mondes nach der Bedeutung solcher Omen."},sec={{t="Ein angespülter Riese",b="Entlang des Zwielichtufers im Süden der Dunkelküste werden Treibholz und andere Überreste aus dem Meer in die Buchten gespült. In einer davon findet Ihr die Überreste eines gewaltigen Dreschers. Gezeiten und Aasfresser haben begonnen, ihn zu zerlegen, doch sein Skelett überragt die gewöhnlichen Raubtiere dieser flachen Küstengewässer bei Weitem. Der Riese gehört nicht in diese Gewässer. Krankheit oder Orientierungslosigkeit könnten ihn auf die Felsen getrieben haben, oder eine tiefere Störung könnte im verhüllten Meer liegen."},{t="Die Wacht des Tempels",b="In Auberdine untersuchen Priesterinnen des Tempels des Mondes die toten Riesen, die an Land gespült werden. Gwennyth Bly'Leggonde beaufsichtigt das Sammeln von Skelettproben, um herauszufinden, warum Raubtiere aus der Tiefe sterben. Kolossale Drescher tauchten einst nahe den Wurzeln von Teldrassil auf, doch ihre Zahl ist stetig gesunken. Die Priesterinnen fürchten, dass das Gleichgewicht des Lebens im Meer vor Kalimdors Nordküste aus den Fugen gerät."}},faq={{q="Was für ein Tier ist dieser gestrandete Kadaver?",a="Der Kadaver ist das Skelett eines gewaltigen räuberischen Meerestiers, das Drescher genannt wird. Es ist um ein Vielfaches größer als die gewöhnlichen Drescher entlang der Küste der Dunkelküste.",al={"was ist die gestrandete meereskreatur","riesiger drescher dunkelküste","gestrandeter monsterkadaver"}},{q="Woher kam diese Kreatur ursprünglich?",a="Gwennyth Bly'Leggonde sagt, dass Kreaturen dieser gewaltigen Größe einst die Gewässer nahe den Wurzeln von Teldrassil durchstreiften, doch ihre Zahl ist stetig gesunken. Dieser Drescher ist in den unmittelbar an die Dunkelküste angrenzenden flachen Gewässern nicht heimisch.",al={"wo leben riesige drescher","herkunft der drescher"}},{q="Warum untersucht der Tempel des Mondes diese Kadaver?",a="Der Tempel des Mondes untersucht die Kadaver, um zu verstehen, warum Meerestiere entlang der Dunkelküste an Land gespült werden. Durch die Untersuchung von Knochen und Überresten hoffen die Priesterinnen herauszufinden, ob Verderbnis, Krankheiten oder äußere Kräfte Tiefseekreaturen an Land treiben.",al={"warum will gwennyth knochen","tempel des mondes meereskreaturen","warum gestrandete tiere untersuchen"}},{q="Wohin sollen die Knochen gebracht werden?",a="Bringt die Meereskreaturknochen zu Gwennyth Bly'Leggonde, einer nachtelfischen Forscherin in der Hafenstadt Auberdine.",al={"wo meereskreaturknochen abgeben","wer bekommt die drescherknochen"}},{q="Wo an der Küste liegt dieser Kadaver?",a="Der Kadaver liegt in einer felsigen Bucht am Zwielichtufer, an der Südküste der Dunkelküste.",al={"wo ist die gestrandete kreatur","drescher fundort dunkelküste","zwielichtufer skelett"}},{q="Stranden noch andere Kreaturen an der Dunkelküste?",a="Ja. Verschiedene Arten von Meerestieren und Meeresriesen wurden entlang der Küste der Dunkelküste angespült, was Forscher in Auberdine zu Untersuchungen veranlasst hat.",al={"andere gestrandete tiere","gestrandete meereskreatur questreihe"}}},fp="20,144,19.428.0,18.402.1,43.158.0,45.210.0,55.260.0,34.105.0,43.90.0,59.141.0"}
P.entries["quest:4736"] = {n="Auf der Suche nach Menara Leerbringer",s="Hexenmeister der Allianz überqueren das Meer, um Menara Leerbringer im Brachland zu finden. Von Strahad Farsans Turm über Ratschet aus lehrt sie erfahrene Praktizierende, Werkzeuge und Gewänder herzustellen, die ihre Kontrolle über Dämonen stärken.",h="Hexenmeister der Allianz überqueren das Meer, um Menara Leerbringer im Brachland zu finden.",kw={"wilddornrose","verzauberte goldblutrobe","eisenschmiede","menara leerbringer","ratschet","strahad farsan","brachland","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister sucht Ihr nach fortgeschrittener Zauberkunst, die Euch zur Herstellung Eurer Verzauberten Goldblutrobe führt.",["faction:Alliance"]="Als Hexenmeister der Allianz durchquert Ihr feindliches Gebiet im Brachland und verlasst Euch auf Ratschets brüchige Neutralität, um Strahads Turm zu erreichen.",["race:Gnome"]="Als gnomischer Hexenmeister ist Euer Widerstand gegen arkane Verderbnis und Teufelsverderbnis für Menara von Bedeutung, die praktische Kontrolle höher schätzt als Theorie.",["race:Human"]="Als menschlicher Hexenmeister lasst Ihr die verborgenen Kulte von Sturmwind und Eisenschmiede hinter Euch, um Ratschets abgeschiedenen Gipfel aufzusuchen."},sec={{t="Ein Ruf aus Eisenschmiede",b="Wilddornrose erkennt, wann ein Hexenmeister über die Grundlagen der Dämonologie hinausgewachsen ist und der Verderbnis widerstanden hat. Er schickt diese Schüler über Eisenschmiede hinaus, über das Meer nach Kalimdor, statt sie unter dem Berg zu behalten. Dort kann eine geschicktere Kunsthandwerkerin sie im praktischen Umgang mit Teufelsmagie unterweisen."},{t="Die Enklave über Ratschet",b="Strahad Farsan unterhält einen einsamen Turm auf den Klippen über Ratschet. Hexenmeister setzen sich oft über Volkszugehörigkeit und politische Grenzen hinweg, um in einer Welt zu überleben, die dunkler Magie misstraut. Menara Leerbringer hält sich in Strahads Zuflucht auf und arbeitet mit Hexenmeistern jeder Gesinnung zusammen. Sie hilft ihnen, ihre Kunst zu verfeinern und ihre beschworenen Unholde gebunden zu halten."}},faq={{q="Wer vergibt die Quest 'Auf der Suche nach Menara Leerbringer'?",a="Wilddornrose schickt disziplinierte Hexenmeister der Allianz, die über die Grundlagen der Dämonologie hinausgewachsen sind, zur weiteren Unterweisung.",al={"questgeber","wer vergibt die quest","wilddornrose standort"}},{q="Wo ist Menara Leerbringer zu finden?",a="Menara Leerbringer ist in Strahad Farsans Turm auf den Klippen über Ratschet im Brachland zu finden.",al={"menara leerbringer standort","wo ist menara leerbringer","strahad farsans turm standort"}},{q="Warum muss ein Hexenmeister der Allianz ins Gebiet der Horde reisen?",a="Hexenmeister überschreiten oft Fraktionsgrenzen, weil ihre Kunst sie in Gefahr bringt. Ratschet ist ein neutraler Hafen unter der Führung des Steamwheedle Cartel, und Strahads Turm bietet Anwendern verbotener Magie einen abgeschiedenen Versammlungs- und Studienort.",al={"warum ins brachland gehen","warum nach ratschet reisen","brachland gefährlich für die allianz"}},{q="Was bietet Menara nach Abschluss an?",a="Menara bietet die Möglichkeit, mächtige Hexenmeistergewänder herzustellen, beginnend mit dem Sammeln der Bestandteile für eine Verzauberte Goldblutrobe.",al={"was lehrt menara","questbelohnung","nächste quest nach menara"}},{q="Gehört Menara Leerbringer zur Allianz oder zur Horde?",a="Menara Leerbringer hilft disziplinierten Hexenmeistern ungeachtet ihrer Herkunft. Sie ist streng und kratzbürstig, behandelt Anwender der dunklen Künste aber ohne Rücksicht auf ihre Fraktionszugehörigkeit.",al={"menara fraktion","ist menara freundlich"}},{q="Warum versammeln sich Hexenmeister über die Grenzen der Völker hinweg?",a="Dämonen können gegen unvorsichtige Beschwörer jedes Volkes zurückschlagen. Hexenmeister teilen ihr Wissen und sichern ihr gemeinsames Überleben, während sie das Twisting Nether meistern.",al={"zusammenhalt der hexenmeister","warum arbeiten hexenmeister zusammen"}}},fx={["34d3d012"]={q="Warum schickt Euch Wilddornrose zu Menara Leerbringer?",a="Wilddornrose erkennt, dass Eure Ausbildung zum Hexenmeister bemerkenswert gut vorangekommen ist, und merkt insbesondere an, dass es Euch bisher gelungen ist, eine Verderbnis durch die Teufels- und arkanen Künste zu vermeiden. Da er glaubt, dass Eure Hingabe und Disziplin eine Belohnung verdienen, schickt er Euch zu Menara Leerbringer oberhalb von Ratschet. Menara besitzt fortgeschrittenes Wissen und die Expertise, die erforderlich ist, um spezialisierte Roben und Werkzeuge herzustellen, um die aufkeimende Macht eines aufstrebenden Hexenmeisters weiter zu stärken.",al={"warum will wilddornrose, dass das erledigt wird","warum zu menara leerbringer schicken","wilddornrose motiv"}}},fp="30,219,24.278.0,25.327.0,54.109.0,37.100.0,63.230.0,39.131.0,39.162.0,47.143.0"}
P.entries["quest:4737"] = {n="Auf der Suche nach Menara Leerbringer",s="Zevrost schickt Hexenmeister aus Orgrimmar zu Menara Leerbringer im Brachland. Er fürchtet, dass Teufelsmagie sie versklaven wird, verweist sie aber an eine Mentorin, die beim Anfertigen mächtiger arkaner Gewänder helfen kann.",h="Zevrost schickt Hexenmeister aus Orgrimmar zu Menara Leerbringer im Brachland.",kw={"brachland","blutrobe","die kluft der schatten","teufelsmagie","menara leerbringer","ratschet","hexenmeisterrobe","zevrost"},ang={["class:Warlock"]="Als Hexenmeister folgt Ihr Menara Leerbringers Anleitung und sammelt alles, was Ihr für Eure eigene ikonische Verzauberte Goldblutrobe braucht, einen Übergangsritus für Hexenmeister der Horde.",["faction:Horde"]="Als Hexenmeister der Horde begegnen Euch traditionsverbundene Schamanen und Krieger mit Verachtung. Ihr findet Zuflucht an verborgenen Orten wie Orgrimmars Kluft der Schatten oder auf neutralem Boden nahe Ratschet."},sec={{t="Warnungen in den Schatten",b="Unter Orgrimmar versammeln sich Hexenmeister in der Kluft der Schatten, wo andere sie mit Unbehagen dulden. Zevrost, einer ihrer verbitterten Lehrmeister, verachtet Akolythen, die die dunklen Künste meistern wollen. Er glaubt, dass jeder Schritt tiefer in die Teufelsmagie sie der Versklavung näherbringt. Für Zevrost wird die dämonische Sucht mit der Zeit jeden Praktizierenden verschlingen. Selbst der disziplinierteste Gelehrte wird zu einem Knecht des Wirbelnden Nethers werden."},{t="Der Weg nach Ratschet",b="Zevrost weiß, dass andere Hexenmeister einen anderen Weg sehen. Orgrimmar hat Kunde von Menara Leerbringer erreicht, einer fähigen Hexenmeisterin auf den Klippen über Ratschet, dem neutralen Goblinhafen. Menara sucht vielversprechende Schüler, die helfen sollen, besondere Werkzeuge für ihre arkane Macht anzufertigen. Für Hexenmeister, die ihre Kunst vertiefen wollen, beginnt mit ihrem Ruf die Herstellung der legendären Verzauberten Goldblutrobe."},{t="Eine pragmatische Gemeinschaft",b="Menara wartet hoch über Ratschet, wo Hexenmeister sich den harten Wahrheiten ihres Ordens stellen. Sie müssen Rivalitäten zwischen Völkern und Kulturen beiseitelegen und einander unterstützen. Die Dämonen, mit denen sie paktieren, kennen weder Vorurteile noch Gnade für jemanden, der ins Wanken gerät. Wissen zu teilen und schützende Gewänder anzufertigen, ist zweckmäßig, keine Wohltätigkeit. Hexenmeister brauchen beides, um die feindseligen Wesen zu überleben, die sie in ihren Dienst zwingen."}},faq={{q="Wer ist Zevrost?",a="Zevrost ist ein orkischer Hexenmeisterlehrer in der Kluft der Schatten unter Orgrimmar. Er misstraut dem Streben nach Teufelsmacht und glaubt, dass ehrgeizige Hexenmeister unweigerlich zu Sklaven dämonischer Verderbnis werden.",al={"zevrost","zevrost hintergrundgeschichte","wer beginnt auf der suche nach menara leerbringer"}},{q="Wer ist Menara Leerbringer?",a="Menara Leerbringer ist eine versierte Hexenmeisterin im Brachland, auf den Klippen über Ratschet. Sie unterweist aufstrebende Hexenmeister und hilft ihnen, seltene Reagenzien für mächtige Zeremonienroben zu sammeln.",al={"menara leerbringer","wo ist menara leerbringer","wer ist menara"}},{q="Warum hält Zevrost alle Hexenmeister für Narren?",a="Zevrost glaubt, dass Teufelsmagie jeden unweigerlich verdirbt und versklavt, der sie zu meistern versucht. Er meint, kein Praktizierender könne der Sucht widerstehen, und das Streben nach größerer Macht beschleunige nur seinen Untergang.",al={"zevrost verderbnis","warum warnt zevrost mich"}},{q="Wo ist Menara Leerbringer zu finden?",a="Menara Leerbringer ist im Brachland auf den hohen Hügeln über Ratschet zu finden. Hexenmeister reisen ostwärts durch die trockene Savanne, um ihr Lager oberhalb des Hafens zu erreichen.",al={"menara aufenthaltsort","menara leerbringer finden"}},{q="Warum arbeiten Hexenmeister verschiedener Völker zusammen?",a="Die von Hexenmeistern beschworenen Dämonen begegnen jedem mit grausamer Bosheit, der sie nicht zu beherrschen vermag. Ihr Überleben hängt von Präzision ab, deshalb teilen Hexenmeister Wissen und Werkzeuge über kulturelle Grenzen hinweg.",al={"zusammenhalt der hexenmeister","warum schließen sich hexenmeister zusammen"}},{q="Was geschieht, nachdem man Menara Leerbringer gefunden hat?",a="Nachdem ein Hexenmeister Menara Leerbringer gefunden hat, sammelt er exotische, mächtige Materialien aus ganz Azeroth, um die Verzauberte Goldblutrobe herzustellen, ein Gewand zum Schutz vor Teufelsenergien.",al={"nächste quest nach menara","was will menara"}}},fx={df1726dd={q="Warum schickt Euch Zevrost zu Menara Leerbringer?",a="Zevrost glaubt, dass Ihr ein Narr seid, der dazu bestimmt ist, der dämonischen Verderbnis zu verfallen, aber er erkennt Euren Wunsch an, Euer magisches Handwerk zu erweitern. Anstatt Euch direkt dabei zu unterstützen, Macht zu erlangen, die er für gefährlich hält, gibt er Euch an Menara Leerbringer weiter, die sich umgesehen hat und nach aufstrebenden Hexenmeistern sucht, die bereit sind, spezialisierte Werkzeuge herzustellen.",al={"warum zu menara schicken","warum zevrost euch schickt","warum ich zevrost"}}},fp="30,192,23.410.0,19.382.0,22.403.0,15.190.0,25.188.0,46.198.0,37.165.0,51.179.0,45.179.0"}
P.entries["quest:4738"] = {n="Auf der Suche nach Menara Leerbringer",s="Ein Hexenmeister der Allianz wird über das große Meer geschickt, um Menara Leerbringer aufzusuchen. In einem Turm oberhalb von Ratschet unterweist sie Hexenmeister aller Fraktionen im Binden und in der Herstellung von Artefakten.",h="Ein Hexenmeister der Allianz wird über das große Meer geschickt, um Menara Leerbringer aufzusuchen.",kw={"blutrobe","demisette cloyce","verzauberte goldblutrobe","menara leerbringer","ratschet","slaughtered lamb","brachland","hexenmeister quest"},ang={["class:Warlock"]="Als Hexenmeister reist Ihr aus Sturmwinds verborgenen Gewölben in Kalimdors offenes Grenzland. Der Weg lehrt Euch, dass das Streben nach der Beherrschung von Dämonen die Fraktionsgrenzen der Sterblichen überschreitet.",["faction:Alliance"]="Als Zauberwirker der Allianz verlasst Ihr die vertrauten östlichen Lande und reist ins ungezähmte Brachland, um besondere Unterweisung zu finden."},sec={{t="Eine widerwillige Empfehlung",b="Unter dem Slaughtered Lamb in Sturmwind bildet Demisette Cloyce Hexenmeister nach strengen Maßstäben aus. Wenn ein Schüler so weit ist, mächtige Gegenstände herzustellen, glaubt Demisette selten, dass er bereit ist. Doch die höheren Autoritäten der Kabale schicken den Schüler weiter, weit fort von der Hauptstadt, damit er sich bewährt."},{t="Der Turm über Ratschet",b="Menara Leerbringer betreibt ihr Labor in einem Steinturm oberhalb von Ratschet, dem Goblinhafen in den kargen Hügeln des Brachlands. Dort nimmt sie Lehrlinge jedes Volkes und jeder Fraktion auf, jenseits von Sturmwinds Gesetzen und Orgrimmars wachsamen Augen. Die Unholde und Dämonen, denen Hexenmeister gegenübertreten, hegen gegen jede sterbliche Seele dieselbe Bosheit."}},faq={{q="Warum wird ein Hexenmeister der Allianz den weiten Weg ins Brachland geschickt?",a="Nur wenige Hexenmeister der Allianz haben das Wissen oder die Freiheit, anspruchsvolle Teufelsgewänder wie die Verzauberte Goldblutrobe herzustellen. Menara Leerbringers abgeschiedener Turm oberhalb des neutralen Ratschet bietet eine seltene Gelegenheit, gefährliche Handwerkskünste außerhalb der Reichweite von Hauptstadtwachen und Inquisitoren zu studieren.",al={"warum ratschet","warum ins brachland","warum menara leerbringer"}},{q="Wer ist Demisette Cloyce?",a="Demisette Cloyce ist eine hochrangige menschliche Hexenmeisterlehrerin, die unter dem Slaughtered Lamb in Sturmwinds Magierviertel arbeitet. Streng und auf den Schutz gefährlichen Wissens bedacht, schickt sie Schüler nur dann zu Menara, wenn die verborgenen Mächte hinter der Hexenmeisterenklave es ihr befehlen.",al={"demisette cloyce hintergrund","wer startet auf der suche nach menara"}},{q="Kümmert sich Menara Leerbringer um den Konflikt zwischen Allianz und Horde?",a="Nein. Menara lehrt, dass Hexenmeister über Volk und Fraktion hinausblicken müssen. Die Dämonen und jenseitigen Mächte, die sie beschwören, gehen gegen jeden grausam vor, der strauchelt, weshalb gemeinsames Überleben und dunkle Künste mehr zählen als Kriege der Sterblichen.",al={"ist menara horde oder allianz","hasst menara die allianz"}},{q="Auf die Herstellung welches Gegenstands bereitet Menara Leerbringer den Hexenmeister vor?",a="Menara zu erreichen ist der erste Schritt, um die Robe of Arcana in die Verzauberte Goldblutrobe zu verwandeln. Das mächtige Gewand entsteht aus seltenen Reagenzien, feiner Schneiderkunst und gebundenen dämonischen Energien.",al={"was lehrt menara","für welche robe ist das","blutrobe quest"}},{q="Ist die Reise nach Ratschet für einen Hexenmeister der Allianz gefährlich?",a="Das Brachland ist größtenteils Gebiet der Horde, mit feindseligen Wildtieren, Zentauren und Orkpatrouillen. Ratschet ist ein neutraler Hafen unter der Führung des Steamwheedle Cartel, sodass ein Reisender der Allianz Menaras Turm entlang der Küste oder sicher per Schiff aus Beutebucht erreichen kann.",al={"wie gefährlich ist ratschet","ist das brachland sicher"}},{q="Warum glaubt Demisette Cloyce, dass der Spieler noch nicht bereit ist?",a="Demisette hält die Herstellung teufelserfüllter Machtgegenstände für leichtsinnig, wenn unerfahrene Neulinge sich daran versuchen. Hexenmeisterartefakte verlangen strenge Disziplin. Ein kleiner Fehler beim Binden von Reagenzien oder dämonischen Essenzen kann den Ausübenden vernichten oder Schrecken auf die Welt loslassen.",al={"warum demisette am spieler zweifelt","demisettes warnung"}}},fp="30,172,26.297.0,23.308.0,59.275.0,24.268.0,65.207.0,61.192.0,58.261.0,55.252.0"}
P.entries["quest:4739"] = {n="Auf der Suche nach Menara Leerbringer",s="Menara Leerbringer erwartet in Ratschet Hexenmeister der Horde, die ihr Wissen vertiefen wollen. Von Unterstadt aus überqueren sie das Große Meer zu ihrem Zufluchtsort oberhalb des Hafens.",h="Menara Leerbringer erwartet in Ratschet Hexenmeister der Horde, die ihr Wissen vertiefen wollen.",kw={"brachland","verzauberte goldblutrobe","kaal seelentod","menara leerbringer","ratschet","strahads turm","unterstadt","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister beginnt Ihr mit fortgeschrittenen Übungen und könnt besondere Gewänder anstreben, die auf die Energien des Nethers abgestimmt sind.",["faction:Horde"]="Als Angehöriger der Horde seht Ihr, wie Hexenmeisterfraktionen ein verborgenes Netzwerk zwischen Lordaeron und Kalimdor unterhalten.",["race:Undead"]="Als Verlassener verlasst Ihr die düsteren Tiefen von Unterstadt und reist in Kalimdors sonnendurchflutete Einöden, um Eure Studien fortzusetzen."},sec={{t="Ein Ruf aus den Schatten",b="Kaal Seelentod beobachtet in Unterstadt, wie Hexenmeister ihre Fähigkeiten verbessern. Sobald einer einfachen Flüchen und Wichtelknechten entwachsen ist, schickt er ihn zur spezialisierten Unterweisung über das Große Meer. Die Kontrolle über Dämonen lässt wenig Raum für Fehler. Ein erfahrener Mentor kann einem Hexenmeister helfen, die unberechenbaren Mächte des Nethers zu überleben."},{t="Der Turm über Ratschet",b="Strahad Farsans Turm erhebt sich auf einer hohen Klippe über Ratschet. Dort unterweisen Praktizierende wie Menara Leerbringer jüngere Initianden, fernab der wachsamen Blicke der Stadtwachen. Hexenmeister unterschiedlicher Herkunft legen Stammesrivalitäten und politische Feindschaften beiseite. Die Dämonen, mit denen sie paktieren, verschlingen Menschen, Orcs oder Verlassene gleichermaßen, wenn der Wille ihres Beschwörers wankt."}},faq={{q="Wer vergibt diese Quest?",a="Kaal Seelentod schickt Hexenmeister aus Unterstadt zu Menara Leerbringer, sobald sie für eine weiterführende Unterweisung ausreichend geübt sind.",al={"questgeber","wo gibt es die quest","kaal seelentod standort"}},{q="Wo ist Menara Leerbringer zu finden?",a="Menara Leerbringer lebt im Brachland, gemeinsam mit Strahad Farsan im steinernen Turm über Ratschet.",al={"wo ist menara","menara leerbringer finden","menara standort"}},{q="Warum müssen Hexenmeister der Horde den weiten Weg ins Brachland auf sich nehmen?",a="Hexenmeister der Horde reisen ins Brachland, um in Abgeschiedenheit in den dämonischen Künsten unterwiesen zu werden. Menara Leerbringer unterrichtet und fertigt Roben in Strahads Turm, wo Hexenmeister jeder Herkunft fernab weltlicher und religiöser Obrigkeiten studieren.",al={"warum ratschet","warum ins brachland reisen","warum zu menara gehen"}},{q="Was geschieht nach der Ankunft bei Menara Leerbringer?",a="Menara erkennt Eure Ausbildung an und bietet an, Euch bei der Herstellung einer Verzauberten Goldblutrobe anzuleiten. Mit dieser Arbeit beginnt eine Reise durch Azeroth, auf der Ihr seltene und gefährliche Bestandteile sammelt.",al={"questfortsetzung","was gibt menara","nächste quest"}},{q="Warum teilen Hexenmeister verschiedener Völker ihr Wissen?",a="Dämonen nehmen keine Rücksicht auf die Volkszugehörigkeit, wenn ein Beschwörer die Kontrolle verliert. Um zu überleben, teilen Hexenmeister ihre Techniken und bewahren ihre Kunst vor Katastrophen.",al={"zusammenarbeit der hexenmeister","warum arbeiten hexenmeister zusammen","menara hexenmeister hintergrundgeschichte"}},{q="Wer ist Strahad Farsan?",a="Strahad Farsan ist ein Meisterhexenmeister, der den steinernen Turm über Ratschet unterhält. Der Turm bietet Praktizierenden einen abgelegenen Ort zum Erlernen dämonischer Künste, fernab der großen Hochburgen der Fraktionen.",al={"strahad turm","wem gehört der turm in ratschet","strahad farsan"}}},fx={["09af788d"]={q="Warum schickt Euch Kaal Seelentod zu Menara Leerbringer?",a="Kaal erkennt, dass Eure aufstrebende Macht und Euer Selbstvertrauen der grundlegenden Unterweisung entwachsen sind. Hexenmeister arbeiten unter der ständigen Gefahr der dämonischen Mächte, die sie beschwören; ohne fortgeschrittene Disziplin und angemessene arkane Instrumente riskiert ein ehrgeiziger Praktizierender die völlige Vernichtung. Menara Leerbringer ist darauf spezialisiert, aufstrebende Hexenmeister zu prüfen und mächtige Werkzeuge zur Verankerung ihrer Handwerkskunst herzustellen, weshalb ihre Anleitung für Euer fortwährendes Überleben und Eure Meisterschaft unerlässlich ist.",al={"warum schickt mich kaal","motiv von kaal seelentod","warum zu menara leerbringer"}}},fp="30,147,26.305.0,23.360.0,22.126.0,37.93.0,58.229.0,46.178.0,51.143.0,22.180.0"}
P.entries["quest:474"] = {n="Sieg über Nek'rosh",s="Im Sumpfland rückt die Allianz gegen Nek'rosh und seine Dragonmaw-Kriegsschar vor. Ihre Katapulte brennen, doch der Hafen von Menethil bleibt bedroht, bis der Häuptling fällt.",h="Im Sumpfland rückt die Allianz gegen Nek'rosh und seine Dragonmaw-Kriegsschar vor.",kw={"hauptmann starkfaust","katapult","häuptling","dragonmaw","eisenschmiede","hafen von menethil","nek'rosh","sumpfland"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch Häuptling Nek'rosh in seinem befestigten Kriegslager. Dort erprobt Ihr Eure Kampfkraft an einem der grimmigsten Orkkommandanten der Marschen.",["faction:Alliance"]="Als Mitglied der Allianz seid Ihr auf den Seeweg des Hafens von Menethil angewiesen, der Eisenschmiede und Sturmwind mit Kalimdor und den nördlichen Gewässern verbindet.",["race:Dwarf"]="Als Zwerg von Khaz Modan kennt Ihr die Dragonmaw als bleibende Narbe an den angestammten Grenzen Eures Volkes. Ein Sieg über Nek'rosh schützt die Straßen der Zwerge und Eisenschmiedes Seehandel im Westen."},sec={{t="Die Dragonmaw enthaupten",b="Die Dragonmaw plagen seit Langem die Marschen von Khaz Modan. Sie halten befestigte Lager und bedrohen die Seewege des Hafens von Menethil. Nachdem die Katapulte des Clans entdeckt und verbrannt wurden, schlagen die Verteidiger der Marschen gegen den Anführer der Kriegsschar zu. Häuptling Nek'rosh befehligt die hiesigen Orcs und bleibt das letzte Hindernis, um die Belagerung zu brechen. Ohne ihn fehlt den verbliebenen Plünderern die Führung ihres Anführers."},{t="Den Hafen sichern",b="Bringt Nek'roshs abgetrennten Kopf zu Hauptmann Starkfaust im Hafen von Menethil, und die Garnison von Eisenschmiede wird einen großen Sieg erringen. Die Dragonmaw haben ihre schweren Belagerungswaffen und ihren Häuptling verloren, ein Schlag, von dem sie sich wohl nicht schnell erholen werden.\n\nDer Hafen von Menethil ist die wichtigste Lebensader der Allianz zwischen Lordaeron und Khaz Modan. Nach Nek'roshs Fall sind seine Docks und Handelsschiffe besser vor plötzlichen Angriffen geschützt."}},faq={{q="Wer ist Nek'rosh?",a="Nek'rosh führt die verbliebenen Dragonmaw im Sumpfland an. Von ihren Lagern aus organisierte er einen Angriff mit Belagerungskatapulten auf den Hafen von Menethil, bevor die Allianz zurückschlug.",al={"häuptling nek'rosh","wer ist nekrosh","nekrosh sumpfland"}},{q="Warum will der Hafen von Menethil Nek'roshs Tod?",a="Nek'rosh bedroht den Hafen von Menethil unmittelbar. Unter seinem Kommando bauten die Dragonmaw Kriegskatapulte, um den Hafen zu beschießen und die lebenswichtigen Seewege zwischen Khaz Modan und anderen Allianzgebieten lahmzulegen.",al={"warum nekrosh töten","hauptmann starkfaust beweggründe"}},{q="Wer befiehlt Nek'roshs Tod?",a="Der Angriff folgt auf das Niederbrennen der Katapulte der Dragonmaw. Hauptmann Starkfaust befehligt die Verteidigung des Hafens von Menethil und nimmt den abgetrennten Kopf des Häuptlings entgegen.",al={"wer vergibt sieg über nekrosh","wo nekroshs kopf abgeben"}},{q="Was geschieht mit dem Dragonmaw-Clan nach Nek'roshs Niederlage?",a="Mit der Zerstörung ihrer Katapulte und dem Tod ihres Häuptlings verlieren die Dragonmaw Führung und Kampfgeist. Versprengte treiben noch immer in den Marschen ihr Unwesen, doch ihr unmittelbarer Feldzug gegen den Hafen von Menethil ist zerschlagen.",al={"dragonmaw nach nekrosh","was geschieht mit den orcs im sumpfland"}},{q="Was tut der Dragonmaw-Clan im Sumpfland?",a="Die Dragonmaw siedelten sich während des Zweiten Krieges im Sumpfland und im benachbarten Hochland von Grim Batol an. Nach der Niederlage der Horde blieben abtrünnige Überreste in den Sümpfen, überfielen Handelswege und hegten tiefen Hass auf die Allianz und die Zwerge von Khaz Modan.",al={"warum sind dragonmaw im sumpfland","dragonmaw sumpfland geschichte"}},{q="Warum ist der Hafen von Menethil für die Allianz so entscheidend?",a="Der Hafen von Menethil ist Eisenschmiedes einziger großer Seehafen an der Westküste. Seine Fähren bringen Truppen, Handelswaren und Reisende über das große Meer nach Kalimdor und nordwärts in Richtung Lordaeron.",al={"bedeutung von menethil","hafen von menethil strategischer wert"}}},fx={["55fbf5d4"]={q="Wozu dient Nek'roshs Kopf?",a="Hauptmann Starkfaust benötigt unwiderlegbare Beweise dafür, dass der Anführer der Schwarzmeißel im Sumpfland gefallen ist. Nek'roshs Kopf zum Hafen von Menethil zurückzubringen bestätigt, dass der Häuptling seine Streitkräfte nicht länger sammeln oder eine weitere Belagerung des Hafens einleiten kann, was der Garnison versichert, dass die Bedrohung tatsächlich gebrochen ist.",al={"warum nek'roshs kopf nehmen","zweck von nek'roshs kopf","was mache ich mit nek'roshs kopf"}}},fp="15,175,26.394.0,19.407.0,16.170.0,44.198.0,33.154.0,62.203.1,49.267.0,50.185.0"}
P.entries["quest:4740"] = {n="GESUCHT: Gurgelbacke!",s="Auberdines Rat fordert Gurgelbackes Tod wegen einer getöteten Schildwache und verlorener Schiffe vor der Dunkelküste. Sucht den Häuptling der Greymist weiter südlich an der Küste.",h="Auberdines Rat fordert Gurgelbackes Tod wegen einer getöteten Schildwache und verlorener Schiffe vor der...",kw={"auberdine","dunkelküste","glynda nal'shea","greymist","gurgelbacke","murloc","schildwachen","steckbrief"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass Auberdine ein wichtiger Handelsknotenpunkt im Norden ist. Die Frachtschiffe, deren Versenkung Gurgelbacke angelastet wird, bedeuten einen kostspieligen Schlag für die Versorgung der Allianz in Kalimdor.",["race:NightElf"]="Als Nachtelf, der die Dunkelküste verteidigt, rächt Ihr eine gefallene Schildwache und schützt die lebenswichtige Versorgung über Auberdines Docks."},sec={{t="Bedrohung im nebligen Flachwasser",b="Die Greymist-Murlocs sind an der Dunkelküste gewöhnlich eine Plage. Gurgelbacke hat sich gegen Auberdine gewandt, und der Steckbrief vor dem Gasthaus nennt ihn als Mörder mindestens einer Schildwache der Nachtelfen. Außerdem wird er verdächtigt, zwei Frachtschiffe vor der Küste sabotiert oder zerstört zu haben. Angesichts verlorener Schiffe und Überfälle entlang der Küste hat der Dorfrat von Auberdine ein öffentliches Kopfgeld auf ihren Anführer ausgesetzt."},{t="Der Hinterhalt bei den Hütten",b="Gurgelbacke lauert vor der südlichen Küste nahe einigen Murloc-Hütten, die sich um ein Lagerfeuer scharen. Eindringlinge erwartet eine organisierte Verteidigung, wenn Küstenläufer und Strandkriecher der Greymist aus der Brandung stürmen, um ihre Siedlung zu schützen. Dann erscheint Gurgelbacke mit seiner Vorhut, um die Eindringlinge anzugreifen."},{t="Gerechtigkeit für die Gefallenen",b="Der Beweis für Gurgelbackes Tod erfüllt das düstere Anliegen der Schildwachen. Schildwache Glynda Nal'Shea übernimmt die Auszahlung des Kopfgeldes im Namen des Rates. Nachdem die Führung der Greymist gebrochen ist, erhalten Reisende und Schiffe an der nebligen Dunkelküste eine Atempause vor Sabotageakten."}},faq={{q="Wo erhalte ich den Kopfgeldauftrag für Gurgelbacke?",a="Sucht den Steckbrief vor dem Gasthaus im Zentrum von Auberdine an der Dunkelküste.",al={"wo beginnt gesucht gurgelbacke","gurgelbacke questbeginn","auberdine steckbrief"}},{q="Warum setzt der Rat von Auberdine ein Kopfgeld auf Gurgelbacke aus?",a="Der Rat von Auberdine setzt das Kopfgeld aus, weil Gurgelbacke mindestens eine Schildwache der Nachtelfen getötet hat und verdächtigt wird, zwei Frachtschiffe vor der Dunkelküste versenkt zu haben.",al={"warum gurgelbacke töten","was hat gurgelbacke getan","gurgelbackes verbrechen"}},{q="Wo finde ich Gurgelbacke?",a="Gurgelbacke befindet sich weit südlich von Auberdine, am Strand bei drei Murloc-Hütten rund um ein Lagerfeuer.",al={"gurgelbacke fundort","wo ist gurgelbacke","gurgelbackes lager"}},{q="Warum ist Gurgelbacke bei meiner Ankunft nicht im Murloc-Lager?",a="Gurgelbacke hält sich verborgen. Tretet zwischen die Hütten nahe dem Lagerfeuer, und Greymist-Murlocs stürmen in Wellen aus dem Meer. Gurgelbacke erscheint mit der letzten Welle, nachdem die ersten Verteidiger gefallen sind.",al={"gurgelbacke nicht da","gurgelbacke erscheinen","wie gurgelbacke herbeirufen"}},{q="Wer gibt die Quest ab, sobald Gurgelbacke tot ist?",a="Meldet Gurgelbackes Tod bei Schildwache Glynda Nal'Shea, die in Auberdine Dienst tut.",al={"bei wem gurgelbacke abgeben","gurgelbacke abgeben","glynda nalshea standort"}},{q="Unterscheiden sich die Murlocs in diesem Lager von anderen Murlocs an der Dunkelküste?",a="Gurgelbacke befehligt die Greymist-Murlocs, darunter Küstenspäher und Krieger, die ihr Lager am Meer in aufeinander abgestimmten Wellen verteidigen.",al={"greymist-murlocs","gurgelbackes stamm","welche murlocs sind bei gurgelbacke"}}},fx={["715f24d2"]={q="Wer ist Murkdeep und warum ist er ein Ziel?",a="Murkdeep ist ein außergewöhnlich gefährlicher Murlochäuptling, der die Hütten der Graunebel-Murlocs entlang der Küste der Dunkelküste südlich von Auberdine bewacht. Im Gegensatz zu gewöhnlichen, an der Küste lebenden Plagegeistern wird er offiziell für den Tod mindestens einer Schildwache der Nachtelfen verantwortlich gemacht und verdächtigt, das Sinken zweier Frachtschiffe vor der Küste orchestriert zu haben. Seine Tödlichkeit macht ihn zu einer vorrangigen Bedrohung für die Sicherheit der Schifffahrt und die Küstenverteidigung von Auberdine.",al={"wer ist murkdeep","warum murkdeep als ziel","was hat murkdeep getan"}}},fp="17,143,36.382.0,22.278.0,22.232.0,42.74.0,59.156.0,26.90.0,52.190.0,45.74.0,71.135.0"}
P.entries["quest:475"] = {n="Ein beunruhigender Wind",s="Athridas Bearmantle erwartet Nachricht aus Sternenhauch, doch die Berichte bleiben aus. Im Grabhügel von Ban'ethil wacht der Große Wächter Gaerolas Talvethren über die schlafenden Druiden der Kralle, und sein Schweigen deutet auf Gefahr in Teldrassil hin.",h="Athridas Bearmantle erwartet Nachricht aus Sternenhauch, doch die Berichte bleiben aus.",kw={"athridas bearmantle","ban'ethil","druiden der kralle","smaragdgrüner traum","gaerolas talvethren","sternenhauch","teldrassil","beunruhigender wind","ysera"},ang={["class:Druid"]="Als Druide verehrt Ihr den Grabhügel von Ban'ethil und seine an Ysera gebundenen Schläfer zutiefst. Jede Störung ihrer Wächter verlangt sofortiges Handeln.",["race:NightElf"]="Als Nachtelf helft Ihr, die heilige Ruhe der Druiden der Kralle zu bewahren. Ihre Sicherheit schützt das empfindliche Gleichgewicht Eurer neuen Heimat auf Teldrassil."},sec={{t="Ein schweigender Wächter",b="Athridas Bearmantle verlässt sich auf regelmäßige Nachrichten von Gaerolas Talvethren, dem Großen Wächter, der über die Druiden der Kralle im Grabhügel von Ban'ethil wacht. Die Druiden schlafen dort, um ihren heiligen Pakt mit Ysera im Smaragdgrünen Traum zu wahren. Ihre Zuflucht bewahrt das spirituelle Gleichgewicht des jungen Weltenbaums. Nun bleiben die Berichte aus dem Osten aus, und Unruhe breitet sich im Wald aus."},{t="Unruhe in Sternenhauch",b="Ihr reist ostwärts durch Teldrassil nach Sternenhauch, um Gaerolas zu finden. Dort regt sich Verderbnis, und die Tiere in der Wildnis werden unruhig. Als Ihr ihn erreicht, erfahrt Ihr, dass Unheil über das Dorf gekommen ist und die nahegelegenen Grabhügel bedroht."}},faq={{q="Wer ist Athridas Bearmantle?",a="Athridas Bearmantle ist ein bedeutender nachtelfischer Aufseher in Teldrassil. Er wacht über den Wald und schützt die Zufluchtsstätten, in denen seine schlafenden druidischen Verwandten ungestört ruhen.",al={"athridas bearmantle","athridas hintergrundgeschichte","auftragsgeber athridas"}},{q="Wer ist Gaerolas Talvethren?",a="Gaerolas Talvethren ist der Große Wächter, der auserwählt wurde, die schlafenden Druiden der Kralle im nahegelegenen Grabhügel von Ban'ethil zu bewachen. Ihre Geister wandern durch den Smaragdgrünen Traum.",al={"gaerolas talvethren","großer wächter gaerolas","wer ist gaerolas"}},{q="Was ist der Grabhügel von Ban'ethil?",a="Der Grabhügel von Ban'ethil ist eine heilige unterirdische Höhlung auf Teldrassil. Nachtelfische Druiden schlafen dort lange Zeit, um mit Ysera Zwiesprache zu halten und ihre Pakte im Smaragdgrünen Traum zu ehren.",al={"grabhügel von ban'ethil","banethil","was ist ban'ethil"}},{q="Warum war Gaerolas nicht erreichbar?",a="Gaerolas konnte seine regelmäßigen Berichte nicht senden, weil Gefahr und Verderbnis Sternenhauch und den umliegenden Wald bedrohten. Er kämpfte darum, die Kontrolle zu behalten.",al={"warum schwieg gaerolas","was geschah mit gaerolas","unheil in sternenhauch"}},{q="Wohin führt diese Aufgabe als Nächstes?",a="Nachdem Ihr Gaerolas Talvethren in Sternenhauch gefunden habt, schickt er Euch mit ernsten Nachrichten zurück zu Athridas Bearmantle in Dolanaar. Die nahegelegenen Furbolgs der Gnarlpine sind einer sich ausbreitenden, unnatürlichen Verderbnis erlegen.",al={"nächste aufgabe","ein beunruhigender wind folgeaufgabe","was folgt auf ein beunruhigender wind"}},{q="Was ist der Pakt mit Ysera, der in der Aufgabe erwähnt wird?",a="Nachtelfische Druiden versinken in langen meditativen Schlummer, um an der Seite des Green Dragonflight und Yseras durch den Smaragdgrünen Traum zu wandeln. Sie dienen als Hüter des unberührten Urbilds der Natur.",al={"pakt mit ysera","ysera druidenpakt","druiden der kralle schlafen"}}},fx={["3a7b456f"]={q="Warum schickt Euch Athridas Bearmantle zu Gaerolas?",a="Athridas ist zutiefst beunruhigt, da regelmäßige Nachrichten von Gaerolas Talvethren überfällig sind. Gaerolas hält Wache über die schlafenden Druiden der Kralle, die im Grabhügel von Ban'ethil ruhen, und gewährleistet ihre Sicherheit, damit sie ihren heiligen Pakt mit Ysera im Smaragdgrünen Traum aufrechterhalten können. Da sich finstere Vorzeichen über den Ästen von Teldrassil regen, benötigt Athridas jemanden, der nach Osten zum Sternenhauch reist und bestätigt, dass die schlafenden Druiden ungestört bleiben.",al={"warum nach sternenhauch schicken","motiv von athridas bearmantle","warum die quest a troubling breeze"}}},fp="18,240,16.385.0,20.249.1,27.173.0,27.164.0,33.182.0,32.161.0,32.210.1,51.174.0"}
P.entries["quest:476"] = {n="Die Verderbnis der Knarzklauen",s="Nahe Sternenhauch bedroht die Verderbnis der Knarzklauen Teldrassil. Der verwundete Große Wächter Gaerolas Talvethren schickt Nachricht nach Dolanaar. Die Furbolgs der Knarzklauen haben das Dorf überrannt und sind dämonischer Verderbnis verfallen. Ihre Gewalt könnte die schlafenden Druiden in den Grabhügeln von Ban'ethil erreichen.",h="Nahe Sternenhauch bedroht die Verderbnis der Knarzklauen Teldrassil.",kw={"athridas bearmantle","grabhügel von ban'ethil","dolanaar","teufelsmoos","furbolg","gaerolas talvethren","die verderbnis der knarzklauen","sternenhauch","ursal the mauler"},ang={["class:Druid"]="Als Druide steht Ihr einer akuten Bedrohung für die Grabhügel von Ban'ethil und den Zirkel des Cenarius gegenüber. Eure schlafenden Brüder sind dem verderbten Stamm der Knarzklauen schutzlos ausgeliefert.",["race:NightElf"]="Als Nachtelf trifft Euch der Fall von Sternenhauch wie ein tragischer Schlag. Selbst der neu gewachsene Weltbaum ist anfällig für die dämonische Verderbnis, die Euer Volk so erbittert auszumerzen versuchte."},sec={{t="Eine verzweifelte Warnung",b="Nahe den Ruinen von Sternenhauch liegt Gaerolas Talvethren schwer verwundet. Seine einstigen Verbündeten, die Furbolgs der Knarzklauen, haben ihm aufgelauert. Einst friedliche Nachbarn und Hüter der Wildnis, sind sie nun verwildert.\n\nZu schwer verletzt, um die Warnung selbst zu überbringen, schickt Gaerolas Euch zu Athridas Bearmantle in Dolanaar. Er fürchtet, dass sich der Wahnsinn weiter in Teldrassil ausbreiten wird."},{t="Die Geißel des Teufelsmooses",b="In Dolanaar erfährt Athridas Bearmantle, dass Teufelsmagie die Furbolgs der Knarzklauen ergriffen hat. Ihr Häuptling, Ursal the Mauler, hat sich das verderbte Teufelsmoos zunutze gemacht, das im Weltbaum wuchert. Seine Macht treibt sein Volk in gewalttätige Raserei.\n\nDer Stamm bedroht Siedlungen wie Sternenhauch. Ganz in der Nähe liegen schlafende Druiden schutzlos in den Grabhügeln von Ban'ethil."}},faq={{q="Was ist mit Sternenhauch geschehen?",a="Teufelsmagie trieb die Furbolgs der Knarzklauen dazu, Sternenhauch zu überrennen und zu plündern. Ihr plötzlicher Überfall vertrieb die Bewohner oder brachte ihnen den Tod. Gaerolas Talvethren blieb verwundet nahe den Ruinen zurück und konnte nicht entkommen.",al={"warum ist sternenhauch verlassen","sternenhauch angegriffen","wer hat sternenhauch zerstört"}},{q="Warum sind die Furbolgs der Knarzklauen gewalttätig geworden?",a="Ursal the Mauler hat die Furbolgs der Knarzklauen gegen ihre einstigen nachtelfischen Verbündeten aufgebracht. Ihr Häuptling nutzt die böse Macht des Teufelsmooses auf Teldrassil, dessen dunkle Magie den Stamm in unkontrollierbare Raserei treibt.",al={"warum sind die knarzklauen wahnsinnig","wahnsinn der knarzklauen","warum furbolgs angreifen"}},{q="Wer ist Gaerolas Talvethren?",a="Gaerolas Talvethren ist der nachtelfische Große Wächter der schlafenden Druids of the Talon. Furbolgs der Knarzklauen lauerten ihm auf seinem Weg zu den Grabhügeln von Ban'ethil auf. Verwundet ist er auf Reisende angewiesen, die Nachricht von der Katastrophe nach Dolanaar bringen.",al={"gaerolas","verletzter nachtelf sternenhauch"}},{q="Wer ist Athridas Bearmantle?",a="Athridas Bearmantle ist eine bedeutende nachtelfische Autorität, die in Dolanaar stationiert ist. Er wacht über die Sicherheit der Region und hilft, Maßnahmen gegen Bedrohungen für den Weltbaum und seine Bewohner abzustimmen.",al={"athridas","athridas bearmantle dolanaar"}},{q="Warum sorgen sich die Nachtelfen um die Grabhügel von Ban'ethil?",a="In den Grabhügeln von Ban'ethil ruhen viele Druiden tief im Smaragdgrünen Traum. Wenn die rasenden Furbolgs der Knarzklauen die Grabhügel erreichen, werden die schlafenden Nachtelfen schutzlos sein.",al={"bedrohung für ban'ethil","warum sind die grabhügel von ban'ethil wichtig","schlafende druiden in gefahr"}},{q="Was ist Teufelsmoos?",a="Teufelsmoos ist ein verderbter Bewuchs in Teldrassil, durchdrungen von dunklen dämonischen Energien. Wird es berührt oder seine Macht genutzt, treibt sein Einfluss die örtlichen Wildtiere und Furbolgs in den Wahnsinn.",al={"was ist teufelsmoos","teufelsmoos teldrassil"}}},fx={d35b6598={q="Warum möchte Gaerolas Talvethren, dass dies erledigt wird?",a="Gaerolas entdeckte aus erster Hand, dass Ursal the Mauler den Gnarlpine-Stamm mit Teufelsmoos verdirbt und sie zum Amoklauf treibt. Da der Sternenhauch geplündert wurde und der heilige Grabhügel von Ban'ethil direkt bedroht ist, weiß er, dass Dolanaar sofort gewarnt werden muss, bevor die Furbolgs eine noch größere Katastrophe verursachen.",al={"motiv von gaerolas","warum nachrichten an athridas senden","grund für gaerolas quest"}},a846c6e3={q="Warum kann Gaerolas die Nachricht nicht selbst überbringen?",a="Gaerolas wurde von den verdorbenen Furbolgs aus dem Hinterhalt angegriffen und schwer verwundet, als er zum Grabhügel von Ban'ethil aufbrach. Da er den Angriff kaum überlebt hat, sind seine Verletzungen so schwer, dass er den langen Weg zurück nach Dolanaar nicht bewältigen kann, was ihn dazu zwingt, sich auf Euch zu verlassen, um die dringende Warnung an Athridas Bearmantle zu überbringen.",al={"warum braucht mich gaerolas","warum kann gaerolas nicht nach dolanaar gehen","warum ich für gaerolas"}}},fp="20,280,19.371.0,23.363.1,36.208.0,47.227.0,27.240.0,27.193.0,59.165.0,17.157.0"}
P.entries["quest:4761"] = {n="Thundris Windwirker",s="In Auberdine erfährt Thundris Windwirker, dass die Blackwood-Furbolgs feindselig geworden sind. Terenthis schickt Euch mit Nachrichten über ihre zunehmende Aggression, und Thundris sucht die Ursache der Verderbnis, die sich in Dunkelküste ausbreitet.",h="In Auberdine erfährt Thundris Windwirker, dass die Blackwood-Furbolgs feindselig geworden sind.",kw={"auberdine","blackwood","cliffspring","dunkelküste","furbolg","terenthis","thundris windwirker"},ang={["class:Druid"]="Dass die ansässigen Furbolgs und Waldbewohner so rasch der Verderbnis verfallen, deutet auf ein schweres Ungleichgewicht im Land hin. Die Cenarion-Verbündeten und Dorfältesten können das nicht ignorieren.",["faction:Alliance"]="Auberdine vor feindseligen Waldstämmen zu schützen, sichert die Versorgungslinien der Allianz und schützt Reisende auf dem Weg zwischen Kalimdor und Teldrassil.",["race:NightElf"]="Auberdine ist der wichtigste Hafen der Kaldorei und ihr Stützpunkt an der Festlandküste. Indem Ihr Ältestem Windwirker Nachrichten überbringt, unterstützt Ihr die Bemühungen Eures Volkes, seine heilige Wildnis zu bewahren."},sec={{t="Ein Bericht an den Ältesten",b="Ihr bringt Thundris Windwirker in Auberdine Terenthis’ Bericht, nachdem Ihr verderbte Furbolglager in Dunkelküste ausgekundschaftet habt. Terenthis bleibt in der Wildnis, um die sich ausbreitende Verderbnis zu untersuchen. Als Dorfältester wacht Thundris über das tägliche Leben und wägt die spirituellen Gefahren und die Bedrohungen der Umwelt ab, denen die Kaldorei gegenüberstehen. Euer Bericht liefert Auberdines Führung den Beweis, dass die Probleme der Furbolgs über Gebietsfragen hinausgehen: Eine unnatürliche Bosheit ergreift Besitz von ihnen."},{t="Verderbnis entlang der Küste",b="Thundris hat gehört, dass die Waldbewohner nahe Auberdine feindselig geworden sind. Doch die Furbolgs sind nicht seine einzige Sorge. Verderbnis breitet sich in Dunkelküstes Boden, Pflanzen und Gewässern aus. Thundris glaubt, dass das Land erst heilen kann, wenn jemand den Ursprung der Fäulnis findet. Also richtet er seine Aufmerksamkeit auf die Wasserläufe und ruft fähige Verbündete dazu auf, die Verunreinigung flussaufwärts zurückzuverfolgen."}},faq={{q="Wer ist Thundris Windwirker?",a="Thundris Windwirker führt Auberdine als Dorfältester und wacht über die Verwaltung und die täglichen Angelegenheiten des Ortes. Gemeinsam mit Schildwachen und Druiden versucht er, die sich in Dunkelküste ausbreitende Verderbnis zu verstehen und zu bekämpfen.",al={"thundris windwirker","ältester von auberdine","wer ist thundris"}},{q="Warum schickt Terenthis Euch zu Thundris?",a="Terenthis schickt Euch zur Führung Auberdines, um Bericht zu erstatten, nachdem Ihr die Lager der Blackwood-Furbolgs ausgekundschaftet habt. Thundris Windwirker hat Theorien über den Wahnsinn, der Wildtiere und Furbolgs befällt, und braucht Nachrichten aus erster Hand, um Gegenmaßnahmen abzustimmen.",al={"warum zu thundris","terenthis bericht","auberdine bericht"}},{q="Was geschieht mit den Furbolgs in Dunkelküste?",a="Die Verderbnis hat Dunkelküstes Furbolgs zunehmend gewalttätig gemacht. Ihre Feindseligkeit entspringt einer Verderbnis, die das Land vergiftet, und nicht bloß Streitigkeiten um ihr Gebiet.",al={"verderbte furbolgs","feindseligkeit der furbolgs","warum sind furbolgs wahnsinnig"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Ältester Windwirker vermutet, dass Dunkelküstes Gewässer die Ursache der Fäulnis mit sich tragen könnten. Er schickt Euch los, um Wasserproben aus dem Klippenquell zu nehmen und herauszufinden, wo die Verunreinigung beginnt.",al={"nächste quest","was nach thundris","klippenquell quest"}}},fp="19,222,21.456.0,26.359.0,27.207.0,40.230.0,47.160.0,40.165.0"}
P.entries["quest:4762"] = {n="Der Klippenquell",s="Fauliges Wasser fließt nun den Klippenquell hinab nach Auberdine. Thundris Windwirker schickt Ermittler der Allianz aus, um eine Probe aus dem Wasserfallbecken unter einer Straßenbrücke zu entnehmen. Er vermutet, dass die Verderbnis jenseits der Flussufer ihren Anfang nahm.",h="Fauliges Wasser fließt nun den Klippenquell hinab nach Auberdine.",kw={"auberdine","blackwood","klippenquell","dunkelküste","teufelswald","fluss","verderbnis","thundris","wasserfall","windweaver"},ang={["class:Druid"]="Als Druide des Zirkels des Cenarius seht Ihr, wie sauberes Waldwasser durch anhaltende dämonische Verderbnis faulig wird. Ihr seid aufgerufen, die verwundete Natur der Dunkelküste zu reinigen.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Auberdine auf die Küste der Dunkelküste angewiesen ist. Erreicht die sich ausbreitende Fäulnis den Nebelrand, bedroht sie die Heimat und Lebensgrundlagen der Kaldorei."},sec={{t="Ein verseuchter Wasserlauf",b="Vom östlichen Hochland fließt der Klippenquell zu den flachen Küstengewässern des Nebelrands, direkt nördlich von Auberdine. Nun trägt sein Wasser eine unnatürliche Fäulnis auf die Nachtelfensiedlung zu. Thundris Windwirker fürchtet, dass das faulige Wasser die Küsten und die Vorräte der Stadt vergiften wird. Deshalb schickt er Späher flussaufwärts, um Proben aus dem Wasserfallbecken unter der Straßenbrücke zu entnehmen."},{t="Die Wurzel im Teufelswald",b="Die Blackwood-Furbolgs haben entlang des Flusses Lager errichtet, und ihre Unruhe ist deutlich zu erkennen. Thundris vermutet, dass sie die Verderbnis verbreiten könnten, glaubt aber, dass ihre wahre Wurzel anderswo liegt, im Teufelswald. Er erwartet, dass die Wasserprobe seinen Verdacht bestätigt.\n\nDer Wald im Osten wurde während des Dritten Krieges gezeichnet. Um das Wasser zu reinigen, muss man den verderbten Furbolgs entgegentreten und die uralten Quellen des Landes läutern."}},faq={{q="Wo entnehme ich die Wasserprobe?",a="Begebt Euch von Auberdine aus nach Norden zur Mündung des Klippenquells am Nebelrand. Folgt dem Fluss landeinwärts bis zum ersten Wasserfall unter einer darüberführenden Straßenbrücke und füllt dann das Probenröhrchen mit Wasser aus dem Becken.",al={"wo ist die wasserprobe","klippenquell lage","wasserfallbecken lage"}},{q="Warum wird der Klippenquell faulig?",a="Thundris vermutet, dass die Blackwood-Furbolgs entlang des Flusses die Fäulnis verbreiten könnten, glaubt jedoch, dass ihre Verderbnis eine tiefere Wurzel hat. Er braucht eine Wasserprobe, um dem nachzugehen.",al={"warum ist der fluss verderbt","was vergiftet das wasser der dunkelküste","klippenquell quelle der verderbnis"}},{q="Wer ist Thundris Windwirker?",a="Thundris Windwirker ist ein Nachtelfengelehrter und Ermittler in Auberdine. Er untersucht den fortschreitenden ökologischen Verfall der Dunkelküste und sucht nach den Ursachen der Verderbnis in der Region.",al={"thundris windweaver hintergrund","wer vergibt die klippenquell-quest"}},{q="Sind die Furbolgs für die Vergiftung des Flusses verantwortlich?",a="Thundris vermutet, dass die Blackwood-Furbolgs die Verderbnis verbreiten könnten, glaubt aber, dass ihre Verderbnis eine tiefere Quelle hat. Die Wasserprobe wird ihm bei seinen Nachforschungen helfen.",al={"haben furbolgs das wasser verseucht","blackwood-furbolgs verderbnis"}},{q="Wie wirkt sich dieser Fluss auf Auberdine aus?",a="Der Klippenquell mündet direkt nördlich von Auberdine in den Nebelrand. Küstenströmungen könnten das faulige Flusswasser an die Küste der Stadt tragen und so ihre Fischerei, Pflanzenwelt und Süßwasserversorgung bedrohen.",al={"bedrohung für auberdine","warum ist der klippenquell für auberdine wichtig"}},{q="Was geschieht nach der Untersuchung der Probe?",a="Thundris dankt Euch für die Probe und bereitet weitere Nachforschungen über die verderbten Blackwood-Furbolgs vor. Er hofft, einen Weg zu finden, sie von ihrer Verderbnis zu reinigen.",al={"quest nach dem klippenquell","was folgt auf den klippenquell"}}},fx={["1995e089"]={q="Warum möchte Thundris Windwirker, dass dies erledigt wird?",a="Thundris Windwirker fürchtet, dass die Verderbnis, die sich The Cliffspring River hinunter ausbreitet, in den Nebelrand schwemmt und Auberdine selbst befleckt. Während er vermutet, dass die örtlichen Schwarzholzfurbolgs den Fluss vergiftet haben, glaubt er, dass eine tiefere, ältere Dunkelheit hinter ihrem Wahnsinn steckt. Er benötigt rohe Beweise, um die Verderbnis zu diagnostizieren und einen formalen Handlungsplan zu erstellen, bevor die Gewässer der Siedlung vollständig ruiniert sind.",al={"warum thundris wasserprobe","motiv von thundris windweaver","warum den klippenquell reinigen"}},["1f8a1dfc"]={q="Wozu dient die Probe des Klippenquells?",a="Die Probe des Klippenquells ermöglicht es Thundris Windwirker, die Fäulnis zu untersuchen, die in die Wasserwege der Dunkelküste kriecht. Die Untersuchung des verdorbenen Wassers gibt ihm den physischen Beweis, den er benötigt, um dessen Eigenschaften zu testen, dessen tieferen Ursprung zu untersuchen und ein mögliches Heilmittel vorzubereiten.",al={"nutzung der probe des klippenquells","wozu ist die wasserprobe","warum wasserprobe sammeln"}}},fp="21,236,18.369.0,19.408.1,36.198.0,42.182.1,27.168.0,53.163.1,37.194.0,38.151.1"}
P.entries["quest:4763"] = {n="Die verderbten Schwarzfelle",s="Im Norden der Dunkelküste stehen die verderbten Schwarzfelle unter einem finsteren Einfluss. Hinweise im verseuchten Wasser des Klippenquells veranlassen Thundris Windwirker, Euch dagegen auszusenden. Ihr sammelt ihre Nahrung und läutert sie mit Mondbrunnenwasser, lockt so ihren dämonischen Drahtzieher hervor und brecht seine Macht über das nördliche Lager.",h="Im Norden der Dunkelküste stehen die verderbten Schwarzfelle unter einem finsteren Einfluss.",kw={"auberdine","blackwood","dunkelküste","furbolg","mondbrunnen","satyr","talisman der verderbnis","thundris windweaver","xabraxxis"},ang={["class:Druid"]="Das Gleichgewicht wiederherzustellen bedeutet, die Fäulnis an ihrer Wurzel auszumerzen. Die Teufelstalismane eines Satyrs verderben urtümliche Waldgeschöpfe und machen die Konfrontation des Zirkels des Cenarius mit Xabraxxis dringlich.",["class:Priest"]="Elunes reine, heilende Gnade durch Mondbrunnenwasser zu kanalisieren, steht in scharfem Gegensatz zur verderblichen Schatten- und Teufelsmagie, die der Satyr wirkt.",["race:NightElf"]="Die Furbolgs waren lange mit den kaldorei befreundet. Sie unter den Einfluss ihrer uralten Feinde, der Satyrn, fallen zu sehen, ist eine bittere Tragödie, die die Nachtelfen unbedingt wiedergutmachen wollen."},sec={{t="Ein verborgener Meister",b="In Auberdine rätseln die Nachtelfen schon lange, warum sich die einst friedlichen Furbolgs der Blackwood gegen ihre Nachbarn wandten. Ihre Suche entlang des Klippenquells führte die Fäulnis auf die Einmischung von Satyrn zurück. Diese uralten Diener der Brennenden Legion manipulieren den Stamm mit Teufelsmagie. Tückische Talismane verdrehen den Furbolgs den Verstand und treiben sie zu wilder Aggression."},{t="Die Fesseln sprengen",b="Thundris Windwirker bereitet ein Heilmittel vor, um den Drahtzieher hervorzulocken. Ihr sammelt Getreide, Früchte und Nüsse aus der nördlichen Siedlung der Blackwood und tränkt sie dann in heiligem Wasser aus Auberdines Mondbrunnen. Das Wasser läutert die verseuchte Nahrung. Stellt sie an das zentrale Lagerfeuer, und die Furbolgs in der Nähe finden kurz Ruhe vor ihrem Wahnsinn. Xabraxxis, der Satyrverderber, erscheint voller Zorn, um seine Macht über das Lager zu verteidigen."}},faq={{q="Warum sind die Furbolgs der Blackwood aggressiv?",a="Dämonischer Einfluss hat den Verstand der Furbolgs vergiftet. Satyrn haben sich heimlich nahe den Lagern eingenistet und kanalisieren finstere Magie durch verzauberte Talismane. Das verkehrt die natürlichen Instinkte der Furbolgs in rasende Gewalt.",al={"warum furbolgs wahnsinnig","warum sind furbolgs feindselig","aggression der blackwood"}},{q="Wer ist Xabraxxis?",a="Xabraxxis ist ein Satyrverderber, der das nördliche Lager der Furbolgs der Blackwood überwacht. Er wirkt aus den Schatten, um den Stamm im Griff teuflischen Wahnsinns zu halten, und sichert seine Kontrolle mit einem Talisman der Verderbnis.",al={"xabraxxis hintergrund","wer ist der satyr","satyrboss dunkelküste"}},{q="Heilt die Läuterung ihrer Nahrung die Furbolgs für immer?",a="Nein. Mit Mondbrunnenwasser getränkte Nahrung vertreibt den dämonischen Nebel nur lange genug, damit die Furbolgs Frieden finden und Xabraxxis hervorgelockt wird. Den Satyr zu töten und seinen Talisman an sich zu nehmen, ist ein bedeutender Sieg, doch laut Thundris Windwirker erfordert eine dauerhafte Heilung der verderbten Stämme weitere Anstrengungen.",al={"ist die heilung dauerhaft","haben wir die furbolgs gerettet","sind furbolgs geheilt"}},{q="Woher kam die Idee, Mondbrunnenwasser zu verwenden?",a="Mondbrunnen sind heilige Becken, die von der Göttin Elune gesegnet wurden. Ihre verjüngende Magie wirkt Teufelsmagie und Untod entgegen. Thundris Windwirker stellt eine Reinigungsschale bereit, damit das geweihte Wasser die dämonischen Gifte neutralisieren kann, die die Nahrung der Furbolgs durchziehen.",al={"warum mondbrunnenwasser","mondbrunnen reinigungsschale"}},{q="Was geschieht, wenn die Nahrungsschale am Lagerfeuer aufgestellt wird?",a="Die Furbolgs in der Nähe befreien sich kurz von ihrem Blutrausch. Sie versammeln sich friedlich um die gesegnete Nahrung und stellen ihre Angriffe ein. Erzürnt darüber, dass seine Marionetten ihren Qualen entkommen, erscheint Xabraxxis sofort, um die Störenfriede zu bestrafen.",al={"schale am lagerfeuer","läuterung der furbolgs"}},{q="Wer ist Thundris Windwirker?",a="Thundris Windwirker ist ein Nachtelf, der als Forscher und Ermittler in Auberdine stationiert ist. Er koordiniert die Bemühungen, die Ursachen des schleichenden ökologischen Verfalls der Dunkelküste und des Wahnsinns ihrer Tierwelt aufzudecken.",al={"thundris windweaver hintergrund","wer vergibt die quest"}}},fx={dd154993={q="Warum möchte Thundris Windwirker, dass dies erledigt wird?",a="Thundris Windwirker sieht die Furbolgs nicht nur als gefährliche Bestien, sondern als uralte Verbündete, die durch dunkle Magie in den Wahnsinn getrieben wurden. Die Nachtelfen glauben, dass die Säuberung des dämonischen Einflusses, der den Schwarzholzstamm im Griff hat, entscheidend ist, um das Gleichgewicht der Wälder der Dunkelküste wiederherzustellen. Indem er die Wurzel der Verderbnis identifiziert und den Satyrn ihre Macht entzieht, hofft Thundris, die Furbolgs vor dem dauerhaften spirituellen Ruin zu bewahren.",al={"warum thundris helfen","ziel von thundris windweaver","warum die furbolgs reinigen"}},["3c287e3e"]={q="Wozu dient der Talisman der Verderbnis?",a="Der Talisman der Verderbnis ist ein finsteres dämonisches Relikt, das von den Satyrn kanalisiert wird, um den natürlichen Willen der Furbolgs zu untergraben. Durch ihn verdrehen Verderber die Gedanken des Schwarzholzstammes und halten einen unerbittlichen magischen Griff aufrecht, der sie in Wahnsinn und Feindseligkeit treibt. Thundris muss ihn beschlagnahmen und zerstören, um diesen Griff zu brechen und den Wald zurückzuerobern.",al={"zweck des talismans der verderbnis","was bewirkt der talisman der verderbnis","satyr-talisman"}}},fp="23,323,15.353.0,21.401.1,42.227.0,17.203.0,52.285.1,51.242.0,57.228.1,27.213.0"}
P.entries["quest:4767"] = {n="Windreiter",s="Am Freiwindposten hofft Elu, sich den Windreitern der Horde anzuschließen. Er bittet Euch, am Steilhang wilde Wyverneier zu sammeln, wo die Horde mehr Reittiere braucht.",h="Am Freiwindposten hofft Elu, sich den Windreitern der Horde anzuschließen.",kw={"elu","freiwindposten","der steilhang","tausend nadeln","windreiter","wyverneier"},ang={["class:Hunter"]="Als Jäger wisst Ihr, wie viel Sorgfalt es erfordert und welche Gefahren es birgt, wilde Gelege aus dem Nest eines revierverteidigenden Raubtiers zu holen.",["faction:Horde"]="Wyvern tragen die Horde durch ganz Kalimdor. Ihre Stallbestände aufzufüllen ist für die Verständigung und Verteidigung im Grenzland wichtig.",["race:Tauren"]="Als Tauren könnt Ihr stolz auf die Windreiter vom Freiwindposten sein, die der Pflege und Ausbildung von Wyvern hohen Wert beimessen."},sec={{t="Der Ruf des Himmels",b="In ganz Kalimdor tragen Windreiter Kuriere, Späher und Krieger der Horde über weite Entfernungen. Am Freiwindposten hofft der junge Tauren Elu, sich ihren Reihen anzuschließen. Die Horde braucht mehr Reittiere, daher soll Elu helfen, neue Wyvern für ihre Meisterwindreiter zu finden. Er bittet Reisende um Hilfe."},{t="Aufstieg zum Steilhang",b="Der Steilhang erhebt sich über die Tafelberge von Tausend Nadeln und ist ein bevorzugter Nistplatz wilder Wyvern. Um lebensfähige Eier zu sammeln, erklimmt Ihr die Klippen und stellt Euch ausgewachsenen Tieren, die ihre Nester bewachen. Elu hofft, mit den Eiern seine Hingabe zu beweisen. Dann kann er beginnen, Wyvern für die Flugmeister der Horde aufzuziehen und auszubilden."}},faq={{q="Wer vergibt diese Quest?",a="Elu gibt Euch diese Aufgabe oben auf dem Freiwindposten in Tausend Nadeln. Er hofft, ein Windreiter zu werden.",al={"windreiter questgeber","wer startet windreiter","elu standort"}},{q="Was braucht Elu?",a="Elu bittet Euch, ihm zehn Highperch Wyvern Eggs aus den Nestern am Steilhang zu bringen.",al={"windreiter questziele","was sammeln","wyverneier"}},{q="Wo liegt der Steilhang?",a="Der Steilhang liegt nordwestlich vom Freiwindposten und unmittelbar südlich vom Weißgipfelposten. Eine natürliche Rampe, die ein Totempfahl markiert, führt vom Grund der Schlucht zu den Nistplätzen.",al={"wie zum steilhang gelangen","steilhang zugang","wo sind wyverneier"}},{q="Warum sammelt die Horde wilde Wyverneier?",a="Die Meisterwindreiter der Horde müssen den wachsenden Bedarf an Flugreittieren in ihren Außenposten decken, und die Zucht in Gefangenschaft kann nicht mithalten. Die Aufzucht von Wyvern aus wilden Gelegen gibt den Tierführern neue Reittiere, die sie für Transport und Erkundung ausbilden können.",al={"warum wyverneier sammeln","geschichte hinter wyverneiern"}},{q="Sind die wilden Wyvern feindselig?",a="Ja. Wilde Wyvern verteidigen ihre Brut erbittert und greifen jeden an, der sich ihren Gelegen am Steilhang nähert.",al={"greifen wyvern an","gefahr durch wyvern"}},{q="Was hat Elu mit den Eiern vor?",a="Elu hofft, mit den Eiern seine reguläre Ausbildung zum Windreiter beginnen und Wyvern aufziehen zu können, um sich mit ihnen zu verbinden und der Horde am Himmel zu dienen.",al={"elu wyvern","was geschieht mit den eiern"}}},fp="10,150,19.286.0,19.306.0,21.101.0,19.76.0,27.166.0,44.230.0,29.116.0,41.129.0"}
P.entries["quest:477"] = {n="Grenzübergänge",s="Im Grabmal schickt Euch Schattenpriester Allister los, um Dalarans Vorräte abzufangen und herauszufinden, warum die Kirin Tor Mühlenbern unterstützen. Ihre Kisten werden durch den Silberwald zu einem Lager Dalarans nahe Lohenscheit transportiert.",h="Im Grabmal schickt Euch Schattenpriester Allister los, um Dalarans Vorräte abzufangen und herauszufinden...",kw={"mühlenbern","grenzübergänge","dalarans kiste","hillsbrad","lohenscheit","das grabmal","schattenpriester allister","silberwald"},ang={["class:Mage"]="Als Zauberwirker der Horde teilt Ihr das Interesse an Dalarans magischen Lieferungen und daran, was sie über die Geheimnisse und Schutzzauber der Kirin Tor in Lordaeron verraten könnten.",["class:Priest"]="Als Priester der Verlassenen helft Ihr Schattenpriester Allister, das Herrschaftsgebiet der Priesterschaft der Verlassenen gegen heilige und arkane Rivalen zu sichern.",["race:Undead"]="Als Untoter wisst Ihr, dass die Verlassenen einen Außenposten Dalarans an ihrer Südflanke nicht ungehindert gewähren lassen können, besonders wenn er direkt vor der Nase des Grabmals Vorräte verschickt."},sec={{t="Nachschub an der Grenze",b="Wagen bringen Dalarans Vorräte und arkane Güter aus dem Vorgebirge des Hügellands durch den Silberwald. Sie versorgen die Außenposten und Aufmarschgebiete entlang des Weges. Direkt nördlich von Lohenscheit liegt ein Lager mit Personal aus Dalaran, das die Straße überwacht. Mühlenbern ist die wichtigste verbliebene Hochburg der Menschen im östlichen Silberwald, und Dalaran unterstützt sie weiterhin."},{t="Der Verdacht der Verlassenen",b="Schattenpriester Allister und die Anführer der Verlassenen im Grabmal wollen wissen, warum Dalaran Mühlenbern so stark unterstützt. Sie vermuten, dass die Kirin Tor nicht allein für eine Provinzstadt Leben und Vorräte tief im Gebiet der Verlassenen riskieren würden. Ein größeres strategisches oder magisches Ziel könnte dahinterstecken. Das Abfangen der Kisten könnte den Verlassenen zeigen, was Dalaran nach Westen schickt."},{t="Die Fracht aufdecken",b="Die Kiste, die Ihr für Allister bergen sollt, enthält mehr als Proviant. Darin liegen alte Karten des Silberwalds und des westlichen Lordaerons sowie ein magischer Anhänger. Die Fracht umfasst auch arkane Gegenstände und Karten, doch ihr Zweck bleibt unklar."}},faq={{q="Warum sind Dalarans Zauberer im Silberwald aktiv?",a="Dalaran handelt von Mühlenbern aus, um die Präsenz der Menschen und der Allianz im westlichen Lordaeron aufrechtzuerhalten. Schattenpriester Allister vermutet, dass die Kirin Tor mehr als die Verteidigung eines ländlichen Weilers anstreben, weshalb die Verlassenen ihre Nachschubwege ins Visier nehmen.",al={"warum ist dalaran hier","dalaran silberwald","warum dalaran in mühlenbern"}},{q="Wo befinden sich die Kisten Dalarans?",a="Die Kisten befinden sich in einem Lager Dalarans direkt nördlich von Lohenscheit, abseits der Hauptstraße. Magier und Wachen Dalarans bewachen sie.",al={"standort der kisten","wo sind die kisten","lager bei pyrewood"}},{q="Was befindet sich in der Kiste Dalarans?",a="Schattenpriester Allister weiß nicht, was Dalaran verschickt. Er bittet Euch, den Inhalt einer Kiste aus dem Lager nördlich von Lohenscheit zurückzubringen, damit er ihn untersuchen kann.",al={"kisteninhalt","was ist in der kiste"}},{q="Wer ist Schattenpriester Allister?",a="Schattenpriester Allister ist ein bedeutender Anführer der Verlassenen im Grabmal im Silberwald. Er leitet die Aufklärung und Angriffe gegen die letzten Stellungen der Menschen und Dalarans Vorstöße.",al={"schattenpriester allister","wer vergibt grenzübergänge"}},{q="Wie gelangen die Vorräte in den Silberwald?",a="Wagen bringen die Lieferungen aus Dalarans Gebiet im Vorgebirge des Hügellands über den Grenzpass in den Silberwald. Von dort erreichen sie die Aufmarschlager nahe Mühlenbern und Pyrewood.",al={"dalarans nachschubroute","wagen im hügelland"}},{q="Was folgt nach Abschluss dieser Quest?",a="Nachdem Ihr die Kiste untersucht habt, bringt Eure Funde zu Schattenpriester Allister, damit er sie in Maps and Runes erforschen kann.",al={"was kommt danach","folgequest","nächste quest"}}},fx={["3c89d6a1"]={q="Warum möchte Schattenpriester Allister, dass dies erledigt wird?",a="Mühlenbern steht als sturer Hort menschlichen Widerstands im Silberwald, der fast vollständig durch die arkane Unterstützung von Dalaran befestigt und aufrechterhalten wird. Schattenpriester Allister vermutet, dass die Magier eine tiefere, verborgene Agenda verfolgen, wenn sie so stark in eine solche abgelegene Stadt investieren. Indem die Verlassenen die Wagenlieferungen abfangen, die in ihren Außenposten nördlich von Pyrewood strömen, hoffen sie, Dalarans wahre Motive aufzudecken und einen wachsenden Stützpunkt der Allianz direkt vor der Haustür der Unterstadt zu beseitigen.",al={"warum will allister die kiste","motiv von schattenpriester allister","warum dalaran-vorräte stehlen"}}},fp="16,219,24.360.0,24.377.0,20.242.1,52.223.0,37.124.0,33.175.1,30.185.0,52.185.0,42.105.1"}
P.entries["quest:4770"] = {n="Auf der Heimreise",s="Pao'ka Bergrausch sitzt zwischen den Wyvern des Steilhangs fest. Ihr helft dem jungen Tauren-Naturforscher, den Schluchtboden zu erreichen und zum Weißgipfelposten zurückzukehren, nachdem er in ihre Nistgründe geraten ist.",h="Pao'ka Bergrausch sitzt zwischen den Wyvern des Steilhangs fest.",kw={"eskorte","der steilhang","auf der heimreise","motega feuermähne","pao'ka bergrausch","tausend nadeln","weißgipfelposten","wyvern"},ang={["faction:Horde"]="Als Mitglied der Horde kennt Ihr Wyvern vielleicht als Verbündete und Reittiere in ganz Kalimdor. Die wilden Wyvern des Steilhangs wecken durch ihr Wesen und ihren strategischen Wert Interesse.",["race:Tauren"]="Als Tauren kennt Ihr die Pflichten, die Stämme und Älteste gemeinsam tragen. Motegas Versprechen an Pao'kas Vater spiegelt die Bande wider, die ihre Feldstudien leiten."},sec={{t="Ein überforderter Naturforscher",b="Pao'ka Bergrausch kam mit dem Ältesten Motega Feuermähne nach Tausend Nadeln. Sie wollten die Tierwelt des Schluchtbodens und die aufragenden Steinsäulen erforschen. Neugierig und allzu selbstsicher ging Pao'ka allein zum Steilhang, um dessen Wyvern aus der Nähe zu beobachten. Die revierverteidigenden Bestien vertrieben ihn. Nun sitzt der junge Gelehrte seit Tagen verängstigt zwischen den Felsen fest."},{t="Der Weg die Felsen hinab",b="Überall am Steilhang bewachen aggressive Wyvern ihre Gelege und hoch gelegenen Nistplätze. Ihr bahnt einen Weg durch die nistenden Raubtiere, damit Pao'ka ebenen Boden erreichen kann. Der panische Jüngling kann sich im Freien nicht verteidigen und verlässt sich auf vorbeikommende Reisende der Horde, um die Wyvern abzuwehren. Er muss den sichereren Schluchtpfad erreichen, der nach Osten führt."},{t="Erleichterung und Rechenschaft",b="Pao'ka erreicht den Fuß der Klippen und kann sich auf den Heimweg zum Weißgipfelposten machen. Motega Feuermähne ist fassungslos über das Geschehene. Er hatte Pao'kas zögerlichem Vater versprochen, während ihrer Feldstudien auf den Jungen aufzupassen. Erleichtert, dass Pao'ka seine leichtsinnige Expedition überlebt hat, belohnt Motega seine Retter. Insgeheim wünscht er, er hätte den Lehrling an ein Totem gekettet."}},faq={{q="Wer ist Pao'ka Bergrausch?",a="Pao'ka Bergrausch ist ein junger Tauren-Lehrling, der mit Motega Feuermähne nach Tausend Nadeln kam, um wilde Tiere zu erforschen und seine Beobachtungen aufzuzeichnen. Seine jugendliche Begeisterung führte ihn allein zum Steilhang.",al={"paoka","pao'ka","wer ist der eskort-nsc"}},{q="Warum versteckte sich Pao'ka am Steilhang?",a="Pao'ka ging allein zu den Nistplätzen, um die heimischen Wyvern und ihre Nester aus der Nähe zu beobachten. Die aggressiven Bestien griffen ihn an, zwangen ihn, sich zu verstecken, und hielten ihn auf dem hohen Tafelberg gefangen.",al={"warum ist paoka am steilhang","was ist paoka passiert","warum sitzt er fest"}},{q="Wer ist Motega Feuermähne?",a="Motega Feuermähne ist ein Tauren-Naturforscher, der am Weißgipfelposten in Tausend Nadeln stationiert ist. Pao'kas Vater vertraute ihm die Sicherheit des Jünglings während ihrer Feldstudien an.",al={"motega","wer ist motega feuermähne","nsc zur questabgabe"}},{q="Wo liegt der Steilhang?",a="Der Steilhang ist ein hoher Tafelberg und ein Nistgebiet der Wyvern im Westen von Tausend Nadeln. Er liegt unmittelbar westlich vom Weißgipfelposten und nordwestlich vom Freiwindposten.",al={"steilhang lage","wo ist der steilhang","von wo aus wird er eskortiert"}},{q="Wo ist der Weißgipfelposten?",a="Der Weißgipfelposten ist ein kleines Lager der Horde östlich des Steilhangs in Tausend Nadeln. Tauren-Naturforscher nutzen es als Stützpunkt für ihre Feldstudien zur Tierwelt der Schlucht.",al={"weißgipfelposten lage","wo ist der weißgipfelposten"}},{q="Weiß Motega, dass Pao'ka vermisst wurde?",a="Nein. Pao'ka schlich sich zum Steilhang davon, ohne Motega etwas zu sagen. Motega wusste nicht, dass sein Lehrling in Gefahr war, bis Ihr von der Rettung berichtet.",al={"wusste motega bescheid","warum hat motega nicht nach ihm gesucht"}}},fx={["17b8918e"]={q="Warum möchte Pao'ka Bergrausch, dass dies erledigt wird?",a="Pao'ka schlich sich allein in Der Steilhang, um die Wyvern zu beobachten, und wurde in die Enge getrieben, nachdem er sich zu nahe an ihre Nester gewagt hatte. Da er gefangen ist und seit Tagen zwischen aggressiven Raubtieren feststeckt, kann er sich nicht alleine herauskämpfen. Schlimmer noch, er weiß, dass Motega Feuermähne wütend sein wird, wenn seine leichtsinnige Expedition entdeckt wird, was eine eskortierte Flucht zu seiner einzigen Hoffnung macht, um zu überleben und zum Weißgipfelposten zurückzukehren.",al={"warum paoka helfen","motiv von paoka","warum braucht paoka eine eskorte"}},edb8f2eb={q="Warum muss Pao'ka von Euch eskortiert werden und nicht von den Wachen?",a="Pao'ka hat sich heimlich vom Weißgipfelposten weggeschlichen, und niemand im Lager weiß überhaupt, dass er vermisst wird. Die Wachen zu rufen würde seinen Ungehorsam gegenüber Motega Feuermähne enthüllen, aber noch dringender ist, dass er seit Tagen in der Adlerwarte feststeckt, ohne einen Verbündeten zu sehen. Ihr seid einfach der erste freundliche Reisende, der über sein Versteck gestolpert ist.",al={"warum ich für paoka","warum ruft paoka keine wachen","warum paoka allein helfen"}}},fp="14,211,29.366.0,23.328.0,20.385.1,28.189.0,35.184.0,23.170.0,27.150.0,25.162.0,36.138.1"}
P.entries["quest:478"] = {n="Karten und Runen",s="Im Silberwald offenbaren Karten und Runen Dalarans Interesse an Mühlenbern. Agenten der Horde bergen eine verborgene Kiste für Schattenpriester Allister am Grabmal.",h="Im Silberwald offenbaren Karten und Runen Dalarans Interesse an Mühlenbern.",kw={"mühlenbern","kiste aus dalaran","kirin tor","karten und runen","mit runen beschrifteter anhänger","schattenpriester allister","silberwald","das grabmal"},ang={["class:Mage"]="Als Magier wisst Ihr, dass der mit Runen beschriftete Anhänger Verzauberungsmuster der Kirin Tor trägt, geprägt von Dalarans Tradition der Schutzschilde und arkanen Schutzzauber.",["class:Priest"]="Als Priester wisst Ihr, dass selbst Schattenpriester Allisters gewaltige Shadow Magic die kunstvollen arkanen Formeln nicht entschlüsseln kann, die in den Anhänger geritzt sind.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Sicherung des Silberwalds gegen mit der Allianz verbündete Kräfte wie die Kirin Tor einen lebenswichtigen Nachschubkorridor durch das nördliche Lordaeron schützt.",["race:Undead"]="Als Untoter wisst Ihr, dass Dalarans überlebende Zauberer Außenposten nahe dem Herrschaftsgebiet von Unterstadt unterhalten. Ihre verzauberten Talismane zu bergen hilft, die Souveränität der Verlassenen im Silberwald zu sichern."},sec={{t="Eine verborgene Fracht",b="Agenten der Horde finden eine Kiste aus Dalaran, die entlang der Grenzrouten nahe Mühlenbern verborgen ist. Darin liegen detaillierte Regionalkarten und ein mit Runen beschrifteter Anhänger. Menschliche Wachen stehen in der Nähe, also bergen die Kundschafter das Artefakt vorsichtig. Dalarans arkaner Einfluss reicht bis nahe an ihre Grenzen."},{t="Flüstern am Grabmal",b="Am Grabmal nimmt Schattenpriester Allister den geborgenen Anhänger entgegen. Die Führung der Verlassenen erkennt, dass die Kirin Tor in Mühlenbern tätig sind, doch ihre Absichten bleiben unklar. Allister kann die mächtige Zauberei nicht entschlüsseln, die in die Runen gewoben ist. Er sucht arkane Experten unter den Untoten, um Dalarans Plan aufzudecken."}},faq={{q="Was befindet sich in der Kiste aus Dalaran?",a="Die Kiste aus Dalaran enthält detaillierte Regionalkarten und einen seltsamen, mit Runen beschrifteten Anhänger. Zusammen deuten sie darauf hin, dass Dalaran Pläne für das Gebiet um Mühlenbern schmiedet.",al={"was war in der kiste","kisteninhalt","beute aus dalarans kiste"}},{q="Wer ist Schattenpriester Allister?",a="Schattenpriester Allister ist eine bedeutende Autorität der Verlassenen und am Grabmal stationiert. Er beaufsichtigt die örtliche Informationsbeschaffung und koordiniert die Verteidigung gegen feindliche menschliche Überreste und Agenten der Kirin Tor im Silberwald.",al={"wer ist allister","geschichte von schattenpriester allister"}},{q="Warum bereitet Dalarans Anwesenheit in Mühlenbern den Verlassenen Sorgen?",a="Die Verlassenen fürchten Dalarans Präsenz in Mühlenbern, an der Grenze zu den Gebieten in Lordaeron, die sie beanspruchen. Arkane Relikte oder geheime Truppenbewegungen könnten Unterstadts Kontrolle über den Silberwald bedrohen.",al={"warum mühlenbern wichtig ist","konflikt zwischen verlassenen und dalaran"}},{q="Kann Schattenpriester Allister den Anhänger entschlüsseln?",a="Nein. Allister erkennt Dalarans Zauberei auf dem Anhänger, doch seine priesterlichen Künste reichen nicht aus, um dessen Verzauberungen zu entschlüsseln. Er sucht tieferes arkanes Wissen.",al={"kennt allister die runen","kann allister den anhänger lesen"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Die Untersuchung geht mit Dalar's Analysis weiter. Der Anhänger geht an Dalar Morgenweber, einen arkanen Spezialisten am Grabmal, der die Magie der Kirin Tor aufschlüsseln kann.",al={"was ist die nächste quest","nach karten und runen"}},{q="Welche Quest führt zu Karten und Runen?",a="Border Crossings führt zu Karten und Runen. Darin beauftragen die Verlassenen einen Agenten, verdächtige Handelsfrachtkisten zu untersuchen, die von Dalarans Grenzen in den Silberwald gelangen.",al={"vorausgesetzte quest","voraussetzung für karten und runen"}}},fp="14,150,14.274.0,25.305.1,33.147.0,30.228.0,58.191.0,48.136.0,40.162.0,38.165.0"}
P.entries["quest:4787"] = {n="Das uralte Ei",s="In Tanaris sucht Yeh'kinya das Uralte Ei, das in der Prophecy of Mosh'aru erwähnt wird. Es stammt aus dem Zeitalter der Trollreiche, und er möchte, dass Ihr es aus Jintha'Alor im Hinterland holt.",h="In Tanaris sucht Yeh'kinya das Uralte Ei, das in der Prophecy of Mosh'aru erwähnt wird.",kw={"uraltes ei","hakkar","hinterland","jintha'alor","mosh'aru","prophezeiung","tanaris","yeh'kinya"},sec={{t="Ein Relikt der Trollreiche",b="Die Prophecy of Mosh'aru erzählt von einem Uralten Ei aus dem Zeitalter, als Trolle riesige Reiche beherrschten. Seine Macht kann Hakkars Essenz in sich aufnehmen. Yeh'kinya glaubt, dass es der einzige Weg sein könnte, die Welt vor seinem Bösen zu bewahren."},{t="Hinter dem Amphitheater",b="Yeh'kinya bittet Euch, das Ei nach Tanaris zu bringen. Erzählungen zufolge liegt es tief im Inneren von Jintha'Alor im Hinterland, in einer Höhle hinter dem Amphitheater ganz oben in der Stadt. Große Kräfte regen sich, und Yeh'kinya fürchtet, dass die Zeit knapp wird."}},faq={{q="Was ist das Uralte Ei?",a="Ein Relikt aus dem Zeitalter, als Trolle riesige Reiche beherrschten, von dem die Prophecy of Mosh'aru erzählt. Seine Macht kann Hakkars Essenz in sich aufnehmen.",al={"uraltes ei hintergrund","was bewirkt das ei","prophecy of mosharu ei"}},{q="Warum will Yeh'kinya das Ei?",a="Yeh'kinya glaubt, dass das Ei der einzige Weg sein könnte, die Welt vor Hakkars Bösem zu bewahren.",al={"warum das ei finden","yehkinyas absicht","hakkar mit dem ei aufhalten"}},{q="Wo ist das Ei verborgen?",a="Erzählungen zufolge liegt das Ei tief im Inneren von Jintha'Alor im Hinterland, in einer Höhle hinter dem Amphitheater ganz oben in der Stadt.",al={"wo ist das uralte ei","uraltes ei fundort","ei höhle jinthaalor"}},{q="Wer möchte das Ei gebracht bekommen?",a="Yeh'kinya wartet in Tanaris und möchte, dass Ihr das Uralte Ei dorthin bringt.",al={"wer startet uraltes ei","wer vergibt die quest","yehkinya questgeber"}}},fp="15,184,24.209.0,23.217.0,24.126.0,32.85.0,24.112.0,34.72.0"}
P.entries["quest:479"] = {n="Nachforschungen in Mühlenbern",s="In Mühlenbern weben Zauberer aus Dalaran Magie, die die Herrschaft der Verlassenen über den Silberwald bedroht. Vom Grabmal aus entsendet Schattenpriester Allister Agenten, um ihre Arbeit zu stören und die magischen Foki an sich zu bringen.",h="In Mühlenbern weben Zauberer aus Dalaran Magie, die die Herrschaft der Verlassenen über den Silberwald...",kw={"allister","mühlenbern","dalar","dalaran","kirin tor","anhänger","das grabmal","silberwald"},ang={["class:Mage"]="Als Magier wisst Ihr, dass ein großes arkanes Ritual genaue Abstimmung erfordert. Die verzauberten Foki der Kirin Tor zu entfernen, stört ihre Zauberkunst.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Kontrolle über den Silberwald Lordaerons westliche Zugänge vor Außenposten schützt, die der Allianz angehören und Dalaran treu sind.",["race:Undead"]="Die Überreste der Kirin Tor in Mühlenbern befinden sich nahe dem Gebiet von Unterstadt. Ihre Magie bedroht das Überleben der Verlassenen."},sec={{t="Eine Bedrohung aus dem Osten",b="Mühlenbern liegt in den östlichen Hügeln des Silberwalds. Seine menschlichen Bewohner sind Zauberer und Verteidiger, die den Kirin Tor von Dalaran die Treue geschworen haben. Die Magier weben mächtige Magie in einem gewaltigen Ritual. Im Grabmal erkennen Schattenpriester Allister und sein Gefährte Dalar die Gefahr. Wenn die Kirin Tor ihre Macht ungehindert kanalisieren, drohen die Verlassenen den Silberwald vollständig zu verlieren."},{t="Das Gewirke stören",b="Während Dalar den Wald hellseherisch erkundet und der Magie nachspürt, entsendet Allister Agenten gegen die Zauberwirkenden in Mühlenbern. Beschwörer, Magier und ihre Beschützer aus Dalaran tragen verzauberte Anhänger, die ihre Künste bündeln und aufeinander abstimmen. Nehmt den erschlagenen Zauberern die Talismane ab, und das Ritual gerät ins Stocken. Das verschafft dem Grabmal Zeit, den Rädelsführer ausfindig zu machen, der das arkane Gewirke lenkt."}},faq={{q="Warum nimmt Schattenpriester Allister Mühlenbern ins Visier?",a="Die Magier der Kirin Tor in Mühlenbern kanalisieren mächtige arkane Energien. Allister fürchtet, dass ihre Zauber die Verlassenen die Kontrolle über den Silberwald kosten könnten.",al={"warum mühlenbern angreifen","allisters beweggrund","bedrohung durch mühlenbern"}},{q="Wozu dienen die Anhänger aus Dalaran?",a="Beschwörer, Magier und Beschützer aus Dalaran tragen die Anhänger, um ihre Zauberkunst zu bündeln. Sie ihnen abzunehmen schwächt die Bemühungen der Zauberer und hilft Allister, die magischen Fortschritte der Kirin Tor zu untersuchen.",al={"was sind anhänger aus dalaran","zweck der anhänger","warum anhänger sammeln"}},{q="Wo liegt Mühlenbern?",a="Mühlenbern liegt in den östlichen Hügeln des Silberwalds. Folgt vom Grabmal aus der Hauptstraße nach Süden und nehmt dann die östliche Abzweigung in die Stadt.",al={"lage von mühlenbern","weg nach mühlenbern","wo liegt mühlenbern"}},{q="Wer ist Dalar, und wie ist er daran beteiligt?",a="Dalar ist ein Zauberwirker der Verlassenen im Grabmal, der mit Schattenpriester Allister zusammenarbeitet. Er spürt der Magie nach und sucht ihre Quellen, die den Zauberern aus Dalaran in Mühlenbern Kraft verleihen.",al={"wer ist dalar","dalars rolle","dalar silberwald"}},{q="Was geschieht nach der Bergung der Anhänger?",a="Die Anhänger offenbaren, dass ein fähiger Zauberer ein bereits weit fortgeschrittenes Ritual Dalarans leitet. Dieser Zauberer muss gestellt werden, um das Zauberwirken vollständig zu unterbinden.",al={"was geschieht als nächstes","fortsetzung von nachforschungen in mühlenbern","nach anhängern aus dalaran"}},{q="Warum sind noch Menschen aus Dalaran im Silberwald?",a="Vor dem Dritten Krieg war Mühlenbern eine kleine Holzfällerstadt. Nach der Verwüstung ihres Königreichs zeigten die überlebenden Kirin Tor Interesse an der Stadt und halten sie weiterhin gegen die Geißel und die Verlassenen.",al={"warum sind menschen aus dalaran hier","kirin tor im silberwald","geschichte von mühlenbern"}}},fx={fc82e396={q="Gegen wen werdet Ihr in Mühlenbern ausgesandt?",a="Schattenpriester Allister schickt Euch direkt gegen die menschlichen Streitkräfte, die die befestigte Stadt Mühlenbern halten: Dalaran-Beschwörer, Magier und ihre Beschützer. Während Dalaran selbst weiter östlich liegt, unterhalten diese Zauberer und Wachen hier im Silberwald eine Festung und kanalisieren aktiv gefährliche Magie, die die Kontrolle der Verlassenen über den Wald bedroht.",al={"wer sind die ziele","gegner in mühlenbern","gegen wen kämpfe ich in mühlenbern"}}},fp="24,206,22.364.0,20.364.0,50.161.0,39.184.0,27.147.0,37.176.0,43.159.1,50.197.0"}
P.entries["quest:480"] = {n="Der Wirker",s="Im Silberwald arbeitet Ataeric daran, einen ruhenden Leyknoten für Dalaran zu erwecken. Im Grabmal schickt Schattenpriester Allister Euch los, den Erzmagier aufzuhalten und seinen Stab zu nehmen, damit Dalarans Magie die Herrschaft der Verlassenen über das südliche Lordaeron nicht bedroht.",h="Im Silberwald arbeitet Ataeric daran, einen ruhenden Leyknoten für Dalaran zu erwecken.",kw={"allister","mühlenbern","ataeric","dalaran","kirin tor","leyenergie","das grabmal","silberwald","wirker"},ang={["class:Mage"]="Als Magier wisst Ihr, dass Leylinien eine tiefgehende Beherrschung arkaner Geometrie erfordern. Ataerics Fall zeigt, wie empfindlich solche Rituale werden, wenn ihre wichtigsten Leitbahnen verloren gehen.",["class:Priest"]="Als Priester seht Ihr, wie Schattenpriester Allister diesen Einsatz mit kalter Entschlossenheit leitet, um einen arkanen Katalysator auszulöschen, bevor dessen Macht wächst.",["faction:Horde"]="Als Mitglied der Horde steht Ihr Dalarans feindseligen Überresten gegenüber. Jeder Zuwachs ihrer arkanen Stärke bedroht die Ländereien der Horde im nördlichen Lordaeron.",["race:Undead"]="Als Untoter steht Ihr Dalarans lebenden Magiern gegenüber, die den Verlassenen die Herrschaft über die Ruinen von Lordaeron streitig machen. Ihren Erzmagier aufzuhalten hilft, das Umland des Grabmals zu sichern."},sec={{t="Den Leyfaden durchtrennen",b="Nach Euren früheren Nachforschungen über Mühlenbern und Dalarans Bewegungen erfuhren die Verlassenen, dass dessen Zauberer einen ruhenden Leyenergieknoten im Silberwald erwecken wollen. Dalaran könnte diese geballte arkane Macht nutzen, um seine Stellung zu stärken und Unterstadts Herrschaft über das südliche Lordaeron zu bedrohen."},{t="Der Fall des Erzmagiers",b="Schattenpriester Allister weiß, dass die Arbeit an ihrem Ursprung beendet werden muss. Erzmagier Ataeric leitet sie, geschützt durch Schutzzauber und andere Magier. Tötet ihn und nehmt seinen Stab an Euch, und die gesammelte Magie zerstreut sich. Die Leyenergien kommen wieder zur Ruhe und vereiteln so die Pläne der Kirin Tor im Tal."}},faq={{q="Wer ist der Wirker?",a="Erzmagier Ataeric ist der Wirker, ein mächtiger Zauberwirker Dalarans im Silberwald. Er will die verborgenen Leyenergien unter dem Gebiet verbinden und erwecken.",al={"wer ist der wirker","erzmagier ataeric","ataeric wirker"}},{q="Warum wollen die Verlassenen den Erzmagier töten lassen?",a="Die Verlassenen fürchten, dass Dalaran dem ruhenden Leyknoten nahe Unterstadt gewaltige arkane Macht entziehen wird. Schattenpriester Allister sieht darin eine Bedrohung für die Souveränität der Verlassenen und befiehlt, Ataeric zu töten, bevor der Knoten vollständig erwacht.",al={"warum ataeric töten","konflikt verlassene dalaran","warum dalaran angreifen"}},{q="Was geschieht nach Ataerics Niederlage?",a="Wenn Ataeric getötet wird und Ihr seinen Stab an Euch nehmt, bricht das arkane Netzwerk zusammen. Die gesammelten Zauber lösen sich auf und die Leylinie kommt wieder zur Ruhe, wodurch die Kirin Tor ihren wichtigsten Stützpunkt arkaner Macht im südlichen Silberwald verlieren.",al={"nach dem wirker","ausgang der quest","was geschieht mit dem leyknoten"}},{q="Wer schickt Euch auf diese Quest?",a="Schattenpriester Allister schickt Euch vom Grabmal im Silberwald aus los. Er erteilt den Befehl, nachdem er frühere Berichte über Dalarans Präsenz rund um Mühlenbern geprüft hat.",al={"wer vergibt der wirker","allister quest","questgeber wirker"}},{q="Welche Bedeutung hat Ataerics Stab?",a="Erzmagier Ataerics Stab bündelt und kanalisiert die Leyenergien der Region. Ihn an Euch zu nehmen stellt sicher, dass sich die Magie vollständig auflöst, und verschafft Allister ein Artefakt, das er für die eigenen Vorhaben der Verlassenen untersuchen kann.",al={"ataerics stab","zweck des erzmagierstabs","warum den stab nehmen"}},{q="Woher stammt Dalarans Präsenz im Silberwald?",a="Obwohl Dalaran im Dritten Krieg verwüstet wurde, unterhalten Überreste der Kirin Tor befestigte Enklaven, Außenposten und arkane Experimente in nahe gelegenen Gebieten wie Mühlenbern. Sie wollen die Kontrolle zurückgewinnen und lebenswichtige magische Reserven nutzbar machen.",al={"dalaran im silberwald","warum sind dalarans magier im silberwald","mühlenbern dalaran"}}},fp="10,239,23.310.0,19.272.1,18.154.0,45.225.0,39.232.1,28.174.0,44.202.0,54.240.0"}
P.entries["quest:481"] = {n="Dalars Analyse",s="Im Silberwald führt Allisters Bericht dazu, dass ein Relikt aus Dalaran zur Untersuchung zu Dalar gelangt. Ein mit Runen beschrifteter Anhänger aus einer Vorratskiste erreicht Dalar Morgenweber im Grabmal. Das Relikt zeigt, dass Dalarans überlebende Magier große magische Macht für einen verborgenen Zweck sammeln.",h="Im Silberwald führt Allisters Bericht dazu, dass ein Relikt aus Dalaran zur Untersuchung zu Dalar gelangt.",kw={"mühlenbern","dalar morgenweber","dalaran","kirin tor","anhänger","das grabmal","schattenpriester allister","silberwald"},ang={["class:Mage"]="Als Magier der Verlassenen erkennt Ihr den Anhänger der Kirin Tor vielleicht als traditionelles Werkzeug der Zauberwirkerei Dalarans. Seine Anwesenheit deutet darauf hin, dass Eure einstigen Mitstreiter eine gewaltige Beschwörung vorbereiten.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Vorhaben der Kirin Tor im Silberwald zu vereiteln und die Östlichen Königreiche vor wiedererstarkenden, mit der Allianz verbündeten magischen Gruppierungen zu schützen.",["race:Undead"]="Als Mitglied der Verlassenen helft Ihr, Dalarans Aktivitäten in Mühlenbern zu überwachen, um die Grenzen des Silberwalds zu sichern und das Grabmal vor feindlicher Zauberei zu schützen."},sec={{t="Die Fracht eines Kuriers",b="Eine Vorratskiste aus Dalaran wird in einem Lager nördlich von Lohenscheit geplündert. Unter alten Karten findet Schattenpriester Allister einen mit Runen beschrifteten Anhänger. Seine Verzauberung übersteigt Allisters geistliches Wissen, also schickt er ihn zu Dalar Morgenweber im Grabmal. Dalars Fähigkeiten als arkaner Gelehrter machen ihn besser geeignet, Dalarans magische Schutzzauber zu entschlüsseln."},{t="Machenschaften der Kirin Tor",b="Dalar Morgenweber erkennt in dem Anhänger einen spezialisierten Energieleiter, den hochrangige Zauberer der Kirin Tor einst bevorzugten. Er erlaubt ihnen, mächtige Magie zu kanalisieren. Viele solcher Relikte werden direkt ins befestigte Mühlenbern geschickt, ein Zeichen dafür, dass die Zauberer ein Unterfangen von gewaltigem Ausmaß vorbereiten. Dalar untersucht ihre Schutzzauber, um ihre Absichten zu ergründen."}},faq={{q="Was ist der mit Runen beschriftete Anhänger?",a="Der Anhänger ist ein arkaner Energieleiter, mit dem hochrangige Magier der Kirin Tor große Mengen magischer Energie sicher kanalisieren. Dass er unterwegs entdeckt wurde, deutet darauf hin, dass Mühlenbern mächtige Foki für hochstufige Zauberkunst erhält.",al={"was ist der anhänger","geschichte des anhängers der kirin tor","mühlenbern anhänger"}},{q="Warum schickt Schattenpriester Allister den Anhänger zu Dalar Morgenweber?",a="Schattenpriester Allister arbeitet mit Schattenmagie und sammelt im Grabmal Informationen für die Verlassenen. Da der Anhänger ein komplexes arkanes Relikt aus Dalaran ist, schickt er ihn zu Dalar Morgenweber, um seine Runen zu untersuchen und seinen Zweck zu bestimmen.",al={"warum dalar","wer ist dalar morgenweber","warum zum grabmal schicken"}},{q="Wo liegt Mühlenbern und warum überwachen die Verlassenen den Ort?",a="Mühlenbern ist eine befestigte Menschenstadt im südöstlichen Silberwald, die von Dalarans Magiern unterhalten wird. Tief in dem von Fürstin Sylvanas Windläufer beanspruchten Gebiet stellt sie eine militärische und magische Bedrohung für die Verlassenen dar, die ihre Grenzen genau beobachten.",al={"warum mühlenbern überwachen","mühlenberns zauberer","dalaran im silberwald"}},{q="Was geschieht, nachdem Dalar den Anhänger analysiert hat?",a="Dalar erkennt, dass die Kirin Tor Energieleiter für ein großes Unterfangen sammeln. In Dalaran's Intentions, der folgenden Aufgabe, blickt er mithilfe von Magie durch Mühlenberns Schutzschilde und entdeckt, was die Zauberer planen.",al={"what comes next","nach dalars analyse","dalarans absichten"}},{q="Wo ist Dalar Morgenweber zu finden?",a="Dalar Morgenweber ist in der Krypta im Grabmal zu finden, dem Hauptstützpunkt der Verlassenen im Silberwald, der an der Hauptstraße liegt.",al={"dalars standort","wo ist dalar","dalar morgenweber silberwald"}},{q="Warum agieren die Kirin Tor offen im Silberwald?",a="Bevor die Geißel Lordaeron verwüstete, war Mühlenbern eine ruhige Holzfällerstadt. Obwohl die Hauptstadt und Dalaran fielen, machten überlebende Zauberer Mühlenbern zu einem aktiven Bollwerk, in dem sie ständig gegen die Ausbreitung der Verlassenen kämpfen.",al={"kirin tor silberwald","dalarans präsenz im silberwald"}}},fp="16,271,17.345.0,22.329.1,35.209.0,69.244.0,58.249.0,46.232.1,36.138.0,60.217.0"}
P.entries["quest:4811"] = {n="Der rote Kristall",s="Schildwache Glynda Nal'Shea bittet Euch, einen roten Kristall in den östlichen Bergen der Dunkelküste zu untersuchen. Mondkinklauen vermehren sich in der Nähe und scheinen von ihm angezogen zu werden, und die Schildwachen müssen wissen, ob der Kristall wirklich existiert.",h="Schildwache Glynda Nal'Shea bittet Euch, einen roten Kristall in den östlichen Bergen der Dunkelküste zu...",kw={"auberdine","dunkelküste","glynda nal'shea","mondkinklauen","roter kristall","schildwachen"},ang={["class:Druid"]="Als Druide seid Ihr spirituell eng mit den Mondkinklauen und der natürlichen Ordnung der Dunkelküste verbunden. Die störende Anziehungskraft des Kristalls bedroht das Gleichgewicht, das Ihr bewahrt.",["faction:Alliance"]="Als Mitglied der Allianz seid Ihr auf Auberdine als wichtigen Küstenhafen im Norden Kalimdors angewiesen. Eine Gefahr, die ungehindert in den Hügeln wächst, könnte den Zufluchtsort von der Wildnis abschneiden.",["race:NightElf"]="Als Kaldorei könnten Euch die aufgebrachten Mondkinklauen beunruhigen. Euer Volk verehrt sie als heilige Schützlinge Elunes und der Natur."},sec={{t="Beunruhigender Wandel in der Wildnis",b="Mondkinklauen waren einst sanfte, mystische Geschöpfe, die mit Kalimdors Wildnis verbunden waren. Nun vermehren sich aggressive Rudel an den Hängen östlich von Auberdine. Einige Nachtelfen verehren sie noch immer, doch Schildwache Glynda Nal'Shea stellt angesichts der wachsenden Gefahr die Sicherheit der Stadt an erste Stelle. Berichte weisen auf einen einzigen Ort zwischen den östlichen Gipfeln hin."},{t="Anomalie in den östlichen Bergen",b="Späher und Wanderer erzählen von einem unnatürlichen roten Kristall, der hoch über der Dunkelküste aus einem felsigen Berghang ragt. An der nebelverhangenen Küste verbreiten sich Gerüchte leicht, deshalb möchte Glynda, dass Ihr Euch den Ort selbst anseht. Der Kristall existiert wirklich. Die Schildwachen müssen noch herausfinden, warum sich dort Mondkinklauen versammeln und ob er das Land bedroht."}},faq={{q="Was ist der rote Kristall in der Dunkelküste?",a="Der rote Kristall ist eine leuchtende Formation, die in den östlichen Bergen der Dunkelküste eingebettet ist. Die Schildwachen wissen wenig über seinen Ursprung, doch die heimischen Wildtiere, besonders Mondkinklauen, scheinen von ihm angezogen zu werden.",al={"was ist der rote kristall","dunkelküste kristall","roter felsen auberdine"}},{q="Wer schickt Euch auf die Suche nach dem roten Kristall?",a="Schildwache Glynda Nal'Shea in Auberdine schickt Euch los, um Nachforschungen anzustellen. Sie hilft bei der Verteidigung der Siedlung und möchte Berichte aus den östlichen Bergen bestätigt wissen.",al={"wer vergibt die quest der rote kristall","glynda nalshea quest","auberdine kristall questgeber"}},{q="Warum verhalten sich Mondkinklauen in der Nähe des Kristalls aggressiv?",a="Mondkinklauen, die einst als sanft und mystisch galten, sind nun aufbrausend und verteidigen ihr Revier. Glynda vermutet, dass der Kristall mit ihrem veränderten Verhalten und ihrer wachsenden Zahl zusammenhängt.",al={"warum sind mondkinklauen wütend","wütende mondkinklauen dunkelküste","mondkinklauen feindselig"}},{q="Wo befindet sich der rote Kristall?",a="Der Kristall liegt östlich von Auberdine, hoch auf dem östlichen Gebirgskamm der Dunkelküste, wo Mondkinklauen in der Nähe umherstreifen.",al={"wo ist der rote kristall","roter kristall fundort","dunkelküste roter kristall karte"}},{q="Halten die Nachtelfen den Kristall für gefährlich?",a="Glynda misstraut dem Kristall. Sie weiß nicht, ob er harmlos oder unheilvoll ist, doch seine Wirkung auf die wilden Tiere weckt bereits Sorgen um Auberdines Sicherheit.",al={"ist der kristall schädlich","ist der rote kristall böse"}},{q="Was geschieht, nachdem Ihr den Kristall entdeckt habt?",a="Wenn Ihr Glynda mitteilt, dass der Kristall wirklich existiert, bestätigt Ihr die Berichte. Daraufhin versucht sie herauszufinden, was er ist, und beginnt, ihn mit Wasser aus Auberdines Mondbrunnen zu reinigen und Proben von ihm zu nehmen.",al={"was folgt auf der rote kristall","as water cascades folgequest"}}},fx={["79e10640"]={q="Warum möchte Schildwache Glynda Nal'Shea, dass der rote Kristall gefunden wird?",a="Schildwache Glynda Nal'Shea ist mit dem Schutz von Auberdine betraut. Während Mondkin einst als sanfte und mystische Wesen verehrt wurden, nimmt ihre Zahl östlich der Stadt stark zu und sie sind zunehmend aggressiv geworden. Gerüchten zufolge versammeln sich die Kreaturen um eine mysteriöse rote Formation in den östlichen Bergen. Glynda muss bestätigen, ob der Kristall tatsächlich existiert, damit sie beurteilen kann, ob er eine direkte Gefahr für Auberdine darstellt, und herausfinden kann, warum sich die wilden Mondkin so seltsam zu ihm hingezogen fühlen.",al={"warum will glynda nal'shea den roten kristall","motiv von schildwache glynda","warum den roten kristall finden"}}},fp="15,209,31.304.0,28.319.0,37.181.0,42.157.0,57.166.0,33.107.0,55.153.0,44.173.1"}
P.entries["quest:4812"] = {n="Wenn das Wasser fließt",s="In Auberdine hofft Schildwache Glynda Nal'Shea, dass Mondbrunnenwasser enthüllt, was sich unter dem roten Kristall der Dunkelküste verbirgt. Heiliges Wasser könnte seine undurchsichtige Oberfläche durchdringen.",h="In Auberdine hofft Schildwache Glynda Nal'Shea, dass Mondbrunnenwasser enthüllt, was sich unter dem roten...",kw={"wenn das wasser fließt","auberdine","dunkelküste","leere wasserphiole","teufelswald","glynda nal'shea","mondbrunnen","roter kristall"},ang={["class:Druid"]="Als Druide wacht Ihr über das empfindliche Ökosystem der Dunkelküste. Unnatürliche Formationen entlang des Gebirgskamms unterhalb des verderbten Teufelswalds geben Euch Grund, ihnen zu misstrauen.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass die in Auberdine stationierten Späher die Küste vor der Verderbnis schützen müssen, die vom östlichen Hochland herabkriecht.",["race:NightElf"]="Als Kaldorei kennt Ihr Mondbrunnen als heilige Quellen des Lebens und des Trostes. Ihr geweihtes Wasser könnte enthüllen, was in einer seltsamen Formation liegt, und zeigen, wie Elune's Grace hilft, Bedrohungen entlang Eurer Grenzen zu ergründen."},sec={{t="Das Unbekannte läutern",b="Schildwache Glynda Nal'Shea sucht einen sicheren Weg, den roten Kristall hoch an den östlichen Klippen der Dunkelküste zu untersuchen. Mondbrunnenwasser birgt göttliche, heilende Magie, gesegnet durch die Hingabe der Nachtelfen an Elune. Glynda glaubt, dass Wasser aus Auberdines Mondbrunnen mit dem seltsamen Stein reagieren und seine undurchsichtige Hülle durchdringen könnte, ohne ihn zu zerstören."},{t="Der Schatten des Teufelswalds",b="Die Verderbnis des Teufelswalds macht den östlichen Gebirgskamm zu einem gefährlichen Ort für Nachforschungen. Dämonische Energien entstellten den Wald oberhalb der Dunkelküste während des Dritten Krieges, und Schildwache Glynda Nal'Shea fürchtet, die rote Felsnadel könnte mit dieser Verderbnis zusammenhängen. Als heiliges Wasser über das Gitterwerk des Kristalls rinnt, wird der summende Stein kurz durchsichtig. Was darin liegt, verlangt nach einem genaueren Blick."}},faq={{q="Wo bekomme ich das Wasser für diese Quest?",a="Schöpft mit der leeren Phiole, die Schildwache Glynda Nal'Shea Euch gibt, Wasser aus Auberdines Mondbrunnen. Auberdine ist die Siedlung der Nachtelfen.",al={"wo ist der mondbrunnen","mondbrunnenwasser fundort","leere wasserphiole füllen"}},{q="Warum wirkt Mondbrunnenwasser auf den Kristall?",a="Mondbrunnen enthalten geweihtes, von Elune gesegnetes Wasser voller Magie. Schildwache Glynda Nal'Shea erwartet, dass seine läuternde Essenz mit der fremdartigen Energie des Steins reagiert und seine verborgene Beschaffenheit enthüllt.",al={"warum mondbrunnenwasser","mondbrunnenmagie auf kristall"}},{q="Wo befindet sich der rote Kristall?",a="Der rote Kristall liegt an der östlichen Bergwand der Dunkelküste, eingebettet in die felsigen Ausläufer zwischen dem Ufer und dem Hochland darüber.",al={"roter kristall fundort","wo ist der kristall","roter kristall dunkelküste"}},{q="Warum sorgt sich Schildwache Glynda wegen des Teufelswalds?",a="Der Teufelswald liegt östlich oberhalb der Dunkelküste, gezeichnet von dämonischer Verderbnis aus dem Dritten Krieg. Da der Kristall nahe dem Grenzkamm erschien, fürchtet Glynda, dass er denselben dämonischen Ursprung haben könnte.",al={"glynda teufelswald","verbindung zum teufelswald"}},{q="Was geschieht, wenn Ihr das Wasser über den Kristall gießt?",a="Schildwache Glynda erwartet, dass das machtvolle Mondbrunnenwasser einen Hinweis auf die Beschaffenheit des Kristalls enthüllt. Seine Reaktion zeigt sich, wenn Ihr das Wasser über ihn gießt.",al={"ergebnis beim übergießen mit wasser","was geschieht mit dem kristall"}},{q="Wer vergibt die Quest Wenn das Wasser fließt?",a="Schildwache Glynda Nal'Shea in Auberdine gibt Euch diese Aufgabe nach der Erkundung namens The Red Crystal.",al={"questgeber","wer startet wenn das wasser fließt"}}},fx={a7631f7f={q="Wozu dient die Phiole mit Mondbrunnenwasser?",a="Schildwache Glynda Nal'Shea stellt die Phiole bereit, damit Ihr gereinigtes Wasser aus dem Mondbrunnen von Auberdine sammeln und zu dem mysteriösen roten Kristall tragen könnt. Mondbrunnen enthalten mächtige, gesegnete Magie, die mit magischen Anomalien reagieren kann. Indem sie das Wasser über den seltsamen Stein gießt, hofft Glynda, dass seine heilige Energie mit der Struktur reagiert und Hinweise darauf enthüllt, woraus sie besteht – und ob sie eine Gefahr für die Dunkelküste darstellt.",al={"zweck der phiole mit mondbrunnenwasser","warum brauche ich mondbrunnenwasser","quest um die phiole mit mondbrunnenwasser"}}},fp="17,158,21.329.0,21.375.1,40.130.0,43.198.0,33.134.0,45.187.0,52.152.1,38.106.0"}
P.entries["quest:4813"] = {n="Die Fragmente im Inneren",s="An den östlichen Klippen kehrt Ihr mit Wasser aus einem Mondbrunnen zum roten Kristall zurück. Es könnte enthüllen, was sich darin verbirgt, und Ihr bringt die Erkenntnisse zu Schildwache Glynda Nal'Shea in Auberdine zurück.",h="An den östlichen Klippen kehrt Ihr mit Wasser aus einem Mondbrunnen zum roten Kristall zurück.",kw={"auberdine","knochenfragmente","dunkelküste","glynda nal'shea","kieferknochen","mondbrunnenwasser","mysteriöser roter kristall"},ang={["class:Druid"]="Als Druide erkennt Ihr eine merkwürdige Anomalie in einem Mineral, das natürlicher Verwitterung ebenso widersteht wie mächtiger Magie. Es liegt außerhalb des üblichen Gleichgewichts der Wildnis.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass humanoide Knochen, eingeschlossen in seltsamem Kristall entlang der Gebirgsgrenzen von Eschental und Teufelswald, die Schildwachen der Dunkelküste zur Wachsamkeit mahnen."},sec={{t="Eine düstere Enthüllung",b="Gesegnetes Mondbrunnenwasser klärt die trübe Oberfläche des purpurroten Kristalls. In seinem dichten Mineral liegen mehrere kleine Knochenfragmente und die Hälfte eines humanoiden Kieferknochens. Der Kristall ist so hart, dass selbst mächtige Zauber ihn nur schwer aufbrechen könnten. Welches Wesen oder Artefakt diese Überreste auch hinterlassen hat, sie sind einsam über der Küste der Dunkelküste bewahrt geblieben."},{t="Bericht in Auberdine",b="Zurück in Auberdine berichtet Ihr Schildwache Glynda Nal'Shea, was Ihr gefunden habt. Die Entdeckung gibt den örtlichen Anführern der Nachtelfen weiteren Anlass zur Sorge, liefert aber keine klaren Antworten. Glynda wird die Erkenntnisse dem Stadtrat vorlegen. Der Kristall ruht hoch auf den östlichen Klippen, weit genug von der Stadt entfernt, um sie etwas zu beruhigen; er stellt keine unmittelbare Gefahr dar."}},faq={{q="Was ist im roten Kristall eingeschlossen?",a="Gesegnetes Mondbrunnenwasser klärt den roten Kristall genug, um mehrere darin eingeschlossene Knochenfragmente und die Hälfte eines humanoiden Kieferknochens sichtbar zu machen.",al={"was ist im kristall","was sind die fragmente","welche knochen sind darin"}},{q="Lässt sich der Kristall aufbrechen, um die Knochen zu untersuchen?",a="Der Kristall ist außergewöhnlich widerstandsfähig, und selbst mächtige Magie könnte ihn nur schwer aufbrechen. Von wem genau die Knochen stammen, bleibt unbekannt.",al={"kann man den kristall zerbrechen","den roten kristall öffnen"}},{q="Wem berichtet Ihr von den Erkenntnissen?",a="Ihr berichtet Schildwache Glynda Nal'Shea in der Hafenstadt Auberdine von Euren Erkenntnissen.",al={"wer gibt die fragmente im inneren ab","quest abgeben","glynda nalshea"}},{q="Was werden die Schildwachen wegen des Kristalls unternehmen?",a="Schildwache Glynda Nal'Shea plant, den Rat in Auberdine zu informieren, damit seine Mitglieder über das weitere Vorgehen beraten können. Der Kristall ruht hoch in den östlichen Klippen, daher sehen sie ihn nicht als dringende Bedrohung an.",al={"wie geht es mit dem kristall weiter","auberdine rat kristall"}}},fp="20,185,17.339.1,22.340.0,39.129.1,52.139.1,34.83.0,45.194.1"}
P.entries["quest:482"] = {n="Dalaran Absichten",s="Im Silberwald schickt Dalar Morgenweber Schattenpriester Allister eine Warnung. Ein für die Kirin Tor in Mühlenbern bestimmter Anhänger enthüllt ihren Plan, einen ruhenden Leyenergieknoten unter der Stadt zu erwecken. Im Grabmal bereiten die Verlassenen ihre Antwort vor.",h="Im Silberwald schickt Dalar Morgenweber Schattenpriester Allister eine Warnung.",kw={"mühlenbern","dalar morgenweber","dalaran absichten","kirin tor","leyenergie","das grabmal","schattenpriester allister","silberwald"},ang={["class:Mage"]="Als Magier könnt Ihr die Methode der Kirin Tor erkennen. Ruhende Leylinien anzuzapfen, ermöglicht ihnen, effizient einen mächtigen arkanen Brückenkopf zu errichten, ohne gewaltige Kraftquellen durch die Wildnis zu schleppen.",["class:Priest"]="Als Priester wisst Ihr, dass Schattenpriester Allister die Verteidigung der Verlassenen am Grabmal leitet. Er verbindet kalten militärischen Pragmatismus mit den dunklen Lehren der Priesterschaft der Verlassenen, um lebende Bedrohungen auszumerzen.",["race:Undead"]="Als Untoter wisst Ihr, dass Dalarans Präsenz tief im Silberwald die Grenzen der Verlassenen bedroht. Das Leylinienritual aufzuhalten, schützt die Straßen zwischen Tirisfal und den südlichen Grenzen."},sec={{t="Ein ruhender Funke",b="Dalar Morgenweber untersucht einen mit Runen beschrifteten Anhänger aus einer Vorratskiste aus Dalaran. Er erinnert ihn an eine alte Erkundung Mühlenberns durch die Kirin Tor. Das stille Dorf wurde aus einem bestimmten Grund gewählt: Es liegt über einem ruhenden Leyenergieknoten. Dalar erkennt, dass die Zauberer seine Macht anzapfen wollen.\n\nEinen solchen Nexus zu erwecken, erfordert gewaltige magische Reserven. Die verzauberten Anhänger, die die Zauberer tragen, sind der Schlüssel, um diese Macht zu kanalisieren und zu entfesseln."},{t="Die Bedrohung für Silberwald",b="Die Verlassenen können keinen befestigten Außenposten der Kirin Tor dulden, der von Leyenergie gespeist wird. Er würde die südlichen Zugänge zum Grabmal und nach Tirisfal bedrohen. Welches Ritual die Magier auch vorbereiten, rohe Leyenergie würde Dalaran einen gewaltigen strategischen Vorteil in Lordaeron verschaffen.\n\nDeshalb schickt Dalar Schattenpriester Allister eine dringende Nachricht. Er bittet Allister, einen Weg zu finden, die Zauberer aufzuhalten, bevor ihr Ritual vollendet ist."}},faq={{q="Was versuchen die Kirin Tor in Mühlenbern zu tun?",a="Die Zauberer von Dalaran wollen den ruhenden Leyenergieknoten unter Mühlenbern erwecken. Seine Macht würde es ihnen ermöglichen, sich dauerhaft festzusetzen und ihre weiterreichenden Pläne im Silberwald zu verfolgen.",al={"mühlenbern leylinie","was tun dalarans zauberer im silberwald","mühlenbern zweck"}},{q="Warum schickt Dalar Euch zu Schattenpriester Allister?",a="Schattenpriester Allister bestimmt über die Taktik der Verlassenen und ihre Gegenmaßnahmen gegen Dalaran. Dalar Morgenweber steuert arkanes Wissen und Forschung bei, während Allister vom Grabmal aus die Gegenmaßnahmen leitet.",al={"warum allister berichten","wer ist allister","dalar morgenweber allister"}},{q="Welche Rolle spielen die Anhänger der Zauberer bei ihren Plänen?",a="Um den ruhenden Leyknoten zu erwecken, sind gewaltige Kraftreserven nötig. Die verzauberten Anhänger der Zauberer dienen als Leiter und Speicher für diese Magie. Sie ihnen abzunehmen, würde die Aktivierung des Knotens behindern.",al={"kirin tor anhänger","mühlenbern anhänger","warum anhänger sammeln"}}},fx={["6acaedff"]={q="Warum ist Dalar Morgenweber so besorgt über die Arbeit der Kirin Tor in Mühlenbern?",a="Dalar Morgenweber erkennt, dass Mühlenbern auf einem ruhenden Ley-Energieknotenpunkt liegt, der von den Kirin Tor vorgesehen wurde. Wenn die menschlichen Zauberer diese rohe arkane Macht erfolgreich erwecken und nutzen, könnte dies Dalaran einen gewaltigen Stützpunkt mitten im Silberwald gewähren. Um die Region für die Verlassenen zu sichern und eine wachsende magische Bedrohung zu beseitigen, muss Dalar sicherstellen, dass die Führung von Das Grabmal sofort Maßnahmen ergreift, um ihre Arbeit zu stoppen.",al={"warum will dalar dies erledigt haben","motiv von dalar morgenweber","warum kirin tor in mühlenbern stoppen"}}},fp="20,248,15.407.0,24.415.0,48.190.0,50.206.0,50.197.0"}
P.entries["quest:4821"] = {n="Fremdartiges Ei",s="Am Freiwindposten schickt Hagar Blitzhuf Euch los, um ein Ei zu holen, das unter den Felsnadeln von Schlangen bewacht wird. Er will es zurückgebracht haben, bevor etwas aus seinem Inneren ausbrechen kann.",h="Am Freiwindposten schickt Hagar Blitzhuf Euch los, um ein Ei zu holen, das unter den Felsnadeln von Schlangen...",kw={"fremdartiges ei","arikara","freiwindposten","hagar blitzhuf","schlangenhöhle","serpent wild","schlangen","tausend nadeln"},ang={["class:Hunter"]="Als Jäger, der mit Kalimdors Wildtieren vertraut ist, erkennt Ihr vielleicht, dass die Nester in der Schlucht etwas weitaus Urtümlicheres als gewöhnliche Wüstenschlangen bergen.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass der Freiwindposten Euer wichtigster Außenposten in Tausend Nadeln ist. Aufkommende Spitzenprädatoren einzudämmen hilft, die Versorgungslinien zu verteidigen.",["race:Tauren"]="Als Tauren lebt Ihr am Freiwindposten über dem Grund der Schlucht und seid darauf angewiesen, die Tierwelt unter Euch zu verstehen. Eine eingedrungene oder unnatürliche Schlangenbrut könnte das Gleichgewicht rund um Eure Heimat stören."},sec={{t="Ein seltsames Nest",b="Hagar Blitzhuf hört von einem ungewöhnlichen Ei in den Schlangenhöhlen unter den Felsnadeln. Die Schlangen der Schlucht bewachen es wie ihre eigene Brut und greifen Reisende an, die sich nähern. Aus Sorge um die Jagdgründe bittet Hagar Euch, das Nest zu finden, an seinen Wächtern vorbeizukommen und das seltsame Ei zur Untersuchung zurückzubringen."},{t="Der Schlüpfling erwacht",b="Als Hagar Blitzhuf das Ei untersucht, bricht seine Schale sofort auf. Ein Young Arikara, eine junge geflügelte Monstrosität, bricht daraus hervor. Das Neugeborene greift nicht an. Es erhebt sich in die Lüfte und flieht von den Holzplattformen des Freiwindpostens, während sich tiefere Urkräfte in den Winden der Schlucht regen."}},faq={{q="Wo lässt sich das Fremdartige Ei finden?",a="Das Ei liegt in Schlangennestern am Fuß der Klippen in Tausend Nadeln, besonders südlich und nordöstlich des Freiwindpostens. Es ruht auf dem Grund der Schlucht zwischen feindseligen heimischen Schlangen.",al={"fremdartiges ei fundort","wo ist das fremdartige ei","ei erscheinungsort tausend nadeln"}},{q="Warum bewachen die heimischen Schlangen es?",a="Niemand weiß, was das Ei gelegt hat, doch die Schlangen der Schlucht bewachen es, als gehörte es zu ihrem eigenen Gelege. Sie greifen neugierige Eindringlinge an, die sich dem Nest nähern.",al={"warum beschützen schlangen das ei","schlangenverhalten fremdartiges ei"}},{q="Wer ist Hagar Blitzhuf?",a="Hagar Blitzhuf ist ein Späher und Wächter der Tauren, der hoch über Tausend Nadeln am Freiwindposten stationiert ist. Er hält nach ungewöhnlichen Bewegungen und Bedrohungen für die Tierwelt der Schlucht Ausschau und koordiniert die Bemühungen der Horde, die örtlichen Wildtiere unter Kontrolle zu halten.",al={"hagar blitzhuf hintergrundgeschichte","wer ist questgeber hagar"}},{q="Was geschieht, wenn Ihr das Ei abliefert?",a="Wenn Ihr das Ei übergebt, untersucht Hagar es aus der Nähe und enthüllt dabei, was es birgt.",al={"was schlüpft aus dem fremdartigen ei","was ist im ei"}},{q="Wozu führt diese Quest?",a="Mit der Abgabe des Eis beginnt sofort Serpent Wild, der erste Schritt einer längeren Questreihe. Hagar will verstehen, was das Ei barg.",al={"nächste quest nach fremdartiges ei","arikara questreihe nächster schritt"}},{q="Stammt das Ei tatsächlich aus dem Weltall?",a="Hier bedeutet „fremdartig“, dass es der heimischen Tierwelt von Tausend Nadeln fremd und unvertraut ist, nicht, dass es ein Wesen von den Sternen birgt. Hagar will herausfinden, welche Art von Wesen das Ei birgt.",al={"ist das fremdartige ei außerirdisch","ist das ei fremdartig"}}},fx={["7e0b1b71"]={q="Warum möchte Hagar Blitzhuf das Fremdartiges Ei haben?",a="Hagar hat beunruhigende Gerüchte über ein unbekanntes, fremdes Ei gehört, das in den Schlangengruben von Tausend Nadeln entdeckt wurde. Da keiner der Späher in der Lage war, nah genug heranzukommen, um es an den Schlangen vorbei zu untersuchen, die es erbittert verteidigen, möchte er, dass es geborgen wird, damit er es aus erster Hand untersuchen kann. Er ist zutiefst besorgt darüber, welche Art von unbekanntem Geschöpf unter dem Freiwindposten daraus schlüpfen könnte.",al={"warum will hagar das ei","motiv von hagar blitzhuf","warum die quest um das fremdartige ei"}},a4db3611={q="Was ist das Fremdartiges Ei?",a="Das Fremdartiges Ei ist ein ungewöhnliches Gelege, das tief in den Schlangengruben in Tausend Nadeln gefunden wurde. Obwohl es nicht wie eine normale Schlangenbrut aussieht, bewachen örtliche Windschlangen es erbittert, als wäre es ihr eigenes. Hagar Blitzhuf sucht danach, um dessen Ursprünge zu inspizieren, doch bei näherer Betrachtung schlüpft daraus schnell eine junge Windschlange, die davonfliegt.",al={"was ist das fremdartige ei","zweck des fremdartigen eies","hintergrund zum fremdartigen ei"}}},fp="9,171,14.318.0,21.283.1,33.181.0,39.160.1,27.228.0,38.80.1,29.130.1,38.172.1"}
